    }
    dfs(1, 0);
    int t = get_lca(x, y);
    if (h[x] - h[t] >= h[y] - h[t]) {
        for (auto u : g[t]) {
            if (dp[t][0] == u) continue;
            if (get_lca(u, x) == u) go(u, t);
        }
        int ans = 0;
        for (int i = 1; i <= n; ++i) {
            if (was[i] != 1) continue;
            int dist1 = h[i] + h[x] - 2 * h[get_lca(i, x)];
            int dist2 = h[y] + h[i] - 2 * h[get_lca(i, y)];
            ans = max(ans, dist2 - 1);
        }
        cout << ans << '\n';
    }
    else {
        for (auto u : g[v]) {
            if (dp[v][0] == u) continue;
            if (get_lca(u, y) == u) was[u] = 2;
        }
        dfs1(t, 0);
        int ans = 0;
        for (int i = 1; i <= n; ++i) {
            if (was[i] != 1) continue;
            int dist1 = h[i] + h[x] - 2 * h[get_lca(i, x)];
            int dist2 = h[y] + h[i] - 2 * h[get_lca(i, y)];
            ans = max(ans, dist2 - 1);
        }
        cout << ans << '\n';
    }
    return 0;
}

