#include <bits/stdc++.h>
using namespace std;
#define rep(i, n) for (int i = 0; i < (int)(n); i++)
typedef long long ll;


int N, u, v;
vector<vector<int>> links, children;
vector<int> parent, depth, visit;
pair<int, int> max_depth;


void input() {
    cin >> N >> u >> v;
    u--;
    v--;
    links = vector<vector<int>>(N);
    rep(i, N-1) {
        int A, B;
        cin >> A >> B;
        A--;
        B--;
        links[A].push_back(B);
        links[B].push_back(A);
    }
}


void make_tree(int num, int p, int d) {
    if (d > max_depth.first) max_depth = make_pair(d, num);
    parent[num] = p;
    depth[num] = d;
    visit[num] = 1;
    for (int i : links[num]) {
        if (visit[i]) continue;
        children[num].push_back(i);
        make_tree(i, num, d+1);
    }
}


void max_depth_under_u(int num) {
    if (depth[num] > max_depth.first) max_depth.first = depth[num];
    for (int i : children[num]) max_depth_under_u(i);
}


