            for (int j : G[i]) if (!invalid[j] && dist[j] == -1) {
                que.push(j);
                dist[j] = dist[i] + 1;
            }
        }
        ans += *max_element(dist.begin(), dist.end());
    }
    cout << ans << endl;

    return 0;
}

