vector<int> bfs(int s, vector<vector<int>> &g) {
    int n = g.size();
    vector<int> d(n, -1);
    d[s] = 0;
    queue<int> que;
    que.push(s);
    while(que.size()) {
        int now = que.front();
        que.pop();
        if(d[now] == -1) {
            continue;
        }
        for(auto next : g[now]) {
            if(d[next] == -1) {
                d[next] = d[now] + 1;
                que.push(next);
            }
        }
    }
    return d;
}

