void DFS(int init,vector<vector<int> >& E, vector<int> & Node)
{
  int N = E.size();
  vector<int> visited (N,0);
  stack<int> st;
  Node[init] = 0;
  visited[init] = 1;
  st.push(init);
  while(st.empty() != 1)
  {
    int NODE = st.top();
    st.pop();
    if(E[NODE].size() == 1) Node[NODE] = 0;
    for (int i = 0; i < E[NODE].size(); i++)
    {
      int to = E[NODE][i];
      if(visited[to]==0)
      {
        st.push(to);
        Node[to] = Node[NODE] + 1;
        visited[to] = 1;
      }
    }
  }
}

