void solve() {
    int n, u, v;
    cin >> n >> u >> v;
    u--; v--;
    vvi g(n, vi());
    int a, b;
    REP(i, n - 1) {
        cin >> a >> b;
        a--; b--;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
    }

    vi d(n);

    function<void(int, int)> dfs = [&](int c, int p) {
        if (p != -1) d[c] = d[p] + 1; else d[c] = 0;
        if (p != -1 && sz(g[c]) == 1) return;

        for (auto e : g[c]) {
            if (e == p) continue;
            dfs(e, c);
        }
    };

    dfs(v, -1);

    vi r(n);
    int ans = 0;

    int nc, np;
    function<void(int, int)> dfs2 = [&](int c, int p) {
        if (p != -1) r[c] = r[p] + 1; else r[c] = 0;
        if (r[c] > d[c]) {
            return;
        } else if (r[c] == d[c]) {
            chmax(ans, r[c]);
            nc = p;
            np = c;
            return;
        } else if (r[c] + 1 == d[c]) {
            chmax(ans, r[c]);
            nc = c;
            for (auto e : g[c]) {
                if (d[e] == r[c]) {
                    np = e;
                    break;
                }
            }
        }
        if (p != -1 && sz(g[c]) == 1) return;

        for (auto e : g[c]) {
            if (e == p) continue;
            dfs2(e, c);
        }
    };

    dfs2(u, -1);

    int ans2 = 0;
    vi q(n);
    function<void(int, int)> dfs3 = [&](int c, int p) {
        if (p != np) q[c] = q[p] + 1; else q[c] = 0;
        chmax(ans2, q[c]);
        if (p != -1 && sz(g[c]) == 1) return;

        for (auto e : g[c]) {
            if (e == p) continue;
            dfs3(e, c);
        }
    };

    dfs3(nc, np);


    cout << ans + ans2 << endl;
}

