//頂点u, vを含む最小木
Graph G(100100);
bool isgoal = false;
int goal;
deque<int> deq;
int d[100100];

void dfs_(int v, int par){
    if(isgoal)return;
    deq.push_back(v);

    if(v == goal){isgoal = true;return;};
    for(int i = 0; i < G[v].size(); i++){
        int nv = G[v][i];
        if(nv == par)continue;
        dfs_(nv, v);
    }

    if(isgoal)return;
     deq.pop_back();
}



void dfs(int v, int par, int proh){
    //fill(d, d + 100100, 0);
    if(v == proh)return;

    for(int nv : G[v]){
        if(nv == par)continue;
        d[nv] = d[v] + 1;
        dfs(nv, v, proh);
    }
}


