        a--;b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    goal = u;
    dfs_(v, -1);

    rep(i, (deq.size() + 1) / 2 + 1){
        proh = deq.front();
        deq.pop_front();
    }
    dfs(v, -1, proh);
    rep(i, n){
        if(res < d[i]){
            res = d[i];
            goal = i;
        }
    }
    fill(d, d + n, 0);
    dfs(u, -1, -1);

    cout << d[goal] - 1 << endl;
}

