    Graph G(n);
    rep(i,n-1){
        int a,b;
        cin>>a>>b;
        a--;b--;
        G[a].pb(P(b,1));
        G[b].pb(P(a,1));
    }
    Vi oi=dijkstra(v-1,G);
    Vi nige=dijkstra(u-1,G);
    ll ans=0;
    rep(i,n){
        if(oi[i]-nige[i]<0) continue;
        ans=max(ans,oi[i]-1);
    }
    cout<<ans<<endl;
}

