const int MAXN = 2e5 + 5;

int n , a ,b  , aa , bb , hi[MAXN] , t , hei[MAXN] , low[MAXN] , vis[MAXN] , up[MAXN][23];
long long sol ;

vector<int > adj[MAXN];
bool is_a(int a, int b)
{
    return low[b]>=low[a]&&hi[b]<=hi[a];
}
int lca(int a, int b)
{
    if(is_a(a,b))return a;
    if(is_a(b,a))return b;
    for(int i=21;i>=0;i--)
        if(!is_a(up[a][i],b) )
            a = up[a][i];
    return up[a][0];
}
int dfs(int x,int l,int h=0)
{
    vis[x]=1;
    low[x]=t++;
    up[x][0]=l;
    hei[x]=h;
    for(int i=1;i<22;i++)
        up[x][i] = up[ up[x][i-1] ][i-1];
    for(auto u : adj[x])
        if(u!=x&&!vis[u])
            dfs(u,x,h+1);
    hi[x]=t++;
}

int lift(int x ,int y)
{
    int ret=0;
    if(y==1)return hei[x];
    for(int i=21;i>=0;i--)
        if(is_a(y,up[x][i]))
        {
            x = up[x][i];
            ret+=(1<<i);
        }
    return ret;
}

int dist(int a , int b)
{
    int lc = lca(a,b);
    return lift(a,lc)+lift(b,lc);
}
int ans ;

int solve(int x , int l , int d)
{
    int D = dist(bb , x) -1 ;
    if( D >= d )
        ans = max(ans , D);
    for(auto u : adj[x])
    {
        if(u==l)
            continue;
        solve(u  , x , d+1) ;
    }
}

