void dfs(const Graph &G, int v, int p, vector<ll> &Astep){
  for(auto nv : G[v]) {
    if(nv==p) {
      continue;
    } else {
      Astep[nv]=Astep[v]+1; // 子に自分の値を渡す．
      dfs(G, nv, v, Astep);
    }
  }
}

