      dist[next] = now.SE+1;
      que.push(pll(next, now.SE+1));
    }
  }


  REP(i, n)
    visited[i] = false;

  que.push(pll(dist[u], 0));
  visited[u] = true;
  pll ans = pll(dist[u],0);
  while(!que.empty()){
    pll now = que.front();
    que.pop();
    for(ll i = 0; i<g[now.FI].size(); i++){
      ll next = g[now.FI][i];
      if(visited[next] || dist[next]<now.SE)
        continue;

      visited[next] = true;
      if(ans.FI < dist[next]){
        ans.FI = dist[next];
        ans.SE = now.SE+1;
      }
      que.push(pll(next, now.SE+1));
    }
  }

  cout << ans.FI-1 << endl;
}

