signed main() {
	INIT;

	VAR(int, n, u, v); --u; --v;
	VEC_ROW(int, n - 1, a, b);

	struct Edge {
		int to, cost;
		Edge() {}
		Edge(int to, int cost) : to(to), cost(cost) {}
		bool operator<(const Edge& r) const {
			return cost < r.cost;
		}
	};
	std::vector<std::vector<Edge>> g(n);
	REP(i, n - 1) {
		--a[i]; --b[i];
		g[a[i]].emplace_back(b[i], 1);
		g[b[i]].emplace_back(a[i], 1);
	}

	std::vector<int> dist(n);
	std::function<void(int)> Dijkstra = [&](int s) {
		using P = std::pair<int, int>;
		std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
		std::fill(dist.begin(), dist.end(), INFLL);
		dist[s] = 0;
		pq.push(P(0, s));
		while (!pq.empty()) {
			P p = pq.top(); pq.pop();
			int v = p.second;
			if (dist[v] < p.first) continue;
			for (int i = 0; i < g[v].size(); ++i) {
				Edge e = g[v][i];
				if (dist[e.to] > dist[v] + e.cost) {
					dist[e.to] = dist[v] + e.cost;
					pq.push(P(dist[e.to], e.to));
				}
			}
		}
	};
	Dijkstra(u);
	V<int> distU = dist;
	Dijkstra(v);
	V<int> distV = dist;

	V<int> depth(n, 0);
	{
		auto rec = [&](auto && f, int x, int par) -> void {
			for (auto&& e : g[x]) if (e.to != par) {
				depth[e.to] = depth[x] + 1;
				f(f, e.to, x);
			}
		};
		rec(rec, v, -1);
	}

	int ans = 0;
	REP(i, n) {
		if (distU[i] < distV[i]) CHMAX(ans, depth[i] - 1);
	}
	OUT(ans)BR;

	return 0;
}

