void solve() {
    int n, u, v;
    cin >> n >> u >> v;
    u--; v--;
    vector<vector<int>> t(n, vector<int>());
    int a, b;
    REP(i, n - 1) {
        cin >> a >> b;
        a--; b--;
        t[a].emplace_back(b);
        t[b].emplace_back(a);
    }

    vector<int> dist(n, 0);
    function<void(int, int, int)> dfs = [&](int c, int p, int d) {
        dist[c] = d;
        if (p != -1 && sz(t[c]) == 1) return;
        for (int x : t[c]) {
            if (x == p) continue;
            dfs(x, c, d + 1);
        }
    };
    dfs(v, -1, 0);
    int ans = 0;
    function<void(int, int, int)> dfst = [&](int c, int p, int d) {
        if (dist[c] == d) return;
        if (sz(t[c]) == 1) {
            chmax(ans, dist[c] - (abs(dist[c] - d) % 2 == 1 ? 1 : 0));
            if (p != -1 ) return;
        }
        for (int x : t[c]) {
            if (x == p) continue;
            if (dist[x] < d + 1) {
                continue;
            }
            dfst(x, c, d + 1);
        }
    };
    dfst(u, -1, 0);
    cout << ans << EOL;
}

