        a--; b--;
        edge e = {b, 1};
        edge f = {a, 1};
        G[a].push_back(e);
        G[b].push_back(f);
        edge e2 = {b, 1};
        edge f2 = {a, 1};
        G2[a].push_back(e2);
        G2[b].push_back(f2);
    }
    dijkstra(taka);
    dijkstra2(ao);

    int ans = 0;

    for(int i = 0; i <= V; i++){
        //cout << i << " " << d[i] << " " << d2[i] << "\n";
        if(d[i] < d2[i]){
            ans = max(ans, d[i]);
