vll d(100001, INF);
vll d_oni(100001, INF);

void dfs_oni(ll p, ll cnt) {
  // Already visited
  if (d_oni[p] != INF) {
    return;
  }

  d_oni[p] = cnt;
  FORm(it, tree[p]) {
    dfs_oni(*it, cnt + 1);
  }
}

ll dfs(ll p, ll cnt) {
  // Already visited
  if (d[p] != INF) {
    if ((d[p] - d_oni[p]) % 2) {
      return d_oni[p] - 1;
    }
    return d_oni[p];
  }

  // 鬼が先に来れる
  if (cnt >= d_oni[p]) {
    return d_oni[p];
  }

  d[p] = cnt;
  ll ans = 0;
  FORm(it, tree[p]) {
    chmax(ans, dfs(*it, cnt + 1));
  }
  return ans;
}

