ll dfs2(ll at, ll t){
	if(aoki[at] == t){return t;}
	if(aoki[at] == t-1){return t-1;}

	ll keep = t+((aoki[at]-t)/2)*2;
	ll taihi = 0;
	rep(i, 0, edge[at].size()){
		ll next = edge[at][i];
		taihi = max(aoki[next], taihi);
	}
	keep = min(t+((taihi-t)/2)*2, keep);

	ll res = keep;
	taka[at] = keep;
	rep(i, 0, edge[at].size()){
		ll next = edge[at][i];
		if(aoki[next] >= t+1 && taka[next] == -1){
			ll buf = dfs2(next, t+1);
			res = max(buf, res);
		}
	}
	return res;
}


