struct TreeNode{
    TreeNode* parent;
    vector<TreeNode*> children;
    int height, dist;
};


const int sz = 1e5+5;
int n, u, v;
int vis[sz];
vector<int> adj[sz];
TreeNode* t;

TreeNode* makeTree(int node, TreeNode* parent){
    vis[node] = true;
    TreeNode* tn = new TreeNode();
    tn->parent = parent;
    for(int next : adj[node]){
        if(!vis[next]) tn->children.push_back(makeTree(next, tn));
    }

    if(node == u) t = tn;
    return tn;
}

int getHeight(TreeNode* node){
    if(node->children.empty()){
        node->height = 0;
        return 0;
    }

    int height = -1;
    for(TreeNode* next : node->children){
        height = max(height, 1+getHeight(next));
    }

    node->height = height;
    return height;
}

void setDist(TreeNode* node, int dist){
    node->dist = dist;
    for(TreeNode* next : node->children){
        setDist(next, dist+1);
    }
}

void solve(){
    cin >> n >> u >> v;
    --u, --v;
    for(int i = 0; i < n-1; ++i){
        int a, b;
        cin >> a >> b;
        --a, --b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    TreeNode* root = makeTree(v, NULL);
    getHeight(root);
    setDist(root, 0);

    int ans = 0, dist = t->dist, turns = 0;
    while(t != root){
        if(dist <= 0) break;
        ans = max(ans, t->height + dist - 1 + turns);

        t = t->parent;
        dist -= 2;
        turns++;
    }

    cout << ans << '\n';
}

