                ll a, b;
                scanf("%lld %lld", &a, &b);
                link[a-1].push_back(b-1);
                link[b-1].push_back(a-1);
        }

        ll tmap[n], amap[n], used[n];

        for(ll i=0; i<n; i++) used[i] = 0;
        queue<P> que; que.push({u-1, 0});
        while(!que.empty()){
                P apex = que.front(); que.pop();
                used[apex.first] = 1;
                tmap[apex.first] = apex.second;
                for(ll ver: link[apex.first]){
                        if(!used[ver]) que.push({ver, apex.second+1});
                }
        }

        for(ll i=0; i<n; i++) used[i] = 0;
        que.push({v-1, 0});
        while(!que.empty()){
                P apex = que.front(); que.pop();
                used[apex.first] = 1;
                amap[apex.first] = apex.second;
                for(ll ver: link[apex.first]){
                        if(!used[ver]) que.push({ver, apex.second+1});
                }
        }

        /*
        for(ll i=0; i<n; i++) printf("%lld ", tmap[i]);
        for(ll i=0; i<n; i++) printf("%lld ", amap[i]);
        */

		ll tmp, get, ii = 1e20;
        for(ll i=0; i<n; i++){
                if(tmap[i]==amap[i] or tmap[i]==amap[i]+1){
                        if(i<ii){
                                tmp = tmap[i]-(tmap[i]==amap[i]+1);
                                get = i;
                                ii = i;
                        }
                }
        }

        for(ll i=0; i<n; i++) used[i] = 0;
        used[get] = 1;
        for(ll ver: link[get]){
                if(tmap[ver]<tmap[get]) que.push({ver, tmp});
        }

        ll dist[n];
        for(ll i=0; i<n; i++) dist[i] = -1e11;
        while(!que.empty()){
                P apex = que.front(); que.pop();
                used[apex.first] = 1;
                dist[apex.first] = apex.second;
                for(ll ver: link[apex.first]){
                        if(!used[ver]) que.push({ver, apex.second+1});
                }
        }

        ll ans = 0;
        for(ll i=0; i<n; i++) ans = max(ans, dist[i]);
        printf("%lld\n", ans);

        return 0;
