int ans;
vector<int> v[maxn];
int d[2][maxn];

void dfs(int k, int now, int dd, int fa)
{
    d[k][now] = dd;
    for (int x : v[now])
    {
        if (x == fa)
            continue;
        dfs(k, x, dd + 1, now);
    }
}

void search(int now, int fa)
{
    if (d[0][now] >= d[1][now])
        return;
    ans = max(ans, d[1][now] - 1);
    for (int x : v[now])
    {
        if (x == fa)
            continue;
        search(x, now);
    }
}

