int main() {
    int n; cin >> n;
    int u, v; cin >> u >> v; // v = oni,ne
    u--; v--;
    vector<edge> ar(n);
    rep(i,n-1){
        int a, b; cin >> a >> b;
        ar[a-1].to.emplace_back(b-1);
        ar[b-1].to.emplace_back(a-1);
    }
    int ans = 0;
    rep(i,n){
        ar[i].ko = -1;
        ar[i].kouho = 0;
    }
    stack<int> st;
    st.push(v);
    ar[v].oya = -1;
    ar[v].dist = 0;
    while (!st.empty()){
        int g = st.top(); st.pop();
        if (g == -1) break;
        ar[g].ko = -2;
        bool t = true;
        vector<int> kesu;
        rep(i,ar[g].to.size()){
            int c = ar[ar[g].to[i]].ko;
            if (c == -1){
                st.push(ar[g].to[i]);
                ar[ar[g].to[i]].oya = g;
                ar[ar[g].to[i]].dist = ar[g].dist+1;
                t = false;
                break;
            }
            else if (c != -2){
                ar[g].kouho = max(ar[g].kouho,c+1);
                kesu.emplace_back(i);
            }
        }
        rep(i,kesu.size()){
            ar[g].to.erase(ar[g].to.begin()+kesu[kesu.size()-1-i]);
        }
        if (t){
            ar[g].ko = ar[g].kouho;
            st.push(ar[g].oya);
        }
    }
    int nu = u;
    rep(i,(ar[u].dist-1)/2){
        nu = ar[nu].oya;
        ans++;
    }
    if ((ar[u].dist-1) % 2 == 0){
        ans += ar[nu].ko;
    }
    else {
        ans += ar[nu].ko+1;
    }
    cout << ans << endl;
}

