        tree[a].pb(b);
        tree[b].pb(a);
    }
    queue<int> q;
    // go only in the subtree from y in which x is
    vis[y] = true;
    int index = y;
    for(int i:tree[y])
    {
        vis[i] = true;
        if(dfs(i))
        {
            index = i;
            break;
        }
    }
    vis.assign(n+1, false);
    lev.assign(n+1, 0);
    int curr =index; 
    // go till dist/2 because if there is any subtree which is bigger in between
    // y and that dist/2 vertex x can't reach there and go down that path
    int z = (dist)/2 + 1, u = y, from = y;
    vis[y] = true;
    z = min(z, dist);
    while(z > 0)
    {
        bool found = false;
        for(int i:tree[u])
        {
            if(i == from) continue;
            if(in_path[i])
            {
                from = u;
                u = i;
                vis[u] = true;
                z--;
                found = true;
                break;
            }
        }
        if(!found)
        {
            break;
        }

    }
    curr = u;
    lev[curr] = min((dist)/2 + 1, dist);
    ans = lev[curr];
    q.push(curr);
    vis[curr] = true;
    while(!q.empty())
    {
        curr = q.front();
        q.pop();

        for(int i:tree[curr])
        {
            if(vis[i]) continue;
            if(in_path[i]) continue;
            vis[i] = true;
            lev[i] = lev[curr]+1;
            ans = max(ans, lev[i]);
            q.push(i);
        }
    }
    cout << ans - 1 << "\n";
    return 0;
}

