int lmax = 0;

void mark(int cur, int curdist)
{
	dist[cur] = curdist;

	for (int i = 0; i < graph[cur].size(); i++)
	{
		int next;

		next = graph[cur][i];

		if (!avisited[next])
		{
			avisited[next] = true;

			mark(next, curdist + 1);
		}
	}
}

void dfs(int cur, int curdist)
{
	bdist[cur] = curdist;

	if (dist[cur] > lmax)
	{
		lmax = dist[cur];
	}

	for (int i = 0; i < graph[cur].size(); i++)
	{
		int next;

		next = graph[cur][i];

		if (!bvisited[next] && curdist + 1 < dist[next])
		{
			bvisited[next] = true;

			dfs(next,curdist);
		}
	}
}

