#include<bits/stdc++.h>
using namespace std;
using ll = long long;

#define INF 1e+9
#define MAX_V 100000

struct edge {
    int to;
    int cost;
};

// <最短距離, 頂点の番号>
using P = pair<int, int>;

int V;
vector<edge> G[MAX_V];
vector<edge> G2[MAX_V];
int d[MAX_V];
int d2[MAX_V];

void dijkstra(int s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d+V, INF);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;

        for (int i=0; i<G[v].size(); ++i) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

void dijkstra2(int s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d2, d2+V, INF);
    d2[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (d2[v] < p.first) continue;

        for (int i=0; i<G2[v].size(); ++i) {
            edge e = G2[v][i];
            if (d2[e.to] > d2[v] + e.cost) {
                d2[e.to] = d2[v] + e.cost;
                que.push(P(d2[e.to], e.to));
            }
        }
    }
}

int main(){
    int taka, ao;
    cin >> V >> taka >> ao;
    taka--; ao--;
    for(int i = 0; i < V - 1; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        edge e = {b, 1};
        edge f = {a, 1};
        G[a].push_back(e);
        G[b].push_back(f);
        edge e2 = {b, 1};
        edge f2 = {a, 1};
        G2[a].push_back(e2);
        G2[b].push_back(f2);
    }
    dijkstra(taka);
    dijkstra2(ao);

    int ans = 0;

    for(int i = 0; i < V; i++){
        //cout << i << " " << d[i] << " " << d2[i] << "\n";
        if(d[i] < d2[i]){
            ans = max(ans, d2[i] - 1);
        }
    }
    ans = max(ans, d[ao]/2);
    cout << ans << "\n";
    return 0;
}

