  std::cin >> N >> U >> V;

  for(int i=0;i<N-1;++i){
      int a, b;
      std::cin >> a >> b;

      G[a].emplace_back(b);
      G[b].emplace_back(a);
  }

  {
      int i = 0;
      dfs(V, -1, 0, i);
  }

  int res = 0;

  for(int i=1;i<=N;++i){
      if(G[i].size() == 1){continue;}

      int v = lca(i, U);

      int d_Uv = std::abs(depth[U] - depth[v]), d_Vv = depth[v];

      if(d_Uv < d_Vv || (i == v && d_Uv == d_Vv)){
          res = std::max(res, depth[i]);
      }
  }

  std::cout << res << std::endl;
}

