struct mint
{
  ll x; // typedef long long ll;
  mint(ll x = 0) : x((x % mod + mod) % mod) {}
  mint operator-() const { return mint(-x); }
  mint &operator+=(const mint a)
  {
    if ((x += a.x) >= mod)
      x -= mod;
    return *this;
  }
  mint &operator-=(const mint a)
  {
    if ((x += mod - a.x) >= mod)
      x -= mod;
    return *this;
  }
  mint &operator*=(const mint a)
  {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const
  {
    mint res(*this);
    return res += a;
  }
  mint operator-(const mint a) const
  {
    mint res(*this);
    return res -= a;
  }
  mint &operator++()
  {
    if ((x += 1) >= mod)
      x -= mod;
    return *this;
  }
  mint &operator--()
  {
    if ((x += mod - 1) >= mod)
      x -= mod;
    return *this;
  }
  mint operator*(const mint a) const
  {
    mint res(*this);
    return res *= a;
  }
  mint pow(ll t) const
  {
    if (!t)
      return 1;
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1)
      a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const
  {
    return pow(mod - 2);
  }
  mint &operator/=(const mint a)
  {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const
  {
    mint res(*this);
    return res /= a;
  }
};


int main()
{
  int n, u, v;
  cin >> n >> u >> v;
  vector<vector<int>> g(n+1);
  rep(i, n-1) {
    int a, b; cin >> a >> b;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  vector<int> taka(n+1, INF), aoki(n+1, INF);

  queue<int> q;
  auto update = [&](int now, vector<int> &dist) {
    for(auto next : g[now]) {
      if(chmin(dist[next], dist[now]+1)) q.push(next);
    }
  };

  taka[u] = 0;
  q.push(u);
  while(!q.empty()) {
    int now = q.front(); q.pop();
    update(now, taka);
  }

  aoki[v] = 0;
  q.push(v);
  while(!q.empty()) {
    int now = q.front(); q.pop();
    update(now, aoki);
  }

  int ans = 0;
  for(int i = 1; i <= n; ++i) {
    if(g[i].size() != 1 || taka[i] >= aoki[i]) continue;

    int tmp = taka[i] + (aoki[i]-taka[i])-1;
    chmax(ans, tmp);
  }

  cout << ans << endl;
}

