vector<int> adj[100000];
bool cp[100000];
int a, b, lb = 0, ml;
void dfs1(int c, int p, int l){
	cp[c] = false;
	if (c == b){
		cp[c] = true;
		lb = l;
	}
	for (int i = 0; i < adj[c].size(); i++){
		if (adj[c][i] != p){
			dfs1(adj[c][i], c, l + 1);
			cp[c] = cp[c] || cp[adj[c][i]];
		}
	}
}
void dfs2(int c, int p, int l){
	ml = max(ml, l);
	for (int i = 0; i < adj[c].size(); i++){
		if (adj[c][i] != p){
			dfs2(adj[c][i], c, l + 1);
		}
	}
}
int main(){
	int n, x, y;
	scanf("%d %d %d", &n, &a, &b);
	a--;
	b--;
	for (int i = 1; i < n; i++){
		scanf("%d %d", &x, &y);
		adj[x - 1].push_back(y - 1);
		adj[y - 1].push_back(x - 1);
	}
	dfs1(a, -1, 0);
	int ans = lb - 1, c = a, p = -1;
	for (int i = 0; i < ceil(lb / 2.0); i++){
		int next;
		ml = -1;
		for (int j = 0; j < adj[c].size(); j++){
			if (!cp[adj[c][j]]){
				dfs2(adj[c][j], c, 0);
			}else if (adj[c][j] != p){
				next = adj[c][j];
			}
		}
		if (ml != -1){
			ans = max(ans, lb - i + ml);
		}
		p = c;
		c = next;
	}
	printf("%d\n", ans);
}

