        d[s] = 0;
        queue<i64> que;
        que.push(s);
        while (!que.empty()) {
            i64 u = que.front(); que.pop();

            for (i64 v : G[u]) {
                if (d[v] == -1) {
                    d[v] = d[u] + 1;
                    que.push(v);
                }
            }
        }
        return d;
    };

    vector<i64> ds = calc(s);
    vector<i64> dt = calc(t);

    i64 root = t;
    i64 maxd = 0;
    i64 maxv = s;
    REP(i, N) {
        if (i != root && G[i].size() == 1 && ds[i] < dt[i]) {
            if (chmax(maxd, ds[i])) {
                maxv = i;
            }
        }
    }

    auto parent = [&](i64 u) {
        if (u == root) return root;
        i64 p = -1;
        for (i64 v : G[u]) {
            if (dt[v] + 1 == dt[u]) {
                p = v;
                break;
            }
        }
        return p;
    };

    i64 v = parent(parent(maxv));
    cout << (dt[v] + (v != parent(maxv))) << endl;

    return 0;
}

