#define MAX_NODE 100005

/*

	node[     0] --> n0, n1, n2, ... 
	 ...
	node[100005] --> n0, n1, n2, ...

*/
vector<int> node[MAX_NODE];
int N;

vector<int> dist;

/*
	s : current node
	d : distance from source
	p : previous node
*/
void resolveDFS(int v, int d = 0, int p = -1) {
	// save distance to v
	dist[v] = d;
	for (int u : node[v]) {
		// bidirectional controll
		if (u == p) continue;

		resolveDFS(u, d + 1, v);
	}
}

vector<int> calcDistance(int s) {
	// initialize vector that represent distance from node s to each nodes
	dist = vector<int>(N);
	// calculate distance by DFS (Depth-First Search) 
	resolveDFS(s);

	return dist;
}

