	// number of tree node
	cin >> N;

	// node index where Takahashi start as s, and Aoki as t
	int s, t;
	cin >> s >> t;
	s--;
	t--;

	// edge in tree
	int a, b;
	for (int i = 0; i < N-1; i++)
	{
		cin >> a >> b;
		a--;
		b--;
		node[a].push_back(b);
		node[b].push_back(a);
	}

	// distance from Takahashi
	vector<int> distS = calcDistance(s);
	// distance from Aoki
	vector<int> distT = calcDistance(t);

	int m = 0;
	for (int i = 0; i < N; i++) {
		/*
			If Aoki can arrive at node i faster than Takahashi, save the distance from Takahashi
		*/
		if (distS[i] < distT[i]) {
			m = max(m, distT[i]);
		}
	}

	/*
		Game exactly finishes one node before the leaf
	*/
	cout << (m - 1) << endl;

	return 0;
}

