void dfs(int v, int p, int d, const vector<vector<int>> &G) {
    dist[v] = d;
    for (auto &u : G[v]) {
        if (u == p) continue;
        dfs(u, v, d + 1, G);
    }
}

void dfs2(int v, int p, int d, const vector<vector<int>> &G) {
    dist2[v] = d;
    for (auto &u : G[v]) {
        if (u == p) continue;
