void dfs(int u,int fa){
	dep[u]=dep[fa]+1;
	anc[u][0]=fa;
	for (int i=1;i<=20;i++){
		anc[u][i]=anc[anc[u][i-1]][i-1];
	}
	for (int i=0;i<adj[u].size();i++){
		int v=adj[u][i];
		if (v==fa) continue;
		dfs(v,u);
		len[u]=max(len[u],len[v]+1);
	}
}
int lca(int a,int b){
	if (dep[a]<dep[b]) swap(a,b);
	for (int i=20;i>=0;i--){
		if (dep[anc[a][i]]>=dep[b]) a=anc[a][i];
	} 
	if (a==b) return a;
	for (int i=20;i>=0;i--){
		if (anc[a][i]!=anc[b][i]){
			a=anc[a][i];
			b=anc[b][i];
		}
	}
	return anc[a][0];
}
int dis(int u,int v){
	int z=lca(u,v);
	return dep[u]+dep[v]-dep[z]*2;
}
