struct SegmentTree {
private:
    int n;
    //vector<map<char,ll> > node;

public:
    vector<map<char,ll> > node;
    // 元配列 v をセグメント木で表現する
    SegmentTree(string v) {
    // 最下段のノード数は元配列のサイズ以上になる最小の 2 冪 -> これを n とおく
    // セグメント木全体で必要なノード数は 2n-1 個である
    int sz = v.size();
    n = 1; while(n < sz) n *= 2;
    node.resize(2*n-1);
    for(int i=0; i<sz; i++) node[i+n-1][st[i]]++;
    for(int i=n-2; i>=0; i--) node[i] = marge_map(node[2*i+1], node[2*i+2]);
    }
    void update(int x,char b) {
    x += (n-1);
    node[x][st[x-(n-1)-1]]--;
    d(x-(n-1))
    st[x-(n-1)-1]=b;
    d(st)
    node[x][b]++;
    while(x > 0) {
        x = (x - 1) / 2;
        node[x] = marge_map(node[2*x+1], node[2*x+2]);
        }
    }
    // 要求区間 [a, b) 中の要素の最小値を答える
    // // k := 自分がいるノードのインデックス
    // // 対象区間は [l, r) にあたる
    // get a,b+1で呼び出す
    map<char,ll> get(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        d(l)d(r)d(a)d(b)
        map<char,ll> emp;
        if(r <= a || b <= l) return emp;
        // 要求区間が対象区間を完全に被覆 -> 対象区間を答えの計算に使う
        if(a <= l && r <= b) return node[k];
        // 要求区間が対象区間の一部を被覆 -> 子について探索を行う
        // 左側の子を vl ・ 右側の子を vr としている
        // 新しい対象区間は、現在の対象区間を半分に割ったもの
        auto v1 = get(a, b, 2*k+1, l, (l+r)/2);
        auto v2 = get(a, b, 2*k+2, (l+r)/2, r);
        return marge_map(v1, v2);
    }    
};

