bool predicate(ll mid, ll y) {
  return (y <= f(mid));
}

ll bs(ll lo, ll hi, ll y = 1) {
  if ( predicate(lo, y)) return lo;
  if (!predicate(hi, y)) return hi + 1;
  while (hi - lo > 1) {
    ll mid = lo + ((hi - lo) >> 1);
    if (predicate(mid, y)) hi = mid;
    else lo = mid;
  }
  return hi;
}

