class Edge
{
	public:
	int cost;
	int from;
	int to;

	Edge(int n,int c)
	{
		to=n;
		cost=c;
	}

	Edge(int f,int t,int c)
	{
		from=f;
		to=t;
		cost=c;
	}
};

vector<Edge> g[100000];
vector<int> keiro;//u-v間の経路
bool used[100000];
bool uvpath(int s,int t,int now,int prev)
{
	if(now==t)
	{
		keiro.push_back(now);
		return true;
	}
	for(int i=0;i<g[now].size();i++)
	{
		Edge e=g[now][i];
		if(e.to==prev)
			continue;
		if(uvpath(s,t,e.to,now))
		{
			keiro.push_back(now);
			return true;
		}
	}
	return false;
}
int longpath(int now,int prev,int length)
{
	int ret=length;
	for(int i=0;i<g[now].size();i++)
	{
		Edge e=g[now][i];
		if(e.to==prev)
			continue;
		ret=max(ret,longpath(e.to,now,length+1));
	}
	return ret;
}

