	fill(d.begin(), d.end(), INF);
	priority_queue<pii,vector<pii>,greater<pii>> q;
	q.push(make_pair(0,x));
	while (!q.empty())
	{
		auto p = q.top();
		q.pop();
		int frm = p.second;
		int co = p.first;
		if (d[frm] <= co) continue;
		d[frm] = co;
		for (auto v : es[frm]) {
			if(d[v] > co + 1)
				q.push(make_pair(co+1,v));
		}
	}
}
