void bfs() {
  queue<int> que;
  que.push(v);
  visited[v] = true;
  dis[v] = 0;
  while (!que.empty()) {
    int tmp = que.front();
    que.pop();
    for (int next : to[tmp]) {
      if (!visited[next]) {
        visited[next] = true;
        que.push(next);
        dis[next] = dis[tmp] + 1;
      }
    }
  }
}

void dfs(int tmp) {
  eble[tmp] = true;
  for (int next : to[tmp]) {
    if (!eble[next]) {
      int x = abs(dis[u]-dis[next]), y = abs(dis[v]-dis[next]);
      if (x > y) continue;
      eble[next] = true;
      if (x < y) dfs(next);
    }
  }
}

