	d1[i] = 0;
	while(!q.empty()){
		int atual = q.front();
		q.pop();
		if(vis[atual]) continue;
		vis[atual] = 1;
		for(auto& v : graph[i]){
			if(vis[v] == 0){
				q.push(v);
				d1[v] = min(d1[v], d1[atual]+1);
			}
		}
	}
}

