    for(int to:v[a])
    {
        if(to==p) continue;
        if(dfs1(to,b,path,a))
        {
            path.push_back(to);
            if(p==-1) path.push_back(a);
            return 1;
        }
    }
    return 0;
}

pair<int,int> dfs2(int a,int p=-1)
{
    pair<int,int> best=make_pair(0,0);
    if(a==zero) return make_pair(0,zero);
    for(int to:v[a])
    {
        if(to==p) continue;
        pair<int,int> d=dfs2(to,a);
        d.first++;
        best=max(best,d);
    }
    if(best.first==0) best.second=a;
    return best;
}

