  int n, u, v;
  cin >> n >> u >> v;
  u--;
  v--;
  Graph g(n);
  for (int i = 0; i < n - 1; i++) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  vector<int> d(n, INF), par(n, -1);
  queue<int> que;
  d[v] = 0;
  que.push(v);
  while (!que.empty()) {
    int cur = que.front();
    que.pop();
    for (auto nxt : g[cur]) {
      if (d[nxt] != INF) continue;
      d[nxt] = d[cur] + 1;
      par[nxt] = cur;
      que.push(nxt);
    }
  }
  int pos = u;
  for (int i = 0; i < (d[u] - 1) / 2; i++) {
    pos = par[pos];
  }
  int ret = d[u] / 2;
  vector<int> d2(n, INF);
  d2[pos] = 0;
  que.push(pos);
  while (!que.empty()) {
    int cur = que.front();
    que.pop();
    for (auto nxt : g[cur]) {
      if (d2[nxt] != INF) continue;
      d2[nxt] = d2[cur] + 1;
      que.push(nxt);
    }
  }
  int tmp = 1 - d[u] % 2;
  for (int i = 0; i < n; i++) {
