int main()
{
    auto N = in<int>();
    graph g(N);
    auto u = in<int>() - 1, v = in<int>() - 1;
    for (int i = 0; i < N - 1; i++) {
        const auto a = in<int>() - 1;
        const auto b = in<int>() - 1;
        g.add_edge(a, b, true);
    }
    std::vector<bool> is_path(N, false);
    std::vector<int> path;
    std::vector<int> height(N, 0);
    mfp([&](auto&& dfs, const int s, const int p, const int d) -> bool {
        bool pat = s == v;
        int max  = 0;
        if (s != v) {
            for (const int to : g[s]) {
                if (to == p) { continue; }
                const bool sub = dfs(dfs, to, s, d + 1);
                pat |= sub;
                if (not sub) { chmax(max, height[to] + 1); }
            }
            height[s] = max;
        }
        if (pat) { path.push_back(s); }
        return is_path[s] = pat;
    })(u, -1, 0);
    std::reverse(path.begin(), path.end());
    SHOW(path);
    SHOW(height);
    int max = (path.size() - 1) / 2;
    for (int i = 0; i < path.size(); i++) {
        const int du = i;
        const int dv = path.size() - du - 1;
        if (du >= dv) { break; }
        const int ul = du + height[path[i]];
        int l        = ul;
        int dl       = dv - du;
        SHOW(path[i], l, dl);
        for (int i = 1;; i++) {
            if (i % 2 == 1) {
                if (dl == 1) {
                    l += i - 1;
                    break;
                } else if (dl == 2) {
                    l += i;
                    break;
                }
                dl -= 2;
            }
        }
        chmax(max, l);
    }
    outln(max);
    return 0;
}

