void dfs(vector<vector<int>>& adj, vector<int>& dist, int ch, int par) {
    if(par == -1) {
        for(auto& x: adj[ch]) {
            dfs(adj, dist, x, ch);
        }
    } else {
        dist[ch] = dist[par] + 1;
        for(auto& x: adj[ch]) {
            if(x != par) {
                dfs(adj, dist, x, ch);
            }
        }
    }
} 

