const int N = 1e5 + 10;
const int K = 20;
vector<int> a[N];
int dep[N], f[K][N];
bool leaf[N];

void DFS(int u, int parent) {
  f[0][u] = parent;
  for (int k = 1; k < K; ++k) {
    int v = f[k - 1][u];
    f[k][u] = v < 0 ? -1 : f[k - 1][v];
  }
  dep[u] = parent < 0 ? 0 : dep[parent] + 1;
  for (auto& v : a[u]) {
    if (v == parent) continue;
    leaf[u] = false;
    DFS(v, u);
  }
}

int LCA(int x, int y) {
  if (dep[x] < dep[y]) swap(x, y);
  for (int k = 0, delta = dep[x] - dep[y]; k < K; ++k) {
    if (delta & (1 << k)) x = f[k][x];
  }
  for (int k = K - 1; k >= 0; --k) {
    if (f[k][x] != f[k][y]) {
      x = f[k][x];
      y = f[k][y];
    }
  }
  return x == y ? x : f[0][x];
}

int main() {
  int n, u, v;
  scanf("%d%d%d", &n, &u, &v);
  --u; --v;
  for (int i = 1; i < n; ++i) {
    int x, y;
    scanf("%d%d", &x, &y);
    --x; --y;
    a[x].push_back(y);
    a[y].push_back(x);
  }

  fill(leaf, leaf + n, true);
  DFS(v, -1);

  int best = 0;
  for (int i = 0; i < n; ++i) {
    if (!leaf[i]) continue;
    int lca = LCA(i, u);
    if (dep[lca] <= dep[u] - dep[lca]) {
      best = max(best, dep[u] / 2);
      continue;
    }
    best = max(best, dep[i] - 1);
  }
  printf("%d\n", best);

  return 0;
}

