struct node {
    int aoki;
    vector<int> neighbor;

    bool isLeaf() const {
        return neighbor.size() == 1;
    }
};

using graph = vector<node>;

void aoki(int s, graph& g) {
    function<void(int, int)> rec = [&](int v, int bv) {
        for (int u : g[v].neighbor) {
            if (u != bv) {
                g[u].aoki = g[v].aoki + 1;
                rec(u, v);
            }
        }
    };

    g[s].aoki = 0; 
    rec(s, -1);
}

int takahashi(int s, graph& g) {
    function<int(int, int, int)> rec = [&](int v, int bv, int step) {
        if (g[v].aoki <= step || g[v].aoki - step == 1 && g[v].isLeaf()) {
            return step;
        }

        int ret = 0;

        for (int u : g[v].neighbor) {
            if (u != bv) {
                ret = max(ret, rec(u, v, step + 1));
            }
        }

        return ret;
    };

    return rec(s, -1, 0);
}

