long long solve() {
  long long res = 0, id = u;
  disv.assign(n, inf);
  disv[v] = 0;
  qu.push(v);
  while(!qu.empty()) {
    long long now = qu.front();
    qu.pop();
    for(long long nextp : edge[now])
      if(disv[nextp] > disv[now] + 1) {
        disv[nextp] = disv[now] + 1;
        qu.push(nextp);
      }
  }
  disu.assign(n, inf);
  disu[u] = 0;
  qu.push(u);
  while(!qu.empty()) {
    long long now = qu.front();
    qu.pop();
    for(long long nextp : edge[now])
      if(disu[nextp] > disu[now] + 1 &&
         disu[now] + 1 < disv[nextp]) {
        disu[nextp] = disu[now] + 1;
        qu.push(nextp);
        id = nextp;
      }
  }
  res = disu[id];
  res += disv[id] - disu[id] - 1;
  return res;
}

