ll dist(graph<ll> const &g, ll const t, ll const a) {
  auto visited = u_set<ll>{};
  auto q = list<tuple<ll, ll>>{tuple<ll, ll>{t, 0}};
  while (!q.empty()) {
    auto &x = q.front();
    ll v = get<0>(x);
    ll d = get<1>(x);
    q.pop_front();
    for (auto const &c : g.at(v)) {
      if (c == a)
        return d + 1;
      if (visited.find(c) == visited.end()) {
        q.emplace_back(tuple<ll, ll>{c, d + 1});
        visited.insert(c);
      }
    }
  }
}
u_map<ll, ll> color(graph<ll> const &g, ll const t, ll const a) {
  auto visited = u_set<ll>{};
  auto q = list<tuple<ll, ll>>{tuple<ll, ll>{a, 0}};
  visited.insert(a);
  auto color = u_map<ll, ll>{};
  while (!q.empty()) {
    auto &x = q.front();
    ll v = get<0>(x);
    ll d = get<1>(x);
    color[v] = d;
    q.pop_front();
    for (auto const &c : g.at(v)) {
      if (visited.find(c) == visited.end()) {
        q.emplace_back(tuple<ll, ll>{c, d + 1});
        visited.insert(c);
      }
    }
  }
  return color;
}
ll runaway(graph<ll> const &g, ll const t, ll const a) {
  auto &&distA = color(g, t, a);
  auto &&depth = color(g, a, t);
  auto visited = u_set<ll>{};
  auto q = list<tuple<ll, ll>>{tuple<ll, ll>{t, 0}};
  visited.insert(a);
  ll ans = 0;
  while (!q.empty()) {
    auto &x = q.front();
    ll v = get<0>(x);
    ll d = get<1>(x);
    ans = max(d, ans);
    q.pop_front();
    for (auto const &c : g.at(v)) {
      if (visited.find(c) == visited.end() && depth[c] > distA[c]) {
        q.emplace_back(tuple<ll, ll>{c, d + 1});
        visited.insert(c);
      }
    }
  }
  return ans;
}
