	TNode() :parent(-1), cost(0), id(-1) {};
};
template<class T>
using Tree = vector<TNode<T>>;

template<class T>
void doublingConstruct(Tree<T>& tree, VVI& doubling) {
	int N = tree.size();
	doubling.push_back(VI(N, -1));
	for (int n = 0; n < N; n++) {
		doubling[0][n] = tree[n].parent;
	}
	VI res(N, -1);
	while (true) {
		bool flag = false;
		VI& d = doubling.back();
		for (int n = 0; n < N; n++)
		{
			if (d[n] != -1) {
				res[n] = d[d[n]];
				flag = true;
			}
			else res[n] = -1;
		}
		if (!flag)return;
		doubling.push_back(res);
	}
}

//木の各要素の深さ(各辺重さ1としたときの根からの距離)
template<class T>
void setDepth(int root,Tree<T>& tree, VI& depth) {
	int N = tree.size();
	depth.resize(N,0);
	queue<int> q;
	q.push(root);
	while(!q.empty()){
		int cur = q.front();
		q.pop();
		int d = depth[cur];
		for (int ch : tree[cur].childs) {
			depth[ch] = d + 1;
			q.push(ch);
		}
	}
}

//木の頂点から指定した回数だけ根の側に進む
template<class T>
int goRoot(Tree<T>& tree, VVI& doubling, int v,int time) {
	int N = tree.size();
	for (int t = 0; t < doubling.size() && v != -1; t++) {
		if ((time & (1 << t))) {
			v = doubling[t][v];
		}
	}
	return v;
}

//LCA
template<class T>
int LCA(Tree<T>& tree, VVI& doubling,VI& depth, int u, int v) {
	if (u == v)return u;
	if (depth[u] > depth[v])swap(u, v);
	v = goRoot(tree, doubling, v, depth[v] - depth[u]);
	//goRoot(u,s) != goRoot(v,s),goRoot(u,e) == goRoot(v,e)
	int s = -1, e = N;
	while (e - s > 1) {
		int m = (e + s) / 2;
		if (goRoot(tree, doubling, u, m) != goRoot(tree, doubling, v, m))s = m;
		else e = m;
	}
	return goRoot(tree, doubling, u, e);
}

template<class Type>
void SetTree(WeightedGraph<Type>& G, Tree<Type>& T, int root = 0) {
	int N = G.size();
	T.resize(N);
	queue<int> q;
	q.push(root);
	T[root].parent = -1;
	T[root].id = -1;
	T[root].cost = 0;
	while (!q.empty()) {
		int cur = q.front();
		q.pop();
		for (Gedge<Type>& e : G[cur]) {
			if (e.to == T[cur].parent)continue;
			T[e.to].parent = cur;
			T[cur].childs.push_back(e.to);
			T[e.to].id = e.id;
			T[e.to].cost = e.cost;
			q.push(e.to);
		}
	}
}

Tree<int> T;
VI depth;
VVI doubling;

VI DDP;

int ddp(int u) {
	if (DDP[u] != -1)return DDP[u];
	DDP[u] = depth[u];
	for (int ch : T[u].childs) {
		chmax(DDP[u], ddp(ch));
	}
	return DDP[u];
}

void solve() {
	WeightedGraph<int> G(N);
	for (int n = 0; n < N-1; n++)
	{
		G[A[n] - 1].push_back({ B[n] - 1,1 });
		G[B[n] - 1].push_back({ A[n] - 1,1 });
	}
	SetTree(G, T, V - 1);
	setDepth(V - 1, T, depth);
	doublingConstruct(T, doubling);
	int dU = depth[U - 1];
	int ans = 0;
	DDP.resize(N, -1);
	VI ord(N);
	for (int n = 0; n < N; n++)
	{
		ord[n] = n;
		DDP[n] = depth[n];
	}
	sort(ord.begin(), ord.end(), [&](int a, int b) {
		return depth[a] > depth[b];
	});
	for (int n = 0; n < N; n++) {
		int cur = ord[n];
		if (T[cur].parent != -1) {
			chmax(DDP[T[cur].parent], DDP[cur]);
		}
	}

	for (int p = 0; p < N; p++) {
		int dp = depth[p];
		if (dU - dp >= (dU%2 ==0?dU:dU+1) / 2) {
			chmax(ans, (dU % 2 == 0 ? dU : dU - 1) / 2);
			continue;
		}
		int temp = dU - dp;
		int dq = ddp(p);
		temp += dq - dp;
		int I = dU + dq - 2 * dp;
		int k0 = ((dq - I) % 2 == 0 ? dq - I : dq - I - 1) / 2;
		int k1 = ((dq - I - 2) % 2 == 0 ? dq - I - 2 : dq - I - 1) / 2;
		temp += min(2*k0, 2*k1+1);
		chmax(ans, temp);
	}
	cout << ans << "\n";

}

