void solve() {
    int n, u, v;
    cin >> n >> u >> v;
    u--; v--;
    vvi g(n, vi());
    int a, b;
    vi ab(n);
    REP(i, n - 1) {
        cin >> a >> b;
        a--; b--;
        ab[a]++;
        ab[b]++;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
    }

    bool ok = false;
    REP(i, n) {
        if (ab[i] > 2) ok = true;
    }
    if (!ok) {
        cerr << n << "." << u << "." << v << endl;
        printve(ab);
        abort();
    }

    vi d(n);

    function<void(int, int)> dfs = [&](int c, int p) {
        if (p != -1) d[c] = d[p] + 1; else d[c] = 0;
        if (p != -1 && sz(g[c]) == 1) return;

        for (auto e : g[c]) {
            if (e == p) continue;
            dfs(e, c);
        }
    };

    dfs(v, -1);

    vi r(n);
    int ans = 0;

    bool f = true;
    function<void(int, int)> dfs2 = [&](int c, int p) {
        if (p != -1) r[c] = r[p] + 1; else r[c] = 0;
        if (r[c] > d[c]) {
            return;
        } else if (r[c] == d[c]) {
            chmax(ans, r[c]);
            return;
        } else if (r[c] + 1 == d[c] and f) {
            chmax(ans, r[c] * 2);
            f = false;
        }
        chmax(ans, r[c]);
        if (p != -1 && sz(g[c]) == 1) {
            chmax(ans, d[p]);
            return;
        }

        for (auto e : g[c]) {
            if (e == p) continue;
            dfs2(e, c);
        }
    };

    dfs2(u, -1);

    cout << ans << endl;
}

