void dfs(Graph<int> &g, vi &path, int p, int v, int &r) {
  static bool fin = false;
  path.push_back(v);
  for (auto nv : g[v]) {
    if (nv == r) {
      path.push_back(nv);
      fin = true;
      return;
    }
    if (nv != p) dfs(g, path, v, nv, r);
    if (fin) return;
  }
  path.pop_back();
}

void dfs2(Graph<int> &g, int p, int v, int d, int &cnt) {
  chmax(cnt, d);
  for (auto nv : g[v]) {
    if (nv != p) dfs2(g, v, nv, d+1, cnt);
  }
}

