ll n, l;
vector<ll> adj[100001];
ll timer;
ll dep[100001]={0};
vector<int> tin, tout;
vector<vector<ll>> up;
void dfs(ll v,ll p)
{
    tin[v]=++timer;
    up[v][0]=p;
    for (int i = 1; i <= l; ++i)
        up[v][i]=up[up[v][i-1]][i-1];
    for (int u : adj[v]) {
        if (u != p)
            { dep[u]=dep[v]+1;
            dfs(u, v);}
    }
    tout[v] = ++timer;
}
bool is_ancestor(ll u,ll v)
{
    return tin[u] <= tin[v] && tout[u] >= tout[v];
}
ll lca(ll u,ll v)
{
    if (is_ancestor(u, v))
        return u;
    if (is_ancestor(v, u))
        return v;
    for (int i = l; i >= 0; --i) {
        if (!is_ancestor(up[u][i], v))
            u = up[u][i];
    }
    return up[u][0];
}
void preprocess(ll root) {
    tin.resize(n+1);
    tout.resize(n+1);
    timer = 0;
    l = ceil(log2(n+1));
    up.assign(n+1, vector<ll>(l + 2));
    dfs(root, root);
}
