void solve(){
    int x = lca(U, V);
    int disV = height[V] - height[x];
    int disU = height[U] - height[x];
    if(disV <= disU){
        ans += (disV + disU - 1) / 2;
        U = father(U, (disV + disU - 1) / 2);
        ans += dp[U];
        if((disU + disV) % 2 == 0)
            ans++;
    }
    else{
        ans += (disV + disU - 1) / 2;
        U = father(V, (disV + disU - 1) / 2);
        if((disU + disV) % 2 == 0){
            ans++;
            U = f[0][U];
        }
        ans += DP[U];
    }
}

