            dfs(v);
            dp[u] = max(dp[v] + 1, dp[u]);
        }
    }
}

void calcDP(int u){
    mark[u] = 0;
    for(auto v: adj[u]){
        if(mark[v]){
            for(auto v2: adj[u])
                if(mark[v2])
                    DP[v] = max(DP[v], dp[v]);
            if(u != 0)
                DP[v] = max(DP[v], 1 + DP[u]);
        }
    }
    for(auto v: adj[u])
        if(mark[v])
            calcDP(v);
}

