}

int lca(int u, int v){
    if(height[u] > height[v])
        swap(u, v);
    for(int i = 19; i >= 0; i--)
        if(f[i][v] != -1 && height[f[i][v]] >= height[u])
            v = f[i][v];
    if(u == v)
        return u;
    for(int i = 19; i >= 0; i--){
        if(f[i][v] != -1 && f[i][v] != f[i][u]){
            v = f[i][v];
            u = f[i][u];
        }
    }
    return f[0][u];
}

int father(int u, int t){
    for(int i = 19; i >= 0; i--){
        if(f[i][u] != -1 && height[u] - height[f[i][u]] <= t){
            t -= height[u] - height[f[i][u]];
            u = f[i][u];
