        --x;
        if(x == u)
            x = 0;
        else if(x == 0)
            x = u;
    }
    for(auto& x : b){
        --x;
        if(x == u)
            x = 0;
        else if(x == 0)
            x = u;
    }
    if(v == 0)
        v = u;
    u = 0;
    for(int i = 0; i < n - 1; ++i){
        edges[a[i]].emplace_back(b[i]);
        edges[b[i]].emplace_back(a[i]);
    }
    HeavyLightDecomposition hld(edges);
    int ans = 0;
    for(int i = 0; i < n; ++i){
        int u_dist = hld.depth[i];
        int v_dist = hld.depth[i] + hld.depth[v] - 2 * hld.depth[hld.lca(i, v)];
