void process(){
    FOR(i, 1, n) LCA[i][0] = Ancestor[i];
    for(int j = 1; (1 << j) <= n; ++j)
        FOR(i, 1, n) if (LCA[i][j-1] != 0){
            LCA[i][j] = LCA[LCA[i][j-1]][j-1];
        }
}

int findLCA(int u, int v){
    if (H[u] < H[v]) swap(u, v);

    int log = log2(H[u]);
    int u1=u, v1=v;

    FORD(i, log, 0)
        if (H[u] - (1 << i)>= H[v]) u = LCA[u][i];

    if (u == v) return u;

    FORD(i, log, 0) if (LCA[u][i] != 0 && LCA[u][i] != LCA[v][i]){
        u = LCA[u][i];
        v = LCA[v][i];
    }
    return Ancestor[u];
}


