}

class SegmentTree {
private:
	int n;
	Array node;

public:
	SegmentTree(Array &v) {
		int sz = v.size();
		n = 1; while (n < sz)n *= 2;
		node.resize(2 * n - 1, 0);
		REP(i, sz) {
			node[i + n - 1] = v[i];
		}
		for (int i = n - 2; i >= 0; i--) {
			node[i] = gcd(node[i * 2 + 1], node[i * 2 + 2]);
		}
	}
	ll getSum(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		if (r <= a || b <= l)return 0;
		if (a <= l && r <= b)return node[k];

		ll vl = getSum(a, b, 2 * k + 1, l, (l + r) / 2);
		ll vr = getSum(a, b, 2 * k + 2, (l + r) / 2, r);
		ll ret = gcd(vl, vr);
		return ret;
	}
};

