void dfs3(Graph &graph, ll  v, ll par,ll d) {
	used[v] = d;
	d++;
	REP(i, graph[v].size()) {
		ll to = graph[v][i].to;
		if (to != par)dfs3(graph, to, v, d);
	}
}


ll dfs2(Graph &graph, ll v, ll par,ll d) {
	d++;
	ll ret = used[v];
	REP(i, graph[v].size()) {
		ll to = graph[v][i].to;
		if (to != par&&used[to]>d) {
			chmax(ret, dfs2(graph, to, v, d));
		}
	}
	return ret;
}

