        for(auto v:G[t1]){
            if(v != p1[t1]){
                if(d[v] > max_d){
                    max_d = d[v];
                    id = v;
                }
            } else {
                par = v;
            }
        }

        if(max_d == 0){
            t1 = par;
            dis--;
        } else if(dis > 2 && d[par] > max_d){
            t1 = par;
            dis--;
        } else {
            t1 = id;
            dis++;
        }

        if(dis == 0)break;

        dis--;
        ans++;
    }

    cout << ans << "\n";

    auto finish = std::chrono::high_resolution_clock::now();  
    std::chrono::duration<double> elapsed = finish - start;
    cerr << "Elapsed time: " << elapsed.count() << " s\n";

    return 0;    
}

