int depth[212345];

int dfs(int u, int par) {
	int &res = depth[u];
	res = 0;
	for (int v : g[u]) if (v != par) {
		chmax(res, dfs(v, u) + 1);
	}
	return res;
}

int solve(int d, int u) {
	if (d == 0) return 0;
	int res = depth[u];
	// 上
	if (d <= 1) return res;
	res++;
	d -= 2;

	// 下, 上
	int x = d / 2;
	res += x * 2;
	return res;
}

