		scanf("%d %d", &A, &B);
		A--; B--;
		g[A].push_back(B);
		g[B].push_back(A);
	}

	LowestCommonAncestor lca(g, false);
	lca.build(V);
	dfs(V, -1);

	int curD = lca.query(U, V);
	int ans = solve(curD, U), cur = 0;

	while (curD > 0) {
		for (int v : g[U]) {
			if (lca.find(v, U) == v) {
				U = v;
				break;
			}
		}
		--curD;
		if (curD == 0) break;

		for (int v : g[V]) {
			int lc = lca.find(U, v);
			if (lc == v) {
				V = v;
				break;
			}
		}
		--curD;
		++cur;

		chmax(ans, cur + solve(curD, U));
	}
	cout << ans << endl;


	return 0;
}

