void dfs(int u, int p)
{
    up[0][u] = p;
    dep[u] = dep[p] + 1;

    for (int i = 1; i <= 20; ++i)
    {
        up[i][u] = up[i - 1][up[i - 1][u]];
    }
    for (int v : gr[u])
    {
        if (v != p) dfs(v, u);
    }

}

int lca(int u, int v)
{
    if (dep[v] > dep[u]) swap(u, v);
    for (int i = 20; i >= 0; --i)
    {
        if (up[i][u] != 0 && dep[up[i][u]] >= dep[v]) u = up[i][u];
    }
    if (u == v) return u;
    for (int i = 20; i >= 0; --i)
    {
        if (up[i][u] != 0 && up[i][v] != 0 && up[i][u] != up[i][v]) u = up[i][u], v = up[i][v];
    }
    return up[0][u];
}
int dist(int u, int v)
{
    int e = lca(u, v);
    return dep[u] - dep[e] + dep[v] - dep[e];
}

