vector<int> lvl_heights(vector<int>G[],int n,int r)
{
    vector<int>V(n+1,-1);
    V[r] = 0;

    queue<int>Q;
    Q.push(r);

    while(!Q.empty())
    {
        int p = Q.front();
        Q.pop();

        int i;
        for(i=0;i!=G[p].size();i++)
        {
            if(V[G[p][i]] == -1)
            {
                V[G[p][i]] = V[p]+1;
                Q.push(G[p][i]);
            }
        }
    }

    return V;
}


int TagTree(vector<int>G[],int n,int u,int v)
{
    if(n == 2)
        return 0;

    vector<int>A = lvl_heights(G,n,v);
    vector<int>T = lvl_heights(G,n,u);      // define

    int i,m;
    m = -1;
    for(i=1;i!=n+1;i++)
    {
        if(G[i].size() == 1)
        {
            if(A[G[i][0]] >= T[G[i][0]])
            {
                m = max(m,A[G[i][0]]);
            }
        }
    }

    return m;
}

