vector<vector<int>> nodes(100000, vector<int>());

bool findPath(int target, int node, vector<int> &path, int from) {
  if (node == target) {
    path.push_back(node);
    return true;
  }
  rep(i, nodes[node].size()) {
    if (nodes[node][i] == from) continue;
    if (findPath(target, nodes[node][i], path, node)) {
      path.push_back(node);
      return true;
    }
  }
  return false;
}

int maxDistance(int from, int node) {
  vector<int> dist;
  rep(i, nodes[node].size()) {
    if (nodes[node][i] != from) {
      dist.push_back(maxDistance(node, nodes[node][i]));
    }
  }
  if (dist.size() == 0) {
    return 0;
  }
  int maxDist = 0;
  rep(i, dist.size()) {
    maxDist = max(maxDist, dist[i]);
  }
  return maxDist + 1;
}

