    A--; B--;
    G[A].emplace_back(B);
    G[B].emplace_back(A);
  }

  vi d(N);
  // get each distance from V
  pii dummy = {-1, -1};
  bfs(V, dummy, d);
  int ret = 0;
  ret += (d[U]-1)/2;

//cerr << "ret " << ret << endl;

  if (ret == 0) {
    cout << d[U]-1 << endl;
    return 0;
  }

  // Approach U to V by ret
  int cur = U;
  int step = 0;
  while (true) {
    if (step == ret) break;

    step++;
    for (auto x : G[cur]) {
      if (d[x]+1==d[cur]) {
        cur = x;
	break;
      }
    }
  }

//cerr << "cur " << cur << endl;
  if (d[U]%2==0) ret++;
//cerr << "ret2 " << ret << endl;

