int main () {
	int N, u, v;
	cin >> N >> u >> v;

	NODE tree[100001];

	for (int i=1; i<=N; i++) {
		tree[i].depth = -1;
		tree[i].parent = -1;
		tree[i].num = 0;
		tree[i].adj = NULL;
	}

	for (int i=0; i<N-1; i++) {
		int a, b;
		cin >> a >> b;
		tree[a].num ++;
		tree[b].num ++;
		if (tree[a].num==1) {
			if ((tree[a].adj = (int *)malloc(sizeof(int))) == NULL) {
				cerr << "malloc" << endl;
				return -1;
			}
		} else {
			if ((tree[a].adj = (int *)realloc(tree[a].adj, tree[a].num*sizeof(int))) == NULL) {
				cerr << "realloc" << endl;
				free (tree[a].adj);
				return -1;

			}
		}
		if (tree[b].num==1) {
			if ((tree[b].adj = (int *)malloc(sizeof(int))) == NULL) {
				cerr << "malloc" << endl;
				return -1;
			}
		} else {
			if ((tree[b].adj = (int *)realloc(tree[b].adj, tree[b].num*sizeof(int))) == NULL) {
				cerr << "realloc" << endl;
				free (tree[b].adj);
				return -1;

			}
		}
		tree[a].adj[tree[a].num-1] = b;
		tree[b].adj[tree[b].num-1] = a;
	}


	tree[v].depth = 0;
	queue<int> que;
	que.push (v);
	while (!que.empty ()) {
		int n = que.front ();
		que.pop ();
		for (int i=0; i<tree[n].num; i++) {
			int idx = tree[n].adj[i];
			if (tree[idx].depth == -1) {
				tree[idx].depth = tree[n].depth + 1;
				tree[idx].parent = n;
				que.push (idx);
			}
		}
	}

	// 中間を探す
	int med = tree[u].depth/2 + 1;
	int mnode = u;
	while (tree[mnode].depth!=med)
		mnode = tree[mnode].parent;

	// 深いところを探す
	int max = med;
	int n = mnode;
	stack<int> st;
	st.push (n);
	while (!st.empty ()) {
		n = st.top ();
		st.pop ();
		if (tree[n].num==1) {
			if (tree[n].depth>max)
				max = tree[n].depth;
		} else {
			for (int i=0; i<tree[n].num; i++) {
				if (tree[n].adj[i] != tree[n].parent) {
					st.push (tree[n].adj[i]);
				}
			}
		}
	}

	cout << max-1 << endl;

	for (int i=0; i<N; i++)
		free (tree[i].adj);

	return 0;
}

