		a--, b--;
		g[a].push_back({ a,b });
		g[b].push_back({ b,a });
	}

	vector<int> depth(n), Maxd(n), par(n);

	function<int(int, int)> dfs = [&](int c, int p) {
		par[c] = p;
		depth[c] = depth[p] + 1;
		int Max = depth[c];
		for (auto itr : g[c]) {
			if (itr.to != p)
				Max = max(Max,dfs(itr.to ,c));
		}
		return Maxd[c] = Max;
	};

	depth[v] = -2;
	dfs(v, v);

	int cur = u, dist = 0, ans = 0;
	while (1) {
		if (depth[cur] == dist) {
