void dfs(Graph G, int u, int v, int turn, int &ans, int i){
  i++;
//  cout<<"u:"<<u<<" v:"<<v<<" turn:"<<turn<<endl;
  if(u==v){
    ans=max(ans,turn);
    return;
  }
  seen[v]=true;
  if(i%2==1){
    for(int next_u: G[u]){
      dfs(G, next_u, v, turn, ans, i);
    }
  }
  else{
    turn++;
    for(int next_v: G[v]){
      if(seen[next_v]) continue;
      dfs(G, u, next_v, turn, ans, i);
    }
  }
}
