using namespace std;

using ll = long long;
const ll MOD = 998244353;

typedef pair<ll, ll> P;
struct edge { ll to, cost; };

const int MAX_V =100000;
const ll INF = 1LL<<60;

int V;
vector<edge> G[MAX_V];
ll d[MAX_V];

void dijkstra(ll s) {
    // greater<P>を指定することでfirstが小さい順に取り出せるようにする
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d + V, INF);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        rep(i,G[v].size()) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

int main() {
    int u, v, A, B;
    cin >> V >> u >> v;
    u--;
    v--;
    rep(i, V - 1) {
        cin >> A >> B;
        A--;
        B--;
        G[A].push_back({B, 1});
        G[B].push_back({A, 1});
    }
    dijkstra(u);
    vector<int> du(V);
    rep(i, V) du[i] = d[i];
    dijkstra(v);
    vector<int> dv(V);
    rep(i, V) dv[i] = d[i];
    int maxdu = 0, maxu = u;
    rep(i, V) {
        if (dv[i] <= du[i]) continue;
        if (du[i] > maxdu) {
            maxdu = du[i];
            maxu = i;
            //cout << maxu << "\n";
        }
    }
    //cout << "maxu=" << maxu << " dv[maxu]=" << dv[maxu] << " du[maxu]=" << du[maxu] << "\n";
