const int N = 1e5 + 123, K = 17;
int n, U, V, h[N], tin[N], tout[N];
int timer, up[K][N];
vi adj[N];

void go(int v, int p) {
	tin[v] = ++timer;
	up[0][v] = p;
	for (int i = 1; i < K; i++) {
		up[i][v] = up[i - 1][up[i - 1][v]];
	}
	for (int to : adj[v]) {
		if (to == p) {
			continue;
		}
		h[to] = h[v] + 1;
		go(to, v);
	}
	tout[v] = timer;
}

bool upper(int x, int y) {
	return tin[x] <= tin[y] && tout[y] <= tout[x];
}

int lca(int x, int y) {
	if (upper(x, y)) {
		return x;
	}
	if (upper(y, x)) {
		return y;
	}
	for (int i = K - 1; i >= 0; i--) {
		if (!upper(up[i][x], y)) {
			x = up[i][x];
		}
	}
	return up[0][x];
}

int d(int x, int y) {
	return h[x] + h[y] - 2 * h[lca(x, y)];
}

int ans = 0;

void dfs(int v, int p) {
	if (d(U, v) < h[v]) {
		ans = max(ans, h[v] - 1);
	}
	for (int to : adj[v]) {
		if (to == p) {
			continue;
		}
		dfs(to, v);
	}
}

