void dijkstra(vector<vector<int>> &G, int s, vector<int> &d) {
    using P = pair<int, int>;
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d.begin(), d.end(), inf);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;

        for (int i=0; i<G[v].size(); ++i) {
            int to = G[v][i];
            if (d[to] > d[v] + 1) {
                d[to] = d[v] + 1;
                que.push(P(d[to], to));
            }
        }
    }
}

