ll par[maxn];
ll gl[maxn];
ll dp[maxn];

void dfs(ll u, ll d) {
	used[u] = 1;
	gl[u] = d;
	dp[u] = d;
	for (ll v : g[u]) {
		if (used[v]) continue;
		par[v] = u;
		dfs(v, d + 1);
		dp[u] = max(dp[u], dp[v]);
	}
}


