int to[N<<1] , nxt[N<<1] , lst[N] ;
inline void add ( int u , int v )
{
	static int cnt=0 ;
	++cnt,to[cnt]=v,nxt[cnt]=lst[u],lst[u]=cnt,
	++cnt,to[cnt]=u,nxt[cnt]=lst[v],lst[v]=cnt;
}

int fa[N] , dep[N] , siz[N] ;
int son[N] , top[N] ;
inline void Dfs1 ( int x , int f )
{
	int i ;
	dep[x]=dep[fa[x]=f]+1,siz[x]=1;
	for ( i=lst[x] ; i ; i=nxt[i] )
		if ( to[i]^f )
			Dfs1(to[i],x),
			siz[x]+=siz[to[i]],
			son[x]=siz[to[i]]>siz[son[x]]?to[i]:son[x];
	return ;
}
inline void Dfs2 ( int x , int c )
{
	int i ;
	top[x]=c;
	if ( !son[x] )
		return ;
	Dfs2(son[x],c);
	for ( i=lst[x] ; i ; i=nxt[i] )
		if ( to[i]^fa[x] && to[i]^son[x] )
			Dfs2(to[i],to[i]);
	return ;
}

inline int Lca ( int u , int v )
{
	while ( top[u]^top[v] )
		if ( dep[top[u]]>dep[top[v]] )
			u=fa[top[u]];
		else
			v=fa[top[v]];
	return dep[u]<dep[v]?u:v;
}

inline int Dis ( int u , int v )
{
	return dep[u]+dep[v]-2*dep[Lca(u,v)];
}

