struct Vertex
{
    int level, parent, deepestLevel;
    vint edges;
};

int DFS(vector<Vertex>& graph, int current, int parent, int level)
{
    graph[current].level = level;
    graph[current].parent = parent;
    if (graph[current].edges.size() == 1 && graph[current].edges[0] == parent)
    {
        graph[current].deepestLevel = level;
        //
        //cout << "sink " << current << endl;
        //
        return level;
    }

    int deepest = -1;
    for (const int to : graph[current].edges)
    {
        if (graph[to].level == 0)
        {
            int currentDeepest = DFS(graph, to, current, level + 1);
            deepest = max(deepest, currentDeepest);
        }
    }
    graph[current].deepestLevel = deepest;
    return deepest;
}

int getLongest(vector<Vertex>& graph, int start)
{
    if (graph[start].edges.size() == 1)
    {
        return graph[start].level;
    }

    int longest = -1;
    for (const int to : graph[start].edges)
    {
        if (to != graph[start].parent)
        {
            longest = max(longest, getLongest(graph, to));
        }
    }
    return longest;
}

