template <typename _Ty>
struct Edge {
    int src, to;
    _Ty cost;

    constexpr Edge(int _to, _Ty _cost) noexcept
        : src(-1), to(_to), cost(_cost) {}
    constexpr Edge(int _src, int _to, _Ty _cost) noexcept
        : src(_src), to(_to), cost(_cost) {}
};
template <typename _Ty>
using WeightedGraph = std::vector<std::vector<Edge<_Ty>>>;

template <typename _Ty>
void dijkstra(std::vector<_Ty>& dist, std::vector<int>& prev,
              const WeightedGraph<_Ty>& g, int s) {
    constexpr _Ty inf = std::numeric_limits<_Ty>::max();
    dist.assign(g.size(), inf);
    prev.assign(g.size(), -1);

    using Pi = std::pair<_Ty, int>;
    std::priority_queue<Pi, std::vector<Pi>, std::greater<Pi>> q;
    dist[s] = 0;
    q.emplace(dist[s], s);
    while (!q.empty()) {
        _Ty cost;
        int idx;
        tie(cost, idx) = q.top();
        q.pop();
        if (dist[idx] < cost) continue;
        for (const auto& edge : g[idx]) {
            _Ty next_cost = cost + edge.cost;
            if (next_cost >= dist[edge.to]) continue;
            dist[edge.to] = next_cost;
            prev[edge.to] = idx;
            q.emplace(next_cost, edge.to);
        }
    }
}

Vi dist, prev_idx;
WeightedGraph<int> g;
Vi checked;
Vi tami;

int dfs(int u) {
    int tmp = dist[u];
    for (const auto& to : g[u]) {
        if (checked[to.to] != 0) continue;
        checked[to.to] = 1;
        tmp = max(tmp, dfs(to.to));
    }
    tami[u] = tmp;
    return tmp;
}

