int64_t N, u, v;

vector<vector<int64_t>> g;

const int64_t kInf = numeric_limits<int64_t>::max();

void Dfs(int64_t i, vector<int64_t>* d) {
  for (auto v_ : g[i]) {
    if ((*d)[v_] == kInf) {
      (*d)[v_] = (*d)[i] + 1;
      Dfs(v_, d);
    }
  }
}

signed main(int argc, char* argv[]) {
  (void)argc;
#ifdef USE_STACK_TRACE_LOGGER
  google::InitGoogleLogging(argv[0]);
  google::InstallFailureSignalHandler();
#else
  (void)argv;
#endif  // USE_STACK_TRACE_LOGGER
  In(N, u, v);
  u--;
  v--;
  g.resize(N);
  rep(i, N - 1) {
    int64_t A, B;
    In(A, B);
    A--;
    B--;
    g[A].emplace_back(B);
    g[B].emplace_back(A);
  }

  if (N == 2) {
    cout << 0 << endl;
    return EXIT_SUCCESS;
  }

  vector<int64_t> du(N, kInf), dv(N, kInf);
  du[u] = 0;
  dv[v] = 0;

  Dfs(u, &du);
  Dfs(v, &dv);

  int64_t ans = 0;
  rep(i, N) {
    bool flag = false;
    for (auto v_ : g[i]) {
      if (g[v_].size() == 1) {
        flag = true;
        break;
      }
    }
    if (flag && du[i] <= dv[i]) {
      ChMax(ans, dv[i]);
    }
  }

  cout << ans << endl;

  return EXIT_SUCCESS;
}

