void dfs1(int root, int parent, int lvl)
{
    level[root] = lvl;
    for (auto x : adj[root])
    {
        if (x == parent) continue;

        dfs1(x, root, lvl + 1);
    }
}

void dfs2(int root, int parent, int dist)
{
    if (level[root] <= dist) return;

    for (auto x : adj[root])
    {
        if (x == parent) continue;

        dfs2(x, root, dist + 1);
    }
    ans = max(ans, level[root] - 1);
}

