      for (const auto& n : tree[c]) {
        if (aoki[n] == -1) {
          aoki[n] = aoki[c] + 1;
          que.push(n);
        }
      }
    }
  }

  { // takahashi
    std::queue<int> que{};
    que.push(u);
    takahashi[u] = 0;
    while (!que.empty()) {
      auto c = que.front();
      que.pop();
      for (const auto& n : tree[c]) {
        if (takahashi[n] == -1) {
          takahashi[n] = takahashi[c] + 1;
          que.push(n);
        }
      }
    }
  }

  int ans{-1};
  for (int i = 0; i < N; ++i) {
    if (takahashi[i] < aoki[i]) {
      chmax(ans, aoki[i]-1);
    }
  }

  assert(ans != -1);
  cout << ans << CRLF;
  return;
}

