        int a,b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    LCA lca(N,0,g);
    int p = lca.lca(U,V);
    vec<int> dp(N,0);
    vec<int> distU(N,0),distV(N,0),distP(N,0);
    auto dfs = [&](auto& self,int cur,int par,vec<int>& dist)-> void{
        for(auto& e:g[cur]) if(e!=par){
            dist[e] = dist[cur]+1;
            self(self,e,cur,dist);
        }
    };

    dfs(dfs,V,-1,distV);
    dfs(dfs,U,-1,distU);
    dfs(dfs,p,-1,distP);
    if(distP[U]<=distP[V]){
        int d = lca.dep(V)+lca.dep(U)-lca.dep(p);
        cout << d/2 << endl;
        return 0;
    }

    int ans = 0;
    for(int i=0;i<N;i++){
        if(distU[i]<distV[i]){
            int d = distV[i]-distU[i];
            ans = max(ans,distU[i]+d/2);
        }
    }
    cout << ans << endl;
}

