struct edge { int to; int cost; };
typedef pair<int,int> P; //first:cost second:vertex (if cost is double plz change)
vector<edge> tree[MAX];
/*
tree[v][i] : edge {vertex x, cost of path [v -> x] } ("i"th path of vertex v)
*/
int d[2][MAX]; //min cost of vertex:s to vertex:i

void dijkstra(int s,int x){
    priority_queue< P,vector<P>,greater<P> > que;
    fill(d[x],d[x]+MAX,INF); // d = {INF,INF,...,INF}
    d[x][s] = 0;
    que.push(P(d[x][s],s));

    while(!que.empty()){
        P p = que.top();
        que.pop();
        int v = p.second;
        if(d[x][v] < p.first){continue;}
        for(int i = 0;i < tree[v].size();i++){
            edge e = tree[v][i];
            if(d[x][e.to] > d[x][v] + e.cost){
                d[x][e.to] = d[x][v] + e.cost;
                que.push(P(d[x][e.to],e.to));
                //cout << "Push" << sp << e.to << sp << d[e.to] << endl;
            }
        }
    }
}

