void bfs(int s, int type) {
  queue<P> q;

  q.push(P(s, 0));
  done[s][type] = true;

  while (q.size()) {
    P p = q.front();
    q.pop();
    int u = p.first;
    dist[u][type] = p.second;
    for (int v: edge[u]) {
      if (done[v][type]) continue;
      q.push(P(v, dist[u][type]+1));
      done[v][type] = true;
    }
  }
}

