{
	ll h=0;
	parent[s]=p;
	for(ll i=0;i<adj_list[s].size();i++)
	{
		if(adj_list[s][i]!=p)
		{
			h=max(h,1+dfs(adj_list[s][i],s));
		}
	}
	height[s]=h;
	return h;
