void bfs(int s,vector<vector<int>> &graph,vector<int> &dis){
    deque<int> que;
    que.push_back(s);
    dis[s] = 1;
    int cnt = 1;
    while(!que.empty()){
        int tn = que.size();
        // cout<<tn<<endl;
        while(tn--){
            auto p = que.front();
            // cout<<"**"<<p<<"**"<<endl;

            que.pop_front();
            for(auto i:graph[p]){
                if(dis[i]) continue;
                dis[i] = cnt;
                que.push_back(i);
            }
        }
        cnt++;
    }
    dis[s-1] = 0;
}

