int main()
{
	scanf("%d%d%d", &n, &u, &v);
	for (int i = 1; i < n; i++)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		a[++m].e = y; a[m].nxt = st[x]; st[x] = m;
		a[++m].e = x; a[m].nxt = st[y]; st[y] = m;
	}
	unordered_set<int> f[2]; // fronts after kth step
	unordered_set<int> p[2]; // visited after kth step
	f[0].insert(u); p[0].insert(u);
	queue<int> vq[2]; vq[0].push(v); vv[v] = true;
	int ans = 0;
	while(true)
	{
		// takahashi's turn
		for (auto x : f[ans & 1])
		{
			for (int j = st[x]; j; j = a[j].nxt)
			{
				int y = a[j].e;
				if (p[!(ans & 1)].count(y)) continue;
				if (vv[y]) continue;
				p[!(ans & 1)].insert(y);
				f[!(ans & 1)].insert(y);
			}
		}
		if (p[!(ans & 1)].empty()) break; // takahashi ran into aoki
		f[ans & 1].clear();
		while (!vq[ans & 1].empty())
		{
			int x = vq[ans & 1].front(); vq[ans & 1].pop();
			for (int j = st[x]; j; j = a[j].nxt)
			{
				int y = a[j].e;
				if (vv[y]) continue;
				vv[y] = true; vq[!(ans & 1)].push(y);
				if (p[0].count(y)) p[0].erase(y);
				if (p[1].count(y)) p[1].erase(y);
				if (f[!(ans & 1)].count(y)) f[!(ans & 1)].erase(y);
			}
		}
		ans++;
		if (p[ans & 1].empty()) break; // aoki erased all positions
	}
	printf("%d\n", ans);
	return 0;
}

