const int INF = 1e9;
using Edge = pair<int,int>;
using Graph = vector<vector<Edge> >; 

template<typename T>
vector<T> dijkstra(const Graph &G, int s){
    vector<T> dist((int)G.size(),INF);
    priority_queue<Edge, vector<Edge>, greater<Edge>> que;
    dist[s] = 0;
    que.push(make_pair(0,s));//頂点と暫定距離

    while(!que.empty()){
        Edge e = que.top();que.pop();
        int v = e.second;
        if(dist[v] < e.first)continue;
        for(auto p : G[v]){
            if(dist[p.first] > dist[v] + p.second){
                dist[p.first] = dist[v] + p.second;
                que.push(make_pair(dist[p.first],p.first));
            }
        }
    } 
    return dist;
}

int main(){ 
  int n, u, v;
