    int u,v;
    cin >> u >> v;
    u--;v--;
    g[u].push_back(make_pair(v,1));
    g[v].push_back(make_pair(u,1));
  }
  auto du = dijkstra<int>(g,u);
  auto dv = dijkstra<int>(g,v);
  int res = 0;
  for (int i = 0; i < n; i++) {
    if (du[i] > dv[i]) continue;
    res = max(res, dv[i]-1);
  }
  cout << res << endl;
  return 0;
}

