using Graph = vector<vector<int>>;
Graph g;

int chase[100005];
int run[100005];

void rec_run(int p, int v) {
    if (p == -1) run[v] = 0;
    else run[v] = run[p] + 1;

    for (auto e : g[v]) {
        if (e == p) continue;
        rec_run(v, e);
    }
}

void rec_chase(int p, int v) {
    if (p == -1) chase[v] = 0;
    else chase[v] = chase[p] + 1;

    for (auto e : g[v]) {
        if (e == p) continue;
        rec_chase(v, e);
    }
}

void solve() {
    int N, u, v; cin >> N >> u >> v;
    u--; v--;

    g.resize(N);
    for (int i = 0; i < N-1; i++) {
        int A, B; cin >> A >> B;
        A--; B--;
        g[A].push_back(B);
        g[B].push_back(A);
    }

    rec_run(-1, u);
    rec_chase(-1, v);

    int ans = 0;
    for (int i = 0; i < N; i++) {
        //print("chase:", chase[i], " run:", run[i]);
        if (chase[i] > run[i]) ans = max(ans, chase[i]);
    }
    ans--;

    cout << ans << '\n';
}

