void read()
{
    cin >> n >> tak_curr >> root ;

    g.resize ( n ) ;
    tak_curr -- ; root -- ;

    for ( int i=0 ; i < n-1 ; i ++ )
    {
        int a , b ;
        cin >> a >> b  ;

        a -- ; b -- ;
        g[a].pb ( b ) ;
        g[b].pb ( a ) ;
    }
}

void dfs ( int node , int parent = -1 )
{
    if ( parent != -1 )
        level[node] = level[parent] + 1 ;

    p[node] = parent ;
    for ( int j : g[node] )
    {
        if ( j == parent ) C ;
        dfs ( j , node ) ;
    }
}

void assign_levels ()
{
    level.resize ( n ) ;
    p.resize ( n ) ;

    dfs ( root ) ;
}

void find_new_position_of_takahashi( int dis )
{
    for ( int i=0 ; i < dis ; i ++ )
        tak_curr = p[tak_curr] ; // climb up dis levels
}

int max_level = -1 ;

void find_max_level_in_new_subtree_of_tak_curr( int node , int parent = -1 )  // This is a dfs
{
    max_level = max ( max_level , level[node] ) ;

    for ( int j : g[node] )
    {
        if ( j == parent ) C ;
        if ( j == p[node] ) C ;

        find_max_level_in_new_subtree_of_tak_curr ( j , node ) ;
    }
}

void solve ( int test_case )
{
    read() ;
    assign_levels() ;

    int dis = level[tak_curr] ;
    if ( dis % 2 == 0 )
        dis -- ;

    dis >>= 1 ;
    int ans = dis ;
    int oki_level = dis ;

    find_new_position_of_takahashi( dis ) ; // by climbing up
    find_max_level_in_new_subtree_of_tak_curr( tak_curr , -1 ) ;

    dis = max_level - level[tak_curr] ;

    int tak_level = max_level ;
    oki_level += dis ;
    ans += dis ;

    // now since oki is parent ( was root ) ; hence we can say that oki and takahashi are cuurently always in
    // the same subtree.

    // and hence ; we just need to find the time taken by oki to make levels of oki and takahashi same !

    int c = 0 ;
    while ( tak_level != oki_level )
    {
        if ( c == 0 ) tak_level -- ;
        else tak_level ++ ;

        if ( tak_level == oki_level )
            break ;

        ans ++ ;
        oki_level ++ ;

        c ^= 1 ;
    }

    cout << ans ; line
}

