 	for (ll i = 0; i < n; i++) {
 		for (ll j = 0; j <= logn; j++) {
 			dp[i][j] = 0;
 		}
 	}
 	for (ll i = 0; i < n; i++) {
 		dp[i][0] = parent[i];
 	}
 	for (ll j = 1; j <= logn; j++) {
 		for (ll i = 0; i < n; i++) {
 			dp[i][j] = dp[dp[i][j - 1]][j - 1];
 		}
 	}
 	ll ans = depth[u] - 1;
 	for (ll i = 0; i < n; i++) {
 	 	ll com = lca(u, i);
