using ll = long long;

ll solve() {
    ll N, U, V, a, b;
    cin >> N >> U >> V;
    U--, V--;
    vector<vector<int>> G(N);
    for ( int i = 0; i < N-1; i++ ) {
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    if ( U == V ) return 0;
    vector<ll> dt(N), da(N);

    function<void(int,int,vector<ll>&)> dfs = [&](int v, int p, vector<ll>& d) {
        if ( p == -1 ) {
            d[v] = 0;
        } else {
            d[v] = d[p] + 1;
        }
        for ( int u : G[v] ) {
            if ( u == p ) continue;
            dfs( u, v, d);
        }
    };

    dfs(U, -1, dt);
    dfs(V, -1, da);

    ll m = 0;
    for ( int i = 0; i < N; i++ ) {
        if ( dt[i] < da[i] ) {
            m = max(m, da[i]);
        }
    }
    if ( m > 0 ) m--;

    return m;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

