    void dfs(ll v=0, ll p=-1){
        used[v]=true;
        if(!found) root.emplace_back(v);
        if(v==goal) found=true;
        for(auto E : G[v]){
            if(used[E.to] == false) dfs(E.to , v);
            if(found) break;
        }
        if(!found) root.pop_back();
        //used[v]=false; //同じところに違う経路で行くなら追加 計算量爆発に注意
