void bfs(int str, int type) {
	dist[str][type] = 0;
	queue<int> q;
	q.push(str);

	while (!q.empty()) {
		int parent = q.front();
		q.pop();

		for (auto child : gr[parent]) {
			if (dist[child][type] == INT_MAX) {
				dist[child][type] = dist[parent][type] + 1;
				q.push(child);
			}
		}
	}
}

int dfs(int curr, int par) {
	int mx_dep = 0;
	for (auto child : gr[curr]) {
		if (child == par or dist[child][0] >= dist[child][1]) continue;
		mx_dep = max(mx_dep, dfs(child, curr));
	}
	return mx_dep + 1;
}

