const int INF = 999999;

template <typename T>
void make_adjacent(int nV, vector<pair<ii,T>>& arcs, vector<vector<pair<int,T>>>& adj) {
	adj.resize(nV);
	for (pair<ii, T> p: arcs) {
		int u = p.first.first, v = p.first.second;
		assert(u != v);
		T distance = p.second;
		adj[u].push_back(make_pair(v, distance));
		adj[v].push_back(make_pair(u, distance));
	}
}

template <typename T>
void dij1(int nV, vector<vector<pair<int,T>>>& adjacent, vector<T>& d, int start) {
	d.assign(nV, INF);
	d[start] = 0;
	vector<int> prev(nV, -1);

	priority_queue<pair<T, int>> Q;
	Q.push(make_pair(0, start));

	vector<bool> visited(nV, false);

	while (!Q.empty()) {
		T du = -Q.top().first;
		int u = Q.top().second; Q.pop();
		if (visited[u]) continue;
		visited[u] = true;

		int c = adjacent[u].size();
		for (int i=0; i<c; ++i) {
			int v = adjacent[u][i].first;
			T distance = adjacent[u][i].second;
			T alt = du + distance;
			if (d[v] > alt) {
				d[v] = alt;
				prev[v] = u;
				Q.push(make_pair(-alt, v));
			}
		}
	}
}

int solve(int N, int u,int v, vi& a, vi& b) {
    vector<vector<ii>> adj(N);

    rep(i,N-1){
        adj[ a[i] ].emplace_back(b[i], 1);
        adj[ b[i] ].emplace_back(a[i], 1);
    }

    vi da(N, INF), db(N, INF);
    dij1(N, adj, da, u);
    dij1(N, adj, db, v);

    int best = db[u]-1;
    vii de(N);
    rep(i,N){
        if (db[i] <= da[i]) continue;
        amax(best, max(da[i], db[i]-1));
    }
    return  best;
}

int main() {
    int N,u,v; scanf("%d %d %d%*c", &N, &u, &v);
    --u; --v;
    vi a(N-1),b(N-1);
    rep(i,N-1){
        scanf("%d %d%*c", &a[i], &b[i]);
        a[i]--; b[i]--;
    }
    cout << solve(N,u,v,a,b) << endl;
    return 0;
}

