const int inf = 1e9;

void show(const VI &v) {
	for (int i = 0; i < v.size(); i++) {
		printf("%d: %d\n", i+1, v[i]);
	}
}

VI make_dist(int st, const VVI &connect) {
	int n = connect.size();
	VI dist(n, inf);
	queue<int> que;
	que.push(st);
	dist[st] = 0;

	while (!que.empty()) {
		auto x = que.front();
		que.pop();

		for (auto y: connect[x]) {
			if (dist[y] == inf) {
				dist[y] = dist[x] + 1;
				que.push(y);
			}
		}
	}
	return dist;
}

int get_closer(int pos, const VI &dist, const VVI &connect) {
	int to = pos;
	for (auto x: connect[pos]) {
		if (dist[x] < dist[to]) {
			to = x;
		}
	}
	return to;

}

