    int a, b; cin >> a >> b;
    a--;
    b--;
    g[a].push_back({b, 1});
    g[b].push_back({a, 1});
  }

  auto fst = dijkstra(g, u);
  auto scd = dijkstra(g, v);

  // fst が真に小さい頂点のうち，最大のもの
  int ans = 0;
  for(int i = 0; i < n; i++) {
    if(fst[i] < scd[i]) {
      ans = max(ans, scd[i]);
    }
  }

  cout << ans - 1 << endl;

  return 0;
}

