using ll = long long;

using namespace std;
#define MAX_N 100010

using P = pair<int, int>;
#define fi first
#define se second

int n, taka, aoki;
vector<P> G[100010];

// 各点への最短経路 dijkstra
int ad[MAX_N], td[MAX_N];  //頂点kから各点への距離
void dijkstra(int k, int *d) { //Gは隣接行列 G[i][j].firstが距離, secondが向かう頂点名, kはスタートする頂点
    fill(d, d+n, MAX_N); d[k] = 0;
    priority_queue< P, vector<P>, greater<P> > que;
    que.push(P(0, k));
    while (!que.empty()) {
        P p = que.top(); que.pop();
        int now = p.second;
        if (d[now] < p.first) continue;
        for (auto g:G[now]) {
            int to = g.second;
            long newd = g.first + d[now];
            if (d[to] > newd) {
                d[to] = newd;
                que.push(P(d[to], to));
            }
        }
    }
}


