        G[a].push_back({1, b});
        G[b].push_back({1, a});
    }
    dijkstra(aoki, ad);
    dijkstra(taka, td);
    int ans = 0;
    for (int i=0; i<n; i++) {
        if (td[i] <= ad[i]) {
            ans = max(ad[i], ans);
        }
    }
    cout << ans - 1 << '\n';
    return 0;
}

