struct solver
{

    solver()
    {
        int n; cin>>n;
        int u,v; cin>>u>>v; --u,--v;
        vector<vector<int>> g(n);
        for(int i=1; i<n; ++i)
        {
            int a,b; cin>>a>>b; --a,--b;
            g[a].emplace_back(b);
            g[b].emplace_back(a);
        }

        vector<int> dist1(n,n),dist2(n,n);

        queue<int> que;

        que.push(u);
        dist1[u]=0;
        while(!que.empty())
        {
            int f=que.front();
            que.pop();
            for(int ff:g[f])
            {
                if(sbmin(dist1[ff],dist1[f]+1))
                {
                    que.push(ff);
                }
            }
        }

        que.push(v);
        dist2[v]=0;
        while(!que.empty())
        {
            int f=que.front();
            que.pop();
            for(int ff:g[f])
            {
                if(sbmin(dist2[ff],dist2[f]+1))
                {
                    que.push(ff);
                }
            }
        }

        int ans=0;

        for(int v=0; v<n; ++v)
        {
            if(dist1[v]<dist2[v])
            {
                sbmax(ans,dist2[v]-1);
            }
        }
        cout << ans << '\n';
    }
};

