int main(int argc, const char * argv[]) {
    ios_base::sync_with_stdio(false);
    int N, U, V;
    cin >> N >> U >> V;
    --U; --V;
    vector<vector<int>> G(N, vector<int>());
    for (int n = 0; n < N-1; ++n) {
        int A, B;
        cin >> A >> B;
        --A; --B;
        G[A].push_back(B);
        G[B].push_back(A);
    }

    queue<int> Q;
    vector<int> Used(N);
    vector<int> Rank(N);
    Q.push(V);
    Rank[V] = 0;
    Used[V] = 1;
    while (!Q.empty()) {
        int Tmp = Q.front(); Q.pop();
        for (int Next : G[Tmp]) {
            if (Used[Next]) {
                continue;
            }
            Used[Next] = 1;
            Rank[Next] = Rank[Tmp] + 1;
            Q.push(Next);
        }
    }

    Used.assign(N, 0);
    vector<int> Tak(N, -1);
    Q.push(U);
    Used[U] = 1;
    Tak[U] = 0;
    while (!Q.empty()) {
        int Tmp = Q.front(); Q.pop();
        for (int Next : G[Tmp]) {
            if (Used[Next]) {
                continue;
            }
            Used[Next] = 1;
            if (Rank[Next] > Tak[Tmp] + 1) {
                Tak[Next] = Tak[Tmp] + 1;
                Q.push(Next);
            }
        }
    }

    int MaxRank = 0;
    for (int n = 0; n < N; ++n) {
        if (Tak[n] < 0) {
            continue;
        }
        MaxRank = max(MaxRank, Rank[n]);
    }

    cout << MaxRank - 1 << endl;

    return 0;
}

