    in(n);
    in(x),in(y);
    pre();
    for(i=1;i<n;i++)
    {
        in(a),in(b);
        ad[a].pb(b);
        ad[b].pb(a);
    }
    lev[1]=0;
    dfs(1);
    build();
    a=0;
    for(i=1;i<=n;i++)
    {
        if(dist(i,y)>dist(i,x))
            a=max(a,dist(i,y));
    }
    out(a-1);
}

