graph::graph(int n,int m,int origin){
  order=comp=n;
  adj.resize(n);
  par.resize(n,-1);
  depth.resize(n);
  outcome.resize(n);
  rep(i,m){
    int u,v;cin >>u >>v; u-=origin; v-=origin;
    adj.at(u).push_back(v);
    adj.at(v).push_back(u);
  }
}

int graph::dfs_tree(int u){
  static int dep=0;

  depth.at(u)=dep;
  int m=dep-1;
  dep++;
  for(auto v:adj.at(u)){
    if(v==par.at(u)) continue;
    par.at(v)=u;
    int temp=dfs_tree(v);
    if(temp>m)m=temp;
  }
  dep--;
  outcome.at(u)=m;
  return m;
}
