bool fill_path(ll u, ll p, ll goal, VL& path, VVL& edge_list) {
  if (p >= 0 && edge_list[u].size() == 1 && u != goal) return false;

  path.push_back(u);
  if (u == goal) return true;

  bool exist = false;

  for (auto v : edge_list[u]) {
    if (v == p) continue;

    if (fill_path(v, u, goal, path, edge_list)) {
      exist = true;
      break;
    }
  }

  if (!exist) path.pop_back();

  return exist;
}

ll N, tU, aV;
VVL edge_list;
ll limit_v, ng_v;
// VL t_ds;
VL a_ds;

ll dfs(ll u, ll p) {
  ll res = a_ds[u] - 1;

  for (ll v : edge_list[u]) {
    if (v == ng_v || v == p) continue;

    ll _res = dfs(v, u);
    chmax(res, _res);
  }

  return res;
}

void fill_ds(ll u, ll p, ll cur_d, VL& ds) {
  chmin(ds[u], cur_d);

  for (ll v : edge_list[u]) {
    if (v == p) continue;
    fill_ds(v, u, cur_d + 1, ds);
  }
}

