  cin >> N >> takahashi >> aoki;
  takahashi--;
  aoki--;
  vector<vector<int>> ki(N);
  for(int i = 0; i < N-1; i++){
    int a, b;
    cin >> a >> b;
    ki.at(a-1).push_back(b-1);
    ki.at(b-1).push_back(a-1);
  }
  searchPath(aoki, ki);
  route.erase(route.begin());
  /*for(int i = 0; i < route.size(); i++){
    cout << route.at(i) <<endl;
  }*/
  halfSize = route.size() / 2;
  if(route.size() == 0){
    used2.at(aoki) = true;
    used2.at(takahashi) = true;
    longestPath(takahashi, ki, 0);
  }
  else if(route.size() == 1){
    used2.at(route.at(halfSize)) = true;
    used2.at(takahashi) = true;
    longestPath(takahashi, ki, 0);
  } else{
    used2.at(route.at(halfSize)) = true;
    used2.at(route.at(halfSize-1)) = true;
    longestPath(route.at(halfSize-1), ki, 0);
  }
  int Path = route.size() - halfSize + Max;
  if(route.size() % 2 == 0){
    Path++;
  }

  if(route.size() % 2 == 0){
    //cout << Max <<endl;
    cout << Path - 1 <<endl;
  }
  else{
    cout << Path <<endl;
  }
}

