vector<int> dist(vector<vector<int>> &adj, int a) {
  int n = adj.size();
  vector<int> ans(n, -1);
  queue<int> q;
  q.push(a);
  ans[a] = 0;
  while (!q.empty()) {
  	int f = q.front();
    q.pop();
    for (const int &i : adj[f]) {
      if (ans[i] == -1) {
      	ans[i] = ans[f] + 1;
        q.push(i);
      }
    }
  }
  return ans;
}

