vector<int> ShortestPathTree(const VVI& g, int s) {
	int V = g.size();
	vector<int> dist(V);
	function<void(int, int, int)> dfs = [&](int v, int p, int depth) {
		dist[v] = depth;
		for (auto e : g[v])if (e != p) {
			dfs(e, v, depth + 1);
		}
	};
	dfs(s, -1, 0);
	return dist;
}

