    A[i]--; B[i]--;
    G[A[i]].push_back(edge(B[i], 1));
    G[B[i]].push_back(edge(A[i], 1));
  }
  LCA lca(N);
  lca.init(0, -1, 0, 0);
  lca.build();
  D[v] = 0;
  dfs(v, -1, 0);
  int offset = 1 - (D[u] % 2);
  ll ans = 0;
