bool dfs1(int x,int fa)
{
    if(visp[x] > viss[x]) return false;
    if(visp[x] == viss[x])
    {
        //printf("%d %d\n",x,visp[x]);
        ans = max(visp[x],ans);
        return false;
    }
    int flag= 0;
    for(int v:G[x])
    {
        if(visp[v]||fa == v) continue;
        visp[v] = visp[x] +1;
        flag += dfs1(v,x);
    }
    if(flag || fa != x)
    {
        int res = viss[x];
        res -= (viss[x] - visp[x]) % 2;
        //printf("%d %d %d %d\n",x,res,visp[x],viss[x]);
        ans = max(res, ans);
    }
}
