  }
  graph g(N);
  REP(i,N-1){
    g.add_edge(A[i].fi,A[i].se,1);
    g.add_edge(A[i].se,A[i].fi,1);
  }
  g.dijkstra(t);
  vector<ll> taka=g.d;
  g.dijkstra(a);
  vector<ll> aoki=g.d;

  // REP(i,N){
  //   cout << taka[i] << " " << aoki[i] << endl;
  // }

  ll MAX=-1;
  REP(i,N){
