      MAX=max(MAX,taka[i]);
    }
  }

  ll MAX2=-1;
  REP(i,N){
    if(taka[i]==MAX&&taka[i]<aoki[i]){
      MAX2=max(MAX2,aoki[i]);
    }
  }

  cout << MAX2-1 << endl;
}

