const int N = 1e5 + 5;
const int INF = 1e9 + 7;
int n, a, b, ans, dist1[N], dist2[N];
vector<int> g[N];

void solve() {
	cin >> n >> a >> b;
	for (int i = 1; i < n; ++i) {
		int u, v;
		cin >> u >> v;
		g[u].pb(v);
		g[v].pb(u);
	}
	for (int i = 1; i <= n; ++i) dist1[i] = dist2[i] = INF;
	queue<int> q;
	q.push(a);
	dist1[a] = 0;
	while (!q.empty()) {
		auto t = q.front();
		q.pop();
		for (auto d : g[t]) {
			if (dist1[d] == INF) {
				dist1[d] = dist1[t] + 1;
				q.push(d);
			}
		}
	}
	dist2[b] = 0;
	q.push(b);
	while (!q.empty()) {
		auto t = q.front();
		q.pop();
		for (auto d : g[t]) {
			if (dist2[d] == INF) {
				dist2[d] = dist2[t] + 1;
				q.push(d);
			}
		}
	}
	int ans = 0;
	for (int i = 1; i <= n; ++i) {
		if (dist1[i] < dist2[i]) {
			ans = max(ans, dist2[i] - 1);
		}
	}
	cout << ans;
}

