    void print(const T& container)
    {
        bool first = true;
        for (auto&& x : container) {
            if (!first) {
                cout << ' ';
            }
            cout << x;
            first = false;
        }
        cout << '\n';
    }
};

void turn(std::vector<int>& tree, int root)
{
    if (root != tree[0]) {
        turn(tree, tree[root]);
    }
    int prevRoot = tree[0];
    tree[0] = tree[prevRoot] = root;
    tree[root] = -1;
}

void depth(const std::vector<int>& tree, std::vector<int>& d, int node)
{
    if (d[node] != -1) return;
    if (node == tree[0]) {
        d[node] = 0;
        return;
    }
    if (tree[node] == -1) {
        d[node] = 0;
        return;
    }
    if (d[tree[node]] == -1) {
        depth(tree, d, tree[node]);
    }
    d[node] = d[tree[node]] + 1;
}

