struct UnionFind{
    vector<int>par;

    UnionFind(int n):par(n){
        for(int i=0;i<n;i++)par[i] = i;
    }
    int find(int x){
        if(par[x] == x)return x;
        else return par[x] = find(par[x]);
    }
    void unite(int x,int y){
        int rx = find(x);
        int ry = find(y);
        if(rx != ry)par[rx] = ry;
    }
    bool same(int x,int y){
        return find(x)==find(y);
    }
};

