using Edges = vector<int>;


void BFS(vector<Edges> &G, vector<int> &pred, vector<int> &dist, vector<int> &checked ,int s, int n){
  for(int v=0; v<n; ++v){
    pred[v] = -1;
    dist[v] = qweqwe::constnumber::INF_i32;
    checked[v] = 0;
  }
  checked[s] = 1;
  dist[s] = 0;
  queue<int> Q;
  Q.push(s);
  while(!Q.empty()){
    auto u = Q.front();
    for(auto v : G[u]){
      if(checked[v]==0){
        dist[v] = dist[u] + 1;
        pred[v] = u;
        checked[v] = 1;
        Q.push(v);
      }
    }
    Q.pop();
    checked[u] = 2;
  }
}

void solve(){
  int n, u, v;
  cin >> n >> u >> v;
  --u; --v;
  vector<Edges> g(n);
  vector<int> par(n), distv(n), distu(n),checked(n);
  FOR(i,0,n-1){
    int a, b;
    cin >> a >> b;
    --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  BFS(g,par,distv,checked,v,n);
  BFS(g,par,distu,checked,u,n);
  vector<pair<int,int>> distv_(n);
  FOR(i,0,n) distv_[i] = pair<int,int>(distv[i],i);
  sort(distv_.begin(), distv_.end() );
  reverse( distv_.begin(), distv_.end());
  int ao=0, tk=0, fr=0;
  FOR(i,0,n){
    vector<int> distf(n);
    BFS(g,par,distf,checked,i,n);
    if(distv[u] > distv[i] || distf[v] < distf[u]) continue;
    ao = 0;
    tk = distv[u];
    fr = distv_[i].first;//cout << i << endl;
    break;
  }
  int ans = 0; int vc = 1;//cout << ao << "," << tk <<","<<fr<<endl;
  while(tk > ao){
    if(tk==ao) break;
    if(tk>=fr) vc = (-1);
    if(tk<fr) vc = 1;
    tk += vc;
    if(tk==ao) break;
    ++ao;
    ++ans;//cout << ao << " " << tk << endl;
  }
  cout << ans << endl;
}

