void solve(){
    int N,u,v;cin>>N>>u>>v;
    u--;v--;
    vector<vector<int>> tree(N);
    REP(i,N-1){
        int a,b; cin>>a>>b;
        a--;b--;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }
    int dtl=0,dtv=0;
    int flag=0;
    if(tree[u].size()==1) flag++;
    vector<int> d;
    function<bool(int,int,int)> dfs=[&](int now,int pre,int len){
        if(now==v){
            dtv=len;
            return true;
        }
        if(tree[now].size()==1) d.push_back(len);
        bool res=false;
        for(auto e:tree[now]){
            if(e==pre) continue;
            if(dfs(e,now,len+1)){
                res=true;
                if(len==(dtv-1)/2) u=now;
                if(len==dtv-1) for(auto e2:tree[now]){
                    if(e2==pre) continue;
                    if(e2==e) return true;
                    d.pop_back();
                }
            }
        }
        return res;
    };
    dfs(u,-1,0);
    d.clear();
    int ans=(dtv-1)/2;
    if(dtv%2==0) ans++;
    if(flag==1&&dtv<=2){
        cout<<ans<<endl;
        return;
    }
    dtl=0;
    dfs(u,-1,0);
    REP(i,d.size()) chmax(dtl,d[i]);
    ans+=dtl;

    cout<<ans<<endl;
}

