void bfs(ll node, ll N, const v<v<ll>> &edge, v<ll> &dist)
{
    v<bool> visit(N+1);
    queue<ll> q;
    q.push(node);
    dist.clear();
    dist.resize(N+1);

    dist[node] = 0;
    while(!q.empty()){
        node = q.front();
        q.pop();
        visit[node] = true;

        for(const auto n : edge[node]){
            if(visit[n]) continue;
            q.push(n);
            dist[n] = dist[node] + 1;
        }
    }
}

int main()
{
    ll N, u, V;
    cin >> N >> u >> V;
    v<v<ll>> edge(N + 1);
    for(ll i = 0; i < N; ++i){
        ll a, b;
        cin >> a >> b;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    v<ll> dist_u(N+1), dist_v(N+1);
    bfs(u, N, edge, dist_u);
    bfs(V, N, edge, dist_v);
    ll d_v = 0;
    for(ll i = 1; i <= N; ++i){
        if(dist_v[i] > dist_u[i]){
            d_v = max(d_v, dist_v[i]);
        }
    }
    cout << d_v - 1;
    cout << endl;
}

