constexpr int MOD = 1000000007;

void bfs(const vvi& G, vi& d, int root) {
    int n = G.size();

    queue<int> q;
    vb seen(n, false);

    q.push(root);
    seen[root] = true;
    d[root] = 0;

    while (!q.empty()) {
        int curr = q.front();
        q.pop();

        for (int next : G[curr]) {
            if (seen[next]) { continue; }

            q.push(next);
            seen[next] = true;
            d[next] = d[curr] + 1;
        }
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, u, v;
    cin >> n >> u >> v;
    --u;
    --v;

    vvi G(n);
    rep(i, 0, n - 1) {
        int a, b;
        cin >> a >> b;
        G[a - 1].push_back(b - 1);
        G[b - 1].push_back(a - 1);
    }

    // O(n)
    vi from_u(n, -1), from_v(n, -1);
    bfs(G, from_u, u);
    bfs(G, from_v, v);

    // uとvの間の距離．
    int dist = from_u[v];

    int ans = 0;
    rep(i, 0, n) {
        // uとvの直線上にある場合．
        if (from_u[i] + from_v[i] == dist) {
            ans = max(ans, dist - 1);
            continue;
        }

        // uとvの間にあり，直線上にない場合．
        int d = abs(from_u[i] - from_v[i]);
        if (d < dist) {
            if (from_u[i] < from_v[i]) {
                int tmp = from_u[i] + d - 1;
                ans = max(ans, tmp);
            }
            continue;
        }

        // uとvの間にない場合．
        if (from_u[i] > from_v[i]) {
            int tmp = from_u[i] + dist - 1;
            ans = max(ans, tmp);
        }
    }

    cout << ans << endl;
    return 0;
}

