int main(){
	int n,u,v;	cin>>n>>u>>v;
	for(int i=1;i<n;i++){
		int a,b;	cin>>a>>b;
		Tree[a].push_back(b);
		Tree[b].push_back(a);
	}

	// Aoki
	memo[v]=0;	visited[v]=true;
	stack<int> s;	s.push(v);

	while(s.empty()==false){
		int now=s.top();	s.pop();
		for(int next:Tree[now]){
			if(visited[next])continue;

			visited[next]=true;
			memo[next]=memo[now]+1;		s.push(next);
		}
	}

	//for(int i=1;i<=n;i++)printf("cost[%d]: %d\n",i,memo[i]);

	for(int i=1;i<=n;i++)visited[i]=false;

	s.push(u);	memo2[u]=0;	visited[u]=true;
	while(s.empty()==false){
		int now=s.top();	s.pop();
		for(int next:Tree[now]){
			if(visited[next])continue;

			visited[next]=true;
			memo2[next]=memo2[now]+1;		s.push(next);
		}
	}

	int ans=0;
	for(int i=1;i<=n;i++){
		if(memo[i]<memo2[i])continue;

		ans=max(ans,memo[i]);
	}

	cout<<ans-1<<endl;

	return 0;
}

