    bool getRouteFromVToU(const int previous, const int current, vector<int>& route) {
        route.emplace_back(current);
        if (current == u_) return true;
        for (const auto& next : edges_[current]) {
            if (next == previous) continue;
            bool correct = getRouteFromVToU(current, next, route);
