int N, U, V;
int aokidepth[100000], takdist[100000], aokidist[100000];
bool came[100000], cango[100000];
vector<int> graph[100000];

void takdfs(int v, int p, int c) {
    takdist[v] = c;
    came[v] = true;
    for(int x : graph[v]) {
        if(x == p || x == V) continue;
        takdfs(x, v, c + 1);
    }
}

void aokidfs(int v, int p, int c) {
    aokidist[v] = c;
    aokidepth[v] = c;
    if(aokidist[v] > takdist[v]) cango[v] = true;
    for(int x : graph[v]) {
        if(x == p) continue;
        aokidfs(x, v, c + 1);
    }
}

