        pll p=que.top();que.pop();
        ll v=p.second;
        if(d[v]<p.first) continue;
        rep(i,(ll)G[v].size()){
            edge e=G[v][i];
            if(d[e.to]>d[v]+e.cost){
                d[e.to]=d[v]+e.cost;
                prever[e.to] = v;
                que.push(pii(d[e.to],e.to));
            }
        }
    } 
}

