/*
計算量：O(ElogV)
引数
　g:探索するグラフ
　start:探索するスタートノード番号
戻り値
　dist:スタートノードから各頂点までの距離
　prev:最短路木の親頂点
*/
void bfs01(const vector<vector<Edge>> &g, ll start, vector<ll> &dist, vector<ll> &prev) {
	ll gsize = g.size();
	dist.assign(gsize, INF); dist[start] = 0;
	prev.assign(gsize, -1);

	deque<ll> que;
	que.emplace_back(start);
	while (!que.empty()) {
		ll e = que.front();
		que.pop_front();
		for(auto&& f : g[e]) {
			if (dist[f.to] > dist[e] + f.cost) {
				dist[f.to] = dist[e] + f.cost;
				prev[f.to] = e;
				if(f.cost) que.emplace_back(f.to);
				else que.emplace_front(f.to);
			}
		}
	}
}
//最短路木の親頂点を元にstart->goalの経路を作成
vector<ll> buildPath(const vector<ll> &prev, ll goal) {
	vector<ll> path;
	for (ll u = goal; u >= 0; u = prev[u])
		path.push_back(u);
	reverse(path.begin(), path.end());
	return path;
}

