void solve() {
	scanf("%lld%lld%lld", &N, &startT, &startA);
	startT--;startA--;
	A.assign(N, 0);
	B.assign(N, 0);
	rep(i, N-1) { scanf("%lld%lld", &A[i], &B[i]); A[i]--;B[i]--;}

	vector<vector<Edge>> g(N);
	vector<vector<ll>> glca(N);
	rep(i,N-1){
		Edge e(A[i],B[i],1);
		Edge e1(B[i],A[i],1);
		g[A[i]].push_back(e);
		g[B[i]].push_back(e1);
		glca[A[i]].push_back(B[i]);
		glca[B[i]].push_back(A[i]);
	}

	vector<ll> dist, prev;
	bfs01(g, startT, dist, prev);

	vector<ll> distA, prevA;
	bfs01(g, startA, distA, prevA);


	DoublingLowestCommonAncestor< vector<vector<ll>> > lca(glca);
	lca.build();

	vector<ll> dis(N,-1);
	rep(i,N){
		ll lcav=lca.query(startT,i);
		if(distA[lcav] > dist[lcav]){
			dis[i]=distA[i];
		}
	}
	ll maxval=-1;
	rep(i,N){
		chmax(maxval,dis[i]);
	}
	ll ans = maxval-1;
	printf("%lld\n", ans);
}

