const int N = 1e5 + 5;

struct lca
{
	v32 ndist;
	vector<v32> up;
	int lgn;
	void dfs(int ii, int pp, graph &g)
	{
		for (auto jj : g[ii])
			if (jj != pp)
			{
				ndist[jj] = 1 + ndist[ii];
				up[jj][0] = ii;
				dfs(jj, ii, g);
			}
	}
	lca(int n, int src, graph &g)
	{
		lgn = ceil(1.0 * log2(n + 1));
		ndist.assign(n + 1, 0);
		up.assign(n + 1, v32(lgn, -1));
		ndist[src] = 0;
		up[src][0] = src;
		dfs(src, 0, g);
		for (int i = 1; i < lgn; i++)
			for (int j = 1; j < n + 1; j++)
				up[j][i] = up[up[j][i - 1]][i - 1];
	}
	int getLCA(int a, int b)
	{
		if (ndist[a] > ndist[b])
			swap(a, b);
		int diff = ndist[b] - ndist[a];
		for (int i = 0; i < lgn; i++)
			if (diff & (1 << i))
				b = up[b][i];
		if (a == b)
			return a;
		for (int i = lgn - 1; i >= 0; i--)
			if (up[a][i] != up[b][i])
				a = up[a][i], b = up[b][i];
		return up[a][0];
	}
	int getDist(int a, int b)
	{
		int ans = ndist[a] + ndist[b] - 2 * ndist[getLCA(a, b)];
		return ans;
	}
};

void dfs(int ii, int pp, graph &g, int h, int &mx)
{
	mx = max(h, mx);
	for (auto jj : g[ii])
		if (jj != pp)
			dfs(jj, ii, g, h + 1, mx);
	return;
}

