        }
        if (a == b)
            return a;
        REPD(k, LOG - 1, 0)
        if (prt[a][k] != prt[b][k])
        {
            a = prt[a][k];
            b = prt[b][k];
        }
        return prt[a][0];
    }
    void init(int _n)
    {
        n = _n;
        REP(i, 1, n)
        g[i].clear();
    }
    void addEdge(int u, int v)
    {
        g[u].push_back(v);
        g[v].push_back(u);
    }
    void yutruli()
    {
        dfssz(1, 0);
        REP(k, 1, LOG - 1)
        REP(i, 1, n)
        prt[i][k] = prt[prt[i][k - 1]][k - 1];
    }
    int dist(int x, int y)
    {
        int l = lca(x, y);
        return dep[x] + dep[y] - 2 * dep[l];
    }
} tree;

