// 根付き木の各頂点の親, 深さ, 高さを求める
int root;
#define MAX_N 200001
vector<vector<int>>graph(MAX_N, vector<int>());
int par[MAX_N], depth[MAX_N], height[MAX_N]; // 0で初期化
void tree_init(int r){
    root = r;
    par[root] = -1;
    stack<int> st_op, st_cl;
    st_op.push(root);
    while (! st_op.empty()) {
        int t = st_op.top(); st_op.pop();
        st_cl.push(t);
        for (int x: graph[t]) {
            if (x == par[t]) continue;
            depth[x] = depth[t] + 1;
            par[x] = t;
            st_op.push(x);
        }
    }
    while (! st_cl.empty()) {
        int t = st_cl.top(); st_cl.pop();
        for (int x: graph[t]) {
            if (x == par[t]) continue;
            height[t] = max(height[t], height[x] + 1);
        }
    }
}

