        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    tree_init(v);
    int cnt = (depth[u] - 1) / 2;
    for (int i = 0; i < cnt; ++i) {
        u = par[u];
    }
    // 鬼は必ず高さ1の頂点で捕まえる
    int ans = depth[u] + height[u] - 1;
    cout << ans << "\n";
    return 0;
}

