                if (best_value < tdist[i] && tdist[i] < adist[i] && tdist[i] != -1) {
                    best_value = tdist[i];
                    best_key = i;
                }
            }
        }

        Int ans = adist[best_key] - 1;
        cout << ans << endl;

    }
};


