    int N,u,v; cin >> N >> u >> v;
    --u,--v;
    LowestCommonAncester LCA(N);
    rep(i,N-1){
        int a,b; cin >> a >> b;
        LCA.add_edge(--a,--b);
    }
    LCA.build();
    int l=LCA.distance(u,v);
    int ans=0;
    rep(i,N){
        int p=LCA.lca(u,i),d1=LCA.distance(u,p),d2=LCA.distance(v,p);
        if (d2<=d1){
            chmax(ans,l/2);
            continue;
        }
        chmax(ans,LCA.distance(v,i)-1);
    }
    cout << ans << endl;
}

