using namespace std;

const int N = 100'009;

vector<int> g[N];
int w[N];
int pa[N];
int q[N];
int d[N];
int sum[N];
int best[N];
int fb[N];

int main() {
  int n, a, b;
  scanf("%d%d%d", &n, &a, &b);
  --a;
  --b;
  for (int i = 0; i < n; ++i) {
    w[i] = 1;
    g[i].clear();
  }
  for (int i = 0; i < n - 1; ++i) {
    int x, y;
    scanf("%d%d", &x, &y);
    --x;
    --y;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  memset(pa, -1, sizeof pa);
  q[0] = b;
  for (int qh = 0, qt = 1; qh < qt; ++qh) {
    int x = q[qh];
    for (int y : g[x]) {
      if (y != pa[x]) {
        pa[y] = x;
        q[qt++] = y;
      }
    }
  }
  vector<int> path;
  for (int i = a; i != -1; i = pa[i]) {
    path.push_back(i);
  }
  int sz = (int)path.size();
  memset(d, -1, sizeof d);
  for (int i = 0; i < sz; ++i) {
    d[path[i]] = 0;
  }
  for (int i = 0; i < sz; ++i) {
    best[i] = 0;
    q[0] = path[i];
    int qt = 1;
    for (int qh = 0; qh < qt; ++qh) {
      int x = q[qh];
      for (int y : g[x]) {
        if (d[y] == -1) {
          d[y] = d[x] + w[y];
          q[qt++] = y;
          best[i] = max(best[i], d[y]);
        }
      }
    }
  }
  sum[0] = 0;
  for (int i = 0; i < sz; ++i) {
    sum[i + 1] = sum[i] + w[path[i]];
  }
  for (int i = sz - 1; i >= 0; --i) {
    fb[i] = sum[sz] - sum[i] + best[i];
  }
  int aa = (sz - 1) / 2, bb = (sz - 1) / 2 + 1;
  int ans = (sz - 1) - bb;
  if (sz % 2 == 1) {
    ++ans;
    --aa;
  }
  while (aa >= 0) {
    ans = max(ans, fb[aa] - 2);
    --aa;
  }
  printf("%d\n", ans);
}

