// 最小共通先祖 (Lowest Common Ancestor, LCA) を求める
// Verified: AOJ GRL_5_C (Lowest Common Ancestor)

// 移動元と行先と辺のコストを記録する構造体
template <typename T = int>
struct Edge {
    int from, to;
    T cost;
    Edge(int s, T d = 1) : to(s), cost(d) {}
    Edge(int f, int s, T d) : from(f), to(s), cost(d) {}

    bool operator<(const Edge &e) const {
        return cost < e.cost;
    }
    bool operator>(const Edge &e) const {
        return cost > e.cost;
    }
};

template <typename T = int>
using Graph = vector< vector< Edge<T> > >;


template <typename T>
struct TreeLCA {
public:
    int const MAX_LOG_V;
    vector< vector< Edge<T> > > G;
    int root, vn;
    vector< vector<int> > parent;
    vector<int> depth;

    // constructor (Graph, root)
    TreeLCA(vector< vector< Edge<T> > > &_G, int _r) : 
        MAX_LOG_V(20), G(_G), root(_r), vn(G.size()), 
        parent(MAX_LOG_V, vector<int>(vn, 0)), depth(vn, -1)
        { depth[root] = 0; init(vn); }

    void dfs(int v, int p, int d) {
        parent[0][v] = p;
        depth[v] = d;
        for(int i=0; i<G[v].size(); i++) {
            if(depth[ G[v][i].to ] >= 0) continue;
            if(G[v][i].to != p) dfs(G[v][i].to, v, d+1);
        }
    }

    void init(int V) {
        dfs(root, -1, 0);
        for(int k=0; k+1 < MAX_LOG_V; k++) {
            for(int v=0; v < V; v++) {
                if(parent[k][v] < 0) parent[k+1][v] = -1;
                else parent[k+1][v] = parent[k][parent[k][v]];
            }
        }
    }

    // u と v の最小共通祖先
    int lca(int u, int v) {
        if(depth[u] > depth[v]) swap(u, v);
        for(int k=0; k < MAX_LOG_V; k++) {
            if((depth[v] - depth[u]) >> k & 1) {
                v = parent[k][v];
            }
        }
        if(u == v) return u;
        for(int k=MAX_LOG_V - 1; k>=0; k--) {
            if(parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }

    // u と v のパスの長さ (LCA を使って計算)
    int dist(int u, int v) {
        int anc = lca(u, v);
        return depth[u] + depth[v] - 2 * depth[anc];
    }
};

int main() {
    int N, S, T; cin >> N >> S >> T; S--; T--;
    vector< vector<int> > G(N);
    Graph<> GR(N);
    for(int i=0; i<N-1; i++) {
        int u, v; cin >> u >> v;
        u--; v--;
        G[u].emplace_back(v);
        G[v].emplace_back(u);
        GR[u].emplace_back(v);
        GR[v].emplace_back(u);
    }

    // v を根とする根付き木を考える
    // 終了する場所は葉またはその一個上
    // それぞれの葉について到達可能であるかを判定した後偶奇？？
    vector<bool> leaf(N);
    auto dfs = [&](auto&& f, int cur, int par) -> void {
        leaf[cur] = true;
        for(auto to : G[cur]) {
            if(to == par) continue;
            leaf[cur] = false;
            f(f, to, cur);
        }
    };
    dfs(dfs, T, -1);

    auto dfs2 = [&](auto &&f, int cur, int par, vector<int> &dist) -> void {
        for(auto to : G[cur]) {
            if(to == par) continue;
            dist[to] = dist[cur] + 1;
            f(f, to, cur, dist);
        }
    };

    vector<int> da(N, INF), db(N, INF);
    da[S] = 0, db[T] = 0;
    dfs2(dfs2, S, -1, da);
    dfs2(dfs2, T, -1, db);

    TreeLCA<int> lc(GR, T);
    auto can_reach = [&](int k) {
        // S と目的地の lca
        int lca = lc.lca(S, k);
        // この場所に来るのが同時か T のほうがはやいならダメ
        return (da[lca] < db[lca]);
    };

    int ans = 0;
    for(int i=0; i<N; i++) {
        if(!leaf[i]) continue;
        if(can_reach(i)) {
            ans = max(ans, db[i] - 1);
        }
    }
    cout << ans << endl;
    return 0;
}

