    vector<ll> ds=dij.shortest_path(s);
    vector<ll> dt=dij.shortest_path(t);
    ll ans = 0;
    if(cnt[s]==1){
        if(ds[t]%2==0) ans = max(ans,dt[s]);
        else ans = max(ans,dt[s]-1);
        return 0;
    }
    for(int i=0;i<n;i++){
        if(cnt[i]==1){
            if(ds[i] <= dt[i]){
                if(ds[t]%2==0) ans = max(ans,dt[i]);
                else ans = max(ans,dt[i]-1);
            }
        }
    }
