void dfsu(int u, int s = 0) {
    if (in[u]) return;
    in[u] = 1;

    dis[u] = s;

    for (auto& v : g[u]) dfsu(v, s + 1);
}

void dfsv(int u, int s = 0) {
    if (in[u]) return;
    in[u] = 1;
    // cout << u << ' ' << s << ' ' << dis[u] << '\n';

    bool isleaf = true;
    for (auto& v : g[u])
        if (!in[v]) {
            isleaf = false;
        }

    if (isleaf) {
        res = max(res, s - ((dis[u] ^ s) & 1));
        return;
    } else {
        if (dis[u] == s) {
            res = max(res, s);
            return;
        }
    }

    for (auto& v : g[u]) dfsv(v, s + 1);
}

