        --s,--t;
        e[s].push_back(t);
        e[t].push_back(s);
    }
    int du[n],dv[n];
    fill(du,du+n,INF);
    fill(dv,dv+n,INF);
    queue<int> q;
    du[u]=0;
    q.push(u);
    while(q.size()){
        int s=q.front();
        q.pop();
        for(int t:e[s]){
            if(du[t]==INF){
                du[t]=du[s]+1;
                q.push(t);
            }
        }
    }
    dv[v]=0;
    q.push(v);
    while(q.size()){
        int s=q.front();
        q.pop();
        for(int t:e[s]){
            if(dv[t]==INF){
                dv[t]=dv[s]+1;
                q.push(t);
            }
        }
    }
    int ans=-1;
    for(int i=0;i<n;i++){
        if(du[i]<dv[i]){
            ans=max(ans,dv[i]-1);
        }
    }
    cout<<ans<<endl;
}

