struct Node {
    vector<Int> adjacents;
    Int lenFromA = -1;
    Int lenFromB = -1;
    bool flag;
};
int main() {
    Int n, u, v;
    cin >> n >> u >> v;
    u--;
    v--;
    auto nodes = vector<Node>(n);
    rep(i, n - 1) {
        Int a, b;
        cin >> a >> b;
        a--;
        b--;
        nodes[a].adjacents.PB(b);
        nodes[b].adjacents.PB(a);
    }
    function<void(Int, Int, Int)> dfsA = [&](Int index, Int parent, Int distance) {
        auto &node = nodes[index];
        node.lenFromA = distance;
        for (auto &nextIndex : node.adjacents) {
            if (nextIndex == parent) continue;
            dfsA(nextIndex, index, distance + 1);
        }
    };
    function<void(Int, Int, Int)> dfsB = [&](Int index, Int parent, Int distance) {
        auto &node = nodes[index];
        node.lenFromB = distance;
        node.flag = (node.lenFromA < node.lenFromB);
        for (auto &nextIndex : node.adjacents) {
            if (nextIndex == parent) continue;
            dfsB(nextIndex, index, distance + 1);
        }
    };
    dfsA(u, -1, 0);
    dfsB(v, -1, 0);
    Int result = 0;
    for (auto &node : nodes) {
        if (node.flag) {
            result = max(result, node.lenFromB);
        }
    }
    Puts(result - 1);
}

