vector<int> d;
vector<vector<int>> g;
void bfs(int s) {
    int n=sz(g);
    d.resize(n);
    rep(i,n) d[i]=INF;
    queue<int> q;
    q.push(s);
    d[s]=0;
    while(sz(q)) {
        int now=q.front(); q.pop();
        for(int nxt:g[now]) {
            if(d[nxt]==INF) {
                q.push(nxt);
                d[nxt]=d[now]+1;
            }
        }
    }
}

int ans=0;
void dfs(int now,int pre,int cnt) {
    if(sz(g[now])==1 && cnt!=0) {
        chmax(ans,d[now]-1);
        return;
    }
    for(int nxt:g[now])  {
        if(nxt==pre) {
            continue;
        }
        if(cnt==d[nxt]){
            chmax(ans,cnt);
            continue;
        }
        if(cnt+1==d[nxt]) {
            chmax(ans,cnt+1);
            continue;
        }
        dfs(nxt,now,cnt+1);
    }
}

