void DFS(vector<vector<int>>& G, int node, int depth, vector<int>& res) {
	res[node] = depth;
	for (auto& dst : G[node]) {
		if(res[dst] == -1) DFS(G, dst, depth+1, res);
	}
}

int solve(vector<vector<int>>& G, int node, int depth, vector<int>& Tak, vector<int>& Ao, vector<bool>& memo) {
	memo[node] = true;
	int res = -1;
	for (auto& dst : G[node]) {
		if(not memo[dst] and Tak[node] < Ao[node])
			res = max(solve(G, dst, depth+1, Tak, Ao, memo), res);
	}
	int a = Ao[node];
	--a;
	//cerr << "node:" << node << " out:" << a << endl;
	res = max(res, a);
	return res;
}

void solve() {
	int N, u, v; cin >> N >> u >> v;
	--u, --v;

	vector<vector<int> > G(N);
	REP(i, N - 1) {
		int a, b; cin >> a >> b;
		--a, --b;
		G[a].emplace_back(b);
		G[b].emplace_back(a);
	}

	vector<int> TakLength(N, -1);
	DFS(G, u, 0, TakLength);

	vector<int> AoLength(N, -1);
	DFS(G, v, 0, AoLength);

	vector<bool> memo(N);
	int res = solve(G, u, 0, TakLength, AoLength, memo);
	cout << res << endl;
}

