void make_tree(vector<vector<int>> &edges, int now, int p, vector<vector<int>> &children, vector<int> &parent, vector<int> &depth){
    parent[now] = p;
    if(p != -1)
        depth[now] = depth[p] + 1;
    for(auto t: edges[now]){
        if(t == parent[now])
            continue;
        make_tree(edges, t, now, children, parent, depth);
        children[now].push_back(t);
    }
}

int get_longest(int now, vector<vector<int>> &children, vector<int> &parent, vector<int> &longest){
    if(children[now].size() == 0){
        longest[now] = 0;
        return 0;
    }
    if(longest[now] > 0)
        return longest[now];

    for(auto child: children[now]){
        get_longest(child, children, parent, longest);
        longest[now] = max(longest[now], longest[child]);
    }
    longest[now] += 1;
    return longest[now];

}
