        edges[b].push_back(a);
    }
    if(u == v){
        cout << 0 << endl;
        return 0;
    }

    vector<vector<int>> children(n);
    vector<int> parent(n);
    vector<int> depth(n, 0);

    make_tree(edges, v, -1, children, parent, depth);

    vector<int> longest(n, 0);
    get_longest(v, children, parent, longest);
    int cango = (depth[u]-1) / 2;

    int dist = depth[u];
    int now = u;

    int ans = 0;
    IFOR(i, 0, cango){
        int dist = depth[u] - 2 * i;
        int tmp = longest[now] + i;
        tmp += dist / 2;
        ans = max(ans, tmp);

        now = parent[now];
    }
    cout << ans << endl;

    return 0;
}

