using vi = std::vector<int>;
using vvi = std::vector<vi>;

vi bfs(const vvi &tree, int N, int root)
{
    vi d(N, -1);
    std::queue<int> next;
    d[root] = 0;
    next.push(root);

    while (!next.empty())
    {
        int cp = next.front(); next.pop();
        for (int node: tree[cp])
        {
            if (d[node] < 0)
            {
                d[node] = d[cp] + 1;
                next.push(node);
            }
        }
    }
    return d;
}

