{
    int max_dist = 0, max_virt = -1;
    for (int i = 0; i < N; i++)
    {
        if (dv[i] > max_dist && dv[i] > du[i])
        {
            max_dist = dv[i];
            max_virt = i;
        }
    }
    return max_virt;
}

