int du[MAX_V];

void dijkstra_u(int s) {
  priority_queue<P, vector<P>, greater<P>> que;
  fill(du, du + V, INF);
  du[s] = 0;
  que.push(P(0, s));

  while (!que.empty()) {
    P p = que.top();
    que.pop();
    int v = p.second;
    if (du[v] < p.first) {
      continue;
    }

    for (int i = 0; i < G[v].size(); i++) {
      edge e = G[v][i];
      if (du[e.to] > du[v] + e.cost) {
        du[e.to] = du[v] + e.cost;
        que.push(P(du[e.to], e.to));
      }
    }
  }
}

int dv[MAX_V];

void dijkstra_v(int s) {
  priority_queue<P, vector<P>, greater<P>> que;
  fill(dv, dv + V, INF);
  dv[s] = 0;
  que.push(P(0, s));

  while (!que.empty()) {
    P p = que.top();
    que.pop();
    int v = p.second;
    if (dv[v] < p.first) {
      continue;
    }

    for (int i = 0; i < G[v].size(); i++) {
      edge e = G[v][i];
      if (dv[e.to] > dv[v] + e.cost) {
        dv[e.to] = dv[v] + e.cost;
        que.push(P(dv[e.to], e.to));
      }
    }
  }
}

