  int result = 0;
  // まず高橋君から近付いて煽る
  int aoristep = (duv - 1) / 2;
  int uu = u, vv = v;
  repi(aoristep) {
    uu = route_to_v[uu];
    vv = route_to_v[vv];
  }
  int duuvv = duv - aoristep * 2; // 1か2
  result += aoristep;
  // この時点で高橋君の手番
  // 高橋君はできるだけ長い距離逃げる
  int pl = longest_path_length(uu, route_to_v[uu]);  // 逃げ道の長さ
  result += pl;        // 追いつめられる
  result += duuvv - 1; // 終わり
  // cout << "aoristep:" << aoristep << endl;
  // cout << "duuvv:" << duuvv << endl;
  // cout << "pl:" << pl << endl;
  cout << result << endl;
}

