void dijkstra(ll n) {
	priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>>que;
	fill(takahashi.begin(), takahashi.end(), INF);
	takahashi[n] = 0;
	que.push(pair<ll, ll>(0ll, n));

	while (!que.empty()) {
		pair<ll, ll>p = que.top();
		que.pop();
		ll mon = p.second;
		if (takahashi[mon] < p.first) continue;
		for (int i = 0; i < G[mon].size(); ++i) {
			edge e = G[mon][i];
			if (takahashi[e.to] > takahashi[mon] + e.cost) {
				takahashi[e.to] = takahashi[mon] + e.cost;
				que.push(pair<ll, ll>(takahashi[e.to], e.to));
			}
		}
	}
}

void dijkstra2(ll n) {
	priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>>que;
	fill(aoki.begin(), aoki.end(), INF);
	aoki[n] = 0;
	que.push(pair<ll, ll>(0ll, n));

	while (!que.empty()) {
		pair<ll, ll>p = que.top();
		que.pop();
		ll mon = p.second;
		if (aoki[mon] < p.first) continue;
		for (int i = 0; i < G[mon].size(); ++i) {
			edge e = G[mon][i];
			if (aoki[e.to] > aoki[mon] + e.cost) {
				aoki[e.to] = aoki[mon] + e.cost;
				que.push(pair<ll, ll>(aoki[e.to], e.to));
			}
		}
	}
}

