struct RootTree {
    struct Node {
        ll parent = -1;
        vector<ll> child;
    };
    vector<Node> nodes;
    RootTree(size_t n) { nodes = vector<Node>(n, Node{-1, {}}); }
    void set_child(ll p, ll c) {
        assert(0 <= p && p < nodes.size());
        assert(0 <= c && c < nodes.size());
        assert(nodes[c].parent == -1);
        nodes[p].child.push_back(c);
        nodes[c].parent = p;
    }
    vector<vector<ll>> doubling_parents_table() {
        // return[k][i] = ノードiから2^k登ったところにあるノード（ルートを超える時は-1）
        vector<vector<ll>> ans;
        int k = 0;
        while (true) {
            ans.push_back(vector<ll>(nodes.size(), -1));
            bool proceed = false;
            for (int i = 0; i < nodes.size(); i++) {
                if (k == 0) {
                    ans[k][i] = nodes[i].parent;
                } else {
                    ll half = ans[k - 1][i];
                    if (half == -1) {
                        ans[k][i] = -1;
                    } else {
                        ans[k][i] = ans[k - 1][half];
                    }
                }
                if (ans[k][i] != -1) {
                    proceed = true;
                }
            }
            if (!proceed) {
                break;
            }
            k++;
        }
        return ans;
    }
    vector<ll> depth_table(ll root) {
        // return[i] = ノードiの深さ
        vector<ll> ans(nodes.size(), -1);
        vector<ll> stack;
        stack.push_back(root);
        ans[root] = 0;
        while (stack.size() > 0) {
            ll node = stack.back();
            stack.pop_back();
            assert(ans[node] != -1);
            for (ll child : nodes[node].child) {
                ans[child] = ans[node] + 1;
                stack.push_back(child);
            }
        }
        return ans;
    }
    ll lca(ll a, ll b, const vector<ll>& depth,
               const vector<vector<ll>>& parent) {
        assert(0 <= a && a < nodes.size());
        assert(0 <= b && b < nodes.size());
        if (depth[a] != depth[b]) {
            if (depth[a] < depth[b]) {
                swap(a, b);
            }
            ll diff = depth[a] - depth[b];
            while (diff != 0) {
                int n = 0;
                while (true) {
                    if (diff < (1 << (n + 1))) {
                        break;
                    }
                    n++;
                }
                assert(diff >= (1 << n));
                a = parent[n][a];
                diff = depth[a] - depth[b];
            }
        }
        while (true) {
            if (a == b) {
                return a;
            }
            if (parent[0][a] == parent[0][b]) {
                return parent[0][a];
            }
            int n = 0;
            while (true) {
                if (parent[n + 1][a] == parent[n + 1][b]) {
                    break;
                }
                n++;
            }
            a = parent[n][a];
            b = parent[n][b];
        }
    }
};

vector<vector<ll>> graph;
vector<bool> visited;
RootTree tree(0);

void create_tree(ll now) {
    visited[now] = true;
    for (ll to : graph[now]) {
        if (!visited[to]) {
            tree.set_child(now, to);
            create_tree(to);
        }
    }
}

