    tree = RootTree(N);
    visited.resize(N);
    create_tree(ao);
    vector<ll> depth = tree.depth_table(ao);
    vector<vector<ll>> parent_table = tree.doubling_parents_table();
    rep(node_idx, 0, N) {
        RootTree::Node node = tree.nodes[node_idx];
        if (node.child.size() > 0) {
            continue;
        }
        ll lca = tree.lca(tak, node_idx, depth, parent_table);
        ll dist_tak = depth[tak] - depth[lca];
        ll dist_ao = depth[lca];
        if (!(dist_tak < dist_ao)) {
            continue;
        }
        ll dep = depth[node_idx];
        ans = max(ans, dep - 1);
    }
    cout << ans << endl;
}

