template< typename G >
struct DoublingLowestCommonAncestor{
  const int LOG;
  vector<int> dep;
  const G &g;
  vector<vector<int> > table;

  DoublingLowestCommonAncestor(const G &g) : g(g), dep(g.size()), LOG(32 - __builtin_clz(g.size())) {
    table.assign(LOG, vector<int>(g.size(),-1));
  }

  void dfs(int idx, int par, int d){
    table[0][idx] = par;
    dep[idx] = d;
    for(auto & to : g[idx]){
      if(to != par) dfs(to, idx, d+1);
    }
  }

  void build(){
    dfs(0,-1,0);
    rep(k,LOG-1){
      rep(i,table[k].size()){
        if(table[k][i] == -1) table[k+1][i] = -1;
        else table[k+1][i] = table[k][table[k][i]];
      }
    }
  }

  int query(int u, int v){
    if(dep[u] > dep[v])swap(u,v);
    per(i,LOG) if(((dep[v] - dep[u]) >> i) & 1) v = table[i][v];
    if(u==v) return u;
    per(i,LOG){
      if(table[i][u] != table[i][v]){
        u = table[i][u];
        v = table[i][v];
      }
    }
    return table[0][u];
  }

  int dist(int u, int v){
    return dep[u] + dep[v] - 2*dep[query(u,v)];
  }
};

map<int,int> mp;
vector<vector<int> > makeTree(int V, int s,const vector<vector<int> > &G){
  vector<vector<int> > Tree(V);
  queue<PII> que;
  que.push(PII(s,0));
  mp[s] = 0;
  while(!que.empty()){
    PII p = que.front();que.pop();
    int cur = p.first;
    int Tv = p.second;
    for(const int & u : G[cur]){
      if(mp.count(u))continue;
      int Tu;
      Tu = mp[u] = mp.size();
      que.push(PII(u,Tu));
      Tree[Tv].push_back(Tu);
    }
  }
  return Tree;
}

