/// tree con LCA procesamiento O(N log N) consultas O(log N)
struct tree {
    int N, timer, l,root;
    vector<vii> G;
//   vii children[NMAX];
    vvi up;
    vi tin,tout,level;
    tree(int n,int _root) : N(n),root(_root) {
        tin.resize(n),tout.resize(n),level.resize(n);
        up.resize(n),G.resize(n);
    };

    void add_edge(int a, int b, int w = 0) {
        G[a].push_back(MP(b, w));
        G[b].push_back(MP(a, w));
    }

    void build() {
        l = log2(N)+1;
        //   while((1 << l) <= N)  ++l;
        for(int i = 0; i < N; ++i) up[i].resize(l + 1);
        dfs(root,root);
    }

    void dfs(int node, int p,int lev=0) {
        tin[node] = ++timer;
        level[node]=lev++;
        up[node][0] = p;
        for(int i = 1; i <= l; ++i)
            up[node][i] = up[up[node][i - 1]][i - 1];
        for(auto c : G[node])
            if(c.first != p) dfs(c.first, node,lev);
        tout[node] = ++timer;
    }

    bool upper(int a, int b) {return tin[a] <= tin[b] && tout[a] >= tout[b];}

    int lca(int a, int b) {
        if(upper(a, b)) return a;
        if(upper(b, a)) return b;
        for(int i = l; i >= 0; --i)
            if(!upper(up[a][i], b))
                a = up[a][i];
        return up[a][0];
    }

    int dist(int u,int v){
        return abs(level[u]-level[v]);
    }
};


int main() {
    READ(1);
    int n,u,v;cin>>n>>u>>v;
    --u,--v;
    tree t(n,v);
    FOR(i,n-1){
        int x,y;cin>>x>>y;
        t.add_edge(x-1,y-1);
    }
    t.build();
    vi stock;
    for(int i=0;i<n;++i) if (t.tin[i]+1==t.tout[i]) stock.push_back(i);
    sort(stock.begin(),stock.end(),[&t](int x,int y){return t.level[x]>t.level[y];});
    for(int node:stock){
        int l=t.lca(node,u);
        int d1=t.dist(u,l);
        if (d1<t.level[l]) {
            cout << t.level[node]-1;
            return 0;
        }
    }
}

