int dfs2(int now, int back = -1, int t = 0) {
  if (Aoki[now] <= t) {
    return Aoki[now];
  }

  bool isleaf = true;
  int res = 0;

  for (int to : G[now]) {
    if (to == back) continue;
    res = max(res, dfs2(to, now, t + 1));
    isleaf = false;
  }

  if (isleaf)
    res = max(res, min(Aoki[now], t));

  return res;
}

