int DFS(int i, int p, std::vector<std::set<int>>const& edge, std::vector<int>const& depth, std::vector<boost::optional<int>>& next)
{
	int max = -1;
	for (auto n : edge[i])
	{
		if (n == p)
		{
			continue;
		}
		auto r = DFS(n, i, edge, depth, next);
		if (max < r)
		{
			next[i] = n;
			max = r;
		}
	}
	return max == -1 ? depth[i] : max;
}

