void dfs(int x)
{
    for(int i = 1; i<17; i++)
        par[x][i] = par[par[x][i-1]][i-1];
    for(int i = 0; i<g[x].size(); i++)
    {
        if(g[x][i]!=par[x][0])
        {
            par[g[x][i]][0] = x;
