            dfs(g[x][i]);
        }
    }
}

int lca(int x, int y)
{
    int i = 16, j = 16;
    if(depth[y]>depth[x])
        swap(x,y);
    while(depth[x]>depth[y])
    {
        if(depth[x]-depth[y]>=(1<<i))
            x = par[x][i];
        i--;
    }
    while(x!=y)
    {
        if(j==-1)
            break;
        if(par[x][j]!=par[y][j])
            x = par[x][j], y = par[y][j];
        j--;
    }
    if(x==y)
        return x;
    return par[x][0];
}

void farthest(int a, int dist)
{
    maxDist = max(maxDist, dist);
    for(int i=0; i<g[a].size(); i++)
    {
        if(depth[g[a][i]] <= depth[a])
        {
            continue;
        }
        farthest(g[a][i], dist+1);
    }
}

