void Graph_func::read_edge() {
	cin >> Vnum >> uini >> vini;
	if (graph_tree)
		Enum = Vnum - 1;// graph
	else
		cin >> Enum;
	uini--;
	vini--;
	edgelist.resize(Enum);
	edgeweight.resize(Enum);
	adjnum.resize(Vnum);
	xdist.resize(Vnum);
	adjlist.resize(Vnum);
	xprevlist.resize(Vnum);
	if (graph_weight)
		adjlistweight.resize(Vnum);
	rep(i, Enum) {
