void
solve() {
  int n, u, v;
  cin>>n>>u>>v;

  int a, b;
  vector<vector<int>> link(n+1);
  for (int i=0; i<n-1; i++) {
    cin>>a>>b;
    link[a].push_back(b);
    link[b].push_back(a);
  }

  map<int, int> parent;
  map<int, int> level;
  stack<int> now;
  now.push(v);
  parent[v] = -1;
  level[v] = 0;
  while (now.size() > 0) {
    int p = now.top();
    now.pop();

    for (auto next : link[p]) {
      if (parent[next] != 0) continue;

      parent[next] = p;
      level[next] = level[p] + 1;
      now.push(next);
    }
  }

  vector<int> path;
  int node = u;
  while (node != v) {
    path.push_back(node);
    node = parent[node];
  }
  path.push_back(v);

  int runner = 0, catcher = path.size()-1; 
  int ans = 0;
  while (catcher - runner > 2) {
    runner++;
    catcher--;
    ans++;
  }

  u = path[runner];
  v = path[catcher];

  stack<int> far;
  far.push(u);
  int tail = u;
  while (far.size() > 0) {
    auto p = far.top();
    far.pop();

    for (auto next : link[p]) {
      if (level[next] <= level[p]) continue;

      far.push(next);
      if (level[next] > level[tail])
        tail = next;
    }
  }

  path.clear();
  node = tail;
  while (node != v) {
    path.push_back(node);
    node = parent[node];
  }
  path.push_back(v);
  reverse(path.begin(), path.end());

  catcher = 0;
  runner = 0;
  for (int i=0; i<path.size(); i++)
    if (path[i] == u) {
      runner = i;
      break;
    }

  while (1) {
    if (runner + 1 < path.size()) {
      runner++;
      catcher++;
      ans++;
    }
    else {
      if (path[runner-1] == path[catcher]) {
        break;
      }
      else {
        ans++;
        break;
      }
    }
  }

  cout<<ans<<endl;
}

