                if(v == prev) continue;
                dfs(dfs, v, cur, c+1);
            }
        };

        dfs(dfs, u, -1, 0);
    }

    long r = 0;
    {
        auto dfs = [&](auto dfs, long cur, long prev, long c) -> void {
            for(auto &v: G[cur]) {
                if(v == prev) continue;
                if(udis[v] < c) continue;

                if(G[v].size() == 2)
                    r = max(r, long(udis[v]));

                dfs(dfs, v, cur, c+1);
            }
        };
        dfs(dfs, v, -1, 0);
    }
    cout << r << endl;
}

