int n, x, y;
vector<int> g[SZ];

void read() {
    cin >> n >> x >> y;
    --x, --y;
    for (int i = 1; i < n; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
}

int tim1[SZ];
bool used1[SZ];
void dfs1(int u, int t = 0) {
    used1[u] = true;
    tim1[u] = t;
    for (int v : g[u]) {
        if (!used1[v]) {
            dfs1(v, t + 1);
        }
    }
}

bool used[SZ];
int ans = 0;
int tim[SZ];
void dfs2(int u, int t = 0) {
    used[u] = true;
    tim[u] = t;
    for (int v : g[u]) {
        if (!used[v] && t + 1 < tim1[v]) {
            dfs2(v);
        }
    }
}

void solve() {
    if (g[x].size() == 1 && g[x][0] == y) {
        cout << 0;
        return;
    }
    dfs1(y);
    fill(tim, tim + n, -1);
    dfs2(x);
    int ans = 1;
    for (int u = 0; u < n; ++u) {
        if (g[u].size() == 1 && used[u]) {
            ans = max(ans, tim1[u] - tim[u] - 1);
        }
    }
    cout << ans;
}

signed main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    read();
    solve();

    return 0;
}

