  dist[v] = d;
  for (auto nv : g[v]) {
    if (!seen[nv]) dfs(nv,d+1);
  }
}

int ans = 0; // 最長手番を更新
void escape(int v, int d) { // 高橋さんの逃走。頂点vをd手目に訪問
  // pp(v);pp(d);
  ans = max(ans, d);
  // pp(ans);
  for (auto nv : g[v]) {
    // pp(nv);
    // pp(dist[nv]);
    if (dist[nv] > d+1) {
      escape(nv, d+1);
    } else if (dist[nv] == d+1) {
      ans = max(ans, d+1); // 移動できるが直後につかまる
    }
  }
}

