int n, d[nax];
vector<int> a[nax];
int x, y, tin[nax], tout[nax], timer, up[nax][19]; /// Takahashi and Aoki respectively
void dfs(int nod, int par){
    tin[nod] = ++ timer;
    up[nod][0] = par;
    for(int i = 1 ;i <= 18 ; i ++)
        up[nod][i] = up[up[nod][i - 1]][i - 1];
    for(int i : a[nod]){
        if(i == par) continue;
        d[i] = d[nod] + 1;
        dfs(i, nod);
    }
    tout[nod] = ++ timer;
}
bool ancestor(int u, int v){
    return tin[u] <= tin[v] && tout[u] >= tout[v];
}
int lca(int u, int v){
    if(ancestor(u, v)) return u;
    if(ancestor(v, u)) return  v;
    for(int i = 18 ;i  >= 0 ; i --){
        if(!ancestor(up[u][i], v)){
            u = up[u][i];
        }
    }
    return up[u][0];
}
vector<int> lf;
int dist(int u, int v){
    return d[u] + d[v] - 2 * d[lca(u, v)];
}

int main(){
    tout[0] = 1e9;
    scanf("%d %d %d", &n, &x, &y);
    for(int i =1 ; i< n; i++){
        int u, v;
        scanf("%d %d", &u, &v);
        a[u].push_back(v);
        a[v].push_back(u);
    }
    dfs(y, 0);
    for(int i = 1 ;i <= n ;i ++){
        if(i != y && (int)a[i].size() == 1)
            lf.push_back(i);
    }
    int ans = 0;
    for(int c : lf){
        int lc = lca(x, c);
        int disT = dist(x, lc);
        int disA = dist(y, lc);
        eprintf("%d Ta = %d AO = %d\n", lc, disT, disA);
        if(disA <= disT) {
            ans = max(ans, disA);
            continue;
        }
        int A = dist(c, y);
        ans = max(ans, A - 1);
    }
    eprintf("\n");
    return !printf("%d\n", ans);
}
