void solve(long long N, long long u, long long v, std::vector<long long> A,
           std::vector<long long> B) {
  rep(i, N){
    A[i]--, B[i]--;
    e[A[i]].push_back(B[i]);
    e[B[i]].push_back(A[i]);
    dist[i] = -1e6;
  }
  u--,v--;
  g = u;
  dist[v] = 0;
  //dfs2(v, -1);
