  // rep(i, N) cerr << dist[i] << " ";
//  cerr << endl;
  int turn = 0;
  int aok = 0;
  int di = dist[u];
  while(di != aok){
    if(turn){
      aok++;
    }
    else {
      vector<pair<int,int>> cand;
      for(auto s:e[u]){
        if(dist[s] > aok + 1){
          if(dept[s]>dept[u]){
            cand.push_back(make_pair(dist2[s] + 1e6, -dist[s]));
          }else {
