        }
      }
      int nxt = max_element(cand.begin(), cand.end()) - cand.begin();
      u = e[u][nxt];
      di = dist[u];
    }

//    cerr << u << " " << di << " " << aok << " " << turn <<  endl;
    turn ^= 1;
  }
  cout << aok << endl;
}

