void DFS(vector<vector<Edge> > &G, vector<ll> &color, int now){
    queue<ll> que;
    que.push(now);
    while (que.size()){
        int pos = que.front();
        que.pop();
        for (int i = 0; i < G[pos].size(); i++){
            Edge es = G[pos][i];
