        return to == a.to && cost == a.cost;
    }
};

template<typename T>
struct node{
    T value;
    vector<arc> arcs;
    node(T v) : value(v){}

    node& operator= (T const& a){
        value = a;
        return *this;
    }
    operator T() const {
        return value;
    }

};

template<typename T>
class graph{
protected:
    vector<node<T>> nodes;
    int n;
public:

    graph(int N, T value) : nodes(N, value), n(N){};

    void addArc(int from, int to, int cost){
        assert(0 <= from && from <= n - 1 && 0 <= to && to <= n - 1);
        nodes[from].arcs.push_back({to,cost});
    }
    void addEdge(int a, int b, int cost){
        addArc(a, b, cost);
        addArc(b, a, cost);
    }
    node<T>& operator[](int index) {
        return nodes[index];
    }

    auto begin() { return nodes.begin(); }
    auto end()   { return nodes.end();   }

    auto const& getInstance(){
        return nodes;
    }

};

class bellmanford : public graph<int>{
    int N;
    int changed;

    void r(unordered_set<int> froms, int termination){
        bool c = false;
        unordered_set<int> f;
        for (auto& from : froms){
            for (auto& i : nodes[from].arcs) {
                if (nodes[i.to].value > i.cost + nodes[from].value) {
                    nodes[i.to].value = i.cost + nodes[from].value;
                    f.insert(i.to);
                    c = true;
                }
            }
        }
        // Terminated
        if (!c) return;

        // Negative loop?
        if(!termination){
            changed = c;
            return;
        }
        // continue
        r(move(f), termination-1);
    }

public:

    bellmanford(int N): graph::graph(N, std::numeric_limits<int>::max()),
                        N(N), changed(false){}

    bool run(int start){
        nodes[start].value = 0;
        r({start}, N - 1);
        return changed;
    }

    int const& operator[] (int index){
        return nodes[index].value;
    }

};

ll h(graph<int> &g, int parent, int bad, int counter=0){
    if (g.getInstance().at(parent).arcs.size() == 1) {
            return counter;
    }

    ll result = 0;

    for(auto &x : g.getInstance().at(parent).arcs){
        if (x.to == bad) continue;
        result = max(result, h(g, x.to, parent, counter+1));
    }
    return result;
}

int f(graph<int> &g, int parent, int child){
    if (parent == child) {
        return h(g, child, parent);
    }

    for(auto x : g.getInstance().at(parent).arcs){
        auto r = f(g, x.to, child);
        if (r >= 0)
            return r;
    }
    return -1;
}

