    int result = 0;

    if (find(g.getInstance()[v - 1].arcs.cbegin(),
             g.getInstance()[v - 1].arcs.cend(), arc{u - 1, 1})
        != g.getInstance()[v - 1].arcs.cend()) {
        cout << 0;
