void bfs(const vvi& G, vi& d, int root) {
    int n = G.size();

    queue<int> q;
    vb seen(n, false);

    q.push(root);
    seen[root] = true;
    d[root] = 0;

    while (!q.empty()) {
        int curr = q.front();
        q.pop();

        for (int next : G[curr]) {
            if (seen[next]) { continue; }

            q.push(next);
            seen[next] = true;
            d[next] = d[curr] + 1;
        }
    }
}

