        // uとvの間にあり，直線上にない場合．
        int d = abs(from_u[i] - from_v[i]);
        if (d < dist) {
            if (from_u[i] < from_v[i]) {
                int tmp = from_u[i] + d - 1;
                ans = max(ans, tmp);
            }
