        u--, v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vt<int> ds(n, -1), dt(n, -1);
    auto bfs = [&](vt<int>& dist, int x) {
        dist[x] = 0;
        queue<int> q;
        q.push(x);
        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (int v : adj[u]) {
