int dfs(unordered_map<int, vector<int>>& graph, int start, int goal, int pre, int d, vector<int>& path, vector<int>& ans_path) {
    if (start == goal) {
        ans_path = path;
        return d;
    }
    int ans = INF;
    for (auto &adj : graph[start]) {
        if (adj == pre) continue;
        path.push_back(adj);
        ans = min(ans, dfs(graph, adj, goal, start, d + 1, path, ans_path));
        path.pop_back();

    }
    return ans;
}
int dfs2(unordered_map<int, vector<int>>& graph, int start, int pre, int d) {

    int ans = d;
    for (auto &adj : graph[start]) {
        if (adj == pre) continue;
        ans = max(ans, dfs2(graph, adj, start, d + 1));

    }
    return ans;
}
