    int new_start = u;
    if ((d - 1) / 2 > 0)
        new_start = ans_path[(d - 1) / 2 - 1];
    int dont_move = ans_path[(d - 1) / 2];
    ans += dfs2(graph, new_start, dont_move, 0);
    cout << ans << endl;
    return 0;
}

