int bfs(int n, int a, int b){
    memset(dis, 0, sizeof(dis));
    memset(vis, 0, sizeof(vis));
    queue<int> qa;
    queue<int> qb;

    qa.push(a);
    qb.push(b);
    dis[a] = 0;

    int ans = 0;
    while (!qa.empty() && !qb.empty()) {

        int t = qa.size();
        int cur;
        for (int i=0; i < t; i++) {
            cur = qa.front();
            qa.pop();
            if (vis[cur]==0) {
                for (int j=0; j<v[cur].size(); j++) {
                    int tmp = v[cur][j];
                    if (vis[tmp]==0 && tmp!=b) {
                        dis[tmp] = dis[cur] + 1;
                        qa.push(tmp);
                    }
                }
            }
        }

        t = qb.size();
        for (int i=0; i < t; i++) {
            cur = qb.front();
            qb.pop();
            for (int j=0; j<v[cur].size(); j++) {
                int tmp = v[cur][j];
                if (vis[tmp]==0) {
                    qb.push(tmp);
                    ans = max(ans, dis[tmp]);
                    vis[tmp] = 1;
                }
            }
        }
    }
    return ans;
}

