        cin >> a >> b;
        a--, b--;
        g[a].push_back(b);
        g[b].push_back(a);
        cnt[a]++, cnt[b]++;
    }
    queue<int> q;
    akari<int> ds(n, -1), ds2(n, -1);
    ds[u] = 0;
    q.push(u);
    while (!q.empty())
    {
        int curv = q.front();
        q.pop();
        for (int nv : g[curv])
        {
            if (ds[nv] != -1)
            {
                continue;
            }
            ds[nv] = ds[curv] + 1;
            q.push(nv);
