vvi adj;  // adjacency list representation
int n; // number of nodes
vector<int> d, p; //d[u] - shortest dist from s to u, p[u] - parent of u
vector<bool> used;

void bfs(int s) { // s - source vertex
	queue<int> q;
	q.push(s); used[s] = true;
	p[s] = -1; //no parent for s
	while (!q.empty()) {
	    int v = q.front(); q.pop();
	    for(int u : adj[v]) {
	        if (!used[u]) {
	            q.push(u); used[u] = true;
	            d[u] = d[v] + 1; // update distance for u
	            p[u] = v;  // update parent for u
        	}
    	}
	}
}
//*********RESTORE SHORTEST PATH FROM BFS:
vector<int> path;
void restorePath(int u) { // u - destination (from source s as above)
	if (!used[u]) cout << "No path!";
	else
    	for (int v = u; v != -1; v = p[v]) path.push_back(v);
    		reverse(path.begin(), path.end());
}

// DP on tree:
// calculate for each node s a value count[s]: the number of nodes in its subtree:
//calculate for every node x the maximum length of a path that goes through
// a child of x: use DP on tree.
vi maxDist;

void dfs(int s, int e) {//dfs from s, e is parent of s. Find max distance from s to a child
	maxDist[s] = 0;
	int mx = -1;

//	cout << "DFS from s=" << s << ", e = " << e << endl;

	for (auto u : adj[s]) {
		if (u == e) continue;
		dfs(u, s);

//		debug(mx, maxDist[u]);

		mx = max(mx, maxDist[u]);

//		debug(mx);

	}
	maxDist[s] = 1 + mx;

//	debug(maxDist);

}

void solve() {
	int u, v; cin >> n >> u >> v; u--, v--;
	if(u==v) {cout << 0 << endl; return;}
	adj.resize(n);
	FOR(i, 0, n-1) {
		int a, b; cin >> a >> b; a--, b--;
		adj[a].PB(b); adj[b].PB(a);
	}
	d.resize(n), p.resize(n); //d[u] - shortest dist from s to u, p[u] - parent of u
	used.assign(n, false);
	bfs(v); // bfs from v, so v is root
	restorePath(u); // get vi path as shortest path from v to u

//	debug(path);

	int m = SZ(path); // so dinh trong path tu v den u
	int ans = 0;
	maxDist.assign(n, 0);
	if(even(m)) { // neu so dinh la chan, tuc la so doan la le
		int k = (m-2)/2; ans += k; // v tien den phia u m/2-1 buoc la toi da
		int e = path[k];
		int s = path[k+1];

//		debug(k, e, s);

		dfs(s, e);
		ans += maxDist[s];
	}
	else {
		int k = (m-3)/2; ans += k; // v tien den phia u m/2-1 buoc la toi da
		int e = path[k+1];
		int s = path[k+2];

//		debug(k, e, s);

		dfs(s, e);
		ans += maxDist[s];
	}
	cout << ans << endl;
}

