void how_many_decendable(const vector<vector<ll>>&tree,vector<ll>&res,ll from,ll parent=-1)
{
    res[from]=0;
    for(auto c:tree[from]){
        if(c!=parent){
            how_many_decendable(tree,res,c,from);
            res[from]=max(res[from],res[c]+1);
        }
    }
}
void tree_distance(const vector<vector<ll>>&tree,vector<ll>&res,ll from,ll parent=-1,ll dist=0)
{
    res[from]=dist;
    for(auto c:tree[from]){
        if(c!=parent){
            tree_distance(tree,res,c,from,dist+1);
        }
    }
}
void get_parent(const vector<vector<ll>>&tree,vector<ll>&res,ll from,ll parent=-1)
{
    for(auto c:tree[from]){
        if(c!=parent){
            get_parent(tree,res,c,from);
        }
    }
    res[from]=parent;
}
