ll dfs2(ll from, ll at, ll t){
	if(aoki[at] == t){return t;}
	if(aoki[at] == t-1){return t-1;}

	ll res = t;
	bool keep = false;
	rep(i, 0, edge[at].size()){
		ll next = edge[at][i];
		if(aoki[next] > t+1 && aoki[at] >= t+2){
			keep = true;
		}
		if(aoki[next]  > t && next != from){
			ll buf = dfs2(at, next, t+1);
			res = max(buf, res);
		}
	}
	if(keep){
		ll buf = dfs2(-1, at, t+2);
		res = max(buf, res);
	}
	return res;
}


