void dijkstra(int s) {
    priority_queue<pii, vector<pii>, greater<pii> > que;
    rep(i,N) {
        d[i] = 2000000;
    }
    d[s] = 0;
    que.push(pii(0,s));
    while(!que.empty()) {
        pii p = que.top();
        que.pop();
        int v = p.second;
        if(d[v] < p.first) continue;
        rep(i, G[v].size()) {
            edge e = G[v][i];
            if(d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(pii(d[e.to], e.to));
            }
        }
    }
}

void dijkstra2(int s) {
    priority_queue<pii, vector<pii>, greater<pii> > que;
    rep(i,N) {
        d2[i] = 2000000;
    }
    d2[s] = 0;
    que.push(pii(0,s));
    while(!que.empty()) {
        pii p = que.top();
        que.pop();
        int v = p.second;
        if(d2[v] < p.first) continue;
        rep(i, G[v].size()) {
            edge e = G[v][i];
            if(d2[e.to] > d2[v] + e.cost) {
                d2[e.to] = d2[v] + e.cost;
                que.push(pii(d2[e.to], e.to));
            }
        }
    }
}

