//Dijkstra（経路復元なし）
//vector<Weight> 戻り値[t] := sから頂点tへ辿り着くための累計最小重み
// 戻り値[t] == -1 の場合、s から頂点 t へは辿り着けないということ

//Dijkstraのベースになるデータ構造を宣言
// !! 重み（コスト）の型をここで設定する !! ldなど、整数じゃなくてもOK
using Weight = ll; //<---ここ！！

