struct Edge{
  int from, to;
  Weight wei;
  // struct Edge のコンストラクタ
  Edge(int from_, int to_, Weight wei_):from(from_),to(to_),wei(wei_){}
};
// struct Edge のvectorをEdgesとする
typedef vector<Edge> Edges;

// グラフ全体の構造体を定義
// 実態は、各頂点に張られた辺たち（Edges）の集合体（Edgesのvector）
// Graph[v] は vector<頂点vに張られた辺>
struct Graph : public vector<Edges>{
  //struct Graphのコンストラクタ 引数Vを与える
  Graph(){ }
  Graph(int V): vector<Edges>(V){ }
  /*
  有向辺を追加する
  */
  void addEdge(int from, int to, Weight wei=1){
    // Graph[from頂点] （from頂点から張られたEdges）に新しい辺を追加する
    // 辺に重みの差が無い（全て1とみなせる）場合、重みを引数として渡さなくても1とみなして処理
    (*this)[from].push_back(Edge(from, to, wei));
  }
  /*
  無向辺を追加する
  */
  void addUEdge(int u, int v, Weight wei=1){
    (*this)[u].push_back(Edge(u, v, wei));
    (*this)[v].push_back(Edge(v, u, wei));
  }
};

//ここから実際に使う関数

// Edge > Edge の比較は、重みの大小で評価
bool operator>(const Edge &a, const Edge &b){
  return a.wei>b.wei;
}

//戻り値のvector<Weight>にvec.at(頂点のidx)をすれば、各頂点に到達するまでに最低限必要な重みの合計（以降、累計重みと呼ぶ）が得られる
//dijkstra(Graph, スタート地点のidx) で呼び出す
// const は「関数内でGraphを変更しません」という意味で、&は単にコピーの時間を省くためと思われる
vector<Weight> dijkstra(const Graph &G, int src){

  // 型 p_wei_vert : pair<Weight, int> を定義
  // pair<その頂点に辿り着くまでの最小累計重み（最短経路の重み）, 頂点番号>
  typedef pair<Weight, int> p_wei_vert;
  // 最小値を取り出すpriority_q : 「これから訪れたい頂点と、その頂点までの累計重み」を入れる
  // vector <p_wei_vert<累計重み, 行き先頂点> >
  priority_queue<p_wei_vert, vector<p_wei_vert>, greater<p_wei_vert>> pq_to_visit;
  // pair {累計重み0, スタート地点のidx}の追加
  pq_to_visit.push(make_pair(0, src));
  // 頂点数を受け取っただけ
  int V = (int)G.size();

  vector<Weight> res(V, -1);
  // res はDP[]のようなもので、res[v] : vに辿り着く最小累計重み
  // res[v] == -1であれば、未到達
  // res[v] != -1であれば頂点vに到達済みで、到達済みであれば、イコール最短経路確定済となる（理由は後で）
  // ちなみにダイクストラを使う場合、重みは正（非負？）のはずだから、既に到達した頂点のres値が負となることはない

  while(pq_to_visit.size()){
    // pqから、重み最小のp_wei_vert（cost, vert）を取り出してp_wei_vert pに入れる
    // つまり、「今行ける場所の中で、最も累計重みの低い場所に行こうとしてみる」ということ
    auto p = pq_to_visit.top(); pq_to_visit.pop();
    Weight d = p.first;
    int v = p.second;
    if(res[v] > -0.5)continue;
    // res[v]が非負、つまり頂点vに過去に到達済みなら、pq_to_visitに追加せず次のループへ
    // ループを抜けたなら過去に到達していないので、今回のルートが「頂点vへの最短経路」
    // これでres[v] つまりvへの最短経路での重み は確定であり、再度代入することはない
    res[v] = d;

    // Graph[v] すなわちvに張られた全てのEdgeについてループし、vから移動できる頂点を探す
    for(const auto &edge : G[v]){
      int to = edge.to;
      Weight wei = edge.wei;

      if (res[to] > -0.5) continue; 
      // 枝刈り（既に探索済み = 頂点toの累計最小重みが確定しれば、pqに入れない）

      pq_to_visit.push(make_pair(d + wei, to));
      // pqに、今見ている頂点vから移動できる、まだ訪問していない頂点の情報を入れる
      // 入れるのは「頂点vの到達までの累計重み（d = p.first） + wei（pから張られた辺の重み）, 行き先」
      // while 文の最初の方で累計重みが小さい方から取り出して訪問するために使う。その際「まだ訪問していない頂点のうち、スタートから最も小さい重みで行ける頂点」を訪問していくことにより、その訪問の仕方が、その頂点まで最も小さい重みで行ける経路であることが担保される（ダイクストラのアルゴリズム）
    }
  }
  // 最終的に、resは「各頂点に辿り着くための最小重み」となっているので、それを返す
  return res;
}

