// ax + by = gcd(a,b) 最大公約数
template< typename T >
T extgcd(T a, T b, T& x, T& y) {
	T d = a;
	if (b != 0) {
		d = extgcd(b, a % b, y, x);
		y -= (a / b) * x;
	}
	else {
		x = 1;
		y = 0;
	}
	return d;
}

vector<int> graph[100000] = {};

int memo_aoki[100000] = {};
int memo_taka[100000] = {};
bool visited[100000] = {};


int main(void) {

	int N, u, v;
	cin >> N >> u >> v;

	u--; v--;

	for (int i = 0; i < N - 1; i++) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		graph[a].push_back(b);
		graph[b].push_back(a);
	}

	//aoki memo
	{
		queue<pair<int, int>> q;
		q.push({ v,0 });

		while (!q.empty()) {
			pair<int, int> p = q.front();
			q.pop();

			if (!visited[p.first]) {
				visited[p.first] = true;

				memo_aoki[p.first] = p.second;

				for (int i = 0; i < graph[p.first].size(); i++) {
					q.push({ graph[p.first][i],p.second + 1});
				}
			}
		}
	}
	//takahashi memo
	{
		for (int i = 0; i < N; i++) {
			visited[i] = false;
		}
		queue<pair<int, int>> q;
		q.push({ u,0 });

		while (!q.empty()) {
			pair<int, int> p = q.front();
			q.pop();

			if (!visited[p.first]) {
				visited[p.first] = true;

				memo_taka[p.first] = p.second;

				for (int i = 0; i < graph[p.first].size(); i++) {
					q.push({ graph[p.first][i],p.second + 1 });
				}
			}
		}
	}
	//answer
	{
		int answer = 0;

		for (int i = 0; i < N; i++) {
			if (memo_taka[i] <= memo_aoki[i] && graph[i].size() != 1) {
				CHMAX(answer,memo_aoki[i]);
			}
		}

		COUT(answer);
	}



	return 0;
}

