ll deepest(Tree *node)
{

  ll ans = node->val;
  queue<Tree *> que;
  que.push(node);

  while (!que.empty())
  {
    auto q = que.front();
    que.pop();
    if (depths[q->val] > depths[ans])
      ans = q->val;
    for (auto no : q->children)
    {
      que.push(no);
    }
  }

  return ans;
}

