const int maxN = 1 << 20;

int parent[maxN], dist[maxN], mx;
vector <int> G[maxN];

void dfs(int v, int fat)
{
	parent[v] = fat;
	dist[v] = dist[fat] + 1;
	for (int u : G[v]) if (u != fat)
		dfs(u, v);
}

void dfs2(int v, int fat, int d)
{
	mx = max(mx, d);
	for (int u : G[v])
		if (u != fat)
			dfs2(u, v, d+1);
}

int main()
{
	int n, x, y;
	scanf ("%d%d%d", &n, &x, &y);

	FOR(i, 1, n)
	{
		int a, b;
		scanf ("%d%d", &a, &b);
		G[a].pb(b);
		G[b].pb(a);
	}
	dist[0] = -1;
	dfs(y, 0);

	int target = dist[x]/2 + 1, res = dist[x]%2 ^ 1;
	while (dist[x] != target)
		x = parent[x], res++;

	dfs2(x, parent[x], 0);
	res += mx;
	printf("%d", res);

	printf("\n");

	return 0;
}

