void dfs1(int pos) {
	if (pos == v)return;
	aflag[pos] = true;
	for (int i = 0; i < G[pos].size(); i++) {
		if (aflag[G[pos][i].to])continue;
		dfs1(G[pos][i].to);
	}
}
void dfs2(int pos,int depth) {
	dist1[pos] = depth;
	for (int i = 0; i < G[pos].size(); i++) {
		if (dist1[G[pos][i].to] != -1)continue;
		dfs2(G[pos][i].to, depth + 1);
	}
}
void dfs3(int pos, int depth) {
	dist2[pos] = depth;
	for (int i = 0; i < G[pos].size(); i++) {
		if (dist2[G[pos][i].to] != -1)continue;
		dfs2(G[pos][i].to, depth + 1);
	}
}
