bool used[100100];
int h[100100], h2[100100];
int par[100100];

void dfs(int i){
  used[i] = true;
  for(auto e: edge[i]){
    if(used[e])continue;
    h[e] = h[i] + 1;
    par[e] = i;
    child[i].pb(e);
    dfs(e);
  }
}

void dfs2(int i){
  used[i] = true;
  for(auto e: edge[i]){
    if(used[e])continue;
    h2[e] = h2[i] + 1;
    dfs2(e);
  }
}

