#endif // HOME
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int n, x, y, u, v;
    cin >> n >> x >> y;
    for (int i = 1; i < n; ++i) {
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    dfs(1, 0);
    int t = get_lca(x, y);
    if (h[x] - h[t] >= h[y] - h[t]) {
        int ans = 0;
        for (int i = 1; i <= n; ++i) {
            int go = get_lca(i, x);
            if (get_lca(t, go) == go) continue;
            int dd = h[y] + h[go] - 2 * h[get_lca(go, y)];
            int dd1 = h[x] + h[go] - 2 * h[get_lca(go, x)];
            if (dd1 < dd) {
                int dist1 = h[i] + h[x] - 2 * h[get_lca(i, x)];
                int dist2 = h[y] + h[i] - 2 * h[get_lca(i, y)];
                ans = max(ans, dist2 - 1);
            }
        }
        cout << ans << '\n';
    }
    else {
        go(y, dp[y][0]);
        int ans = 0;
        for (int i = 1; i <= n; ++i) {
            if (was[i] == 1) continue;
            int dist1 = h[i] + h[x] - 2 * h[get_lca(i, x)];
            int dist2 = h[y] + h[i] - 2 * h[get_lca(i, y)];
            ans = max(ans, dist2 - 1);
        }
        cout << ans << '\n';
    }
    return 0;
}

