#define FOR(i,a,b) for(int i=(a);i<(b);++i)
#define REP(i,n)  FOR(i,0,n)
#define ALL(a)  (a).begin(),(a).end()

typedef long long lint;

using namespace std;

int main(){
  int N,u,v;
  cin>>N>>u>>v;
  u--;v--;
  int log2N=int(log2(N))+1;
  // cerr<<log2N;
  vector<int> c[N];
  REP(i,N-1){
    int A,B;
    cin>>A>>B;
    A--;B--;
    c[A].push_back(B);
    c[B].push_back(A);
  }
  vector<int> d(N,-1);
  vector<vector<int> > parent(N,vector<int>(log2N,-1));
  queue<int> q;
  q.push(v);
  d[v]=0;
  while(!q.empty()){
    int p=q.front();
    q.pop();
    for(auto e:c[p]){
      if(d[e]==-1){
        d[e]=d[p]+1;
        parent[e][0]=p;
        FOR(i,1,log2N){
          if(parent[e][i-1]<0)parent[e][i]=-1;
          else parent[e][i]=parent[parent[e][i-1]][i-1];
        }
        q.push(e);
      }
    }
  }
  // REP(i,N)cerr<<d[i]<<" "<<endl;
  auto LCA=[=](int a,int b){
    if(d[a]>d[b])swap(a,b);
    int dif=d[b]-d[a];
    REP(i,log2N){
      if(dif==0)break;
      if(dif%2)b=parent[b][i];
      dif/=2;
    }

    if(a==b)return a;
    for(int i=log2N-1;i>=0;i--){
      if(parent[a][i]==parent[b][i])continue;
      a=parent[a][i];
      b=parent[b][i];
    }
    return parent[a][0];
  };
  set<int> s;
  REP(i,N)if(c[i].size()==1)s.insert(i);
  int ans=0;
  for(auto e:s){
    int ca=LCA(e,u);
    // cerr<<e<<" "<<ca<<endl;
    if(u==ca){
      ans=max(ans,d[e]-1);
    }
    else if(d[u]-d[ca]>=d[ca])continue;
    else{
      ans=max(ans,d[e]-1);
    }
  }
  cout<<ans<<endl;
  return 0;
}

