    if (h[x] - h[t] >= h[y] - h[t]) {
        for (auto u : g[t]) {
            if (dp[t][0] == u) continue;
            if (get_lca(u, x) == u) go(u, t);
        }
        int ans = 0;
        for (int i = 1; i <= n; ++i) {
