class RootedTree
{
    std::vector<int> tree;

public:
    RootedTree(int n)
        : tree(n + 1, 0)
    {
        tree[0] = 1;
    }

    void addEdge(int a, int b)
    {
        if (a > b) std::swap(a, b);
        tree[b] = a;
    }

    void turn(int root)
    {
        if (root == tree[0]) return;
        if (root != tree[0]) {
            turn(tree[root]);
        }
        int prevRoot = tree[0];
        tree[0] = root;
        tree[prevRoot] = root;
        tree[root] = 0;
    }

    void depth(std::vector<int>& res, int node) const
    {
        if (res[node] != -1) return;
        if (node == tree[0]) {
            res[node] = 0;
            return;
        }
        if (res[tree[node]] == -1) {
            depth(res, tree[node]);
        }
        res[node] = res[tree[node]] + 1;
    }

    std::vector<int> depth() const
    {
        std::vector<int> res(tree.size(), -1);
        for (int i : boost::irange(std::size_t{1}, res.size())) {
            depth(res, i);
        }
        return res;
    }
};

void prog()
{
    input in;
    output out;
    int n, u, v;
    in >> n, u, v;
    RootedTree tree(n);
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        in >> a, b;
        tree.addEdge(a, b);
    }
    tree.turn(u);
    auto ud = tree.depth();
    tree.turn(v);
    auto vd = tree.depth();
    int res = -1;
    for (int i : boost::irange(1, n + 1)) {
        if (ud[i] < vd[i]) {
            res = std::max(res, vd[i]);
        }
    }
    out, res - 1;
}

int main()
{
    prog();
    return 0;
}

