private:
	int V;
	vector<vector<int> > G;
	vector<int> ord, depth, id;
	segtree<int> st;
	void dfs(int u, int p, int k) {
		id[u] = (int)ord.size();
		ord.push_back(u);
		depth[u] = k;
		for (int v : G[u]) {
			if (v != p) {
				dfs(v, u, k + 1);
				ord.push_back(u);
			}
		}
	}

public:
	LCA(int node_size) : V(node_size), G(V), depth(V), id(V, -1) {}
	LCA(vector<vector<int>> G) : V(G.size()), G(G), depth(G.size()), id(G.size(), -1) {}
	void add_edge(int from, int to) {
		G[from].push_back(to), G[to].push_back(from);
	}
	void build() {
		ord.reserve(2 * V - 2);
		for (int i = 0; i < V; i++) {
			if (id[i] < 0) {
				dfs(i, -1, 0);
			}
		}
		vector<int> stvec(2 * V - 2);
		for (int i = 0; i < 2 * V - 2; i++) {
			stvec[i] = depth[ord[i]];
		}
		st.resize(stvec);
	}
	int lca(int u, int v) {
		DMP(st.query(min(id[u], id[v]), max(id[u], id[v]) + 1).second);
		return ord[st.query(min(id[u], id[v]), max(id[u], id[v]) + 1).second];
	}
	int dist(int u, int v) {
		int lca_ = lca(u, v);
		return depth[u] + depth[v] - 2 * depth[lca_];
	}
};

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;
	int t, a;
	cin >> t >> a;
    t--,a--;

	vector<vector<int>> edges(N);
	for (int i = 0; i < N - 1; i++) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		edges[u].emplace_back(v);
		edges[v].emplace_back(u);
	}

	LCA tree(edges);
	tree.build();

	int lca_i = tree.lca(t, a);
	DMP(lca_i);
	if (tree.dist(lca_i, t) <= tree.dist(lca_i, a)) {
		cout << tree.dist(t, a) - 1 << "\n";
	}
	else {
      exit(0);
		int max_d = 0;
		for (int i = 0; i < N; i++) {
			max_d = max(max_d, tree.dist(i, a));
		}
		cout << max_d - 1 << "\n";
	}


	return 0;
}

