	  for (int i=0; i<n; i++){parent[i]=-1;}
	  dfs(vertex,-1);
	  int ans=0,prev_ta=t1,prev_ao=t2;
	  ta=t1;ao=t2;
	  while(true){
		  if(ta==ao){break;}
		  if(ta==vertex){
			  ta=prev_ta;
		  }
		  else if(ta!=vertex){
			  prev_ta=ta;
			  ta=parent[ta];
		  }
		  if(ta==ao){break;}
		  if(ao==vertex){
			  ao=prev_ao;
