typedef long long ll;
const int nmax=100005;
struct edge{ll to;ll cost;};
vector<edge> tree[nmax];
ll d[nmax],t[nmax],h[nmax];
bool vis[nmax];
ll n;
void dijkstra(ll s){
  priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,greater<pair<ll,ll>>> pq;
  fill(d,d+n,1e18);
  d[s]=0;
  pq.push(make_pair(0,s));
  while(!pq.empty()){
    pair<ll,ll> p=pq.top();
    pq.pop();
    ll v=p.second;
    if(d[v]<p.first){
      continue;
    }
    for(auto x:tree[v]){
      edge e=x;
      if(d[e.to]>d[v]+e.cost){
        d[e.to]=d[v]+e.cost;
        pq.push(make_pair(d[e.to],e.to));
      }
    }
  }
}
vector<vector<int>> g(nmax);
void dfs(int u){
  stack<int> st;
  st.push(u);
  h[u]=0;
  vis[u]=0;
  while(!st.empty()){
    int p=st.top();
    st.pop();
    for(auto x:g[p]){
      if(!vis[x]&&t[x]<=d[x]){
        h[x]=h[p]+1;
        vis[x]=true;
        st.push(x);
      }
    }
  }
}
