    tree[b].push_back(edge{a,1});
    g[a].push_back(b);
    g[b].push_back(a);
  }
  dijkstra(u);
  for(int i=0;i<n;i++){
    t[i]=d[i];
  }
  dijkstra(v);
  ll ans=0;
  dfs(u);
  for(int i=0;i<n;i++){
    if(h[i]){
      ans=max(ans,d[i]);
    }
  }
  cout << max((ll)0,ans-1) << endl;
}

