    Dijkstra dij(n);
    for(int i=0;i<n-1;i++){
        int a,b;
        cin>>a>>b;
        a--,b--;
        dij.add_undirected_edge(a,b,1);
    }
    int now = 0;
    int p = 0;
    vector<ll> d=dij.shortest_path(0);
    for(int i=0;i<n;i++){
        if(now < d[i]){
            now = d[i];
            p=i;
        }
    }
    vector<ll> f=dij.shortest_path(p);
    now=0;
    int q=0;
    for(int i=0;i<n;i++){
        if(now<f[i]){
            now = f[i];
            q=i;
        }
    }
    bool used[n]={};
    for(int i=0;i<n;i++){
        if(now == d[i] + f[i]) used[i]=1;
    }
