void depth(Graph &G,int v,int p,vector<int> &dep){

  dep[v]=dep[p]+1;

  for(auto nv:G[v]){
    if(nv==p) continue;
    depth(G,nv,v,dep);
  }

}

void subtree_size(Graph &G,int v,int p,vector<int> &subtree){

  for(auto nv:G[v]){
    if(nv==p) continue;
    subtree_size(G,nv,v,subtree);
  }

  subtree[p]=subtree[v]+1;

}


