void dfs(int v, int d, int p) {
  dist[v] = d;
  for (int nv : g[v]) {
    if (nv == p) { continue; } // skip parent
    dfs(nv, d+1, v);
  }
}

vector<ll> calcDist(int s) {
  dist.assign(n, 0); // reset
  dfs(s, 0, -1);
  return dist;
}

