void solve() {
    int n;
    cin >> n;
    if (n == 2) {
        cout << 0 << endl;
        return;
    }

    int s, t;
    cin >> s >> t;
    --s; --t;
    vector<vector<pil> > G(n);
    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        G[a].eb(b, 1);
        G[b].eb(a, 1);
    }

    auto dijkstra = [&](int s) {
        vector<ll> d(n, INF);
        priority_queue<pli, vector<pli>, greater<pli> > q;

        d[s] = 0;
        q.emplace(0, s);

        while (!q.empty()) {
            pli p = q.top();
            q.pop();

            int v = p.S;
            if (d[v] < p.F) continue;
            rep(i, sz(G[v])) {
                int nv = G[v][i].F;
                ll cost = G[v][i].S;
                if (chmin(d[nv], d[v] + cost)) {
                    q.emplace(d[nv], nv);
                }
            }
        }
        return d;
    };
    auto d1 = dijkstra(s), d2 = dijkstra(t);
    // cerr << d1 << endl << d2 << endl;

    int ma = 1, g = s; // d1[s]<d2[s]
    rep(i, n) if (d1[i] < d2[i] && chmax(ma, d2[i])) g = i;

    auto d3 = dijkstra(g);
    rep(i, n) {
        auto calc = [&](int x) {
            int mi = inf, nv = -1;
            for (pil p : G[x]) {
                if (chmin(mi, d3[p.F])) {
                    nv = p.F;
                }
            }
            return nv;
        };
        s = calc(s);
        // cerr << "s t " << s << " " << t << endl;
        if (s == t) {
            cout << i << endl;
            return;
        }

        t = calc(t);
        // cerr << "s t " << s << " " << t << endl;
        if (s == t) {
            cout << i + 1 << endl;
            return;
        }
    }
}

