	while(!pp.empty()){
		P t=pp.top();pp.pop();
		if(t.first!=a[t.second])continue;
		for(auto g:e[t.second]){
			if(a[g.second]>t.first+g.first){
				a[g.second]=t.first+g.first;
				pp.push(P{a[g.second],g.second});
			}
		}
	}
	rep(0,i,n)b[i]=inf;
	b[v]=0;
	priority_queue<P,vector<P>,greater<P>>q;
	//(コスト、頂点番号)で入れる
	q.push(P{0,v});
	while(!q.empty()){
		P t=q.top();q.pop();
		if(t.first!=b[t.second])continue;
		for(auto g:e[t.second]){
			if(b[g.second]>t.first+g.first){
				b[g.second]=t.first+g.first;
				q.push(P{b[g.second],g.second});
			}
		}
