		a--;b--;

		E[a].push_back(b);
		E[b].push_back(a);
	}

	vector<int> dis(n,Inf);
	queue<int> Q;
	Q.push(u);

	dis[u] = 0;

	while(Q.size()!=0){
		int from = Q.front();
		Q.pop();

		for(int i=0;i<E[from].size();i++){
			int to = E[from][i];
			if(dis[to]!=Inf)continue;
			dis[to] = dis[from]+1;
			Q.push(to);
		}
	}


	int cost = (dis[v]-1)/2;

	vector<int> Dis(n,Inf);
	Dis[v] = 0;
	Q.push(v);

	while(Q.size()!=0){
		int from = Q.front();
		Q.pop();
		for(int i=0;i<E[from].size();i++){
			int to = E[from][i];
			if(Dis[to] != Inf)continue;
			Dis[to] = Dis[from]+1;
			Q.push(to);
		}
	}
	int ind;
	for(int i=0;i<n;i++){
		if(dis[i] == cost && dis[i] + Dis[i] == dis[v]){
			ind=i;
			break;
		}
