#include <cassert>
using namespace std;

struct LCA {
private:
  vector<vector<int>> G;
  size_t n, m;
  vector<vector<int>> A;
  void dfs(int v, int p){
    for(auto v_ : G[v]){
      if(v_ == p) continue;
      A[v_][0] = v;
      D[v_] = D[v]+1;
      dfs(v_,v);
    }
  }
  void build(int r){
    dfs(r,-1);
    A[r][0] = r;
    for(size_t i = 1; i < m; ++i){
      for(size_t j = 0; j < n; ++j){
        A[j][i] = A[A[j][i-1]][i-1];
      }
    }
  }
public:
  vector<int> D;
  LCA(const vector<vector<int>>& Tree, int r) : G(Tree), n(Tree.size()), m(1), D(n,0) {
    size_t t = 1;
    while(t < n) ++m, t *= 2;
    A = vector<vector<int>>(n,vector<int>(m,-1));
    build(r);
  }
  size_t query(int u, int v){
    if(D[u] < D[v]) swap(u,v);

    for(size_t i = m-1; i < m; --i){
      size_t u_ = A[u][i];
      if(D[u_] < D[v]) continue;
      u = u_;
    }

    if(u == v) return u;
    assert(D[u] == D[v]);
    for(size_t i = m-1; i < m; --i){
      if(A[u][i] != A[v][i])
        u = A[u][i], v = A[v][i];
    }
    return A[u][0];
  }
};

int main(){
  int N, u, v;
  cin >> N >> u >> v;
  --u,--v;
  vector<vector<int>> T(N);
  for(int i = 0; i < N-1; ++i){
    int a, b;
    cin >> a >> b;
    --a,--b;
    T[a].push_back(b);
    T[b].push_back(a);
  }
  LCA lca(T,v);
  int ans = 0;
  for(int i = 0; i < N; ++i){
    int a = lca.query(u,i);
    int d_a = lca.D[a], d_u = lca.D[u];
    if(d_u-d_a > d_a) continue;
    ans = max(ans,lca.D[i]-1);
  }
  cout << ans << endl;
}

