vector <int> gr[1 + N];
int best[1 + N];
int fat[1 + N];
int bestson[1 + N];

void pre_dfs (int node, int f) {
    h[node] = h[f] + 1;
    fat[node] = f;
    best[node] = 1;
    bestson[node] = 0;
    for (auto son : gr[node])
        if (son != f) {
            pre_dfs (son, node);
            if (best[node] < best[son] + 1) {
                bestson[node] = son;
                best[node] = best[son] + 1;
            }
        }
}

int main () {
    ios::sync_with_stdio (false);
    cin.tie (0); cout.tie (0);

    int n, a, b;
