    for (int i = 1; i < n; i++) {
        int x, y;
        cin >> x >> y;
        gr[x].pb (y);
        gr[y].pb (x);
    }
    pre_dfs (b, 0);
    int node_a = a;
    int steps = 0;
    while (h[b] + steps + 1 < h[a] - steps - 1) {
        steps++;
        node_a = fat[node_a];
    }
    int node_b;
    if ((h[b] - h[a]) % 2) {
        node_b = fat[node_a];
    }
    else {
        node_b = fat[fat[node_a]];
    }
    if (node_b == 0) {
        cout << 0 << "\n";
    }
    int ans = steps;
    steps = 0;
    while (node_a != node_b) {
        if (steps % 2) {
            node_b = bestson[node_b];
            ans++;
        }
        else {
            if (bestson[node_a] == 0)
                node_a = fat[node_a];
            else
                node_a = bestson[node_a];
        }
        steps++;
        if (steps > N) {
            cout << 0;
            return 0;
        }
    }
    cout << ans << "\n";
    return 0;
}

