            ha.push_back(i);
            if(i == a && v[i][0] == b){
                cout << 0 << endl;
                return;
            }
        }
    }
    memo.resize(N, 0);
    dist.resize(N, 0);
    auto tq = q;
    auto tmemo = memo;
    auto tdist = dist;
    q.push({a, 0});
    memo[a] = 1;
    bfs();
    auto dist1 = dist;
    q = tq; memo = tmemo; dist = tdist;
    q.push({b, 0});
    memo[b] = 1;
    bfs();
    auto dist2 = dist;
    int res = 0;
    for(auto t: ha){
        if(dist1[t] < dist2[t]) res = max(res, dist2[t]);
    }

    cout << res-1 << endl;
}

