void solve(){
    long long x = lca(U, V);
    long long disV = height[V] - height[x];
    long long disU = height[U] - height[x];
    if(disV <= disU){
        ans += (disV + disU - 1) / 2;
        U = father(U, (disV + disU - 1) / 2);
        ans += dp[U];
        if((disU + disV) % 2 == 0)
            ans++;
    }
    else{
        ans += (disV + disU - 1) / 2;
        U = father(V, (disV + disU) / 2);
        //cout << U << ' ' << DP[U] << endl;
        ans += DP[U];
        if((disU + disV) % 2 == 0)
            ans++;
    }
}

void dfs(long long u){
    mark[u] = 1;
    for(auto v: adj[u]){
        if(!mark[v]){
            f[0][v] = u;
            height[v] = height[u] + 1;
            dfs(v);
            dp[u] = max(dp[v] + 1, dp[u]);
        }
    }
}

void calcDP(long long u){
    mark[u] = 0;
    long long maxim = 0;
    long long secmax = 0;
    if(u != 0)
        maxim = DP[u] + 1;
    for(auto v: adj[u]){
        if(mark[v]){
            if(dp[v] + 1 >= maxim){
                secmax = maxim;
                maxim = dp[v] + 1;
            }
            else if(dp[v] > secmax)
                secmax = dp[v] + 1;
        }
    }
    for(auto v: adj[u]){
        if(mark[v]){
            DP[v] = maxim;
            if(dp[v] + 1 == maxim)
                DP[v] = secmax;
            //cout << v << ' ' << DP[v] << ' ' << maxim << ' ' << secmax << endl;
            calcDP(v);
        }
    }
}

void calcf(){
    for(long long i = 1; i < 20; i++)
        for(long long j = 0; j < n; j++)
            if(f[i - 1][j] != -1)
                f[i][j] = f[i - 1][f[i - 1][j]];
}

long long lca(long long u, long long v){
    if(height[u] > height[v])
        swap(u, v);
    for(long long i = 19; i >= 0; i--)
        if(f[i][v] != -1 && height[f[i][v]] >= height[u])
            v = f[i][v];
    if(u == v)
        return u;
    for(long long i = 19; i >= 0; i--){
        if(f[i][v] != -1 && f[i][u] != -1 && f[i][v] != f[i][u]){
            v = f[i][v];
            u = f[i][u];
        }
    }
    return f[0][u];
}

long long father(long long u, long long t){
    for(long long i = 19; i >= 0; i--){
        if(((1 << i) & t) != 0){
            u = f[i][u];
        }
    }
    return u;
}

