// mod. m での a の逆元 a^{-1} を計算する
long long modinv(long long a, long long m) {
	long long b = m, u = 1, v = 0;
	while (b) {
		long long t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= m;
	if (u < 0) u += m;
	return u;
}

//aCbを1000000007で割った余りを求める
llint convination(llint a, llint b) {
	llint ans = 1;
	for (llint i = 0; i < b; i++) {
		ans *= a - i;
		ans %= 1000000007;
	}
	for (llint i = 1; i <= b; i++) {
		ans *= modinv(i, 1000000007);
		ans %= 1000000007;
	}
	return ans;
}

//aのb乗をmodで割った余りを求める
llint power(llint a, llint b) {
	if (b == 1)return a;
	if (b == 0)return 1;
	llint tmp = power(a, (llint)b / 2);
	tmp *= tmp;
	tmp %= mod;
	if (b % 2 == 1) {
		tmp *= a;
		tmp %= mod;
	}
	return tmp;
}

bool dfs(int p, int goal, vvint& a, vint& cost, vbool visited) {
	if (visited[p])return false;
	visited[p] = true;
	rep(i, a[p].size()) {
		if (a[p][i] == goal) {
			return true;
		}
		else {
			if (dfs(a[p][i], goal, a, cost, visited)) {
				cost[a[p][i]] = -1;
				return true;
			}
		}
	}
	return false;
}

int main() {
	int n;
	cin >> n;
	int u, v;
	cin >> u >> v;
	u--; v--;
	vvint a(n);
	rep(i, n - 1) {
		int x, y;
		cin >> x >> y;
		x--; y--;
		a[x].push_back(y);
		a[y].push_back(x);
	}
	//uからダイクストラ
	//一番遠い逃げ道を検索して、あとはO(1)?
	vint cost(n, 100000);
	vbool visited(n, false);
	//コスト、位置
	priority_queue<pint,vpint,greater<pint>>que;
	que.push({ 0,u });	
	while (que.size() != 0) {
		auto top = que.top(); que.pop();
		if (visited[top.second])continue;
		visited[top.second] = true;
		cost[top.second] = top.first;
		rep(i, a[top.second].size()) {
			que.push({ top.first + 1,a[top.second][i] });
		}
	}
	vint cost_v(n, 100000);
	vbool visited2(n, false);
	priority_queue<pint, vpint, greater<pint>>que2;
	que2.push({ 0,v });
	while (que2.size() != 0) {
		auto top = que2.top(); que2.pop();
		if (visited2[top.second])continue;
		visited2[top.second] = true;
		cost_v[top.second] = top.first;
		rep(i, a[top.second].size()) {
			que2.push({ top.first + 1,a[top.second][i] });
		}
	}
	fill(visited.begin(), visited.end(), false);
	//uからvまでの途中にある場所は全部costを-1にする
	dfs(u, v, a, cost, visited);
	cost[v] = -1;
	//uのほうがvよりもコストが低い、uからのコストが最も高い点を探す
	int mx = -1;
	int p = -1;
	rep(i, n) {
		if (cost[i] < cost_v[i]) {
			if (mx < cost_v[i] ) {
				mx = cost_v[i] ;
				p = i;
			}
		}
	}
	while(cost_v[p] - cost[p] > 2) {
		cost[p] += 2;
	}
	if (cost_v[p] - cost[p] == 2)cost[p]++;
	cout << cost[p] << endl;
	return 0;
}

