        cin >> a >> b;
        --a; --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    lca = LowestCommonAncestor(aoki, n);

    dfs(takahashi, -1, 0);

    int dest = takahashi;  // (高橋くんからの距離) < (青木くんからの距離) で青木くんからもっとも遠いノード
    int dest_dist = lca.depth[takahashi];
    for(int i=0;i<n;++i) {
        if(depth_from_takahashi[i] < lca.depth[i] &&  dest_dist < lca.depth[i]) {
            dest = i;
            dest_dist = lca.depth[i];
        }
    }
    int dest_lca = lca.get_lca(dest, takahashi);

    bool is_takahashi_turn = true;
    bool used_dest_lca = false;
    int ans = 0;
    while(takahashi != aoki) {
        if(is_takahashi_turn) {
            move(takahashi, (used_dest_lca?dest:dest_lca));
            if(takahashi == dest_lca) used_dest_lca = true;
        } else {
            move(aoki, takahashi);
            ++ans;
        }
        is_takahashi_turn ^= true;
    }

    cout << ans << endl;
}

