#define MAXN 100010
int n, l;
vector<int> adj[MAXN];
int timer;
vector<int> tin, tout;
vector<vector<int>> up;

void dfs(int v, int p){
	tin[v] = ++timer;
	up[v][0] = p;
	for (int i = 1; i <= l; ++i)
		up[v][i] = up[up[v][i-1]][i-1];

	for (int u : adj[v]) {
		if (u != p)
			dfs(u, v);
	}

	tout[v] = ++timer;
}

bool is_ancestor(int u, int v){
	return tin[u] <= tin[v] && tout[u] >= tout[v];
}

int lca(int u, int v){
	if (is_ancestor(u, v))
		return u;
	if (is_ancestor(v, u))
		return v;
	for (int i = l; i >= 0; --i) {
		if (!is_ancestor(up[u][i], v))
			u = up[u][i];
	}
	return up[u][0];
}

void init() {
	tin.resize(n+1);
	tout.resize(n+1);
	timer = 0;
	l = ceil(log2(n+1));
	up.assign(n+1, vector<int>(l + 1));
	dfs(n, n);
}
int dist[2][MAXN];

void calcd(int w, int k){
	vector<bool> visited(n+1, false);
	queue<pair<int, int>> q;
	q.push({w, 0});
	visited[w] = true;
	while(not q.empty()){
		int u = q.front().ff;
	       	int d = q.front().ss; q.pop();
		dist[k][u] = d;
		for(auto v:adj[u]){
			if(visited[v]) continue;
			visited[v] = true;
			q.push({v, d+1});
		}
	}
}


