	Graph g(n);

	REP(i,n-1){
		ll a,b;
		cin>>a>>b;
		a--;b--;
		add_edge(g,a,b,1,true,1);
	}
	Array d;
	Dijkstra(g,v,d);

	Array dt;
	Dijkstra(g,u,dt);

	ll ans=0;
	ll min=INF;

	REP(i,n){
		if(d[i]>dt[i]){
			chmax(ans,d[i]-1);
		}

	}
	//cout<<ans<<min<<endl;

	if(min!=INF) chmin(ans,min);
	cout<<ans<<endl;

	return 0;
}

