	vector<int> dfs(UnWeightedGraph& G, int start){
		int N = sz(G);
		vector<int>dist(sz(G),-1);
		deque<pi> que;
		// 初期条件 (頂点 0 を初期ノードとする)
		que.push_back({start,0}); 

		while (!que.empty()) {
			pi vd = que.back(); //backにするとDFSになる
			que.pop_back();//pop_backにするとDFSになる
			int v=vd.first; int d=vd.second;
			if (dist[v] != -1) continue;
			dist[v] = d;
			// v から辿れる頂点をすべて調べる
			for (auto nv : G[v]) {
				que.push_back({nv,d+1});
			}
		}
		return dist;
	}

