void solve(){
    int N,u,v;cin>>N>>u>>v;
    u--;v--;
    vector<vector<int>> tree(N);
    REP(i,N-1){
        int a,b; cin>>a>>b;
        a--;b--;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }
    int dtl=0,dtv=0;
    int flag=0;
    if(tree[u].size()==1) flag++;
    function<bool(int,int,int)> dfs=[&](int now,int pre,int len){
        if(now==v){
            dtv=len;
            return true;
        }
        if(tree[now].size()==1) chmax(dtl,len);
        bool res=false;
        for(auto e:tree[now]){
            if(e==pre) continue;
            if(dfs(e,now,len+1)){
                res=true;
                if(len==(dtv-1)/2) u=now;
            }
        }
        return res;
    };
    dfs(u,-1,0);
    int ans=(dtv-1)/2;
    if(dtv%2==0) ans++;
    if(flag==1&&dtv<=2){
        cout<<ans<<endl;
        return;
    }
    dtl=0;
    dfs(u,-1,0);
    cout<<dtl<<endl;
    ans+=dtl;

    cout<<ans<<endl;
}

