struct Node {
  int key;
  int depth;
};

vector<vector<int>> G;  // 隣接リスト

bool isLeaf(int node) {
  if (G[node].size() == 1) {
    return true;
  } else {
    return false;
  }
}

int n;
vector<bool> flags;

queue<Node> q;

VI bfs() {
  VI dist(n);
  while (!q.empty()) {
    Node now = q.front();
    q.pop();  // キューの先頭を取り出す
    dist[now.key] = now.depth;

    // 隣接ノードを探索．進むことができればキューに格納する．
    REP(i, G[now.key].size()) {
      int next_key = G[now.key][i];
      Node next = {next_key, now.depth + 1};
      if (!flags[next_key]) {
        flags[next_key] = true;
        q.push(next);
      }
    }
  }
  return dist;
}

int main() {
  int u, v;
  cin >> n >> u >> v;
  u--;
  v--;
  G.resize(n);
  VI dist_from_takahashi(n);
  VI dist_from_aoki(n);
  flags.resize(n);

  REP(i, n - 1) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  Node takahashi = {u, 0};
  q.push(takahashi);
  flags[u] = true;
  dist_from_takahashi = bfs();

  Node aoki = {v, 0};
  q.push(aoki);
  fill(flags.begin(), flags.end(), false);
  flags[v] = true;
  dist_from_aoki = bfs();

  if (isLeaf(u) && dist_from_takahashi[v]==1) {
    ANS(0);
    return 0;
  }

  int ans = 0;
  REP(i, n) {
    if (isLeaf(i)) {
      int dt = dist_from_takahashi[i];
      int da = dist_from_aoki[i];
      if (dt < da) {
        int parent = G[i][0];
        ans = max(ans, dist_from_aoki[parent]);
      }
    }
  }

  ANS(ans);

  return 0;
}

