int N;
vector<vector<int>> edge;

vector<int> CalculateCost(int s)
{
    int INF = INT32_MAX;
    vector<int> cost(N, INF);

    cost[s] = 0;
    queue<int> pos_queue;
    pos_queue.push(s);

    while (pos_queue.size())
    {
        int pos = pos_queue.front();
        pos_queue.pop();
        rep(i, edge[pos].size())
        {
            int next = edge[pos][i];
            if (cost[next] == INF)
            {
                cost[next] = cost[pos] + 1;
                pos_queue.push(next);
            }
        }
    }
    return cost;
}

int main()
{
    int u, v;
    cin >> N >> u >> v;
    u--;
    v--;
    edge.resize(N);
    rep(i, N - 1)
    {
        int A, B;
        cin >> A >> B;
        A--;
        B--;
        edge[A].push_back(B);
        edge[B].push_back(A);
    }
    vector<int> costT = CalculateCost(u);
    vector<int> costA = CalculateCost(v);
    vector<int> cost(N);

    int ans = 0;
    rep(i, N)
    {
        cost[i] = costA[i] - costT[i];
        if (cost[i] > 0)
            ans = max(ans, costA[i]);
    }
    cout << ans - 1 << endl;

    return 0;
}

