ll N,u,v;
ll depth[100010];
ll par[100010];
vector<ll> edges[100010];
void SetDepth(ll v){
    depth[v]=depth[par[v]]+1;
    for(auto e:edges[v]){
        if(depth[e]==INF){
            par[e]=v;
            SetDepth(e);
        }
    }
}
ll MaxDepth(ll v){
    ll ret=depth[v];
    for(auto e:edges[v]){
        if(e!=par[v]){
            ret=max(ret,MaxDepth(e));
        }
    }
    return ret;
}
int main(){
    cin>>N>>u>>v;
    for(ll i=0;i<N-1;i++){
        ll a,b;
