        g[b].push_back(a);
    }
    LCA lca(N,0,g);
    int p = lca.lca(U,V);
    vec<int> distU(N,0),distV(N,0),distP(N,0),dp(N,0);
    auto dfs = [&](auto& self,int cur,int par,vec<int>& dist,bool flag)-> void{
        for(auto& e:g[cur]) if(e!=par){
            dist[e] = dist[cur]+1;
            if(flag) dp[cur] = max(dp[cur],dp[e]+1);
            self(self,e,cur,dist,flag);
        }
    };

    dfs(dfs,V,-1,distV,0);
