std::map<int, std::set<int>> map;

int u,v;

int dist_u[200001];
int dist_v[200001];

void cal_u(const int &cur, const int &depth){
    if(dist_u[cur] || (cur == u && depth))return;
    dist_u[cur] = depth;
    for(const int &next: map[cur]){
        cal_u(next, depth + 1);
    }
}


void cal_v(const int &cur, const int &depth){
    if(dist_v[cur] || (cur == v && depth))return;
    dist_v[cur] = depth;
    for(const int &next: map[cur]){
        cal_v(next, depth + 1);
    }
}


int search_u(const int &cur){
    static int last_node, max_depth = 0;
    static bool visited[200000];
    if(visited[cur])return -1;
    visited[cur] = 1;
    if(dist_u[cur] >= dist_v[cur]) return -1;
    if(dist_v[cur] > max_depth){
        max_depth = dist_v[cur];
        last_node = cur;}
    for(const int &next: map[cur]){
        search_u(next);
    }
    return max_depth;
}

