  int N, U, V, A, B;
  cin >> N >> U >> V;
  for (int i=0; i<N-1; i++) {
    cin >> A >> B;
    G[A].push_back(B);
    G[B].push_back(A);
  }
  dfs(V, 0);
  dfs2(U, 0);
  int ret = 0;
  for (int i=1; i<=N; i++) {
    if (dist2[i] >= INF) continue;
    if (!leaf[i]) continue;
    int d = dist[i] - 1;
    ret = max(ret, d);
  }
  cout << ret << endl;
}

