void dijkstra(){
    for(int i=1;i<=n;i++) dist[i] = INT_MAX;
    for(int i=1;i<=n;i++) vd[i] = false;
    priority_queue < pii > q;
    q.push(mp(0,T));
    dist[T] = 0;
    while(!q.empty()){
        int node = q.top().se;
        q.pop();
        if(!vd[node]){
            vd[node] = true;
            for(int i=0;i<adj[node].size();i++){
                int nex = adj[node][i];
                if(dist[nex] > dist[node] + 1){
                    dist[nex] = dist[node] + 1;
                    q.push(mp(-dist[nex],nex));
                }
            }
        }
    }
}
bool eaten(int x){
    bool vis[n+10];
    for(int i=1;i<=n;i++) vis[i] = false;
    queue <pii> q;
    q.push(mp(0,A));
    while(!q.empty()){
        int node = q.front().se;
        int steps = q.front().fi;
        q.pop();
        if(steps>x) break;
        if(!vis[node]){
            vis[node] = true;
            for(int i=0;i<adj[node].size();i++){
                q.push(mp(steps+1,adj[node][i]));
            }
        }
    }

    for(int i=1;i<=n;i++){
        if(dist[i]%2 == x%2 && dist[i]<=x){
            bool danger = true;
            if(!vis[i]){
                for(int j=0;j<adj[i].size();j++){
                    if(!vis[adj[i][j]]) {danger = false; break;}
                }
            }

            if(!danger) return false;
        }
    }
    return true;
}
int bins(){
    int l = 0;
    int r = n;
    int res = 0;
    while(l<=r){
        int mid = (l+r)/2;
        if(eaten(mid)){res = mid;r = mid-1;}
        else{l = mid+1;}
    }
    return res;
}
