const int inf = 1e9;

void show(const VI &v1, const VI &v2) {
	for (int i = 0; i < v1.size(); i++) {
		printf("%d: %d %d\n", i+1, v1[i], v2[i]);
	}
}

VI make_dist(int st, const VVI &connect) {
	int n = connect.size();
	VI dist(n, inf);
	queue<int> que;
	que.push(st);
	dist[st] = 0;

	while (!que.empty()) {
		auto x = que.front();
		que.pop();

		for (auto y: connect[x]) {
			if (dist[y] == inf) {
				dist[y] = dist[x] + 1;
				que.push(y);
			}
		}
	}
	return dist;
}

int main() {
	int n, u, v, a, b;
	cin >> n >> u >> v;
	u--;
	v--;

	VVI connect(n);
	for (int i = 0; i < n - 1; i++) {
		cin >> a >> b;
		a--;
		b--;
		connect[a].push_back(b);
		connect[b].push_back(a);
	}

	int pos_t = u;
	int pos_a = v;
	auto dist_t = make_dist(pos_t, connect);
	auto dist_a = make_dist(pos_a, connect);

	// show(dist_t, dist_a);

