#include <bits/stdc++.h>
using namespace std;
int N;
vector<set<int>> E;
//追いかけ方をメモ化再帰
map<pair<int,int>,int> NM;
int next(int T, int A){
//  cout << "next(" << T << "," << A << ")=?" << endl;
  //青木君がどの頂点に行くべきか
  if (NM.count(make_pair(T,A))){
//    cout << "next(" << T << "," << A << ")=" << NM.at(make_pair(T,A)) << endl;
    return NM.at(make_pair(T,A));
  }
  if (E[A].count(T)){
    NM[make_pair(T,A)]=T;
//    cout << "next(" << T << "," << A << ")=" << T << endl;
    return T;
  }
  vector<bool> C(N,false);
  queue<int> Q;
  C[T]=true;
  Q.push(T);
  while (1){
    int t = Q.front();
    Q.pop();
    for (int i : E[t]){
      if (E[A].count(i)){
        NM[make_pair(T,A)]=i;
//        cout << "next(" << T << "," << A << ")=" << i << endl;
        return i;
      }
      if (!C[i]){
        Q.push(i);
        C[i]=true;
      }
    }
  }
}
//手数を再帰
int rec(int T, int A){
//  cout << "rec(" << T << "," << A << ")=?" << endl;
  //T: 高橋君の位置
  //A: 青木君の位置
  bool flg = true;
  for (int i : E[T]){
    if (i != A) flg = false;
  }
  if (flg){
//    cout << "rec(" << T << "," << A << ")=" << 0 << endl;
    return 0;
  }
  flg = true;
  for (int i : E[T]){
    if (!E[i].count(A)) flg = false;
  }
  if (flg){
//    cout << "rec(" << T << "," << A << ")=" << 1 << endl;
    return 1;
  }
  int res=0;
  for (int i : E[T]){
    if ((!E[A].count(i))&&(A!=i)){
      res = max(res,rec(i,next(i,A)));
    }
  }
//  cout << "rec(" << T << "," << A << ")=" << res+1 << endl;
  return res+1;
}
int main(){
  set<int> s;
  int u,v;
  cin >> N >> u >> v;
