    E.push_back(s);
  }
  for (int i = 0; i < N - 1; i++){
    int A,B;
    cin >> A >> B;
    E[A-1].insert(B-1);
    E[B-1].insert(A-1);
  }
  cout << rec(u-1,v-1);
}

