const int maxn = 100010;
int n, A, B, res, p[maxn], ban[maxn];
vector<int> edge[maxn];
int getdis(int now = A, int last = -1){
	static int dep;
	int res = 0;
	++dep;
	for(int u : edge[now])if(last != u){
		p[u] = now;
		if(u == B)return dep;
		res = getdis(u, now);
		if(res)return res;
	}
	--dep;
	return res;
}
int getfar(int now, int last = -1){
	int res = 0;
	for(int u : edge[now])if(u != last && !ban[u]){
		res = max(res, getfar(u, now)+1);
	}
	return res;
}
signed main(){
	ios_base::sync_with_stdio(0), cin.tie(0);
	cin >> n >> A >> B;
	for(int a, b, i = 1;i < n;++i){
		cin >> a >> b;
		edge[a].pb(b);
		edge[b].pb(a);
	}
	int D = getdis();
	//cout << "D " << D << '\n';
	int adv = (D-1)/2;
	res = adv;
	for(int i = 0;i < adv;++i)B = p[B];
	if(D&1)A = p[B];
	else A = p[p[B]];
	while(B != A)ban[B] = true, B = p[B];
	int last = getfar(A);
	//cout << "LST " << last << '\n';
	cout << last + res + ((D&1) ? 0 : 1) << '\n';
}

