struct Edge {
  ll to, cost;
  Edge(ll to, ll cost) : to(to), cost(cost) {}
};

typedef vector<vector<Edge> > AdjList; // 辺の情報
typedef vector<ll> dis_dijkstra; // 距離のvector

dis_dijkstra dijkstra(ll n ,AdjList A,ll st ,ll weigh){// 頂点数 n ,グラフ　A　,始点　st　,初期値 weigh
  dis_dijkstra DIS;
  vector<bool> chek;
  DIS = vector<ll>(n+1, LINF);
  chek = vector<bool>(n+1, 0); 
  DIS[st]=weigh;
  ll key=st;
  priority_queue <pair<ll,ll>> PQ;
  PQ.push(mp(weigh,st));
  while(!PQ.empty()){
    pair<ll,ll> f = PQ.top();
    PQ.pop();
    key=f.second;
    chek[key]=1;
    if(DIS[key] < f.first*(-1)){
      continue;
    }
    rep(j,A[key].size()){
      ll v = A[key][j].to;
      if(chek[v]==0 && DIS[v]>DIS[key]+A[key][j].cost){
        DIS[v] = DIS[key] + A[key][j].cost;
        PQ.push(mp(DIS[v]*(-1),v));
      }
    }
  }
  return DIS;
}

