void BFS(int dist[], int s) {
    fill(dist, dist + n, INF);
    queue<int> queue;
    queue.push(s);
    dist[s] = 0;
    while (!queue.empty()) {
        int u = queue.front();
        queue.pop();

        for (int to : graph[u]) {
            if (dist[to] > dist[u] + 1) {
                dist[to] = dist[u] + 1;
                queue.push(to);
            }
        }
    }
}

bool check(int move_a, int move_t) {
    for (int u = 0; u < n; u++) {
        if (dist_t[u] > move_t || dist_t[u] % 2 != move_t % 2) continue;
        if (dist_a[u] > move_a) {
            return false;
        }
    }
    return true;
}

