// BFSの関数を作ってきれいに書く
int n, u, v;
struct pqdata {
    int pos; int dist;
};

vector< vector<int> > graph(100100, vector<int>());
vector<int> Tgraph(100100, -1);
vector<int> Agraph(100100, -1);

void bfs(vector<int> &vec, int start) {
    pqdata first;
    first.pos = start; first.dist = 0;
    queue<pqdata> que;
    que.push(first);
    vec.at(start) = 0;
    while(!que.empty()) {
        pqdata now = que.front();
        que.pop();
        for(int i = 0; i < (int)graph.at(now.pos).size(); ++i) {
            int npos = graph.at(now.pos).at(i);
            int ndist = now.dist+1;
            if(vec.at(npos) == -1) {
                vec.at(npos) = ndist;
                pqdata next;
                next.pos = npos; next.dist = ndist;
                que.push(next);
            }
        }
    }
}

int main() {
    cin >> n >> u >> v;
    u--; v--;
    for(int i = 0; i < n-1; ++i) {
        int aa, bb; cin >> aa >> bb;
        aa--; bb--;
        graph.at(aa).emplace_back(bb);
        graph.at(bb).emplace_back(aa);
    }
    bfs(Tgraph, u);
    bfs(Agraph, v);

    int Alen = 0;
    for(int i = 0; i < n; ++i) {
        if(Agraph.at(i) > Tgraph.at(i)) {
            chmax(Alen, Agraph.at(i));
        }
    }
    cout << Alen-1 << endl;
}

