ll dfs(ll v, ll parent, vector<vector<ll>> &graph, vector<ll> &children_depths, vector<ll> &parents) {
  ll ret = 0;
  each (u, graph[v]) {
    if (u == parent) {
      continue;
    }
    ret = max(ret, dfs(u, v, graph, children_depths, parents) + 1);
  }
  children_depths[v] = ret;
  parents[v] = parent;
  return ret;
}

int main() {
  cout << fixed << setprecision(10);
