    cin.rdbuf(ifs.rdbuf());
  }

  ll N, V, U;
  cin >> N >> V >> U;
  vector<tuple<ll, ll>> AB( N - 1);
  rep (i,  N - 1) {
    cin >> get<0>(AB[i]) >> get<1>(AB[i]);
  }

  V -= 1ll;
  U -= 1ll;

  vector<vector<ll>> graph(N, vector<ll>());
  each (ab, AB) {
    ll a, b;
    tie(a, b) = ab;
    a -= 1;
    b -= 1;
    graph[a].push_back(b);
    graph[b].push_back(a);
  }

  vector<ll> children_depths(N, -1);
  vector<ll> parents(N, -1);

  dfs(U, -1, graph, children_depths, parents);
  ll v = V;
  ll dist = 1;
  while (parents[v] != U) {
    v = parents[v];
    dist += 1;
  }

  ll p_cnt = 0;
  v = V;
  ll ans = 0;
  while (dist > 0) {
    ans = max(ans, dist - 1 + children_depths[v] + p_cnt);
    v = parents[v];
    p_cnt += 1;
    dist -= 2;
  }
  cout << ans << "\n";
}

