void dfs(const vector<vector<int>>& graph, vector<int>& dist, int node) {
    rep(i, 0, graph[node].size()) {
        if (dist[graph[node][i]] >= 0) continue;
        dist[graph[node][i]] = dist[node] + 1;
        dfs(graph, dist, graph[node][i]);
    }
}

