void solve() {
  ll N, u, v;
  cin >> N >> u >> v;

  rep (i, N-1) {
    ll A, B;
    cin >> A >> B;
    joint[A].insert(B);
    joint[B].insert(A);
  }

  aoki_distance[v] = 0;
  queue<ll> aoki_q;
  aoki_q.push(v);
  while (aoki_q.size() > 0) {
    ll tmp = aoki_q.front();
    aoki_q.pop();
    ll dis = aoki_distance[tmp];
    for (auto it: joint[tmp]) if (aoki_distance.count(it) == 0) {
      aoki_distance[it] = dis + 1;
      aoki_q.push(it);
    }
  }

  ll first_distance = aoki_distance[u];
  // 0,1
  // 0,2 
  // 0,3 -> 1,2
  // 0,4 -> 1,3
  ll mid_distance = first_distance / 2 + 1;
  ll mid_point = u;
  while (aoki_distance[mid_point] != mid_distance) {
    for (auto it: joint[mid_point]) {
      if (aoki_distance[it] < aoki_distance[mid_point]) {
        mid_point = it;
        break;
      }
    }
  }

  queue<ll> far_queue;
  far_queue.push(mid_point);
  ll far = aoki_distance[mid_point];
  while (far_queue.size() > 0) {
    ll tmp = far_queue.front();
    far_queue.pop();
    far = max(far, aoki_distance[tmp]);
    for (auto it: joint[tmp]) {
      if (aoki_distance[tmp] < aoki_distance[it]) far_queue.push(it);
    }
  }

  cout << far - 1 << endl;
}

