using namespace std;

int bfs(int n, vector<stack<int>> &edge, int p, vector<int> &cnt) {

  int max = cnt[p];
  queue<int> q;

  while (!edge[p].empty()) {
    int nxt = edge[p].top();
    edge[p].pop();

    //cout << "nxt: " << nxt << endl;

    if (cnt[nxt] < 0) {
      cnt[nxt] = cnt[p] + 1;
      q.push(nxt); 
    }
  }

  //cout << "qsize " << q.size() << endl;

  while (!q.empty()) {
    int nxt = q.front();
    q.pop();
    int tmp = bfs(n, edge, nxt, cnt);
    if (max < tmp) max = tmp;
  }

  return max;
}


