int fire[N] , nex[2*N] , to[2*N] , Ans[N] , dep[N] ;

int read()
{
  int x = 0, w = 1;
  char ch = 0;
  while (ch < '0' || ch > '9') {  // ch 不是数字时
    if (ch == '-') w = -1;        // 判断是否为负
    ch = getchar();               // 继续读入
  }
  while (ch >= '0' && ch <= '9') {  // ch 是数字时
    x = x * 10 + (ch - '0');  // 将新读入的数字’加’在 x 的后面
    // x 是 int 类型，char 类型的 ch 和 ’0’ 会被自动转为其对应的
    // ASCII 码，相当于将 ch 转化为对应数字
    // 此处也可以使用 (x<<3)+(x<<1) 的写法来代替 x*10
    ch = getchar();  // 继续读入
  }
  return x * w;  // 数字 * 正负号 = 实际数值
}

void add(int u , int v){
    nex[++tot] = fire[u] ;
    fire[u] = tot ;
    to[tot] = v ;
}

void dfs1(int x , int fr){
    dep[x] = dep[fr] + 1 ;
    Ans[x] = dep[x] ;
    for(int i = fire[x] ; i ; i = nex[i] ){
        int v = to[i] ;
        if( v == fr ) continue ;
        dfs1( v , x ) ;
        Ans[x] = max( Ans[x] , Ans[v] ) ;
    }
}

int dfs2(int x , int fr , int now )
{
    if( now >= dep[x] ) return 0 ;
    for(int i = fire[x] ; i ; i = nex[i] ){
        int v = to[i] ;
        if( v == fr ) continue ;
        if( dfs2( v , x , now + 1 ) == 0 ) {
            r = x ;
        }
    }
    return 1 ;
}

