    s = read();
    t = read();
    for(int i = 1 ; i <= n - 1 ; i++ ){
        int u , v ;
        u = read();
        v = read();
        add( u , v ) ; add( v , u ) ;
    }
    dfs1( t , 0 ) ;
    dfs2( s , 0 , 0 ) ;
    printf("%d\n" , Ans[r] - 2 ) ;
    return 0 ;
}

