void dfs(int v, int prev, int dis, vector<int>& disList, Graph& g){
    disList[v] = dis;
    for(auto e: g[v]){
        if(e.vertice == prev)   continue;
        dfs(e.vertice, v, dis+1, disList, g);
    }
}

int dfs2(int v, int prev, vector<int>& d1, vector<int>& d2, Graph& g, bool even){
    int res = 0;
    for(auto e: g[v]){
        if(e.vertice == prev)   continue;
        if(d1[e.vertice] < d2[e.vertice]){
            res = max(res, dfs2(e.vertice, v, d1, d2, g, even));
        }
        else if(d1[e.vertice] == d2[e.vertice]){
            res = max(res, d2[e.vertice]);
        }
    }
    res = max(d2[v]-1, res);

    return res;
}

