queue<int> que;
void Search(int n, const vector<list<int>>& mp, vector<int>& d) {
	for (auto i = mp[n].begin(); i != mp[n].end(); i++) {
		if (d[*i] < 0) {
			que.push(*i);
			d[*i] = d[n] + 1;
		}
	}
	if (que.empty())
		return;
	n = que.front();
	que.pop();
	Search(n, mp, d);
	return;
}

