int lca(int u,int v){
    if(dep[u] > dep[v]){
        swap(u,v);
    }
    FORD(i,19,0){
        if(dep[u]+(1<<i) <= dep[v]){
            v = par[v][i];
        }
    }
    if(u == v){
        return u;
    }
    FORD(i,19,0){
        if(par[u][i] == par[v][i]){
            continue;
        }
        u = par[u][i];
        v = par[v][i];
    }
    return par[u][0];
}

