#define in std::cin
#define out std::cout
#define rep(i,N) for(LL i=0;i<N;++i)
typedef long long int LL;

std::vector<std::vector<LL>>G;

// ※！注意！※
// 1-indexで扱う
// MAX_Vはギリギリにしない
const LL MAX_V = 112345;
const LL MAX_LOG_V = 20;
class LCA
{
private:
	LL root = 1;						// 根ノードの番号
	std::vector<std::vector<LL>>parent;
	std::vector<LL>depth;

public:
	void dfs(LL v, LL p, LL d)
	{
		parent[0][v] = p;
		depth[v] = d;
		for (auto i : G[v])
		{
			if (i != p) dfs(i, v, d + 1);
		}
	}

	// 初期化
	void init(LL V)
	{
		parent.resize(MAX_LOG_V, std::vector<LL>(V + 1));
		depth.resize(V + 1);
		dfs(root, -1, 0);
		rep(k, MAX_LOG_V - 1)
		{
			for (LL v = 1; v <= V; ++v)
			{
				if (parent[k][v] < 0) parent[k + 1][v] = -1;
				else parent[k + 1][v] = parent[k][parent[k][v]];
			}
		}
	}

	// uとvのLCAを求める
	LL lca(LL u, LL v)
	{
		if (depth[u] > depth[v]) std::swap(u, v);
		rep(k, MAX_LOG_V)
		{
			if ((depth[v] - depth[u]) >> k & 1) v = parent[k][v];
		}
		if (u == v) return u;
		for (LL k = MAX_LOG_V - 1; k >= 0; --k)
		{
			if (parent[k][u] != parent[k][v])
			{
				u = parent[k][u];
				v = parent[k][v];
			}
		}
		return parent[0][u];
	}

	LL dist(LL u, LL v)
	{
		LL t = lca(u, v);
		return depth[u] + depth[v] - 2 * depth[t];
	}
};

int main()
{
	LL N, u, v;
	in >> N >> u >> v;
	std::vector<LL>A(N - 1), B(N - 1);
	rep(i, N - 1) in >> A[i] >> B[i];

	std::vector<LL>leaves;
	G.resize(N + 1);
	rep(i, N - 1)
	{
		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	}
	for (LL i = 1; i <= N; ++i)
	{
		if (G[i].size() == 1) leaves.push_back(i);
	}

	LL ans = 0;
	LCA tree;
	tree.init(N);
	for (LL t : leaves)
	{
		LL dist_u = tree.dist(t, u);
		LL dist_v = tree.dist(t, v);
		if (dist_u >= dist_v)
		{
			LL dist_uv = tree.dist(u, v);
			ans = std::max(ans, dist_uv / 2);
		}
		else
		{
			ans = std::max(ans, dist_u + (dist_v - dist_u) / 2);
		}
	}

	out << ans << std::endl;
}

