void turn(std::vector<int>& tree, int root)
{
    if (root != tree[0]) {
        turn(tree, tree[root]);
    }
    int prevRoot = tree[0];
    tree[0] = tree[prevRoot] = root;
    tree[root] = -1;
}

void depth(const std::vector<int>& tree, std::vector<int>& d, int node)
{
    if (d[node] != -1) return;
    if (node == tree[0]) {
        d[node] = 0;
        return;
    }
    if (d[tree[node]] == -1) {
        depth(tree, d, tree[node]);
    }
    d[node] = d[tree[node]] + 1;
}

void prog()
{
    input in;
    output out;
    int n, u, v;
    in >> n, u, v;
    std::vector<int> tree(n + 1, -1);
    tree[0] = 1;
    for (int i : boost::irange(0, n - 1)) {
        int a, b;
        in >> a, b;
        if (a > b) std::swap(a, b);
        tree[b] = a;
    }
    std::vector<int> ud(n + 1, -1), vd(n + 1, -1);
    turn(tree, u);
    if (std::count(std::begin(tree), std::end(tree), u) == 1) {
        out, 0;
        return;
    }
    for (int i : boost::irange(1, n + 1)) {
        depth(tree, ud, i);
    }
    turn(tree, v);
    for (int i : boost::irange(1, n + 1)) {
        depth(tree, vd, i);
    }
    int res = -1;
    for (int i : boost::irange(1, n + 1)) {
        if (ud[i] < vd[i]) {
            res = std::max(res, vd[i]);
        }
    }
    out, res - 1;
}

int main()
{
    prog();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

vector<int> G[100005];
int parent[100005];
vector<int> childs[100005];
int jump[20][100005];
int depth[100005];

void dfs0(int u, int p = 0) {
  parent[u] = p;
  if (p == 0)
    depth[u] = 0;
  else
    depth[u] = depth[p] + 1;
  for (int h : G[u])
    if (h != p) {
      childs[u].push_back(h);
      dfs0(h, u);
    }
}

int up(int u, int d) {
  for (int i = 19; i >= 0; i--)
    if (d & (1 << i))
      u = jump[i][u];
  return u;
}

int down(int u, int ref, int d) { return up(ref, depth[ref] - depth[u] - d); }

int lca(int u, int v) {
  if (depth[u] > depth[v])
    swap(u, v);
  v = up(v, depth[v] - depth[u]);
  if (u == v)
    return u;
  for (int i = 19; i >= 0; i--)
    if (jump[i][u] != jump[i][v])
      u = jump[i][u], v = jump[i][v];
  return parent[u];
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);

  int n, a, b;
  cin >> n >> b >> a;
  for (int i = 0; i < n - 1; i++) {
    int u, v;
    cin >> u >> v;
    G[u].push_back(v);
    G[v].push_back(u);
  }

  dfs0(a);

  for (int i = 1; i <= n; i++)
    jump[0][i] = parent[i];
  for (int j = 1; j < 20; j++)
    for (int i = 1; i <= n; i++)
      jump[j][i] = jump[j - 1][jump[j - 1][i]];

  // for (int i = 1; i <= n; i++) {
  //   printf("%d Depth %d\n", i, depth[i]);
  // }

  int ans = max(0, depth[b] - depth[a] - 1);

  for (int i = 1; i <= n; i++)
    if (i != a && i != b) {
      int an = lca(i, b);

      int mva = 0, mvb = 0;
      int pa = a, pb = b;

      // printf("%d Ancestor %d\n", i, an);

      if (depth[b] - depth[an] < depth[an] - depth[a]) {
        // goto an first
        mva += depth[b] - depth[an];
        mvb += depth[b] - depth[an];
        pb = an;
        pa = down(pa, pb, depth[b] - depth[an]);
        // goto i then
        mvb += depth[i] - depth[an];
        mva += depth[i] - depth[an];
        pb = i;
        pa = down(pa, pb, depth[i] - depth[an]);
        mva += depth[pb] - depth[pa] - 1;
        ans = max(ans, mva);
      } else {
        continue;
      }
    }

  cout << ans << endl;
}

