const int MAXN = 1e5 + 5;

vector<ll>adj[MAXN];
ll p[MAXN][22], parent[MAXN], level[MAXN], n, u, v, a, b, res;

void precom()                                        // for calculating 2^k th parent of every node
{
	for(int i = 0 ; i < n ; i++)
		for(int j = 0 ; (1ll << j) < n ; j++)
			p[i][j] = -1;
	for(int i = 0 ; i < n ; i++)
		p[i][0] = parent[i];
	for(int j = 1 ; (1ll << j) < n ; j++)
		for(int i = 0 ; i < n ; i++)
			if(p[i][j - 1] != -1)
				p[i][j] = p[p[i][j - 1]][j - 1];
}

ll lca(ll u, ll v)
{
	if(min(level[u], level[v]) == level[u]) swap(u, v);
	ll dist = level[u] - level[v];
	while(dist)
	{
		ll raise = log2(dist);
		u = p[u][raise];
		dist -= (1ll<<raise);
	}
	if(u == v) return u;
	for(int j = 22 ; j >= 0 ; j--)
	{
		if(p[u][j] != -1 && p[u][j] != p[v][j])
		{
			u = p[u][j];
			v = p[v][j];
		}
	}
	return parent[u];
}

void dfs(ll node, ll par, ll lev)                              // dfs to set parent and calculate levels
{
	level[node] = lev;
	for(auto it : adj[node])
	{
		if(it == par) continue;
		parent[it] = node;
		dfs(it, node, lev + 1);
	}		
}

ll dist(ll x, ll y)
{
	return level[x] + level[y] - 2 * level[lca(x, y)];
}

void dfs1(ll node, ll par)
{
	for(auto it : adj[node])
	{
		if(it == par) continue;
		dfs1(it, node);
	}
	ll x1 = dist(u, node);
	ll x2 = dist(v, node);
	if(x1 < x2) res = max(res, x2 - 1);	
}

