inline void dkstr(vector<vector<pair<int,U>>>& v,int n,int s,vector<U>& d,U inf){
    d.assign(n,inf);
    d[s]=0;
    queue<pair<U,int>> pq;
    pq.emplace(0,s);
    while(!pq.empty()){
        pair<U,int> p=pq.front();pq.pop();
        U D=p.first;
        int i=p.second;
        if(d[i]<D) continue;
        for(auto q:v[i]){
            if(d[q.first]<=D+q.second) continue;
            d[q.first]=D+q.second;
            pq.emplace(D+q.second,q.first);
        }
    }
}

