int N, takahashi, aoki;
vector<bool> used(1000000);
vector<bool> used2(1000000);
vector<int> route;
bool correctPath = false;
int halfSize;
int Max = 0;

void searchPath(int t, vector<vector<int>> &ki){
  if(t == takahashi){
    correctPath = true;
    return;
  }
  for(int i = 0; i < ki.at(t).size(); i++){
    int to = ki.at(t).at(i);
    if(used.at(to)){
      continue;
    }
    used.at(to) = true;
    searchPath(to, ki);
    if(correctPath){
      route.push_back(to);
      return;
    }
  }
  return;
}

void longestPath(int t, vector<vector<int>> &ki, int steps){
  if(steps > Max){
    Max = steps;
  }
  for(int i = 0; i < ki.at(t).size(); i++){
    int to = ki.at(t).at(i);
    if(used2.at(to)){
      continue;
    }
    used2.at(to) = true;
    longestPath(to, ki, steps + 1);
  }
  return;
}

void solve() {
  cin >> N >> takahashi >> aoki;
  takahashi--;
  aoki--;
  vector<vector<int>> ki(N);
  for(int i = 0; i < N-1; i++){
    int a, b;
    cin >> a >> b;
    ki.at(a-1).push_back(b-1);
    ki.at(b-1).push_back(a-1);
  }
  /*
  for(int i = 0; i < N; i++){
    cout << i << ":";
    for(int j = 0; j < ki.at(i).size(); j++){
      cout << ki.at(i).at(j) << " ";
    }
    cout << endl;
  } */
  searchPath(aoki, ki);
  route.push_back(aoki);
  int rs=route.size();
  halfSize = rs / 2+!!(rs%2);//round up
  used2.at(route.at(halfSize)) = true;
  used2.at(route.at(halfSize-1)) = true;
  longestPath(route.at(halfSize-1), ki, 0);
  int Path = rs - halfSize - 1 + Max;
  if(rs % 2 == 1){
	cout << Path - 2 <<endl;
  } else{
  cout << Path <<endl;
  }
}
