    par[curr.first] = curr.second;
    for(int i = 0; i < adj[curr.first].size(); i++){
      q.push({adj[curr.first][i], curr.first});
    }
  }
  vector<int> dU (N, -1), commonAncestor (N, -1);
  q = queue<pi> (); q.push({U, 0});
  while(!q.empty()){
    pi curr = q.front(); q.pop();
    if(dU[curr.first] != -1) continue;
    dU[curr.first] = curr.second;
    for(int i = 0; i < adj[curr.first].size(); i++){
      q.push({adj[curr.first][i], curr.second + 1});
    }
  }
