  while(!q.empty()){
    pi curr = q.front(); q.pop();
    if(commonAncestor[curr.first] != -1) continue;
    commonAncestor[curr.first] = curr.second;
    for(int i = 0; i < adj[curr.first].size(); i++){
      q.push({adj[curr.first][i], adj[curr.first][i] == par[curr.first] ? adj[curr.first][i] : curr.second});
