		dfs_a(u, turn, graph, aoki);
}

void dfs_t(int v, int turn, const vector<vector<int>>& graph, const vector<int>& aoki, vector<int>& taka) {
	if (taka[v] >= 0 || aoki[v] <= turn) return;
	taka[v] = turn++;
	for (auto u : graph[v])
		dfs_t(u, turn, graph, aoki, taka);
}

