void dfs(const vector<vector<int64_t>>& adjs, int64_t current,
         vector<int64_t>& parent, vector<int64_t>& depth,
         vector<int64_t>& max_depth) {
    for (auto v : adjs[current]) {
        if (v == parent[current]) {
            continue;
        }

        depth[v] = depth[current] + 1;
        max_depth[v] = depth[current] + 1;
        parent[v] = current;
        dfs(adjs, v, parent, depth, max_depth);
        max_depth[current] = max(max_depth[current], max_depth[v]);
    }
}

int main() {
    int64_t n, u, v;
    cin >> n >> u >> v;
    --u;
    --v;

    vector<vector<int64_t>> adjs(n);
    for (auto i : irange(0L, n - 1)) {
        int64_t a, b;
        cin >> a >> b;
        --a;
        --b;
        adjs[a].push_back(b);
        adjs[b].push_back(a);
    }

    vector<int64_t> parent(n, -1), depth(n), max_depth(n);
    dfs(adjs, v, parent, depth, max_depth);
    int64_t u_depth = depth[u];
    int64_t m = max_depth[u];
    while (parent[u] >= 0) {
        u = parent[u];
        if (2 * depth[u] <= u_depth) {
            break;
        }

        m = max(m, max_depth[u]);
    }

    cout << m - 1 << endl;
}

#include <bits/stdc++.h>
using namespace std;

class lca {
	public:
		int n, logn;
		vector<vector<int>> parent;
		vector<int> depth;
		lca(vector<vector<int>> &tree, int rt = 0) {
			n = (int)tree.size(), logn = log2(n) + 1;
			parent.resize(n, vector<int>(logn));
			depth.resize(n);
			function<void(int, int, int)> dfs = [&](int u, int p, int d) {
				parent[u][0] = p;
				depth[u] = d;
				for (int v : tree[u]) {
					if (v == p) continue;
					dfs(v, u, d + 1);
				}
			};
			dfs(rt, -1, 0);
			for (int k = 0; k + 1 < logn; k++) {
				for (int u = 0; u < n; u++) {
					if (parent[u][k] < 0) {
						parent[u][k + 1] = -1;
					} else {
						parent[u][k + 1] = parent[parent[u][k]][k];
					}
				}
			}
		}
		int get(int u, int v) {
			if (depth[u] > depth[v]) swap(u, v);
			for (int k = 0; k < logn; k++) {
				if ((depth[v] - depth[u]) >> k & 1) {
					v = parent[v][k];
				}
			}
			if (u == v) return u;
			for (int k = logn - 1; k >= 0; k--) {
				if (parent[u][k] != parent[v][k]) {
					u = parent[u][k];
					v = parent[v][k];
				}
			}
			return parent[u][0];
		}
		int log2(int b) {
			return 31 - __builtin_clz(b);
		}
};
int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	int n, s, t;
	cin >> n >> s >> t;
	s--; t--;
	vector< vector<int> > tree(n);
	for (int i = 1; i < n; i++) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}
	vector<int> depth(n);
	int max_depth = -1, rt = -1;
	function<void(int, int, int)> dfs = [&](int u, int d, int p) {
		depth[u] = d;
		for (int v : tree[u]) {
			if (v == p) continue;
			dfs(v, d + 1, u);
			if (v == t) continue;
			if (depth[v] > max_depth) {
				max_depth = depth[v];
				rt = v;
			}
		}
	};
	dfs(s, 0, -1);
	if (rt == -1) {
		cout << "0\n";
		return 0;
	}
	lca lc(tree, rt);
	int p = lc.get(s, t);
	if (lc.depth[s] >= lc.depth[t]) {
		max_depth = -1;
		dfs(rt, 0, -1);
		cout << max_depth + lc.depth[t] - 2 * lc.depth[p] - 1 << '\n';
	} else {
		cout << lc.depth[t] - 1 << '\n';
	}
	return 0;
}

