void dfs(ll idx, ll from = -1, ll pathSize = 0){

    seen[idx] = true;

    if(idx == prohibitedArea){
        return;
    }

    if(mx.first < pathSize){
        mx.first = pathSize;
        mx.second = idx;
    }

    for(ll i = 0; i < dfsG[idx].size(); i++){
        //次の行き先は？
        ll to = dfsG[idx][i].first;
        //探査済み
        if(seen[to] == true){
            continue;
        }
        dfs(to , idx, pathSize + 1);
    }

    return;
}

