        init(v);
        dfs(v);
        d[u] = max(d[u], d[v]);
        if (d[v] > d[ch[u]]) ch2[u] = ch[u], ch[u] = v;
        else if (d[v] > d[ch2[u]]) ch2[u] = v;
    }
    d[u]++;
}

int lca(int u, int v){
    if (h[u] < h[v]) swap(u, v);
    for (int i = lg[u]; i >= 0; i--)
    if (h[u] - (1 << i) >= h[v]){
        u = p[i][u];
    }
    if (u == v) return u;
    for (int i = lg[u]; i >= 0; i--)
    if (p[i][u] != p[i][v]){
        u = p[i][u];
        v = p[i][v];
    }
    return p[0][u];
}

