            if (du[j] > dv[j]) continue;
            chmax(dist[j], dist[i] + 1);
            if (du[j] == dv[j]) continue;
            que.push(j);
        }
    }

    int ans = *max_element(dist.begin(), dist.end());
    cout << ans << endl;

    return 0;
}

