  --u; --v;

  BFS<int> bfs_t(n);
  BFS<int> bfs_a(n);

  for (int i = 0; i < n - 1; ++i) {
    int a, b; fastin(a); fastin(b);
    --a; --b;
    bfs_a.AddEdge(a, b);
    bfs_a.AddEdge(b, a);
    bfs_t.AddEdge(a, b);
    bfs_t.AddEdge(b, a);
  }

  bfs_t.Solve(u);
  bfs_a.Solve(v);

  int mx = -1;
  int ans = 0;

  for (int i = 0; i < n; ++i) {
    if (bfs_t[i] < bfs_a[i] && bfs_a[i] > mx) {
      mx = bfs_a[i];
      ans = bfs_a[i] - 1;
    }
  }

  printf("%d\n", ans);

  return 0;
}

