#include <bits/stdc++.h>
using namespace std;
using lint = long long int;

struct Vertex {
    vector<lint> edge;
    bool visited = false;
    lint distT = 0;
    lint distA = 0;
};

int main() {
    lint n, u, v;
    cin >> n >> u >> v;
    u--, v--;

    vector<Vertex> g(n);
    for(lint i=0; i<n-1; i++) {
        lint a, b;
        cin >> a >> b;
        a--, b--;
        g[a].edge.push_back(b);
        g[b].edge.push_back(a);
    }

    // 高橋くんからの距離
    queue<lint> queT;
    queT.push(u);
    g[u].distT = 0;
    g[u].visited = true;

    while(!queT.empty()) {
        lint node = queT.front(); queT.pop();
        for(auto next : g[node].edge) {
            if(g[next].visited)  continue;
            g[next].visited = true;
            g[next].distT = g[node].distT + 1;
            queT.push(next);
        }
    }

    // 初期化処理を書く
    for(auto &e : g)  e.visited = false;

    // 青木くんからの距離
    queue<lint> queA;
    queA.push(v);
    g[v].distA = 0;
    g[v].visited = true;

    while(!queA.empty()) {
        lint node = queA.front(); queA.pop();

        for(auto next : g[node].edge) {
            if(g[next].visited)  continue;
            g[next].visited = true;
            g[next].distA = g[node].distA + 1;
            queA.push(next);
        }
    }

    // 高橋くんからの距離 < 青木くんからの距離　かつ　青木くんからの距離が最大
    lint ans = -1;
    for(auto e : g) {
        if(e.distT >= e.distA)  continue;
        ans = max(ans, e.distA);
    }

    cout << --ans << endl;
}

