const LLONG MOD = 1000000007;

int main()
{
    int N, u, v; cin >> N >> u >> v; --u; --v;
    vector<vector<int>> adList(N);
    for (int i = 0; i < N - 1; ++i)
    {
        int v1, v2; cin >> v1 >> v2; --v1; --v2;
        adList[v1].push_back(v2);
        adList[v2].push_back(v1);
    }
    // 青木君の開始位置から各頂点までの距離を計算
    const int INF = 1e6;
    vector<int> aDists(N, INF);
    aDists[v] = 0;
    deque<int> Q{ v };
    while (!Q.empty())
    {
        int t = Q.front(); Q.pop_front();
        for (const int n : adList[t])
        {
            if (aDists[n] > aDists[t] + 1)
            {
                Q.push_back(n);
                aDists[n] = aDists[t] + 1;
            }
        }
    }
    // 高橋君について，青木君より先に到達可能な頂点のうち
    // 最も遠くにある頂点を探す
    vector<int> tDists(N, INF);
    vector<bool> movableFlags(N, false);
    tDists[u] = 0;
    movableFlags[u] = true;
    Q.push_back(u);
    while (!Q.empty())
    {
        int t = Q.front(); Q.pop_front();
        for (const int n : adList[t])
        {
            int dist = tDists[t] + 1;
            // 高橋君の方が先に動くので，等距離の点にも移動できる
            if (tDists[n] > dist && aDists[n] >= dist)
            {
                Q.push_back(n);
                tDists[n] = dist;
                movableFlags[n] = true;
            }
        }
    }
    int ans = -1;
    for (int i = 0; i < N; ++i)
    {
        // 高橋君が移動可能な頂点のうち青木君から見て最も遠い頂点をｘとすると
        // ｘは袋小路であり，その一歩手前のｘで高橋君を捕まえることができる
        if (movableFlags[i])
        {
            ans = max(ans, aDists[i] - 1);
        }
    }
    cout << ans << endl;
}

