void visit(int node, int L) {
    if (visited[node] == 1) {
        return;
    }

    dist[node] = L;
    visited[node] = 1;

    for(int i = 0; i < edges[node].size(); i++) {
        visit(edges[node][i], L + 1);
    }
}


