//Solve N^M. This, mod_pow use Iterative Square Method.
long long mod_pow(long long N, long long M) {
    if (M == 0) return 1;
    long long res = mod_pow((N * N) % MOD, M / 2);
    //最下位ビット(*N)が1の時は単独でNをかける
    if (M & 1) res = (res * N) % MOD;

    return res %= MOD;
}

int gcd(long long a, long long b) {
    if (b == 0) return a;
    else return gcd(b, a % b);
}
long long lcm(long long a, long long b) {
    return a / gcd(a, b) * b ;
}

vector<vector<int>> Edge(100005);
vector<int> dist_takahashi(100005,100100);
vector<int> dist_aoki(100005,100100);
vector<bool> seen(100005);

void dfs_takahashi(int from,int dist){
    seen.at(from) = true;
    dist_takahashi.at(from) = dist;
    for(int V : Edge.at(from)){
        if(seen.at(V)) continue;
        dfs_takahashi(V,dist+1);
    }
}
void dfs_aoki(int from,int dist){
    seen.at(from) = true;
    dist_aoki.at(from) = dist;
    for(int V : Edge.at(from)){
        if(seen.at(V)) continue;
        dfs_aoki(V,dist+1);
    }
}
int ans = 0;
void tag_game(int from,int maxidist){
    seen.at(from) = true;
    ans = max(ans,maxidist);
    if(dist_takahashi.at(from) >= dist_aoki.at(from)){
        return;
    }
    for(int V : Edge.at(from)){
        if(seen.at(V)) continue;
        tag_game(V,maxidist+1);
    }
}

int main() {
