struct node{
	int val,vertex;
	node()
	{
		val=0;vertex=-1;
	}
	node(int v1,int v2)
	{
		val=v1;
		vertex=v2;
	}
};

int timer=0,n,lim;
node data[100011][2]={};
vector< int > graph[100011];
int times[100011][2]={};
int anc[100011][20]={};
int depth[100011]={};
int dp[100011]={};
int dfs(int u,int pa,int d=0)
{
	timer++;
	anc[u][0]=pa;
	depth[u]=d;
	times[u][0]=timer;
	data[u][0]={0,u};
	data[u][1]={0,-1};
	for(auto v:graph[u])
		if(v!=pa){
			int r=dfs(v,u,d+1);
			node temp={1+r,v};
			if(temp.val>=data[u][0].val){
				swap(data[u][0],data[u][1]);
				data[u][0]=temp;
			}
			else if(temp.val>=data[u][1].val)
				data[u][1]=temp;
		}
	times[u][1]=timer;
	return data[u][0].val;
}

void dfs2(int u,node tmp){
	dp[u]=((tmp.vertex>0)?tmp.val:0);
	tmp.val+=1;
	node tmp2=tmp;

	if(tmp.val<=(data[u][1].val+1))
		tmp={data[u][1].val+1,u};

	if(tmp2.val<=(data[u][0].val+1))
		tmp2={data[u][0].val+1,u};	

	for(int v:graph[u])
		if(v!=anc[u][0])
			dfs2(v,((data[u][0].vertex!=v)?tmp2:tmp));
}

bool is_anc(int u,int v){
	return (!u)||(times[u][0]<=times[v][0] && times[u][1]>=times[v][1]);
}

int lca(int v1,int v2)
{
	int k=1+lim,v;
	while(k--){
		v=anc[v1][k];
		if(!is_anc(v,v2))
			v1=v;
	}
	return (!is_anc(v1,v2))?(anc[v1][0]):v1;
}

int up(int u,int d)
{
	int i=0;
	while(d)
	{
		if(d&1) u=anc[u][i];
		d>>=1; i++;
	}
	return u;
}

void pre_lca()
{
	int i,j; anc[0][0]=0;
	for(i=1;i<=lim;i++)
		for(j=0;j<=n;j++)
			anc[j][i]=anc[anc[j][i-1]][i-1];
}

int main()
{
	ios_base::sync_with_stdio(false);cin.tie(0);cout.tie(0);
	int T,i,u,v,x,y;

		cin>>n>>y>>x;
		lim=ceil(log2(n));
		timer=0;

		for(i=0;i<=n;i++)
			graph[i].clear();

		for(i=1;i<n;i++)
		{
			cin>>u>>v;
			graph[u].push_back(v);
			graph[v].push_back(u);
		}

		dfs(1,0,1);

		pre_lca();
		node tmp;

		dfs2(1,tmp);

		u=lca(x,y); int l=depth[x]+depth[y]-2*depth[u];
		if(depth[x]<=depth[y])
			cout<<(((x==y)?0:((l-((l-1)/2))+data[up(y,(l-1)/2)][0].val))-1)<<endl;
		else{
			u=up(x,l-(l-1)/2);
			cout<<((l-((l-1)/2)+max(dp[u],data[u][is_anc(data[u][0].vertex,x)].val))-1)<<endl;
		}

}

