#include <bits/stdc++.h>

using namespace std;

const int maxn = 1e5 + 10, maxl = 20;
int sp[maxn][maxl], h[maxn], ans, s, e, n;
int tin[maxn], tout[maxn], timer;
vector<int> adj[maxn];

void dfs(int u, int par, int hei = 0)
{
    h[u] = hei;
    sp[u][0] = par;
    for (int i = 1; i < maxl; i++)
        sp[u][i] = sp[sp[u][i - 1]][i - 1];

    tin[u] = timer++;

    for (int v : adj[u])
        if (v != par)
            dfs(v, u, hei + 1);

    tout[u] = timer++;
}

bool is_anc(int u, int v)
{
    return tin[u] <= tin[v] && tout[u] <= tout[v];
}

int lca(int u, int v)
{
    if (is_anc(u, v))
        return u;
    if (is_anc(v, u))
        return v;

    for (int i = maxl - 1; ~i; i--)
        if (!is_anc(sp[u][i], v))
            u = sp[u][i];

    return sp[u][0];
}

int dis(int u, int v)
{
    return h[u] + h[v] - 2 * h[lca(u, v)];
}

void find_ans(int u, int par)
{
    ans = max(ans, h[u] - 1);

    for (int v : adj[u])
        if (v != par)
            find_ans(v, u);
}

int main()
{
    ios::sync_with_stdio(false);
    cin >> n >> s >> e;

    for (int i = 0, u, v; i < n - 1; i++)
        cin >> u >> v, adj[u].push_back(v), adj[v].push_back(u);
    dfs(e, e);

    int d = dis(s, e), lc = s;
    d /= 2;
    while (d--)
        lc = sp[lc][0];
    find_ans(lc, sp[lc][0]);

    cout << ans;

    return 0;
}

