	priority_queue<P, vector<P>, greater<P> > que;
	fill(d3, d3 + MAX_V, INF);
	d3[s] = 0;
	que.push(P(0, s));
	while (!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.second;
		if (d3[v] < p.first) continue;
		for (int i = 0; i < g[v].size(); i++) {
