// 根付き木の各頂点の親, 深さ, 高さを求める
int root;
#define MAX_N 200001
vector<int> graph[MAX_N];
int par[MAX_N], depth[MAX_N], height[MAX_N]; // 0で初期化
void tree_init(int r){
    root = r;
    par[root] = -1;
    stack<int> st_op, st_cl;
    st_op.push(root);
    while (! st_op.empty()) {
        int t = st_op.top(); st_op.pop();
        st_cl.push(t);
        for (int x: graph[t]) {
            if (x == par[t]) continue;
            depth[x] = depth[t] + 1;
            par[x] = t;
            st_op.push(x);
        }
    }
    while (! st_cl.empty()) {
        int t = st_cl.top(); st_cl.pop();
        for (int x: graph[t]) {
            if (x == par[t]) continue;
            height[t] = max(height[t], height[x] + 1);
        }
    }
}

int main() {
    int N, u, v;
    cin >> N >> u >> v;
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    tree_init(v);
    int cnt = (depth[u] - 1) / 2;
    for (int i = 0; i < cnt; ++i) {
        u = par[u];
    }
    // 鬼は必ず高さ1の頂点で捕まえる
    int ans = depth[u] + height[u] - 1;
    cout << ans << "\n";
    return 0;
}

