	mxd[x]=dep[x];
	for(re int i=head[x];i;i=e[i].next){
		if(e[i].to!=y&&e[i].to!=son[x]){
			dfs1(e[i].to,x);
			mxd[x]=max(mxd[x],mxd[e[i].to]);
		}
	}
	if(son[x])dfs1(son[x],x);
}
