					ta.push(tree[c][0]);
					se.insert(tree[c][0]);
				}
				continue;
			}
			rep(j, tree[c].size()) {
				if (!ao_flag[tree[c][j]] && !ta_flag[tree[c][j]]&&!se.count(tree[c][j])) {
					ta.push(tree[c][j]);
					se.insert(tree[c][j]);
				}
			}
			ta_flag[c] = 1;
		}
		if (ta.size()==0) {
			cout << ans-1 << endl;
			return 0;
		}
		ans++;
		int b = ao.size();
		rep(i, b) {
			int c = ao.front();
			ao.pop();
			ao_flag[c] = 1;
			rep(j, tree[c].size()) {
				if (!ao_flag[tree[c][j]]) ao.push(tree[c][j]);
			}
		}
	}
