  rep(i,n-1){
    cin >> a[i] >> b[i];
    a[i]--; b[i]--;
    g.add_edge(a[i],b[i],1);
    g.add_edge(b[i],a[i],1);
    f.add_edge(a[i],b[i],1);
    f.add_edge(b[i],a[i],1);
  }

  g.dijkstra(u-1);
  f.dijkstra(v-1);
  if(g.G[u-1].size() == 1){
    for(auto x: g.G[v-1]){
      if(g.G[u-1][0].to == x.to){
        cout << 1 << endl;
        return 0;
      }
    }
  }
  ll ans = 0;
  rep(i,n){
    if(g.d[i] < f.d[i]){
      ans = max(ans,f.d[i]-1);
    }else if(g.d[i] > f.d[i]){
      ans = max(ans,g.d[i] - f.d[i]-1);
    }else{
      ans = max(ans,2*g.d[i]-1);
    }
  }
