struct UnionFind
{
	UnionFind(int n) : p(n, -1) {}
	int root(int u)
	{
		return p[u] < 0 ? u : p[u] = root(p[u]);
	}
	int size(int u)
	{
		return -p[root(u)];
	}
	bool same(int u, int v)
	{
		return root(u) == root(v);
	}
	void unite(int u, int v)
	{
		p[u] = v;
	}
	vector<int> p;
};

int main()
{
	cout << fixed << setprecision(10);
	int n, u, v;
	cin >> n >> u >> v;
	u--;
	v--;

	vector<vector<int>> connect(n);
	UnionFind tree(n);

	REP(i, n - 1)
	{
		int x, y;
		cin >> x >> y;
		x--;
		y--;
		connect[x].push_back(y);
		connect[y].push_back(x);
	}

	vector<int> dist(n, INF);

	queue<int> q;
	q.push(v);
	dist[v] = 0;
	while (q.size())
	{
		int pos = q.front();
		q.pop();

		for (auto& next : connect[pos])
		{
			if (dist[pos] + 1 < dist[next])
			{
				dist[next] = dist[pos] + 1;
				tree.unite(next, pos);
				q.push(next);
			}
		}

	}

	int parm = u;
	REP(i, (dist[u] - 1) / 2)
	{
		parm = tree.p[parm];
	}
	tree.p[parm] = -1;

	int len = 0;
	REP(i, n)
	{
		if (tree.same(i, u))
		{
			chmax(len, dist[i]);
		}
	}

	cout << (dist[parm] - 1) / 2 + (len - (dist[parm] + 1) / 2);

	return 0;
}

#include <bits/stdc++.h>
#define inf (long long)1e9
using namespace std;

long long n, u, v;
vector<long long> edge[100005];
vector<long long> disu, disv;
queue<long long> qu;

long long solve();

int main() {
  cin >> n >> u >> v;
  --u, --v;
  for(int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    edge[--a].push_back(--b);
    edge[b].push_back(a);
  }
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long res = 0, id = u;
  disv.assign(n, inf);
  disv[v] = 0;
  qu.push(v);
  while(!qu.empty()) {
    long long now = qu.front();
    qu.pop();
    for(long long nextp : edge[now])
      if(disv[nextp] > disv[now] + 1) {
        disv[nextp] = disv[now] + 1;
        qu.push(nextp);
      }
  }
  disu.assign(n, inf);
  disu[u] = 0;
  qu.push(u);
  while(!qu.empty()) {
    long long now = qu.front();
    qu.pop();
    for(long long nextp : edge[now])
      if(disu[nextp] > disu[now] + 1 &&
         disu[now] + 1 < disv[nextp]) {
        disu[nextp] = disu[now] + 1;
        qu.push(nextp);
        id = nextp;
      }
  }
  res = disu[id];
  res += (disv[id] - disu[id]) / 2;
  return res;
}

#include <iostream>
#include <algorithm>
#include <vector>
#include <queue>
#include <string>

using ll = long long;

using namespace std;
#define MAX_N 100010

using P = pair<int, int>;
#define fi first
#define se second

int n, taka, aoki;
vector<P> G[100010];

// 各点への最短経路 dijkstra
int ad[MAX_N], td[MAX_N];  //頂点kから各点への距離
void dijkstra(int k, int *d) { //Gは隣接行列 G[i][j].firstが距離, secondが向かう頂点名, kはスタートする頂点
    fill(d, d+n, MAX_N); d[k] = 0;
    priority_queue< P, vector<P>, greater<P> > que;
    que.push(P(0, k));
    while (!que.empty()) {
        P p = que.top(); que.pop();
        int now = p.second;
        if (d[now] < p.first) continue;
        for (auto g:G[now]) {
            int to = g.second;
            long newd = g.first + d[now];
            if (d[to] > newd) {
                d[to] = newd;
                que.push(P(d[to], to));
            }
        }
    }
}

bool under[MAX_N] = {0}, visited[MAX_N] = {0};

void dfs(int tr, int i=aoki) {
    visited[i] = true;
    if (i == tr) under[i] = true;
    for (auto &g:G[i]) {
        if (visited[g.se]) continue;
        if (under[i]) under[g.se] = true;
        dfs(tr, g.se);
    }
}


int main() {
    cin >> n >> taka >> aoki;
    taka--; aoki--;
    for (int i=0, a, b; i<n-1; i++) {
        cin >> a >> b;
        a--; b--;
        G[a].push_back({1, b});
        G[b].push_back({1, a});
    }
    dijkstra(aoki, ad);
    dijkstra(taka, td);
    int ans = 0, tr = -1;
    for (int i=0; i<n; i++) {
        if (td[i] + ad[i] == ad[taka] && ad[i] == (ad[taka] + 2) / 2) {
            tr = i;
            break;
        }
    }
    cerr << tr << '\n';
    dfs(tr);
    for (int i=0; i<n; i++) {
        cerr << i << ' ' << under[i] << ' ' << ad[i] << '\n';
        if (under[i]) ans = max(ans, ad[i]);
    }
    cout << ans - 1 << '\n';
    return 0;
}

