class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N, u, v;
    vector<vector<int>> edge;

    vector<int> parent;

    bool input() {
        N = 0;
        is >> N >> u >> v;
        u--; v--;
        edge.resize(N);
        for (int i = 0; i < N-1; ++i) {
            int a, b;
            is >> a >> b;
            a--; b--;
            edge[a].push_back(b);
            edge[b].push_back(a);
        } // end i
        return !!is;
    }

    void make_tree(int now, int par = -1){
        parent[now] = par;
        for (auto &&child : edge[now]) {
            if(child == par) continue;
            make_tree(child, now);
        } // end child
    }

    int calc(int u, int v) const {
        if(u == v) return 0;
        int m = 0;
        for (auto &&ne : edge[u]) {
            if(ne == v) continue;
            UPMAX(m, calc(ne, u)+1);
        } // end ne

        return m;
    }

    int d(int p, int c){
        if(p == c) return 0;
        return d(p, parent[c]) + 1;
    }

    void run();
};

