void solver::run(){
    if(!input()) return;
    parent.resize(N);
    make_tree(v);
    int dd = d(v, u)-1;
    int count = dd/2;
    for (int i = 0; i < dd/2; ++i) { u = parent[u]; } // end i
    if(dd % 2) count++;
    v = parent[u];
    count += calc(u, v);
    os << count << endl;
}

