int takahashi(int tak, int aok, int prvtak = -1) {
    if (tak == aok) return 0;
    int ret = 0;
    for (auto& nxt: graph[tak]) {
        if (nxt == prvtak) continue;
        chmax(ret, aoki(nxt, aok, tak));
    }
    return ret;
}

int dist(int a, int b) {
    int lca = hld.lca(a, b);
    // debug(hld.dep[a], hld.dep[b], hld.dep[lca]);
    return hld.dep[a] + hld.dep[b] - 2 * hld.dep[lca];
}

int aoki(int tak, int aok, int prvtak = -1) {
    if (tak == aok) return 0;
    int cur = dist(tak, aok);
    for (auto& nxt: graph[aok]) {
        debug(tak, nxt, dist(tak, nxt));
        if (cur > dist(tak, nxt)) {
            return takahashi(tak, nxt) + 1;
        }
    }
    debug(tak, aok);
    assert(0);
}

