	}
}

void build(){
	parent[y][0]=y;
	for(int i=1; i<Log; i++){
		for(int j=0; j<n; j++){
			parent[j][i]=parent[parent[j][i-1]][i-1];
		}
	}
}

int digni(int a, int b){
	int raz=dep[b]-dep[a];
	for(int i=Log-1; i>-1; i--){
		if(raz&(1<<i)){
			b=parent[b][i];
		}
	}
	return b;
}

int siri(int y){
	int poc=y;
	while(true){
//		cout << "to infinity" << endl;
//		cout << y << endl;
		for(int i=0; i<ms[y].size(); i++){
			if(dep[ms[y][i]]>dep[y] && digni(ms[y][i], x)==ms[y][i]){
				y=ms[y][i];
				break;
			}
		}
		if(dep[y]-dep[poc]>dep[x]-dep[y]){
			return y;
		}
	}
}

pair < int, int > naj(int x){
	pair < int, int > p;
	pair < int, int > sol=make_pair(dep[x], x);
	for(int i=0; i<ms[x].size(); i++){
		if(dep[ms[x][i]]>dep[x]){
			p=naj(ms[x][i]);
			if(p.first>sol.first){
				sol=p;
			}
		}
	}
	return sol;
}

