map<POS, COST> dijkstra(GRAPH& G, POS start){
  map<POS, COST> d;  // 最短距離
  each(node, G.all_nodes) {d[node] = INF;}

  PQ<pair<COST, POS>> q;
  q.push(mp(0LL, start));
  while (!q.empty()){
    auto cp = q.top(); q.pop();
    auto cost = cp.first;
    auto pos = cp.second;

    if (cost < d[pos]) {
      d[pos] = cost;
      for (const auto &el:G[pos]){
        auto ncost = cost + el.second;
        auto npos = el.first;
        if (ncost < d[npos]) q.push(mp(ncost, npos));
      }
    }
  }
  return d;
}/*}}}*/


