long long N, takahashi, aoki;
vector<bool> used(1000000);
vector<bool> used2(1000000);
vector<long long> route;
bool correctPath = false;
long long halfSize;
long long Max = 0;

void searchPath(long long t, vector<vector<long long>> &ki){
  if(t == takahashi){
    correctPath = true;
    return;
  }
  for(long long i = 0; i < ki.at(t).size(); i++){
    long long to = ki.at(t).at(i);
    if(used.at(to)){
      continue;
    }
    used.at(to) = true;
    searchPath(to, ki);
    if(correctPath){
      route.push_back(to);
      return;
    }
  }
  return;
}

void longestPath(long long t, vector<vector<long long>> &ki, long long steps){
  //cout << "t:" << t << " steps:" << steps <<endl;
  if(steps > Max){
    Max = steps;
  }
  for(long long i = 0; i < ki.at(t).size(); i++){
    long long to = ki.at(t).at(i);
    if(used2.at(to)){
      //cout << "continue" <<endl;
      continue;
    }
    used2.at(to) = true;
    longestPath(to, ki, steps + 1);
  }
  return;
}

void solve() {
  cin >> N >> takahashi >> aoki;
  takahashi--;
  aoki--;
  vector<vector<long long>> ki(N);
  for(long long i = 0; i < N-1; i++){
    long long a, b;
    cin >> a >> b;
    ki.at(a-1).push_back(b-1);
    ki.at(b-1).push_back(a-1);
  }
  searchPath(aoki, ki);
  route.erase(route.begin());
  /*for(int i = 0; i < route.size(); i++){
    cout << route.at(i) <<endl;
  }*/
  halfSize = route.size() / 2;
  if(route.size() == 0){
    used2.at(aoki) = true;
    used2.at(takahashi) = true;
    longestPath(takahashi, ki, 0);
  }
  else if(route.size() == 1){
    used2.at(route.at(halfSize)) = true;
    used2.at(takahashi) = true;
    longestPath(takahashi, ki, 0);
  } else{
    used2.at(route.at(halfSize)) = true;
    used2.at(route.at(halfSize-1)) = true;
    longestPath(route.at(halfSize-1), ki, 0);
  }
  long long Path = route.size() - halfSize + Max;
  cout << Path <<endl;
}

