    G[a].emplace_back(b);
    G[b].emplace_back(a);
  }
  auto index = [](int v){ return v;};
  auto delta = [&](int v, auto update) {
    for (auto&& to : G[v]) {
      update(to);
    }
  };
  auto dist_t = bfs(n, u, delta, index);
  auto dist_a = bfs(n, v, delta, index);
  ll ans = 0;
  rep(i,n) {
    if (dist_t[i] < dist_a[i]) chmax(ans, dist_a[i]-1);
  }
  cout << ans << endl;
  return 0;
}

