int main(){
  cin >> N >> U >> V;
  for (int i = 0; i < N - 1; i++){
    int A, B; cin >> A >> B;
    Graph[A].push_back(B);
    Graph[B].push_back(A);
  }

  fill(DistV, DistV + N + 1, -1);
  queue <int> que; que.push(V);
  DistV[V] = 0;
  while (!que.empty()){
    int Q = que.front(); que.pop();
    for (int next : Graph[Q]){
      if (DistV[next] != -1) continue;
      DistV[next] = DistV[Q] + 1;
      que.push(next);
    }
  }

  int ans = 0;
  fill(DistU, DistU + N + 1, -1);
  que.push(U); DistU[U] = 0;
