    int Q = que.front(); que.pop();
    for (int next : Graph[Q]){
      if (DistU[next] != -1) continue;
      DistU[next] = DistU[Q] + 1;
      if (DistU[next] <= DistV[next]){
        if (DistU[next] < DistV[next]) que.push(next);
        ans = max(ans, DistU[next]);
      }
    }
  }
  cout << ans << endl;

  return 0;
}

