void distance(vector<int> &d,vector<vector<int>> e,int u){
	vector<int> s;
	d[u]=0;
	s.push_back(u);
	while(s.size()){
		int tempn=s.back();
		s.pop_back();
		for(int i=0;i<e[tempn].size();i++){
			if(d[tempn]<d[e[tempn][i]]){
				s.push_back(e[tempn][i]);
				d[e[tempn][i]]=d[tempn]+1;
			}
		}
	}
}

