const int MAXN = 2e5 + 1;
vector<vector<int>> g(MAXN);
vector<int> bfs(int v)
{
	vector<int> d(MAXN, 1e9);
	queue<int>q;
	q.push(v);
	d[v] = 0;
	while (q.size())
	{
		int u = q.front();
		q.pop();
		for (int i : g[u])
		{
			if (d[i] > d[u] + 1)
			{
				d[i] = d[u] + 1;
				q.push(i);
			}
		}
	}
	return d;
}
