void dfs ( int node , int parent = -1 )
{
    if ( parent != -1 )
        level[node] = level[parent] + 1 ;

    if ( parent != -1 ) { p[node] = parent ; }

    for ( auto i : g[node] )
    {
        if ( i == parent ) C ;
        dfs ( i , node ) ;
    }
}

int max_level = -1 ;

void dfs2 ( int node , int parent = -1 )
{
    max_level = max ( max_level , level[node] ) ;

    for ( auto i : g[node] )
    {
        if ( i == parent ) C ;
        if ( i == p[node] ) C ;

        dfs2 ( i , node ) ;
    }
}

void solve ( int test_case )
{
    int n , node , root ;
    cin >> n >> node >> root ;

    node -- ; root-- ;

    g.resize ( n ) ;
    p.resize ( n ) ;

    for ( int i=0 ; i < n-1 ; i ++ )
    {
        int a , b ;
        cin >> a >> b ;

        a -- ;
        b -- ;

        g[a].pb ( b ) ;
        g[b].pb ( a ) ;
    }

    level.resize ( n ) ;
    dfs ( root ) ;

    int dis = level[node] ;
    if ( dis % 2 == 0 )
        dis -- ;

    dis >>= 1 ;
    int ans = dis ; // up-level movement

    int oki_current = dis ;
    int tak_current = node ;

    for ( int i=0 ; i < dis ; i ++ )
    {
        tak_current = p[tak_current] ;
    }

    dfs2 ( tak_current ) ; // max_level !

    if ( max_level != -1 )
    {
        dis = max_level - level[tak_current] ;
        ans += dis ;
    }

    oki_current += dis ;
    tak_current = max_level ;

    int c = 0 ;
    while ( oki_current != tak_current )
    {
        if ( c == 0 ) tak_current -- ;
        else tak_current ++ ;

        if ( tak_current == oki_current )
            break ;

        oki_current ++ ;
        ans ++ ;
        c ^= 1 ;
    }

    cout << ans ; line
}

