u3 xoredge[u6(1e5 + 1)];
struct nodeT {
	vector<u3> edges;
	array<u3,2> weight;
};
nodeT node[u6(1e5 + 1)];
struct Calc {
	DEFINITER;
	DEFVALUES(//////////////////////////////////////////////////
		(u6,N)
	);///////////////////////////////////////////////////////
	u3 dfs(u3 prevedge,u3 nodeindex,u3 w,u3 windex) {
		u3 maxt = 0;
		for (auto & currentedge : node[nodeindex].edges) {
			if (currentedge != prevedge) {
				u3 t=dfs(currentedge, xoredge[currentedge] ^ nodeindex, w + 1, windex);
				if (t)maxt = max(t, maxt);
			}
		}
		node[nodeindex].weight[windex] = w;
		if (windex == 1) {
			if (node[nodeindex].weight[0] < node[nodeindex].weight[1]) {
				if (maxt == 0) {
					//終端だったり青木くんのが到着先の場合
					return node[nodeindex].weight[0] - (node[nodeindex].weight[1] - node[nodeindex].weight[0]-1) / 2;
				}
				else {
					return maxt;
				}
			}
			else {
				return 0;
			}
		}
		else {
			return 0;
		}
	}
	u6 calc() {
		u6 result = 0;
		array<u3, 2> uv;
		read(uv, 2);
		rep(i, N) {
			array<u3, 2> buf;
			read(buf,2);
			xoredge[i+1]= buf[0] ^ buf[1];
			rep(j, 2) {
				node[buf[j]].edges.push_back(i + 1);
			}
		}
		u3 maxt = 0;
		rep(j, 2) {
			for (auto & currentedge : node[uv[j]].edges) {
				u3 t=dfs(currentedge, xoredge[currentedge] ^ uv[j], 1, j);
				if (t != 0)maxt = max(t, maxt);
			}
		}
		return maxt;
	}

	/*******************************************************************************/
};

