  queue<ll> QQ;
  QQ.push(V-1);
  CAN[V-1]=true;
  while(!QQ.empty()){
    ll i=QQ.front();
    QQ.pop();
    FORE(j,G[i]){
      if(CAN[j]) continue;
      CAN[j]=true;
      chmin(DV[j],DV[i]+1);
      QQ.push(j);
    }
  }

  REP(i,N){
    if(DU[i]<DV[i]) chmax(ans,DV[i]);
  }
  co(ans-1);
  return 0;
}

