long long zeroes(long long n) {
	if (n % 2 || n < 10) return 0;
	long long tmp = n;
	long long res = 0;
	long long power = 0;
	long long max = 1;
	while (tmp >= 10) {
		++power;
		max *= 10;
		tmp /= 10;
	}
	max *= tmp;
	for (int i = 0; i < power; ++i) {
		res += (power - i) * tmp;
		tmp *= (9 + (i > 0));
	}
	return res + zeroes(n - max);
}

