vector<lint> depth(lint N,lint root,vector<lint> l1,vector<lint> l2) {
  vector<lint> res(N,-1);
  res[root] = 0;
  vector<queue<lint>> can(N);
  rep(i,N-1) {
    can[l1[i]].push(l2[i]);
    can[l2[i]].push(l1[i]);
  }

  queue<lint> que;
  que.push(root);
  lint pla;

  while (!que.empty()) {
    pla = que.front();
    while (!can[pla].empty()) {
      if (res[can[pla].front()] == -1) {
        res[can[pla].front()] = res[pla] + 1;
        que.push(can[pla].front());
      }
      can[pla].pop();
    }
    que.pop();
  }

  return res;
}

