vector<vector<pair<int, int>>> graph;
vector<int> dijkstra(int i,int n, vector<vector<pair<int, int>>> graph) {
  vector<int> d(n, INF);
  d[i] = 0;
  priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> q;
  q.push(make_pair(0, i));
  while (!q.empty()) {
    pair<int, int> p = q.top();
    q.pop();
    int v = p.second;
    if (d[v] < p.first) {
      continue;
    }
    for (auto x : graph[v]) {
      if (d[x.first] > d[v] + x.second) {
        d[x.first] = d[v] + x.second;
        q.push(pair<int, int>(d[x.first], x.first));
      }
    }
  }
  return d;
}

signed main() {
  int N, u, v;
  cin >> N >> u >> v;
  u--; v--;

  graph = vector<vector<pair<int, int>>>(N);
  int a, b;
  REP(i, N-1){
    cin >> a >> b;
    a--; b--;
    graph[a].push_back(make_pair(b, 1));
    graph[b].push_back(make_pair(a, 1));
  }

  int flag = 0;
  REP(i, graph[u].size()){
    if(graph[u][i].first != v) flag = 1;
  }
  if(!flag){
    cout << 0 << endl;
    return 0;
  }

  vector<int> dist1 = dijkstra(u, N, graph);
  vector<int> dist2 = dijkstra(v, N, graph);

  int ans = 0;
  REP(i, N){
    cout << dist1[i] << " " << dist2[i] << endl;
    if(dist1[i] < dist2[i]) chmax(ans, dist1[i]);
  }

  if(ans == 0) ans++;
  cout << ans << endl;

  return 0;
}

