using namespace std;

struct edge {
	int src;
	int dst;
	bool usable;
};

const int inf = 1 << 30;

vector<int> get_distances_from(int N, const vector<vector<edge>> &g, int u)
{
	vector<int> d(N, inf);

	vector<bool> visited(N, false);
	queue<int> q;

	auto visit = [&](int y) {
		if (!visited[y]) {
			visited[y] = true;
			q.push(y);
		}
	};

	visit(u);

	for (int depth = 0; !q.empty(); ++depth) {
		queue<int> q2;
		swap(q, q2);
		while (!q2.empty()) {
			int x = q2.front();
			q2.pop();
			d[x] = depth;
			for (auto &e : g[x]) {
				if (e.usable) {
					visit(e.dst);
				}
			}
		}
	}

	return d;
}


int main()
{
	int N;
	cin >> N;
	int u, v;
	cin >> u >> v;
	--u;
	--v;

	vector<vector<edge>> g(N);
	for (int i = 0; i < N - 1; ++i) {
		int A, B;
		cin >> A >> B;
		--A;
		--B;
		edge eA = { A, B, true };
		edge eB = { B, A, true };
		g[A].push_back(eA);
		g[B].push_back(eB);
	}

	auto d_from_v = get_distances_from(N, g, v);
	auto d_from_u = get_distances_from(N, g, u);

	//cout << "d_from_v" << endl;
	//for (int i = 0; i < N; ++i) {
	//	cout << u + 1 << " -> " << i + 1 << " : " << d_from_v[i] << endl;
	//}

	//cout << "d_from_u" << endl;
	//for (int i = 0; i < N; ++i) {
	//	cout << u  + 1 << " -> " << i + 1 << " : " << d_from_u[i] << endl;
	//}

	int unused_count = 0;

	vector<int> p;
	int cur = v;
	p.push_back(cur);
	while (cur != u) {
		for (auto &e : g[cur]) {
			if (d_from_u[cur] == d_from_u[e.dst] + 1) {
				cur = e.dst;
				p.push_back(cur);

				if (unused_count < (d_from_u[v] + 1) / 2) {
					//cout << "*** " << e.src + 1 << " -> " << e.dst + 1 << " is unusable." << endl;
					for (auto &f : g[e.dst]) {
						if (f.dst == e.src) {
							//cout << "*** " << f.src + 1 << " -> " << f.dst + 1 << " is unusable." << endl;
							f.usable = false;
							break;
						}
					}
					e.usable = false;
					++unused_count;
				}

				break;
			}
		}
	}

	//for (auto x : p) {
	//	cout << " -> " << x + 1;
	//}
	//cout << endl;

	auto d_from_u2 = get_distances_from(N, g, u);
	//for (int i = 0; i < N; ++i) {
	//	cout << u + 1 << " -> " << i + 1 << " : " << d_from_u2[i] << endl;
	//}

	int ans = 0;

	for (int i = 0; i < N; ++i) {
		if (d_from_u2[i] < inf && g[i].size() == 1) {
			ans = max(ans, d_from_v[i] - 1);
		}
	}


	cout << ans << endl;
}

