vector<vector<int>> nodes(100000, vector<int>());

bool findRoute(int from, int node, vector<int> &route, int target) {
  if (node == target) {
    route.push_back(node);
    return true;
  }

  rep(i, nodes[node].size()) {
    if (nodes[node][i] != from) {
      if (findRoute(node, nodes[node][i], route, target)) {
        route.push_back(node);
        return true;
      }
    }
  }

  return false;
}

int maxDistance(int from, int node) {
  vector<int> dist;
  rep(i, nodes[node].size()) {
    if (nodes[node][i] != from) {
      dist.push_back(maxDistance(node, nodes[node][i]));
    }
  }
  if (dist.size() == 0) {
    return 0;
  }
  int maxDist = 0;
  rep(i, dist.size()) {
    maxDist = max(maxDist, dist[i]);
  }
  return maxDist + 1;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
