  vector<int> A(N - 1), B(N - 1);
  rep(i, N - 1) {
    cin >> A[i] >> B[i];
    A[i]--;
    B[i]--;
    nodes[A[i]].push_back(B[i]);
    nodes[B[i]].push_back(A[i]);
  }

  vector<int> utov;
  findRoute(-1, v, utov, u);

  int distance = utov.size() - 1;
  if (distance==1) {
    out(maxDistance(v, u));
  } else if (distance==2) {
    out(maxDistance(utov[1], u))
  } else {
    out(maxDistance(utov[2], utov[2])+1)
  }
}

