        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        V[a].node.push_back(b);
        V[b].node.push_back(a);
    }

    {
        memset(A, -1, sizeof(A));
        A[v] = 0;
        queue<pll> q;
        q.push(pll(v, 0));
        while (!q.empty()) {
            pll t = q.front();
            q.pop();
            REP(i, V[t.first].node.size()) {
                ll n = V[t.first].node[i];
                if (A[n] >= 0)
                    continue;
                A[n] = t.second + 1;
                q.push(pll(n, t.second + 1));
            }
        }
