            q.pop();
            ll k = t.first;
            max = std::max(max, T[k]);
            if (V[k].node.size() >= 2) {
                ll m = (A[k] - T[k] + 1) / 2;
                max = std::max(max, std::min(T[k] + m * 2, A[k]));
