                    continue;
                max = std::max(max, T[n]);
                if (V[n].node.size() >= 2) {
                    ll m = (A[n] - T[n] + 1) / 2;
                    max = std::max(max, std::min(T[n] + m * 2, A[n]));
                }
                if (T[n] < A[n])
                    q.push(pll(n, t.second + 1));
            }
        }
    }

