vector<VI> G;
VI par;
vector<Pi_i> leaf;// -d, idx

int commonAncestor(int u, int v){
    if(u == v) return u;
    if(d[u] > d[v]) return commonAncestor(par[u], v);
    return commonAncestor(u, par[v]);
}

int distant(int u, int v){
    return d[u] + d[v] - 2 * d[commonAncestor(u, v)];
}

int main(){
    int u, v; cin >> V >> u >> v;
    --u; --v;
    d.resize(V, -1);
    par.resize(V, -1);
    G.resize(V);
    d[v] = 0;
    par[v] = NIL;
    REP(i, V-1){
        int a, b; cin >> a >> b; --a; --b;
        G[a].PB(b); G[b].PB(a);
    }
    queue<int> q;
    q.push(v);
    while(!q.empty()){
        int cur = q.front(); q.pop();
        int dist = d[cur];
        int cntchild = 0;
        for(auto next: G[cur]){
            if(d[next] != -1) continue;
            d[next] = dist + 1;
            par[next] = cur;
            q.push(next);
            ++cntchild;
        }
        if(!cntchild) leaf.PB(MP(-dist, cur));
    }
    SORT(leaf);
    int goal = NIL, lf = NIL;
    for(auto& l: leaf){
        int ca = commonAncestor(u, l.second);
        if(distant(u, ca) < d[ca] && goal == NIL)
            goal = l.second;
        if(ca == u && lf == NIL) lf = l.second;
        if(goal != NIL && lf != NIL) break;
    }
    int cnt = 0;
//    cout << u+1 << " " << v+1 << "\n";
    while(1){
        if(goal == NIL){
            if(u == lf){
                u = par[u];
            }else{
                int dd = INF, nt = NIL;
                for(auto a: G[u]){
                    int ddd = distant(a, lf);
                    if(dd > ddd){
                        dd = ddd; nt = a;
                    }
                }
                u = nt;
            }
        }else{
            if(u == goal){
                u = par[u];
            }else{
                int dd = INF, nt = NIL;
                for(auto a: G[u]){
                    int ddd = distant(a, goal);
                    if(dd > ddd){
                        dd = ddd; nt = a;
                    }
                }
                u = nt;
            }
        }
        if(v == u) break;
        int dd = INF, nt = NIL;
        for(auto a: G[v]){
            int ddd = distant(a, u);
            if(dd > ddd){
                dd = ddd; nt = a;
            }
        }
        v = nt; ++cnt;
 //       cout << u+1 << " " << v+1 << "\n";
        if(v == u) break;
    }
    cout << cnt << "\n";
    return 0;
}

