template <class T> inline void chmin(T &ans, T t) { if (t < ans) ans = t;}

int disT[100010];
int disA[100010];

void dfs(int now, vector<bool> & visited, vector<vector<int>>& G, bool flag) {
  for (auto it : G[now]) {
    if (!visited[it]) {
      if (flag) {
        // takahashi
        disT[it] = disT[now] + 1;
        visited[now] = true;
        dfs(it, visited, G, flag);
      } else {
        disA[it] = disA[now] + 1;
        visited[now] = true;
        dfs(it, visited, G, flag);
      }
    }
  }
}

int main() {
  int n, u, v;
  cin >> n >> u >> v;
  u --, v --;
  vector<vector<int>> G(n);
  rep(i, n-1) {
    int a,b;
    cin >> a >> b;
    a--, b--;
    G[b].push_back(a);
    G[a].push_back(b);
  }

  vector<bool> visited(n), visitedb(n);
  dfs(u, visited, G, true);
  dfs(v, visitedb, G, false);

  rep(i, n) {
    cout << disT[i] << " ";
  }
  cout << endl;

  rep(i, n) {
    cout << disA[i] << " ";
  }
  cout << endl;

  int ans = 0;
  bool flag = false;
  for (int i = 0; i < n; ++i) {
    if (disA[i] <= disT[i]) {
      ans = max(ans, (disA[i] + disT[i]) / 2);
    } else {

      auto t = disA[i] - disT[i];
      t /= 2;

      if (!flag && t == 0) {
        flag = true;
      }


      // cout << disA[i] << " " << disT[i] << " "<< t << endl;
      ans = max(disT[i] + t, ans);
    }
  }

  cout << ans << endl;
}

