constexpr int N_MAX = 1e5;
int N, U, V;

vvi G(N_MAX, vi());

void bfs(int s, pii banned, vi& d) {
  fill(begin(d), end(d), INF);

  queue<int> q;
  q.push(s);
  d[s] = 0;

  while (!q.empty()) {
    int u = q.front(); q.pop();
    for (int v : G[u]) {
      if (d[v] < INF ||
	  (banned.first == v && banned.second == u) ||
	  (banned.first == u && banned.second == v) ) continue;
      d[v] = d[u] + 1;
      q.push(v);
    }
  }
}

int main(int argc, char** argv) {
  cin >> N >> U >> V;
  U--; V--;

  REP(i, N-1) {
    int A, B;
    cin >> A >> B;
    A--; B--;
    G[A].emplace_back(B);
    G[B].emplace_back(A);
  }

  vi d(N_MAX);
  // get each distance from V
  pii dummy = {-1, -1};
  bfs(V, dummy, d);
  int ret = 0;
  ret += (d[U]-1)/2;

cerr << "ret " << ret << endl;

  if (ret == 0) {
    cout << d[U]-1 << endl;
    return 0;
  }

  // Approach U to V by ret
  int cur = U;
  int step = 0;
  while (true) {
    if (step == ret) break;

    step++;
    for (auto x : G[cur]) {
      if (d[x]+1==d[cur]) {
        cur = x;
	break;
      }
    }
  }

cerr << "cur " << cur << endl;
  if (d[U]%2==0) ret++;
cerr << "ret2 " << ret << endl;

