  int y = 0;
  for (auto x : G[cur]) {
    if (d[x]+1==d[cur]) {
      y = x;
      break;
    }
    assert(false);
  }

  bfs(cur, make_pair(cur, y), d);
  int tmp = 0;
  for(auto x : d) {
    if (x == INF) continue;
    chmax(tmp, x);
  }

  cerr << "tmp " << tmp << endl;

  cout << ret + tmp << endl;

  return 0;
}

