    for(int i = 0; i < graph[u].size(); i++)
    {
        int v = graph[u][i];
        if(visited[v])
            continue;
        if(dfs(v, dis+1))
        {
            if(dis == (l-1)/2)
                a = u;
            if(dis == (l-1)/2 + 1)
                b = u;
            return 1;
        }
    }
    return 0;
}

int find(int u, int dis)
{
    visited[u] = 1;
    int ans = dis;
    for(int i = 0; i < graph[u].size(); i++)
    {
        int v = graph[u][i];
        if(visited[v] || v == b)
            continue;
        ans = max(ans, find(v, dis+1));
    }
    return ans;
}

