// 青木君(=v)から見た各ノードの距離
void a_dfs(int v, int d, vi &dist, vb &seen, Graph &g) {
  seen[v] = true;
  dist[v] = d;
  for (int nv : g[v]) {
    if (seen[nv]) continue;
    a_dfs(nv, d+1, dist, seen, g);
  }
}

// 高橋君(=u)が移動できる場所
void t_dfs(int v, int d, vi &dist, vb &seen, Graph &g) {
  seen[v] = true;
  for (int nv : g[v]) {
    if (seen[nv] || d >= dist[nv]) continue;
    t_dfs(nv, d+1, dist, seen, g);
  }
}

