    while(!q.empty()){
        int now = q.front(); q.pop();
        for(auto next : to[now]){
            if(dist_u[next] == -1) {
                dist_u[next] = dist_u[now] + 1;
                q.push(next);
            }
        }
    }    

    // 青木くん v からの距離 dist_v
    vi dist_v(n, -1);
    queue<int> emp;
    swap(q, emp);

    q.push(v);
    dist_v[v] = 0;

    while(!q.empty()){
