  function<int(int,int)> height = [&](auto cur, auto pre) {
    auto res = 0;
    for(auto nex: G[cur]) if(nex != pre) if(!NG.count(nex)) res = max(res, 1 + height(nex, cur));
    return res;
  };

  ans += height(u, -1);
  if(path.size() & 1) ++ans;
  cout << ans << endl;
