void search(int curr, int prev, int ter) {
    x[curr] = x[prev]+1;
    if (curr == ter) return;
    for (auto &to: e[curr]) {
        if (to != prev) {
            search(to, curr, ter);
        }
    }
}

void search2(int curr, int prev, int u) {
    if (prev != 0) {
        if (x[curr] && x[prev] > x[curr]) {
            d[curr] = d[prev] - 2;
        } else d[curr] = d[prev];
        y[curr] = y[prev] + 1;
    }
    if (d[curr] <= 0) return;
    for (auto &to: e[curr]) {
        if (to != prev) {
            search2(to, curr, u);
        }
    }
}

