const ll INF = 1e18;

ll N, FI_V, SE_V;
VVL edge_list;
ll limit_v, ng_v;
VL se_ds;

bool fill_path(ll u, ll p, VL& path) {
  if (p >= 0 && edge_list[u].size() == 1 && u != SE_V) return false;

  path.push_back(u);
  if (u == SE_V) return true;

  bool exist = false;

  for (auto v : edge_list[u]) {
    if (v == p) continue;

    if (fill_path(v, u, path)) {
      exist = true;
      break;
    }
  }

  if (!exist) path.pop_back();

  return exist;
}

// ある点から ng_v を含まない範囲での最善解を得る
ll dfs(ll u, ll p) {
  ll res = se_ds[u] - 1;

  for (ll v : edge_list[u]) {
    if (v == ng_v || v == p) continue;

    ll _res = dfs(v, u);
    chmax(res, _res);
  }

  return res;
}

void fill_ds(ll u, ll p, ll cur_d, VL& ds) {
  chmin(ds[u], cur_d);

  for (ll v : edge_list[u]) {
    if (v == p) continue;
    fill_ds(v, u, cur_d + 1, ds);
  }
}

void solve() {
  cin >> N >> FI_V >> SE_V;
  FI_V--, SE_V--;

  if (FI_V == SE_V) drop(0);

  edge_list = VVL(N, VL(0));

  rep(i, N - 1) {
    ll a, b;
    cin >> a >> b;
    a--, b--;
    edge_list[a].push_back(b);
    edge_list[b].push_back(a);
  }

  // 1. 先手から後手までのパスを求める

  // 2.
  // 後手から逃げ切れる限界（limit_v）を求め、スタートからその点までの範囲から到達できる全ての点について考える

  // 3. それらに含まれるある端の点について、そこから 1
  // 戻った点で２者は合流するから、後手から全ての点への距離を求めておき、そこから
  // 1 引けば良い

  VL path(0);
  fill_path(FI_V, -1, path);

  limit_v = path[path.size() / 2 - 1];
  ng_v = path[path.size() / 2];

  se_ds = VL(N, INF);
  fill_ds(SE_V, -1, 0, se_ds);

  ll res = dfs(limit_v, -1);
  cout << res << endl;
}

void solve2() {
  cin >> N >> FI_V >> SE_V;
  FI_V--, SE_V--;

  if (FI_V == SE_V) drop(0);

  edge_list = VVL(N, VL(0));

  rep(i, N - 1) {
    ll a, b;
    cin >> a >> b;
    a--, b--;
    edge_list[a].push_back(b);
    edge_list[b].push_back(a);
  }

  // 後手から逃げ切れる限界は先手からの距離も求めておけばわざわざ求める必要がなくなる
  VL se_ds(N, INF);
  VL fi_ds(N, INF);
  fill_ds(SE_V, -1, 0, se_ds);
  fill_ds(FI_V, -1, 0, fi_ds);

  ll res = 0;

  rep(i, N) {
    if (fi_ds[i] < se_ds[i]) {
      chmax(res, se_ds[i] - 1);
    }
  }

  cout << res << endl;
}

