int solve(int n,int A,int T){
    if(A==T) return 0;
    for(int i = 1; i <= n; i++) vis[i] = 0;
    vis[A] = 1;
    int h = 0, t = -1;
    Q[++t] = A;
    while(h<=t){
        int u = Q[h++];
        for(unsigned int i = 0; i < g[u].size(); i++){
            int v = g[u][i];
            if(vis[v]) continue;
            disA[v] = disA[u] + 1;
            vis[v] = 1;
            Q[++t] = v;
        }
    }
    int ans = disA[T]-1;
    for(int i = 1; i <= n; i++) vis[i] = 0;
    vis[T] = 1;
    h = 0, t = -1;
    Q[++t] = T;
    while(h<=t){
        int u = Q[h++];
        int cnt = 0;
        for(unsigned int i = 0; i < g[u].size(); i++){
            int v = g[u][i];
            if(vis[v]) continue;
            cnt++;
            vis[v] = 1;
            disT[v] = disT[u] + 1;
            Q[++t] = v;
        }
        //printf("u = %d\n",u);
        if(cnt==0 && disT[u]<disA[u]) ans = max(ans,disA[u]-1);
    }
    return ans;
}

