int main() {
    int n, s, t;
    std::cin >> n >> s >> t;
    --s, --t;

    Graph<> tree(n);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        std::cin >> u >> v;
        --u, --v;
        tree[u].emplace_back(u, v);
        tree[v].emplace_back(v, u);
    }

    std::vector<int> sdist(n, -1);
    sdist[s] = 0;
    std::queue<int> que;
    que.push(s);

    while (!que.empty()) {
        int v = que.front();
        que.pop();

        for (auto e : tree[v]) {
            if (sdist[e.dst] < 0) {
                sdist[e.dst] = sdist[v] + 1;
                que.push(e.dst);
            }
        }
    }

    std::vector<int> tdist(n, -1);
    tdist[t] = 0;
    que.push(t);

    while (!que.empty()) {
        int v = que.front();
        que.pop();

        for (auto e : tree[v]) {
            if (tdist[e.dst] < 0) {
                tdist[e.dst] = tdist[v] + 1;
                que.push(e.dst);
            }
        }
    }

    int ans = 0;
    for (int v = 0; v < n; ++v) {
        if (sdist[v] < tdist[v]) {
            ans = std::max(ans, tdist[v] - 1);
        }
    }

    std::cout << ans << std::endl;
    return 0;
}

