vi g[100010];
int td[100010] , ad[100010] , ok[100010];

void solve(){
  fastin.scan(N);
  fastin.scan(T);
  fastin.scan(A);
  T--; A--;
  rep(i , N - 1){
    fastin.scan(x); fastin.scan(y);
    x--; y--; g[x].pb(y); g[y].pb(x);
  }

  auto dfs = [&](auto& rec , int cur , int par)->void{
    if(par != -1) ad[cur] = ad[par] + 1;
    each(dst , g[cur]){
      if(dst != par) rec(rec , dst , cur);
    }
  };
  dfs(dfs , A , -1);
  trca(ad , N);
  auto efs = [&](auto& rec, int cur , int par)->void{
    if(par != -1) td[cur] = td[par] + 1;
    ok[cur] = td[cur] < ad[cur];
    if(par != -1) ok[cur] &= ok[par];
    if(ok[cur]) ans = max(ans , ad[cur] - 1);
    each(dst , g[cur]){
      if(dst != par) rec(rec , dst , cur);
    }
  };
  efs(efs , T , -1);
  trca(td , N);
  trca(ok , N);

  fastout.println(ans); 
}

