using namespace std;

class Tree {
	int size;
	vector<vector<int> > adj;
	vector<int> parent;
	vector<int> depth;
	vector<int> maxDepth;
	void reroot_internal(int r, int back) {
		if(back == -1) {
			depth[r] = 0;
			parent[r] = r;
		} else {
			depth[r] = depth[back] + 1;
			parent[r] = back;
		}
		maxDepth[r] = depth[r];

		iter(vector<int>, adj[r], i)
			if(*i != back) {
				reroot_internal(*i, r);
				if(maxDepth[*i] > maxDepth[r])
					maxDepth[r] = maxDepth[*i];
			}
	}
public:
	Tree(int n) {
		adj.resize(size = n);
		parent.resize(n);
		depth.resize(n);
		maxDepth.resize(n);
	}
	void connect(int a, int b) {
		adj[a].push_back(b);
		adj[b].push_back(a);
	}
	void reroot(int r) {
		reroot_internal(r, -1);
	}
	int getParent(int n) {
		return parent[n];
	}
	int getDepth(int n) {
		return depth[n];
	}
	int getMaxDepth(int n) {
		return maxDepth[n] - depth[n];
	}
};

