    cin >> a >> b;
    a--, b--;
    G[a].pb(b);
    G[b].pb(a);
  }
  root = v;
  init_lca();

  ll ans = 0;
  rep(i, N){
    if(depth[i] != depth[u]) continue;
    ll LCA = lca(i, u);
    if(depth[u] - depth[LCA] < depth[LCA]){
      ans = max(ans, dfs(i) - 1);
    }
  }
  cout << ans << endl;
}


