void dfs(int x,int p,int cnt){
    dist[x] = cnt;
    table[x][0] = p;
    tin[x] = ++timer;
    for(int i=1;i<20;i++){
        table[x][i] = table[table[x][i-1]][i-1];
    }
    for(int i : g[x]){
        if(i != p){
            dfs(i,x,cnt+1);
        }
    }
    tout[x] = ++timer;
}

bool anc(int x,int y){
    return tin[x] <= tin[y] && tout[x] >= tout[y];
}

int lca(int x,int y){
    if(anc(x,y)){
        return x;
    }
    if(anc(y,x)){
        return y;
    }
    for(int i = 19; i >= 0; i--){
        if(!anc(table[x][i],y)){
            x = table[x][i];
        }
    }
    return table[x][0];
}

