void solve() {
    i64 N = RD();
    i64 V = RD1();
    i64 W = RD1();

    vector<vector<i64>> G(N);
    REP(_, N-1) {
        i64 a = RD1();
        i64 b = RD1();
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }
    DBG(G);

    vector<i64> d1; tie(d1,ignore) = graph_bfs(G, V);
    DBG(d1);
    vector<i64> d2; tie(d2,ignore) = graph_bfs(G, W);
    DBG(d2);

    i64 ans = 0;
    // 全ての葉を調べる
    REP(v, N) {
        if(SIZE(G[v]) > 1) continue;  // 葉でない
        i64 x = d1[v];  // 逃げる側が葉に行くまでの歩数
        i64 y = d2[v];  // 鬼が葉に行くまでの歩数
        if(x > y) continue;

        chmax(ans, y-1);
    }

    PRINTLN(ans);
}

