void solve(void)
{
  int N; cin >> N;
  int u, v; cin >> u >> v;
  --u, --v;
  vector<vector<int>> tree(N);
  for (int _ = 0; _ < N-1; ++_) {
    int a, b; cin >> a >> b;
    --a; --b;
    tree[a].push_back(b);
    tree[b].push_back(a);
  }

  vector<int> takahashi(N, -1);
  vector<int> aoki(N, -1);
  { // aoki
    std::queue<int> que{};
    que.push(v);
    aoki[v] = 0;
    while (!que.empty()) {
      auto c = que.front();
      que.pop();
      for (const auto& n : tree[c]) {
        if (aoki[n] == -1) {
          aoki[n] = aoki[c] + 1;
          que.push(n);
        }
      }
    }
  }

  int ans{-1};
  { // takahashi
    std::queue<int> que{};
    que.push(u);
    takahashi[u] = 0;
    while (!que.empty()) {
      auto c = que.front();
      que.pop();
      if (aoki[c] >= takahashi[c]) {
        ans = aoki[c]-1;
      }
      else {
        continue;
      }
      for (const auto& n : tree[c]) {
        if (takahashi[n] == -1) {
          takahashi[n] = takahashi[c] + 1;
          que.push(n);
        }
      }
    }
  }
  assert(ans != -1);
  cout << ans << CRLF;
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

