using namespace std;

struct Node {
    vector<Node> children;
    INT depth;
    INT id;
    INT pid;
};

int main(){
    INT N, u, v;
    cin >> N >> u >> v;

    unordered_multimap<INT, INT> path;
    FOR(i, N-1){
        INT A, B;
        cin >> A >> B;
        path.emplace(A, B);
        path.emplace(B, A);
    }

    vector<Node*> nodes(N+1);

    Node root;
    root.depth = 0;
    root.id    = v;
    root.pid   = -1;
    nodes[v] = &root;

    auto treeBuild = [&](auto treeBuild, INT pid, INT id, INT depth, vector<Node>& children_vec ) -> void {
        auto range = path.equal_range( id );
        auto it = range.first;
        while( it != range.second ){
            INT cid = it->second;
            if( cid != pid ){
                Node tmp;
                tmp.depth = depth+1;
                tmp.id = cid;
                tmp.pid = id;
                children_vec.emplace_back(tmp);
                nodes[cid] = &children_vec[children_vec.size()-1];
                treeBuild( treeBuild, nodes[cid]->pid, nodes[cid]->id, nodes[cid]->depth, nodes[cid]->children );
            }
            it++;
        }
    }; 
    treeBuild( treeBuild, root.pid, root.id, root.depth, root.children );

    auto max_depth = []( auto max_depth, Node& node, INT depth )->INT {
        INT ret = depth;
        for( Node& child : node.children ){
            chmax( ret, max_depth(max_depth, child, depth+1) );
        }
        return ret;
    };

    INT ans = 0;
    INT d1 = nodes[u]->depth;
    INT t = 0;
    Node* node = nodes[u];
    do {
        INT d2 = max_depth(max_depth, *node, 0);
        chmax( ans, (d1+d2-1+t) );
        node = nodes[ node->pid ];
        d1 -= 2;
        t++;
    } while (d1 > 0);

    cout << ans << endl;

    return 0;
}

