class Graph{
  long int v;
  unordered_map<long int,unordered_set<long int>> adj;

public:
    Graph(long int n){
      v = n + 1;
    }

    void addEdge(long int u, long int v){
      adj[u].insert(v);
      adj[v].insert(u);
    }

    vector<long int> BFS(long int u){
      vector<long int> distance(v,LONG_MAX);
      distance[u] = 0;
      unordered_set<long int> visited;

      visited.insert(u);
      queue<long int> q;
      q.push(u);

      while(!q.empty()){
        auto e = q.front();
        q.pop();

        for(auto ele : adj[e]){
          if(visited.find(ele) == visited.end()){
            distance[ele] = distance[e] + 1;
            q.push(ele);
            visited.insert(ele);
          }
        }
      }
      for(auto &ele : distance)
        if(ele == LONG_MAX)
          ele = -1;
      return distance;
    }
};

