class dijkstra{
    public:
    ll N;
    vector<vector<pair<ll, ll> > > G;
    vector<ll > dist;
    vector<bool > used;
    vector<ll > prever;
    priority_queue<pair<ll, ll > , vector<pair<ll, ll > >, greater<pair<ll, ll > > > que;


    //グラフに頂点を追加と初期化諸々
    dijkstra(ll n = 4545){
        N = n;
        G.assign(N, vector<pair<ll, ll > >());
        dist.assign(N, 11451419191919);
        used.assign(N, false);
        prever.assign(N, -1);
    }
    //グラフに辺を追加
    void addEdge(ll v, ll u, ll w = 1){
        G[u].push_back(make_pair(v, w));
    }

    //最短距離計算(始点=s)
    vector<ll > CalcDist(ll s){
        que.push(make_pair(0, s));
        while(!que.empty()){
            //距離
            ll d = 0;
            //次の頂点
            ll t_v = 0;
            d = que.top().first;
            t_v = que.top().second;
            //topから削除
            que.pop();
            //探査済みなら処理しない
            if(used[t_v] == true) continue;
            //探査済みにする
            used[t_v] = true;
            //キューの上には既に最小距離が来ているので
            dist[t_v] = d;

            //次探査する頂点はt_vなのでt_vから更に次にの頂点の繋がりをキューにいれる
            for(ll i = 0; i < G[t_v].size(); i++){
                //もし探査済みの頂点で，そこまでの累積距離より今更新しようとしている距離が
                //大きいときは更新しない
                ll to = G[t_v][i].first;
                ll cost = d+G[t_v][i].second;
                if(dist[to] <= cost) continue;
                prever[to] = t_v;
                //累積距離と次の頂点
                que.push(make_pair(cost, to));
                //仮dist
                dist[to] = cost;
            }
        }   
        return dist;
    }

    //経路列挙(終点=t)
    vector<ll > get_path(ll t){
        vector<ll > path;
        //始点を追加
        for(; t != -1; t = prever[t]){
            //cout << prever[t] << endl;
            path.push_back(t);
        }
        //reverse(path.begin(), path.end());
        return path;
    }

};

