ll get_LCA(ll va, ll vb){
	if(depth[va] > depth[vb]){
		va = get_parent(va, depth[va] - depth[vb]);
	}else if(depth[va] < depth[vb]){
		vb = get_parent(vb, depth[vb] - depth[va]);
	}
	ll lv = -1, rv = N+1;
	while(rv - lv > 1){
