ll bfs1(ll n, vector<vll> &nx, ll u, ll v) {
	queue<ll> task;
	task.push(u);
	vector<bool> seen(n, false);
	seen[u] = true;

	ll depth = 1;
	while (task.size()) {
		ll sz = task.size();
		while (sz--) {
			ll x = task.front();
			task.pop();
			for (ll i = 0; i < nx[x].size(); i++) {
				if (nx[x][i] == v) return depth;
				if (!seen[nx[x][i]]) {
					task.push(nx[x][i]);
					seen[nx[x][i]] = true;
				}
			}
		}
		depth++;
	}
}

vll bfs2(ll n, vector<vll> &nx, ll u, ll v, ll dist) {
	queue<ll> task1, task2;
	task1.push(u);
	task2.push(v);
	vector<bool> seen1(n, false), seen2(n, false);
	seen1[u] = true;
	seen2[v] = true;

	ll depth = 1;
	while (1) {
		ll sz = task2.size();
		while (sz--) {
			ll x = task2.front();
			task2.pop();
			for (ll i = 0; i < nx[x].size(); i++) {
				if (!seen2[nx[x][i]]) {
					task2.push(nx[x][i]);
					seen2[nx[x][i]] = true;
				}
			}
		}
		if (depth == dist / 2) break;
		depth++;
	}

	while (1) {
		ll x = task1.front();
		task1.pop();
		for (ll i = 0; i < nx[x].size(); i++) {
			if (seen2[nx[x][i]]) return {x, nx[x][i]};
			if (!seen1[nx[x][i]]) {
				task1.push(nx[x][i]);
				seen1[nx[x][i]] = true;
			}
		}
	}
}

