int dfs_a(graph &G, vector<bool> &seen_a, vector<P> &a, int v, bool f, int d, int u, int &tm, int &fm) {
  d++;
  seen_a[v] = true;
  if (v == u) f = true;
  for (auto nv : G[v]) {
    if (seen_a[nv]) continue;
    dfs_a(G,seen_a,a,nv,f,d,u,tm,fm);
  }
  if (f) {
    a[v].first = d;
    a[v].second = true;
    tm = max(tm,d);
  } else {
    a[v].first = d;
    a[v].second = false;
    fm = max(fm,d);
  }
  if (v == u) f = false;
  d--;
  return 0;
}

int dfs_b(graph &G, vector<bool> &seen_b, vector<int> &b, int v, int d) {
  d++;
  seen_b[v] = true;
  for (auto nv : G[v]) {
    if (seen_b[nv]) continue;
    dfs_b(G,seen_b,b,nv,d);
  }
  b[v] = d;
  return 0;
}

