using namespace std ;

const int N = 200010;
int n , s , t , tot , r ;
int nex[2*N] , to[2*N];
int head[N], ans[N], deep[N];

int read()
{
  int x = 0, w = 1;
  char ch = 0;
  while (ch < '0' || ch > '9') {  // ch 不是数字时
    if (ch == '-') w = -1;        // 判断是否为负
    ch = getchar();               // 继续读入
  }
  while (ch >= '0' && ch <= '9') {  // ch 是数字时
    x = x * 10 + (ch - '0');  // 将新读入的数字’加’在 x 的后面
    // x 是 int 类型，char 类型的 ch 和 ’0’ 会被自动转为其对应的
    // ASCII 码，相当于将 ch 转化为对应数字
    // 此处也可以使用 (x<<3)+(x<<1) 的写法来代替 x*10
    ch = getchar();  // 继续读入
  }
  return x * w;  // 数字 * 正负号 = 实际数值
}

void add(int u , int v)
{
    nex[++ tot] = head[u] ;
    head[u] = tot ;
    to[tot] = v ;
}

void d1(int x , int w){
    deep[x] = deep[w] + 1 ;
    ans[x] = deep[x] ;
    for(int i = head[x] ; i ; i = nex[i] ){
        int v = to[i] ;
        if( v == w ) continue ;
        d1( v , x ) ;
        ans[x] = max( ans[x] , ans[v] ) ;
    }
}

int d2(int x , int y, int w)
{
    if( w >= deep[x] ) return 0 ;
    for(int i = head[x] ; i ; i = nex[i] ){
        if( to[i] == w ) continue ;
        if(!d2(to[i] ,x ,w + 1 )) {
            r = x ;
        }
    }
    return 1 ;
}

int main()
{
    n = read();
    s = read();
    t = read();
    for(int i = 1 ; i <= n - 1 ; i ++ ){
        int u , v ;
        u = read();
        v = read();
        add( u , v ) ; 
        add( v , u ) ;
    }
    d1( t , 0 ) ;
    d2( s , 0 , 0 ) ;
    ans[r] -= 2;
    cout<<ans[r];
    return 0 ;
}

