vector <int> get_v (int v, int x) {
    vector <int> d(n, INF), ans;
    d[v] = 0;
    queue <int> q;
    q.push(v);
    while (!q.empty()) {
        v = q.front();
        q.pop();
        for (int to : edge[v]) {
            if (d[to] == INF) {
                d[to] = d[v] + 1;
                q.push(to);
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (d[i] <= x) ans.pb(i);
    }
    return ans;
}
