int f(int n) {
    if (n == 1) {
        return 0;
    } else if (n == 2) {
        return 1;
    } else {
        return 2 + f(n - 2);
    }
}

int takahashi(int s, graph& g) {
    function<int(int, int, int)> rec = [&](int v, int bv, int step) {
        int ret = 0;

        if (g[v].isLeaf()) {
            ret = step + f(g[v].aoki - step);
        }

        for (int u : g[v].neighbor) {
            if (u != bv && g[u].aoki - step > 0) {
                ret = max(ret, rec(u, v, step + 1));
            }
        }

        return ret;
    };

    return rec(s, -1, 0);
}

