void dfs(int i, int dep, int from) {
  d[i] = dep;
  parent[i] = from;
  for (auto &j : p[i]) {
    if (j == from) continue;
    dfs(j, dep + 1, i);
  }
}

int lca(int i, int j) {
  if (d[i] < d[j]) swap(i, j);
  int k = 22;
  while (k >= 0 && d[i] > d[j]) {
    if (d[parentk[k][i]] >= d[j]) {
      i = parentk[k][i];
    }
    k--;
  }
  k = 22;
  if (i == j) return i;
  while (k >= 0 && i != j) {
    if (parentk[k][i] != parentk[k][j]) {
      i = parentk[k][i];
      j = parentk[k][j];
    }
    k--;
  }
  return parent[i];
}

