  parent.resize(n);
  for (int i = 0; i < n - 1; i++) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    p[a].push_back(b);
    p[b].push_back(a);
  }
  dfs(u, 0, u);
  parentk.resize(23);
  for (int i = 0; i < n; i++) parentk[0].push_back(parent[i]);
  for (int k = 1; k < 23; k++) {
    for (int i = 0; i < n; i++) {
      parentk[k].push_back(parentk[k - 1][parentk[k - 1][i]]);
    }
  }
  ll ans = d[v] / 2;
  for (int i = 0; i < n; i++) {
    int q = lca(v, i);
    if (d[v] - d[q] + d[i] - d[q] <= d[i]) {
      continue;
    }
    ll diff = d[v] - 2 * d[q];
    ans = max(ans, (diff - 1) / 2 + d[i]);
  }
  cout << ans << endl;
  return 0;
}

