void BFS(vector<Edges> &G, vector<int> &pred, vector<int> &dist, vector<int> &checked ,int s, int n){
  for(int v=0; v<n; ++v){
    pred[v] = -1;
    dist[v] = qweqwe::constnumber::INF_i32;
    checked[v] = 0;
  }
  checked[s] = 1;
  dist[s] = 0;
  queue<int> Q;
  Q.push(s);
  while(!Q.empty()){
    auto u = Q.front();
    for(auto v : G[u]){
      if(checked[v]==0){
        dist[v] = dist[u] + 1;
        pred[v] = u;
        checked[v] = 1;
        Q.push(v);
      }
    }
    Q.pop();
    checked[u] = 2;
  }
}

