int n, u, v;
vector<int> link[100005];
int maxDepth[100005];
bool visit[100005];
bool visit2[100005];
int rootOf[100005];
int answerDp[100005];

int dfs(int root) {
    visit[root] = true;
    for (int i : link[root]) {
        if (visit[i]) continue;
        rootOf[i] = root;
        maxDepth[root] = max(maxDepth[root], dfs(i) + 1);
    }
    visit[root] = false;
    return maxDepth[root];
}

int dfs2(int root, int mv) {
    if (maxDepth[root] == 0) return 0;
    if (answerDp[root]) return answerDp[root];
    visit2[root] = true;

    for (int i : link[root]) {
        if (visit2[i]) continue;

        if (maxDepth[i] < maxDepth[root]) {
            answerDp[root] = max(answerDp[root], dfs2(i, mv) + 1);
        }
        else {
            answerDp[root] = max(answerDp[root], dfs2(i, mv + 1) + 1);
        }
    }

    visit2[root] = false;
    return answerDp[root];
}

