    if (maxDepth[u] == 0 && maxDepth[v] == 1) {
        return cout << 0, 0;
    }

    int answer = maxDepth[v] - 1;

    int cnt = 1;
    int tu = rootOf[u];
    while (tu != v) {
        int depthOfV = maxDepth[v] - cnt;

        if (depthOfV <= maxDepth[tu])
            break;

        answer = max(answer, depthOfV + cnt - 1);
        cnt++;
        tu = rootOf[tu];
    }

    return cout << answer, 0;
}

