void add(ll u,ll v,ll w){
	cnt++;
	edge[cnt].to=v;
	edge[cnt].w=w;
	edge[cnt].next=head[u];
	head[u]=cnt;
}
void dijkstra(ll u){
	dist[u]=0;
	q.push(node {u,dist[u]});

	while(!q.empty()){
		node x=q.top();
		q.pop();
		if(vis[x.to]) continue;
		vis[x.to]=true;
		for(ll i=head[x.to];i!=-1;i=edge[i].next){
			ll v=edge[i].to;
			if(dist[v]>dist[x.to]+edge[i].w){
				dist[v]=dist[x.to]+edge[i].w;
				q.push(node {v,dist[v]});
			}
		}
	}
}
