int dist(vector<vector<int>> &vec,int dest,int curr)
{
    int n=vec.size();
    vector<int> visited(n,0);
    queue<pair<int,int>> q;
    q.push(make_pair(curr,0));
    visited[curr]=1;
    while(!q.empty())
    {
        pair<int,int> p=q.front();
        int temp=p.first;
        int dis=p.second;
        if(temp==dest)
        return dis;
        q.pop();
        for(int i=0;i<vec[temp].size();++i)
        {
            if(!visited[vec[temp][i]])
            {
                visited[vec[temp][i]]=1;
                q.push(make_pair(vec[temp][i],dis+1));
            }
        }
    }
}

