bool dfs_vtou(vector<vector<ll>>& tree, vector<ll>& path, ll parent, ll u, ll now, ll depth) {
  ll d = depth;
  for (ll i : tree[now]) {
    if (i == parent) continue;
    if (i == u) {
      path.push_back(i);
      path.push_back(now);
      return true;
    }
    if (dfs_vtou(tree, path, now, u, i, depth + 1)) {
      path.push_back(now);
      return true;
    }
  }
  return false;
}

ll dfs(vector<vector<ll>>& tree, ll parent, ll now, ll depth) {
  ll d = depth;
  for (auto i : tree[now]) {
    if (i == parent) continue;
    d = max(d, dfs(tree, now, i, depth + 1));
  }
  return d;
}

