        int v_to=nodes[v].to[i];
        if(v_to==p)continue;
        nodes[v_to].dist=nodes[v].dist+1;
        if(v_to==U)nodes[v_to].find=true;
        dfs1(v_to, v, nodes);
        if(nodes[v_to].find)nodes[v].find=true;
    }
    for (int i = 0; i < nodes[v].to.size(); i++){
        int v_to=nodes[v].to[i];
        if(v_to==p)continue;
        nodes[v].dist=max(nodes[v].dist,nodes[v_to].dist);
    }
}
void dfs2(int v, int p, vector<node> &nodes){
    for (int i = 0; i < nodes[v].to.size(); i++){
        int v_to=nodes[v].to[i];
        if(v_to==p)continue;
        if(!nodes[v_to].find)continue;
        if(nodes[v_to].dist!=dist_max)continue;
        d1++;
        dfs2(v_to,v,nodes);
    }
}

