int N, u, v;
vvi adj;

struct LCA {
	int n, LOGN;
	vi lvl, par;	// lvl[root] = 0, par[root] = -1
	vvi P, F;
	int combine(int x, int y) {
		// if x corresponds to path u -> v, y to path v -> w
		// we should return value corresponding to path u -> w
	}
	LCA(int _n, int root) {
		n = _n;
		LOGN = log2(n) + 1;
		lvl.assign(n + 1, 0);
		par.assign(n + 1, -1);
		// P[i][j] = 2^j'th ancestor of i
		P.assign(n + 1, vi(LOGN, -1));
		// F[i][j] = value of some function F corresponding
		// to the path from i to it's 2^j'th ancestor
		F.assign(n + 1, vi(LOGN, -1));
		dfs(root, 0, -1);

		for (int i = 1; i <= n; ++i) {
			P[i][0] = par[i];
			F[i][0] = 0;	// put a value corresponding to
					// a consisting edge par[i]->i
		}

		for (int j = 1; (1 << j) <= n; ++j)
			for (int i = 1; i <= n; ++i)
				if (P[i][j - 1] != -1) {
					P[i][j] = P[P[i][j - 1]][j - 1];
					F[i][j] = combine(F[i][j - 1], F[P[i][j - 1]][j - 1]);
				}
	}
	void dfs(int u, int level, int parent) {
		lvl[u] = level, par[u] = parent;
		for (auto& v : adj[u])
			if (v != parent)
				dfs(v, level + 1, u);
	}
	int query(int u, int v) {
		if (lvl[u] < lvl[v])
			swap(u, v);
		int log = 1;
		while ((1 << log) <= lvl[u])
			++log;
		--log;
		for (int i = log; i >= 0; --i)
			if (lvl[u] - (1 << i) >= lvl[v])
				u = P[u][i];
		if (u == v)
			return u;
		for (int i = log; i >= 0; --i)
			if (P[u][i] != -1 && P[u][i] != P[v][i])
				u = P[u][i], v = P[v][i];
		return par[u];
	}
	int pathQuery(int u, int v) {
		int w = query(u, v);
		int ret = 0;
		int log = 1;
		while ((1 << log) <= lvl[u])
			++log;
		--log;
		for (int i = log; i >= 0; --i)
			if (lvl[u] - (1 << i) >= lvl[w]) {
				// append path P[u][i] -> u
				ret = combine(ret, F[u][i]);
				u = P[u][i];
			}
		log = 1;
		while ((1 << log) <= lvl[v])
			++log;
		--log;
		for (int i = log; i >= 0; --i)
			if (lvl[v] - (1 << i) >= lvl[w]) {
				// append path P[v][i] -> v
				ret = combine(ret, F[v][i]);
				v = P[v][i];
			}
		return ret;
	}
};


