VEC(int) Bfs(VEC(VEC(int))& Edges, int src)
{
    const int N = Edges.size();
    queue<int> bfsQ;
    VEC(int) DistA(N, -1);
    auto Visit = [&](int node, int dist) {
        if (DistA[node] < 0) {
            DistA[node] = dist;
            bfsQ.push(node);
        }
    };

    Visit(src, 0);
    while (!bfsQ.empty()) {
        int node = bfsQ.front();
        bfsQ.pop();
        for (int next : Edges[node])
            Visit(next, DistA[node] + 1);
    }

    return DistA;
};

int main(int argc, char **argv)
{
    io_init();

    // Actual program code starts here.
    int N, T, A;
    cin >> N >> T >> A;
    T--; A--;
    VEC(VEC(int)) Edges(N);
    FOR(i, 0, N - 1) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        Edges[a].push_back(b);
        Edges[b].push_back(a);
    }

    VEC(int) DistT = Bfs(Edges, T), DistA = Bfs(Edges, A);

    auto check = [&](int t) {
        int mx = 0;
        FOR(i, 0, N)
            if (DistT[i] <= t && DistT[i] % 2 == t % 2)
                mx = max(mx, DistA[i]);

        return mx <= t ? mx : -1;
    };

    int lo = 1, hi = N - 1;
    while (hi - lo > 1) {
        int md = (lo + hi) / 2;
        if (check(md) >= 0)
            hi = md;
        else
            lo = md + 1;
    }

    if (check(lo) < 0)
        lo = hi;

    cout << check(lo) << endl;
    return 0;
};

