//Lowest Common Ancestor
//initがあるの注意
const ll MAX_V = 200010;
const ll MAX_LOG_V = 30;
vector<ll> G[MAX_V];
ll root = 0;//根のノード番号

ll parent[MAX_LOG_V][MAX_V];
//2^k回親をたどって到達する点
//根を通り過ぎる時は-1

ll depth[MAX_V];
void dfs_lca(ll v, ll p, ll d){
  parent[0][v] = p;
  depth[v] = d;
  for(ll to : G[v]){
    if(to == p) continue;
    dfs_lca(to, v, d + 1);
  }
}

void init_lca(ll V = 200009){
  dfs_lca(root, -1, 0);
  for(ll k = 0; k + 1 < MAX_LOG_V; k++){
    for(ll v = 0; v < V; v++){
      if(parent[k][v] < 0) parent[k+1][v] = -1;
      else parent[k+1][v] = parent[k][parent[k][v]];
    }
  }
}

//uとvのLCAを求める
ll lca(ll u, ll v){
  if(depth[u] > depth[v]) swap(u, v);
  for(ll k = 0; k < MAX_LOG_V; k++){
    if((depth[v] - depth[u]) >> k & 1){
      v = parent[k][v];
    }
  }
  if(u == v) return u;
  //二分探索でLCAを求める
  for(ll k = MAX_LOG_V - 1; k >= 0; k--){
    if(parent[k][u] != parent[k][v]){
      u = parent[k][u];
      v = parent[k][v];
    }
  }
  return parent[0][u];
}

ll N;
ll u, v;

ll dfs(ll now){
  ll res = depth[now];
  for(ll to: G[now]){
    if(depth[to] < depth[now]) continue;
    res = max(res, dfs(to));
  }
  return res;
}

void solve(){
  cin >> N;
  cin >> u >> v;
  u--, v--;
  root = v;
  rep(i, N-1){
    ll a, b;
    cin >> a >> b;
    a--, b--;
    G[a].pb(b);
    G[b].pb(a);
  }
  root = v;
  init_lca();

  ll ans = 0;
  rep(i, N){
    if(depth[i] != depth[u]) continue;
    ll LCA = lca(i, u);
    if(depth[LCA] - depth[u] < depth[LCA]){
      ans = max(ans, dfs(i) - 1);
    }
  }
  cout << ans << endl;
}


