int32_t calc_farthest(vector<int32_t>& distT, vector<int32_t>& distA) {
  int32_t farA = 0;
  int32_t minSame = 0;
  for (int32_t i = 0; i < (int32_t)distA.size(); i++) {
    if(farA < distA[i] && distA[i] > distT[i]) {
      //cout << i << "," << distA[i] << "," << distT[i] << endl;
      if (distA[i] > distT[i]) {
        farA = distA[i];
      }
    } else if (distA[i] == distT[i]) {
      if (minSame == 0) {
        minSame = distA[i];
      } else {
        minSame = min(minSame, distA[i]);
      }
    }
  }
  if (minSame > farA - 1) {
    return minSame;
  } else {
    return farA - 1;
  }
}

