  vector<bool> visited(dist.size(), false);
  queue<pair<int32_t,int32_t>> q;
  q.push(make_pair(start, 0));
  while (!q.empty()) {
    pair<int32_t,int32_t> cur = q.front();
    q.pop();
    if(visited[cur.first] == true) {
      continue;
    } else {
      visited[cur.first] = true;
      dist[cur.first] = cur.second;
    }
    if (!graph[cur.first].empty()) {
      for (auto next : graph[cur.first]) {
        if(!visited[next]) {
          q.push(make_pair(next, cur.second + 1));
        }
      }
    }
  }
  return;
}

