int dfs2(int pos, int bef, int d) {
	int ret = 0;
	for (int i = 0; i < edge[pos].size(); i++) {
		int nxt = edge[pos][i];
		if (nxt == bef)continue;
		if (saitanro[nxt])continue;
		ret = max(ret, dfs2(nxt, pos, d + 1));
	}
	if (ret == 0)return d;
	return ret;
}

