ll limit_v, ng_v;
VVL ds;

ll dfs(ll u, ll p) {
  ll res = ds[aV][u] - 1;

  for (ll v : edge_list[u]) {
    if (v == ng_v || v == p) continue;

    ll _res = dfs(v, u);
    chmax(res, _res);
  }

  return res;
}

void solve() {
