  ds = VVL(N, VL(N, INF));

  rep(from, N) {
    ds[from][from] = 0;

    for (ll to : edge_list[from]) {
      ds[from][to] = 1;
    }
  }

  // ワーシャルフロイド
  rep(k, N) rep(i, N) rep(j, N) {
    ds[i][j] = min(ds[i][j], ds[i][k] + ds[k][j]);
  }

  VL path(0);
