vll dijkstra(vvll &e, ll s) {
    ll n = e.size();
    vll d(n), used(n);
    queue<ll> que;
    d[s] = 0;
    used[s] = 1;
    que.push(s);
    while (!que.empty()) {
        ll cur = que.front();
        que.pop();
        for (auto nxt : e[cur]) {
            if (used[nxt]) continue;
            d[nxt] = d[cur] + 1;
            que.push(nxt);
            used[nxt] = 1;
        }
    }
    return d;
