		dist1[aoki] = 0;
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			for (auto u : g[v]) {
				if (dist1[u] > dist1[v] + 1) {
					dist1[u] = dist1[v] + 1;
					p1[u] = v;
					q.push(u);
				}
			}
		}
		vector<int>path;
		int fin = tak;
		while (fin != aoki) {
			path.push_back(fin);
			fin = p1[fin];
		}
		path.push_back(aoki);
		reverse(path.begin(), path.end());
		int gg = path[(int)path.size() / 2 - 1];
		set<int>forbidden;
		for (int i = (int)path.size() / 2; i < path.size(); i++) {
			forbidden.insert(path[i]);
		}
		q.push(gg);
		dist2[gg] = 0;
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			for (auto u : g[v]) {
				if (dist2[u] > dist2[v] + 1 && forbidden.find(u)==forbidden.end()) {
					dist2[u] = dist2[v] + 1;
					q.push(u);
				}
			}
		}
		int ans = 0;
		for (int i = 1; i <= n; i++) {
			if (dist2[i] != inf) {
				ans = max(ans, dist2[i]);
			}
		}
		cout << ans + path.size() / 2 - (!(path.size() % 2));
	}
};

