class DIJKSTRA {

  typedef long long ll;
  typedef std::pair<ll,ll> P;
  struct Edge { ll to; ll cost; };

  private:
    std::vector<std::vector<Edge>> G; // j-th Edge connected with vertex i : G[i][j]
    std::vector<ll> D;  // result
    std::vector<ll> C;  // # of paths
    bool directed;

  public:
    DIJKSTRA ( ll N , bool dir = false ) : directed (dir) {
      G.resize(N);
      D.assign(N, std::numeric_limits<ll>::max());
      C.assign(N, 0);
    }

    void Path ( ll i, ll j, ll x ) {
      G[i].push_back( {j,x} );
      if ( !directed ) G[j].push_back( {i,x} );
    }

    void Run (ll start) {
      std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
      pq.push( P(0, start) );
      D[start] = 0;
      C[start] = 1;
      while( !pq.empty() ) {
        auto cur = pq.top(); pq.pop();
        int d = cur.first;
        int v = cur.second;
        if ( D[v] < d ) continue;
        for(auto&& e : G[v]) {
          if ( D[e.to] > D[v] + e.cost ) {
            D[e.to] = D[v] + e.cost;
            pq.push( P(D[e.to], e.to) );
            C[e.to] = C[v];
          }
          else if ( D[e.to] == D[v] + e.cost ) C[e.to] += C[v];
        }
      }
      return;
    }

    ll Get ( ll i ){ return D[i]; }

    ll GetPaths ( ll i ) { return C[i]; }
};


int main (void) {
  std::cin.tie(0);  std::ios::sync_with_stdio(false);
  int N, u, v; std::cin >> N >> u >> v; u--, v--;
  std::vector<int> E(N), C(N);
  std::vector<std::vector<int>> G(N);
  rep(i,N-1) {
    int A, B; std::cin >> A >> B; A--,B--;
    G[A].push_back(B);
  }

  {
    DIJKSTRA dij(N);
    rep(i,N) for(auto&& e : G[i]) dij.Path(i,e,1);
    dij.Run(u);
    rep(i,N) E[i] = dij.Get(i);
  }
  {
    DIJKSTRA dij(N);
    rep(i,N) for(auto&& e : G[i]) dij.Path(i,e,1);
    dij.Run(v);
    rep(i,N) C[i] = dij.Get(i);
  }

  int dcmax = -1;
  for(int i=0; i<N; i++) {
    if ( E[i] < C[i] ) dcmax = std::max(dcmax, C[i]);
  }
  std::cout << dcmax - 1 << std::endl;
  return 0;
}

