    if (dis_s[i] < dis_t[i] and dis_s[i] > ds) {
      ds = dis_s[i];
      go = i;
    }
  }
  if (go == -1) {
    s = G[s][0];
    cout << (s != t) << '\n';
    return (0);
  }
  deque <int> p_s, p_t;
  int tmp = go;
  p_s.pb(tmp);
  while (tmp != s) p_s.pb(path_s[tmp]), tmp = path_s[tmp];
  tmp = go;
  p_t.pb(tmp);
  while (tmp != t) p_t.pb(path_t[tmp]), tmp = path_t[tmp];
  reverse(all(p_s));
  reverse(all(p_t));
  p_s.pop_front();
  p_t.pop_front();
  int prev = s;
  int ans = 0;
  while (s != go) {
    prev = s;
    s = p_s.front();
    t = p_t.front();
    p_s.pop_front();
    p_t.pop_front();
    ans++;
  }
  while (!p_t.empty()) {
    swap(prev, s);
    if (s == t) break;
    t = p_t.front();
    p_t.pop_front();
    ans++;
  }
  cout << ans << '\n';
  return (0);
}

