void bfs(vector<int64_t> &D, int64_t init)
{
  D[init] = 0;
  queue<int64_t> Q;
  Q.push(init);
  while (Q.size())
  {
    int64_t cur = Q.front();
    Q.pop();
    for (int i = 0; i < Graph[cur].size(); i++)
    {
      int64_t nxt = Graph[cur][i];
      if (D[nxt] != INF)
        continue;
      D[nxt] = D[cur] + 1;
      Q.push(nxt);
    }
  }
}

