const int MAXN = 100010;
const int LOG = 19;
struct HLD
{
    int n;
    vector<int> g[MAXN];
    int dep[MAXN];
    int prt[MAXN][LOG];
    void dfssz(int u, int p)
    {
        dep[u] = dep[p] + 1;
        prt[u][0] = p;
        for (int &v : g[u])
            if (v != p)
            {
                dep[v] = dep[u] + 1;
                dfssz(v, u);
            }
    }
    inline int lca(int a, int b)
    {
        if (dep[a] > dep[b])
            swap(a, b);
        int diff = dep[b] - dep[a];
        REPD(k, LOG - 1, 0)
        if (diff & (1 << k))
        {
            b = prt[b][k];
        }
        if (a == b)
            return a;
        REPD(k, LOG - 1, 0)
        if (prt[a][k] != prt[b][k])
        {
            a = prt[a][k];
            b = prt[b][k];
        }
        return prt[a][0];
    }
    void init(int _n)
    {
        n = _n;
        REP(i, 1, n)
        g[i].clear();
    }
    void addEdge(int u, int v)
    {
        g[u].push_back(v);
        g[v].push_back(u);
    }
    void yutruli()
    {
        dfssz(1, 0);
        REP(k, 1, LOG - 1)
        REP(i, 1, n)
        prt[i][k] = prt[prt[i][k - 1]][k - 1];
    }
    int dist(int x, int y)
    {
        int l = lca(x, y);
        return dep[x] + dep[y] - 2 * dep[l];
    }
} tree;

