bool close[MAXN];
int dp[MAXN];
int len;
void dfs(int now, int d, int fa)
{
    if (d <= len)
        close[now] = 1;
    dp[now] = d;
    for (int x : tree.g[now])
    {
        if (x == fa)
            continue;
        dfs(x, d + 1, now);
    }
}
int D;
void search(int now, int d, int fa)
{
    if (close[now])
        return;
    if (dp[now] > dp[D])
        D = now;
    for (int x : tree.g[now])
    {
        if (x == fa)
            continue;
        search(x, d + 1, now);
    }
}

