bool path(int now, int fa, int tt, vector<int> &v)
{
    if (now == tt)
    {
        v.push_back(now);
        return 1;
    }
    for (int x : tree.g[now])
    {
        if (x == fa)
            continue;
        if (path(x, now, tt, v))
        {
            v.push_back(now);
            return 1;
        }
    }
    return 0;
}

