  vector<T> distance;
  vector<sl> prev;

  Dijkstra(const sl& N, const sl& start, const vector<vector<DirectedEdge<T>>>& edges) {
    priority_queue<pair<T, sl>, vector<pair<T, sl>>, greater<pair<T, sl>>> que;
    distance.resize(N);
    prev.resize(N);
    FOR0(i, N) {
      if (i == start) {
        distance[start] = 0;
        prev[start] = start;
      } else {
        distance[i] = INF;
        prev[i] = numeric_limits<sl>::max();
      }
      que.emplace(distance[i], i);
    }
    while (!que.empty()) {
      auto u = que.top().second;
      que.pop();
      FORITER(edges[u], it) {
        sl v = it->to;
        T new_cost = distance[u] + it->cost;
        if (distance[v] > new_cost) {
          distance[v] = new_cost;
          prev[v] = u;
          que.emplace(new_cost, v);
        }
      }
    }
  }
};

static sl N, U, V;
vector<vector<DirectedEdge<sl>>> E;

void solve(void) {
  Dijkstra<sl> d(N, V, E); // from Aoki
  Dijkstra<sl> e(N, U, E); // from Takahashi
  if (U == V || (E[U].size() == 1 && E[U][0].to == V)) {
    cout << 0 << endl;
    return;
  }
  sl max_cost = 0;
  FOR0(i, N) {
    if (e.distance[i] != Dijkstra<sl>::INF) {
      if (d.distance[i] == Dijkstra<sl>::INF || d.distance[i] > e.distance[i]) {
        max_cost = max(max_cost, d.distance[i]) - 1;
      }
    }
  }
  cout << max_cost << endl;
}

int main(void) {
  cin >> N >> U >> V;
  U -= 1;
  V -= 1;
  E.resize(N);
  sl A, B;
  FOR0(i, N - 1) {
    cin >> A >> B;
    A -= 1;
    B -= 1;
    E[A].emplace_back(B, 1);
    E[B].emplace_back(A, 1);
  }
  solve();
  return 0;
}

