void bfs(int s, int *dep){
    queue<int> q;
    bool used[N];
    fill(used,used+N,false);
    for(int i=0;i<N;i++){
        dep[i] = -1;
    }
    q.push(s);
    dep[s]=0;
    while(!q.empty()){
        int u=q.front(); q.pop();
        used[u]=true;
        for(int i=0;i<G[u].size();i++){
            int v=G[u][i];
            if(!used[v]){
                q.push(v);
                dep[v] =dep[u]+1;
            }
        }
    }
}



