bool dfs(int x,int pa)
{
	pp[x][0]=pa;
	for(int i=1;i<20;i++)
		pp[x][i]=pp[pp[x][i-1]][i-1];
	dep[x]=1;
	f[x]=(x==u);
	for(int i:adj[x])
	{
		if(i==pa)continue;
		hi[i]=hi[x]+1;
		f[x]|=dfs(i,x);
		dep[x]=max(dep[x],1+dep[i]);
	}
	mxdp=max(mxdp,dep[x]);
	return f[x];
}

int ispa(int x,int y)
{
	if(hi[x]<hi[y])
		swap(x,y);
	for(int i=19;i>=0;i--)
	{
		if(hi[x]-(1<<i)>=hi[y])
		{
			x=pp[x][i];
		}
	}
	if(x==y) return 1;
	return 0;
}

