void createAoki(int cur, int dist) {
  aoki[cur] = dist;
  for (int i = 0; i < t[cur].size(); i++) {
    int next = t[cur][i];
    if (aoki[next] == -1) {
      createAoki(next, dist + 1);
    }
  }
