void solve(int cur, int pre, int dist) {
  if (aoki[cur] >= dist) {
    if (dist % 2 == aoki[cur] % 2) {
      ans = max(ans, dist);
    } else {
      ans = max(ans, dist - 1);
    }
  }
  if (aoki[cur] <= dist) {
    return;
  }
  if (t[cur].size() == 1) {
    int distPre = aoki[t[cur][0]];
    ans = max(ans, distPre);
  }
  ans = max(ans, dist);
  for (int i = 0; i < t[cur].size(); i++) {
    int next = t[cur][i];
    if (pre != next) {
      solve(next, cur, dist + 1);
    }
  }
}

