int bfs(const vvi &tree, vi &dist, int N, int start)
{
    dist.resize(N);
    fill(begin(dist), end(dist), -1);

    queue<int> next;
    dist[start] = 0;
    next.push(start);

    int longest;
    while (!next.empty())
    {
        int cp = next.front(); next.pop();
        for (int i = 0; i < N; i++)
        {
            if (tree[cp][i] && dist[i] < 0)
            {
                dist[i] = dist[cp] + 1;
                next.push(i);
                longest = i;
            }
        }
    }
    return longest;
}

