class Solve
{
  int N;
  int takahashi, aoki;
  vector<vector<Edge>> V;

public:
  Solve(int N) : N{N}
  {
    cin >> takahashi >> aoki;
    --takahashi;
    --aoki;
    V = ReadTree(N);
  }

  void flush()
  {
    vector<int> DAoki(N), DTakahashi(N);
    DAoki[aoki] = 0;
    dfs(aoki, DAoki);
    DTakahashi[takahashi] = 0;
    dfs(takahashi, DTakahashi);
    int ans{0};
    for (auto i{0}; i < N; ++i)
    {
      if (DAoki[i] >= DTakahashi[i])
      {
        ch_max(ans, DAoki[i]);
      }
    }
    cout << ans - 1 << endl;
  }

private:
  void dfs(int src, vector<int> &D, int parent = -1)
  {
    for (auto e : V[src])
    {
      if (e.dst != parent)
      {
        D[e.dst] = D[src] + 1;
        dfs(e.dst, D, src);
      }
    }
  }
};

