        --a, --b;
        g[a].emplace_back(b, 1);
        g[b].emplace_back(a, 1);
    }

    dijkstra(dist, prev_idx, g, V);

    tami.resize(N);
    checked.resize(N);
    checked[V] = 1;
    dfs(V);

    int ad = (dist[U] - 1) / 2;

    int max_tami = tami[U];
    int tmpU = U;
    for (int i = 0; i < ad; ++i) {
        tmpU = prev_idx[tmpU];
        max_tami = max(max_tami, tami[tmpU]);
    }

    cout << max_tami - 1 << endl;

    return 0;
}

