using namespace std;

void dfs(int root, vector<vector<int> > graph, int n, vector<int>& dis) {
	stack<int>order;
	vector<bool>seen(n, false);
	order.push(root);
	while (!order.empty()) {
		int now = order.top();
		order.pop();
		seen[now] = true;
		for (int i = 0; i < graph[now].size(); i++) {
			if (!seen[graph[now][i]]) {
				order.push(graph[now][i]);
				dis[graph[now][i]] = dis[now] + 1;
			}
		}
	}
}

void solve() {
	int n, u, v, ans = 0; cin >> n >> u >> v; u--; v--;
	int t;
	vector<vector<int> >graph(n);
	vector<int>t_dis(n), a_dis(n);
	for (int i = 0; i < n - 1; i++) {
		int a, b; cin >> a >> b;
		a--; b--;
		graph[a].emplace_back(b);
		graph[b].emplace_back(a);
	}
	dfs(u, graph, n, t_dis);
	dfs(v, graph, n, a_dis);
	for (int i = 0; i < n; i++) {
		if (a_dis[i] - t_dis[i] > 0) {
			if (ans < a_dis[i]) {
				ans = a_dis[i];
			}
		}
	}
	cout << ans - 1 << endl;
}

int main() {
	solve();
}

