int n, u, v, a, b, dist[100010];
vector<int> g[100010];

void rec1(int v, int p, int d) {
	dist[v] = d;

	for(int nv : g[v]) {
		if (nv == p) continue;
		rec1(nv, v, d + 1);
	}
}

int rec2(int v, int p, int d) {
	if (d >= dist[v]) return 0;

	int res = dist[v] - 1;
	for (int nv : g[v]) {
		if (nv == p) continue;
		res = max(res, rec2(nv, v, d + 1));
	}
	return res;
}

