pair<vector<length>,vector<int>> pfs(Weighted& g,int s,length infinity=linf){
	vector<int> prv(g.size());
	vector<length> d(g.size());fill(all(d),linf);
	using cont=pair<length,int>;
	priority_queue<cont,vector<cont>,greater<cont> > q;

	d[s]=0;q.push({0,s});
	int cv; length cd;
	while(q.size()){
		cd=q.top().first;
		cv=q.top().second;
		q.pop();
		if(cd>d[cv])continue;
		for(edge &e:g[cv])if(d[e.to]>cd+e.cost){
			d[e.to]=cd+e.cost;
			prv[e.to]=cv;
			q.push({d[e.to],e.to});
		}
	}
	return pair<vector<length>,vector<int>>(d,prv);
