int bfs(int n, int a, int b){
    memset(disb, -1, sizeof(disb));
    queue<int> q;
    q.push(b);
    disb[b] = 0;

    int max_len = 0;
    while (!q.empty()) {
        int cur = q.front();
        q.pop();

        for (int i=0; i < v[cur].size(); i++) {
            int tmp = v[cur][i];
            if (disb[tmp]==-1) {
                disb[tmp] = disb[cur] + 1;
                max_len = max(max_len, disb[tmp]);
                q.push(tmp);
            }
        }   
    }

    memset(flag, 0, sizeof(flag));
    memset(disa, -1, sizeof(disa));
    q.push(a);
    flag[a] = 1;
    disa[a] = 0;
    int ans = 0;
    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        flag[cur] = 0;

        for (int i=0; i < v[cur].size(); i++) {
            int tmp = v[cur][i];
            if (disa[cur] + 1 < disb[tmp]) {
                if (flag[tmp]==0) {
                    q.push(tmp);
                    flag[tmp] = 1;
                }
                disa[tmp] = disa[cur] + 1;
                ans = max(ans, disa[tmp]);
            } else if (disb[tmp]== disa[cur] + 1) {
                ans = max(ans, disb[tmp]);
            }

            if (disb[tmp]==max_len) {
                    break;
            }
        }
    }
    return ans;
}

