void searchPath(int t, vector<vector<int>> ki){
  if(t == takahashi){
    correctPath = true;
    return;
  }
  for(int i = 0; i < ki.at(t).size(); i++){
    int to = ki.at(t).at(i);
    if(used.count(to)){
      continue;
    }
    used.insert(to);
    searchPath(to, ki);
    if(correctPath){
      route.push_back(to);
      return;
    }
  }
  return;
}

void longestPath(int t, vector<vector<int>> ki, int steps){
  //cout << "t:" << t << " steps:" << steps <<endl;
  if(steps > Max){
    Max = steps;
  }
  for(int i = 0; i < ki.at(t).size(); i++){
    int to = ki.at(t).at(i);
    if(used2.count(to)){
      //cout << "continue" <<endl;
      continue;
    }
    used2.insert(to);
    longestPath(to, ki, steps + 1);
  }
  return;
}

