class FPlayingTagOnTree {
    vector<vector<int>> edges_;

    void fillDepth(const int prev, const int cur, const int depth, vector<int>& leafDepth) {
        if (edges_[cur].size() == 1 && edges_[cur].front() == prev) {
            leafDepth[cur] = depth;
            return;
        }
        for (const auto& next : edges_[cur]) {
            if (next == prev) continue;
            fillDepth(cur, next, depth+1, leafDepth);
        }
    }
public:
	void solve(std::istream& in, std::ostream& out) {
	    int N, u, v;
	    in >> N >> u >> v;
	    vector<int> A(N), B(N);
	    REP(i,1,N) in >> A[i] >> B[i];
	    edges_ = vector<vector<int>> (N+1);
	    REP(i,1,N) {
	        edges_[A[i]].emplace_back(B[i]);
	        edges_[B[i]].emplace_back(A[i]);
	    }
	    vector<int> leafDepthU(N+1), leafDepthV(N+1);
	    fillDepth(-1, u, 0, leafDepthU);
	    fillDepth(-1, v, 0, leafDepthV);
	    int answer = 0;
        REP(i,1,N+1) {
            if (leafDepthU[i] == 0 && leafDepthV[i] == 0 || leafDepthU[i] >= leafDepthV[i]) continue;
            answer = max(answer, leafDepthV[i] - 1);
        }
        out << answer << "\n";
	}
};


