vector<int> height;
vector<int> bestch;

void rec(int v, int d = 0, int p = -1) {
    par[v] = p;
    depth[v] = d;
    height[v] = 0;
    for (auto ch : G[v]) {
        if (ch == p) continue;
        rec(ch, d+1, v);
    }
    for (auto ch : G[v]) {
        if (chmax(height[v], height[ch] + 1)) {
            bestch[v] = ch;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    while (cin >> N >> v >> r) {
        --v, --r;
