        height.resize(N);
        bestch.assign(N, -1);
        for (int i = 0; i < N-1; ++i) {
            int a, b; cin >> a >> b; --a, --b;
            G[a].push_back(b);
            G[b].push_back(a);
        }

        rec(r);

        //COUT(par);COUT(bestch);COUT(depth);

        int res = 0;
        while (true) {
            // 上へ
            if (depth[v] > res + 2) {
                v = par[v];
                ++res;
            }
