                    else {
                        ++res;
                        break;
                    }
                }
                else {
                    v = bestch[v];

                    if (depth[v] == res) break;

                    ++res;

                    if (depth[v] == res) break;
                }
            }

            //cout << v << "(" << depth[v] << "), " << res << endl;
        }
