int dfs(int from, int par, int goal) {
	if(from == goal) {
		route[from] = 1;
		return 1;
	}
	used[from] = true;
	int ret = 0;
	for(int to : edge[from]) {
		if(to == par) {
			continue;
		}
		if(not used[to]) {
			int tmp = dfs(to, from, goal);
			ret += tmp;
		}
	}
	if(ret > 0) {
		route[from] = ret + 1;
		return ret + 1;
	}
	return ret;
}
int dfs1(int from, int par) {
	int ret = 0;
	used[from] = true;
	for(int to : edge[from]) {
		if(route[to] != -1) continue;
		if(not used[to]) ret = max(ret, dfs1(to, from));
	}
	return ret + 1;
}
