void dfs(int x, int p, int d){
    tin[x] = t++;

    ancestor[0][x] = p;
    for (int i = 1; i < 20; i++)
        ancestor[i][x] = ancestor[i - 1][ancestor[i - 1][x]];

    dist[x] = d;
    for (int i = 0; i < adj[x].size(); i++)
        if (adj[x][i] != p)
            dfs(adj[x][i], x, d + 1);

    tout[x] = t;
}

bool is_ancestor(int x, int y){
    if (x == 0 || y == 0)
        return true;
    return tin[x] <= tin[y] && tout[x] >= tout[y];
}

int lca(int x, int y){
    if (is_ancestor(x, y))
        return x;
    if (is_ancestor(y, x))
        return y;
    for (int i = 19; i >= 0; i--)
        if (!is_ancestor(ancestor[i][x], y))
            x = ancestor[i][x];
    return ancestor[0][x];
}

