#define Inf 100000000

vector<int> get_dis(vector<vector<int>> &E,int start){
	vector<int> dis(E.size(),Inf);
	dis[start] = 0;
	queue<int> Q;
	Q.push(start);

	while(Q.size()!=0){
		int from = Q.front();
		Q.pop();
		for(int i=0;i<E[from].size();i++){
			int to = E[from][i];
			if(dis[to]!=Inf)continue;
			dis[to] = dis[from] + 1;
			Q.push(to);
		}
	}

	return dis;
}


