void dfs(ll u,ll par)
{
    h[u]=0;
    p[u][0]=par;
    lvl[u]=lvl[par]+1;
    for(auto v : adj[u])
    {
        if(v==par) continue;
        dfs(v,u);
        h[u]=max(h[u],h[v]+1);
    }
}
ll lca(ll u,ll v)
{
    ll i,lg;
    if(lvl[u]<lvl[v])swap(u,v);
    for(lg=0;(1<<lg)<=lvl[u];lg++);
    lg--;
    for(i=lg;i>=0;i--)
    {
        if((lvl[u]-(1<<i))>=lvl[v])
        u=p[u][i];
    }
    if(u==v) return u;
    for(i=lg;i>=0;i--)
    {
        if(p[u][i]!=-1&&p[u][i]!=p[v][i]){
            u=p[u][i];v=p[v][i];
        }
    }
    return p[u][0];
}
ll getAncestor(ll u,ll dis)
{
    dis=lvl[u]-dis;
    ll i,lg;
    for(lg=0;(1<<lg)<=lvl[u];lg++);
    lg--;
    for(i=lg;i>=0;i--)
    {
        if(lvl[u]-(1<<i)>=dis)
        u=p[u][i];
    }
    return u;
}
ll dis(ll u,ll v)
{
    if(lvl[u]<lvl[v]) swap(u,v);
    ll w=lca(u,v);
    return lvl[u]+lvl[v]-2*lvl[w];
}

