class Graph {
 private:
  vvl g;
  ll root;
  vvl parent;
  vl depth;
  ll n;
  ll logn;

 public:
  Graph(ll n, ll r) : n(n), g(n), root(r), depth(n) {
    logn = 0;
    ll tmp = 1;
    while (tmp < n) {
      logn++;
      tmp *= 2;
    }
    parent = vvl(logn, vl(n));
  }

  void addEdge(ll u, ll v) {
    g[u].push_back(v);
    g[v].push_back(u);
  }

  void dfs(ll v, ll p, ll d) {
    parent[0][v] = p;
    depth[v] = d;
    rep(i, g[v].size()) {
      if (g[v][i] != p) dfs(g[v][i], v, d + 1);
    }
  }

  void init() {
    dfs(root, -1, 0);
    rep(k, logn - 1) {
      rep(v, n) {
        if (parent[k][v] < 0)
          parent[k + 1][v] = -1;
        else
          parent[k + 1][v] = parent[k][parent[k][v]];
      }
    }
  }

  ll getDist(ll v) { return depth[v]; }
};

class UnionFind {
 protected:
  vi data;

 public:
  UnionFind(int size) : data(size, -1) {}
  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x != y) {
      if (data[y] < data[x]) {
        swap(x, y);
      }
      data[x] += data[y];
      data[y] = x;
    }
    return x != y;
  }
  bool same(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

