        cout << x << ' ';
    cout << endl;
    cout << "q = ";
    for (auto x : q)
        cout << x << ' ';
    cout << endl;
#endif
    int ans = 0, x = 0, y = 0;
    int Psize = p.size();
    int Qsize = q.size();

    while (y < Qsize - 1)
    {
        if (x < Psize - 1)
            ++x;
        else
            x = Psize - 2;
#ifdef DEBUG
    cout << "Takahashi foi para " << p[x] << endl;
#endif
        if (p[x] == q[y])
            return ans;

        ++ans;
        ++y;

#ifdef DEBUG
