        x = parent[x];
        max_root.insert(x);
    }

    if ((max_root.count(u)) || (max_depth.first == depth[u])) {
        cout << max_depth.first - 1 << endl;
        return 0;
    }

    x = parent[u];
    while (!max_root.count(x)) x = parent[x];

    if (depth[x] > depth[u] - depth[x]) {
        cout << max_depth.first - 1 << endl;
        return 0;
    }

    max_depth.first = depth[u];
    max_depth_under_u(u);
    cout << max_depth.first - 1 << endl;
}

