vector<vector<ll>> net;

void calc_dist(ll src, vector<ll>& out){
    out.resize(net.size());
    fill(out.begin(), out.end(), -1);
    out.at(src) = 0;
    queue<ll> que;
    que.push(src);
    while(!que.empty()){
        ll cur = que.front(); que.pop();
        for(auto nxt : net.at(cur)){
            if(out.at(nxt) == -1){
                out.at(nxt) = out.at(cur) + 1;
                que.push(nxt);
            }
        }
    }
}

void solve(long long N, long long u, long long v, std::vector<long long> A, std::vector<long long> B){
    net.resize(N);
    u--; v--;
    REP(i, N - 1){
        ll a = A.at(i) - 1;
        ll b = B.at(i) - 1;
        net.at(a).push_back(b);
        net.at(b).push_back(a);
    }

    vector<ll> distu, distv;
    calc_dist(u, distu);
    calc_dist(v, distv);

    ll tgt_dist = -1;
    ll tgt = -1;
    REP(i, N){
        if(distu.at(i) < distv.at(i) && tgt_dist < distv.at(i)){
            tgt = i;
            tgt_dist = distv.at(i);
        }
    }

    cout << tgt_dist - 1 << endl;
}

