int dfs1(int u, vector<vector<int>>& graph, vector<int>& dist1, vector<int>& dist2){
  int n = (int)graph.size();

  stack<int> s;
  s.push(u);

  int max_dist = dist2[u];
  int max_dist_node = u;

  while(!s.empty()){
    int node = s.top();
    s.pop();
    for(int i : graph[node]){
      if(dist2[i] <= dist1[node] + 1) continue;
      if(dist1[i] != -1) continue;
      dist1[i] = dist1[node] + 1;
      if(max_dist < dist2[i]){
        max_dist = dist2[i];
        max_dist_node = i;
      }
      s.push(i);
    }
  }

  return max_dist_node;
}

