int des[100010];
bool des_f[100010];
void Des(int i){//最下層計算
    if(!des_f[i]){
        if(s[i].empty()){des[i]=0;des_f[i]=true;}
        else{
            vector<int> v=s[i];
            int max=0;
            while(!v.empty()){
                int k=v.back();
                v.pop_back();
                if(!des_f[k]){Des(k);}
                if(max<des[k]){max=des[k];}
            }
            des[i]=max+1;
            des_f[i]=true;
        }
    }
}


