using namespace std;
vector<int> search2(map<int, vector<int>> &g, int u, int n)
{
    deque<pair<int, int>> que;
    que.clear();
    map<int, bool> used;
    used.clear();
    que.push_back({u, 0});
    vector<int> ret(n, -1);
    while (!que.empty())
    {
        int cur = que.front().first, cost = que.front().second;
        que.pop_front();
        if (used[cur] == true)
        {
            continue;
        }
        ret[cur] = cost;
        used[cur] = true;

        for (auto x : g[cur])
        {
            que.push_back({x, cost + 1});
        }
    }
    return ret;
}

