        //cerr << "*" << a << b << endl;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    auto udist = search2(g, u, n);
    auto vdist = search2(g, v, n);
    int ans = -1;
    rep(i, n)
    {
        if (udist[i] > vdist[i])
        {
