int dfs(VVI &es, VI &d, VI &par, int i, int cnt = 0) {
    d[i] = cnt;
    int mv = 1;
    for (const int &dst: es[i]) {
        if (dst == par[i]) continue;
        par[dst] = i;
        mv = max(mv, dfs(es,d,par,dst,cnt+1));
    }
    return 0;
    //return d[i] = mv;
}

int getd(VVI &es, VI &d, VI &par, int i) {
    int ret = d[i];
    for (const int &dst: es[i]) {
        if (dst == par[i]) continue;
        ret = max(ret, getd(es,d,par,dst));
    }
    return ret;
}

void solve() {
    int n,u,v;
    cin >> n >> u >> v;
    --u; --v;
    VVI es(n);
    int a,b;
    REP(i,0,n-1) {
        cin >> a >> b;
        --a; --b;
        es[a].push_back(b);
        es[b].push_back(a);
    }
    VI par(n, -1), d(n);
    dfs(es,d,par,u);

    int pp = v;
    while (par[pp] != u) pp = par[pp];
    int ans = d[v] - 1;
    for (const int &dst: es[u]) {
        if (dst == pp) continue;
        int gd = getd(es,d,par,dst);
        ans = max(ans, gd + d[v] - 1);
    }

    int td = (d[v] - 1) / 2 + 1;
    //dump(td);
    //dump(d[v]);
    //dump(ans);
    int t = v, prev = -1;
    while (d[t] != td) {
        prev = t;
        t = par[t];
