using namespace std;

int const maxn = 1e5 + 5, logg = 20;
vector < int > g[maxn];
int h[maxn], was[maxn], H[maxn], mxh[maxn];
int dp[maxn][logg];

void dfs(int v, int p) {
    dp[v][0] = p;
    h[v] = h[p] + 1;
    mxh[v] = h[v];
    for (int i = 1; i < logg; ++i) dp[v][i] = dp[dp[v][i - 1]][i - 1];
    for (auto u : g[v]) if (u != p) dfs(u, v), mxh[v] = max(mxh[v], mxh[u]);
}

int get_la(int u, int x) {
    for (int i = 0; i < logg; ++i) {
        if ((x&(1 << i)) > 0) u = dp[u][i];
    }
    return u;
}

int get_lca(int v, int u) {
    if (h[v] > h[u]) v = get_la(v, h[v] - h[u]);
    else u = get_la(u, h[u] - h[v]);
    if (u == v) return u;
    for (int i = logg - 1; i >= 0; --i) {
        if (dp[u][i] != dp[v][i]) u = dp[u][i], v = dp[v][i];
    }
    return dp[u][0];
}

int get(int v) {
    for (auto u : g[v]) {
        if (dp[v][0] != u && mxh[u] == mxh[v]) {
            return get(u);
        }
    }
    return v;
}

void dfs1(int v, int hh) {
    was[v] = 1;
    H[v] = hh;
    for (auto u : g[v]) {
        if (was[u] != 0) continue;
        dfs1(u, hh + 1);
    }
}

