struct tree{
  vector<vector<int>> G,son,ancestor;
  vector<int> depth,parent;
  queue<int> que;
  int root=-1;
  bool made_lca=false;

  tree(int n):G(n),son(n),parent(n,-1),depth(n,0),ancestor(n){
    for(int i=0;i<n;i++)ancestor[i].resize(30);
  }

  void add_edge(int u,int v){
    G[u].push_back(v);
    G[v].push_back(u);
  }

  void have_root(int r){
    root=r;
    depth[r]=-1;
    que.push(r);
    while(que.size()){
      int p=que.front();que.pop();
      for(int q:G[p]){
        if(parent[p]==q)continue;
        son[p].push_back(q);
        parent[q]=p;
        que.push(q);
      }
    }
  }

  void set_depth(){
    assert(~root);
    depth[root]=0;
    que.push(root);
    while(que.size()){
      int p=que.front();que.pop();
      for(int q:son[p]){
        depth[q]=depth[p]+1;
        que.push(q);
      }
    }
  }

  inline void make_lca(){
    assert(~root);
    if(depth[root]<0)set_depth();
    for(auto p:ancestor)for(auto &q:p)q=-1;
    for(int i=0;i<G.size();i++)ancestor[i][0]=parent[i];
    for(int j=1;j<30;j++)
      for(int i=0;i<G.size();i++)
        if(~ancestor[i][j-1])
          ancestor[i][j]=ancestor[ancestor[i][j-1]][j-1];
    made_lca=true;
  }

  int lca(int u,int v){
    if(!made_lca)make_lca();
    if(depth[u]>depth[v])swap(u,v);
    int diff=depth[v]-depth[u],cnt=0;
    while(diff){
      if(diff&1)v=ancestor[v][cnt];
      cnt++;
      diff>>=1;
    }
    if(u==v)return u;
    int high=25,low=-1;
    for(int k=25;k>=0;k--)if(ancestor[u][k]!=ancestor[v][k])u=ancestor[u][k],v=ancestor[v][k];
    return ancestor[u][0];
  }

};
signed main(){
  int n;cin>>n;int u,v;cin>>u>>v;u--;v--;swap(u,v);
  tree t(n);
  for(int i=1;i<n;i++){
    int a,b;cin>>a>>b;a--;b--;
    t.add_edge(a,b);
  }
  t.have_root(u);
  int ans=0;
  for(int i=0;i<n;i++){
    if(t.lca(i,v)==u)continue;
    int a=t.lca(i,v);
    if(t.depth[v]-t.depth[a]>t.depth[a])continue;
    //cout<<"I"<<i<<endl;
    chmax(ans,t.depth[i]-1);
  }
  cout<<ans<<endl;
}

