        int a, b;
        cin >> a >> b;
        a--, b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    lca L(edge, u);
    vector<int> d(n, -1);
    queue<int> que;
    que.push(u);
    d[u] = 0;
    while(!que.empty()) {
        int now = que.front();
        que.pop();
        for(auto next : edge[now]) {
            if(d[next] == -1) {
                d[next] = d[now] + 1;
                que.push(next);
            }
        }
    }
    ll M = 0;
    for(int i = 0; i < n; i++) {
        if(d[i] + d[v] - 2 * d[L.get(i, v)] > M) {
            if(d[u] - d[L.get(i, v)] < d[v] - d[L.get(i, v)]) {
                M = d[i] + d[v] - 2 * d[L.get(i, v)];
            }
        }
    }
