struct LCA {
    vector<int> height, euler, first, segtree;
    vector<bool> visited;
    int n;

    LCA(vector<vector<int>> &adj, int root = 0) {
        n = adj.size();
        height.resize(n);
        first.resize(n);
        euler.reserve(n * 2);
        visited.assign(n, false);
        dfs(adj, root);
        int m = euler.size();
        segtree.resize(m * 4);
        build(1, 0, m - 1);
    }

    void dfs(vector<vector<int>> &adj, int node, int h = 0) {
        visited[node] = true;
        height[node] = h;
        first[node] = euler.size();
        euler.push_back(node);
        for (auto to : adj[node]) {
            if (!visited[to]) {
                dfs(adj, to, h + 1);
                euler.push_back(node);
            }
        }
    }

    void build(int node, int b, int e) {
        if (b == e) {
            segtree[node] = euler[b];
        } else {
            int mid = (b + e) / 2;
            build(node << 1, b, mid);
            build(node << 1 | 1, mid + 1, e);
            int l = segtree[node << 1], r = segtree[node << 1 | 1];
            segtree[node] = (height[l] < height[r]) ? l : r;
        }
    }

    int query(int node, int b, int e, int L, int R) {
        if (b > R || e < L)
            return -1;
        if (b >= L && e <= R)
            return segtree[node];
        int mid = (b + e) >> 1;
        int left = query(node << 1, b, mid, L, R);
        int right = query(node << 1 | 1, mid + 1, e, L, R);
        if (left == -1) return right;
        if (right == -1) return left;
        return height[left] < height[right] ? left : right;
    }

    int lca(int u, int v) {
        int left = first[u], right = first[v];
        if (left > right)
            swap(left, right);
        return query(1, 0, euler.size() - 1, left, right);
    }

    int dist(int u,int v){
        int lc = lca(u,v);
        return height[u]+height[v]-2*height[lc];
    }
};

int32_t main(){
	int n,a,b;
	cin>>n>>a>>b;
	--a;--b;
	if(a==b){
		cout << "0\n";
		return 0;
	}
	g.resize(n);
	for(int i=0;i<n-1;++i){
		int u,v;cin>>u>>v;
		u--;v--;
		g[u].push_back(v);
		g[v].push_back(u);
	}
	LCA t(g);
	int ans=t.dist(a,b)/2;
	for(int i=0;i<n;++i){
		int mid = t.lca(i,b);
		if(mid == t.lca(i,a) && t.dist(mid,a)<=t.dist(mid,b)){
			ans = max(ans,min(t.dist(mid,b),t.dist(a,mid)));
			continue;
		}
		ans = max(ans,min(t.dist(i,a),t.dist(i,b)));
	}
	cout << ans << endl;
	return 0;
}

