constexpr int N = 1e5 + 5;

int dist[N];
vector< int> conn[N];

void dfs(int a, int prt, int d) {
    dist[a] = d;
    for (int &b : conn[a]) {
        if (b == prt) continue;
        dfs(b, a, d + 1);
    }
}

int dfs2(int a, int di) {
    int rv = -1;
    for (const int& b : conn[a]) {
        if (dist[b] == di or dist[b] == di + 1) {
            rv = max(rv, dist[b]);
        } else if (dist[b] > di + 1) {
            rv = max(rv, dfs2(b, di + 1));
        }
    }
    return rv;
}

