int main() {
    ll n, u, v; cin >> n >> u >> v;
    vector<vector<ll> > G(n);
    ll a, b;
    for (ll i = 0; i < n-1; i++) {
        cin >> a >> b;
        G[a-1].push_back(b-1);
        G[b-1].push_back(a-1);
    }

    queue<ll> q;
    ll *du = new ll[n];
    for (ll i = 0; i < n; i++)
        du[i] = -1;
    du[u-1] = 0;

    bool *check = new bool[n];
    check[v-1] = true;
    q.push(u-1);
    while (!q.empty()) {
        ll x = q.front();
        for (ll i = 0; i < G[x].size(); i++) {
            ll p = G[x][i];
            if (du[p] >= 0)
                continue;
            du[p] = du[x] + 1;
            q.push(p);
        }
        q.pop();
    }

    ll *dv = new ll[n];
    for (ll i = 0; i < n; i++)
        dv[i] = -1;
    dv[v-1] = 0;

    check[v-1] = true;
    q.push(v-1);
    while (!q.empty()) {
        ll x = q.front();
        for (ll i = 0; i < G[x].size(); i++) {
            ll p = G[x][i];
            if (dv[p] >= 0)
                continue;
            dv[p] = dv[x] + 1;
            q.push(p);
        }
        q.pop();
    }


    ll g = u-1;
    for (ll i = 0; i < n; i++) {
        if (du[i] <= dv[i] && du[i] > du[g])
            g = i;
    }

    cout << dv[g] - 1 << endl;
    return 0;
}

