    friend ostream& operator<<(ostream &out, const Graph &g) {
        for (int i = 0; i < g.size(); ++i) {
            out << '[' << setw(2) << i << ']';
            for (const auto &e : g[i]) {
                out << ' ' << setw(2) << e.to;
            }
            out << '\n';
        }
        return out;
    }
}; // }}}
