//Lowest Common Ancestor
//initがあるの注意
const ll MAX_V = 200010;
const ll MAX_LOG_V = 30;
vector<ll> G[MAX_V];
ll root = 0;//根のノード番号

ll parent[MAX_LOG_V][MAX_V];
//2^k回親をたどって到達する点
//根を通り過ぎる時は-1

ll depth[MAX_V];
void dfs_lca(ll v, ll p, ll d){
  parent[0][v] = p;
  depth[v] = d;
  for(ll to : G[v]){
    if(to == p) continue;
    dfs_lca(to, v, d + 1);
  }
}

void init_lca(ll V = 200009){
  dfs_lca(root, -1, 0);
  for(ll k = 0; k + 1 < MAX_LOG_V; k++){
    for(ll v = 0; v < V; v++){
      if(parent[k][v] < 0) parent[k+1][v] = -1;
      else parent[k+1][v] = parent[k][parent[k][v]];
    }
  }
}

//uとvのLCAを求める
ll lca(ll u, ll v){
  if(depth[u] > depth[v]) swap(u, v);
  for(ll k = 0; k < MAX_LOG_V; k++){
    if((depth[v] - depth[u]) >> k & 1){
      v = parent[k][v];
    }
  }
  if(u == v) return u;
  //二分探索でLCAを求める
  for(ll k = MAX_LOG_V - 1; k >= 0; k--){
    if(parent[k][u] != parent[k][v]){
      u = parent[k][u];
      v = parent[k][v];
    }
  }
  return parent[0][u];
}




ll N;
ll u, v;
vector<pair<ll, ll>> dist;

void dfs(ll now, ll from, ll id){
  for(ll to:G[now]){
    if(to == from) continue;
    if(id == 1){
      dist[to].f = dist[now].f + 1;
    }
    if(id == 2){
      dist[to].s = dist[now].s + 1;
    }
    dfs(to, now, id);
  }
}

void solve(){
  cin >> N;
  cin >> u >> v;
  root = v;
  u--, v--;
  rep(i, N-1){
    ll a, b;
    cin >> a >> b;
    a--, b--;
    G[a].pb(b);
    G[b].pb(a);
  }
  dist.resize(N);
  dist[u].f = 0;
  dfs(u, -1, 1);
  dist[v].s = 0;
  dfs(v, -1, 2);

  vector<ll> samedfs;
  rep(i, N){
    if(dist[i].s == dist[u].s){
      samedfs.pb(i);
    }
  }
  init_lca();
  vector<ll> pos;
  rep(i, samedfs.size()){
    ll x = lca(samedfs[i], u);
    if(dist[x].s - dist[u].s < dist[x].s){
      pos.pb(samedfs[i]);
    }
  }


  ll ans = 0;
  for(ll x: pos){
    ll now = x;
    ll cnt = 0;
    bool update = 1;
    while(update){
      update = 0;
      for(ll to: G[now]){
        if(dist[now].s < dist[to].s){
          update = 1;
          cnt++;
          now = to;
          break;
        }
      }
    }

    ans = max(ans, cnt + dist[x].s - 1);
  }
  cout << ans << endl;
}


int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

