vector<long long> calcDistances(const int start) {
    vector<long long> distances(N+1, -1);
    queue<int> current;
    distances[start] = 0;
    current.push(start);
    while (!current.empty()) {
        int a = current.front();
        for (int i = 0; i < (int)edges[a].size(); ++i) {
            auto b = edges[a][i];
            if (distances[b] == -1) {
                distances[b] = distances[a]+1;
                current.push(b);
            }
        }
        current.pop();
    }
    return distances;
}
