void calcCostAoki(int root)
{
	queue<pair<int, int> > q;

	repc(i, 1, N) visited[i] = false;

	q.push(p(root, 0));
	visited[root] = true;
	costAoki[root] = 0;

	while (!q.empty()) {
		pair<int, int> item = q.front(); q.pop();
		int current = item.first;
		int cost = item.second + 1;
		int size = T[current].size();

		rep(i, size) {
			int next = T[current][i];
			if (!visited[next]) {
				costAoki[next] = cost;
				visited[next] = true;
				q.push(p(next, cost));
			}
		}
	}
}

int costTakahashi[100001];

void calcCostTakahashi(int root)
{
	queue<pair<int, int> > q;

	repc(i, 1, N) visited[i] = false;

	q.push(p(root, 0));
	visited[root] = true;
	costTakahashi[root] = 0;

	while (!q.empty()) {
		pair<int, int> item = q.front(); q.pop();
		int current = item.first;
		int cost = item.second + 1;
		int size = T[current].size();

		rep(i, size) {
			int next = T[current][i];
			if (!visited[next]) {
				costTakahashi[next] = cost;
				visited[next] = true;
				q.push(p(next, cost));
			}
		}
	}
}

int destTakahashi(int root)
{
	pair<int, int> ret = p(-1, -1);

	repc(i, 1, N) {
		int cost = ret.second;

		if (costAoki[i] <= costTakahashi[i]) continue;
		if (cost < costAoki[i]) {
			ret.first = i;
			ret.second = costAoki[i];
		}
	}

	return ret.first;
}

