    dist[s] = 0;
    que.emplace(0, s);
    while(!que.empty()){
        P p = que.top();
        que.pop();
        int v = p.second;
        if(dist[v] < p.first) continue;
        for(int i = 0; i < G[v].size(); i++){
            int to = G[v][i].first;
            T cost = G[v][i].second;
            if(dist[to] > dist[v] + cost){
                dist[to] = dist[v] + cost;
                que.emplace(dist[to], to);
            }
        }
    }
    return dist;
}

signed main(){
    int n,u,v;
    cin >> n >> u >> v;
    u--;
    v--;
    vector<vector<P>> G(n);
    REP(i,n - 1){
        int a,b;
        cin >> a >> b;
        a--;
        b--;
        G[a].emplace_back(b, 1);
        G[b].emplace_back(a, 1);
    }
    vector<int> distt = Dijkstra<int>(u, G);
    vector<int> dista = Dijkstra<int>(v, G);
    int ans = 0;
    REP(i,n){
        if(distt[i] <= dista[i]){
            ans = max(ans, dista[i] - 1);
        }
    }
    cout << ans << endl;
    return 0;
}

