struct node {
	int depth;
	set<int> children;
};

void maketree(node* nodes, int num) {
	for (auto it = nodes[num].children.begin(); it != nodes[num].children.end(); ++it) {
		nodes[*it].children.erase(num);
		nodes[*it].depth = nodes[num].depth + 1;
		maketree(nodes, *it);
	}
}

