using namespace std;

struct N {
	int r;
	int rmax;
	bool b;
	vector<int> e;
};

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n; cin >> n;
	int a, b; cin >> a >> b;

	vector<N> ns(n + 1, { 0, {} });
	FOR_LT(i, 0, n - 1) {
		int u, v; cin >> u >> v;
		ns[u].e.push_back(v);
		ns[v].e.push_back(u);
	}

	{
		stack<int> s;
		ns[b].r = 1;
		s.push(b);

		while (!s.empty()) {
			int c = s.top();
			auto& cn = ns[c];
			if (cn.b) {
				cn.rmax = cn.r;
				for (auto& e : cn.e) {
					cn.rmax = max(cn.rmax, ns[e].rmax);
				}
				s.pop();
				continue;
			}

			cn.b = true;
			for (auto& e : cn.e) {
				if (ns[e].r == 0) {
					ns[e].r = cn.r + 1;
					s.push(e);
				}
			}
		}
	}

	int ans = (ns[a].rmax - ns[a].r) + max(ns[a].r - 2, 0);
	int i = a;
	int j = 1;
	while (true) {
		auto& cn = ns[i];
		if (cn.r <= j) {
			break;
		}
		ans = max(ans, (ns[i].rmax - ns[i].r + max(ns[i].r - (j + 1), 0)) + (j - 1));
		j++;

		for (auto& e : cn.e) {
			if (cn.r > ns[e].r) {
				i = e;
				break;
			}
		}

	}
	cout << ans << endl;

	return 0;
}

