    queue<int> q;
    vector<int> dep(maxN);
    bool used[N];
    fill(used,used+N,false);
    //memset(dep,-1,sizeof(dep));
    for(int i=0;i<N;i++){
        dep[i] = -1;
    }
    q.push(s);
    dep[s]=0;
    while(!q.empty()){
        int u=q.front(); q.pop();
