    if(anc(x,y)){
        return x;
    }
    if(anc(y,x)){
        return y;
    }
    for(int i = 19; i >= 0; i--){
        if(!anc(table[x][i],y)){
            x = table[x][i];
        }
    }
    return table[x][0];
