const int MAX_N = 1e5;
vector<vector<int> > tree(MAX_N + 1);
vector<int> cost1(MAX_N + 1);
vector<int> cost2(MAX_N + 1);

vector<bool> searched1(MAX_N, false);
vector<bool> searched2(MAX_N, false);
vector<bool> searched3(MAX_N, false);

void dfs1(int p, int c) {
    for(int to: tree[p]) {
        if (!searched1[to]) {
            searched1[to] = true;
            cost1[to] = c;
            dfs1(to, c + 1);
        }
    }
}
void dfs2(int p, int c) {
    for(int to: tree[p]) {
        if (!searched2[to]) {
            searched2[to] = true;
            cost2[to] = c;
            dfs2(to, c + 1);
        }
    }
}

int main() {
    int N, u, v;
    cin >> N >> u >> v;

    for (int i = 0; i < N-1; i++) {
        int a, b; cin >> a >> b;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }

    searched1[v] = true;
    cost2[v] = 0;
    dfs1(v, 1);
    searched2[u] = true;
    cost2[u] = 0;
    dfs2(u, 1);

    int ans = 0;
    queue<int> q;
    q.push(u);
    while (!q.empty()) {
        int t = q.front();
        q.pop();
        for(int tar: tree[t]) {
            if (!searched3[tar] && cost1[tar] > cost2[tar]) {
                searched3[tar] = true;
                q.push(tar);
            }
            if (cost1[tar] > cost2[tar]) {
                ans = max(cost1[tar] - 1, ans);
            }
            if (cost1[tar] == cost2[tar]) {
                ans = max(cost1[tar], ans);
            }
        }
    }
    cout << ans << endl;
}

