	dist[u]=0;
	q.push(node {u,dist[u]});

	while(!q.empty()){
		node x=q.top();
		q.pop();
		if(vis[x.to]) continue;
		vis[x.to]=true;
		for(int i=head[x.to];i!=-1;i=edge[i].next){
