typedef pair<int, int> pii;

vector<pii> dist(vector<vector<int>> &adj, int a) {
  int n = adj.size();
  vector<pii> ans(n, {-1, -1});
  queue<int> q;
  q.push(a);
  ans[a] = {0, -1};
  while (!q.empty()) {
  	int f = q.front();
    q.pop();
    for (const int &i : adj[f]) {
      if (ans[i].first == -1) {
      	ans[i].first = ans[f].first + 1;
        ans[i].second = f;
        q.push(i);
      }
    }
  }
  return ans;
}

