template<class Type>
Type solve(Type res = Type()){
    int N,u,v; cin >> N >> u >> v;
    u--; v--;
    vector<vector<int>> G(N);
    for(int i = 0; i < N-1;i++){
        int A,B; cin >> A >> B;
        A--; B--;
        G[A].push_back(B);
        G[B].push_back(A);
    }
    vector<int> order;
    function<bool(int,int)> path_check = [&](int n,int pre){
        order.push_back(n);

        if(n == v) return true;
        for(auto next:G[n]){
            if(next == pre) continue;
            if(path_check(next,n)) return true;
        }
        order.pop_back();
        return false;
    };
    path_check(u,-1);

    int l = 0, r = (int)order.size()-1;
    while(r-l>2){
        l++;
        r--;
        res++;
    }
    u = order[l];
    v = order[r];

    int ng_idx = v;
    if(r-l==2){
        res++;
        ng_idx = order[l+1];
    }

    vector<ll> dist(N,LINF);
    dist[u] = 0;
    priority_queue<pll> pq;
    pq.push(pll(0,u));
    while(pq.size()){
        ll c,n; tie(c,n) = pq.top(); pq.pop();
        if(dist[n] < -c) continue;
        for(auto next:G[n]){
            if(next == ng_idx) continue;
            if(dist[next] > dist[n] + 1){
                dist[next] = dist[n] + 1;
                pq.push(pll(-dist[next],next));
            }
        }
    }
    ll maxdist = 0;
    for(int i = 0; i < N;i++){
        if(dist[i] == LINF) continue;
        maxdist = max(maxdist,dist[i]);
    }
    res += maxdist;

    return res;
}
