void dijkstra(v(vp) &G,int V,int s) {
// G[f][i] = P(t,c) means that from `f` to `t` 's cost is `c` 
  d = vi(V,INF);
  priority_queue<P,vp, greater<P>> que;
  d[s] = 0;
  que.push(P(0,s));
  while(!que.empty()) {
    P p = que.top();
    que.pop();
    int tar = p.second;
    if(d[tar] < p.first) continue;
    rep(i,sz(G[tar])) {
      P e = G[tar][i];
      if(d[e.first] > d[tar] + e.second) {
        d[e.first] = d[tar] + e.second;
        que.push(P(d[e.first],e.first));
      }
    }
  }
}

int main() {
  int N,s,t;
  cin >> N >> s >> t;
  s--;
  t--;
  v(vp) G(N);
  rep(i,N-1) {
    int a,b;
    cin >> a >> b;
    a--;
    b--;
    G[a].push_back(P(b,1));
    G[b].push_back(P(a,1));
  }
  dijkstra(G,N,s);
  vi ta = d;
  dijkstra(G,N,t);
  vi ao = d;
  int ans = 0;
  rep(i,N) {
    if(ta[i] < ao[i]) {
      ans = max(ans,ao[i]-1);
    }
  }
  cout << ans << endl;

  return 0;
}

