void add(int u, int v) {
	edge[++cnt] = (Edge){v, head[u]}; head[u] = cnt;
}

void dfs(int u, int pre) {
	fa[u] = pre;
	max[u] = dis[u];
	PE(e, u) {
		int v = edge[e].t;
		if (v == pre) continue;
		dis[v] = dis[u] + 1;
		dfs(v, u);
		max[u] = std::max(max[u], max[v]);
	}
}

