		// printf("max = %d, dis = %d\n", max[S], dis[S]);
		ans += dis[S] / 2;
		int tmp = (dis[S] / 2), gx = S;
		while (tmp--) gx = fa[gx];
		ans += max[gx] - dis[gx];
	} else {
		ans += (dis[S]  - 1)/ 2;
		int tmp = ans, gx = S;
		while (tmp--) gx = fa[gx];
		ans += max[gx] - dis[gx] + 1;
	}
	printf("%d\n", ans);
	return 0;
}

