void dfs(vector<vector<int>>& G, int u, vector<int>& dist) {
  for (auto v : G[u]) {
    if (dist[v] != -1) continue;
    dist[v] = dist[u] + 1;
    dfs(G, v, dist);
  }
}

int dfs2(vector<vector<int>>& G, int u, vector<int>& distT,
         vector<int>& distA) {
  if (distA[u] <= distT[u]) {
    return (distA[u] + distT[u]) / 2;
  }
  int ret = distT[u];
  for (auto v : G[u]) {
    if (distT[v] != -1) continue;
    distT[v] = distT[u] + 1;
    ret = max(ret, dfs2(G, v, distT, distA));
  }
  return ret;
}

