using namespace std;
const int INF = 1e9;

vector<int> bfs(int start, vector< vector<int> > &G) {
  vector<int> dist(G.size(), INF);
  queue<int> q;
  q.push(start);
  dist[start] = 0;
  while (!q.empty()) {
    int cur = q.front(); q.pop();

    for (int i = 0; i < G[cur].size(); ++i) {
      int next = G[cur][i];
      if (dist[next] == INF) {
	q.push(next);
	dist[next] = dist[cur] + 1;
      }
    }
  }
  return dist;
}

int main() {
  int n, u, v;
  cin >> n >> u >> v;
  u--; v--;
  vector< vector<int> > G(n);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  vector<int> dist_T = bfs(u, G);
  vector<int> dist_A = bfs(v, G);

  int idx = -1;
  int ma = -1;
  for (int i = 0; i < n; ++i) {
    if (dist_T[i] < dist_A[i] && dist_A[i] > ma) {
      idx = i;
      ma = dist_A[i];
    }
  }

  int meet = G[idx][0];
  int ans = dist_A[meet];
  cout << ans << endl;
  return 0;
}

