using namespace std;

class Solution {
public:
    int solve(int n, vector<pair<int,int>>& edges, int H, int A) {
        int rt = A;

        vector<vector<int>> graph(n);
        for (auto& e : edges) {
            int u = e.first, v = e.second;
            graph[u].push_back(v);
            graph[v].push_back(u);
        }

        vector<int> depth(n + 1, 0);
        vector<int> dp(n + 1, 0);
        vector<int> pars(n, -1);
        vector<int> ord;
        ord.push_back(rt);
        depth[rt] = 0;
        for (int i = 0; i < ord.size(); ++i) {
            int u = ord[i];
            for (auto v : graph[u]) {
                if (v == pars[u]) {
                    continue;
                }
                pars[v] = u;
                ord.push_back(v);
                depth[v] = depth[u] + 1;
            }
        }

        reverse(ord.begin(), ord.end());
        for (auto u : ord) {
            dp[u] = depth[u];
            for (auto v : graph[u]) {
                if (v == pars[u]) {
                    continue;
                }
                dp[u] = max(dp[u], dp[v]);
            }
        }

        int res = 0;
        int cur = H;
        while (cur != -1 && depth[H] - depth[cur] <= depth[cur]) {
            if (depth[H] - depth[cur] == depth[cur]) {
                res = max(res, depth[H] - depth[cur]);
            } else {
                res = max(res, dp[cur] - 1);
            }
            cur = pars[cur];
        }

        return res;
    }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n; 
    cin >> n;
    int u, v;
    cin >> u >> v;
    --u, --v;
    vector<pair<int,int>> edges;
    for (int i = 0; i + 1 < n; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        edges.emplace_back(u, v);
    }

    Solution sol;
    cout << sol.solve(n, edges, u, v) << "\n";

    return 0;
}

