ll findLca(ll a, ll b) {
  if (a == b)
    return a;
  if (depth[a] < depth[b])
    swap(a, b);
  ll rem = depth[a] - depth[b];
  for (ll i = 19; i >= 0; i--) {
    if (rem & (1 << i))
      a = dp[a][i];
  }

  if (a == b)
    return a;

  for (ll i = 19; i >= 0; i--) {
    if (dp[a][i] != dp[b][i])
      a = dp[a][i], b = dp[b][i];
  }
  return dp[a][0];
}
