		a--, b--;
		G[a].emplace_back(Edge(b, 1));
		G[b].emplace_back(Edge(a, 1));
	}

	Dijkstra<ll, (ll)2e18> taka(G, u);	// 逃げる
	Dijkstra<ll, (ll)2e18> aoki(G, v);	// 迫る

	// 目的地 
	ll maxPos = 0;
	ll maxDist = 0;
	for (int i = 0; i < N; i++) {
		if (taka.res[i] < aoki.res[i]) {
			if ((IsEven(taka.res[i])&&IsEven(aoki.res[i]))&&
				(IsOdd(taka.res[i])&&IsOdd(aoki.res[i]))) {
				if (maxDist < aoki.res[i]) {
