		}
	}
	return;
}
int lca(int u,int v){
	if(depth[u]>depth[v])swap(u,v);
	for(int i=MAX_LOG_V-1;i>=0;i--){
		if(((depth[v]-depth[u])>>i)&1)v=parent[i][v];
	}
	if(u==v)return u;
	for(int i=MAX_LOG_V-1;i>=0;i--){
		if(parent[i][u]!=parent[i][v]){
			u=parent[i][u];
			v=parent[i][v];
		}
	}
	return parent[0][u];
}

