    }


    dij2.calc_shortest_path(v); // 青木からの距離

    // 何回上がれるか
    ll up = (to_aoki-1)/2;
    debug(up);

    if(up==0){
      //逃げるしかない
      ll max_depth = 0;
      for(ll to : G[u]){
        if(dij2.distance(to)>dij2.distance(u)){
          ll d = dfs(to, u);
          chmax(max_depth, d);
        }
      }
      if(to_aoki==2){
        p(max_depth+1); return 0;
      }else{
        // 1
        p(max_depth); return 0;
      }
    }

    //while(up--){
