      if (y == p) continue;
      dfs(dfs,y,x,d+1);
      cmx(h.at(x), h.at(y));
    }
    h.at(x)++;
  };
  dfs(dfs,root,root,0);
  debug(D);

  int ans = D / 2;
  auto efs = [&] (auto&& efs, int x, int p, int d) -> bool {
    bool ret = x == s;
    for (auto&& y : graph.at(x)) {
      if (y == p) continue;
      ret |= efs(efs,y,x,d+1);
    }
    if (ret == true && D / 2 < d) {
      lint tmp = D - d + h.at(x);
      debug(x,d,h.at(x),D,tmp);
      cmx(ans,tmp);
      debug(ans,tmp);
    }
    return ret;
  };
  efs(efs,root,root,0);

  // debug(h);
  std::cout << ans << std::endl;
  return 0;
}

