vector<int> E[MAX_N];
int D[MAX_N];
int rD[MAX_N];
vector<int> DD[MAX_N];

int ans = 0;

bool reaf[MAX_N];
void calcD(int pos, int pre, int depth) {
  D[pos] = depth;
  bool flag = true;
  for(int next : E[pos]) {
    if(next == pre) continue;
    calcD(next, pos, depth+1);
    flag = false;
  }
  if(flag) {
    reaf[pos] = true;
  }
}

bool used[MAX_N];

void solve(int pos, int pre, int depth)
{
  used[pos] = true;
  for(int next : E[pos]) {
    if(next == pre) continue;
    if(D[next] > depth+1) {
      solve(next, pos, depth+1);
    }
  }
}

