        a--;
        b--;
        G[a].push_back(edge{b, 1});
        G[b].push_back(edge{a, 1});
    }

    dijkstra(u);
    dijkstra2(v);
    int ans = 0;
    for(int i = 0; i < V; i++)
        if(d[i] <= d2[i]) ans = max(ans, d2[i] - 1);
    cout << ans;
    return 0;
}

