    Graph G(n);
    for (int i=0; i<n-1; i++) {
        int a, b;
        cin >> a >> b;
        G.at(a-1).push_back(b-1);
        G.at(b-1).push_back(a-1);
    }

    vector<pair<int, int>> dis(n, make_pair(-1, -1));
    queue<int> que;

    // calc Takahashi distance
    que.push(u);
    dis.at(u).first = 0;
    while (!que.empty()) {
        int cur = que.back(); que.pop();
        for (int x : G.at(cur)) {
            if (dis.at(x).first != -1) {
                continue;
            }
            dis.at(x).first = dis.at(cur).first + 1;
            que.push(x);
        }
    }
    // calc Aoki distance
    que.push(v);
    dis.at(v).second = 0;
    while (!que.empty()) {
        int cur = que.back(); que.pop();
        for (int x : G.at(cur)) {
            if (dis.at(x).second != -1) {
                continue;
            }
            dis.at(x).second = dis.at(cur).second + 1;
            que.push(x);
        }
