    while(!q.empty()){
        ll p=q.front();q.pop();
        for(auto&nxt:edge[p]){
            if(vt[nxt]==-1){
                q.push(nxt);
                vt[nxt]=vt[p]+1;
            }
        }
    }
    q.push(a);va[a]=0;
    while(!q.empty()){
        ll p=q.front();q.pop();
        for(auto&nxt:edge[p]){
            if(va[nxt]==-1){
                q.push(nxt);
                va[nxt]=va[p]+1;
            }
        }
    }
    ll oe = (va[0]-vt[0]+20000000)%2;

    ll ans=0;
    if(oe==0){
        ans=LINF;
        rep(i,n){
            if(vt[i]==va[i])chmin(ans, vt[i]);
        }
    }else{
        rep(i,n){
            if(vt[i]+1==va[i])chmax(ans, vt[i]);
        }
    }
    // puta(vt);
    // puta(va);
    puta(ans);
    return 0;
}

