    void print(const T& container)
    {
        bool first = true;
        for (auto&& x : container) {
            if (!first) {
                cout << ' ';
            }
            cout << x;
            first = false;
        }
        cout << '\n';
    }
};

void turn(std::vector<int>& tree, int root)
{
    if (root == tree[0] || root == -1) return;
    if (root != tree[0]) {
        turn(tree, tree[root]);
    }
    int prevRoot = tree[0];
    tree[0] = root;
    tree[prevRoot] = root;
    tree[root] = -1;
}

void depth(const std::vector<int>& tree, std::vector<int>& d, int node)
{
    if (d[node] != -1) return;
    if (node == tree[0]) {
        d[node] = 0;
        return;
    }
    if (tree[node] == -1) {
        d[node] = 0;
        return;
    }
    if (d[tree[node]] == -1) {
        depth(tree, d, tree[node]);
    }
    d[node] = d[tree[node]] + 1;
}

void prog()
{
    input in;
    output out;
    int n, u, v;
    in >> n, u, v;
    std::vector<int> tree(n + 1, -1);
    tree[0] = 1;
    for (int i : boost::irange(0, n - 1)) {
        int a, b;
        in >> a, b;
        if (a > b) std::swap(a, b);
        tree[b] = a;
    }
    std::vector<int> ud(n + 1, -1), vd(n + 1, -1);
    turn(tree, u);
    if (std::count(std::begin(tree), std::end(tree), u) == 1) {
        out, 0;
        return;
    }
    for (int i : boost::irange(1, n + 1)) {
        depth(tree, ud, i);
    }
    turn(tree, v);
    for (int i : boost::irange(1, n + 1)) {
        depth(tree, vd, i);
    }
    int res = -1;
    for (int i : boost::irange(1, n + 1)) {
        if (ud[i] < vd[i]) {
            res = std::max(res, vd[i]);
        }
    }
    out, res - 1;
}

int main()
{
    prog();
    return 0;
}

