class LCA {
public:
    long V, logV;
    vector<long> depth, len;
    vector<vector<long> > parent;

    LCA(long V) {
        this->V = V;
        logV = 0;
        while (V > (1LL<<logV)) logV++;
        this->depth = vector<long>(V);
        this->len = vector<long>(V);
        this->parent = vector<vector<long> >(logV, vector<long>(V));
    }

    void init(long v, long par, long d, long l) {
        depth[v] = d;
        parent[0][v] = par;
        len[v] = l;
        for (int i = 0; i < (int)G[v].size(); i++) {
            long w = G[v][i].to;
            long lc = G[v][i].cost;
            if (w == par) continue;
            init(w, v, d+1, lc + l);
        }
    }

    void build() {
        for (int k = 0; k + 1 < logV; k++) {
            for (int v = 0; v < V; v++) {
                if (parent[k][v] < 0) parent[k+1][v] = -1;
                else parent[k+1][v] = parent[k][parent[k][v]];
            }
        }
    }

    long query(long u, long v) {
        if (depth[u] > depth[v]) swap(u, v);
        for (int k = 0; k < logV; k++) {
            if ((depth[v] - depth[u]) >> k & 1)
                v = parent[k][v];
        }
        if (u == v) return u;

        for (int k = logV-1; k >= 0; k--) {
            if (parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }
};

