    G[a].push_back({b, 1});
    G[b].push_back({a, 1});
  }

  LCA lca(n);
  lca.init(0, -1, 0, 0);
  lca.build();
  int z = lca.query(u, v);
  if (lca.len[u] <= lca.len[v]) {
    cout << (lca.len[u] + lca.len[v] - 2 * lca.len[z]) / 2 << endl;
