    qu.pop();
    for(int i: t[tmp]){
      qu.push(i);
      if(du[i] > du[tmp] + 1) du[i] = du[tmp] + 1;
    }
  }

  vector<int> dv(n, 100000000);
  dv[v-1] = 0;
  queue<int> qv;
  qv.push(v-1);
