template <typename T>
class BufferManager {
  protected:
    /**
     * @brief
     * 本体、ポインタで管理
     * \todo unique_ptrに変更
     */
    T* buf;

  public:
    /**
     * @brief Construct a new Buffer Manager object
     *
     * @param buf
     */
    BufferManager(T* buf) : buf(buf) {}
    /**
     * @brief
     * size分バッファを取得
     * @param size
     * @return T*
     */
    virtual T* pop(int size) = 0;
    /**
     * @brief
     * 領域をマネージャに返却（解放）する
     * @param p
     */
    virtual void push(T* p) = 0;
    /**
     * @brief
