bool dfs1(int i=taka, int depth=0) {
    visited[i] = true;
    d[i] = depth;
    if (i == aoki) {
        tsd = (d[i] - 1) / 2;
        asd = (d[i] + 2) / 2;
        if (d[i] == asd) as = i;
        if (d[i] == tsd) ts = i;
        return true;
    }
    for (auto &g:G[i]) {
        if (visited[g]) continue;
        bool isChild = dfs1(g, depth+1);
        if (isChild) {
            if (d[i] == asd) as = i;
            if (d[i] == tsd) ts = i;
            return true;
        }
    }
    return false;
}

int dfs2(int i=ts) {
    int ans = 0;
    visited[i] = true;
    if (i == as) return -1;
    for (auto &g:G[i]) {
        if (visited[g]) continue;
        int val = dfs2(g);
        if (val < 0 && i != ts)
            return -1;
        ans = max(ans, val + 1);
    }
    // cerr << i << ' ' << ans << '\n';
    return ans;
}

