struct GraphAdapter {
    template<class T>
    static UnWeightedGraph to_unweighted_graph(const WeightedGraph<T> &origin) {
        int V = origin.size();
        UnWeightedGraph graph(V);
        for (int i = 0; i < V; i++) for (auto &e: origin[i]) graph[i].push_back((int) e);
        return graph;
    }

    static WeightedGraph<int> to_weighted_graph(const UnWeightedGraph &origin) {
        int V = origin.size();
        WeightedGraph<int> graph(V);
        for (int i = 0; i < V; i++) for (auto to: origin[i]) graph[i].push_back({i, to, 1});
        return graph;
    }
};

struct Doubling {
    const long long LOG;
    const int N;
    vector<vector<int>> nexted;

    Doubling(int N, long long log = 60) : N(N), LOG(log) {
        nexted.assign(LOG + 1, vector<int>(N + 1, -1));
    }

    inline void set_init_next(const int v, const int x) {
        nexted[0][v] = x;
    }

    void build() {
        for (int k = 0; k < LOG; k++) {
            for (int v = 0; v < N; v++) {
                if (nexted[k][v] == -1) nexted[k + 1][v] = -1;
                else nexted[k + 1][v] = nexted[k][nexted[k][v]];
            }
        }
    }

    inline int query(int v, long long p) {
        for (long long i = LOG; i >= 0; i--) {
            if (v < 0) return -1;
            if (p & (1LL << i)) {
                v = nexted[i][v];
            }
        }
        return v;
    }
};

template<typename T>
class LowestCommonAncestor {
public:
    const long long LOG;
    const int N;

    const WeightedGraph<T> &graph;
    vector<int> depth;
    vector<T> dist;
    vector<vector<int>> nexted;

public:
    LowestCommonAncestor(const WeightedGraph<T> &graph, const long long LOG = 60) : graph(graph), LOG(LOG), N(graph.size()), depth(N, -1), dist(N, numeric_limits<T>::max()) {
        nexted.assign(LOG + 1, vector<int>(N, -1));
    }

    void dfs(int v, int p, int d, long long sum) {
        depth[v] = d;
        dist[v] = sum;
        nexted[0][v] = p;
        for (auto e: graph[v]) {
            int to = e.to;
            long long cost = e.cost;
            if (to != p) {
                dfs(to, v, d + 1, sum + cost);
            }
        }
    }

    void build(int s) {
        dfs(s, -1, 0, 0);
        for (int k = 0; k < LOG; k++) {
            for (int v = 0; v < N; v++) {
                if (nexted[k][v] == -1) nexted[k + 1][v] = -1;
                else nexted[k + 1][v] = nexted[k][nexted[k][v]];
            }
        }
    }

    int lca(int u, int v) {
        if (depth[u] > depth[v]) swap(u, v);
        for (long long i = LOG - 1; i >= 0; i--) {
            if ((depth[v] - depth[u]) & (1LL << i)) {
                v = nexted[i][v];
            }
        }
        if (u == v)return u;
        for (long long i = LOG - 1; i >= 0; i--) {
            if (nexted[i][u] != nexted[i][v]) {
                u = nexted[i][u];
                v = nexted[i][v];
            }
        }
        return nexted[0][u];
    }

    T get_distance(int u, int v) {
        T sum = dist[u] + dist[v] - 2 * dist[lca(u, v)];
        return sum;
    }

};

void dfs(LL R, int v, int p, int s, LL &cal, int depth, WeightedGraph<LL> &graph) {
    if (v == s) {
        depth = 0;
    }
    for (auto e: graph[v]) {
        int to = e.to;
        if (to == p) {
            continue;
        }
        if (depth == -1) {
            dfs(R, to, v, s, cal, depth, graph);
        } else {
            dfs(R, to, v, s, cal, depth + 1, graph);
        }
    }
    chmax(cal, depth);
}

int main() {

    int N;
    cin >> N;

    int L, R;
    cin >> L >> R;

    L--, R--;

    WeightedGraph<long long> graph(N);
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        graph[u].push_back({u, v, 1});
        graph[v].push_back({v, u, 1});
    }

    LowestCommonAncestor<long long> LCA(graph);
    LCA.build(R);


    LL ans = (LCA.get_distance(L, R) - 1) / 2;

    LL cand = (LCA.get_distance(L, R)) / 2;

    auto nexted = LCA.nexted;

    auto s = L;

    for (LL i = 30; i >= 0; i--) {
        if (ans & (1LL << i)) {
            s = nexted[i][s];
        }
    }

    LL cal = 0;
    dfs(R, R, -1, s, cal, -1, graph);

    if (LCA.get_distance(L, R) % 2 == 0) {
        ans++;
    }

    cout << max(cand, cal + ans) << endl;

    return 0;
}

