#define int long long
using namespace std;
using Graph = vector<vector<int>>;

signed main() {
  int N, aoki,taka;
  cin >> N >> taka >> aoki;

  Graph G(N);
  int A, B;
  for( int i = 0; i < N-1; i++ ){
    cin >> A >> B;
    G.at(A-1).push_back(B-1);
    G.at(B-1).push_back(A-1);
  }

  //青木君を根としてBFS
  vector<int> Adist(N, -1);
  queue<int> que;

  Adist.at(aoki-1) = 0;
  que.push(aoki-1);

  while( !que.empty() ){
    int v = que.front();
    que.pop();

    for( int nv : G.at(v) ){
      if( Adist.at(nv) != -1 ) continue;
      Adist.at(nv) = Adist.at(v)+1;
      que.push(nv);
    }
  }

  //高橋君から見てBFS
  vector<int> Tdist(N, -1);
  Tdist.at(taka-1) = 0;
  que.push(taka-1);

  while( !que.empty() ){
    int v = que.front();
    que.pop();

    for( int nv : G.at(v) ){
      if( Tdist.at(nv) != -1 ) continue;
      //青木君のほうが早く到達する頂点は無視
      if( Adist.at(nv) <= Tdist.at(v)+1 ) continue;

      Tdist.at(nv) = Tdist.at(v) + 1;
      que.push(nv);
    }
  }

  int ans = 0;
  for( int i = 0; i < N; i++ ){
    if( Tdist.at(i) != -1 && Adist.at(i)-1 > ans ) ans = Adist.at(i) - 1;
  }
  cout << ans << endl;

}

