template< typename Graph >
class LowestCommonAncestor {
public:
	ll n;
	std::vector<ll> path, in_order;
	std::vector<std::pair<ll,ll>> depth;
	std::vector< std::vector< std::pair<ll,ll> > > st;
	std::vector< ll > lookup;
	LowestCommonAncestor(const Graph &g, ll root) : n(g.size()), path(n * 2 - 1), in_order(n), depth(n * 2 - 1) {
		ll k = 0;
		dfs(g, root, -1, 0, k);
		build(depth);
	}

	ll query(ll u, ll v) const {
		ll l = std::min(in_order[u], in_order[v]);
		ll r = std::max(in_order[u], in_order[v]) + 1;
		std::pair<ll,ll> t = rmq(l, r);
		return path[t.second];
	}

	void dfs(const Graph &g, ll v, ll p, ll d, ll &k) {
		in_order[v] = k;
		path[k] = v;
		depth[k] = {d, k};
		++k;
		for (auto &nextv : g[v]) {
			if (nextv != p) {
				dfs(g, nextv, v, d + 1, k);
				path[k] = v;
				depth[k] = {d, k};
				++k;
			}
		}
	}

	void build(const vector< std::pair<ll,ll> > &v) {
		ll b = 0;
		while((1 << b) <= (ll)v.size()) ++b;
		st.assign(b, std::vector< std::pair<ll,ll> >(1 << b));
		for(ll i = 0; i < (ll)v.size(); i++) {
			st[0][i] = v[i];
		}
		for(ll i = 1; i < b; i++) {
			for(ll j = 0; j + (1 << i) <= (1 << b); j++) {
				st[i][j] = std::min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
			}
		}
		lookup.resize(v.size() + 1);
		for(ll i = 2; i < (ll)lookup.size(); i++) {
			lookup[i] = lookup[i >> 1] + 1;
		}
	}

	std::pair<ll,ll> rmq(ll l, ll r) const {
		ll b = lookup[r - l];
		return std::min(st[b][l], st[b][r - (1 << b)]);
	}
};


