vector<int> g[MAXN], tour;
int first[MAXN], height[MAXN], t = 0;

void dfs(int u, int p = -1, int h = 0) {
	first[u] = t++;
	height[u] = h;
	tour.push_back(u);
	for(int v : g[u]) {
		if(v != p) {
			dfs(v, u, h+1);
			tour.push_back(u);
			t++;
		}
	}
}

int main() {
	ios_base::sync_with_stdio(false);
