	for(int i = 0; i < n-1; i++) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		g[u].push_back(v);
		g[v].push_back(u);
	}

	dfs(0);
	int B = 1, sz = tour.size();
	while(B < sz) {
		B *= 2;
	}

	vector<pair<int, int>> tree(2*B);
	for(int i = 0; i < sz; i++) {
		tree[i+B] = {height[tour[i]], tour[i]};
	}
	for(int i = B-1; i > 0; i--) {
		tree[i] = min(tree[2*i], tree[2*i+1]);
	}

	auto lca = [&](int u, int v) {
		int L = first[u] + B, R = first[v] + B;
		if(L > R) swap(L, R);
		pair<int, int> ans = {inf, -1};

		while(L <= R) {
			if(L % 2 == 1) ans = min(ans, tree[L++]);
			if(R % 2 == 0) ans = min(ans, tree[R--]);
			L /= 2, R /= 2;
		}

		return ans.second;
	};

	auto dist = [&](int u, int v) {
		return height[u] + height[v] - 2*height[lca(u, v)];
	};

	int ans = 0;

#define debug(x) cerr << #x << " : " << x << endl

	for(int e = 0; e < n; e++) {
		if(e == mouse || e == cat) continue;
