		if(mouse_d < cat_d /* && (cat_d % 2 != mouse_d % 2) */) {
			//$ debug(e); debug(cat_d); debug(mouse_d);
			ans = max(ans, cat_d - (cat_d % 2 != mouse_d % 2));
		} else if(mouse_d == cat_d) {
			vector<int> nodes = {mouse, cat, e};
			int mn = inf, u = -1;
			sort(nodes.begin(), nodes.end());
			do {
				int a = nodes[0], b = nodes[1], c = nodes[2];
				//$ cerr << a << ' ' << b << ' ' << c << '\n';
				int d = lca(a, b);
				int len = dist(a, b) + dist(d, c);
				if(len < mn) {
					mn = len, u = d;
					//$ cerr << d << ' ' << len << endl;
				}
			} while(next_permutation(nodes.begin(), nodes.end()));

			//$ cerr << cat << ' ' << mouse << ' ' << e << endl;
			//$ cerr << u << endl;

			if(u == e) {
				//$ cerr << e << ' ' << cat_d << endl;
				ans = max(ans, cat_d);
			}
		}
	}

	cout << ans << endl;
}

