ll deepen(ll s){
  bool flag=false;
  used[s]=true;
  REP(i,e[s].size()){
    if(!used[e[s][i]]){
      flag=true;
      return deep[s]=max(deep[s],deepen(e[s][i]));
    }
  }
  if(!flag) return deep[s]=du[s];
}



