vector<vector<int>> nodes(100000, vector<int>());

bool findPath(int target, int node, vector<int> &path, int from) {
  if (node == target) {
    path.push_back(node);
    return true;
  }
  rep(i, nodes[node].size()) {
    if (nodes[node][i] == from) continue;
    if (findPath(target, nodes[node][i], path, node)) {
      path.push_back(node);
      return true;
    }
  }
  return false;
}

int maxDistance(int from, int node) {
  vector<int> dist;
  rep(i, nodes[node].size()) {
    if (nodes[node][i] != from) {
      dist.push_back(maxDistance(node, nodes[node][i]));
    }
  }
  if (dist.size() == 0) {
    return 0;
  }
  int maxDist = 0;
  rep(i, dist.size()) {
    maxDist = max(maxDist, dist[i]);
  }
  return maxDist + 1;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(16);

  int N, u, v;
  cin >> N >> u >> v;
  u--;
  v--;
  rep(i, N - 1) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    nodes[a].push_back(b);
    nodes[b].push_back(a);
  }

  vector<int> utov;
  findPath(u, v, utov, -1);

  int dist = utov.size() - 1;
  if (dist % 2 == 0) {
    out(maxDistance(utov[dist / 2], utov[dist / 2 - 1]) + dist / 2);
  } else {
    out(maxDistance(utov[dist / 2 + 1], utov[dist / 2]) + dist / 2);
  }
}

