void dfs(int u = rt, int p = rt) {
    if (g[u].size() == 1 && u != rt) {
        lf.push_back(u);
        return;
    }
    loop (i, g[u].size()) {
        int v = g[u][i];
        if (v == p)  continue;
        pr[v][0] = u;
        dep[v] = dep[u] + 1;
        dfs(v, u);
    }
}

void inline init() {
    dfs();
    cont (k, lgsz) {
        cont (u, n) {
            int p = pr[u][k - 1];
            if (!p)  continue;
            pr[u][k] = pr[p][k - 1];
        }
    }
}

int inline lca(int u, int v) {
    if (dep[u] > dep[v]) {
        swap(u, v);
    }
    circ (k, 0, lgsz) {
        if (((dep[v] - dep[u]) >> k) & 1) {
            v = pr[v][k];
        }
    }
    if (u == v)  return u;
    for (int k = lgsz; k >= 0; --k) {
        if (pr[u][k] != pr[v][k]) {
            u = pr[u][k], v = pr[v][k];
        }
    }
    return pr[u][0];
}

