void dijkstra1(int s){
    priority_queue<pii,vector<pii>,greater<pii>> que;
    fill(d1,d1+V,INF);
    d1[s] = 0;
    que.push(pii(0,s));
    while(!que.empty()){
        pii p = que.top();que.pop();
        int v = p.se;
        if(d1[v] < p.fi) continue;
        rep(i,G[v].size()){
            edge e = G[v][i];
            if(d1[e.to] > d1[v]+e.cost){
                d1[e.to] = d1[v] + e.cost;
                que.push(pii(d1[e.to],e.to));
            }
        }
    }
}
