    cin >> a >> b;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  ll up;
  vector<ll> path = find_path(g, u, v);
  if (path.size() >= 4) {
    up = (path.size() - 2) / 2;
  } else {
    up = 0;
  }
  u = path[path.size() - 1 - up];
  v = path[up + path.size() % 2];

  if (path.size() % 2 == 1) {
    up++;
  }

  ll longest = find_longest(g, u, v);
