        cin>>A>>B;A--;B--;
        nodes[A].to.push_back(B);
        nodes[B].to.push_back(A);
    }
    dfs1(V,-1,nodes);
    dist_max=0,d1=0;
    for(int v : nodes[V].to){
        if(nodes[v].find){
            dist_max=nodes[v].dist;
            break;
        }
    }
    dfs2(V,-1,nodes);
    d2=nodes[U].dist-d1;
    int ans=0;
    if(d2<d1){
        ans=dist_max-1;
    }else{
        ans=d1+d2-1;
    }
    cout<<ans<<endl;
}

