  queue<int> q;

  q.push(s);
  dist[s] = 0;

  while(!q.empty()){
    int v = q.front();
    q.pop();

    for(auto nv : G[v]) {
      if(dist[nv] != -1) continue;
      dist[nv] = dist[v] + 1;
      q.push(nv);
    }
  }
}

