void rec(int i, int p, int d, bool ao){
    if(ao) {
        aok[i] += d;
        dis[i] -= d;
    }
    else{ 
        dis[i] += d;
    }
    for(int ni : G[i]){
        if(p == ni) continue;
        rec(ni, i, d+1, ao);
    }
}

