    int n, u, v;
    scanf("%d%d%d", &n, &u, &v);
    G.resize(n);
    --u; --v;
    dis.resize(n, 0);
    aok.resize(n, 0);
    rep(i, n-1){
        int A, B;
        scanf("%d%d", &A, &B);
        --A; --B;
        G[A].emplace_back(B);
        G[B].emplace_back(A);
    }
    rec(u, -1, 0, false);
    rec(v, -1, 0, true);
    int en = 0;
    int mx = 0;
    for(int i = 0; i < n; ++i){
        if(dis[i] < 0 and aok[i] > mx){
            mx = aok[i];
            en = i;
        }
    }
    ppp(aok[en]-1);
    return 0;
}

