struct Graph {
    struct Vertex { int n, d[2]; };
    struct Edge { int i, n; };
    Graph(int n, int m) : v(n, { -1, 0, 0 }), e(m), n(n), m(0) {}
    void add_edge(int i, int j) {
        e[m] = { j, v[i].n };
        v[i].n = m;
        m++;
    }
    void dfs(int i, int p, int d, int t) {
        v[i].d[t] = d;
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge &o = e[j];
            if (o.i == p) continue;
            dfs(o.i, i, d + 1, t);
        }
    }
    void solve() {
        int r = 0;
        for (int i = 0; i < n; i++) {
            if (v[i].d[0] < v[i].d[1]) {
                r = max(r, v[i].d[1] - 1);
            }
        }
        cout << r << endl;
    }
    vector<Vertex> v;
    vector<Edge> e;
    int n, m;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, u, v;
    cin >> n >> u >> v;
    u--; v--;

    Graph g(n, (n - 1) * 2);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;

        g.add_edge(a, b);
        g.add_edge(b, a);
    }

    g.dfs(u, -1, 0, 0);
    g.dfs(v, -1, 0, 1);
    g.solve();

    return 0;
}

