    Edge(int from, int to, T cost) : from(from), to(to), cost(cost) {}

    explicit operator int() const { return to; }
};

template<class T>
using Edges = vector<Edge<T>>;

template<class T>
using WeightedGraph = vector<Edges<T>>;

using UnWeightedGraph = vector<vector<int>>;

template<class T>
using DistMatrix = vector<vector<T>>;

struct GraphAdapter {
    template<class T>
    static UnWeightedGraph to_unweighted_graph(const WeightedGraph<T> &origin) {
        int V = origin.size();
        UnWeightedGraph graph(V);
        for (int i = 0; i < V; i++) for (auto &e: origin[i]) graph[i].push_back((int) e);
        return graph;
    }

    static WeightedGraph<int> to_weighted_graph(const UnWeightedGraph &origin) {
        int V = origin.size();
        WeightedGraph<int> graph(V);
        for (int i = 0; i < V; i++) for (auto to: origin[i]) graph[i].push_back({i, to, 1});
        return graph;
    }

    template<class T>
    static DistMatrix<T> to_dist_matrix(const WeightedGraph<T> &origin, T INF) {
        int V = origin.size();
        DistMatrix<T> matrix(V, vector<T>(V, INF));
        for (int i = 0; i < V; i++) for (auto &e:origin[i]) matrix[i][e.to] = e.cost;
        for (int i = 0; i < V; i++) matrix[i][i] = 0;
        return matrix;
    }
};

template<typename T>
class LowestCommonAncestor {
private:
    const long long LOG;
    const int N;

    const WeightedGraph<T> &graph;
    vector<int> depth;
    vector<T> dist;
    vector<vector<int>> nexted;

public:
    LowestCommonAncestor(const WeightedGraph<T> &graph, const long long LOG = 60) : graph(graph), LOG(LOG), N(graph.size()), depth(N, -1), dist(N, numeric_limits<T>::max()) {
        nexted.assign(LOG + 1, vector<int>(N, -1));
    }

    void dfs(int v, int p, int d, long long sum) {
        depth[v] = d;
        dist[v] = sum;
        nexted[0][v] = p;
        for (auto e: graph[v]) {
            int to = e.to;
            long long cost = e.cost;
            if (to != p) {
                dfs(to, v, d + 1, sum + cost);
            }
        }
    }

    void build(int s) {
        dfs(s, -1, 0, 0);
        for (int k = 0; k < LOG; k++) {
            for (int v = 0; v < N; v++) {
                if (nexted[k][v] == -1) nexted[k + 1][v] = -1;
                else nexted[k + 1][v] = nexted[k][nexted[k][v]];
            }
        }
    }

    int lca(int u, int v) {
        if (depth[u] > depth[v]) swap(u, v);
        for (long long i = LOG - 1; i >= 0; i--) {
            if ((depth[v] - depth[u]) & (1LL << i)) {
                v = nexted[i][v];
            }
        }
        if (u == v)return u;
        for (long long i = LOG - 1; i >= 0; i--) {
            if (nexted[i][u] != nexted[i][v]) {
                u = nexted[i][u];
                v = nexted[i][v];
            }
        }
        return nexted[0][u];
    }

    int parent_d(int v, long long d) {
        for (long long i = LOG - 1; i >= 0; i--) {
            if (d & (1LL << i)) {
                v = nexted[i][v];
            }
        }
        return v;
    }

    T get_distance(int u, int v) {
        T sum = dist[u] + dist[v] - 2 * dist[lca(u, v)];
        return sum;
    }

};

void dfs(LL R, int v, int p, int s, LL &cal, int depth, WeightedGraph<LL> &graph) {
    if (v == s) {
        depth = 0;
    }
    for (auto e: graph[v]) {
        int to = e.to;
        if (to == p) {
            continue;
        }
        if (depth == -1) {
            dfs(R, to, v, s, cal, depth, graph);
        } else {
            dfs(R, to, v, s, cal, depth + 1, graph);
        }
    }
    cal = max<LL>(cal, depth);
//    chmax(cal, depth);
}

