    LCA.build(R);


    LL ans = (LCA.get_distance(L, R) - 1) / 2;

    LL cand = (LCA.get_distance(L, R)) / 2;

    auto s = LCA.parent_d(L, ans);

    LL cal = 0;
    dfs(R, R, -1, s, cal, -1, graph);

    if (LCA.get_distance(L, R) % 2 == 0) {
        ans++;
    }

    cout << max(cand, cal + ans) << endl;

    return 0;
}

