const int Maxn = 100005;

int n, A, B;
vector <int> neigh[Maxn];
int distA[Maxn], distB[Maxn];
int parA[Maxn], parB[Maxn];
int best;

void Traverse(int v, int p, int lvl, int dist[], int par[])
{
    dist[v] = lvl; par[v] = p;
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (u == p) continue;
        Traverse(u, v, lvl + 1, dist, par);
    }
}

void Solve(int v)
{
    best = max(best, (distA[v] + distB[v]) / 2);
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (parB[v] == u) continue;
        Solve(u);
    }
}

