{
    scanf("%d %d %d", &n, &A, &B);
    for (int i = 0; i < n - 1; i++) {
        int a, b; scanf("%d %d", &a, &b);
        neigh[a].push_back(b);
        neigh[b].push_back(a);
    }
    Traverse(A, 0, 0, distA, parA);
    Traverse(B, 0, 0, distB, parB);
    int r = A;
    while (parB[r] && distA[parB[r]] < distB[parB[r]])
        r = parB[r];
    Solve(r);
    printf("%d\n", best);
    return 0;
}

