void solve(long long N, long long u, long long v, std::vector<long long> A, std::vector<long long> B){
  vector<vector<ll>> tree(N);
  REP(N-1){
    tree[A[i]].push_back(B[i]);
    tree[B[i]].push_back(A[i]);
  }
  vector<ll> depth(N,-1);
  vector<ll> parent(N,-1);
  deque<ll> q;
  q.push_back(v);
  depth[v]=0;
  parent[v]=-1;
  while(!q.empty()){
    ll tmp=q.back();q.pop_back();
    for (auto &&j : tree[tmp])
    {
      if(depth[j]==-1){
        depth[j]=depth[tmp]+1;
        parent[j]=tmp;
        q.push_front(j);
      }
    }
  }
  bool f=(depth[u])%2==0;
  ll p=(depth[u]+1)/2-1;
  REP(p){
    u=parent[u];
  }
  ll depmax=depth[u];
  q.clear();
  q.push_back(u);
  while(!q.empty()){
    ll tmp=q.back();q.pop_back();
    for (auto &&i : tree[tmp])
    {
      if(i==parent[tmp]){
        continue;
      }
      depmax=max(depmax,depth[i]);
      q.push_front(i);
    }
  }
  cout<<depmax-1<<endl;
}

