            bfsQ.push(node);
        }
    };

    Visit(A, 0);
    while (!bfsQ.empty()) {
        int node = bfsQ.front();
        bfsQ.pop();
        for (int next : Edges[node])
            Visit(next, DistA[node] + 1);
    }

    cout << *max_element(ALL(DistA)) - 1 << endl;
    return 0;
};

