void dfs(int now, vector<bool> & visited, vector<vector<int>>& G, bool flag) {
  for (auto it : G[now]) {
    if (!visited[it]) {
      if (flag) {
        // takahashi
        disT[it] = disT[now] + 1;
        visited[now] = true;
        dfs(it, visited, G, flag);
      } else {
        disA[it] = disA[now] + 1;
        visited[now] = true;
        dfs(it, visited, G, flag);
      }
    }
  }
}

