//木に対して、startvを始点とした各頂点との距離を求める
void treebfs(vector<vector<ll>> &g, ll startv, vector<ll> &dist){
	dist.assign(g.size(), -1);
	dist[startv] = 0;
	queue<ll> que;
	que.push(startv);
	while(!que.empty()) {
		ll v = que.front();
		que.pop();
		for(ll nextv : g[v]){
			if(dist[nextv] != -1) continue;
			dist[nextv] = dist[v] + 1;
			que.push(nextv);
		}
	}
}

