template< typename G >
class DoublingLowestCommonAncestor {
public:
	const G &g;
	vector< int > depth;//depth[v]=根からvまでの距離
	const int LOG;
	vector< vector< int > > table;

	DoublingLowestCommonAncestor(const G &g) : g(g), depth(g.size()), LOG(32 - __builtin_clz(g.size())) {
		table.assign(LOG, vector< int >(g.size(), -1));
	}

	void dfs(int idx, int par, int d) {
		table[0][idx] = par;
		depth[idx] = d;
		for(auto &to : g[idx]) {
			if(to != par) dfs(to, idx, d + 1);
		}
	}

	void build(int v) {
		dfs(v, -1, 0);
		for(int k = 0; k + 1 < LOG; k++) {
			for(int i = 0,tablesize = table[k].size(); i < tablesize; i++) {
				if(table[k][i] == -1) table[k + 1][i] = -1;
				else table[k + 1][i] = table[k][table[k][i]];
			}
		}
	}

	int query(int u, int v) {
		if(depth[u] > depth[v]) swap(u, v);
		for(int i = LOG - 1; i >= 0; i--) {
			if(((depth[v] - depth[u]) >> i) & 1) v = table[i][v];
		}
		if(u == v) return u;
		for(int i = LOG - 1; i >= 0; i--) {
			if(table[i][u] != table[i][v]) {
				u = table[i][u];
				v = table[i][v];
			}
		}
		return table[0][u];
	}
};

