vector<int> bfs(const vector<vector<int>>& g, int s) {
  vector<int> d(g.size(), 1e9);
  d[s] = 0;
  queue<int> q;
  q.push(s);
  while (!q.empty()) {
    int i = q.front();
    q.pop();
    for (auto j : g[i]) {
      if (d[i] + 1 < d[j]) {
        d[j] = d[i] + 1;
        q.push(j);
      }
    }
  }
  return d;
}

