// End of template code!
void explore(int root, vector<int>& dist, int parent) {
    //dist[root] has already been set
    for(const auto& viz : g[root]) {
        if(dist[viz] == -1 && viz != parent) {
            dist[viz] = dist[root] + 1;
            explore(viz, dist, root);
        }
    }
}

int main() 
{
    buff();
    // quero saber qual é o caminho mais longo que não passa pelo inimigo
    cin >> n;
    g.resize(n); 
    cin >> u >> v;
    --u; --v;
    // qual o maior caminho que u pode percorrer sem passar por V?
    for(int i = 0; i < n - 1; ++i)
    {
        cin >> a >> b; --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    vector<int> dist_u(n, -1);
    dist_u[u] = 0;
    explore(u, dist_u, -1);

    vector<int> dist_v(n, -1);
    dist_v[v] = 0;
    explore(v, dist_v, -1);

    int st_dist = dist_u[v];

    // agora quero saber por quantas rodadas U consegue fugir
    int large_delay = 0;
    for(int i = 0; i < n; ++i)
    {
        if(dist_v[i] - dist_u[i] == st_dist) {
            large_delay = max(large_delay, dist_u[i]); // a resposta final vai ser garantidamente uma folha do grafo
        }
    }

    // agora tenho que calcular como fica a resposta dependendo da distância atual entre u e v
    vector<int> memo(n + 1);
    memo[0] = 0;
    memo[1] = 0;
    memo[2] = 1;
    for(int i = 3; i <= n; ++i) memo[i] = 2 + memo[i - 2];

    int best = memo[st_dist];
    for(int i = 0; i < n; ++i)
    {
        if(dist_u[i] < dist_v[i]) {
            int cur = dist_u[i];
            best = max(best, cur + memo[dist_v[i] - dist_u[i]]);
        }
    }

    cout << best << '\n';


    return 0;
}

