void bfs(vector< vector<int> >& edges, vector<int>& dist, int node){
    queue<int> Q;
    vector<int> state(edges.size());
    Q.push(node);
    dist[node] = 0;
    state[node] = 1;
    while(!Q.empty()){
        node = Q.front();
        Q.pop();
        for(int e : edges[node]){
            if(state[e] == 0){
                state[e]=1;
                dist[e] = dist[node] + 1;
                Q.push(e);
            }
        }
    }
}

