    std::deque< int > dist;
    std::deque< std::vector< int > > route;
    pos.push_back(v);
    dist.push_back(0);
    route.push_back(std::vector< int >(1, v));

    while(!pos.empty()){
        int c_pos = pos[0];
        int c_dist = dist[0];
        std::vector< int > c_route = route[0];
        pos.pop_front();
        dist.pop_front();
        route.pop_front();

        if(min_dist[c_pos] <= c_dist){
            continue;
        }

        min_dist[c_pos] = c_dist;
        if(c_pos == u){
            min_route = c_route;
            break;
        }

        for(int i=0; i<AB[c_pos].size(); i++){
            pos.push_back(AB[c_pos][i]);
            dist.push_back(c_dist+1);
            std::vector< int > route_tmp = c_route;
            route_tmp.push_back(AB[c_pos][i]);
            route.push_back(route_tmp);
        }
    }

    int center = (min_route.size() % 2 == 0) ? min_route[min_route.size() / 2] : min_route[min_route.size() / 2 + 1];
    int pre_center = (min_route.size() % 2 == 0) ? min_route[min_route.size() / 2 - 1] : min_route[min_route.size() / 2];
