struct LCA {
	vector<vector<int>>table;
	vector<int>dep;
	vector<vector<int>>e;
	const int LOG = 25;
	void dfs(int now, int par, int d) {
		table[now][0] = par;
		dep[now] = d;
		fore(x, e[now]) {
			if (x != par)dfs(x, now, d + 1);
		}
	}
	//0-indexed
	//edgesは双方向
	void lcainit(int n, int root, vector<int>edges[]) {
		e.resize(n);
		dep.resize(n);
		table.resize(n);
		for (int i = 0; i < n; i++) {
			fore(x, edges[i])e[i].pb(x);
		}
		for (int i = 0; i < n; i++)table[i].resize(LOG);
		dfs(root, -1, 0);
		for (int k = 0; k + 1 < LOG; k++) {
			for (int i = 0; i < n; i++) {
				if (table[i][k] == -1)table[i][k + 1] = -1;
				else table[i][k + 1] = table[table[i][k]][k];
			}
		}
	}

	int query(int u, int v) {
		if (dep[u] > dep[v])swap(u, v);
		for (int i = LOG - 1; i >= 0; i--) {
			if (((dep[v] - dep[u]) >> i) & 1)v = table[v][i];
		}
		if (u == v)return v;
		for (int i = LOG - 1; i >= 0; i--) {
			if (table[u][i] != table[v][i]) {
				u = table[u][i];
				v = table[v][i];
			}
		}
		return table[u][0];
	}
};

