		edge[b].emplace(a);
	}
	std::vector<boost::optional<int>> parent(N);
	std::vector<int> depth(N);
	std::vector<boost::optional<std::pair<int, int>>> next(N);
	boost::dynamic_bitset<> flag(N);
	std::queue<std::pair<int, int>> queue;
	std::vector<int> no_child;
	queue.emplace(-1, u);
	while (queue.size())
	{
		int p, i;
		std::tie(p, i) = queue.front();
		queue.pop();
		if (flag[i])
		{
			continue;
		}
		flag[i] = true;
		if (p == -1)
		{
			depth[i] = 0;
		}
		else
		{
			depth[i] = depth[p] + 1;
			parent[i] = p;
		}
		if (edge[i].size() == 1 && i != u)
		{
			no_child.emplace_back(i);
		}
		else
		{
			for (auto n : edge[i])
			{
				queue.emplace(i, n);
			}
		}
	}
	for (auto s : no_child)
	{
		auto i = parent[s];
		auto p = s;
		while (i)
		{
			if (!next[*i])
			{
				next[*i] = std::make_pair(p, s);
			}
			else
			{
				if (depth[next[*i]->second] < depth[s])
				{
					next[*i] = std::make_pair(p, s);
				}
				break;
			}
			p = *i;
			i = parent[*i];
		}
	}
	auto aoki = 0;
	auto result = 0;
	while (2 < depth[v] - aoki)
	{
		v = *parent[v];
		if (depth[v] == aoki)
		{
			break;
		}
		++result;
		++aoki;
	}
	while (aoki < depth[v])
	{
		if (!next[v])
		{
			v = *parent[v];
		}
		else
		{
			v = next[v]->first;
		}
		if (depth[v] == aoki)
		{
			break;
		}
		else
		{
			++result;
			++aoki;
		}
	}
	std::cout << result << std::endl;
}

