template<class T>
struct GraphNode {
    GraphNode(T data):
        neighbors(),
        data(data) 
    { }

    std::vector<GraphNode *> neighbors;
    T data;
};

template<class T>
class Graph {
public:
    enum CONTINUE_SEARCH {
        CONTINUE, END
    };

    Graph(const uint64_t num_nodes, T data):
        nodes(num_nodes, GraphNode<T>(data))
    { }

    GraphNode<T> &get_node(uint64_t n) {
        return nodes[n];
    }

    void add_bidirectional_edge(const uint64_t a, const uint64_t b) {
        nodes[a].neighbors.push_back(&nodes[b]);
        nodes[b].neighbors.push_back(&nodes[a]);
    }

    void depth_first_search(const uint64_t start_node, std::function<CONTINUE_SEARCH(GraphNode<T> &, uint64_t)> func) {
        auto searched_nodes = std::set<GraphNode<T> *>();
        depth_first_search_impl(nodes[start_node], func, searched_nodes, 0);
    }

private:
    void depth_first_search_impl(GraphNode<T> &node, std::function<CONTINUE_SEARCH(GraphNode<T> &, uint64_t)> func, std::set<GraphNode<T> *> &searched_nodes, uint64_t depth) {
        if(searched_nodes.find(&node) == searched_nodes.end()) {
            searched_nodes.insert(&node);
            if(func(node, depth) == CONTINUE_SEARCH::CONTINUE) {
                for(auto neighbor: node.neighbors) {
                    depth_first_search_impl(*neighbor, func, searched_nodes, depth + 1);
                }
            }
        }
    }

    std::vector<GraphNode<T> > nodes;
};

struct Data {
    uint64_t chaser_depth = 0;
    uint64_t runner_depth = 0;
};

GraphNode<Data> *node = nullptr;

uint64_t solve(Graph<Data> &g, uint64_t runner, uint64_t chaser) {
    g.depth_first_search(chaser, [](GraphNode<Data> &node, uint64_t depth) {
        node.data.chaser_depth = depth;
        return Graph<Data>::CONTINUE;
    });
    g.depth_first_search(runner, [](GraphNode<Data> &n, uint64_t depth) {
        if(n.data.chaser_depth <= depth) {
            return Graph<Data>::END;
        }
        n.data.runner_depth = depth;
        if(node == nullptr || node->data.chaser_depth < n.data.chaser_depth) {
            node = &n;
        }
        return Graph<Data>::CONTINUE;
    });
    return node->data.chaser_depth - 1;
}

int main() {
    uint64_t n, runner, chaser;
    std::cin >> n >> runner >> chaser;
    auto g = Graph<Data>(n, Data());
    for(int i = 0; i < n - 1; ++i) {
        uint64_t a, b;
        std::cin >> a >> b;
        g.add_bidirectional_edge(a - 1, b - 1);
    }

    std::cout << solve(g, runner - 1, chaser - 1);

    return 0;
}

