	REP(i, n-1) {
		--a[i]; --b[i];
		g[a[i]].emplace_back(b[i]);
		g[b[i]].emplace_back(a[i]);
	}

	V<bool> checked(n, false);
	checked[u] = true;
	V<int> depth(n, 0);
	{
		auto rec = [&](auto && f, int x, int par) -> void {
			for (auto&& to : g[x]) if (to != par) {
				depth[to] = depth[x] + 1;
				f(f, to, x);
			}
		};
		rec(rec, v, -1);
	}

	std::queue<int> que({ u });
	int D = 0;
	while (!que.empty()) {
		std::queue<int> que2;
		while (!que.empty()) {
			int now = que.front(); que.pop();
			if (depth[now] <= D) continue;
			for (auto& to : g[now]) {
				if (checked[to]) continue;
				if (depth[to] <= D) continue;
				checked[to] = true;
				que2.push(to);
			}
		}
		++D;
		std::swap(que, que2);
	}
	int ans = 1;
	REP(i, n) {
		if (checked[i]) CHMAX(ans, depth[i] - 1);
	}
	OUT(ans)BR;

	return 0;
}

