namespace edamat {
template <class Info>
struct edge {
    int from, to;
    Info info;
    edge(int to, Info info) : to(to), info(info) {}
    edge(int from, int to, Info info) : from(from), to(to), info(info) {}
};

//! graphは基底クラス！使うときはundirected_graphかdirected_graphを使う。
template <class Info>
class graph {
   protected:
    using edge_type = edge<Info>;
    ::std::size_t N;
    ::std::vector<::std::vector<edge_type>> edges;

   public:
    graph(::std::size_t N_) : N(N_), edges(N_) {}
    virtual void add_edge(int x, int y, Info info = static_cast<Info>(1)) = 0;
    const ::std::vector<edge_type> &delta(int v) const {
        assert(v < N);
        return edges[v];
    }
    const ::std::vector<edge_type> &operator[](int v) const {
        return this->delta(v);
    }
    ::std::size_t size() const noexcept { return N; }
};

template <class Info>
struct rooted_tree : public graph<Info> {
   private:
    int l;
    int root = -1;
    ::std::vector<int> depth;
    ::std::vector<::std::vector<int>> par;

   public:
    rooted_tree(::std::size_t N) : graph<Info>(N), depth(N) {
        l = 0;
        while((1 << l) < N) l++;
        par =
            ::std::vector<::std::vector<int>>(l, ::std::vector<int>(N + 1, -1));
    }
    void add_edge(int x, int y, Info info = static_cast<Info>(1)) {
        this->edges[x].push_back(edge<Info>(x, y, info));
        this->edges[y].push_back(edge<Info>(y, x, info));
    }
    const int parent(int v) { return par[0][v]; }

   private:
    void dfs1(int v, int p = -1, int d = 0) {
        if(p != -1) par[0][v] = p;
        depth[v] = d;
        for(auto &e : this->edges[v]) {
            if(e.to == p) continue;
            dfs1(e.to, v, d + 1);
        }
    }
    ::std::pair<Info, int> dfs2(int v, int p) {
        ::std::pair<Info, int> ret(0, v);
        for(auto &e : this->edges[v]) {
            if(e.to == p) continue;
            auto cost = dfs2(e.to, v);
            cost.first += e.info;
            ret = max(ret, cost);
        }
        return ret;
    }

   public:
    void build(int _root = 0) {
        assert(root == -1);
        root = _root;
        dfs1(root, -1, 0);
        for(int i = 0; i < l - 1; ++i) {
            for(int j = 0; j < this->size(); j++) {
                if(par[i][j] == -1)
                    par[i + 1][j] = -1;
                else
                    par[i + 1][j] = par[i][par[i][j]];
            }
        }
    }
    int lca(int x, int y) {
        assert(root != -1);
        if(depth[x] > depth[y]) ::std::swap(x, y);
        int dif = depth[y] - depth[x];
        for(int i = l - 1; i >= 0; i--) {
            if(dif & (1 << i)) {
                y = par[i][y];
            }
        }
        if(x == y) return x;
        for(int i = l - 1; i >= 0; i--) {
            int nx = par[i][x], ny = par[i][y];
            if(nx != ny) {
                x = nx;
                y = ny;
            }
        }
        return par[0][x];
    }
    int depth_dif(int x, int y) {
        assert(root != -1);
        int z = lca(x, y);
        return depth[x] + depth[y] - 2 * depth[z];
    }
    const Info diameter() {
        auto p = dfs2(0, -1);
        auto q = dfs2(p.second, -1);
        return (q.first);
    }
};
}  // namespace edamat

void solve() {
    int n, u, v;
    scanf("%d%d%d", &n, &u, &v);
    u--;
    v--;
    edamat::rooted_tree<int> g(n);
    rep(i, n - 1) {
        int a, b;
        scanf("%d%d", &a, &b);
        a--, b--;
        g.add_edge(a, b);
    }
    g.build(v);
    int ans = -1;
    rep(i, n) {
        auto x = g.lca(u, i);
        if(g.depth_dif(x, u) < g.depth_dif(x, v)) {
            ans = max(ans, g.depth_dif(v, i));
        }
    }
    std::cout << ans - 1 << std::endl;
}
int main() {
    /* main code */
    solve();
    return 0;
}

