vector<int> sssp(const vector<vector<int>> &G, int s) {
    const int INF = 1e9;
    vector<int> res(G.size(), INF); res[s] = 0;
    vector<bool> seen(G.size(), false);
    queue<int> que; que.emplace(s);
    while (!que.empty()) {
        int v = que.front(); que.pop();
        seen[v] = true;
        for (auto u : G[v]) if (!seen[u]) {
            res[u] = res[v] + 1;
            que.emplace(u);
        }
    }
    return res;
}

