vector<ll> dijkstra(int V, int s, vector<vector<ll>> &G) {
  vector<ll> d(V,LLONG_MAX);d[s]=0;
  priority_queue<P,vector<P>,greater<P>> q;q.push({0,s});
  while (!q.empty()) {
    int precost,v;tie(precost,v)=q.top();q.pop();
    if (d[v]<precost) continue;
    for (ll n:G[v]) {
      if (d[n]>d[v]+1) {
        d[n] = d[v]+1;
        q.push({d[n],n});
      }
    }
  }
  return d;
}

