int main() {
  int n, u, v; cin >> n >> u >> v; --u; --v;
  vector<vector<int> > graph(n);
  REP(_, n - 1) {
    int a, b; cin >> a >> b; --a; --b;
    graph[a].emplace_back(b);
    graph[b].emplace_back(a);
  }
  vector<int> dist_u(n, -1), dist_v(n, -1);
  dist_u[u] = dist_v[v] = 0;
  queue<int> que;
  que.emplace(u);
  while (!que.empty()) {
    int now = que.front(); que.pop();
    for (int e : graph[now]) {
      if (dist_u[e] == -1) {
        dist_u[e] = dist_u[now] + 1;
        que.emplace(e);
      }
    }
  }
  que.emplace(v);
  while (!que.empty()) {
    int now = que.front(); que.pop();
    for (int e : graph[now]) {
      if (dist_v[e] == -1) {
        dist_v[e] = dist_v[now] + 1;
        que.emplace(e);
      }
    }
  }
  int ans = 0;
  REP(i, n) {
    if (graph[i].size() == 1 && dist_u[i] < dist_v[i]) {
      ans = max(ans, dist_v[i] - 1);
    }
  }
  cout << ans << '\n';
  return 0;
}

