vector<int> dijkstra(int i, int n, vector<vector<pair<int, int>>> graph) {
  vector<int> d(n, INF);
  d[i] = 0;
  priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> q;
  q.push(make_pair(0, i));
  while (!q.empty()) {
    pair<int, int> p = q.top();
    q.pop();
    int v = p.second;
    if (d[v] < p.first) {
      continue;
    }
    for (auto x : graph[v]) {
      if (d[x.first] > d[v] + x.second) {
        d[x.first] = d[v] + x.second;
        q.push(pair<int, int>(d[x.first], x.first));
      }
    }
  }
  return d;
}

signed main() {
  int N, u, v; 
  cin >> N >> u >> v;
  u--; v--;

  vector<vector<pair<int, int>>> graph(N);
  REP(i, N-1){
    int a, b;
    cin >> a >> b;
    a--; b--;
    graph[a].emplace_back(b, 1);
    graph[b].emplace_back(a, 1);
  }

  vector<int> dist1 = dijkstra(u, N, graph);
  vector<int> dist2 = dijkstra(v, N, graph);

  int ans = (dist1[v]-1)/2;
  bool tonari = false;
  if(dist1[v]%2){
    tonari = true;
  }

  int dist = dist1[v];
  int now;
  int ng;
  REP(i, N){
    if(dist1[i] == ans && dist2[i] == dist-ans) now = i;
    if(dist1[i] == ans+1 && dist2[i] == dist-ans-1) ng = i;
  }

  queue<int> q;
  q.push(now);
  vector<int> d(N, INF);
  d[now] = 0;
  while(!q.empty()){
    int p = q.front(); q.pop();
    for(auto v : graph[p]){
      if(d[v.first] != INF) continue;
      if(v.first == ng) continue;
      q.push(v.first);
      d[v.first] = d[p]+1;
    }
  }

  int MAX = 0;
  REP(i, N){
    if(d[i] == INF) continue;
    chmax(MAX, d[i]);
  }

  if(!tonari) ans++;
  ans += MAX;

  cout << ans << endl;

  return 0;
}

