    rep(i, N - 1) {
        var(int, a, b);
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }

    if (N == 2) {
        return outl(0), 0;
    }

    queue<int> que_u;
    que_u.emplace(u);

    vector<int> dist_u(N + 1, INF);
    dist_u[u] = 0;

    while (!que_u.empty()) {
        int nowNode = que_u.front();
        que_u.pop();
        for (auto nextNode: G[nowNode]) {
            if (chmin(dist_u[nextNode], dist_u[nowNode] + 1)) {
                que_u.emplace(nextNode);
            }
        }
    }

    queue<int> que_v;
    que_v.emplace(v);

