using namespace std;

const int maxn = 1e5+10;
const int INF = 1e9+10;

vi g[maxn];
int du[maxn],dv[maxn];
map<int,vi> mp1,mp2;

void bfs(int u,int v){
	for(int i=0;i<maxn;++i){
		du[i]=dv[i]=INF;
	}
	du[u]=0;
	dv[v]=0;
	queue<int> q;
	q.push(u);
	while(!q.empty()){
		int x=q.front();
		q.pop();
		for(auto &w:g[x]){
			if(du[x]+1 < du[w]){
				du[w] = du[x]+1;
				mp1[du[x]+1].pb(w);
				q.push(w);
			}
		}
	}
	q.push(v);
	while(!q.empty()){
		int x=q.front();
		q.pop();
		for(auto &w:g[x]){
			if(dv[x]+1 < dv[w]){
				dv[w] = dv[x]+1;
				mp2[dv[x]+1].pb(w);
				q.push(w);
			}
		}
	}
}

