	int ans=0,f=0;
	bool end=false;
	while(!end){
		bool ok=false;
		int aux=u;
		for(auto &x:mp1[du[u]+1]){
			if(x!=v && binary_search(all(g[u]),x)){
				u=x;
				ok=true;
				break;
			}
		}
