using namespace std;

struct Node {
    vector<Node> children;
    INT depth;
    INT id;
    INT pid;
};

int main(){
    INT N, u, v;
    cin >> N >> u >> v;

    unordered_multimap<INT, INT> path;
    FOR(i, N-1){
        INT A, B;
        cin >> A >> B;
        path.emplace(A, B);
        path.emplace(B, A);
    }

    vector<Node*> nodes(N+1);

    Node root;
    root.depth = 0;
    root.id    = v;
    root.pid   = -1;
    nodes[v] = &root;

    auto treeBuild = [&](auto treeBuild, INT pid, INT id, INT depth, vector<Node>& children_vec ) -> void {
        auto range = path.equal_range( id );
        auto it = range.first;
        while( it != range.second ){
            INT cid = it->second;
            if( cid != pid ){
                Node tmp;
                tmp.depth = depth+1;
                tmp.id = cid;
                tmp.pid = id;
                children_vec.emplace_back(tmp);
                nodes[cid] = &children_vec[children_vec.size()-1];
                treeBuild( treeBuild, nodes[cid]->pid, nodes[cid]->id, nodes[cid]->depth, nodes[cid]->children );
            }
            it++;
        }
    }; 
    treeBuild( treeBuild, root.pid, root.id, root.depth, root.children );

    auto max_depth = []( auto max_depth, Node& node, INT depth, INT ignore_id )->INT {
        INT ret = depth;
        for( Node& child : node.children ){
            if ( child.id != ignore_id ){
                chmax( ret, max_depth(max_depth, child, depth+1, -2) );
            }
        }
        return ret;
    };

    INT ans = 0;
    INT d1 = nodes[u]->depth;
    INT t = 0;
    Node* node = nodes[u];
    INT last_id = -2;
    do {
        INT d2 = max_depth(max_depth, *node, 0, last_id);
        chmax( ans, (d1+d2-1+t) );
        last_id = node->id;
        node = nodes[ node->pid ];
        d1 -= 2;
        t++;
    } while (d1 > 0);

    cout << ans << endl;

    return 0;
}

#include<iostream>
#include<vector>
#include<queue>
using namespace std;
const int BUF = 100005;


int nNode, s, t;
vector<int> adj[BUF];

void read() {
    for (int i = 0; i < BUF; ++i) adj[i].clear();

    cin >> nNode >> s >> t;
    --s;
    --t;
    for (int i = 0; i < nNode - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
}


void bfs(int bgn, int cost[BUF]) {
    queue<int> Q;

    cost[bgn] = 0;
    Q.push(bgn);

    while (!Q.empty()) {
        int cur = Q.front();
        Q.pop();

        for (int i = 0; i < adj[cur].size(); ++i) {
            int nex = adj[cur][i];
            if (cost[nex] == -1) {
                cost[nex] = cost[cur] + 1;
                Q.push(nex);
            }
        }
    }
}


void work() {
    int costS[BUF];
    int costT[BUF];
    memset(costS, -1, sizeof(costS));
    memset(costT, -1, sizeof(costT));
    bfs(s, costS);
    bfs(t, costT);

    int ans = 0;
    for (int i = 0; i < nNode; ++i) {
        if (costS[i] < costT[i]) continue;

        if (costS[i] % 2 == costT[i] % 2) {
            if (adj[i].size() == 1)
                ans = max(ans, costS[i] - 2);
            else
                ans = max(ans, costS[i]);
        } else {
            ans = max(ans, costS[i] - 1);
        }
    }
    cout << ans << endl;
}


int main() {
    read();
    work();
    return 0;
}

