  while(!que.empty()){
    int v=que.front();
    que.pop_front();
    for(int nv : g[v]){
      if(dist[nv]!=-1 || dist[v]+1>dis[nv]) continue;
      dist[nv]=dist[v]+1;
      if(dist[nv]<dis[nv]) que.pb(nv);
    }
  }  

  int an=-1;
  int ans;
  rep(i,n){
    if(chmax(an,dist[i])) {
      if(dist[i]==dis[i]) ans=dis[i];
      else ans=dis[i]-1;
    }
  }

  cout << ans << endl;
}

