void GetDistAoki(vector<vector<int>>& adj, int start, vector<int>& dist) {
  int N = adj.size();
  dist[start] = 0;
  queue<int> q;
  q.push(start);
  int d = 1;
  while (q.size()) {
    for (int iq = q.size()-1; iq >= 0; --iq) {
      int from = q.front(); q.pop();
      for (auto to : adj[from]) {
        if (dist[to] == -1) {
          dist[to] = d;
          q.emplace(to);
        }
      }
    }
    ++d;
  }
}
void DFS(int from, vector<vector<int>>& adj, vector<int>& dist_aoki, ll steps, ll& ans, vector<array<int,2>>& max_steps) {
  if (max_steps[from][steps&1] > steps) return;
  max_steps[from][steps&1] = steps;

  ans = max(ans, steps);
  for (auto to : adj[from]) {
    if (steps+1 < dist_aoki[to]) {
      DFS(to, adj, dist_aoki, steps+1, ans, max_steps);
    } else if (steps+1 == dist_aoki[to]) {
      ans = max(ans, steps+1);
    }
  }
}
