template <typename T>
struct WeightedGraph
{
    int n;
    vector<vector<Edge<T>>> g;

    WeightedGraph(int n) : n(n){
        g.resize(n);
    }

    void init(int n_){
        n = n_;
        g.resize(n_);
    }

    void add_edge(int from, int to, T cost){
        g[from].push_back((Edge<T>){to, cost});
    }
};

struct Graph
{
    int n;
    vector<vector<int>> g;

    Graph(int n) : n(n){
        g.resize(n);
    }

    void init(int n_){
        n = n_;
        g.resize(n_);
    }

    void add_edge(int from, int to){
        g[from].push_back(to);
    }
};

template <typename T>
vector<T> Dijkstra(WeightedGraph<T> &g, int s){
    int n = g.n;
    vector<T> d(n);
    fill(d.begin(), d.end(), -1);
    queue<int> que;
    d[s] = 0;
    que.push(s);
    while(que.size()){
        int now = que.front();
        que.pop();
        for(Edge<T> e : g.g[now]){
            if(d[e.to] == -1){
                d[e.to] = d[now] + e.cost;
                que.push(e.to);
            }
        }
    }
    return d;
}

