template<typename F>
decltype(auto) fix(F&& f) {
	return[f = std::forward<F>(f)](auto&&... args) {
		return f(f, std::forward<decltype(args)>(args)...);
	};
}

int main() {
	int n, u, v;
	std::cin >> n >> u >> v;
	--u, --v;

	std::vector<std::vector<int>> edges(n);
	for (int i = 0; i < n - 1; ++i) {
		int a, b;
		std::cin >> a >> b;
		--a, --b;

		edges[a].push_back(b);
		edges[b].push_back(a);
	}

	auto dfs = fix([&](auto f, int x, int depth, std::vector<int>& dists) -> void {
		dists[x] = depth;

		for (auto&& to : edges[x])
			if (dists[to] == -1)
				f(f, to, depth + 1, dists);
	});

	std::vector<int> tak(n, -1), aok(n, -1);
	dfs(u, 0, tak);
	dfs(v, 0, aok);

	int ans = 0;
	for (int i = 0; i < n; ++i)
		if (tak[i] < aok[i])
			ans = std::max(ans, aok[i]);

	std::cout << ans - 1 << std::endl;
}

