const ll MAX_N = 1e5;
vector<ll> G[MAX_N];
ll distance_U[MAX_N];
ll distance_V[MAX_N];

// 深さ優先探索
ll seen[MAX_N];
void dfs(ll i, ll d, ll distance[], int N){// i: 今いる場所, d: ここまでの移動距離, distance[]: 各頂点の距離, N: distanceの要素数
	ll G_size = G[i].size();
	// printf("i %lld, size: %lld\n", i, G_size);
    seen[i] = true; // i を訪問済にする
	distance[i] = d; // 距離を記録
    // i から行ける各頂点 next_i について
	REP(j,G_size){
		ll next_i = G[i][j];
		// printf("dfs %lld-> %lld\n", i, next_i);

        if (seen[next_i]) continue; // next_v が探索済だったらスルー
		dfs(next_i, d+1, distance, N); // 再帰的に探索
	}
}

int main() {
