	// 	}
	// 	printf("\n");
	// }
	// 解法
	REP(i,N)seen[i] = false; // 全頂点を「未訪問」に初期化
	dfs(u, 0, distance_U, N); // 高橋君の各頂点までの距離
	REP(i,N)seen[i] = false; // 全頂点を「未訪問」に初期化
	dfs(v, 0, distance_V, N); // 高橋君の各頂点までの距離
	// REP(i,N)printf("i: %lld, dist U: %lld\n",i, distance_U[i]);
	// REP(i,N)printf("i: %lld, dist V: %lld\n",i, distance_V[i]);
	ll ans = 0;
	REP(i,N){
		if (distance_U[i]<=distance_V[i] & distance_V[i]>ans) ans = distance_V[i];
	}
	ans--;
	//出力
	printf("%lld\n", ans);
}

