using Graph = vector<vector<ll>>;
Graph G(100010);

queue<ll> Q;

void bfs(ll s,vector<ll>& table){ 
  for(int i = 0;i < table.size();i++){
    table[i] = INF;
  }
  table[s] = 0;
  Q.push(s);
  while(Q.size()){
    ll x = Q.front();
    ll n = G[x].size();
    Q.pop();
    for(ll i = 0;i < n;i++){
      ll y = G[x][i];
      if(table[y] == INF){
        table[y] = table[x] + 1;
        Q.push(y);
      }
    }
  }
  return ;
}

void dfs(ll x,ll a,vector<bool>& frag,vector<ll> tableT){
  ll n = G[x].size();
  ll d = tableT[x];
  for(int i = 0;i < n;i++){
    int y = G[x][i];
    if(!frag[y] && y != a){
      break;
    }
    if(y != a && tableT[y] == d + 1){
      frag[y] = 0;
      dfs(y,x,frag,tableT);
    }
  }
}
