void solve()
{
    int n, u, v;
    cin >> n >> u >> v;
    u--, v--;
    yukari<int> g(n);
    for (int i = 0; i < n - 1; i++)
    {
        int a, b;
        cin >> a >> b;
        a--, b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    queue<int> q;
    akari<int> ds(n, -1), ds2(n, -1);
    ds[u] = 0;
    q.push(u);
    while (!q.empty())
    {
        int curv = q.front();
        q.pop();
        for (int nv : g[curv])
        {
            if (ds[nv] != -1)
            {
                continue;
            }
            ds[nv] = ds[curv] + 1;
            q.push(nv);
        }
    }
    // for (int val : ds)
    // {
    //     cout << val << ' ';
    // }
    // cout << endl;

    ds2[v] = 0;
    q.push(v);
    while (!q.empty())
    {
        int curv = q.front();
        q.pop();
        for (int nv : g[curv])
        {
            if (ds2[nv] != -1)
            {
                continue;
            }
            ds2[nv] = ds2[curv] + 1;
            q.push(nv);
        }
    }
    // for (int val : ds2)
    // {
    //     cout << val << ' ';
    // }
    // cout << endl;
    int ans = 0;
    for (int i = 0; i < n; i++)
    {
        if (ds[i] <= ds2[i])
        {
            ans = max(ans, ds[i] + (ds2[i] - ds[i]) / 2);
        }
    }
    cout << ans << endl;
}

int main()
{
    solve();
    return 0;
}

