using Int = int_fast64_t;

class edge{
public:
	Int cost;
	size_t from, to;
	edge(Int c, size_t f, size_t t){
		cost = c;
		from = f;
		to = t;
	}
};
using edges = vector<edge>;
using graph = vector<edges>;
void readgraph(graph &g, size_t E, bool D, bool C, bool Z){ // E:num_of_edges, D:directed, C:costed, Z:already 0-indexed
	for(size_t i=0; i<E; ++i){
		edge e(1, 0, 0);
		if(!C) cin >> e.from >> e.to;
		else cin >> e.from >> e.to >> e.cost;
		if(!Z){
			--e.from;
			--e.to;
		}
		g[e.from].push_back(e);
		if(!D){
			swap(e.from, e.to);
			g[e.from].push_back(e);
		}
	}
}

void dfs(Int v, Int p, Int d, graph &g, vector<vector<Int>> &parent, vector<Int> &depth){
	parent[0][v] = p;
	depth[v] = d;
	for(auto e:g[v])
		if((Int)e.to != p)
			dfs(e.to, v, d+1, g, parent, depth);
}

void init(Int v, graph &g, vector<vector<Int>> &parent, vector<Int> &depth){
	dfs(v, -1, 0, g, parent, depth);
	for(Int k=0; k+1<20; ++k)
		for(Int i=0; i<(Int)g.size(); ++i){
			if(parent[k][i] < 0) parent[k+1][i] = -1;
			else parent[k+1][i] = parent[k][parent[k][i]];
		}
}

Int lca(Int a, Int b, vector<vector<Int>> &parent, vector<Int> &depth){
	if(depth[a] > depth[b]) swap(a, b);
	for(Int k=0; k<20; ++k)
		if((depth[b] - depth[a]) >> k & 1)
			b = parent[k][b];
	if(a == b) return a;
	for(Int k=19; k>=0; --k)
		if(parent[k][a] != parent[k][b]){
			a = parent[k][a];
			b = parent[k][b];
		}
	return parent[0][a];
}

