void solve() {
  int n;
  int p[2];
  cin >> n >> p[0] >> p[1];
  p[0]--; p[1]--;

  vector<vector<int> > g(n);
  rep(i, n - 1) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    g[a].eb(b);
    g[b].eb(a);
  }

  /*
  青木くんとぶつからない, 一番遠い葉へ向かう
  */

  vector<vector<int> > table(2, vector<int>(n, inf));

  rep(key, 2) {
    queue<int> q;
    q.push(p[key]);
    table[key][p[key]] = 0;

    while (!q.empty()) {
      int now = q.front();
      q.pop();

      for (int nxt : g[now]) {
        if (chmin(table[key][nxt], table[key][now] + 1)) {
          q.push(nxt);
        }
      }
    }
  }

  int meet = -1, ma = -1;
  rep(i, n) if (table[0][i] < table[1][i] && chmax(ma, table[0][i])) {
    meet = i;
  }
  // cout << meet << endl;
  cout << table[1][meet] - 1 << endl;
  // 高橋くんが葉に逃げるタイミングではつかまらない
}

