    pair<ll, ll> pos = que2.top(); que2.pop();
    if(w2[pos.first]<=pos.second) continue;
    w2[pos.first]=pos.second;
    REP(i,Tree[pos.first].size()){
      que2.push(make_pair(Tree[pos.first][i], pos.second+1));
    }
  }

  ll ans = 0;
  REP(i,N){
    if(w2[i]<w1[i]) continue;
    if(Tree[i].size()==1) continue;
    if(w1[v]&1 && (w2[i]-w1[i])&1) ans = max(ans, w2[i]);
    if(w1[v]%2==0 && (w2[i]-w1[i])%2==0) ans = max(ans, w2[i]);
  }

  OUT(ans);

  return 0;
}

