using namespace std;
const int LG = 18;
long long up[100005][LG], tin[200005], tout[100005], CLK = 1, lvl[100005];
vector<int> v[100005];
void dfspre(int u, int dad, int depth){
	tin[u] = CLK++;
	lvl[u] = depth;
	up[u][0] = dad;
	for(int i = 1; i < LG; ++i)
		up[u][i] = up[up[u][i-1]][i-1];
	for(auto i : v[u]) if(i != dad)
		dfspre(i, u, depth+1);
	tout[u] = CLK++;
}
bool is_ancestor(int x, int y){
	return tin[x] <= tin[y] && tout[y] <= tout[x];
}
int lca(int x, int y){
	if(is_ancestor(x,y)) return x;
	if(is_ancestor(y,x)) return y;

	for(int i = LG; i--;){
		if(!is_ancestor(up[x][i], y))
			x = up[x][i];
	}
	return up[x][0];
}
int dist(int x, int y){
	return lvl[x] + lvl[y] - 2*lvl[lca(x, y)];
}
int x, y, RES;
void dfs(int u, int dad){
	if(dist(u, y) <= dist(u, x)){
		RES = max(RES, dist(u, x) - (dist(x,y)%2));
		return;
	}
	for(auto i: v[u]) if(i != dad){
		dfs(i, u);
	}
	RES = max(RES, max(dist(u,x), dist(u,y)) - (dist(x,y)%2));
}
int main(){
	ios_base::sync_with_stdio(0);
	cin.tie(0);cout.tie(0);
	int n; cin >> n >> x >> y;
	for(int x, y, i = n; --i;){
		cin >> x >> y;
		v[x].push_back(y);
		v[y].push_back(x);
	}
	dfspre(x, x, 0);

	for(int i = 1; i <= n; ++i) if(dist(x, lca(i, y)) < dist(y, lca(i, y)) || (lca(i,y)==i && dist(x, lca(i, y)) == dist(y, lca(i, y)))){
		int ok = 0;
		for(int u: v[i]) if(dist(u, y) > dist(i, y)) ok = 1;
		if(!ok) continue;

		// cout << i << ' ' << dist(y, i) - dist(x, y)%2 << endl;
		RES = max(RES, dist(y, i));
	}
	cout << RES << endl;
}

