void dfs(const Graph &G, int v){
  seen[v] = true; // v を訪問済みにする

  // vから行ける各頂点 next_v について
  for(auto next_v : G[v]){
    if (seen[next_v]) continue; // next_v が探索済みだったらスルー
    // if(next_v == ao) break;
    if(A[v]+1 >= B[next_v]) continue;
    A[next_v] = A[v] + 1;
    dfs(G, next_v); // 再帰的に探索
  } 
}

void dfs1(const Graph &G, int v){
  seen1[v] = true; // v を訪問済みにする

