        v[y].push_back(x);
        if ((x==a&&y==b) || (x==b&&y==a)) {
            flag = true;
        }
    }

    if (flag) {
        cout << "0" << endl;
    } else {
        cout << bfs(n, a, b) << endl;
    }

    return 0;
}

