vector<int> dis(int v, int n, map<int,vector<int>> &m) {
  queue<int> q;
  q.push(v);
  vector<int> level(n,-1);
  level[v-1] = 0;
  while(!q.empty()) {
    int now = q.front();
    q.pop();
    for(auto next : m[now]) {
      if(level[next-1]!=-1) continue;
      q.push(next);
      level[next-1] = level[now-1]+1;
    }
  }
  return level;
}

