void dfs2(int pos, int pre, int step, vector<vector<int>>& to, vector<int>& vh,
          vector<int>& uh)
{
    uh[pos] = step;
    // dump(pos, step);
    if (vh[pos] <= step) {
        if (ans < vh[pos]) {
            ans = vh[pos];
        }
