	vector<vector<Edge<int>>> edges(N);
	for (int i = 0; i < N - 1; i++) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		edges[u].emplace_back(v, 1);
		edges[v].emplace_back(u, 1);
	}

	auto d_t = Dijkstra(edges, t);
	auto d_a = Dijkstra(edges, a);

	int max_d = 0, max_d2 = 0;

	auto dfs = [&](auto &&f, int now, int prev) -> void {


		for (const auto &e : edges[now]) {
			if (e.to == prev) continue;

			if (d_t[e.to] < d_a[e.to]) {
				chmax(max_d, d_a[e.to]);
				f(f, e.to, now);
			}
			else if (d_t[e.to] == d_a[e.to]) chmax(max_d2, d_t[e.to]);

		}

	};
	dfs(dfs, t, -1);

