inline int gi()
{
	int f = 1, x = 0; char c = getchar();
	while (c < '0' || c > '9') {if (c == '-') f = -1; c = getchar();}
	while (c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return f * x;
}

inline ll gl()
{
	ll f = 1, x = 0; char c = getchar();
	while (c < '0' || c > '9') {if (c == '-') f = -1; c = getchar();}
	while (c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return f * x;
}

const int maxn = 100003;

int n, gq, qm, tot, head[maxn], ver[maxn * 2], nxt[maxn * 2];
int dep[maxn], kk[maxn], fa[maxn], ans, now;

void dfs(int u, int f)
{
	dep[u] = kk[u] = dep[f] + 1, fa[u] = f;
	for (int i = head[u]; i; i = nxt[i])
	{
		int v = ver[i];
		if (v == f) continue;
		dfs(v, u);
		kk[u] = max(kk[u], kk[v]);
	}
}

inline void add(int u, int v)
{
	ver[++tot] = v, nxt[tot] = head[u], head[u] = tot;
}

int main()
{
	//freopen(".in", "r", stdin);
	//freopen(".out", "w", stdout);
	n = gi(), gq = gi(), qm = gi();
	for (int i = 1; i < n; i+=1)
	{
		int u = gi(), v = gi();
		add(u, v), add(v, u);
	}
	dfs(qm, 0);
	now = gq;
	while (1)
	{
		if (dep[gq] - dep[now] >= dep[now] - dep[qm]) break;
		ans = max(ans, kk[now] - 1);
		now = fa[now];
	}
	printf("%d\n", ans - 1);
	return 0;
}

