vvll in_Graph(ll nodeNum, ll edgeNum, bool isDirected){
	vvll to(nodeNum);
	REP(i, edgeNum){
		ll v, u;
		cin >> v >> u;
		v--; u--;
		to[v].push_back(u);
		if (!isDirected) to[u].push_back(v);
	}
	return std::move(to);
}


void solve()
{
	ll N, U, V;  cin >> N >> U >> V;
	U--; V--;
	vvll to = in_Graph(N, N-1, false);

	//親と深さを得る
	vll parent(N);
	vll depth(N);
	auto dfsP = [&](ll st){
		stack<ll> Q;
		Q.push(st);
		parent[st] = -1;
		depth[st] = 0;
		while (!Q.empty()){
			ll v = Q.top(); Q.pop();
			EACH(u, to[v]){
				if (u == parent[v]) continue;

				parent[u] = v;
				depth[u] = depth[v]+1;
				Q.push(u);
			}
		}
	};
	dfsP(V);

	//中央まで移動
	ll q = depth[U] / 2 + 1;
	ll uuu = U;
	while (true){
		if (depth[uuu] == q) break;
		uuu = parent[uuu];
	}

	//そこから一番深いところを得る
	auto dfs = [&](ll st)->ll{
		stack<ll> Q;
		Q.push(st);
		ll maxDepth = depth[st];
		while (!Q.empty()){
			ll v = Q.top(); Q.pop();
			EACH(u, to[v]){
				if (u == parent[v]) continue;

				chmax(maxDepth, depth[u]);
				Q.push(u);
			}
		}
		return maxDepth;
	};

	ll ans = dfs(uuu) - 1;
	cout << ans << '\n';
}


