llong dp[100005] = {-1, -1};

pair<int, int> dfs(int idx, int par) {
    pair<int, int> ret(0, idx);

    for (auto &e:to_edge[idx]) {
        if (e == par) continue;
        auto cost = dfs(e, idx);
        cost.first++;
        ret = max(ret, cost);
    }
    return ret;
}

void d(int idx, int par) {
    dp[idx]++;
    for (auto &e:to_edge[idx]) {
        if (e == par) continue;
        d(e, idx);
    }
}

pair<int, int> diam() {
    auto p = dfs(1, -1);
    auto q = dfs(p.second, -1);
    return {p.second, q.second};
}

