void dfs2(int u, int h, bool paint, int p = -1) {
  if (h >= 0 and vis[u]) {
    vis[u] = 0;
  }
  for (int i = 0; i < (int) adj[u].size(); ++i) {
    int v = adj[u][i];
    if (v != p) {
      dfs2(v, h - 1, !paint, u);
    }
  }
}

ll f(ll x) {
  memset(vis, 0, sizeof(bool) * n);
  dfs(u, !(x & 1));
  int cnt = 0;
  dfs2(v, x, 1);
  for (int u = 0; u < n; ++u) {
    cnt += !vis[u];
  }
  if (cnt != n) {
    memset(vis, 0, sizeof(bool) * n);
    dfs(u, !((x + 1) & 1));
    int cnt = 0;
    dfs2(v, x, 1);
    for (int u = 0; u < n; ++u) {
      cnt += !vis[u];
    }
    return cnt == n;
  }
  return 1;
}

bool predicate(ll mid, ll y) {
  return (y <= f(mid));
}

ll bs(ll lo, ll hi, ll y = 1) {
  if ( predicate(lo, y)) return lo;
  if (!predicate(hi, y)) return hi + 1;
  while (hi - lo > 1) {
    ll mid = lo + ((hi - lo) >> 1);
    if (predicate(mid, y)) hi = mid;
    else lo = mid;
  }
  return hi;
}

