    laz.resize(2*n-1, -1);    
  }

  inline void eval(int len, int k) {
    if ( laz[k] < 0 ) return;
    if ( k*2+1 < n*2-1 ) {
      laz[k*2+1] = laz[k];
      laz[k*2+2] = laz[k];
    }
    dat[k] = laz[k];
    laz[k] = -1;    
  }

  int update(int a, int b, int x, int k, int l, int r) {
    eval(r-l, k);
    if ( r <= a || b <= l ) return dat[k];
    if ( a <= l && r <= b ) return laz[k] = x;
    eval(r-l, k);
    dat[k] = max(update(a, b, x, k*2+1, l, (l+r)/2),
		 update(a, b, x, k*2+2, (l+r)/2, r));
    return dat[k];    
  }

  int query(int a, int b, int k, int l, int r) {
    eval(r-l, k);
    if ( r <= a || b <= l ) return def;
    if ( a <= l && r <= b ) return dat[k];
    int vl = query(a, b, k*2+1, l, (l+r)/2);
    int vr = query(a, b, k*2+2, (l+r)/2, r);
    return max(vl, vr);    
  }

  void update(int a, int b, int x) {
    update(a, b, x, 0, 0, n);    
  }

  int query(int a, int b) {
    return query(a, b, 0, 0, n);    
  }
};

using Pii = pair<int, int>;

int solve(int s, vector<int> &D) {  
  bool used[n];
  fill_n(used, n, false);
  queue<Pii> Q;
  Q.push(Pii(s, 0));
  while ( !Q.empty() ) {
    Pii q = Q.front(); Q.pop();
    int u = q.first, c = q.second;

    if ( used[u] ) continue;
    used[u] = true;
    D[u] = c;

    for ( int v: G[u] ) {
      if ( used[v] ) continue;
      Q.push(Pii(v, c+1));      
    }    
  }
}

