void  dijkstra(ll s){
    priority_queue<pll,vector<pll>,greater<pll>> que;
    fill(d,d+n,LLINF);
    d[s]=0;
    que.push(pll(0,s));
    prever = vll(n,-1);

    while(!que.empty()){
        pll p=que.top();que.pop();
        ll v=p.second;
        if(d[v]<p.first) continue;
        rep(i,(ll)G[v].size()){
            edge e=G[v][i];
            if(d[e.to]>d[v]+e.cost){
                d[e.to]=d[v]+e.cost;
                prever[e.to] = v;
                que.push(pii(d[e.to],e.to));
            }
        }
    } 
}

vll get_path(ll t){
    vll path;
    for(; t != -1;t=prever[t]){
        path.push_back(t);
    }

    reverse(path.begin(), path.end());
    return path;
}


