class Tree{
public:

    int N;
    vector<vector<int>> G;
    vector<int> aoki;
    vector<int> taka;
    int ans = 0;

    Tree(int _n){
        N = _n;
        G.resize(N);
        aoki.resize(N);
        taka.resize(N);
    }

    void make_edge(int s, int t){
        G[s].push_back(t);
        G[t].push_back(s);
    }

    void dfs_aoki(int n, int par){
        if(par == -1){
            aoki[n] = 0;
        }

        for(int i = 0; i < (int)G[n].size(); i++){
            int nxt = G[n][i];
            if(nxt != par){
                aoki[nxt] = aoki[n] + 1;
                dfs_aoki(nxt, n);
            }
        }
    }

    void dfs_taka(int n, int par){
        if(par == -1){
            taka[n] = 0;
        }

        for(int i = 0; i < (int)G[n].size(); i++){
            int nxt = G[n][i];
            if(nxt != par){
                taka[nxt] = taka[n] + 1;
                dfs_taka(nxt, n);
            }
        }
    }

    void print(){
        for(int i = 0; i < N; i++){
            cout << "i = " << i << endl;
            cout << "ao" << aoki[i] << endl;
            cout << "ta" << taka[i] << endl;
        }
    }

    int find_aoki_pos(int n){
        while(taka[n] - aoki[n] > 2){
            ans++;
            for(int i = 0; i < (int)G[n].size(); i++){
                int nxt = G[n][i];
                if(taka[nxt] == taka[n] - 1){
                    n = nxt;
                    break;
                }
            }
        }

        return n;
    }

    int find_taka_pos(int n){
        while(aoki[n] - taka[n] > 2){
            for(int i = 0; i < (int)G[n].size(); i++){
                int nxt = G[n][i];
                if(aoki[nxt] == aoki[n] - 1){
                    n = nxt;
                    break;
                }
            }
        }

        return n;
    }

    int dfs(int n, int par){
        int ret = 1;
        for(int i = 0; i < (int)G[n].size(); i++){
            int nx = G[n][i];
            if(nx != par && aoki[nx] == aoki[n] + 1){
                //cout << "nx = " << nx << endl;
                ret = max(ret, dfs(nx, n) + 1);
            }
        }

        return ret;
    }
};


int main(){
    int N, u, v;
    cin >> N >> u >> v;
    u--;
    v--;

    Tree tr = Tree(N);

    for(int i = 0; i < N - 1; i++){
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        tr.make_edge(a, b);
    }

    tr.dfs_aoki(v, -1);
    tr.dfs_taka(u, -1);

    int aft_taka = tr.find_taka_pos(u);
    int aft_aoki = tr.find_aoki_pos(v);

    //cout << aft_taka << " " << aft_aoki << endl;

