using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;
static const ll INF=1e18;
static const ll MAX=101010;
static const ll MOD=1e9+7;


ll N, U, V;
vector<ll> g[MAX];
ll ud[MAX], vd[MAX];

void dijkstra(ll s, ll* d) {
  ll i, u;
  ll clr[MAX];
  for(i=0; i<N; i++) {
    d[i]=INF;
    clr[i]=0;
  }
  priority_queue<P> q;
  q.push(P(0, s));
  d[s]=0;

  while(q.size()) {
    P f=q.top(); q.pop();
    u=f.sc;

    clr[u]=1;
    if(d[u]<-f.ft) continue;

    for(i=0; i<g[u].size(); i++) {
      ll v=g[u][i];
      if(clr[v]==0 && d[v]>d[u]+1) {
        d[v]=d[u]+1;
        q.push(P(-d[v], v));
      }
    }
  }
}

int main(void) {
  cin >> N >> U >> V;
  U--; V--;
  ll i;

  for(i=0; i<N-1; i++) {
    ll a, b;
    cin >> a >> b;
    a--; b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  dijkstra(U, ud);
  dijkstra(V, vd);

  ll ans=0;
  for(i=0; i<N; i++)
    if(vd[i]>ud[i])
      chmax(ans, vd[i]-1);

