LL calcMaxDepth(LL cur, LL parent, LL depth, vector<vector<LL>>& edge, vector<LL>& max_depth){
    LL ret = depth;
    for(LL next: edge[cur]){
        if(next == parent) continue;
        ret = max<LL>(ret, calcMaxDepth(next, cur, depth+1, edge, max_depth));
    }
    max_depth[cur] = ret;
    return ret;
}

bool findPath(LL cur, LL parent, LL target, vector<vector<LL>>& edge, vector<LL>& path){
    path.push_back(cur);
    if(cur == target) return true;
    for(LL next: edge[cur]){
        if(next == parent) continue;
        if(findPath(next, cur, target, edge, path)){
            return true;
        }
    }
    path.pop_back();
    return false;
}


