void solve(){
    ll n, x, y; cin >> n >> x >> y;
    x --; y --;
    vector<vector<ll>> E(n);
    rep(_, n - 1){
        ll u, v; cin >> u >> v;
        u --; v --;
        E[u].push_back(v);
        E[v].push_back(u);
    }

    // x rooted depth
    vector<ll> xdepth(n, -1);
    xdepth[x] = 0;
    vector<ll> stack{x};
    while(!stack.empty()){
        ll v = stack.back(); stack.pop_back();
        for(auto& nv : E[v]){
            if(xdepth[nv] != -1){
                continue;
            }
            xdepth[nv] = xdepth[v] + 1;
            stack.push_back(nv);
        }
    }

    // y rooted depth
    vector<ll> ydepth(n, -1);
    ydepth[y] = 0;
    stack.clear();
    stack.push_back(y);
    while(!stack.empty()){
        ll v = stack.back(); stack.pop_back();
        for(auto& nv : E[v]){
            if(ydepth[nv] != -1){
                continue;
            }
            ydepth[nv] = ydepth[v] + 1;
            stack.push_back(nv);
        }
    }

    ll res = 0;
    rep(v, n){
        if(xdepth[v] < ydepth[v]){
            chmax(res, ydepth[v] - 1);
        }
    }
    cout << res << endl;
}

