struct UnionFind {
  VL data;
  UnionFind(int size) : data(size, -1) { }
  bool unite(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool find(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  ll size(int x) {
    return -data[root(x)];
  }
  ll num_root(ll size){
    VL roots;
    re(i,size)roots.pb(root(i));
    sort(all(roots));
    roots.erase(unique(all(roots)),roots.end());
    return roots.size();
  }
};


struct graph{
    ll V;
    vector<VP > v;
    graph(ll V) : V(V), v(vector<VP >(V)){}
    void add_diedge(ll v1, ll v2, ll w){
        v[v1].pb({v2, w});
        v[v2].pb({v1, w});
    }
    void add_edge(ll v1, ll v2, ll w){
        v[v1].pb({v2, w});
    }
    VL vval = vector<ll>(V, 0);
    VL dist = vector<ll>(V, -1);
    VL prever = vector<ll>(V,-1);
    set<ll> leaves;
    VL dijkstra(ll start){
        priority_queue<P, vector<P>, greater<P> > que;
        que.push(P(0,start));
        while(!que.empty()){
            P pa = que.top();
            que.pop();
            ll u = pa.se;
            if(dist[u] >= 0 && dist[u] < pa.fi)continue;
            dist[u]=pa.fi;
            for(P e : v[u]){
                if(dist[e.fi] < 0 || dist[e.fi] > dist[u] + e.se){
                    dist[e.fi] = dist[u] + e.se;
                    prever[e.fi] = u;
                    que.push(P(dist[e.fi],e.fi));
                }
            }
        }
        return dist;
    }
    void dfs(ll now, ll prv, ll c){
        vval[now]+=c;
        for(auto nxt : v[now])if(nxt.fi != prv){
            dfs(nxt.fi, now, vval[now]);
        }
    }
    VL bfs(ll start){
        VL dist(V,-1);
        queue<ll> Q;
        Q.push(start);
        dist[start]=0;
        ll now;
        while(!Q.empty()){
            now = Q.front();
            Q.pop();
            ll cnt=0;
            for(auto nxt : v[now]){
                if(dist[nxt.fi]==-1){
                    cnt++;
                    dist[nxt.fi]=0;
                    dist[nxt.fi]+=dist[now]+1;
                    Q.push(nxt.fi);
                }
            }
            if(cnt==0)leaves.insert(now);
        }
        return dist;
    }
    void gprll(){
        re(i,V){ps(i);ps(": ");for(P x : v[i]){ps(x.fi);ps(",");ps(x.se);ps(" ");}p("");}
    }
    vector<VL> dd = vector<VL>(V, VL(V,inf)); 
    void warshall_floyd() {
      re(i,V)for(P e: v[i])dd[i][e.fi]=e.se;
      d(dd[0][2]);
      re(k,V)re(i,V)re(j,V)dd[i][j] = min(dd[i][j], dd[i][k] + dd[k][j]);
    }
};



