        que.pop();
        for(int x : G[n]){
            if(disto[x] == INF){
                disto[x] = disto[n] + 1;
                que.push(x);
            }
        }
    }
    vecout(distn);
    vecout(disto);
    ll ans = 0;
    vector<bool> use(N);
    rep(i,N){
        if(disto[i] == distn[i] && !use[i]){
            use[i] = 1;
            ll now = i;
            while(1){
                ll next = -1;
                for(int x : G[now]){
                    if(disto[x] == distn[x] && disto[now] - 1 == disto[x]){
                        next = x;
                        use[x] = 1;
                        break;
                    }
                }
                if(next == -1)break;
                now = next;
            }
            chmax(ans,disto[now]);
        }
    }
    rep(i,N){
        if(disto[i] < distn[i])continue;
        else if(disto[i] > distn[i]){
            chmax(ans,disto[i] - 1);
        }
    }
    cout << ans << "\n";
}

