			continue;
		son[ x ].push_back( e[ x ][ i ] );
		fa[ e[ x ][ i ] ] = x;
		dep[ e[ x ][ i ] ] = dep[ x ] + 1;
		dfs( e[ x ][ i ] );
		ma[ x ] = max( ma[ x ], ma[ e[ x ][ i ] ] );
	}
}

