const int INF = 1e9;
const int MAX = 100010;
vector<int> edge[MAX];

void bfs(int start, vector<int> &dist) {
	for(int i = 0; i < MAX; ++i) {
		dist[i] = INF;
	}
	queue<pair<int, int>> que;
	que.emplace(start, 0);
	while(not que.empty()) {
		int from, cost;
		tie(from, cost) = que.front();
		que.pop();
		if(dist[from] <= cost) continue;
		dist[from] = cost;
		for(int to : edge[from]) {
			que.emplace(to, cost + 1);
		}
	}
}

int main() {
	int n; cin >> n;
	int u, v; cin >> u >> v;
	--u, --v;
	for(int i = 0; i < n - 1; ++i) {
		int a, b; cin >> a >> b;
		--a, --b;
		edge[a].push_back(b);
		edge[b].push_back(a);
	}
	vector<int> udist(MAX), vdist(MAX);
	bfs(u, udist);
	bfs(v, vdist);
	int ans = 0;
	for(int i = 0; i < n; ++i) {
		if(udist[i] < vdist[i]) {
			ans = max(ans, udist[i] + (vdist[i] - udist[i] - 1));
		}
	}
	cout << ans << '\n';
	return 0;
}

