vector<int> bfs(vector<vector<int>> &G, int N, int s) {
    vector<int> res(N, INF);
    res[s] = 0;
    queue<int> que;
    que.push(s);
    while (!que.empty()) {
        int u = que.front(); que.pop();
        for (int v : G[u]) {
            if (res[v] != INF) continue;
            res[v] = res[u] + 1;
            que.push(v);
        }
    }
    return res;
}

