struct Tmp {
  int u, v, count;
  bool isTakahashi;
};

void solve(void)
{
  int N; cin >> N;
  int u, v; cin >> u >> v;
  --u, --v;
  vector<vector<int>> tree(N);
  for (int _ = 0; _ < N-1; ++_) {
    int a, b; cin >> a >> b;
    --a; --b;
    tree[a].push_back(b);
    tree[b].push_back(a);
  }
  // using Pair = pair<int, int>;
  std::deque<Tmp> que{};
  que.push_back({u, v, 0, true});
  int ans{-1};
  vector<int> aokiMemo(N, -1);
  aokiMemo[v] = 0;
  while (!que.empty()) {
    auto node = que.front();
    que.pop_front();
    if (node.u == node.v) {
      chmax(ans, node.count);
      continue;
    }
    if (node.isTakahashi) {
      for (const auto& next : tree[node.u]) {
        que.push_back({next, node.v, node.count, false});
      }
    }
    else {
      aokiMemo[node.v] = node.count;
      for (const auto& next : tree[node.v]) {
        if (aokiMemo[next] == -1) {
          que.push_back({node.u, next, node.count+1, true});
        }
      }
    }
  }
  cout << ans << CRLF;
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

