void dijkstra(int s){
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d + V, INF);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()){
        P p = que.top(); que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        for (int i = 0; i < G[v].size(); i++){
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
    //fprintf(stderr, "%d, %d, %d\n", V, T, S);
    //for (int i = 0; i < V; i++){
    //    fprintf(stderr, "%d, %d: %d\n", s, i, d[i]);
    //}
    //exit(1);
    return;
}

int dfs(int v) {
    // �s�����������C���N�������g���Ȃ��烁��
    int dep = 0;
    seen[v] = true; // v ��K��ςɂ���
    for (int i = 0; i < G[v].size(); i++){
        edge e = G[v][i];
        if (seen[e.to]) continue; 
        int tmp = dfs(e.to);
        dep = max(tmp, dep);
    }

    // �A�肪�������C���N�������g���Ȃ��烁��
    depth[v] = dep + 1;
    return depth[v];
}

