        cin >> A[i] >> B[i];
        C[i] = 1;
        G[A[i] - 1].push_back((edge){B[i] - 1, C[i]});
        G[B[i] - 1].push_back((edge){A[i] - 1, C[i]});
    }



    dijkstra(S);
    seen.assign(V, false); // �S���_���u���K��v�ɏ�����
    nnext.assign(V, -1); // �S���_���u���K��v�ɏ�����
    dfs(S);

    int c = T;
    while(1){
        int next;

        for (int i = 0; i < G[c].size(); i++){
           edge e = G[c][i];
           if (d[e.to] < d[c]){
                next = e.to;
                break;
           }
        }

        nnext[next] = c;
        if (next == S){
            break;
        }
        c = next;
    }

