  }

  vector<int> distA(N, -1);
  distA[v] = 0;
  dfs(G, v, distA);

  vector<int> distT(N, -1);
  distT[u] = 0;
  int answer = dfs2(G, u, distT, distA);
  cout << answer << endl;
