ll power(ll x, ll y, ll p)
{ 
    ll res = 1;  
    x = x % p;
    while (y > 0) { 
        if (y & 1) res = (res * x) % p; 
        y = y >> 1;
        x = (x * x) % p;   
    } 
    return res; 
}
const ll L = 1e5 + 5;
const ll logn = 20;
ll parent[L];
ll dp[L][logn + 5];
vector <ll> ad[L];
ll vis[L];
ll depth[L];
void dfs(ll ind, ll par)
{
	vis[ind] = 1;
	parent[ind] = par;
	for (ll v : ad[ind]) {
		if (!vis[v]) {
			depth[v] = depth[ind] + 1;
			dfs(v, ind);		
		}
	}
}
ll lca(ll u, ll v)
{
	if (depth[u] < depth[v])
		swap(u, v);
	ll dist = depth[u] - depth[v];
	for (ll i = logn; i >= 0; i--) {
		ll temp = dist - (1 << i);
		if (temp >= 0) {
			dist -= (1 << i);
			u = dp[u][i];
		}
	}
	if (u == v)
		return u;
	for (ll i = logn; i >= 0; i--) {
		if (dp[u][i] != dp[v][i]) {
			u = dp[u][i];
			v = dp[v][i];
		} 
	}
	return parent[u];
}
