 	for (ll i = 1; i < n; i++) {
 		cin >> x >> y;
 		x--, y--;
 		ad[x].pb(y);
 		ad[y].pb(x);
 	}
 	dfs(v, v);
 	for (ll i = 0; i < n; i++) {
 		for (ll j = 0; j <= logn; j++) {
 			dp[i][j] = 0;
 		}
 	}
 	ll mxd = depth[u];
 	ll mxi = u;
 	for (ll i = 0; i < n; i++) {
 		if (depth[i] > mxd) {
 			mxd = depth[i];
 			mxi = i;
 		}	
 		dp[i][0] = parent[i];
 	}
 	for (ll j = 1; j <= logn; j++) {
 		for (ll i = 0; i < n; i++) {
 			dp[i][j] = dp[dp[i][j - 1]][j - 1];
 		}
 	}
 	ll ans;
 	if (mxi == u) {
 		ans = depth[u] - 1;
 	}
 	else {
 		ll com = lca(u, mxi);
 		ll dist1 = depth[com];
 		ll dist2 = depth[u] - depth[com];
 		if (dist1 > dist2) {
 			ans = mxd - 1;
 		}
 		else {
 			ans = depth[u] - 1;
 		}
 	}
 	cout << ans << endl;
 	return 0;
}

