void dfs(Graph &G, int v, vector<bool> &seen, int mokuteki, vector<int> &depth){
  seen.at(v) = true;
  for (auto nv : G.at(v)){
    if (seen.at(nv)) continue;
    if (nv == mokuteki) continue;
    depth.at(nv) = depth.at(v) + 1;
    dfs(G, nv, seen, mokuteki, depth);
  }
  return;
}

void dfsdis(Graph &G, int v, vector<bool> &seen, int mokuteki, vector<int> &depth){
  // mokutekiから見たvの距離
  seen.at(v) = true;
  for (auto nv : G.at(v)){
    if (seen.at(nv)) continue;
    dfsdis(G, nv, seen, mokuteki, depth);
    if (depth.at(nv) != -1) depth.at(v) = depth.at(nv) + 1;
  }
  return;
}

