  }
  int ans = 0;

  vector<bool> seen(N,false);
  vector<int> depths(N, -1);
  depths.at(U) = 0;
  dfsdis(G, V, seen, U, depths);
  int inidis = depths.at(V); //最初のUとVの距離
  for (int i=0; i<(inidis-1)/2; i++){
    // UはまずなるべくVに近づいていく
    depths.assign(N, -1);
    seen.assign(N, false);
    depths.at(V) = 0;
    dfsdis(G, U, seen, V, depths);
    for (int i=0; i<N; i++){
      if (depths.at(i) == depths.at(U) - 1){
        U = i;
        break;
      }
    }
    // VもUへ近づいていく
    depths.assign(N, -1);
    seen.assign(N, false);
    depths.at(U) = 0;
    dfsdis(G, V, seen, U, depths);
    for (int i=0; i<N; i++){
      if (depths.at(i) == depths.at(V) - 1){
        V = i;
        break;
      }
    }
    ans++;
  }

  // 下の操作を行うために例外処理
  int bufV = V;
  if (inidis % 2 == 0){
    // UとVの間に頂点が一つあるはず。そこを予め潰しておく
    depths.assign(N, -1);
