using namespace std;

using ll = long long;

struct LCA {
    using Graph = vector< vector<int> >;

    const Graph& g;
    const int LOGV;
    const int root;

    vector< vector<int> > parent;
    vector<int> depth;

    LCA(const Graph& g, int root = 0) : g(g), LOGV(32 - __builtin_clz(g.size())), root(root) {
        int V = g.size();
        parent.resize(LOGV, vector<int>(V));
        depth.resize(V);

        dfs(root, -1, 0);
        for (int k = 0; k + 1 < LOGV; k++) {
            for (int v = 0; v < V; v++) {
                if (parent[k][v] < 0) parent[k + 1][v] = -1;
                else parent[k + 1][v] = parent[k][parent[k][v]];
            }
        }
    }

    void dfs(int v, int p, int d) {
        parent[0][v] = p;
        depth[v] = d;
        for (int i : g[v]) {
            if (i != p) dfs(i, v, d + 1);
        }
    }

    int operator()(int u, int v) const {
        if (depth[u] > depth[v]) swap(u, v);
        for (int k = 0; k < LOGV; k++) {
            if ((depth[v] - depth[u]) >> k & 1) {
                v = parent[k][v];
            }
        }
        if (u == v) return u;
        for (int k = LOGV - 1; k >= 0; k--) {
            if (parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }
};

void dfs(int cur, int par, const vector< vector<int> >& g, vector<int>& ps, vector<int>& d) {
    ps[cur] = par;
    for (int nex : g[cur]) {
        if (nex == par) continue;
        d[nex] = d[cur] + 1;
        dfs(nex, cur, g, ps, d);
    }
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n, u, v;
    cin >> n >> u >> v;
    --u; --v;

    vector< vector<int> > g(n);
    for (int i = 1; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    vector<int> ps(n, -1), d(n, 0);
    dfs(u, -1, g, ps, d);
    int root = v;
    for (int i = 0; i < d[v] / 2; ++i) {
        root = ps[root];
    }

    LCA lca(g, root);
    auto calc = [&](int a, int b) {
        return lca.depth[a] + lca.depth[b] - lca.depth[lca(a, b)] * 2;
    };

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (lca(i, u) == root) {
            ans = max(ans, d[u] / 2);
        } else {
            int du = calc(i, u), dv = calc(i, v);
            if (du <= dv) {
                // cerr << i << " " << du << " " << du + max(dv - du - 1, 0) << endl;
                ans = max(ans, du + max(dv - du - 1, 0));
            } else {
                assert(false);
            }
        }
    }
    cout << ans << "\n";
    return 0;
}

