	vi taka(N, 1 << 30), aoki(N, 1 << 30);
	taka[u] = aoki[v] = 0;
	std::queue<int> bfs;
	bfs.push(u);
	while (!bfs.empty())
	{
		auto now{bfs.front()};
		bfs.pop();
		for (auto& e: edges[now])
		{
			if (taka[e] != (1 << 30)) continue;
			taka[e] = taka[now] + 1;
			bfs.push(e);
		}
	}
	bfs.push(v);
	while (!bfs.empty())
	{
		auto now{bfs.front()};
		bfs.pop();
		for (auto& e: edges[now])
		{
			if (aoki[e] != (1 << 30)) continue;
			aoki[e] = aoki[now] + 1;
			bfs.push(e);
		}
	}
	int ans{1};
	int dist{aoki[u]};
	if (dist % 2 == 1)
	{
		for (int i{}; i < N; i++)
		{
			if (aoki[i] <= taka[i] || aoki[i] + taka[i] == dist) continue;
			if (aoki[i] - taka[i] == dist)
				ans = std::max(ans, dist / 2 * 2 + taka[i]);
			else
			{
				int corner{(dist - (aoki[i] - taka[i])) / 2};
				ans = std::max(ans, dist / 2 * 2 + taka[i] - corner * 2);
			}
		}
	}
	else
	{
		for (int i{}; i < N; i++)
		{
			if (aoki[i] <= taka[i] || aoki[i] + taka[i] == dist) continue;
			if (aoki[i] - taka[i] == dist)
