constexpr int N_MAX = 1e5;
int N, U, V;

vvi G(N_MAX, vi());

void bfs(int s, vi& d) {
  fill(begin(d), end(d), INF);

  queue<int> q;
  q.push(s);
  d[s] = 0;

  while (!q.empty()) {
    int u = q.front(); q.pop();
    for (int v : G[u]) {
      if (d[v] < INF) continue;
      d[v] = d[u] + 1;
      q.push(v);
    }
  }
}

int main(int argc, char** argv) {
  cin >> N >> U >> V;
  U--; V--;

  REP(i, N-1) {
    int A, B;
    cin >> A >> B;
    A--; B--;
    G[A].emplace_back(B);
    G[B].emplace_back(A);
  }

  vi d(N_MAX);
  bfs(V, d);
  int ret = 0;
  ret += (d[U]-1)/2;

cerr << "ret " << ret << endl;

  if (ret == 0) {
    cout << d[U]-1 << endl;
    return 0;
  }

  // Approach U to V by ret
  int cur = U;
  int step = 0;
  while (true) {
    if (step == ret) break;

    step++;
    for (auto x : G[cur]) {
      if (d[x]+1==d[cur]) {
        cur = x;
	break;
      }
    }
  }

cerr << "cur " << cur << endl;
  if (d[U]%2==0) ret++;
cerr << "ret2 " << ret << endl;

  // curからVの方向を遮断
  int y = 0;
  for (auto x : G[cur]) {
    if (d[x]+1==d[cur]) {
      y = x;
      break;
    }
  }
  // y->curを切る
  for (auto it=G[y].begin(); it!=G[y].end(); it++) {
    if (*it == cur) {
      G[y].erase(it);
      break;
    }
  }
  // cu->yを切る
  for (auto it=G[cur].begin(); it!=G[cur].end(); it++) {
    if (*it == y) {
      G[cur].erase(it);
    }
  }

  bfs(cur, d);
  int tmp = 0;
  for(auto x : d) {
    if (x == INF) continue;
    chmax(tmp, x);
  }

  cerr << "tmp " << tmp << endl;

  cout << ret + tmp << endl;

  return 0;
}

