template<typename Int>
class LCA{
    template<typename T>
    class sparse_table{
        using F=function<T(T,T)>;
        F f;
        vector<vector<T>>data;
        public:
        sparse_table(vector<T> v,F f):f(f){
            int n=v.size(),log=log2(n)+1;
            data.resize(n,vector<T>(log));
            for(int i=0;i<n;i++)data[i][0]=v[i];
            for(int j=1;j<log;j++)for(int i=0;i+(1<<(j-1))<n;i++){
                data[i][j]=f(data[i][j-1],data[i+(1<<(j-1))][j-1]);
            }
        }
        T get(int l,int r){
            if(r<l)swap(l,r);
            //assert(0<l||r<=(T)data.size());
            int k=log2(r-l);
            return f(data[l][k],data[r-(1<<k)][k]);
        }
    };
    vector<pair<Int,Int>> data;
    vector<Int> start;
    sparse_table<pair<Int,Int>>* st;
	vector<Int> dep;
	vector<Int> __dist;
    public:
	LCA(){}
    LCA(vector<vector<Int>> v,Int s){
        data.resize(v.size()*2-1);
        start.resize(v.size());
        Int i=0;
        dep=depth(s,v);
		__dist=__distance(s,v);
        auto f=[&](auto f,Int n,Int p)->void{
            start[n]=i;
            data[i++]=make_pair(dep[n],n);
            for(Int t:v[n]){
                if(t==p)continue;
                f(f,t,n);
                data[i++]=make_pair(dep[n],n);
            }
        };
        call(f,s,-1);
        st=new sparse_table<pair<Int,Int>>(data,[](auto s,auto t){return s.first>t.first?s:t;});
    }
    Int lca(auto p,auto q){
        return st->get(min(start[p],start[q]),max(start[p],start[q])+1).second;
    }
	Int distance(auto p,auto q){
        return __dist[p]+__dist[q]-2*__dist[lca(p,q)];
    }
    private:
    vector<Int> __distance(Int start,vector<vector<Int>>G){
		vector<Int>memo(G.size());
		auto f=[&](auto f,Int v,Int p,Int i)->Int{
			for(auto t:G[v]){
				if(t==p)continue;
				f(f,t,v,i+1);
			}
			return memo[v]=i;
		};
		call(f,start,-1,0);
		return memo;
    }
	vector<Int> depth(Int start,vector<vector<Int>>G){
		vector<Int>memo(G.size());
		auto f=[&](auto f,Int v,Int p)->lint{
			Int mx=0;
			for(auto t:G[v]){
				if(t==p)continue;
				mx=max(mx,f(f,t,v));
			}
			return memo[v]=mx+1;
		};
		call(f,start,-1);
		return memo;
	}
};
vector<lint> depth(lint start,vector<vector<lint>>G){
	vector<lint>memo(G.size());
	auto f=[&](auto f,lint v,lint p)->lint{
		lint mx=0;
		for(auto t:G[v]){
			if(t==p)continue;
			mx=max(mx,f(f,t,v));
		}
		return memo[v]=mx+1;
	};
	call(f,start,-1);
	return memo;
}
