void dfs(ll now, ll from, ll id){
  for(ll to:G[now]){
    if(to == from) continue;
    if(id == 1){
      dist[to].f = dist[now].f + 1;
    }
    if(id == 2){
      dist[to].s = dist[now].s + 1;
    }
    dfs(to, now, id);
  }
}

ll dfs2(ll now){
  ll res = dist[now].s;
  for(ll to: G[now]){
    if(dist[to].s < dist[now].s) continue;
    res = max(res, dfs2(to));
  }
  return res;
}

