struct BFSS
{
    int depth, parent;
};

struct BFSS2
{
    int depth;
    bool is_child_of_x;
};

int bfs(const vvi &tree, vector<BFSS> &dist, int N, int start)
{
    dist.resize(N);
    for (size_t i = 0; i < dist.size(); i++)
    {
        dist[i].depth = -1;
    }


    queue<int> next;
    dist[start].depth = 0;
    dist[start].parent = -1;
    next.push(start);

    int longest;
    while (!next.empty())
    {
        int cp = next.front(); next.pop();
        for (int node: tree[cp])
        {
            if (dist[node].depth < 0)
            {
                dist[node].depth = dist[cp].depth + 1;
                dist[node].parent = cp;
                next.push(node);
                longest = node;
            }
        }
    }
    return longest;
}

int bfs_depth_x(const vvi &tree, vector<BFSS2> &dist, int N, int root, int x)
{
    dist.resize(N);
    for (size_t i = 0; i < dist.size(); i++)
    {
        dist[i].depth = -1;
    }

    queue<int> next;
    dist[root].depth = 0;
    dist[root].is_child_of_x = false;
    next.push(root);

    int longest;
    while (!next.empty())
    {
        int cp = next.front(); next.pop();
        for (int node: tree[cp])
        {
            if (dist[node].depth < 0)
            {
                dist[node].depth = dist[cp].depth + 1;
                if (node == x)
                    dist[node].is_child_of_x = true;
                else
                    dist[node].is_child_of_x = dist[cp].is_child_of_x;

                next.push(node);
                if (dist[node].is_child_of_x)
                {
                    longest = node;
                }                
            }
        }
    }
    return longest;
}

int farest(const vector<BFSS> &du, const vector<BFSS> &dv, int N)
{
    int max_dist = 0, max_virt = -1;
    for (int i = 0; i < N; i++)
    {
        if (dv[i].depth > max_dist && du[i].depth < dv[i].depth)
        {
            max_dist = dv[i].depth;
            max_virt = i;
        }
    }
    return max_virt;
}

int main()
{
    int N, u, v;
    cin >> N >> u >> v;

    vvi tree(N);

    for (int i = 0; i < N - 1; i++)
    {
        int a, b;
        cin >> a >> b;
        tree[a-1].push_back(b-1);
        tree[b-1].push_back(a-1);
    }
    --u;
    --v;

    vector<BFSS> dist_from_v, dist_from_u;
    bfs(tree, dist_from_v, N, v);
    bfs(tree, dist_from_u, N, u);

    int kouji_virt = farest(dist_from_u, dist_from_v, N);
    int du = dist_from_u[kouji_virt].depth;
    int dv = dist_from_v[kouji_virt].depth;
    int ans = dv - 1;

    cout << ans << endl;
    return 0;
}

