    int u = q.front(); q.pop();
    int up = ps[u][0], vd = ds[u] + 1;

    for (int i = 0; i < BN - 1; i++)
      ps[u][i + 1] = (ps[u][i] >= 0) ? ps[ps[u][i]][i] : -1;

    vi &nbru = nbrs[u];
    for (vi::iterator vit = nbru.begin(); vit != nbru.end(); vit++) {
      int v = *vit;
      if (v != up) {
	ps[v][0] = u, ds[v] = vd;
	cns[u]++;
	q.push(v);
      }
    }
  }

  memset(maxds, -1, sizeof(maxds));
  memset(maxcs, -1, sizeof(maxcs));

  for (int u = 0; u < n; u++)
    if (cns[u] == 0) maxds[u] = ds[u], q.push(u);

  while (! q.empty()) {
    int u = q.front(); q.pop();
    int up = ps[u][0];
    if (up >= 0) {
      if (maxds[up] < maxds[u])
	maxds[up] = maxds[u], maxcs[up] = u;
      if (--cns[up] == 0) q.push(up);
    }
  }
  //for (int u = 0; u < n; u++)
  //printf("[%d]=%d,%d,%d\n", u, ds[u], maxds[u], maxcs[u]);

  int cnt = 0;
  while (s != t) {
    // takahashi moves
    if (maxcs[s] < 0 || ds[s] - ds[t] > 2)
      s = ps[s][0];
    else
      s = maxcs[s];
    if (s == t) break;

    // aoki moves
    if (ds[s] - ds[t] == 1)
      t = s;
    else
      t = ancestor(s, ds[s] - ds[t] - 1);
    cnt++;
  }

  printf("%d\n", cnt);
  return 0;
}

