vector<int> dijkstra(const vector<vector<int>>& edges, int start){
	const int N=edges.size();
	vector<int> d(N, 1e6);
	queue<pair<int,int>> q;
	d[start]=0;
	q.push({0,start});
	while(!q.empty()){
		int befd,pos;
		tie(befd,pos)= q.front();
		q.pop();
		for(auto next:edges[pos]){
			if(befd+1>=d[next])continue;
			d[next]=befd+1;
			q.push({befd+1, next});
		}
	}
	return d;
}

