vector<vector<int>> gr;
vector<vector<int>> dist;

void bfs(int str, int type) {
	dist[str][type] = 0;
	queue<int> q;
	q.push(str);

	while (!q.empty()) {
		int parent = q.front();
		q.pop();
		bool is_leaf = true;

		for (auto child : gr[parent]) {
			if (dist[child][type] == INT_MAX) {
				is_leaf = false;
				dist[child][type] = dist[parent][type] + 1;
				q.push(child);
			}
		}

		if (type == 1 and is_leaf == true and dist[parent][0] < dist[parent][1]) {
			ans = max(ans, dist[parent][1]);
		}
	}
}

int main() {

