		int u, v; cin >> u >> v;
		gr[u].push_back(v);
		gr[v].push_back(u);
	}

	if (src == dest) {
		cout << 0;
		return 0;
	}

	bfs(src, 0);
	bfs(dest, 1);

	cout << ans - 1;

