#include <bits/stdc++.h>
using namespace std;

const int maxn = 1e5 + 10, lg = 20;
int par[maxn][lg], maxh[maxn], h[maxn], dp[maxn];
vector <int> adj[maxn];

int get_par(int v, int d){
	for (int i = 0; i < lg; i ++){
		if (d & (1 << i))
			v = par[v][i];
	}
	return v;
}

int lca(int v, int u){
	if (h[v] > h[u]){
		swap(v, u);
	}
	u = get_par(u, h[u] - h[v]);
	if (v == u)
		return v;
	for (int i = lg - 1; i >= 0; i --){
		if (par[v][i] != par[u][i]){
			v = par[v][i];
			u = par[u][i];
		}
	}
	return par[v][0];
}

void dfs(int v, int p = -1){
	fill(par[v], par[v] + lg, -1);
	par[v][0] = p;
	for (int i = 1; i < lg; i ++){
		if (par[v][i - 1] == -1)
			break;
		par[v][i] = par[par[v][i - 1]][i - 1];
	}
	maxh[v] = 0;
	for (auto u: adj[v]){
		if (u != p){
			h[u] = h[v] + 1;
			dfs(u, v);
			maxh[v] = max(maxh[v], 1 + maxh[u]);
		}
	}
}

void dfs2(int v, int p = -1){
	int mx1 = -1e5, mx2 = -1e5;
	for (auto u: adj[v]){
		if (u != p){
			if (maxh[u] >= mx1){
				mx2 = mx1;
				mx1 = maxh[u];
			}
			else{
				mx2 = max(mx2, maxh[u]);
			}
		}
	}
	for (auto u: adj[v]){
		if (u != p){
			dp[u] = dp[v] + 1;
			if (mx1 == maxh[u]){
				dp[u] = max(dp[u], mx2 + 2);
			}
			else{
				dp[u] = max(dp[u], mx1 + 2);
			}
			dfs2(u, v);
		}
	}
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	h[0] = 0;
	int n, x, y;
	cin >> n >> x >> y;
	for (int i = 0; i < n - 1; i ++){
		int v, u;
		cin >> v >> u;
		v --;
		u --;
		adj[v].push_back(u);
		adj[u].push_back(v);
	}
	dfs(0);
	dfs2(0);
	x --;
	y --;
	swap(x, y);
	int z = lca(x, y);
	int d = h[x] + h[y] - 2 * h[z];
	int d2 = (d - 1) / 2;
	if (x == y) {
		cout << 0;
		return 0;
	}
	int ans = 0;
	if (h[y] >= h[x]){
		y = get_par(y, d2);
		ans = maxh[y] + d - d2;
	}
	else{
		y = get_par(x, d - d2 - 1);
		ans = dp[y] + d - d2 - 1;
	}
	ans--;
	cout << ans;
}

