		std::cerr.rdbuf(new colored_stdio_filebuf(stderr, stderr_pre, stdxxx_post));
	} else
#endif
	{
		int fd = open("/dev/null", O_WRONLY);
		dup2(fd, 2);
		close(fd);
	}

	int N, u, v;
	std::vector<std::pair<int ,int>> AB;
	std::cin >> N >> u >> v;
	--u;
	--v;
	AB.resize(N-1);
	for (auto& ab : AB) {
		std::cin >> ab.first >> ab.second;
		--ab.first;
		--ab.second;
	}

	std::unordered_map<int, std::unordered_map<int, int>> neighs;
	for (auto& ab : AB) {
		neighs[ab.first][ab.second] = 1;
		neighs[ab.second][ab.first] = 1;
	}

	auto taka = dijkstra(neighs, u, N);
	auto aoki = dijkstra(neighs, v, N);

	int result = 0;
	for (int i = 0; i < N; ++i) {
