    G[b].pb(a);
  }
  dist.resize(N);
  dist[u].f = 0;
  dfs(u, -1, 1);
  dist[v].s = 0;
  dfs(v, -1, 2);

  vector<ll> samedfs;
  rep(i, N){
    if(dist[i].s == dist[u].s){
      samedfs.pb(i);
    }
  }
  init_lca();
  vector<ll> pos;
  rep(i, samedfs.size()){
    ll LCA = lca(samedfs[i], u);
    if(dist[LCA].s - dist[u].s < dist[LCA].s){
      pos.pb(samedfs[i]);
