		if(dist==1) ans=max(ans,moved+1LL);
		else if(dist==0) ans=max(ans,moved);
		else if(dist>0) ans=max(ans,moved+dist+height[cur]-1);
		dist--;	// movement of A
		moved++;
		cur=parent[cur];
	}
	cout<<ans<<"\n";
}
