const ll MOD = (ll)(1e9+7);

#define l_ength size

void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

int da[100100],db[100100],ans=-INF;

vector<int> g[100100];
queue<int> q;

void solve(int u, int p = -1){
	int i,v;
	for(i=(g[u].l_ength()-1); i>=0; --i){
		v = g[u][i];
		if(p==v){
			continue;
		}
		if(!(da[v]>db[v] && da[u]>db[u])){
			ans = max(ans,min(db[v],db[u]));
		}
		solve(v,u);
	}
}

int main(void){
	int n,a,b,u,v,i;
	cin >> n >> a >> b; --a; --b;
	fill(da,da+n,INF);
	fill(db,db+n,INF);
	for(i=1; i<n; ++i){
		cin >> u >> v;
		--u; --v;
		g[u].push_back(v);
		g[v].push_back(u);
	}
	da[a] = 0; q.push(a);
	while(!q.empty()){
		u = q.front();
		q.pop();
		for(i=(g[u].l_ength()-1); i>=0; --i){
			v = g[u][i];
			if(da[v] > da[u]+1){
				da[v] = da[u]+1;
				q.push(v);
			}
		}
	}
	db[b] = 0; q.push(b);
	while(!q.empty()){
		u = q.front();
		q.pop();
		for(i=(g[u].l_ength()-1); i>=0; --i){
			v = g[u][i];
			if(db[v] > db[u]+1){
				db[v] = db[u]+1;
				q.push(v);
			}
		}
	}
	solve(0);
	cout << ans << endl;
	return 0;
}

