void dfsao(int pos, int dist) {
    if( di[pos] <= dist ) return;
    di[pos] = dist;
    for( int i = 0; i < tree[pos].size(); ++i ) {
        if( di[tree[pos][i]] <= dist + 1 ) continue;
        dfsao(tree[pos][i], dist + 1);

    }
    return;

}

void dfsta(int pos, int dist) {
    if( di[pos] <= dist ) return;
    if( mxdi < di[pos] ) {
        mxdi = di[pos];
        mxpos = pos;

    }

    for( int i = 0; i < tree[pos].size(); ++i ) {
        dfsta(tree[pos][i], dist + 1);

    }
    return;

}

