vi<ll>adj[MAX+1];

void dfs(int cur, int prev){ 
    depth[cur] = depth[prev] + 1; 
    parent[cur][0] = prev; 
    for(auto it:adj[cur]){
        if(it!=prev){
            dfs(it,cur);
        }
    }
