int walk(int u) {
	queue<ii> q;
	q.push({u, 0});
	int ret = 0;
	while (!q.empty()) {
		int v, d;
		tie(v, d) = q.front();
		q.pop();
		//ret = max(ret, da[v]);
		d++;
		for (int x : adj[v]) {
			if (d >= da[x])
				ret = max(ret, da[x]);
			else
				q.push({x, d});
		}
	}
	return ret;
}

