        ans = max(ans, dist[e] - ((dist[e] - (cnt + 1)) & 1));
        if (cnt + 1 < dist[e]) milk.emplace(cnt + 1, e);
      }
    }
  }
  cout << ans << '\n';
  return 0;
}

