typedef long long LL;

int n, s, e;
vector<vector<int>> g;

vector<bool> marked;
vector<int> route;

bool find_route(int u, int v) {
	marked[u] = true;
	route.push_back(u);
	if (u == v)
		return true;
	bool found = false;
	for (int w: g[u]) {
		if (marked[w]) continue;
		found = found || find_route(w, v);
		if (found)
			break;
	}
	if (!found) {
		route.pop_back();
	}
	return found;
}

vector<int> height;

int find_height(int v, int parent) {
	height[v] = 0;
	for (int u: g[v]) {
		if (u == parent) continue;
		height[v] = max(find_height(u, v) + 1, height[v]);
	}
	return height[v];
}

