		u--, v--;
		g[u].push_back(v);
		g[v].push_back(u);
	}

	route.clear();
	marked.assign(n, false);
	find_route(s, e);

	int mid = route[(int)route.size() / 2 - 1];
	int mid_parent = route[(int)route.size() / 2];

	height.resize(n, -1);
	find_height(mid, mid_parent);

	cout << height[mid] + ((int)route.size() + 1) / 2 - 1 << '\n';

	return 0;
}

