void dfs( int node, int pr )
{
    vis[node] = 1;
    if( pr != -1 )
    {
        par[node] = pr;
        height[node] = height[pr] + 1;
    }
    for( auto next : gr[node] )
    {
        if( !vis[next] )
        {
            dfs(next, node);
        }
    }
}

void calc_depth( int node, int pr )
{
    if( pr != -1 && gr[node].size() == 1 )
    {
        depth[node] = 1;
    }

    int mx = 0;
    for( auto next : gr[node] )
    {
        if( next == pr )
            continue;
        calc_depth( next, node );
        mx = max( mx, depth[next] );
    }
    depth[node] = mx+1;
}

int up( int u, int h )
{
    int mul = 0;
    while( h )
    {
        if( h&1 )
        {
            u = lca[u][mul];
        }
        mul++;
        h /= 2;
    }
    return u;
}

int find_lca( int u, int v )
{
    int h1 = height[u], h2 = height[v];
    if( h1 > h2 )
    {
        u = up( u, h1-h2 );
        h1 = h2;
    }
    if( h2 > h1 )
    {
        v = up( v, h2-h1 );
        h2 = h1;
    }

    if( u == v )
        return u;

    int lo=0, hi=h1, mid, ans=0;
    while( lo <= hi )
    {
        mid = lo + (hi-lo)/2;

        int a = up(u,mid), b = up(v,mid);
        if( a == b )
        {
            ans = a;
            hi = mid-1;
        }
        else
        {
            lo = mid+1;
        }
    }
    return ans;
}

