    int p = find_lca(a,b);
    int ha = height[a], hb = height[b], hp = height[p];
    int ans = 0;
    if( hb-hp < ha-hp )
    {
        ans += hb-hp;
        a = up( a, hb-hp );
        b = up( b, hb-hp );

        ha = height[a], hb = height[b];

        int more = ( ha - hb - 1 )/2;
        ans += more;

        a = up( a, more );

        if( (ha-hb)%2 == 0 )
        {
            ans += depth[a];
        }
        else
        {
            ans += depth[a] - 1;
        }
    }
    else if( hb-hp == ha-hp )
    {
        ans += (hb-hp-1);
        a = up( a, hb-hp-1 );
        b = up( b, hb-hp-1 );
        ans += depth[a];
    }
    else
    {
        ans += ha;
        a = up( a, ha );
