        {
            ans += mx-1;

            int more = ( diff - 1 )/2;
            ans += more;

            if( diff%2 == 0 )
            {
                ans += more;
            }
            else
            {
                ans += more-1;
            }
        }
    }
    cout<<ans,nl;


