#include <bits/stdc++.h>

using namespace std;

vector<vector<int>> edges;
vector<int> scores;
vector<bool> visited;

void mark(int i, int score) {
  // cout << " I " << i << endl;
  scores[i] = score;
  for (int next : edges[i]) {
    if (scores[next] == -1) {
      mark(next, score + 1);
    }
  }
}

int max_score(int i, int cost) {
  // cout << " i " << i << " score " << scores[i] << endl;
  visited[i] = true;
  if (scores[i] <= cost)
    return scores[i];
  int score = 0;
  for (int next : edges[i]) {
    if (!visited[next]) {
      score = max(score, max_score(next, cost + 1));
    }
  }
  if (!score) {
    score = scores[i];
    if ((score - cost) % 2 == 1 && edges[i].size() <= 1) {
      return score - 1;
    }
  }
  return score;
}

void solve() {
  int N, u, v;
  cin >> N >> u >> v;
  --u;
  --v;
  edges.resize(N);
  scores.resize(N, -1);
  visited.resize(N);
  for (int i = 0; i < N - 1; ++i) {
    int a, b;
    cin >> a >> b;
    --a;
    --b;
    // cout << " a " << a << " b " << b << endl;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }
  mark(v, 0);
  cout << max_score(u, 0) << endl;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  solve();
}

