const int MAX = 1e5+10;

int N, U, V;
vi edge[MAX], children[MAX];
int parent[MAX];

void make_tree(int n, int p) {
    parent[n] = p;
    children[n] = vi();
    FORE (c, edge[n]) if (c != p) {
        children[n].push_back(c);
        make_tree(c, n);
    }
}

vi shortest_path(int s) {
    vi shortest;
    int path = s;
    while (path != V) {
        shortest.push_back(path);
        path = parent[path];
    }
    shortest.push_back(V);
    return shortest;
}

ll dnf(int n, int len, int ng) {
    if (children[n].size() == 0) return len;
    ll mx = 0;
    FORE (c, children[n]) if (c != ng) {
        mx = max(mx, dnf(c, len+1, ng));
    }
    return mx;
}

int solve() {
    if (edge[U].size() == 1 && edge[U][0] == V) return 0; // 一手目で終わる

    make_tree(V, -1);
    ll ans = 0;

    vi shortest = shortest_path(U);
    int idx = shortest.size()/2 - 1;
    ans = idx;
    if (shortest.size()&1) ans++;
    int u = shortest[idx], ng = shortest[idx+1];

    make_tree(u, -1);
    ans += dnf(u, 0, ng);
    return ans;
}

int main() {
    cin >> N >> U >> V;
    U--; V--;
    REP (i, N-1) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    cout << solve() << endl;
}

