void path_calc(int target, int array[]) {
	for (int i = 0; i < path[target].size(); i++) {
		int next = path[target].at(i);
		if (array[next] != -1) continue;
		array[next] = array[target] + 1;
		path_calc(next, array);
	}
}

void path_calcT(int target, int array[]) {
	for (int i = 0; i < path[target].size(); i++) {
		int next = path[target].at(i);
		if (array[next] != -1) continue;
		array[next] = array[target] + 1;
		// 青木君につかまる場合はその先に行かない
		if (array[next] >= fromA[next]) continue;
		path_calc(next, array);
	}
}

