void dfs(Graph &G, int v, vector<bool> &seen, int mokuteki, vector<int> &depth){
  seen.at(v) = true;
  for (auto nv : G.at(v)){
    if (seen.at(nv)) continue;
    if (nv == mokuteki) continue;
    depth.at(nv) = depth.at(v) + 1;
    dfs(G, nv, seen, mokuteki, depth);
  }
  return;
}

void dfsdis(Graph &G, int v, vector<bool> &seen, int mokuteki, vector<int> &depth){
  // mokutekiから見たvの距離
  seen.at(v) = true;
  for (auto nv : G.at(v)){
    if (seen.at(nv)) continue;
    dfsdis(G, nv, seen, mokuteki, depth);
    if (depth.at(nv) != -1) depth.at(v) = depth.at(nv) + 1;
  }
  return;
}

int main() {
  int N,U,V; cin >>N >>U >>V;
  U--; V--;
  // 2<N<10^5, 1<=u,v<=N, u!=v, 1<=ai,bi<=N
  // U: 逃げる側、V: 追いかける側
  Graph G(N);
  // 頂点は1からNではなく0からN-1とする
  for (int i=0; i<N-1; i++){
    int a,b;
    cin >>a >>b;
    a--; b--;
    G.at(a).push_back(b);
    G.at(b).push_back(a);
  }
  int ans = 0;

  vector<bool> seen(N,false);
  vector<int> depths(N, -1);
  depths.at(U) = 0;
  dfsdis(G, V, seen, U, depths);
  int inidis = depths.at(V); //最初のUとVの距離
  for (int i=0; i<(inidis-1)/2; i++){
    // UはまずなるべくVに近づいていく
    for (int i=0; i<N; i++){
      depths.at(i) = -1;
      seen.at(i) = false;
    }
    depths.at(V) = 0;
    dfsdis(G, U, seen, V, depths);
    for (int i=0; i<N; i++){
      if (depths.at(i) == depths.at(U) - 1){
        U = i;
        break;
      }
    }
    // VもUへ近づいていく
    for (int i=0; i<N; i++){
      depths.at(i) = -1;
      seen.at(i) = false;
    }
    depths.at(U) = 0;
    dfsdis(G, V, seen, U, depths);
    for (int i=0; i<N; i++){
      if (depths.at(i) == depths.at(V) - 1){
        V = i;
        break;
      }
    }
    ans++;
  }

  // 下の操作を行うために例外処理
  int bufV = V;
  if (inidis % 2 == 0){
    // UとVの間に頂点が一つあるはず。そこを予め潰しておく
    for (int i=0; i<N; i++){
      depths.at(i) = -1;
      seen.at(i) = false;
    }
    depths.at(U) = 0;
    dfsdis(G, V, seen, U, depths);
    for (int i=0; i<N; i++){
      if (depths.at(i) == depths.at(V) - 1){
        V = i;
        break;
      }
    }
  }

  // Uが出来る限り上に行ったのであとは下へと降りていく。
  // 逃げられる回数はUから見た木の大きさとUとVの距離(1or2)によって決定される
  for (int i=0; i<N; i++){
