using Graph = std::vector<std::vector<int>>;

void make_dist_map(
    Graph const & g,
    int const from,
    std::vector<int> & dist)
{
    // distは-1クリアされている前提
    std::vector<int> queue;
    queue.push_back(from);
    dist[from] = 0;
    while (!queue.empty()) {
        int node = queue.back(); queue.pop_back();
        int nDist = dist[node];
        int nEdge = g[node].size();
        for (int i=0; i<nEdge; ++i) {
            int dest = g[node][i];
            if (dist[dest] < 0) {
                queue.push_back(dest);
                dist[dest] = nDist + 1;
            }
        }
    }
}

int main()
{
    int N, u, v;
    std::cin >> N >> u >> v;
    u -= 1; // takahashi (free)
    v -= 1; // aoki (chase)

    Graph g(N);

    for (int i=0; i<N; ++i) {
        int A, B;
        std::cin >> A >> B;
        g[A-1].push_back(B-1);
        g[B-1].push_back(A-1);
    }
    std::vector<int> umap(N, -1);
    make_dist_map(g, u, umap);
    std::vector<int> vmap(N, -1);
    make_dist_map(g, v, vmap);

    int max = 0;
    for (int i=0; i<N; ++i) {
        if (umap[i] <= vmap[i]) {
            max = std::max(max, vmap[i]);
        }
    }
    std::cout << max - 1 << std::endl;
    return 0;
}

