void dfs(vector<vector<ll>> &tree, ll now, ll bf, vector<ll> &ans, ll o, vector<ll> &leaf, bool mode){
	bool flag = true;
	for(ll i : tree.at(now)){
		if(i == bf) continue;
		ans.at(i) = ans.at(now) + 1;
		flag = false;
		if(i == o){
			leaf.push_back(i);
			continue;
		}
		dfs(tree, i, now, ans, o, leaf, mode);
	}
	if(mode == true && flag == true) leaf.push_back(now);
}

