void bfs(vi& du, int u) {
    queue<vi> q;
    q.push({ u, 0 });
    while(!q.empty()) {
        auto f = q.front();
        q.pop();
        int node = f[0], steps = f[1];
        if(du[node] != -1)  continue;
        du[node] = steps;
        for(int v : adj[node]) {
            q.push({ v, steps + 1 });
        }
    }
}

