void solve()
{
    ll n,u,v;
    cin >> n >> u >> v;
    vll deg(n+1, 0), dis1(n+1, -1), dis2(n+1, -1);
    vll G[n+1];
    for(ll i=0;i<n-1;i++) {
    	ll x,y;
    	cin >> x >> y;
    	deg[x]++;
    	deg[y]++;
    	G[x].pb(y);
    	G[y].pb(x);
    }
    dis1[u] = 0;
    stack<ll> st;
    st.push(u);
    while(!st.empty()) {
    	ll cur = st.top();
    	st.pop();
    	for(ll ad: G[cur]) {
    		if(dis1[ad] == -1) {
    			dis1[ad] = dis1[cur] + 1;
    			st.push(ad);
    		}
    	}
    }
    dis2[v] = 0;
    stack<ll> st2;
    st2.push(v);
    while(!st2.empty()) {
    	ll cur = st2.top();
    	st2.pop();
    	for(ll ad: G[cur]) {
    		if(dis2[ad] == -1) {
    			dis2[ad] = dis2[cur] + 1;
    			st2.push(ad);
    		}
    	}
    }
    ll ans = 0;
    for(ll i=1;i<=n;i++) {
    	if(deg[i] == 1 && dis1[i] < dis2[i]) {
    		ans = max(ans, dis2[i] - 1);
    	}
    }
    cout << ans << "\n";
}	

