typedef pair<int, int> P;
const int INF = 1 << 30;

class edge {
public:
    int to, cost;
    edge(int t, int d) {
        to = t;  cost = d;
    }
};

int N;
vector<vector<edge>> G;
vector<int> d1, d2;

void dijkstra(vector<int>& d, int s) {
    for (int i = 0; i < N; ++i) d[i] = INF;
    d[s] = 0;
    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P(0, s));
    while (!que.empty()) {
        P p = que.top();  que.pop();
        int i = p.second;
        if (d[i] < p.first) continue;
        for (edge e : G[i]) {
            if (d[e.to] > d[i] + e.cost) {
                d[e.to] = d[i] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

int main() {
    int u, v;
    cin >> N >> u >> v;  --u;  --v;
    G.resize(N, vector<edge>());
    for (int i = 0; i < N - 1; ++i) {
        int a, b;  cin >> a >> b;
        --a;  --b;
        G[a].push_back(edge(b, 1));
        G[b].push_back(edge(a, 1));
    }

    d1.resize(N);
    d2.resize(N);
    dijkstra(d1, v);
    dijkstra(d2, u);
    vector<P> pd;
    for (int i = 0; i < N; ++i) pd.push_back(P(d1[i], d2[i]));
    sort(pd.begin(), pd.end(), greater<P>());
    for (int i = 0; i < N; ++i) {
        if (pd[i].first > pd[i].second) {
            cout << pd[i].first - 1 << endl;
            return 0;
        }
    }
}

