void bfs(int s, vector<int>& D, vector< vector<int> > M) {
    queue<int>  q;
    D[s] = 0;
    q.push(s);
    int u;
    while ( !q.empty() ) {
        u = q.front(); q.pop();
        for (int i = 0; i < M[u].size(); i++) {
            int cur_node = M[u][i];
            if (D[cur_node] != -1) continue;
            D[cur_node] = D[u] + 1;
            q.push(cur_node);
        }
    }
}

