struct Graph {
    struct Vertex { int n, d, x, d0; };
    struct Edge { int i, n; };
    Graph(int n, int m) : v(n, { -1,-1,-1,-1 }), e(m), n(n), m(0) {}
    void add_edge(int i, int j) {
        e[m] = { j, v[i].n };
        v[i].n = m;
        m++;
    }
    int dfs(int i, int p, int d) {
        pair<int, int> d0 = { v[i].d = d, p };
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge &o = e[j];
            if (o.i == p) continue;
            d0 = max(d0, { dfs(o.i, i, d + 1), o.i });
        }
        v[i].d0 = d0.first;
        //v[i].x = d0.second;
        return d0.first;
    }
    void dfs2(int i, int p, int d, int r0) {
        if (d <= d1 && d1 - d < d) {
            int e = d - (d1 - d);
            r0 = max(r0, v[i].d0 - e + max(e - 1, 0));
        }
        if (i == v1) r1 = r0;
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge &o = e[j];
            if (o.i == p) continue;
            dfs2(o.i, i, d + 1, r0);
        }
    }
    vector<Vertex> v;
    vector<Edge> e;
    int n, m, d1, v1, r1;
};

