void dfs1(int idx, int prev, LL dst) {
    // cerr << idx << ", " << prev << ", " << dst << endl;
    dstv[idx] = dst;
    par[idx] = prev;
    REP(i, tree[idx].size()) {
        int jdx = tree[idx][i];
        if(jdx == prev) continue;
        dfs1(jdx, idx, dst + 1);
    }
}

void dfs2(int idx, int prev, LL dst) {
    // cerr << idx << ", " << prev << ", " << dst << endl;
    dstu[idx] = dst;
    REP(i, tree[idx].size()) {
        int jdx = tree[idx][i];
        if(jdx == prev) continue;
        if(dst + 1 >= dstv[jdx]) continue;
        back[jdx] = back[idx] + (par[idx] == jdx);
        dfs2(jdx, idx, dst + 1);
    }
}

