void createAoki(int cur, int dist) {
  aoki[cur] = dist;
  for (int i = 0; i < t[cur].size(); i++) {
    int next = t[cur][i];
    if (aoki[next] == -1) {
      createAoki(next, dist + 1);
    }
  }
}

void solve(int cur, int pre, int dist) {
  if (aoki[cur] >= dist) {
    if (dist % 2 == aoki[cur] % 2) {
      ans = max(ans, dist);
      cerr<<"1ans<-"<<dist<<endl;
    } else {
      ans = max(ans, dist - 1);
      cerr<<"2ans<-"<<dist-1<<endl;
    }
  }
  cerr<<":"<<cur<<","<<dist<<endl;
  if (aoki[cur] <= dist) {
    return;
  }
  if (t[cur].size() == 1) {
    int distCur = aoki[cur];
    int distPre = aoki[t[cur][0]];

    ans = max(ans, distPre);
    cerr<<"3ans<-"<<distPre<<endl;
    cerr<<"::"<<distPre<<","<<distCur<<endl;
    int diff = distPre - dist;
    if (diff % 2 == 0 && diff >= 1) {
      ans = max(ans, distPre);
      cerr<<"4ans<-"<<distCur<<endl;
      cerr <<":::"<< cur<<":" << diff<<endl;
