void maketree(vector<vector<int>>& adj, vector<int>& parent, int now, int prv)
{
	parent[now] = prv;
	bool isleaf = true;
	for (int nxt : adj[now]) {
		if (nxt == prv) continue;
		isleaf = false;
		lv[nxt] = lv[now] + 1;
		maketree(adj, parent, nxt, now);
	}
	if (isleaf) {
		leaf[now] = true;
		maxlv[now] = lv[now];
	}
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> n >> u >> v;
	u -= 1;
	v -= 1;
	adj.resize(n);
	parent.resize(n, -1);
	lv.resize(n);
	maxlv.resize(n);
	leaf.resize(n);
	ind.resize(n);
	for (int i = 0; i < n - 1; i++) {
		int a, b;
		cin >> a >> b;
		adj[a - 1].push_back(b - 1);
		adj[b - 1].push_back(a - 1);
	}
	for (int i = 0; i < n; i++) ind[i] = ((i == v) ? adj[i].size() : adj[i].size() - 1);
	maketree(adj, parent, v, -1);
	queue<int> q;
	for (int i = 0; i < n; i++) if (leaf[i]) q.push(i);
	while (!q.empty()) {
		int now = q.front();
		q.pop();
		if (parent[now] == -1) continue;
		ind[parent[now]] -= 1;
		maxlv[parent[now]] = max(maxlv[parent[now]], maxlv[now]);
		if (ind[parent[now]] == 0) q.push(parent[now]);
	}
	int tmp = 0;
	int gap = lv[u] - lv[v];
	int answer = 0;
	while (gap > 0) {
		answer = max(answer, maxlv[u] - lv[u] + gap - 1 + tmp);
		u = parent[u];
		gap -= 2;
		tmp += 1;
	}
	cout << answer;

	return 0;
}

