void bfs(int n, vector<stack<int>> edge, int p, vector<int> &cnt) {

  queue<int> q;

  while (!edge[p].empty()) {
    int nxt = edge[p].top();
    edge[p].pop();

    if (cnt[nxt] < 0) {
      cnt[nxt] = cnt[p] + 1;
      q.push(nxt); 
    }
  }

  while (!q.empty()) {
    int nxt = q.front();
    q.pop();
    bfs(n, edge, nxt, cnt);
  }
}


