    vector<vector<int>> G(N);
    REP(i,N-1){
        int a, b;
        cin >> a >> b;
        --a, --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    LCA<vector<vector<int>>> lca(G);
    lca.build();

    int ans = 0;
    REP(i,N){
        int t = lca.get(i, u);
        if(lca.dist(t, u) < lca.dist(t, v)) chmax(ans, lca.dist(t, v) - 1);
    }
    cout << ans << endl;
}

