int alphabeta(bool t, int n, int u, int v, int alpha, int beta) {
  if (n >= N || u == v) return n;

  if (t) {
    for (int w : G[u]) {
      alpha = max(alpha, alphabeta(!t, n, w, v, alpha, beta));
      if (beta <= alpha) return alpha;
