class Graph
{
private:
    int _n;
    // エッジ（ノードとノードをつなぐ辺）
    struct Edge
    {
        int to;       // 終点のノード番号
        int cost = 1; // エッジのコスト
    };
    vector<vector<Edge>> _edges; // _edges[i] ノードiから伸びるエッジの集合
    vector<int> _dist;           // ノードの距離を記録

public:
    // コンストラクタ ノード数nを渡す
    Graph(int n);
    ~Graph();
    void uniteNodes(int one, int another, int cost);
    // スタック使用深さ優先探索する 木ならtrue
    int depthFirstSearch(const int start);
    int maxDist(); // 木（閉路を持たない）の数を返す
};

Graph::Graph(int n) : _n(n)
{
    _edges.resize(_n);
    _dist.resize(_n, INF);
}

Graph::~Graph()
{
}

void Graph::uniteNodes(int one, int another, int cost = 1)
{
    _edges[one].push_back({another, cost});
    _edges[another].push_back({one, cost});
}

int Graph::depthFirstSearch(const int start)
{
    // 今後探索するノードを記録するスタック
    stack<int> destination;

    int dist_tkhs_aoki;

    // 最初にスタートを探索した
    destination.push(start);
    _dist[start] = 0;

    // 全てのノードを探索
    while (!destination.empty())
    {
        // スタックから調べる升を取り出す
        const int p = destination.top();
        destination.pop();

        for (auto &&edge : _edges[p])
        {
            // np: 今探索している隣接ノードのノード番号
            const int np = edge.to;
            // npをすでに探索していない
            if (_dist[np] == INF)
            {
                destination.push(np);
                _dist[np] = _dist[p] + 1;
                if (np == tkhs)
                {
                    stack<int> stemp;
                    destination = stemp;
                    dist_tkhs_aoki = _dist[p] + 1;
                    destination.push(np);
                    break;
                }
                // npを今後調べるノードとしてスタックに積む
                // npを探索したと記録する
            }
        }
    }

    const int dist_max = maxDist();
    return dist_max - 1;
}

int Graph::maxDist()
{
    int max_dist = -1;
    for (int i = 0; i < _n; i++)
        if (_dist[i] != INF)
            chmax(max_dist, _dist[i]);

    return max_dist;
}

