      int t = tmp.first;
      int cost = tmp.second;
      reach[t] = 1;

      dump(t, cost, d[t]);
      if (!eda[t]) chmax(ans, d[t]);
      each(el, G.all_edges[t]){
        int nt = el.first; 
        int ncost = cost+1;
        if (reach[nt]==0 && ncost < d[nt]){
          st.push(mp(nt, ncost));
        }
        if (reach[nt]==0 && ncost==d[nt]){
          chmax(ans, d[nt]);
        }
      }
    }
    dump(reach);
  }
  cout << ans << endl;

