class Tree{
public:

    int N;
    vector<vector<int>> G;
    vector<int> taka;
    vector<int> aoki;
    int ans = 0;

    Tree(int n){
        N = n;
        G.resize(N);
        aoki.resize(N);
        taka.resize(N);
    }

    void make_edge(int s, int t){
        G[s].push_back(t);
        G[t].push_back(s);
    }

    void dfs_aoki(int n, int par){
        if(par == -1) aoki[n] = 0;

        for(int i = 0; i < (int)G[n].size(); i++){
            int nx = G[n][i];
            if(nx != par){
                aoki[nx] = aoki[n] + 1;
                dfs_aoki(nx, n);
            }
        }
    }

    void dfs_taka(int n, int par){
        if(par == -1) taka[n] = 0;

        for(int i = 0; i < (int)G[n].size(); i++){
            int nx = G[n][i];
            if(nx != par){
                taka[nx] = taka[n] + 1;
                dfs_taka(nx, n);
            }
        }
    }

    void dfs(int n, int par){
        if(taka[n] < aoki[n]){
            ans = max(ans, aoki[n] - 1);
        }

        for(int i = 0; i < (int)G[n].size(); i++){
            int nx = G[n][i];
            if(nx != par){
                dfs(nx, n);
            }
        }
    }

    int solve(int pt, int po){
        dfs_taka(pt, -1);
        dfs_aoki(po, -1);

        dfs(0, -1);
        return ans;
    }
};

