            Aoki_distance( e.to, count );
        }
    }
    return 0;
}

using P = pair<int,int>; // first: shortest distance, second: vertex number


bool dijkstra(int s, int goal, int N){
    //cout << "start s= " << s << endl;
    fill( d, d+MAXV, INF );
    fill( previous, previous+MAXV, -1 );

    d[s] = 0;

    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P(0,s));

    while( !que.empty() ){
        P p = que.top();
        que.pop();
        int v = p.second;
        if( d[v] < p.first ){
            //cout << "continue" << endl;
            continue;
        }
        for( auto e: G[v] ){
            //cout << "v, e.to, e.cost  " << v << " " << e.to << " " << e.cost << endl;
            if( d[e.to] > d[v] + 1 ){//e.cost ){
                d[e.to] = d[v] + 1;//e.cost;
                previous[e.to] = v;
                //cout << " making route now, previous= " << e.to << " " << previous[e.to] << endl;
                que.push( P(d[e.to], e.to) );
            }
        }
    }

    vector <int> route;
    for( int ii=goal; ii!=-1; ii=previous[ii]  ){
        route.push_back(ii);
    }
    for( int ii=(int) route.size()-1; ii>0; ii-- ){
        //cout << "now prev = " << route[ii] << " " << route[ii-1] << endl;
        if(d[route[ii]]>=Aoki[route[ii]]){
            //cout << "dijkstra return false goal ii " << goal << " " << route[ii] << endl;
            return false;
        }else{
            visited[ii]=true;
        }
    }

    return true;
}

