void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    ll u; llin(u);
    ll v; llin(v);
    V<t2> ablist; llinl2(ablist, n-1);

    S V<ll> linklist[100005];
    make_linklist(ablist, linklist);

    S ll parents[100005];
    S V<ll> children[100005];
    S ll levels[100005];
    make_parental_relation(linklist, u, n, parents, children, levels);

    ll depth = levels[v];
    ll nowv = v;
    ll stopd = depth / 2LL + (depth & 1LL);
    ll stopv = -1LL;
    ll startv = -1LL;
    for (ll nowd = depth; ; nowd--) {
        if (stopd == nowd) {
            stopv = nowv;
            startv = parents[nowv];
            break;
        }
        nowv = parents[nowv];
    }
    debug_printf("stopv=%lld startv=%lld\n", stopv, startv);

    ll ans = levels[startv];
    if (!(levels[v] & 1LL)) ans++;

    queue<t2> q;
    S bool checked[100005];
    memset(checked, 0, sizeof(checked));

    q.push(t2(startv, 0LL));
    checked[startv] = true;
    checked[stopv] = true;

    ll maxd = 0LL;
    while (!q.empty()) {
        auto item = q.front(); q.pop();
        ll x = get<0>(item);
        ll distance = get<1>(item);

        maxd = max(maxd, distance);

        for (auto nx : linklist[x]) {
            if (checked[nx]) continue;
            q.push(t2(nx, distance + 1LL));
            checked[nx] = true;
        }
    }

    debug_printf("--- ans\n");
    cout << ans + maxd << endl;
}

