    for ( long long int i = 0; i < n; i++ ) {
        vector< long long int > vv;
        v.push_back( vv );
    }

    for ( long long int i = 0; i < n - 1; i++ ) {
        long long int x, y;
        cin >> x >> y;
        x--;
        y--;
        v[x].push_back( y );
        v[y].push_back( x );
    }

    if ( a == b ) {
        cout << 0 << endl;
        return 0;
    }

    long long int x[114514] = {};
    long long int y[114514] = {};

    queue< pair< long long int, long long int > > q;
    q.push( make_pair( 1, a ) );
    x[a] = 1;
    while( q.size() > 0 ) {
        long long int d = q.front().first + 1;
        long long int k = q.front().second;
        q.pop();
        for ( long long int i = 0; i < v[k].size(); i++ ) {
            long long int p = v[k][i];
            if ( x[p] > 0 ) continue;
            x[p] = d;
            q.push( make_pair( d, p ) );
        }
    }

    long long int ans = 0;
    q.push( make_pair( 1, b ) );
    y[b] = 1;
    while( q.size() > 0 ) {
