using P = pair<int, int>;
int main(){
	int N, u, v;
	cin >> N >> u >> v;
	u--; v--;
	vector<vector<int>> vec(N, vector<int>());
	for(int i=0; i<N-1; i++){
		int a, b;
		cin >> a >> b;
		a--; b--;
		vec[a].push_back(b);
		vec[b].push_back(a);
	}

	// cout << " vec: "; print_vec2(vec);
	vector<int> aoki(N, 0);
	{
		//青木君は無駄なく動く
		//  →  幅優先探索で十分(2度同じ頂点には行かない)
		queue<P> qu;
		qu.push(P(v, -1));
		while(!qu.empty()){
			int node = qu.front().first;
			int parent = qu.front().second;
			qu.pop();
			for(int i=0; i<vec[node].size(); i++){
				int child = vec[node][i];
				if(child == parent) continue;
				if(aoki[child] != 0) continue;
				aoki[child] = aoki[node] + 1;
				qu.push(P(child, node));
			}
		}
	}
	// cout << " aoki: "; print_vec(aoki);
	int ans = -1;
	vector<int> takahashi(N, 0);
	queue<P> qu;
	qu.push(P(u, -1));
	while(!qu.empty()){
		int node = qu.front().first;
		qu.pop();
		int catch_place = -1;//
		for(int i=0; i<vec[node].size(); i++){
			int child = vec[node][i];
			if(aoki[child]+1 < takahashi[child]){
				//高橋君は青木君の通った道には行けない(行ったら高橋君は青木君に近づいて行っていることになる)
				// aoki[child]+1 の +1　は　高橋君から捕まりざるを得ない場合があるため，+1してその場合を除く
				//これ入れないとTLEになった
				takahashi[child] = takahashi[node]+1;
				// cout << " 1: vec[" << node << "][" << i << "]: " << vec[node][i] << " takahashi[child]: " << takahashi[child] << endl;
				continue; 
			}
			if(aoki[child]+1 == takahashi[node]+1){
				catch_place = child;
				takahashi[child] = takahashi[node]+1;
				// cout << " 2: vec[" << node << "][" << i << "]: " << vec[node][i] << " takahashi[child]: " << takahashi[child] << endl;
				continue;//高橋君は青木君につかまりにいかないので進まない (進んだら高橋君からつかまりに行く場合となる)
			}
			if(aoki[child] == takahashi[node]+1){
				catch_place = child;// 青木君が移動して捕まえに行く場合となる
				takahashi[child] = takahashi[node]+1;
				// cout << " 3: vec[" << node << "][" << i << "]: " << vec[node][i] << " takahashi[child]: " << takahashi[child] << endl;
				continue;
			}
			takahashi[child] = takahashi[node] + 1;
			qu.push(P(child, node));

		}
		if(qu.empty()) ans = aoki[catch_place]; 
	}
	// cout << " takahashi: "; print_vec(takahashi);
	cout << ans << endl;

}

