using namespace std;
long long N, u, v;

vector<long long> tree[100005];
long long memo_t[100005];
long long memo_a[100005];



int main(){
	cin >> N >> u >> v;
	u--;v--;
	rep(i, N-1) {
		long long a, b;
		cin >> a >> b;
		a--;b--;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}


	// point, (pa, dis)
	queue<pair<long long, pair<long long,long long> > >Q;
	Q.push(make_pair(v, make_pair(-1, 0)));
	while(!Q.empty()) {
		long long cur = Q.front().first;
		long long pa = Q.front().second.first;
		long long dis = Q.front().second.second;
		memo_a[cur] = dis;
		Q.pop();
		//cout << cur << endl;
		for(auto next: tree[cur]) {
			if(next != pa) {
				Q.push(make_pair(next, make_pair(cur, dis + 1)));
			}
		}
	}

	long long ans = 0;
	Q.push(make_pair(u, make_pair(-1, 0)));
	while(!Q.empty()) {
		long long cur = Q.front().first;
		long long pa = Q.front().second.first;
		long long dis = Q.front().second.second;
		Q.pop();

		if(memo_a[cur] <= dis) {
			ans = max(ans, memo_a[cur]);
			continue;
		}
		for(auto next: tree[cur]) {
			if(next != pa) {
				Q.push(make_pair(next, make_pair(cur, dis + 1)));
			}
		}

		//端っこに来た
		if(tree[cur].size() == 1 && tree[cur][0] == pa) {
			long long rest = memo_a[cur] - dis;
			long long diff = (rest/2 - 2) * 2;
			if(diff > 0) {
				//自分自身にワープ
				Q.push(make_pair(cur, make_pair(-1, dis + diff)));
			} else {
				//普通に親に戻っちゃう
				Q.push(make_pair(pa, make_pair(-1, dis + 1)));
			}
		}

	}

	cout << ans << endl;
}

