void t_dfs(int now, int cost) {
    t_cost[now] = cost;
    REP(i, G[now].size()) {
        if(t_cost[G[now][i]] == -1 && cost < a_cost[G[now][i]]) {
            t_dfs(G[now][i], cost+1);
        }
    }
}

void a_dfs(int now, int cost) {
    a_cost[now] = cost;
    REP(i, G[now].size()) {
        if(a_cost[G[now][i]] == -1) {
            a_dfs(G[now][i], cost+1);
        }
    }
}

void solve(long long N, long long u, long long v, std::vector<long long> A, std::vector<long long> B){
    fill(t_cost, t_cost+N, -1);
    fill(a_cost, a_cost+N, -1);

    REP(i, N-1) {
        G[A[i]-1].PB(B[i]-1);
        G[B[i]-1].PB(A[i]-1);
    }

    a_dfs(v-1, 0);
    t_dfs(u-1, 0);

    int max_cost = -INF;
    REP(i, N) {
        if(t_cost[i] != -1 && max_cost < a_cost[i]) {
            max_cost = a_cost[i];
        }
    }

    cout << (max_cost - 1) << endl;
}

