using Graph = vector<vector<int>>;
struct LCA {
    vector<vector<int>> par;
    vector<int> dist;
    LCA(const Graph& G, int root = 0) { init(G, root); }

    void init(const Graph& G, int root = 0) {
        int V = G.size();
        int K = 1;
        while ((1 << K) < V) K++;
        par.assign(K, vector<int>(V, -1));
        dist.assign(V, -1);
        dfs(G, root, -1, 0);
        for (int k = 0; k + 1 < K; k++) {
            for (int v = 0; v < V; v++) {
                if (par[k][v] < 0) {
                    par[k + 1][v] = -1;
                } else {
                    par[k + 1][v] = par[k][par[k][v]];
                }
            }
        }
    }

    void dfs(const Graph& G, int v, int p, int d) {
        par[0][v] = p;
        dist[v] = d;
        for (auto to : G[v]) {
            if (to != p) {
                dfs(G, to, v, d + 1);
            }
        }
    }

    int query(int u, int v) {
        if (dist[u] < dist[v]) swap(u, v);
        int K = par.size();
        for (int k = 0; k < K; k++) {
            if ((dist[u] - dist[v]) >> k & 1) {
                u = par[k][u];
            }
        }

        if (u == v) return u;
        for (int k = K - 1; k >= 0; --k) {
            if (par[k][u] != par[k][v]) {
                u = par[k][u];
                v = par[k][v];
            }
        }
        return par[0][u];
    }

    int get_dist(int u, int v) { return dist[u] + dist[v] - 2 * dist[query(u, v)]; }
};
