        --a, --b;
        g[a].push_back(b);
        g[b].push_back(a);    
    }

    auto lca = LCA(g, v);

    int ans = lca.get_dist(u, v);
    REP(i, N) {
        if (v == i) continue;
        if (u == i) continue;
        int tmp = lca.get_dist(v, i);
        int l = lca.query(i, u);
        if (lca.get_dist(u, l) <= lca.get_dist(v, l)) {
            chmax(ans, tmp);
        }
    }

    cout << ans - 1 << endl;
    return 0;
}

