ll t, a, n;

void dfsFill1(ll cur) {
    vis[cur] = 1;
    for (auto next: adj[cur]) {
        if (!vis[next]) {
            tDistance[next] = tDistance[cur] + 1;
            dfsFill1(next);
        }
    }
}

void dfsFill2(ll cur) {
    vis[cur] = 1;
    for (auto next: adj[cur]) {
        if (!vis[next]) {
            aDistance[next] = aDistance[cur] + 1;
            dfsFill2(next);
        }
    }
}

ll dfsDepth(ll cur) {
    vis[cur] = 1;
    bool isLeaf = 1;
    ll dep = 0;
    for (auto next: adj[cur]) {
        if (!vis[next]) {
            isLeaf = 0;
            dep = max(dep, dfsDepth(next));
        }
    }

    if (isLeaf) {
        leafDepth[cur] = 0;
        return 1;
    } else {
        leafDepth[cur] = dep;
        return leafDepth[cur] + 1;
    }
}

bool cmp(ll fir, ll sec) {
    if (leafDepth[fir] != leafDepth[sec]) {
        return (leafDepth[fir] > leafDepth[sec]);
    }
    return (aDistance[fir] > aDistance[sec]);
}

