int dfs(int node, int depth) {
    d1[node] = depth;
    used[node] = true;

    int md = depth;
    for(auto &e: E[node]) {
        if (used[e]) continue;

        int d = dfs(e, depth + 1);

        md = max(d, md);
    }

    return d2[node] = md;
}

int solve(int node, int step) {
    used[node] = true;
    if (step > d1[node]) return 0;

    int res = d2[node] - 1;
    for(auto &e: E[node]) {
        if (used[e]) continue;

        res = max(res, solve(e, step+1));
    }

    return res;
}

