const int INF = 1e9+7;

vector<int> bfs(int s, vector<vector<int>> &graph) {
  vector<bool> visited((int)graph.size(), false);
  vector<int> dist((int)graph.size(), INF);
  dist[s] = 0;
  queue<int> q;
  q.push(s);
  while (!q.empty()) {
    int u = q.front(); q.pop();
    if (visited[u]) continue;
    visited[u] = true;
    for (int v: graph[u]) {
      if (visited[v]) continue;
      if (dist[v] > dist[u] + 1) {
        dist[v] = dist[u] + 1;
        q.push(v);
      }
    }
  }

  return dist;
};

