  initGraph();
  rep(i, 0, N) {
    scanf("%d %d", &a, &b);
    addEdge(a, b);
  }

  int aoki[MAX]; // 青木くんのその頂点までの最短移動距離
  queue ki;
  initQueue(&ki);
  queuePush(&ki, v, 0);
  aoki[v] = 0;
  while ( !emptyQueue(&ki) ) {
    int n = ki.data[ki.front][0]; // 今
    int p = ki.data[ki.front][1]; // 親
    queuePop(&ki);
    taka[n] = taka[p] + 1;
    int count = 0;
    for (list *c = graph[n]; c != NULL; c = c->next) {
      if (c->node == p) continue;
      queuePush(&ki, c->node, n);
      count++;
    }
    if (count == 0) aoki[n] = 0;
  }

  int taka[MAX]; // 高橋くんのその頂点までの最短移動距離
  initQueue(&ki);
  queuePush(&ki, u, 0);
  taka[u] = 0;
