const ll MAX_V = 200010;

class dijkstra
{
public:
  struct edge
  {
    ll to;
    ll cost;
  };

  vector<edge> E[MAX_V];
  ll d[MAX_V];

  void calc(ll s)
  {
    priority_queue<pll, vector<pll>, greater<pll>> que;
    rep(i, MAX_V) d[i] = LINF;
    que.emplace(0LL, s);
    d[s] = 0LL;
    while (!que.empty())
    {
      pll p = que.top();
      que.pop();
      ll v = p.second;
      if (d[v] < p.first)
        continue;

      for (auto &&e : E[v])
      {
        if (d[e.to] > d[v] + e.cost)
        {
