    ds.E[a].push_back({b, 1});
    ds.E[b].push_back({a, 1});
  }
  ds.calc(v);
  for (int i = 1; i <= n; ++i)
  {
    for (auto t : ds.E[i])
    {
      if (ds.d[t.to] == ds.d[i] + 1)
      {
        ch[i].push_back(t.to);
        par[t.to] = i;
      }
    }
  }
  dfs(v);

  int ans = 0;
  int now = u;
  rep(i, (ds.d[u] - 1) / 2)
  {
