ll how_many_decendable(const vector<vector<ll>>&tree,vector<ll>&res,ll start,ll parent)
{
    ll ans=0;
    for(auto c:tree[start]){
        if(c!=parent){
            ans=max(ans,how_many_decendable(tree,res,c,start));
        }
    }
    return (res[start]=ans)+1;
}
void tree_distance(const vector<vector<ll>>&tree,vector<ll>&res,ll from,ll parent,ll dist=0)
{
    res[from]=dist;
    for(auto c:tree[from]){
        if(c!=parent){
            tree_distance(tree,res,c,from,dist+1);
        }
    }
}
void get_parent(const vector<vector<ll>>&tree,vector<ll>&res,ll from,ll parent)
{
    for(auto c:tree[from]){
        if(c!=parent){
            get_parent(tree,res,c,from);
        }
    }
    res[from]=parent;
}
