    }
    pair<int,int> get(int a,int b,int k=0,int l=0,int r=-1){
        if(r==-1)r=n;
        if(b<=l||r<=a)return {INF,INF};
        if(a<=l&&r<=b){
            return node[k];
        }
        else{
            return min(get(a,b,2*k+1,l,(l+r)/2),get(a,b,2*k+2,(l+r)/2,r));
        }
    }
};

struct EulerTour{
private:
    int k;
    void dfs(int v,int p,int dep){
        depth[v]=dep;
        par[v]=p;
        for(int u:tree[v]){
            if(u!=p){
                dwn[u]=k++;
                dfs(u,v,dep+1);
                up[u]=k;
            }
        }
    }
public:
    vector<int> dwn,up,depth,par;
    vector<vector<int>> tree;
    EulerTour(int n){
        dwn.resize(n);
        dwn[0]=-1;
        up.resize(n);
        up[0]=-1;
        tree.resize(n);
        depth.resize(n);
        par.resize(n);
    }
    void add_edge(int u,int v){
        tree[u].push_back(v);
        tree[v].push_back(u);
    }
    void build(int root){
        k=0;
        dfs(root,-1,0);
    }
};

int main(){
    int n,u,v;
    cin>>n>>u>>v;
    --u,--v;
    EulerTour et(n);
    for(int i=0;i<n-1;i++){
        int a,b;
        cin>>a>>b;
        --a,--b;
        et.add_edge(a,b);
    }
    et.build(0);
    vector<pair<int,int>> vec(n-1);
    for(int i=1;i<n;i++){
        vec[et.dwn[i]]={et.depth[i],i};
    }
    SegmentTree seg(vec);
    int ans=-1;
    for(int i=0;i<n;i++){
        int tlca;
        if(i==u)tlca=u;
        else tlca=et.par[seg.get(min(et.dwn[u],et.dwn[i])+1,max(et.dwn[u],et.dwn[i])+1).second];
        int tdist=et.depth[u]+et.depth[i]-2*et.depth[tlca];
        int alca;
        if(i==v)alca=v;
        else alca=et.par[seg.get(min(et.dwn[i],et.dwn[v])+1,max(et.dwn[i],et.dwn[v])+1).second];
        int adist=et.depth[i]+et.depth[v]-2*et.depth[alca];
        if(tdist<adist){
            ans=max(ans,adist-1);
        }
    }
    cout<<ans<<endl;
}

