struct Graph{
    struct Edge{
        int from;
        int to;
        ll  cost;

        Edge(int a, int b, ll c) : from(a), to(b), cost(c) {}
    };
    int N;
    vector<vector<Edge>> edges;
    vector<int> deg;
    vector<ll> dist;

    Graph(int n) : N(n), edges(n), deg(n, 0), dist(n, INF) {}

    bool visited(int v){
        return dist[v] < INF;
    }

    void resetDist(){
        for(int i=0; i<N; i++) dist[i] = INF;
    }

    void connect(int a, int b, ll c){
        edges[a].emplace_back(Edge(a, b, c));
        deg[b]++;
    }

    void dfs(int p, int v, ll d){
        if(visited(v)) return;
        dist[v] = d;
        for(auto e : edges[v]){
            if(e.to == p) continue;
            dfs(v, e.to, d + e.cost);
        }
    }

    bool isAcyclic(){
        static vector<int> status(N, 0);
        for(int i=0; i<N; i++){
            if(!isAcyclicDfs(status, i)) return false;
        }
        return true;
    }

    bool isAcyclicDfs(vector<int>& status, int v){
        status[v] = 1;
        for(auto e : edges[v]){
            if(status[e.to] == 1){
                return false;
            }else if(status[e.to] == 0){
                if(!isAcyclicDfs(status, e.to)){
                    return false;
                }
            }
        }
        status[v] = 2;
        return true;
    }

    int criticalLength(){
        vector<int> source;
        for(int i=0; i<N; i++){
            if(deg[i] == 0) source.push_back(i);
        }

        int cnt = 1;

        while(true){
            vector<int> v;
            for(int s : source){
                for(auto e : edges[s]){
                    deg[e.to]--;
                    if(deg[e.to] == 0){
                        v.push_back(e.to);
                    }
                }
            }
            if(v.empty()) break;
            source = v;
            cnt++;
        }
        return cnt;
    }
};

