struct Node
{
    bool visited = false;
    long taka = INF;
    long aoki = INF;
    vector<long> adj;
};

void bfs(long x, vector<Node> &nodes, bool taka)
{
    queue<long> q;
    q.push(x);
    while (not q.empty()) {
        long y = q.front();
        q.pop();
        Node &r = nodes[y];
        r.visited = true;
        long dist = (taka) ? r.taka : r.aoki;
        for (auto &z : r.adj) {
            Node &u = nodes[z];
            if (u.visited) continue;
            if (taka) {
                if (dist + 1 < u.aoki) {
                    u.taka = dist + 1;
                    q.push(z);
                }
            } else {
                u.aoki = dist + 1;
                q.push(z);
            }
        }
    }
}

int main()
{
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);

    long t = 1;
    //cin >> t;

    while (t--) {
        long n, u, v;
        cin >> n >> u >> v;

        vector<Node> nodes(n+1);
        nodes[u].taka = 0;
        nodes[v].aoki = 0;
        for (long i = 0; i < n-1; i++) {
            long a, b;
            cin >> a >> b;
            nodes[a].adj.push_back(b);
            nodes[b].adj.push_back(a);
        }
        bfs(v, nodes, false);
        for (long i = 1; i <= n; i++) {
            nodes[i].visited = false;
        }
        bfs(u, nodes, true);

        long ans = -INF;
        long diff = nodes[u].aoki;
        for (long i = 1; i <= n; i++) {
            if (nodes[i].taka != INF) {
                ans = max(ans, nodes[i].aoki);
            }
        }
        ans -= 1;
        printf("%lld\n", ans);
    }
}

