using graph = map<int, vector<int>>;

int n;
int inf = 100000000;

vector<int> bfs(graph &G,int v) {
  queue<int> q;
  vector<int> dist(n,-1);
  q.push(v);
  dist[v] = 0;
  while(!q.empty()) {
    int v = q.front(); q.pop();
    for (auto nv : G[v]) {
      if (dist[nv] != -1) continue;
      dist[nv] = dist[v] + 1;
      q.push(nv);
    }
  }
  return dist;
}

int main() {
  int u,v;
  cin >> n >> u >> v;
  u--, v--;
  graph G;
  rep(i,0,n-1) {
    int a,b;
    cin >> a >> b;
    a--; b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  vector<int> a = bfs(G,v), t = bfs(G,u);
  int ans = 0;
  rep(i,0,n) {
    if (a[i] > t[i]) {
      ans = max(ans, a[i] - 1);
    }
  }
  cout << ans << endl;
  return 0;
}

