pair<vector<length>,vector<int>> pfs(Weighted g,int s,length infinity=linf){
	vector<int> prv(g.size());
	vector<length> d(g.size(),infinity);
	using cont=pair<length,int>;
	priority_queue<cont,vector<cont>,greater<cont> > q;

	d[s]=0;q.push({0,s});
	int cv; length cd;
	while(q.size()){
		cd=q.top().first;
		cv=q.top().second;
		q.pop();
		if(cd>d[cv])continue;
		for(edge &e:g[cv])if(d[e.to]>cd+e.cost){
			d[e.to]=cd+e.cost;
			prv[e.to]=cv;
			q.push({d[e.to],e.to});
		}
	}
	return {d,prv};
}//http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=3996122#1
