template< typename G >
struct DoublingLowestCommonAncestor{
  const int LOG;
  vector<int> dep;
  const G &g;
  vector<vector<int> > table;

  DoublingLowestCommonAncestor(const G &g) : g(g), dep(g.size()), LOG(32 - __builtin_clz(g.size())){
    table.assign(LOG, vector<int>(g.size(),-1));
  }

  void dfs(int idx, int par, int d){
    table[0][idx] = par;
    dep[idx] = d;
    for(auto & to : g[idx]){
      if(to != par) dfs(to, idx, d+1);
    }
  }

  void build(){
    dfs(0,-1,0);
    rep(k,LOG-1){
      rep(i,table[k].size()){
        if(table[k][i] == -1) table[k+1][i] = -1;
        else table[k+1][i] = table[k][table[k][i]];
      }
    }
  }

  int query(int u, int v){
    if(dep[u] > dep[v])swap(u,v);
    per(i,LOG) if(((dep[v] - dep[u]) >> i) & 1) v = table[i][v];
    if(u==v) return u;
    per(i,LOG){
      if(table[i][u] != table[i][v]){
        u = table[i][u];
        v = table[i][v];
      }
    }
    return table[0][u];
  }
};

vector<vector<int> > makeTree(int s, const vector<vector<int> > &G){
 vector<vector<int> > Tree(N_MAX);
 set<int> st;
 queue<int> que;
 que.push(0);
 map<int,int> MP;
 MP[mp.size()] = s;
 mp[s] = mp.size();

 while(!que.empty()){
   int cur = que.front();que.pop();
   for(const int & v : G[MP[cur]]){
     if(mp.count(v))continue;
     MP[mp.size()] = v;
     mp[v] = mp.size();
     que.push(mp[v]);
     Tree[cur].push_back(mp[v]);
   }
 }
 return Tree;
}

