//幅優先探索 (グラフ: vector)
void bfs_vec(ll start){
    queue<int> q; //<コスト, ノード>
    bool visited[NODE_SIZE];
    for(int i=0; i<N; i++) visited[i]=false;    //初期位置を設定
    for(int i=0; i<N; i++) dist1[i] = -1;// 最後まで-1なら到達不可能
    q.push(start);  //開始ノードを追加
    dist1[start] = 0; // 初期状態のコスト
    while(!q.empty()){
        int curNode = q.front();
        int curStep = dist1[curNode];
        q.pop();
        if(visited[curNode]) continue;
        visited[curNode] = true;

        for(auto nextEdge: edge[curNode]){
            int nextNode = nextEdge;
            if(!visited[nextNode]){     //未到達のノードだけpush.
                q.push(nextNode);
                dist1[nextNode] = curStep + 1;
            }
        }
    }
}

