void dfs(vector<vector<int>> &tree, int now, int bf, vector<int> &ans, int o, vector<int> &leaf, bool mode){
	bool flag = true;
	for(int i : tree.at(now)){
		if(i == bf) continue;
		ans.at(i) = ans.at(now) + 1;
		flag = false;
		if(i == o){
			leaf.push_back(i);
			continue;
		}
		dfs(tree, i, now, ans, o, leaf, mode);
	}
	if(mode == true && flag == true) leaf.push_back(now);
}

