#define	MOD 1000000007

int	main() {
	int N, u, v;
	cin >>N >>u >>v;
	// Input
	vector<vector<int>>	bridge(N-1, vector<int> (2));
	for (int i=0; i<N-1; i++) 
		for (int j=0; j<2; j++)
			cin >> bridge.at(i).at(j);
	// Struct for each node
	struct Node {
		vector<int> to_node;
		bool fix;
		int cost;
	};
	vector<Node> nodeT(N);
	// Initialize
	for (int i=0; i<N; i++) {
		nodeT.at(i).fix=false;
		nodeT.at(i).cost=INF;
	}
	// Data for each nodeT
	for (int i=0; i<N-1; i++) {
		int F=bridge.at(i).at(0)-1;
		int T=bridge.at(i).at(1)-1;
		nodeT.at(F).to_node.push_back(T);
		nodeT.at(T).to_node.push_back(F);
	}
	// Start
	// Start Node == Cost=0
	nodeT.at(u-1).cost=0;
	priority_queue<vector<int>, vector<vector<int>>, greater<vector<int>>> q;
	q.push({nodeT.at(u-1).cost, u-1});
	// till Goal fixed
	while (!q.empty()) {
		// Pickup the Node with minimum cost
		int c=q.top().at(0);
		int ii=q.top().at(1);
		q.pop();
		// If fixed, skip
		if(nodeT.at(ii).fix)
			continue;
		// Change it to fixed and search for near-by nodeTs
		nodeT.at(ii).fix=true;
		for (int i=0; i<nodeT.at(ii).to_node.size(); i++) {
			int o_node=nodeT.at(ii).to_node.at(i);
			// Update cost
			int o_cost=c+1;
			// Process only when smaller
			if (o_cost>=nodeT.at(o_node).cost)
				continue;
			nodeT.at(o_node).cost=o_cost;
			// Push into queue
			q.push({o_cost, o_node});
		}
	}
	vector<Node> nodeA(N);
	// Initialize
	for (int i=0; i<N; i++) {
		nodeA.at(i).fix=false;
		nodeA.at(i).cost=INF;
	}
	// Data for each nodeA
	for (int i=0; i<N-1; i++) {
		int F=bridge.at(i).at(0)-1;
		int T=bridge.at(i).at(1)-1;
		nodeA.at(F).to_node.push_back(T);
		nodeA.at(T).to_node.push_back(F);
	}
	// Start
	// Start Node == Cost=0
	nodeA.at(v-1).cost=0;
	//priority_queue<vector<int>, vector<vector<int>>, greater<vector<int>>> q;
	q.push({nodeA.at(v-1).cost, v-1});
	// till Goal fixed
	while (!q.empty()) {
		// Pickup the Node with minimum cost
		int c=q.top().at(0);
		int ii=q.top().at(1);
		q.pop();
		// If fixed, skip
		if(nodeA.at(ii).fix)
			continue;
		// Change it to fixed and search for near-by nodeAs
		nodeA.at(ii).fix=true;
		for (int i=0; i<nodeA.at(ii).to_node.size(); i++) {
			int o_node=nodeA.at(ii).to_node.at(i);
			// Update cost
			int o_cost=c+1;
			// Process only when smaller
			if (o_cost>=nodeA.at(o_node).cost)
				continue;
			nodeA.at(o_node).cost=o_cost;
			// Push into queue
			q.push({o_cost, o_node});
		}
	}
	int S=0;
	for (int i=0; i<N; i++) {
		int s=nodeA.at(i).cost-nodeT.at(i).cost;
		if (s>0)
			S=max(S, nodeA.at(i).cost-1);
	}
	cout <<S <<endl;
	return 0;
}

