void dfs(const Graph &G, int v, int p, int d, vector<int> &depth)
{
  depth[v] = d;
  for (auto next_v : G[v])
  {
    if (next_v == p)
      continue;
    dfs(G, next_v, v, d + 1, depth);
  }
}

