vector<vector<int>> vt;
int parse[100010];
int de[100010];
int ma[100010];
void dfs(int here, int par, int depth) {
	parse[here] = par;
	de[here] = depth;
	ma[here] = depth;
	for (int i = 0; i < vt[here].size(); i++) {
		int next = vt[here][i];
		if (next == par)continue;
		dfs(next, here, depth + 1);
		ma[here] = max(ma[here], ma[next]);
	}
}
int main()
{
	int n, m, k;
	scanf("%d %d %d", &n, &m, &k);
	vt.resize(n + 1);
	for (int i = 0; i < n - 1; i++) {
		int q, w;
		scanf("%d %d", &q, &w);
		vt[q].push_back(w);
		vt[w].push_back(q);
	}
	dfs(k, -1, 1);
	int WantFinishEarly = 1;
	int WantFinishSlowly = de[m];
	int dap = 0;
	int update = 0;
	while (1) {
		if (update % 2 == 0) {
			if (WantFinishSlowly - WantFinishEarly <= 2)break;
			WantFinishSlowly--;
			m = parse[m];
			update++;
		}
		else {
			WantFinishEarly++;
			dap++;
			update++;
			if (WantFinishSlowly - WantFinishEarly == 1)break;
		}
	}
	while (1) {
		if (update % 2 == 0) {
			if (ma[m] == WantFinishSlowly)
				WantFinishSlowly--;
			else
				WantFinishSlowly++;
		}
		else {
			WantFinishEarly++;
			dap++;
		}
		if (WantFinishEarly == WantFinishSlowly)break;
		update++;
	}
	printf("%d", dap);
}

