int calc_max_dist_v(int n){
  visit[n] = 1;
  max_dist_v[n] = dist_v[n];
  for(int next : T[n]){
    if(visit[next])continue;
    max_dist_v[n] = max(max_dist_v[n], calc_max_dist_v(next));
  }
  return max_dist_v[n];
}

