void solve(istream& input, ostream& output) {
	int N, u, v; cin >> N >> u >> v;
	u--; v--;
	vector<vector<int>> g(N);
	rep(i, N-1) {
		int a, b; cin >> a >> b; a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	auto dfs = [&](auto f, int n, int d = 0, int p = -1) -> pair<bool, int> {
		if (n == v) return make_pair(true, d);
		for (auto x : g[n]) {
			if (x == p) continue;
			auto r = f(f, x, d+1, n);
			if (!r.first) continue;
			if (d == (r.second - 1) / 2) {
				u = n;
				v = x;
			}
			return r;
		}
		return make_pair(false, -1);
	};
	auto res1 = dfs(dfs, u);

	auto dfs2 = [&](auto f, int n, int d = 0, int p = -1) -> int {
		int ret = d;
		for (auto x : g[n]) {
			if (x == p) continue;
			if (x == v) continue;
			chmax(ret, f(f, x, d+1, n));
		}
		return ret;
	};
	int res = dfs2(dfs2, u) + res1.second / 2;
	// cout << u << " " << v << " " << res << endl;
	cout << res << endl;
}

