ll fast(ll a, ll b, ll mod) {
    if(b < 0)a = inverse(a, mod), b = -b;
    ll ans = 1;
    while(b) {
        if(b & 1) {
            b--;
            ans = ans * a % mod;
        } else {
            a = a * a % mod;
            b /= 2;
        }
    }
    return ans % mod;
}


namespace SOLVE {
    const int maxn = 200100;
    int height[maxn], f[maxn];
    VLL adj[maxn];
    ll n, u, v;
    int le[maxn], ri[maxn];
    int cnt = 1;

    void dfs(int cur, int fa) {
        f[cur] = fa;
        le[cur] = ri[cur] = cnt++;
        for(auto s:adj[cur]) {
            if(s != fa) {
                dfs(s, cur);
                upmax(height[cur], height[s] + 1);
                ri[cur] = ri[s];
            }
        }
    }

    int ans = 0;

    int get_neighbor(int u, int v) {
        for(auto s:adj[v]) {
            if(s != f[v]) {
                if(le[s] <= le[u] and ri[u] <= ri[s])return s;
            }
        }
        assert(0);
        return 1;
    }

    void solve(int u, int v) {
        if(f[u] == v or f[f[u]] == v) {
            if(height[u] == 0){
                if(f[f[u]] == v)ans++;
                return;
            }
            for(auto s:adj[u]) {
                if(height[s] == height[u] - 1) {
                    u = s;
                    break;
                }
            }
            v = get_neighbor(u, v);
            ans++;
            solve(u, v);
        } else {
            u = f[u];
            v = get_neighbor(u, v);
            ans++;
            solve(u, v);
        }
    }

    void main() {
        in(n, u, v);
        REP(i, 1, n) {
            ll a, b;
            in(a, b);
            adj[a].PB(b);
            adj[b].PB(a);
        }
        dfs(v, 0);
        solve(u, v);
        cout << ans << endl;
    }
}


