int root;

vector<int> temp_node[100000];

struct node{
    int parent;
    int height;
    vector<int> child;
};

void construct_tree(node *nd, int p, int s){
    nd[s].parent = p;
    rep(i, temp_node[s].size()){
        int to = temp_node[s][i];
        if(to == p) continue;
        nd[s].child.push_back(to);
        construct_tree(nd, s, to);
    }
}

int calc_height(node *nd, int p, int s){
    int res = -1;
    if(nd[s].child.empty()){
        nd[s].height = 0;
        return 0;
    }
    rep(i, nd[s].child.size()){
        res = max(res, calc_height(nd, s, nd[s].child[i]));
    }
    nd[s].height = res + 1;
    return nd[s].height;
}

int main(void){
    int N; cin >> N;
    int u, v; cin >> u >> v;
    u--; v--;
    root = v;
    node nd[N];

    rep(i, N-1){
        int a, b; cin >> a >> b;
        a--; b--;
        temp_node[a].push_back(b);
        temp_node[b].push_back(a);
    }

    construct_tree(nd, -1, root);

    calc_height(nd, -1, root);

    int pos = u;
    int dist = 0;
    while(pos != root){
        pos = nd[pos].parent;
        dist++;
    }
    int ans = 0;
    int climb = (dist-1) / 2;
    rep(i, climb){
        u = nd[u].parent;
        ans++;
    }
    dist -= ans*2;
    int h = nd[u].height;
    if(dist % 2 == 0){
        cout << ans + h + 1 << endl;
    }
    else{
        cout << ans + h << endl;
    }

    return 0;
}

