// 最近共通祖先 last common ancestor
class LCA{
private:
	vector<vector<int> > to;
	vector<int> depth;
	void dfs(const vector<vector<int> >& edges, int curr, int prev, int cnt){
		depth[curr] = cnt;
		if(prev != -1){
			to[curr].push_back(prev);
			int j = prev;
			rep(k, sz(to[j])){
				j = to[j][k];
				to[curr].push_back(j);
			}
		}
		rep(i,sz(edges[curr])){
			int next = edges[curr][i];
			if(next != prev)
				dfs(edges, next, curr, cnt + 1);
		}
	}
	int climb(int curr, int dist){
		for(int i=0;dist > 0; ++i){
			if(dist % 2 == 1)
				curr = to[curr][i];
			dist /= 2;
		}
		return curr;
	}
public:
	LCA(const vector<vector<int>>& edges, int root){
		int n = sz(edges);
		to.assign(n, vector<int>());
		depth.assign(n,0);
		dfs(edges, root, -1, 0);
	}
	int query(int a, int b){
		pair<int, int> dist(0, 0);
		int diff = depth[a] - depth[b];
		if(diff < 0){
			b = climb(b, -diff);
			dist.second += -diff;
		}else{
			a = climb(a, diff);
			dist.first += diff;
		}

		if(a == b) return dist.first + dist.second;
		for(int x = sz(to[a]) -1; x >= 0; --x){
			if(x < sz(to[a]) && to[a][x] != to[b][x]){
				a = to[a][x];
				b = to[b][x];
				dist.first += 1 << x;
				dist.second += 1 << x;
			}
		}

		return dist.first + dist.second + 2;
	}
};
