class Tree {
	private:
		vector<vecl> G;
		vector<vecl> parents;
		vector<ll> depths;
		ll LOG;

	public: 
		Tree(ll V) {
			LOG = log2(V+10)+10;
			parents.resize(LOG+1, vecl(V+1));
			depths.resize(V+1);
			G.resize(V+1);
		}

		void add(ll x,ll y) {
			G[x].push_back(y);
			G[y].push_back(x);
		}

		void build(ll root=1) {
			ll V = G.size()-1;
			dfs(root, -1, 0);
			rep(k, LOG) {
				rep(v,V) {
					if (parents[k][v] < 0)
						 parents[k + 1][v] = -1;
					else 
						parents[k + 1][v] = parents[k][parents[k][v]];
				}
			}
		}

		void dfs(ll v, ll parent, ll depth) {
			parents[0][v] = parent;
			depths[v] = depth;
			for (auto &i : G[v])
			{
				if (i != parent) dfs(i, v, depth+1);
			}
		}

		vecl leaves() {
			ll V = G.size()-1;
			vecl res;
			rep(i,V) {
				if (G[i].size() == 1) res.push_back(i);
			}
			return res;
		}

		ll lca(ll u, ll v) {
			if (depths[u] > depths[v]) swap(u, v);
			rep(k, LOG) {
				if ((depths[v] - depths[u]) >> k & 1)
				v = parents[k][v];
			}
			if (u == v) return u;
			for (ll k = LOG; k >= 0; k--) {
				if (parents[k][u] != parents[k][v])
				{
					u = parents[k][u];
					v = parents[k][v];
				}
			}
			return parents[0][u];
		}

		ll distance(ll u, ll v) {
			ll t = lca(u, v);
			return depths[u] + depths[v] - 2*depths[t];
		}
};



