void kr(int s, int memo[100000]) {
    bool visited[100000] = {};
    priority_queue<P,vector<P>,greater<P>> pq;
    pq.push(mp(0,s));
    while(pq.size()) {
        int cost = pq.top().fi, to = pq.top().se;pq.pop();
