    return true;
  }
}

long long gcd_(long long a, long long b){
  if(a<b){
    swap(a,b);
  }
  if(a%b==0){
    return b;
  }else{
    return gcd_(b,a%b);
  }
}

long long lcm_(long long x, long long y){
  return (x/gcd_(x,y))*y;
}

