void dfs2(int r, int p) {
    int height = 0;

    par[r] = p;

    for(int i = 0; i < inp[r].size(); i++) {
        if(p != inp[r][i]) {
            dfs2(inp[r][i], r);
            height = max(height, ht[inp[r][i]] + 1);
        }
    }

    ht[r] = height;
}

