template< typename G >
class DoublingLowestCommonAncestor {
public:
	const G &g;
	vector< int > depth;//depth[v]=根からvまでの距離
	const int LOG;
	vector< vector< int > > table;

	DoublingLowestCommonAncestor(const G &g) : g(g), depth(g.size()), LOG(32 - __builtin_clz(g.size())) {
		table.assign(LOG, vector< int >(g.size(), -1));
	}

	void dfs(int idx, int par, int d) {
		table[0][idx] = par;
		depth[idx] = d;
		for(auto &to : g[idx]) {
			if(to != par) dfs(to, idx, d + 1);
		}
	}

	void build() {
		dfs(0, -1, 0);
		for(int k = 0; k + 1 < LOG; k++) {
			for(int i = 0,tablesize = table[k].size(); i < tablesize; i++) {
				if(table[k][i] == -1) table[k + 1][i] = -1;
				else table[k + 1][i] = table[k][table[k][i]];
			}
		}
	}

	int query(int u, int v) {
		if(depth[u] > depth[v]) swap(u, v);
		for(int i = LOG - 1; i >= 0; i--) {
			if(((depth[v] - depth[u]) >> i) & 1) v = table[i][v];
		}
		if(u == v) return u;
		for(int i = LOG - 1; i >= 0; i--) {
			if(table[i][u] != table[i][v]) {
				u = table[i][u];
				v = table[i][v];
			}
		}
		return table[0][u];
	}
};

class Edge {
public:
	ll from,to,cost;
	Edge() {}
	Edge(ll from, ll to, ll cost) : from(from), to(to), cost(cost) {}
};
ostream& operator<<(ostream& s, const Edge& e) {
	s << "{ " << e.from << " -> " << e.to << ", " << e.cost << " }";
	return s;
}

/*
計算量：O(ElogV)
引数
　g:探索するグラフ
　start:探索するスタートノード番号
戻り値
　dist:スタートノードから各頂点までの距離
　prev:最短路木の親頂点
*/
void dijkstra(const vector<vector<Edge>> &g, ll start, vector<ll> &dist, vector<ll> &prev) {
	ll gsize = g.size();
	dist.assign(gsize, INF); dist[start] = 0;
	prev.assign(gsize, -1);

	priority_queue<Edge, vector<Edge>, function<bool(Edge,Edge)>> que(
		[](const Edge &x, const Edge &y){
			return x.cost != y.cost ? (x.cost > y.cost) : 
				(x.from != y.from ? x.from < y.from : x.to < y.to);
		}
	);
	que.push(Edge(-1, start, 0));
	while (!que.empty()) {
		Edge e = que.top();
		que.pop();
		if (prev[e.to] != -1) continue;
		prev[e.to] = e.from;
		for(Edge f : g[e.to]) {
			if (dist[f.to] > e.cost + f.cost) {
				dist[f.to] = e.cost + f.cost;
				que.push(Edge(f.from, f.to, e.cost+f.cost));
			}
		}
	}
}
//最短路木の親頂点を元にstart->goalの経路を作成
vector<ll> buildPath(const vector<ll> &prev, ll goal) {
	vector<ll> path;
	for (ll u = goal; u >= 0; u = prev[u])
		path.push_back(u);
	reverse(path.begin(), path.end());
	return path;
}
