const ll N_MAX = 1e5;

ll N, startT, startA;
vector<ll> A;
vector<ll> B;

void solve() {
	scanf("%lld%lld%lld", &N, &startT, &startA);
	startT--;startA--;
	A.assign(N, 0);
	B.assign(N, 0);
	rep(i, N) { scanf("%lld%lld", &A[i], &B[i]); A[i]--;B[i]--;}


	vector<vector<Edge>> g(N);
	vector<vector<ll>> glca(N);
	rep(i,N-1){
		Edge e(A[i],B[i],1);
		Edge e1(B[i],A[i],1);
		g[A[i]].push_back(e);
		g[B[i]].push_back(e1);
		glca[A[i]].push_back(B[i]);
		glca[B[i]].push_back(A[i]);
	}

	vector<ll> distT, prevT;
	dijkstra(g, startT, distT, prevT);
	vector<ll> distA, prevA;
	dijkstra(g, startA, distA, prevA);


	DoublingLowestCommonAncestor< vector<vector<ll>> > lca(glca);
	lca.build();

	vector<ll> dis(N,-1);
	rep(i,N){
		ll lcav=lca.query(startT,i);
		if(distA[lcav] > distT[lcav]){
			dis[i]=distA[i];
		}
	}
	ll maxval=-1;
	ll maxindex=-1;
	rep(i,N){
		if(chmax(maxval,dis[i])){
			maxindex=i;
		}
	}

	ll ans = maxval-1;
	printf("%lld\n", ans);
}

