void DFS(int past, int now, int level){
	L[now] = level;

	for(int i = 0; i < tree[now].size(); i++){
		if(past != -1){
			if(tree[now][i] == past){
				continue;
			}
		}
		DFS(now, tree[now][i], level+1 );
	}
}

int DFS_2(int past, int now, int level, int BannedL){
	if(L[now] <= BannedL){
		return -1;
	}
	int M = 0;
	for(int i = 0; i < tree[now].size(); i++){
		if(past != -1){
			if(tree[now][i] == past){
				continue;
			}
		}
		M = max(M, DFS_2(now, tree[now][i], level+1, BannedL));
	}

	return max(M, level);
}

