#include <iostream>
#include <vector>
using namespace std;

bool find_path(vector<vector<int>> &E, int s, int g, int p, vector<int> &path) {
  if (s == g) {
    path.push_back(s);
    return true;
  }

  for (int t : E[s]) {
    if (t == p) continue;

    if (find_path(E, t, g, s, path)) {
      path.push_back(s);
      return true;
    }
  }

  return false;
}

int dfs(vector<vector<int>> &E, int v, int p, int d) {
  int ret = d;

  for (int u : E[v]) {
    if (u == p) continue;

    ret = max(ret, dfs(E, u, v, d + 1));
  }

  return ret;
}

