  int pd = path.size() - 1;
  int d = (pd - 1) / 2;
  int r = path[d];
  int z = path[d + 1];

  int dest = dfs(E, r, z, 0);

  if (dest == 0) {
    cout << pd / 2 << endl;
  } else {
    cout << dest + d << endl;
  }
}

