struct Vertex {
	uint d_u = UINT_MAX;
	uint d_v = UINT_MAX;
};

bool dijkstra_u(const uint vid, vector<Vertex>& V, const vector<vector<uint>>& E, const uint d) {

	if(V[vid].d_u <= d) {
		return false;
	}

	V[vid].d_u = d;

	for(auto nv : E[vid]) {
		dijkstra_u(nv, V, E, d+1);
	}

	return true;
}

bool dijkstra_v(const uint vid, vector<Vertex>& V, const vector<vector<uint>>& E, const uint d) {

	if(V[vid].d_v <= d) {
		return false;
	}

	V[vid].d_v = d;

	for(auto nv : E[vid]) {
		dijkstra_v(nv, V, E, d+1);
	}

	return false;
}

