        G[B[i]].push_back(A[i]);
    }
    for(int i = 0; i < N; i++){
        if(G[i].size() == 1) leaf[i] = true;
    }
    root = v;
    // dfs(v, 0);
    init(N);
    int ans;
    int cur = -1;
    for(int i = 0; i < N; i++){
        if(leaf[i]){
            int la = lca(u, i);
            if(depth[la] < depth[u]-depth[la]) continue;
            if(depth[la] == depth[u]-depth[la]) {
                // cout << i << endl;
                if(cur < depth[la]){
                    cur = depth[la];
                }
                continue;
            }
            if(i == u){
                int len;
                if(depth[i]%2 == 0){
                    len = depth[i-1]-1;
                }else{
                    len = depth[i-1];
                }
                if(cur < len) cur = len;
