	ll uuu = u;
	while (true){
		if (depth[uuu] == q) break;
		uuu = parent[uuu];
	}

	maxDepth = depth[uuu];
	dfs(uuu, parent[uuu]);

	cout << maxDepth-1 << '\n';
}

