class Graph {
   private:
    struct edge {
        int to;
        int cost;
        edge(int i, int c = 1) : to(i), cost(c) {}
    };
    vector<vector<edge>> edges;
    vector<int> max_depthes;
    vector<int> reached_nodes;

   public:
    vector<int> path_u_v;
    Graph(int n) { edges.resize(n); };
    int size() const { return edges.size(); };
    int countEdge() const {
        int count = 0;
        for (auto &&i : edges)
            for (auto &&j : i) count++;
        return count;
    }
    void addDirectedEdge(int from, int to, int cost = 1) {
        edges[from].push_back(edge(to, cost));
    }
    void addEdge(int from, int to, int cost = 1) {
        addDirectedEdge(from, to, cost);
        addDirectedEdge(to, from, cost);
    }

    int searchMaxDepths(int hn, int pn, int depth = 0) {
        if (depth == 0) max_depthes.assign(edges.size(), 0);

        int max_depth = depth;

        for (auto &&edge : edges[hn]) {
            const int nn = edge.to;
            if (nn == pn) continue;
            max_depth = max(searchMaxDepths(nn, hn, depth + 1), max_depth);
        }

        return max_depthes[hn] = max_depth;
    }

    void searchPath(int hn, int goal, int pn = -1, int depth = 0) {
        if (depth == 0) reached_nodes.clear();
        reached_nodes.push_back(hn);

        if (hn == goal) path_u_v = reached_nodes;

        for (auto &&edge : edges[hn]) {
            const int nn = edge.to;
            if (nn == pn) continue;
            searchPath(nn, goal, hn, depth + 1);
        }

        reached_nodes.pop_back();
    }

    int answer(int u, int v) {
        searchMaxDepths(v, -1, 0);
        searchPath(v, u);

        int use_max_depth = 0;

        const int d = path_u_v.size();
        for (int i = 0; i < d / 2; i++) {
            use_max_depth =
                max(max_depthes[path_u_v[d - i - 1]], use_max_depth);
        }

        return use_max_depth - 1;
    }
};

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    int n, u, v;  // u: takahashi, v: aoki
    cin >> n >> u >> v;
    u--, v--;  // transform to 0-based
    vector<int> a(n), b(n);
    for (int i = 0; i < n - 1; i++) {
        cin >> a[i] >> b[i];
        a[i]--, b[i]--;  // transform to 0-based
    }

    Graph g(n);
    for (int i = 0; i < n - 1; i++) {
        g.addEdge(a[i], b[i]);
    }

    const int ans = g.answer(u, v);

    cout << ans << endl;
}

