int getnjumps(int a, int t, vector<int> &s, int prev, bool &found) {
    if (a == t) {
        found = true;
        s.push_back(t);
        return 0;
    }

    s.push_back(a);
    for (int j : g[a]) {
        if (j != prev) {
            int res = getnjumps(j, t, s, a, found);
            if (found) {
                return 1 + res;
            }
        }
    }

    s.pop_back();
    return 0;
}

int dfs(int v, int prev) {
    if (g[v].size() == 1) {
        return 0;
    }
    int ans = 0;
    for (int j : g[v]) {
        if (j != prev) {
            ans = max(ans, 1 + dfs(j, v));
        }
    }
    return ans;
}

