    }
    vector<int> s;
    bool found = false;
    int njumps = getnjumps(a, t, s, -1, found);
    int nnodes = njumps - 1;
    if (nnodes < 1) {
        cout << "0"; return 0;
    }
    if (nnodes == 1) {
        cout << "1"; return 0;
    }
    int ntjumps = nnodes >> 1;
    int ancestor = s[s.size() - 1 - ntjumps];
    int njumpstoleaf = 0;
    for (int j : g[ancestor]) {
        if (j != s[s.size() - 2 - ntjumps]) {
            njumpstoleaf = max(njumpstoleaf, 1 + dfs(j, ancestor));
        }
    }
    int ans = njumpstoleaf + (nnodes & 1) + ntjumps;
    cout << ans;

    return 0;
}

