#include <bits/stdc++.h>
using namespace std;
vector<vector<int>> g;
vector<bool> seen_1;
vector<int> depth_1;
vector<bool> seen_2;
vector<int> parent;
vector<int> subTree;
void dfs(int node, bool type) {
  if(!type) {
    if(seen_1[node]) return;
    seen_1[node] = true;
    for(auto& nex : g[node]) {
      if(seen_1[nex]) continue;
      else {
        depth_1[nex] = depth_1[node] + 1;
        parent[nex] = node;
        dfs(nex, type);
      }
    }
  }
  else {
    if(seen_2[node]) return;
    seen_2[node] = true;
    subTree.emplace_back(node);
    for(auto& nex : g[node]) {
      if(seen_2[nex]) continue;
      else dfs(nex, type);
    }
  }
}
int main() {
