  depth_1.resize(n, 0);
  seen_2.resize(n, false);
  parent.resize(n, -1);
  for(int i=0;i<n-1;i++) {
    int a, b;
    cin >> a >> b;
    a--;b--;
    g[a].emplace_back(b);
    g[b].emplace_back(a);
  }
  dfs(v, 0);
  vector<int> path;
  path.emplace_back(u);
  int now = u;
  while(parent[now] != -1) {
    path.emplace_back(parent[now]);
    now = parent[now];
  }
  int target = path[path.size()/2-1];
  seen_2[parent[target]] = true;
  dfs(target, 1);
  int deepest = 0;
  for(auto& el : subTree) {
    if(depth_1[el] > deepest) deepest = depth_1[el];
  }
  cout << deepest - 1 << endl;
  return 0;
}

