int dfs(int now, int d) {
  if (visit[now])
    return 0;
  depth[now] = d;
  visit[now] = 1;
  int dd = 0;
  for (auto elem : graph[now]) {
    if (!visit[elem])
      parent[elem] = now;
    dd = max(dd, dfs(elem, d + 1) + 1);
  }
  longest[now] = dd;
  return dd;
}

