void dfs(int v, int p, int d, int &i){
    depth[v] = d;
    in[v] = i;

    seg.set(i, std::make_tuple(d, v));
    i += 1;

    for(int w : G[v]){
        if(w == p){continue;}
        dfs(w, v, d + 1, i);

        seg.set(i, std::make_tuple(d, v));
        i += 1;
    }
}

int lca(int v, int w){
    if(in[v] > in[w]){
        std::swap(v, w);
    }

    // auto [_, x] = seg.product(in[v], in[w]);
    int x;
    std::tie(std::ignore, x) = seg.product(in[v], in[w]);

    return x;
}

