void bfs(int s) {
	queue<int> q;
	q.push(s);
	vis[s] = true;
	while(!q.empty()) {
		s = q.front();
		q.pop();
		for(auto i : adj[s]) {
			if(!vis[i]) {
				vis[i] = true;
				dis[i] = dis[s] + 1;
				par[i] = s;
				q.push(i);
			}
		}
	}
}

void findDepth(int r) {
	if(adj[r].size() == 0) {
		depth[r] = 1;
		return;
	}
	for(auto j : adj[r]) {
		findDepth(j);
		depth[r] = max(depth[r], depth[j]);
	}
	depth[r]++;
}

