    if (graph[u].size() == 1 && graph[u][0] == v) {
        cout << 0 << '\n';
        return;
    }
    vector<int> T(N, -1), S(N, -1);

    queue<P> que;
    que.push({v, 0});
    S[v] = 0;
    while (!que.empty()) {
        P p = que.front();
        que.pop();
        for (int to : graph[p.first]) {
            if (S[to] == -1) {
                S[to] = p.second + 1;
                que.push({to, S[to]});
            }
        }
    }

    que.push({u, 0});
    T[u] = 0;
    while (!que.empty()) {
        P p = que.front();
        que.pop();
        for (int to : graph[p.first]) {
            if (T[to] == -1) {
                T[to] = p.second + 1;
                que.push({to, T[to]});
            }
        }
    }
    int ans = 0;
    rep(i, N) {
        if (S[i] > T[i]) {
            ans = max(ans, T[i]);
        }
    }
    if (ans == 0) {
        ans ++;
    }
    cout << ans << '\n';
}

