vector<lpair> bfs(int start) {
	vector<lpair> ret(N, lpair(inf<int>, inf<int>));
	ret[start - 1] = lpair(0, start);
	queue<int> que;
	que.push(start);
	while (que.size()) {
		int now = que.front();
		que.pop();

		for (auto &edge: edges[now]) {
			if (ret[edge - 1].first > ret[now - 1].first + 1) {
				ret[edge - 1] = lpair(ret[now - 1].first + 1, edge);
				que.push(edge);
			}
		}
	}

	return ret;
}

int bfs2(int start, vector<int> &bad) {
	int ret = 0;

	vector<lpair> dis(N, lpair(inf<int>, inf<int>));
	dis[start - 1] = lpair(0, start);
	queue<int> que;
	que.push(start);
	while (que.size()) {
		int now = que.front();
		que.pop();
		ret = dis[now - 1].first;
		if (bad[now - 1] == 2) continue;

		for (auto &edge: edges[now]) {
			if (bad[edge - 1] == 1) continue;
			if (dis[edge - 1].first > dis[now - 1].first + 1) {
				dis[edge - 1] = lpair(dis[now - 1].first + 1, edge);
				que.push(edge);
			}
		}
	}

	return ret;
}

