	auto tkhs = bfs(u);
	auto aok = bfs(v);
	vector<lpair> dis(N);
	for (int i = 0; i < N; ++i) {
		dis[i] = lpair(aok[i].first - tkhs[i].first, i + 1);
	}
	sort(ALL(dis));

	int ret = 0;
	vector<int> bad(N);
	for (int i = 0; i < N; ++i) {
		if (dis[i].first < 0) {
			bad[dis[i].second - 1] = 1;
		}
		else if (dis[i].first == 0) {
			bad[dis[i].second - 1] = 2;
		}
		else {
			int last = (--upper_bound(ALL(dis), lpair(dis[i].first, inf<int>))) - dis.begin();
			for (int j = i; j <= last; ++j) {
				ret = max(ret, (dis[j].first - 1)/2*2 + bfs2(dis[j].second, bad));
