		add_edge(g,a,b,1,true,1);
	}
	Array d;
	Dijkstra(g,v,d);

	Array dt;
	Dijkstra(g,u,dt);

	ll ans=0;

	REP(i,n){
		if(d[i]>=dt[i]){
			if(d[i]%2==dt[i]%2){
				chmax(ans,d[i]);
			}else{
				chmax(ans,d[i]+1);	
			}
		}

	}

	cout<<ans<<endl;

	return 0;
}

