void init(int V){
    dfs(root,-1,0);
    for(int k=0;k+1<14;k++){
        for(int v=0;v<V;v++){
            if(parent[k][v]<0)parent[k+1][v]=-1;
            else parent[k+1][v]=parent[k][parent[k][v]];
        }
    }
}

int lca(int u,int v){
    if(depth[u]>depth[v]) swap(u,v);
    rep(k,14){
        if(depth[v]-depth[u]>>k&1){
            v=parent[k][v];
        }
    }
    if(u==v) return u;
    for(int k=13;k>=0;k--){
        if(parent[k][u] != parent[k][v]){
            u = parent[k][u];
            v = parent[k][v];
        }
    }
    return parent[0][u];
}


