template<typename T> struct SegTree{
    using F=function<T(T, T)>;
    int sz=1;
    T et;
    F f, g;
    vector<T> node;

    SegTree(int sz_, T et_, F f_, F g_): et(et_), f(f_), g(g_){
        while(sz<sz_) sz<<=1;
        node.resize(sz<<1, et);
    }

    void update(int i, T x){
        i+=sz;
        node[i]=g(node[i], x);
        i>>=1;
        while(i){
            node[i]=f(node[i<<1], node[(i<<1)+1]);
            i>>=1;
        }
    }

    T query(int l, int r){
        T vl=et, vr=et;
        for(l+=sz, r+=sz; l<r; l>>=1, r>>=1){
            if(l&1) vl=f(vl, node[l++]);
            if(r&1) vr=f(node[--r], vr);
        }
        return f(vl, vr);
    }
};

vector<int> vs, idx, dep, G[MAX];

void lca_dfs(int v, int pv, int &i, int d){
    vs.push_back(v);
    dep.push_back(d);
    if(idx[v]<0) idx[v]=i++;
    for(int nv: G[v])if(nv!=pv){
        lca_dfs(nv, v, i, d+1);
        vs.push_back(v);
        dep.push_back(d);
        ++i;
    }
}

int getlca(int u, int v, SegTree<pii> &st){
    int x=min(idx[u], idx[v]);
    int y=max(idx[u], idx[v]);
    return vs[st.query(x, y+1).se];
}

