using Edges = vector<Edge>;
using Graph = vector<Edges>;


struct LCA{
    static const int LOGN=20;
    array<vector<int>,LOGN+1> par;
    vector<int> dep;
    void dfs(int v,int pre,Graph& g){
        for(auto& e:g[v]){
            if(e.to==pre) continue;
            par[0][e.to]=v;
            dep[e.to]=dep[v]+1;
            dfs(e.to,v,g);
        }
    }

    LCA(Graph& g,int root):dep(g.size()){
        int n=g.size();
        for(int i=0;i<=LOGN;i++) par[i].assign(n,-1);
        dep[root]=0;
        par[0][root]=root;
        dfs(root,-1,g);
        for(int i=0;i<LOGN;i++){
            for(int j=0;j<n;j++){
                par[i+1][j]=par[i][par[i][j]];
            }
        }
    }

    int query(int u,int v){
        if(dep[u]<dep[v]) swap(u,v);
        int d = dep[u]-dep[v];
        for(int i=LOGN;i>=0;i--){
            if((d>>i)&1){
                u = par[i][u];
                d-=(1<<i);
            }
        }
        if(u==v) return u;
        for(int i=LOGN;i>=0;i--){
            if(par[i][u]!=par[i][v]) u=par[i][u],v=par[i][v];
        }
        return par[0][u];
    }
};

const cost_t INF=1e9+9; // must edit this
void dijkstra(int s,Graph& g,vector<cost_t>& d){
    int n=g.size();
    d.assign(n,INF);
    d[s]=0;
    using Item=pair<cost_t,int>;
    priority_queue<Item,vector<Item>,greater<Item>> que;
    que.push(Item(0,s));
    while(!que.empty()){
        auto tmp=que.top(); que.pop();
        int v=tmp.second;
        if(d[v]<tmp.first) continue;
        for(auto &e:g[v]){
            if(d[v]+e.cost<d[e.to]){
                d[e.to]=d[v]+e.cost;
                que.push(Item(d[e.to],e.to));
            }
        }
    }
}

void dfs(int now, int prev, const Graph &tr, Graph &tr2) {
  for(int i=0;i<SZ(tr[now]);++i) {
    int nxt = tr[now][i].to;
    if(nxt == prev) continue;
    tr2[now].push_back(Edge(now, nxt, 1));
    dfs(nxt, now, tr, tr2);
  }
}

