    int ans=0;
    for(int i=1;i<=n;i++)
    {
        int lca=LCA(u,i);
        if(DIS(u,lca)>=DIS(u,v)/2+DIS(u,v)%2) continue;
        ans=max(ans,DIS(v,i)-1);
    }
    cout<<ans;
}

