        is_leaf[i] = deg[i] == 1 && i != v;
    }

    vector<ll> dp(n, -1), dq(n, -1);
    {
        deque<ll> q = {v}; dp[v] = 0;
        while (q.size()) {
            ll i = q.front(); q.pop_front();
            for (ll j : g[i]) {
                if (dp[j] == -1) {
                    dp[j] = dp[i] + 1;
                    q.push_back(j);
                }
            }
        }
    }
    {
        deque<ll> q = {u}; dq[u] = 0;
        while (q.size()) {
            ll i = q.front(); q.pop_front();
            if (dp[i] <= dq[i]) continue; // dead
            for (ll j : g[i]) {
                if (dq[j] == -1 && dq[i] + 1 <= dp[j]) {
                    dq[j] = dq[i] + 1;
                    q.push_back(j);
                }
            }
        }
    }

    DUMPALL(dp);
    DUMPALL(dq);

    ll ans = 0;
    REP(i, n) if (dq[i] != -1) {
        chmax(ans, dp[i] - is_leaf[i]);
    }
    say(ans);

}

