int st,e;

void bfs(int s,vector <int> &dist){
    queue <int> q;
    q.push(s);
    dist[s]=0;
    while(!q.empty()){
        s=q.front();
        q.pop();
        for(int x:adj[s]){
            if(dist[x]!=-1||x==st||x==e)
                continue;
            dist[x]=1+dist[s];
            q.push(x);
        }
    }
}

void solve(){
    int n;
    cin>>n>>st>>e;
    for(int i=1;i<n;i++){
        int u,v;
        cin>>u>>v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector <int> a(n+1,-1),b(n+1,-1);
    bfs(st,a);
    bfs(e,b);
    int ans=0;
    for(int i=0;i<=n;i++){
       // cout<<a[i]<<" ";
        if(a[i]!=-1&&b[i]!=-1&&adj[i].size()==1&&i!=st&&i!=e&&a[i]!=b[i])
            ans=max(ans,min(a[i],b[i]));
    }
    cout<<ans;
}

signed main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	int t;
	//cin>>t;
	t=1;
	while(t--){
		solve();
	}
	return 0;
}

