const int MAXN = 123456;
vector<int> G[MAXN];
int dep[MAXN];
bool OK[MAXN];

void bfs(int cur, vector<int> &dis) {
    dis[cur] = 0;
    queue<int> qu;
    qu.push(cur);
    while (!qu.empty()) {
         int tp = qu.front();
         qu.pop();
         for (auto i : G[tp]) {
             if (!dis[i] && i != cur) {
                 qu.push(i);
                 dis[i] = dis[tp] + 1;
             }
         }
    }
}

int dfs(int cur, int par) {
    int ans = 0;
    for (int i : G[cur]) {
        if (i != par) {
            ans = max(dfs(i, cur), ans);
        }
    }
    return dep[cur] = ans;
}

int dfs2(int cur, int par, int tg) {
    if (cur == tg) return OK[cur] = true;
    for (int i : G[cur]) {
        if (i == par) continue;
        if (dfs2(i, cur, tg)) return OK[cur] = true;
    }
    return false;
}

int main() {
    int N, u, v;
    scanf("%d %d %d", &N, &u, &v);
    u--, v--;
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        a--;
        b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    vector<int> disu(N, 0), disv(N, 0);
    bfs(u, disu);
    bfs(v, disv);
    dfs(v, v);
    dfs2(v, v, u);
    int ans = 0;
    for (int i = 0; i < N; i++) {
        if (disu[i] > disv[i]) continue;
        if (disu[i] == disv[i] && OK[i])
            ans = max(ans, disu[i]);
        else if (disu[i] < disv[i])
            ans = max(ans, disv[i] + dep[i] - 1);
    }
    printf("%d\n", ans);
    return 0;
}

