template<typename T> class graph {
public :
    vector<vector<edge<T>>> g;
    vector<edge<T>> edges;
    int n;
    explicit graph(int n) : n(n) { g.resize(n); }
    void clear() { g.clear(), edges.clear(); }
    void resize(int n) {this->n = n;g.resize(n);}
    int size() { return n; }
