using Weight = int;
struct Edge {
  int src, dst;
  Weight weight;
  Edge(void) {}
  Edge(int src, int dst) : src(src), dst(dst) {}
  Edge(int src, int dst, Weight weight) : src(src), dst(dst), weight(weight) {}
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

void edges_to_graph(Graph &graph, const Edges &edges, const int vertices, const bool directed = true) {
  graph.clear(), graph.resize(vertices);
  for (const auto &e : edges) graph[e.src].emplace_back(e);
  if (!directed) for (const auto &e : edges) graph[e.dst].emplace_back(Edge(e.dst, e.src, e.weight));
}

void dfs(Graph &g, int v, int p, int u, vector<int> &route, bool &goal) {
  route.push_back(v);
  if (v == u) {
    goal = true;
    return;
  }
  for (const auto &e : g[v]) {
    if (e.dst == p) continue;
    dfs(g, e.dst, v, u, route, goal);
    if (goal) return;
  }
  route.pop_back();
}

void dfs2(Graph &g, int v, int p, int cnt, int &maxi) {
  maxi = max(maxi, cnt);
  for (const auto &e : g[v]) {
    if (e.dst == p) continue;
    dfs2(g, e.dst, v, cnt + 1, maxi);
  }
}

