	ll sr=sz(path)/2;
	if(sz(path)%2==1)
		sr++;
	ll ans=sz(path)-1-sz(path)/2;
	for(i=sr;i<sz(path);i++)
	{
		x=sz(path)-1-i;
		ans=max(ans,dp[path[i]]+x);
	}

	cout<<ans<<endl;
}

