const int N = 1e5 + 5;
bool pres[N];
int deg[N], par[N], taka[N], aka[N];

void dfs1(int ii, int pp, graph &g)
{
	par[ii] = pp;
	bool ans = false;
	for (auto jj : g[ii])
		if (jj != pp)
			dfs1(jj, ii, g);
	for (auto jj : g[ii])
		if (jj != pp)
			pres[ii] |= pres[jj];
	return;
}

void dfs2(int ii, int pp, graph &g, int h, int block, int *arr)
{
	arr[ii] = h;
	pres[ii] = true;
	for (auto jj : g[ii])
		if (jj != pp && jj != block)
			dfs2(jj, ii, g, h + 1, block, arr);
	return;
}

void solve()
{
	int n, t, a;
	cin >> n >> t >> a;
	graph g(n + 1, v32());
	int u, v;
	for (int i = 0; i < n - 1; i++)
	{
		cin >> u >> v;
		g[u].push_back(v);
		g[v].push_back(u);
		deg[u]++;
		deg[v]++;
	}
	pres[t] = true;
	dfs1(a, -1, g);
	if (deg[t] == 1 && par[t] == a)
	{
		cout << 0 << ln;
		return;
	}
	int src = -1;
	for (auto jj : g[a])
		if (pres[jj])
		{
			src = jj;
			break;
		}
	dfs2(t, -1, g, 0, a, taka);
	dfs2(src, a, g, 1, a, aka);
	aka[a] = 0;
	int ans = 0;
	for (int i = 1; i < n + 1; i++)
		if (pres[i] && deg[i] && taka[i] < aka[i])
			ans = max(ans, aka[i]);
	cout << ans-1 << ln;
	return;
}

