  vector<int> depths(N);
  for (int i = 0; i < N - 1; ++i) {
    int A, B;
    cin >> A >> B;
    --A;
    --B;
    g[A].push_back(B);
    g[B].push_back(A);
  }

  { // BFS
    queue<int> q;
    parents[v] = -1;
    depths[v] = 0;
    q.push(v);
    while (not q.empty()) {
      int x = q.front();
      q.pop();
      for (auto y : g[x]) {
	if (y == parents[x]) continue;
	parents[y] = x;
	depths[y] = depths[x] + 1;
	q.push(y);
      }
    }
  }

  int start = -1;
  { // set start
    int nsteps = (depths[u] - 1) / 2;
    int x = u;
    for (int i = 0; i < nsteps; ++i) {
      x = parents[x];
    }
    start = x;
  }

  int max_dist = 0;
  {
    queue<int> q;
    vector<int> dists(N, -1);
    dists[start] = 0;
    q.push(start);
    while (not q.empty()) {
      int x = q.front();
      q.pop();
      for (auto y : g[x]) {
  	if (y == parents[x]) continue;
  	dists[y] = dists[x] + 1;
  	max_dist = max(max_dist, dists[y]);
  	q.push(y);
      }
    }
  }

  cout << depths[start] + max_dist - 1 << endl;

  return 0;
}

