    queue<P> que;
    que.push(P(a,0));
    dp[a] = 0;
    while(!que.empty()){
        P p = que.front();
        que.pop();
        for(auto i:G[p.first]){
            if(dp[i]>p.second+1){
                que.push(P(i,p.second+1));
                dp[i] = p.second+1;
            }
        }
    }
    // 高橋くんからBFSして到達可能な頂点のうち青木くんの距離が最も遠いもの
    que.push(P(t,0));
    vector<int> dpt(n + 10, 1e9);
    dpt[t] = 0;
    int ans = dp[t];
    while(!que.empty()){
        P p = que.front();
        que.pop();
        for(auto i:G[p.first]){
            if(dp[i]<=p.second+1 ){
                continue;
            }
            else if(dpt[i]>p.second+1){
                ans = max(ans,dp[i]);
                dpt[i] = p.second+1;
                que.push(P(i,p.second+1));
            }
        }
    }
    cout << ans-1 << endl;
    return 0;
}

