// uからの帰りならtrueを返す
bool dfs1(int pos) {
  visited[pos] = true;
  bool res = (pos == u);
  rep(i, G[pos].size()) {
    int to = G[pos][i];
    if (visited[to]) continue;
    if (dfs1(to)) res = true;
  }
  return via[pos] = res;
}

int dist[N], jct[N]; // vからの距離, v-uの最短ルートからの分岐点

void dfs2(int pos) {
  rep(i, G[pos].size()) {
