void search(int curr, int prev, int ter) {
    x[curr] = x[prev]+1;
    if (curr == ter) return;
    for (auto &to: e[curr]) {
        if (to != prev) {
            search(to, curr, ter);
        }
    }
}

void search2(int curr, int prev, int u) {
    if (prev != 0) {
        if (x[prev] > x[curr]) y[curr] = y[prev] - 1;
        else y[curr] = y[prev] + 1;
    }
    if (y[curr] <= 0 || x[curr] <= x[u] / 2) return;
    for (auto &to: e[curr]) {
        if (to != prev) {
            search2(to, curr, u);
        }
    }
}

