using namespace std;

int n;
vector<vector<int>> adj;

namespace LCA {

int l, timer;
vector<int> tin, tout;
vector<vector<int>> up;

void dfs(int v, int p) {
    tin[v] = ++timer;
    up[v][0] = p;
    for (int i = 1; i <= l; ++i) up[v][i] = up[up[v][i - 1]][i - 1];

    for (int u : adj[v]) {
        if (u != p) dfs(u, v);
    }

    tout[v] = ++timer;
}

bool is_ancestor(int u, int v) {
    return tin[u] <= tin[v] && tout[u] >= tout[v];
}

void preprocess(int root) {
    tin.resize(n);
    tout.resize(n);
    timer = 0;
    l = ceil(log2(n));
    up.assign(n, vector<int>(l + 1));
    dfs(root, root);
}

}  // namespace LCA

namespace Depth {
vector<int> d;

int dfs(int u, int p) {
    for (int v : adj[u]) {
        if (v == p) continue;
        d[u] = max(d[u], 1 + dfs(v, u));
    }
    return d[u];
}

void preprocess(int root) {
    d.resize(n);
    dfs(root, root);
}

}  // namespace Depth

int main() {
    cin.tie(NULL);
    ios_base::sync_with_stdio(false);

    int a, b;
    cin >> n >> b >> a;
    a--, b--;

    adj.resize(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    LCA::preprocess(a);
    Depth::preprocess(a);

    int cnt = 0;
    bool aoki = false;
    while (a != b) {
        if (not aoki) {
            int p = LCA::up[b][0];
            bool go_up = a != p and LCA::up[p][0] != a;
            bool is_leaf = Depth::d[b] == 0;

            if (is_leaf or go_up) {
                b = p;
            } else {  // pick the deepest child to go to
                int u = -1;
                for (int v : adj[b]) {
                    if (Depth::d[v] > Depth::d[b]) continue;
                    if (u == -1 or Depth::d[v] > Depth::d[u]) u = v;
                }
                b = u;
            }

        } else {
            cnt++;
            for (int v : adj[a]) {
                if (Depth::d[v] > Depth::d[a]) continue;
                if (LCA::is_ancestor(v, b)) {
                    a = v;
                    break;
                }
            }
        }

        aoki ^= 1;
    }

    cout << cnt << '\n';
}

