    q.push({s, 0});
    res[s] = 0;
    while(!q.empty()){
        int now = q.front().first;
        int nowdist = q.front().second;
        q.pop();
        rep(i, g[now].size()){
            int next = g[now][i];
            int nextdist = nowdist + 1;
            if(res[next] != -1) continue;
            res[next] = nextdist;
            q.push({next, nextdist});
        }
    }

    return res;
}

int solve(int s, vector<vector<int>> &g, vector<int> &adist, int &a){
