{
    int INF = INT32_MAX;
    vector<int> cost(N, INF);

    cost[s] = 0;
    queue<int> pos_queue;
    pos_queue.push(s);

    while (pos_queue.size())
    {
        int pos = pos_queue.front();
        pos_queue.pop();
        rep(i, edge[pos].size())
        {
            int next = edge[pos][i];
            if (cost[next] == INF)
            {
                cost[next] = cost[pos] + 1;
                pos_queue.push(next);
