    queue<tuple<int, int, int>> q;
    vector<int> depth(N, 0), part_depth(N, 0);
    q.push(make_tuple(v, -1, 0));
    while(q.size()) {
        int cur, prev, d;
        tie(cur, prev, d) = q.front(); q.pop();
        depth[cur] = d;
        if(prev >= 0) edge[cur].erase(prev);
        for(int nxt : edge[cur]) {
            q.push(make_tuple(nxt, cur, d + 1));
        }
    }
    // u - v 間頂点探す
    {
        vector<bool> used(N, false);
        stack<pair<int, int>> st, tmp;
        st.push({v, -1});
        while(st.size()) {
            int cur, prev;
            tie(cur, prev) = st.top();
            if(used[cur]) {
                st.pop();
                if(prev >= 0)
                    part_depth[prev] = max(part_depth[prev], part_depth[cur] + 1);
                continue;
            }
            for(int nxt : edge[cur]) {
                st.push({nxt, cur});
            }
            used[cur] = true;
        }
    }

    recursive(v, u);
    s_uv.insert(v);

    int ans = 0;
    int D = depth[u] - depth[v];

    for(int w : s_uv) {
        if(u == w) continue;
        int d_u = depth[u] - depth[w];
        int d_v = depth[w] - depth[v];
        int d = part_depth[w];
        int cand = 0;
        if(d_u >= d_v) cand = (d_u + d_v) / 2;
        else {
            cand = d_v + d - 1;
        }
        ans = max(ans, cand);
    }
    cout << ans << endl;
    return 0;    
}

