  }
  visited[u] = 1;
  long queue[n];
  queue[0] = u;
  long start = 0, end = 0, tail = 0;
  long cur,next;
  while (tail < n-1) {
    for (long i = start; i <= end; i++) {
      cur = queue[i];
      for (long j = 0; j < tree_s[cur]; j++) {
        next = tree[cur][j];
        if (visited[next] == 1) {
          continue;
        }
        visited[next] = 1;
        depth_u[next] = depth_u[cur]+1;
        tail++;
        queue[tail] = next;
      }
