int N;
int u, v;
int edgeNums[114514];
int* edges[114514];

int highBridge[114514], blueTree[114514];

void dfs_a(int node, int parent, int current) {
	int i;
	blueTree[node] = current;
	for (i = 0; i < edgeNums[node]; i++) {
		if (edges[node][i] != parent) {
			dfs_a(edges[node][i], node, current + 1);
		}
	}
}

void dfs_t(int node, int parent, int current) {
	int i;
	if (current > blueTree[node]) return;
	highBridge[node] = current + 1;
	if (current >= blueTree[node]) return;
	for (i = 0; i < edgeNums[node]; i++) {
		if (edges[node][i] != parent) {
			dfs_t(edges[node][i], node, current + 1);
		}
	}
}

int main(void) {
	int i;
	int answer = 0;
	if (scanf("%d%d%d", &N, &u, &v) != 3) return 1;
	for (i = 1; i < N; i++) {
		int A, B;
		if (scanf("%d%d", &A, &B) != 2) return 1;
		addEdge(&edgeNums[A], &edges[A], B);
		addEdge(&edgeNums[B], &edges[B], A);
	}
	dfs_a(v, 0, 0);
	dfs_t(u, 0, 0);
	for (i = 1; i <= N; i++) {
		/* そこで捕まる可能性があるかを判定 */
		if (highBridge[i] > 0) {
			if (answer < blueTree[i] - 1) answer = blueTree[i] - 1;
		}
	}
	printf("%d\n", answer);
	return 0;
}

