int a[100001],b[100001],edgenum[100001],data[200001],parent[100001],
    depth[100001],vdepth[100001];
int *con[100001];


void find_next_node(int currentnode, int currentdepth){
    int k,curedgenum,nextnode;
    //printf("find_next_node(%d,%d)\n",currentnode,currentdepth);
    curedgenum=edgenum[currentnode];
    if(currentdepth>n){
        printf("Error: depth=%d\n",currentdepth);
        return;
    };
    for(k=0;k<curedgenum;k++){
        nextnode=con[currentnode][k];
        if(nextnode!=parent[currentnode]){
            parent[nextnode]=currentnode;
            depth[nextnode]=currentdepth+1;
            find_next_node(nextnode,currentdepth+1);
        };
    };
};    

void make_connection_list(void){
    int i,k;
    int edgefound[100001];
    for(i=0;i<n;i++){
        edgenum[i]=edgefound[i]=0;
    };
    for(i=0;i<n-1;i++){
        edgenum[a[i]]++;
        edgenum[b[i]]++;
    };
    con[0]=data;
    for(i=1;i<n;i++){
        con[i]=con[i-1]+edgenum[i-1];
    };
    for(i=0;i<n-1;i++){
        con[a[i]][edgefound[a[i]]]=b[i];
        edgefound[a[i]]++;
        con[b[i]][edgefound[b[i]]]=a[i];
        edgefound[b[i]]++;
    };
