template<typename G>
struct DLCA{
    const int Log;
    vector<int> dep;
    const G &g;
    vector<vector<int>> table;
    explicit DLCA(const G &g):g(g),dep(g.size()),Log(32-__builtin_clz(g.size())){
        table.assign(Log,vector<int>(g.size(),-1));
    }
    //各点に番号付
    void dfs(int idx,int par,int d){
        table[0][idx]=par;
        dep[idx]=d;
        for(auto &to:g[idx]){
            if(to!=par)dfs(to,idx,d+1);
        }
    }
    //構築
    void build(){
        dfs(0,-1,0);
        for(int k=0;k<Log-1;k++){
           for(int i=0;i<table[k].size();i++){
               if(table[k][i]==-1)table[k+1][i]=-1;
               else table[k+1][i]=table[k][table[k][i]];
           }
        }
    }
    //２点の最小共通祖先を探す
    int query(int u,int v){
       if(dep[u]>dep[v])swap(u,v);
       for(int i=Log-1;i>=0;i--){
           if(dep[v]-dep[u]&(1<<i))v=table[i][v];
       }
       if(u==v)return u;
       for(int i=Log-1;i>=0;i--){
           if(table[i][u]!=table[i][v]){
               u=table[i][u];
               v=table[i][v];
           }
       }
       return table[0][u];
    }
    //２点間距離
    int dist(int u,int v){
        int par=query(u,v);
        return abs(dep[u]-dep[par])+abs(dep[v]-dep[par]);
    }
};
int main(){
  int n,u,v;
  cin>>n>>u>>v;
  u--;v--;
  V<V<int>> g(n);
  for(int i=0;i<n-1;i++){
      int a,b;
      cin>>a>>b;
      a--;b--;
      g[a].push_back(b);
      g[b].push_back(a);
  }
  DLCA<V<V<int>>> t(g);
  t.build();
  int l,r,par=t.query(u,v),c;int dispar=t.dist(u,par),ans=t.dist(v,par)-1;
  for(int i=0;i<n;i++){
      l=t.dist(u,i),r=t.dist(i,v),c=t.dist(par,i);
      if(dispar+c==l)continue;
      if(l<r){
          chmax(ans,r-1);
      }
  }
  cout<<ans<<"\n";
}

