int f(int now, int from, int k){
	if(now==v){return 1;}
	if(el[now]==1 && e[now][0]==from) return 0;
	for(int i=0; i<el[now]; i++){
		int to=e[now][i];
		if(to!=from){
			int v=f(to, now, k+1);
			if(v>0){
				if(v<=k){
					p[now]=true;
					u=from;
				}
				return v+1;
			}
		}
	}
	return 0;
}

int g(int now, int from){
	if(p[now]) return 0;
	p[now]=true;
	if(el[now]==1 && e[now][0]==from) return 1;
	int ans=0;
	for(int i=0; i<el[now]; i++){
		int to=e[now][i];
		if(to!=from){
			int pos=g(to, now);
			if(pos>ans) ans=pos;
		}
	}
	return ans+1;
}

