fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val t = sc.nextInt() - 1
    val a = sc.nextInt() - 1
    val adj = Array(n) { mutableSetOf<Int>() }
    for (i in 0 until n - 1) {
        val u = sc.nextInt() - 1
        val v = sc.nextInt() - 1
        adj[u].add(v)
        adj[v].add(u)
    }
    val dist_a = Array(n) { 0 }
    val dist_t = Array(n) { 0 }
    val que:Queue<Pair<Int,Int>> = ArrayDeque()
    val visited = BitSet(n)
    visited[t] = true
    que.add(t to 0)
    while (que.count() > 0) {
        val (v, step) = que.poll()
        dist_t[v] = step
        for (w in adj[v]) {
            if (!visited[w]) {
                visited[w] = true
                que.add(w to step + 1)
            }
        }
    }
    que.clear()
    visited.clear()
    visited[a] = true
    que.add(a to 0)
    while (que.count() > 0) {
        val (v, step) = que.poll()
        dist_a[v] = step
        for (w in adj[v]) {
            if (!visited[w]) {
                visited[w] = true
                que.add(w to step + 1)
            }
        }
    }
    var ans = 0
    for (i in 0 until n) {
        if (dist_a[i] <= dist_t[i]) continue
        ans = maxOf(ans, dist_a[i] - 1)
    }
    println(ans)
}

fun main() {
    val writer = PrintWriter(System.out, false)
    writer.solve(FastScanner(System.`in`))
    writer.flush()
}

class FastScanner(s: InputStream) {
    private var st = StringTokenizer("")
    private val br = BufferedReader(InputStreamReader(s))

    fun next(): String {
        while (!st.hasMoreTokens()) st = StringTokenizer(br.readLine())

        return st.nextToken()
    }

    fun nextInt() = next().toInt()
    fun nextLong() = next().toLong()
    fun nextLine() = br.readLine()
    fun nextDouble() = next().toDouble()
    fun ready() = br.ready()
}

