fun solve() {
    val (n, takahashi, aoki) = nextIntList()
    val nodes = Array(n) { Node(it) }
    repeat(n - 1){
        val (a, b) = nextIntList()
        nodes[a - 1].edges.add(Edge(a - 1, b - 1, 1))
        nodes[b - 1].edges.add(Edge(b - 1, a - 1, 1))
    }

    val tdist = bfs(nodes, takahashi - 1)
    val adist = bfs(nodes, aoki - 1)

    var ans = 0L
    for (i in 0 until n){
        val t = tdist[i]
        val a = adist[i]
        if(t >= a) continue
        val res = a - 1
        ans = max(ans, res)
    }

    println(ans)

}

fun bfs(nodes: Array<Node>, start: Int) : Array<Long> {
    val queue = ArrayDeque<Int>()
    queue.add(start)
    val dist: Array<Long> = Array(nodes.size) { -1L }
    dist[start] = 0
    while(queue.isNotEmpty()){
        val now = queue.poll()
        for (edge in nodes[now].edges) {
            if(dist[edge.to] != -1L) continue
            dist[edge.to] = dist[now] + 1
            queue.add(edge.to)
        }
    }
    return dist
}

