    int[] ud;
    int[] vd;

    public void solve() {
        int n = in.nextInt();
        int u = in.nextInt() - 1;
        int v = in.nextInt() - 1;

        g = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i < n - 1; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            g[a].add(b);
            g[b].add(a);
        }

        vd = new int[n];
        dfs(v, -1, 0);

        ud = new int[n];
        Arrays.fill(ud, -1);
        dfs2(u, -1, 0);

        int res = 0;
        for (int i = 0; i < n; i++) {
            if (ud[i] != -1) {
                res = Math.max(res, vd[i] - 1);
            }
        }
        System.out.println(res);
    }

    private void dfs2(int u, int pre, int dep) {
        ud[u] = dep;
        if (dep == vd[u]) return;

        for (int v : g[u]) {
            if (v == pre || vd[v] < dep + 1) continue;

            dfs2(v, u, dep + 1);
        }
    }

    private void dfs(int u, int pre, int dep) {
        vd[u] = dep;
        for (int v : g[u]) {
            if (v == pre) continue;

            dfs(v, u, dep + 1);
        }
    }

