    int t;
    List<Integer>[] adj;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        n = in.nextInt();
        s = in.nextInt() - 1;
        t = in.nextInt() - 1;
        adj = new List[n];
        for (int i = 0; i < n; i++) {
           adj[i] = new ArrayList();
        }
        for (int i = 0; i < n - 1; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            adj[a].add(b);
            adj[b].add(a);
        }
        dist = new int[n];
        far = -1;
        findDist(t, -1, 0);
        findFar(s, -1, 0);
        out.println(end == -1 ? 0 : dist[end]);
    }

    private void findFar(int u, int p, int d) {
        if (d > far) {
            far = d;
            end = p;
        }
        for (int v : adj[u]) {
            if (v == p || d > dist[v] || v == t) continue;
            findFar(v, u, d + 1);
        }
    }

    int end;
    int far;
    int[] dist;

    private void findDist(int u, int p, int d) {
        dist[u] = d;
        for (int v : adj[u]) {
            if (v == p) continue;
            findDist(v, u, d + 1);
        }
    }

}

