class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static int inf = 0xfffffff;

    void solve() {
        int n = in.nextInt();
        int u = in.nextInt() - 1; // 逃げる
        int v = in.nextInt() - 1; // 追う
        List<List<Integer>> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            edges.add(new ArrayList<>());
        }
        for (int i = 1; i < n; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            edges.get(a).add(b);
            edges.get(b).add(a);
        }
        int[] du = dfs(edges, u);
        int[] dv = dfs(edges, v);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (edges.get(i).size() >= 2) {
                continue;
            }
            if (du[i] < dv[i]) {
                ans = Math.max(ans, dv[i] - 1);
            }
        }
        out.println(ans);
    }

    static int[] dfs(List<List<Integer>> edges, int start) {
        Deque<Integer> deque = new ArrayDeque<>();
        deque.addFirst(start);
        int n = edges.size();
        int[] dist = new int[n];
        Arrays.fill(dist, inf);
        dist[start] = 0;
        while (!deque.isEmpty()) {
            int v = deque.pollLast();
            for (Integer u : edges.get(v)) {
                if (dist[u] == inf) {
                    dist[u] = dist[v] + 1;
                    deque.addFirst(u);
                }
            }
        }
        return dist;
    }

