public class Main {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int n = scanner.nextInt();
		int u = scanner.nextInt() - 1;
		int v = scanner.nextInt() - 1;
		List<Integer>[] adjacencyList = new List[n];
