class atc_graph{

	int n;
	ArrayList<ArrayList<Integer>> adj;

	atc_graph(int V){
		n=V;
		adj=new ArrayList<ArrayList<Integer>>();

		for(int p=0;p<n;p++) {
			adj.add(new ArrayList<Integer>());
		}
	}

	void add_edge(atc_graph g,int a,int b) {
		g.adj.get(a).add(b);
		g.adj.get(b).add(a);
	}

	void BFS(atc_graph g,int s,int[] visited,int[] dist,int[] parent) {

		LinkedList<Integer> q=new LinkedList<Integer>();

		q.add(s);

		visited[s]=1;
		dist[s]=1;

		while(!q.isEmpty()) {

			int v=q.poll();

			for(int w:g.adj.get(v)) {

				if(visited[w]==0) {

					visited[w]=1;
					dist[w]=dist[v]+1;
					parent[w]=v;

					q.add(w);

				}	
			}
		}
	}

	void DFS(atc_graph g,int[] max_depth,int s) {

		/* Depth First Search*/

		int inf=-1;				 
		int[] colour=new int[g.n];
		for(int i=0;i<g.n;i++) {
			colour[i]=inf;
		}

//		for(int j=0;j<g.n;j++) {
//			if(colour[j]==inf) {
				DFS_Visit(g,s,colour,max_depth,0);
//			}
//		}
	}

	int DFS_Visit(atc_graph g,int u,int[] colour,int[] max_depth,int depth) {

		int inf=-1;
		colour[u]=1;		 
		int maxi=depth;

		for(int v:g.adj.get(u)) {
			if(colour[v]==inf) {
				maxi=Math.max(maxi, DFS_Visit(g,v,colour,max_depth,depth+1));
			}
		}

		colour[u]=2;
		max_depth[u]=maxi-depth;
		return maxi;
	}


}



