    for (int i = 0; i < n - 1; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
    }
    int[][] g = packU(n, from, to);
    int[] dep1 = new int[n];
    int[] dep2 = new int[n];
    dfs(u, -1, g, 0, dep1);
    dfs(v, -1, g, 0, dep2);

    if (g[u].length == 1 && g[u][0] == v) {
      System.out.println(0);
    } else {
      int ret = 0;
      for (int i = 0; i < n; i++) {
        if (dep1[i] < dep2[i]) {
          ret = Math.max(ret, dep2[i] - 1);
        }
      }
      System.out.println(ret);
    }

  }

  private static void dfs(int n, int pre, int[][] g, int d, int[] dep) {
    dep[n] = d;
    for (int v : g[n]) {
      if (v == pre)
        continue;
      dfs(v, n, g, d + 1, dep);
    }
  }

  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

