	final long m = (long) 1e9 + 7;

	int[] depth;

	void dfs(int cur, int par, ArrayList<Integer>[] g) {
		for (int dst : g[cur]) {
			if (dst == par)
				continue;
			depth[dst] = depth[cur] + 1;
			dfs(dst, cur, g);
		}
	}

	int u, v;

	void run() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		u = sc.nextInt();// T
		v = sc.nextInt();// A
		--u;
		--v;
		int[] A = new int[N - 1];
		int[] B = new int[N - 1];
		ArrayList<Integer>[] g = new ArrayList[N];
		for (int i = 0; i < N; ++i)
			g[i] = new ArrayList<Integer>();
		for (int i = 0; i < N - 1; ++i) {
			A[i] = sc.nextInt();
			B[i] = sc.nextInt();
			--A[i];
			--B[i];
			g[A[i]].add(B[i]);
			g[B[i]].add(A[i]);
		}
		depth = new int[N];
		dfs(v, -1, g);
		ArrayDeque<long[]> dq = new ArrayDeque<>();
		dq.addLast(new long[] { u, 0, depth[u], 0, -1 });
		long ans = 0;
		while (!dq.isEmpty()) {
			long[] cur = dq.pollFirst();
			int curv = (int) cur[0];
			if (g[curv].size() == 1 && cur[3] == 1) {
				long diff = cur[2];
				if (diff % 2 == 0) {
					ans = Math.max(ans, cur[1] + diff - 1);
				} else {
					ans = Math.max(ans, cur[1] + diff - 1);
				}
				continue;
			}

			for (int dst : g[(int) cur[0]]) {
				if (depth[dst] > depth[(int) cur[0]]) {
					ans = Math.max(ans, cur[1] + 1);
					if (cur[3] == 0 && cur[4] == dst)
						continue;
					dq.addLast(new long[] { dst, cur[1] + 1, cur[2], 1, cur[0] });
				} else {
					if (cur[2] - 2 > 0) {
						if (cur[3] == 0 || g[(int) cur[0]].size() == 1) {
							dq.addLast(new long[] { dst, cur[1] + 1, cur[2] - 2, cur[3],
									(g[(int) cur[0]].size() == 1 ? -1 : cur[0]) });
						}
						ans = Math.max(ans, cur[1] + 1);
					} else if (cur[2] == 2) {
						ans = Math.max(ans, cur[1] + 1);
					}
				}
			}
		}
		System.out.println(ans);
	}

