    public Main(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int tStart = in.nextInt() - 1;
        int aStart = in.nextInt() - 1;

        List<Integer>[] adj = new List[n];
        for (int i = 0; i < n; i++)
            adj[i] = new ArrayList<>();

        for (int i = 0; i < n - 1; i++) {
            int u = in.nextInt() - 1;
            int v = in.nextInt() - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        if (tStart == aStart || (adj[tStart].size() == 1 && adj[tStart].get(0) == aStart))
            out.println(0);

        int[] distT = bfs(adj, tStart);
        int[] distA = bfs(adj, aStart);

        int res = 0;
        for (int i = 0; i < n; i++) {
            if (distT[i] <= distA[i]) {
                res = Math.max(res, distA[i] - 1);
            }
        }
        out.println(res);
    }

    private int[] bfs(List<Integer>[] adj, int start) {
        int[] dist = new int[adj.length]; // takashi distance
        Arrays.fill(dist, -1);
        dist[start] = 0;
        Queue<Integer> q = new ArrayDeque<>();
        q.add(start);
        while (!q.isEmpty()) {
            int u = q.remove();
            for (int v : adj[u]) {
                if (dist[v] >= 0) continue;
                dist[v] = dist[u] + 1;
                q.add(v);
            }
        }
        return dist;
    }

    private long gcd(long a, long b) {
        while (true) {
            if (b == 0) return a;
            long tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private int gcd(int a, int b) {
        while (true) {
            if (b == 0) return a;
            int tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private long powm(long x, long p) {
        long res = 1;
        while (p > 0) {
            if (p % 2 == 1)
                res = res * x % MOD;
            x = x * x % MOD;
            p /= 2;
        }
        return res;
    }

