	public static void dfsU(int now , int n) {
		List<Integer> edge = path[now];
		int nowDis = dis_u[now];
		for(int ed : edge) {
			if(dis_u[ed] < 0) {
				dis_u[ed] = nowDis + 1;
				dfsU(ed , n);
			}
		}
	}
	public static void dfsV(int now , int n) {
		List<Integer> edge = path[now];
		int nowDis = dis_v[now];
		for(int ed : edge) {
			if(dis_v[ed] < 0) {
				dis_v[ed] = nowDis + 1;
				dfsV(ed , n);
			}
		}
	}

