public class Main implements Runnable{

	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * ABC148 F問題
		 * 考察メモ
		 * 1. 青木くんは必ず高橋くんに近づくとして問題は無い
		 * 2. 高橋くんの移動できる範囲について考える
		 * まず、青木くんとの距離-1/2までは自由に動ける
		 * そのあとは、ひたすら逃げるだけになる
		 * よって、青木君との距離-1/2までに行ける頂点の中で、
		 * 最も遠い葉までの距離が一番遠い頂点にまず移動する
		 * 後はそこから葉まで移動するだけ
		 * つまり、高橋くん→xが青木くん→xより近ければ、そのxまで移動してから後はxと隣のマスを交互に踏めばいい
		 *
		 */
		int N = io.nextInt(), u = io.nextInt() - 1, v = io.nextInt() - 1;
		ArrayList<ArrayList<Integer>> tree = new ArrayList<>();
		for (int i = 0;i < N;++ i) tree.add(new ArrayList<>());
		for (int i = 1;i < N;++ i) {
			int A = io.nextInt() - 1, B = io.nextInt() - 1;
			tree.get(A).add(B);
			tree.get(B).add(A);
		}
		int[] distu = new int[N], distv = new int[N];
		bfs(distu, u, tree);
		bfs(distv, v, tree);
		int ans = 0;
		for (int i = 0;i < N;++ i) if (distu[i] < distv[i]) ans = Math.max(ans, distv[i] + distu[i] >> 1);
		io.println(ans);
	}

	private void bfs(int[] dist, int search, ArrayList<ArrayList<Integer>> tree) {
		int tmp = dist[search];
		dist[search] = -1;
		for (int i : tree.get(search)) {
			if (dist[i] == 0) {
				dist[i] = tmp + 1;
				bfs(dist, i, tree);
			}
		}
