						nodes[edge.target].add(edge.source, edge.cost);
					}
				}
			}

			void clearNodes() {
				for(Node n : nodes) { n.clear(); }
				for(Node n : reversedNodes) { n.clear(); }
			}
		}

		class Node {
			int id;
			ArrayList<Edge> edges = new ArrayList<Edge>();

			Node(int id) {
				this.id = id;
			}
			void add(int target, long cost) {
				edges.add(new Edge(id, target, cost));
			}
			void clear() {
				edges.clear();
			}
		}

		class Edge implements Comparable<Edge> {
			int source;
			int target;
			long cost;
			Edge(int source, int target, long cost) {
				this.source = source;
				this.target = target;
				this.cost = cost;
			}

			@Override
			public int compareTo(Edge e) {
				return Long.compare(this.cost, e.cost);
			}
		}

public void solve() {
	int numNode = ni();
	int start = ni() - 1;
	int goal = ni() - 1;
	int numEdge = numNode - 1;
	Edge edges[] = new Edge[numEdge];
	for(int i = 0; i < numEdge; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		long c = 1;
		edges[i] = new Edge(a, b, c);
	}
	Graph g = new Graph(numNode, numEdge, edges, false);
	long dist[] = dijkstra(g.nodes, start);
	int d = (int)dist[goal];
	// errprtln(d);
	int pass[] = new int[d + 1];
	pass[0] = goal;
	for(int i = 1; i <= d; i ++) {
		pass[i] = prev[pass[i - 1]];
	}
	reverse(pass);
	// errprtln(pass);
	long ans = (d - 1) / 2;
	goal = pass[d - (int)ans];
	start = pass[(int)ans];
	// errprtln(goal);
	int ng[] = {goal, goal};
	if(d % 2 == 0) { ng[1] = prev[goal]; }
	// errprtln(ng);
	long dist2[] = new long[numNode];
	fill(dist2, -INF);
	Deque<Integer> s = new ArrayDeque<>();
	s.add(start);
	dist2[start] = 0;
	while(!s.isEmpty()) {
		int crt = s.removeFirst();
		for(Edge e : g.nodes[crt].edges) {
			if(e.target == ng[0] || e.target == ng[1]) {
				continue;
			}
			if(isINF(dist2[e.target])) {
				dist2[e.target] = dist2[e.source] + 1;
				s.addLast(e.target);
			}
		}
	}
	// errprtln(dist2);
	ans += max(dist2);
	ans += d % 2 == 0 ? 1 : 0;
	prtln(ans);
}

int prev[];
long[] dijkstra(Node nodes[], int start) { // O((E+V)logV)
	long dist[] = new long[nodes.length];
	prev = new int[nodes.length];
	Arrays.fill(dist, INF);
	dist[start] = 0;

	Queue<Edge> q = new PriorityQueue<Edge>();
	q.add(new Edge(start, start, dist[start]));

	while(!q.isEmpty()) {
		Edge crt = q.poll();

		if(dist[crt.target] < crt.cost) { continue; }
		for(Edge e : nodes[crt.target].edges) {
			if(dist[e.target] > dist[e.source] + e.cost) {
				dist[e.target] = dist[e.source] + e.cost;
				q.add(new Edge(e.source, e.target, dist[e.target]));
				prev[e.target] = e.source;
			}
		}
	}

	return dist;
}

	}
}

