	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * ABC148 F問題
		 * 考察メモ
		 * 1. 青木くんは必ず高橋くんに近づくとして問題は無い
		 * 2. 高橋くんの移動できる範囲について考える
		 * まず、青木くんとの距離-1/2までは自由に動ける
		 * そのあとは、ひたすら逃げるだけになる
		 * よって、青木君との距離-1/2までに行ける頂点の中で、
		 * 最も遠い葉までの距離が一番遠い頂点にまず移動する
		 * 後はそこから葉まで移動するだけ
		 *
		 * 従って、各頂点について最も遠い葉(ただし青木くんが居ない側)までの距離が欲しい
		 * まず、青木くんから幅優先探索する
		 * 次に、この幅優先探索順に対して各木についてmax(子の葉からの距離)+1とする
		 * これで距離が分かりそう
		 * 再帰で書くかー
		 *
		 */
		int N = io.nextInt(), u = io.nextInt() - 1, v = io.nextInt() - 1;
		ArrayList<ArrayList<Integer>> tree = new ArrayList<>();
		for (int i = 0;i < N;++ i) tree.add(new ArrayList<>());
		for (int i = 1;i < N;++ i) {
			int A = io.nextInt() - 1, B = io.nextInt() - 1;
			tree.get(A).add(B);
			tree.get(B).add(A);
		}
		int[] leaf = new int[N], dist = new int[N], dist2 = new int[N];
		bfs(leaf, v, tree);
		bfs2(dist, u, tree);
		bfs2(dist2, v, tree);
		int ans = N + 1;
		for (int i = 0;i < N;++ i) if (dist[i] == dist2[i]) ans = Math.min(ans, dist[i]);
		if (ans > N) ans = 0;
		for (int i = 0;i < N;++ i) {
			if (dist[i] < dist2[i]) { // ここまで捕まらずに移動可能→後は葉に逃げる
				ans = Math.max(ans, dist[i] + leaf[i] + (dist2[i] - dist[i]) / 2);
			}
		}
		io.println(ans);
	}

	private int bfs(int[] dist, int search, ArrayList<ArrayList<Integer>> tree) {
		int max = 0;
		dist[search] = -1;
		for (int i : tree.get(search)) if (dist[i] == 0) max = Math.max(max, 1 + bfs(dist, i, tree));
		dist[search] = max;
		return max;
	}

	private void bfs2(int[] dist, int search, ArrayList<ArrayList<Integer>> tree) {
		int tmp = dist[search];
		dist[search] = -1;
		for (int i : tree.get(search)) {
			if (dist[i] == 0) {
				dist[i] = tmp + 1;
				bfs2(dist, i, tree);
			}
		}
		dist[search] = tmp;
	}

