    void solve() {
        int N = in.nextInt(), M = N-1;
        int t = in.nextInt()-1, a = in.nextInt()-1;
        ArrayList<ArrayList<Integer>> T = new ArrayList<>();
        for(int i = 0; i < N; i++) T.add(new ArrayList<>());
