import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) throws Exception {
        try (Scanner sc = new Scanner(System.in)) {
            int N = sc.nextInt();
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;

            List<Integer>[] edges = new List[N];
            for (int i = 0; i < N; i++) {
                edges[i] = new ArrayList<>();
            }

            for (int i = 0; i < N - 1; i++) {
                int a = sc.nextInt() - 1;
                int b = sc.nextInt() - 1;
                edges[a].add(b);
                edges[b].add(a);
            }

            int[] d = new int[N];
            for (int i = 0; i < N; i++) {
                d[i] = Integer.MAX_VALUE;
            }
            d[u] = 0;
            dfs(u, d, edges);

            int[] e = new int[N];
            for (int i = 0; i < N; i++) {
                e[i] = Integer.MAX_VALUE;
            }
            e[v] = 0;
            dfs(v, e, edges);

            int q = 0;
            for (int i = 0; i < N; i++) {
                if (d[i] < e[i]) {
                    if (e[i] > q) {
                        q = e[i];
                    }
                }
            }

            if (q == 0) {
                System.out.println(0);
            } else {
                System.out.println(q - 1);
            }
        }
    }

    static void dfs(int u, int[] d, List<Integer>[] edges) {
        for (Integer nu : edges[u]) {
            if (d[nu] == Integer.MAX_VALUE) {
                d[nu] = d[u] + 1;
                dfs(nu, d, edges);
            }
        }
    }

}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	final long m = (long) 1e9 + 7;

	int[] depth;

	void dfs(int cur, int par, ArrayList<Integer>[] g) {
		for (int dst : g[cur]) {
			if (dst == par)
				continue;
			depth[dst] = depth[cur] + 1;
			dfs(dst, cur, g);
		}
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int u = sc.nextInt();// T
		int v = sc.nextInt();// A
		--u;
		--v;
		int[] A = new int[N - 1];
		int[] B = new int[N - 1];
		ArrayList<Integer>[] g = new ArrayList[N];
		for (int i = 0; i < N; ++i)
			g[i] = new ArrayList<Integer>();
		for (int i = 0; i < N - 1; ++i) {
			A[i] = sc.nextInt();
			B[i] = sc.nextInt();
			--A[i];
			--B[i];
			g[A[i]].add(B[i]);
			g[B[i]].add(A[i]);
		}
		depth = new int[N];
		dfs(v, -1, g);
		ArrayDeque<long[]> dq = new ArrayDeque<>();
		dq.addLast(new long[] { u, 0, depth[u] });
		long ans = 0;
		while (!dq.isEmpty()) {
			long[] cur = dq.pollFirst();
			for (int dst : g[(int) cur[0]]) {
				if (depth[dst] > depth[(int) cur[0]]) {
					dq.add(new long[] { dst, cur[1] + 1, cur[2] });
					ans = Math.max(ans, cur[1] + 1);
				} else {
					if (cur[2] - 2 > 0) {
						dq.add(new long[] { dst, cur[1] + 1, cur[2] - 2 });
						ans = Math.max(ans, cur[1] + 1);
					} else if (cur[2] == 2) {
						ans = Math.max(ans, cur[1] + 1);
					}
				}
			}
		}
		System.out.println(ans);
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static class Node {
        int index;
        int father = -1;
        int sonHeight = 0;
        int fromRootHeight = 0;
        Set<Integer> connected = new HashSet<>();
        public Node() {
        }
        public Node(int index) {
            this.index = index;
        }
        public void setFather(int father) {
            this.father = father;
        }
        public void setSonHeight(int sonHeight) {
            this.sonHeight = sonHeight;
        }
        public void setFromRootHeight(int fromRootHeight) {
            this.fromRootHeight = fromRootHeight;
        }
        public void addConnected(int connect) {
            connected.add(connect);
        }
    }
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int t = scanner.nextInt();
        int a = scanner.nextInt();
        Node[] tree = new Node[n + 1];
        for (int i = 1; i <= n; ++i) {
            tree[i] = new Node(i);
        }
        for (int i = 1; i <= n - 1; ++i) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            tree[u].addConnected(v);
            tree[v].addConnected(u);
        }
        Queue<Integer> queue = new LinkedList<>();
        int[] visited = new int[n + 1];
        queue.add(a);
        while (!queue.isEmpty()) {
            int current = queue.poll();
            visited[current] = 1;
            for (int connected : tree[current].connected) {
                if (visited[connected] == 1) {
                    continue;
                }
                tree[connected].setFromRootHeight(tree[current].fromRootHeight + 1);
                tree[connected].setFather(current);
                queue.add(connected);
            }
        }
        calculateMaxSonHeight(tree, a, a);
        int diffHeight = tree[t].fromRootHeight - tree[a].fromRootHeight;
      //  System.out.println("a height: " + tree[a].fromRootHeight);
      //  System.out.println(" t height: "  +tree[t].fromRootHeight);
        if (diffHeight == 1) {
            System.out.println(0);
            return;
        }

        int ans = 0;
        int father = t;
     //   System.out.println("diffHieght: " + diffHeight);
        for (int i = 0; i <= (diffHeight - 1) / 2; ++i) {
         //   System.out.println("father: " + father);
            int currentSum = Math.max(
                    tree[father].fromRootHeight - tree[a].fromRootHeight,
                    tree[t].fromRootHeight - tree[father].fromRootHeight
            ) + (tree[father].sonHeight - 1);
         //   System.out.println("currentSum: " + currentSum);
            ans = Math.max(ans, currentSum);
            father = tree[father].father;
        }
        System.out.println(ans);
    }

    public static int calculateMaxSonHeight(Node[] tree, int current, int a) {
        if (tree[current].connected.size() == 1 && current != a) {
            tree[current].setSonHeight(0);
            return 0;
        }
        int height = 0;
        for (int connected : tree[current].connected) {
            if (connected == tree[current].father) {
                continue;
            }
            int currentHeight = calculateMaxSonHeight(tree, connected, a);
            height = Math.max(height, currentHeight);
        }
        tree[current].setSonHeight(height + 1);
        return height + 1;
    }
}

