	//------------------------------------------

	private int p;
	private int[] inv;
	private int[] fact;
	private int[] finv;
	public final int mod(long v) {
		v %= p;
		return (int)(v < 0 ? v+p : v);
	}
	public final int mul(long a, long b) {
		return mod(a*b);
	}
	public final void initFact(double limit, double p) {
		initFact((int)limit, (int)p);
	}
	public final void initFact(int limit, int p) {
		this.p = p;
		this.inv = new int[limit+1];
		this.fact = new int[limit+1];
		this.finv = new int[limit+1];
		fact[1] = finv[1] = inv[0] = inv[1] = 1;
		for(int i=2;i<=limit;i++) {
			int a = p / i;
			int b = p % i;
			inv[i]  = mul(-a, inv[b]);
			fact[i] = mul(fact[i-1], i);
			finv[i] = mul(finv[i-1], inv[i]);
		}
	}
	public final int comb(int m, int n) {
		return mul(mul(fact[m], finv[n]), finv[m-n]);
	}
	//------------------------------------------
	static long lcm (long a, long b) {
		long temp;
		long c = a;
		c *= b;
		while((temp = a%b)!=0) {
			a = b;
			b = temp;
		}
		return (long)(c/b);
	}

	//------------------------------------------


	static public class Node{
		private final LinkedList<Node> next = new LinkedList<>();
		private int u = -1;
		private int v = -1;
		public boolean isEnd() {
			// uがここに到着するまでの回数がvと同じか、より後の場合、
			// ここに来るかここでつかまることになる。
			return u >= v;
		}
		public int diff() {
			return v - u;
		}
	}

	public void exec() throws Exception{
		final int N = sc.nextInt();
		final int u = sc.nextInt();
		final int v = sc.nextInt();
		final Node[] graph = new Node[N+1];
		for(int i=1;i<=N;i++) {
			graph[i] = new Node();
		}
		for(int i=1;i<=N-1;i++) {
			final int A = sc.nextInt();
			final int B = sc.nextInt();
			graph[A].next.add(graph[B]);
			graph[B].next.add(graph[A]);
		}
		final ArrayList<Node> list = new ArrayList<>(N);
		list.add(graph[v]);
		graph[v].v=0;
		while(!list.isEmpty()) {
			final Node node = list.remove(list.size()-1);
			for(Node next : node.next) {
				if(next.v==-1) {
					next.v = node.v+1;
					list.add(next);
				}
			}
		}
		list.add(graph[u]);
		graph[u].u = 0;
		Node max = graph[u];
		while(!list.isEmpty()) {
			final Node node = list.remove(list.size()-1);
			if(node.isEnd()){
				if(max.diff() < node.diff()) {
					max = node;
				}
				continue;
			}
			boolean isEnd = true;
			for(Node next : node.next) {
				if(next.u == -1) {
					next.u = node.u+1;
					list.add(next);
					isEnd = false;
				}
			}
			// 終端に来ている場合
			if(isEnd) {
				if(max.v < node.v) {
					max = node;
				}
			}
		}
		out.println(max.v-1);
	}
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int u = sc.nextInt();
        int v = sc.nextInt();

        // u(Mr. Takahashi) has already visited
        boolean[] alreadyVisitedU = new boolean[n + 1];
        // v(Mr. Aoki) has already visited
        boolean[] alreadyVisitedV = new boolean[n + 1];

        // edge map
        Map<Integer, Set<Integer>> edge = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            // add: a -> b
            if (!edge.keySet().contains(a)) {
                edge.put(a, new HashSet<>());
            }
            edge.get(a).add(b);
            // add: b -> a
            if (!edge.keySet().contains(b)) {
                edge.put(b, new HashSet<>());
            }
            edge.get(b).add(a);
        }

        // map: position -> depth
        Map<Integer, Integer> position2DepthMapU = new HashMap<>();
        Map<Integer, Integer> position2DepthMapV = new HashMap<>();
        dfs(alreadyVisitedU, edge, 0, u, position2DepthMapU);
        dfs(alreadyVisitedV, edge, 0, v, position2DepthMapV);
//        System.out.println("u: " + position2DepthMapU);
//        System.out.println("v: " + position2DepthMapV);

        // u < v のうち、maxのdepthを探す
        int ans = -1;
        for (int i : position2DepthMapU.keySet()) {
            int depthU = position2DepthMapU.get(i);
            int depthV = position2DepthMapV.get(i);
            if (depthU < depthV) {
                ans = Math.max(ans, depthV);
            }
        }
        ans--;
        System.out.println(ans);

        sc.close();
    }

    // return value: depth
    static void dfs(boolean[] alreadyVisited, Map<Integer, Set<Integer>> edge, int currentDepth, int currentPosition,
            Map<Integer, Integer> position2DepthMap) {
        if (alreadyVisited[currentPosition]) {
            return;
        }
        alreadyVisited[currentPosition] = true;
        position2DepthMap.put(currentPosition, currentDepth);
        for (int nextPosition : edge.get(currentPosition)) {
//            position2DepthMap.put(nextPosition, currentDepth + 1);
            dfs(alreadyVisited, edge, currentDepth + 1, nextPosition, position2DepthMap);
        }
        return;
    }

}

