		}

		@Override
		public float floatValue() {
			return prime;
		}

		@Override
		public double doubleValue() {
			return prime;
		}

		@Override
		public String toString() {
			return String.valueOf(prime);
		}
	}

	public static class AbstractArray<T> extends AbstractList<T> implements RandomAccess{

		private final Object[] array;

		public AbstractArray(int size) {
			array = new Object[size];
		}

		public AbstractArray(T[] array) {
			this(array.length);
			System.arraycopy(array, 0, this.array, 0, array.length);
		}

		@Override
		public T set(int index, T element) {
			T ret = get(index);
			array[index] = element;
			return ret;
		}

		@Override
		public T get(int index) {
			@SuppressWarnings("unchecked")
			T ret = (T)array[index];
			return ret;
		}

		public Object[] get() {
			return array;
		}

		public T[] get(T[] array) {
			if (array.length < this.array.length) {
				@SuppressWarnings("unchecked")
				T[] ret  = (T[])Arrays.copyOfRange(this.array, 0, this.array.length, array.getClass());
				return ret;
			}
			System.arraycopy(this.array, 0, array, 0, this.array.length);
			return array;
		}

		@Override
		public int size() {
			return array.length;
		}

		public int length() {
			return size();
		}

		@Override
		public int hashCode() {
			return Arrays.hashCode(array);
		}

		private class Iter implements Iterator<T> {
			private int index;

			private Iter() {
				index = 0;
			}

			@Override
			public boolean hasNext() {
				return index < array.length;
			}

			@Override
			public T next() {
				return get(index++);
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}
		}

		@Override
		public Iterator<T> iterator() {
			return new Iter();
		}
	}

	public static class Array<T> extends AbstractArray<T> implements Serializable{

		private static final long serialVersionUID = 2749604433067098063L;

		public Array(int size) {
			super(size);
		}

		public Array(T[] array) {
			super(array);
		}

		public T front() {
			return get(0);
		}

		public T back() {
			return get(size() - 1);
		}
	}
}

import java.util.*;
public class Main {
	static int N,u,v;
	static List<ArrayList<Integer>> ls = new ArrayList<ArrayList<Integer>>();
	static int t_dist[], a_dist[];
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt(); u = sc.nextInt()-1; v = sc.nextInt()-1;
		for(int i=0;i<N;i++) ls.add(new ArrayList<Integer>());
		for(int i=0;i<N-1;i++) {
			int A = sc.nextInt()-1, B = sc.nextInt()-1;
			ls.get(A).add(B);
			ls.get(B).add(A);
		}
		sc.close();
		t_dist = new int[N];
		a_dist = new int[N];
		int dif[] = new int[N];
		dfs(u, 0,-1);
		adfs(v, 0, -1);
		for(int i=0;i<N;i++) {
			dif[i] = Math.max(a_dist[i]-t_dist[i], 0);
		}
		long ans = 0;
		int i=1;
		if(u<v) {
			while(true) {
				if(dif[u-i]!=0&&u-i>=0) {
					ans++;
					i++;
				}
				else break;
			}
		}else {
			while(true) {
				if(dif[u+i]!=0&&u+i<N) {
					ans++;
					i++;
				}
				else break;
			}
		}

		System.out.println(ans);
	}
	static void dfs(int now, int cnt, int parent) {
		t_dist[now]=cnt;
		for(int i=0;i<ls.get(now).size();i++) {
			int next = ls.get(now).get(i);
			if(next == parent)continue;
			dfs(next, cnt+1, now);
		}
	}
	static void adfs(int now, int cnt, int parent) {
		a_dist[now]=cnt;
		for(int i=0;i<ls.get(now).size();i++) {
			int next = ls.get(now).get(i);
			if(next == parent)continue;
			adfs(next, cnt+1, now);
		}
	}
}

import java.util.*;
import java.util.function.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int u = sc.nextInt();
    int v = sc.nextInt();
    int[] A = new int[N - 1];
    int[] B = new int[N - 1];
    for (int i = 0; i < N - 1; i++) {
      A[i] = sc.nextInt();
      B[i] = sc.nextInt();
    }
    sc.close();

    @SuppressWarnings("unchecked")
    List<Integer>[] tree = new List[N + 1];
    for (int i = 0; i < N - 1; i++) {
      if (tree[A[i]] == null) tree[A[i]] = new ArrayList<>();
      if (tree[B[i]] == null) tree[B[i]] = new ArrayList<>();
      tree[A[i]].add(B[i]);
      tree[B[i]].add(A[i]);
    }

    int[] du = dist(tree, N, u);
    int[] dv = dist(tree, N, v);
    int ans = 0;
    for (int i = 1; i < N + 1; i++)
      if (du[i] < dv[i]) ans = Integer.max(ans, dv[i]);
    System.out.println(ans - 1);
  }

  private static int[] dist(List<Integer>[] tree, int N, int s) {
    int[] d = new int[N + 1];
    Deque<Integer> q = new ArrayDeque<>();
    q.addLast(s);
    while (!q.isEmpty()) {
      int n = q.pollFirst();
      List<Integer> edge = tree[n];
      for (int e : edge)
        if (d[e] == 0 && e != s) {
          d[e] = d[n] + 1;
          q.addLast(e);
        }
    }
    return d;
  }
}

import java.util.*;
import java.io.*;

class Main{
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        int u=fsc.nextInt()-1, v=fsc.nextInt()-1;
        ArrayList<Integer>[] nodes=new ArrayList[n];
        for(int i=0;i<n;i++){
            nodes[i]=new ArrayList<>();
        }
        for(int i=0;i<n-1;i++){
            int a=fsc.nextInt()-1, b=fsc.nextInt()-1;
            nodes[a].add(b);
            nodes[b].add(a);
        }
        fsc.close();
        int[] path=bfs(nodes, u, v);
        int back=Math.max((path.length-2)/2, 0);
        int ans=back;
        int st=path[back];
        int ng=path[back+1];
        ans+=rebfs(nodes, st, ng);
        if(path.length%2==1) ans++;
        System.out.println(ans);
    }
    public static  int[] bfs(ArrayList<Integer>[] nodes, int u, int v){
        ArrayDeque<Integer> q=new ArrayDeque<>();
        q.add(u);
        int n=nodes.length;
        int[] d=new int[n];
        int[] prev=new int[n];
        for(int i=0;i<n;i++){
            d[i]=-1;
        }
        d[u]=0;
        while(q.size()>0){
            int now=q.removeFirst();
            for(int next:nodes[now]){
                if(d[next]<0){
                    d[next]=d[now]+1;
                    q.add(next);
                    prev[next]=now;
                }
            }
        }
        int len=d[v];
        int[] path=new int[len+1];
        int now=v;
        for(int i=0;i<len+1;i++){
            path[len-i]=now;
            now=prev[now];
        }
        return path;
    }
    public static  int rebfs(ArrayList<Integer>[] nodes, int st, int ng){
        ArrayDeque<Integer> q=new ArrayDeque<>();
        q.add(st);
        int n=nodes.length;
        int[] d=new int[n];
        for(int i=0;i<n;i++){
            d[i]=-1;
        }
        d[st]=0;
        int max=0;
        while(q.size()>0){
            int now=q.removeFirst();
            for(int next:nodes[now]){
                if(d[next]<0 && next!=ng){
                    d[next]=d[now]+1;
                    max=Math.max(max, d[next]);
                    q.add(next);
                }
            }
        }
        return max;
    }
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

