            // System.out.println("pos:" + pos);
            if (pos == v) {
                // System.out.println("1");
                break;
            }
            for (int i = 0; i < n - 1; i++) {
                // System.out.println("2");
                if (!visited[i] && map[pos][i] == 1) {
                    sta.add(i);
                    // System.out.println("add:" + i);
                    visited[i] = true;
                    continue S;
                }
            }
            sta.pollLast();
        }
        // stackに経路が乗っている
        int len = sta.size();
        // System.out.println("len : " + len);
        int l = len / 2;
        int left = v;
        for (int i = 0; i < l; i++) {
            left = sta.pollFirst();
        }
        int right = sta.pollFirst();

        // System.out.println("left : " + left + ": right : " + right);

        int toCenter = (len - 2) / 2;
        // 切断する
        // leftからDSする
        map[left][right] = 0;
        map[right][left] = 0;
        sta = new ArrayDeque<>();

        Arrays.fill(visited, false);
        sta.clear();
        sta.add(left);

        int ans = 0;
        int dis[] = new int[n];
        dis[left] = 1;
        visited[left] = true;
        while (!sta.isEmpty()) {
            int pos = sta.pollFirst();
            for (int i = 0; i < n - 1; i++) {
                if (!visited[i] && map[pos][i] == 1) {
                    visited[i] = true;
                    sta.add(i);
                    dis[i] = dis[pos] + 1;
                }

            }
        }
        for (int i = 0; i < dis.length; i++) {
            ans = Math.max(ans, dis[i]);
        }

        if (ans == 1) {
            if (len == 3) {
                System.out.println(1);
            } else {
                System.out.println(0);
            }
        } else {
            if (len % 2 == 0 && ans % 2 == 0) {
                ans--;
            }
            System.out.println(ans + toCenter);
        }
        // System.out.println("ans : " + ans + "toccneter" + toCenter);
        sc.close();
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static int n;
	public static int u;
	public static int v;
	public static int ans = 0;
	public static int[] takadist;
	public static int[] aodist;
	public static List<Integer>[] path;
	public static int dist = 0;

	public static void Aocalc(int parent, int here) {
		aodist[here] = dist;
		dist++;
		for(Integer e : path[here]) {
			if(e != parent) {
				Aocalc(here, e);
			}
		}
	}

	public static void Takacalc(int parent, int here) {
		takadist[here] = takadist[parent] + 1;
		if(takadist[here] >= aodist[here]) {
			ans = Math.max(ans, aodist[here]);
		} else {
			for(Integer e : path[here]) {
				Takacalc(here, e);
			}
		}
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		takadist = new int[n + 1];
		aodist = new int[n + 1];
		for(int i = 0; i < n + 1; i++) {
			takadist[i] = n;
		}
		for(int i = 0; i < n + 1; i++) {
			aodist[i] = n;
		}
		path = new ArrayList[n + 1];
		u = sc.nextInt();
		v = sc.nextInt();
		takadist[u] = 0;
		aodist[v] = 0;
		for(int i = 1; i < n + 1; i++) {
			path[i] = new ArrayList<>();
		}
		for(int i = 0; i < n - 1; i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			path[a].add(b);
			path[b].add(a);
		}
		Aocalc(v, v);
		Takacalc(u, u);
		System.out.println(ans);

	}

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.NoSuchElementException;

public class Main {
	static int[][] edge;
	public static void main(String args[]) {
		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);
		int N = sc.nextInt();
		int u = sc.nextInt();
		int v= sc.nextInt();
		edge = new int[N-1][N-1];
		for(int i=0;i<N;i++) {
			int a = sc.nextInt()-1;
			int b = sc.nextInt()-1;
			edge[a][b] = 1;
		}
		int result = dps(u,-1,v,0);
		result += dps2(v,0,0);
		out.println(result);



		out.flush();
	}

	static int dps(int now,int prev, int dest,int dist) {
		if(now==dest) return dist;
		else{
			for(int next: edge[now]) {
				if(next != prev) {;
					prev = now;
					return dps(next,prev, dest,dist+1);
				}
			}
		}
	}

	static int dps2(int now,int prev, int dist) {
		if(edge[now].length==1) return dist;
		for(int next: edge[now]) {
			if(next!=prev) {
				prev = now;
				return dps2(next,prev, dist);
			}
		}
	}
}

class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		}else{
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
	public String next() {
		if (!hasNext()) throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext()) throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) nl;
	}
	public double nextDouble() { return Double.parseDouble(next());}
}
}

import java.util.*;

public class Main{
	static private Scanner sc = new Scanner(System.in);

	public static void main(String[] args){
		int n = sc.nextInt();
		int u = sc.nextInt();
		int v = sc.nextInt();
		--u;
		--v;

		ArrayList<ArrayList<Integer>> nodeMap = getInitialMap(n);

		for(int i = 1; i < n; ++i){
			int a = sc.nextInt();
			int b = sc.nextInt();
			--a;
			--b;
			nodeMap.get(a).add(b);
			nodeMap.get(b).add(a);
		}

		/*for(int i = 0; i < n; ++i){
			System.out.println(nodeMap.get(i));
		}*/

		ArrayList<Integer> distanceFromU = getInitialDistance(n);
		distanceFromU.set(u, 0);
		dfs(u, distanceFromU, nodeMap);

		ArrayList<Integer> distanceFromV = getInitialDistance(n);
		distanceFromV.set(v, 0);
		dfs(v, distanceFromV, nodeMap);

		/*for(int i = 0; i < n; ++i){
			System.out.println("Distance between " + i + " and " + u + " = " + distanceFromU.get(i));
		}

		for(int i = 0; i < n; ++i){
			System.out.println("Distance between " + i + " and " + v + " = " + distanceFromV.get(i));
		}*/

		int ans = 0;
		for(int i = 0; i < n; ++i){
			if(nodeMap.get(i).size() > 1) continue;

			if(distanceFromU.get(i) <= distanceFromV.get(i)){
				ans = Math.max(ans, distanceFromU.get(i));
			}
		}
		System.out.println(ans);
	}

	static ArrayList<ArrayList<Integer>> getInitialMap(int n){
		ArrayList<ArrayList<Integer>> res = new ArrayList<>();
		for(int i = 0; i < n; ++i){
			res.add(new ArrayList<Integer>());
		}
		return res;
	}

	static ArrayList<Integer> getInitialDistance(int n){
		ArrayList<Integer> res = new ArrayList<>();
		for(int i = 0; i < n; ++i){
			res.add(-1);
		}
		return res;
	}

	static void dfs(int current, ArrayList<Integer> distance, ArrayList<ArrayList<Integer>> nodeMap){
		for(int i = 0; i < nodeMap.get(current).size(); ++i){
			int nextNode = nodeMap.get(current).get(i);
			if(distance.get(nextNode) < 0){
				distance.set(nextNode, distance.get(current) + 1);
				dfs(nextNode, distance, nodeMap);
			}
		}
	}
}

