import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    Node[] nodes = new Node[N];
    for (int i = 0; i < N; i++) nodes[i] = new Node();
    int u = scanner.nextInt() - 1;
    int v = scanner.nextInt() - 1;
    for (int i = 0; i < N - 1; i++) {
      int a = scanner.nextInt() - 1;
      int b = scanner.nextInt() - 1;
      nodes[a].adjacent.add(nodes[b]);
      nodes[b].adjacent.add(nodes[a]);
    }

    dfs(nodes[v], null);
    List<Node> path = dfs2(nodes[v], null, nodes[u]);
    Collections.reverse(path);
    int max = 0;
    for (int i = path.size() - path.size() / 2; i < path.size(); i++) {
      max = Math.max(max, i + path.get(i).level - 1);
    }
    System.out.println(max);
  }

  private static int dfs(Node node, Node from) {
    int level = -1;
    for (Node a : node.adjacent) {
      if (a != from) {
        level = Math.max(level, dfs(a, node));
      }
    }
    node.level = level + 1;
    return node.level;
  }

  private static List<Node> dfs2(Node node, Node from, Node target) {
    if (node == target) {
      List<Node> list = new ArrayList<>();
      list.add(target);
      return list;
    }
    for (Node a : node.adjacent) {
      if (a != from) {
        List<Node> list = dfs2(a, node, target);
        if (list != null) {
          list.add(node);
          return list;
        }
      }
    }
    return null;
  }

  private static class Node {
    private final List<Node> adjacent = new ArrayList<>();
    private int level;
  }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;
import java.util.function.Supplier;

public class Main {
    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final int tVertex = scanner.nextInt();
        final int aVertex = scanner.nextInt();

        final List<Integer>[] tree = new List[n + 1];
        for (int i = 1; i < tree.length; i++) {
            tree[i] = new ArrayList<>();
        }
        for (int i = 0; i < n - 1; i++) {
            final int a = scanner.nextInt();
            final int b = scanner.nextInt();
            tree[a].add(b);
            tree[b].add(a);
        }

        final List<Integer> route = new ArrayList<>();
        final boolean[] isVisited = new boolean[n + 1];
        isVisited[tVertex] = true;
        search(tree, tVertex, aVertex, route, isVisited);

        Arrays.fill(isVisited, false);
        for (int i = route.size() / 2; i < route.size(); i++) {
            isVisited[route.get(i)] = true;
        }

        final List<Integer> routeFromA = new ArrayList<>();
        final List<Integer> routeFromA2 = searchLongest(tree, route.get(route.size() / 2), routeFromA, isVisited);

        System.out.println(routeFromA2.size() + (route.size() - 1) / 2 - 2);
    }

    private static List<Integer> searchLongest(final List<Integer>[] tree, final int current, final List<Integer> route, final boolean[] isVisited) {
        isVisited[current] = true;
        route.add(current);
        List<Integer> longest = new ArrayList<>(route);
        for (final int next : tree[current]) {
            if (isVisited[next]) {
                continue;
            }

            final List<Integer> tmp = searchLongest(tree, next, route, isVisited);
            if (tmp.size() > longest.size()) {
                longest = Collections.unmodifiableList(tmp);
            }
        }
        route.remove(route.size() - 1);
        return longest;
    }

    private static boolean search(final List<Integer>[] tree, final int current, final int dest, final List<Integer> route, final boolean[] isVisited) {
        isVisited[current] = true;
        route.add(current);
        if (current == dest) {
            return true;
        }
        for (final int next : tree[current]) {
            if (isVisited[next]) {
                continue;
            }

            if (search(tree, next, dest, route, isVisited)) {
                return true;
            }
        }
        route.remove(route.size() - 1);
        return false;
    }
}

import java.util.*;

public class Main {
    private static Map<Integer, List<Integer>> mp = new HashMap<>();
    private static Map<Integer, Integer> aokiMap = new HashMap<>();
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int u = sc.nextInt()-1;
        int v = sc.nextInt()-1;
        for(int i=0;i<N-1;i++){
            int A = sc.nextInt()-1;
            int B = sc.nextInt()-1;
            mp.computeIfAbsent(A,(p)->new ArrayList<>() ).add(B);
            mp.computeIfAbsent(B,(p)->new ArrayList<>() ).add(A);
        }
        traverseAoki(v);
        System.out.println(dijkstraTaka(u));
    }

    private static int dijkstraTaka(int u){
        PriorityQueue<Taka> pq = new PriorityQueue<>(Comparator.comparingInt(a -> -aokiMap.get(a.now)));//Reverse order of larger to smaller
        Map<Integer, Integer> takaMap = new HashMap<>();
        int maxAoki=0;
        pq.add(new Taka(u,-1,0));
        while(!pq.isEmpty()){
            Taka top = pq.poll();
            Integer now = top.now;
            Integer from = top.from;
            Integer walk = top.walk;
            if(walk >= aokiMap.get(now)){
                maxAoki = Math.max(maxAoki, aokiMap.get(now));
                continue;
            }
            for(Integer nei: mp.get(now)){
                if(nei.equals(from)){
                    if(mp.get(now).size() != 1){
                        continue;
                    }
                }
                pq.add(new Taka(nei, now, walk+1));
            }
        }
        return maxAoki;
    }

    private static void traverseAoki(int v){
        Queue<Integer> q = new LinkedList<>();
        q.add(v);
        aokiMap.put(v,0);
        while(!q.isEmpty()){
            Integer now = q.poll();
            for(Integer nei:mp.get(now)){
                if(aokiMap.containsKey(nei)){continue;}//already traversed.
                aokiMap.put(nei, aokiMap.get(now)+1);
                q.add(nei);
            }
        }
    }

    private static class Taka{
        int now;
        int from;
        int walk;
        Taka(int n, int f, int w){
            now = n;
            from = f;
            walk = w;
        }

        @Override
        public boolean equals(Object obj) {
            if(obj.getClass() == this.getClass()){
                Taka o = (Taka)obj;
                return o.from==from && o.now ==now && o.walk == walk;
            }
            return super.equals(obj);
        }

        @Override
        public int hashCode() {
            return now * 200_000 + from + walk;
        }
    }
}

