	static int t_dist[], a_dist[];
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long u = sc.nextLong()-1;
        long v = sc.nextLong()-1;

        int ai;
        int bi;
