                    map.put(a + N, b);
                }
                if (!map.containsKey(b)) {
                    map.put(b, a);
                } else {
                    map.put(b + N, a);
                }
            }

            int[] d = new int[N];
            for (int i = 0; i < N; i++) {
                d[i] = 1000000;
            }
            d[u] = 0;
