            int[] e = new int[N];
            for (int i = 0; i < N; i++) {
                e[i] = 1000000;
            }
            e[v] = 0;
            dfs(v, e, map);

            int p = -1;
            int q = -1;
            for (int i = 0; i < N; i++) {
                if (d[i] > e[i]) {
                    if (d[i] > q) {
                        p = i;
                        q = d[i];
                    }
                }
            }

