        if (d[nu] == 1000000) {
            d[nu] = d[u] + 1;
            dfs(nu, d, map);
        }

        nu = map.get(u + d.length);
        if (nu != null && d[nu] == 1000000) {
            d[nu] = d[u] + 1;
            dfs(nu, d, map);
        }
    }

}

