import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;

public class Main {

    static int N, U, V;
    static int[] A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        U = sc.nextInt()-1;
        V = sc.nextInt()-1;

        A = new int[N-1];
        B = new int[N-1];
        for (int i = 0; i < N-1; i++) {
            A[i] = sc.nextInt()-1;
            B[i] = sc.nextInt()-1;
        }

        System.out.println(solve());
    }

    static int solve() {
        int[][] G = adjB(N, A, B);

        int[] distFromV = distFrom(N, G, V);
        int[] distFromU = new int[N];
        boolean[] availableFromU = new boolean[N];
        int max = 0;
        for (Node node : orderFromRoot(N, G, U)) {
            if( node.a == U ) {
                availableFromU[node.a] = true;
                distFromU[node.a] = 0;

            } else if( !availableFromU[node.parent] ) {
                availableFromU[node.a] = false;
                distFromU[node.a] = -1;

            } else {
                int du = distFromU[node.parent]+1;
                int dv = distFromV[node.a];

                if( du < dv ) {
                    distFromU[node.a] = du;
                    availableFromU[node.a] = true;
                    max = Math.max(max, dv-1);

                } else if( du == dv ) {
                    distFromU[node.a] = du;
                    availableFromU[node.a] = false;
                    max = Math.max(max, dv);

                } else {
                    distFromU[node.a] = -1;
                    availableFromU[node.a] = false;
                }
            }
        }

        return max;
    }

    static int[] distFrom(int N, int[][] G, int start) {
        int[] dist = new int[N];
        for (Node node : orderFromRoot(N, G, start)) {
            if( node.a == start ) {
                dist[node.a] = 0;
            } else {
                dist[node.a] = dist[node.parent]+1;
            }
        }
        return dist;
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    static Node[] orderFromRoot(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = 0;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx++] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
