		for(int i = 1; i <= N; i++)
		        edge.put(i,  new HashSet<>());
		for (int i = 1; i <= N-1; i++) {
		        int A = sc.nextInt(), B = sc.nextInt();
		        edge.get(A).add(B);
		        edge.get(B).add(A);
		}
