				this.y = y;
				this.h = h;
				this.w = w;
				this.b = b;
				this.val = val;
				i = x * w + y;
			}

			@Override
			public int compareTo(Grid g) {
				return Long.compare(this.val, g.val);
			}
		}

		boolean isValid(int x, int y, int h, int w) {
			return x >= 0 && x < h && y >= 0 && y < w;
		}
		boolean isValid(Grid g) {
			return isValid(g.x, g.y, g.h, g.w);
		}

		// graph
		class Graph {
			int numNode;
			int numEdge;
			boolean directed;
			Edge edges[];
			Node nodes[];
			Node reversedNodes[];

			Graph(int numNode, int numEdge, boolean directed) {
				this.numNode = numNode;
				this.numEdge = numEdge;
				this.directed = directed;
				nodes = new Node[numNode];
				reversedNodes = new Node[numNode];
				for(int i = 0; i < numNode; i ++) {
					nodes[i] = new Node(i);
					reversedNodes[i] = new Node(i);
				}
			}

			void init(Edge edges[]) {
				this.edges = edges;
				for(Edge edge : edges) {
					nodes[edge.source].add(edge.target, edge.cost);
					if(directed) {
						reversedNodes[edge.target].add(edge.source, edge.cost);
					}else {
						nodes[edge.target].add(edge.source, edge.cost);
					}
				}
			}

			void clearNodes() {
				for(Node n : nodes) { n.clear(); }
				for(Node n : reversedNodes) { n.clear(); }
			}
		}

		class Node extends ArrayList<Edge> {
			int id;

			Node(int id) {
				this.id = id;
			}
			void add(int target, long cost) {
				add(new Edge(id, target, cost));
			}
		}

		class Edge implements Comparable<Edge> {
			int source;
			int target;
			long cost;
			Edge(int source, int target, long cost) {
				this.source = source;
				this.target = target;
				this.cost = cost;
			}

			@Override
			public int compareTo(Edge e) {
				return Long.compare(this.cost, e.cost);
			}
		}

public void solve() {
	int numNode = ni();
	int start = ni() - 1;
	int goal = ni() - 1;
	int numEdge = numNode - 1;
	Graph g = new Graph(numNode, numEdge, false);
	Edge edges[] = new Edge[numEdge];
	for(int i = 0; i < numEdge; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		long c = 1;
		edges[i] = new Edge(a, b, c);
	}
	g.init(edges);
	long ans = 0;

	long dist[] = dijkstra(g.nodes, start);
	int pass[] = getPass(start, goal);

	int l = 0;
	int r = pass.length - 1;
	while(true) {
		if(l + 1 >= r - 1) break;
		l ++;
		start = pass[l];
		r --;
		ans ++;
		goal = pass[r];
		if(l + 1 >= r - 1) break;
	}

	dist = bfs(g.nodes, start, goal, pass[max(l + 1, r - 1)]);
	int maxNode = 0;
	long maxDist = 0;
	for(int i = 0; i < numNode; i ++) {
		if(!isINF(dist[i]) && maxDist < dist[i]) {
			maxNode = i;
			maxDist = dist[i];
		}
	}
	ans += maxDist;
	ans += (r - l) / 2;
	prtln(ans);
}

long[] bfs(Node nodes[], int start, int ng, int ng2) {
	long dist[] = new long[nodes.length];
	Arrays.fill(dist, INF);

	Deque<Integer> s = new ArrayDeque<>();
	s.addLast(start);
	dist[start] = 0;
	while(!s.isEmpty()) {
		int crt = s.removeFirst();
		for(Edge e : nodes[crt]) {
			if(isINF(dist[e.target])) {
				if(e.target == ng) continue;
				if(e.target == ng2) continue;
				dist[e.target] = dist[e.source] + 1;
				s.addLast(e.target);
			}
		}
	}

	return dist;
}

int[] getPass(int start, int goal) {
	List<Integer> passList = new ArrayList<>();
	passList.add(goal);
	while(passList.get(passList.size() - 1) != start) {
		passList.add(prev[passList.get(passList.size() - 1)]);
	}
	int pass[] = new int[passList.size()];
	for(int i = 0; i < passList.size(); i ++) {
		pass[i] = passList.get(i);
	}

	reverse(pass);
	return pass;
}

int prev[];
long[] dijkstra(Node nodes[], int start) { // O((E+V)logV)
	long dist[] = new long[nodes.length];
	Arrays.fill(dist, INF);
	dist[start] = 0;

	prev = new int[nodes.length];

	Queue<Edge> q = new PriorityQueue<Edge>();
	q.add(new Edge(start, start, dist[start]));

	while(!q.isEmpty()) {
		Edge crt = q.poll();

		if(dist[crt.target] < crt.cost) { continue; }
		for(Edge e : nodes[crt.target]) {
			if(dist[e.target] > dist[e.source] + e.cost) {
				dist[e.target] = dist[e.source] + e.cost;
				q.add(new Edge(e.source, e.target, dist[e.target]));
				prev[e.target] = e.source;
			}
		}
	}

	return dist;
}

	}
}

