            adj[b].Add(a);
        }
        var parent = E.Repeat(-1, n).ToArray();
        var depth = E.Repeat(-1, n).ToArray();

        var queue = new Queue<int>();
        queue.Enqueue(v);
        queue.Enqueue(-1);
        queue.Enqueue(0);
        var perm = new List<int>();
        while (queue.Count > 0) {
            var current = queue.Dequeue();
            var pa = queue.Dequeue();
            var dep = queue.Dequeue();
            if (depth[current] != -1) continue;
            perm.Add(current);
            depth[current] = dep;
            parent[current] = pa;

            foreach (var next in adj[current]) {
                if (next != pa) {
                    queue.Enqueue(next);
                    queue.Enqueue(current);
                    queue.Enqueue(dep + 1);
                }
            }
        }
        var maxDepth = new int[n];
        foreach (var p in perm.AsEnumerable().Reverse()) {
            var d = depth[p];

            foreach (var next in adj[p]) {
                if (parent[p] == next) continue;
                d = Math.Max(d, maxDepth[next]);
            }
            maxDepth[p] = d;
        }
        int ans = 0;
        var takahashiPos = u;
        var aokiDepth = 0;
        var maxDistance = 0;
        while (true) {
            var currentDepth = depth[takahashiPos];
            if (aokiDepth >= currentDepth) break;
            var maxdepth = maxDepth[takahashiPos];

            maxDistance = Math.Max(maxDistance, maxdepth);

            takahashiPos = parent[takahashiPos];
            aokiDepth++;
        }
        cout.WriteLine(simulate(0, depth[u], maxDistance));
    }

    private int simulate(int aoki, int takahashi, int maxDistance) {
        int ans = 0;

        while (true) {
            if (takahashi < maxDistance) {
                takahashi++;
            } else {
                takahashi--;
            }
            if (aoki == takahashi) break;
            aoki++;
            ans++;
            if (aoki == takahashi) break;
        }

        return ans;
    }
}

