static class Program
{
    static void Cut(int[] parents, List<int>[] children, int i, int n)
    {
        int j = -1;
        while (n-- > 0)
        {
            j = i;
            i = parents[j];
        }
        while (i >= 0)
        {
            children[i] = new List<int> { j };
            j = i;
            i = parents[j];
        }
    }

    const int INF = int.MaxValue / 2;

    static int[] Depth(List<int>[] children, int i)
    {
        int N = children.Length;
        var d = Enumerable.Repeat(INF, N).ToArray();
        var q = new Queue<int>();
        d[i] = 0;
        q.Enqueue(i);
        while (q.Count > 0)
        {
            int u = q.Dequeue();
            foreach (int v in children[u])
            {
                if (d[u] + 1 < d[v])
                {
                    d[v] = d[u] + 1;
                    q.Enqueue(v);
                }
            }
        }
        return d;
    }

    static int Solve(int[] parents, List<int>[] children, int u, int v)
    {
        int d = Depth(children, v)[u];
        Cut(parents, children, u, (d + 1) / 2);
        return Depth(children, v).Where(n => n < int.MaxValue / 2).Max() - 1;
    }

    static void Main(string[] args)
    {
        var V1 = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        int N = V1[0], u = V1[1] - 1, v = V1[2] - 1;
        var parents = new int[N];
        var children = new List<int>[N];
        var edges = new List<int>[N];
        for (int i = 0; i < N; ++i)
        {
            parents[i] = -1;
            children[i] = new List<int>();
            edges[i] = new List<int>();
        }
        for (int i = 0; i < N - 1; ++i)
        {
            var V2 = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
            int a = V2[0] - 1, b = V2[1] - 1;
            edges[a].Add(b);
            edges[b].Add(a);
        }
        var visited = new bool[N];
        var queue = new Queue<int>();
        visited[v] = true;
        queue.Enqueue(v);
        while (queue.Count > 0)
        {
            int a = queue.Dequeue();
            foreach (int b in edges[a])
            {
                if (!visited[b])
                {
                    parents[b] = a;
                    children[a].Add(b);
                    visited[b] = true;
                    queue.Enqueue(b);
                }
            }
        }
        Console.WriteLine(Solve(parents, children, u, v));
    }
}

