class Solver
{
    Scanner sc = new Scanner();
    //
    List<int>[] edge;
    int max,mj;
    public void Solve()
    {
        int N, u, v;
        sc.Make(out N, out u, out v);
        u--;v--;

        edge = Create(N, () => new List<int>());
        for (var i = 0; i < N-1; i++)
        {
            int a, b;
            sc.Make(out a, out b);
            a--; b--;
            edge[a].Add(b);
            edge[b].Add(a);
        }
        var du = bfs(edge,u);
        var dv = bfs(edge, v);
        var g = Create(N, () => new List<int>());
        for (var i = 0; i < N; i++)
            if (du[i] < dv[i])
                foreach (var e in edge[i])
                    if (du[e] < dv[e])
                        g[i].Add(e);
        var eq = false;
        foreach (var e in edge[u])
            eq |= du[e] == dv[e];
        bfs(g, u);
        WriteLine(bfs(g, mj).Max()+ToInt32(eq));
    }
    int[] bfs(List<int>[] edge,int st)
    {
        var dist = Create(edge.Length, () => -1);max = 0;
        var q = new Queue<int>();
        q.Enqueue(st);
        dist[st] = 0;
        while (q.Any())
        {
            var p = q.Dequeue();
            foreach (var e in edge[p])
                if (dist[e] == -1)
                {
                    dist[e] = dist[p] + 1;
                    if (chmax(ref max, dist[e]))
                        mj = e;
                    q.Enqueue(e);
                }
        }
        return dist;
    }
}

