            LowestCommonAncestor lca = new LowestCommonAncestor(N);


            int[] A = new int[N - 1];
            int[] B = new int[N - 1];

            for (int i = 0; i < N - 1; i++)
            {
                A[i] = cin.ReadInt - 1;
                B[i] = cin.ReadInt - 1;

                lca.AddEdge(A[i], B[i]);
            }

            // 青木くんがroot
            lca.Build(root: v);

            int dist = lca.GetDistance(u, v);

            int dist2 = dist % 2 == 0 ? dist / 2 : dist / 2 + 1;

            // if (dist2 == 0)
