            //     cou.WriteLine(dist);
            //     return;
            // }

            if (u == v)
            {
                cou.WriteLine(0);
                return;
            }

            if (dist == 1)
            {
                if (lca.G[u].Count == 1)
                {
                    // Dbg.WriteLine("!!!!!!!!!!!!逃げ場なし");
                    cou.WriteLine(0);
                    return;
                }
            }

            if (dist == 2)
            {
                if (lca.G[u].Count == 1)
                {
                    cou.WriteLine(1);
                    return;
                }
            }

            int ind1 = lca.pathIndexes[dist2 - 1];
            int ind2 = lca.pathIndexes[dist2];


            var lca2 = new LowestCommonAncestor(N);

            for (int i = 0; i < N - 1; i++)
            {
                if ((A[i] == ind1 && B[i] == ind2) || (A[i] == ind2 && B[i] == ind1))
                {
                    continue;
                }

                lca2.AddEdge(A[i], B[i]);
            }

            lca2.Build(root: ind2);

            int ans = lca2.depth.Max();

            ans += dist2;

            ans--;

            cou.WriteLine(ans);
        }
