  class Program
  {
    static void Main(string[] args)
    {
      var n = CIn.ReadInt();
      var uv = CIn.ReadIntArray(2).Select(e => e - 1).ToArray();

      var tree = new List<int>[n];

      for (var i = 0; i < n; i++)
      {
        tree[i] = new List<int>();
      }

      for (var i = 0; i < n - 1; i++)
      {
        var a = CIn.ReadInt() - 1;
        var b = CIn.ReadInt() - 1;

        tree[a].Add(b);
        tree[b].Add(a);
      }

      var dist = new int[2, n];

      for (var i = 0; i < 2; i++)
      {
        var stack = new Stack<SearchRoute>();
        var searched = new bool[n];

        stack.Push(new SearchRoute(uv[i], 0));

        while (stack.Count > 0)
        {
          var sr = stack.Pop();
          searched[sr.Node] = true;
          dist[i, sr.Node] = sr.Depth;

          foreach (var d in tree[sr.Node])
          {
            if (!searched[d]) stack.Push(new SearchRoute(d, sr.Depth + 1));
          }
        }
      }

      var max = 0;

      for (var i = 0; i < n; i++)
      {
        if (dist[0, i] < dist[1, i]) max = Math.Max(max, dist[1, i]);
      }

      Console.WriteLine(max - 1);
    }
  }

