public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int u = GetInt() - 1;
		int v = GetInt() - 1;
		var adj = Enumerable.Range(0, N).Select(_ => new List<int>()).ToArray();
		for(int i = 0; i < N - 1; i++)
		{
			int A = GetInt() - 1;
			int B = GetInt() - 1;
			adj[A].Add(B);
			adj[B].Add(A);
		}

		var tak = bfs(N, u, adj);
		var aok = bfs(N, v, adj);

		int ans = 0;
		for(int i = 0; i < N; i++)
		{
			if(tak[i] >= aok[i])
				continue;

			chmax(ref ans, aok[i] - 1);
		}
		WriteLine(ans);
	}

	private int[] bfs(int N, int s, List<int>[] adj)
	{
		int INF = int.MaxValue / N;
		var res = Enumerable.Repeat(INF, N).ToArray();
		var queue = new Queue<int>();
		res[s] = 0;
		queue.Enqueue(s);
		while(queue.Count > 0)
		{
			int v = queue.Dequeue();
			foreach(int u in adj[v])
			{
				if(res[u] != INF)
					continue;

				res[u] = res[v] + 1;
				queue.Enqueue(u);
			}
		}
		return res;
	}
}

