class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        N = sc.ReadInt();
        U = sc.ReadInt();
        V = sc.ReadInt();
        U--; V--;
        G = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            G[i] = new List<int>();
        }
        for (int i = 0; i < N - 1; i++)
        {
            var a = sc.ReadInt();
            var b = sc.ReadInt();
            a--; b--;
            G[a].Add(b);
            G[b].Add(a);
        }
        var distU = DistTree(U);
        var distV = DistTree(V);
        var ans = 0L;
        for (int i = 0; i < N; i++)
        {
            if (distU[i] < distV[i])
            {
                var res = distV[i] - 1;
                ans = Math.Max(ans, res);
            }
        }
        Console.WriteLine(ans);
    }
    static int N, U, V;
    static List<int>[] G;

    static long[] DistTree(int start)
    {
        var q = new Queue<Tuple<int, int, int>>();
        q.Enqueue(Tuple.Create(start, -1, 0));
        var dist = new long[G.Length];
        while (q.Count > 0)
        {
            var t = q.Dequeue();
            var now = t.Item1;
            var prev = t.Item2;
            var d = t.Item3;
            dist[now] = d;
            foreach (var next in G[now])
            {
                if (next == prev) continue;
                q.Enqueue(Tuple.Create(next, now, d + 1));
            }
        }
        return dist;
    }


    static Scanner sc = new Scanner();
}
