class Solver
{
    public void Solve()
    {
        //Solve Code Here
        int n = Cin, u = Cin - 1, v = Cin - 1;
        var nodes = new Node[n];
        for (var i = 0; i < nodes.Length; i++) nodes[i] = new Node(i);
        for (int i = 0; i < n - 1; i++) nodes[Cin - 1].AddConnection(nodes[Cin - 1]);
        SearchA(nodes[v], 0);
        var state = SearchT(nodes[u], 0);
        Coutln(state.Item1 - 1);
    }

    //Other Functions Here

    private Tuple<int, int> SearchT(Node node, int dist)
    {
        node.DistT = dist;
        if (node.DistA - node.DistT <= 0) return Tuple.Create(-1, 0);

        Tuple<int, int> max = Tuple.Create(node.DistA, node.DistA - node.DistT);
        foreach (var n in node.Connections)
        {
            if (n.DistT != -1) continue;
            var state = SearchT(n, dist + 1);
            if (max.Item1 < state.Item1) max = state;
        }

        return max;
    }

    private void SearchA(Node node, int dist)
    {
        node.DistA = dist;
        foreach (var n in node.Connections)
        {
            if (n.DistA != -1) continue;
            SearchA(n, dist + 1);
        }
    }
}

