    public class Tree
    {
        public class Node
        {
            public List<int> Children = new List<int>();
        }

        public Tree(int nodeNumber)
        {
            Nodes = new Node[nodeNumber];
            for (int i = 0; i < Nodes.Length; i++)
            {
                Nodes[i] = new Node();
                Connenters = new List<int[]>();
            }
        }

        /// <summary>
        /// 頂点の配列。それぞれの頂点には、一つの親と、複数の子がある
        /// </summary>
        public Node[] Nodes { get; }

        public List<int[]> Connenters { get; }

        public void Connent(int to, int from)
        {
            Connenters.Add(new int[3] { to, from, 0 });
            Nodes[to].Children.Add(from);
            Nodes[from].Children.Add(to);
        }
    }

    static void Main()
    {
        int[] Nuv = ReadInts;
        int N = Nuv[0];
        int u = Nuv[1]-1;
        int v = Nuv[2]-1;

        Tree tree = new Tree(N);

        for (int i = 0; i < N-1; i++)
        {
            var con = ReadInts;
            tree.Connent(con[0]-1, con[1]-1);
        }

        int[] takahashi = new int[N];
        takahashi[u] = 0;
        int[] aoki = new int[N];
        aoki[v] = 0;


        DFS(u, 0, tree, new HashSet<int>() {u }, takahashi);
        DFS(v, 0, tree, new HashSet<int>() { v }, aoki);

        int ans = 0;
        for (int i = 0; i < N; i++)
        {
            if (aoki[i] > takahashi[i])
            {
                ans = Max(aoki[i] - 1,ans);
            }
        }

        WriteLine(ans);

    }

    public static void DFS(int start,int count,Tree tree,HashSet<int> done,int[] ans)
    {
        foreach(int child in tree.Nodes[start].Children)
        {
            if (!done.Contains(child))
            {
                ans[child] = count + 1;
                done.Add(child);
                DFS(child, count + 1, tree, done,ans);
            }
        }
    }



