using System;
using System.Linq;
using System.Collections.Generic;

namespace Algorithm
{
    class Program
    {
        static void Main(string[] args)
        {
            var l = Console.ReadLine().Split().Select(int.Parse).ToArray();
            int N = l[0], v = l[1], u = l[2];
            var tree = new List<List<int>>();
            for (var i = 0; i < N; i++)
                tree.Add(new List<int>());
            for (var i = 0; i < N-1; i++) {
               var x = Console.ReadLine().Split().Select(int.Parse).ToList();
               x[0]--;
               x[1]--;
               tree[x[0]].Add(x[1]);
               tree[x[1]].Add(x[0]);
            }

            var t = Bfs(tree, v-1);
            var s = Bfs(tree, u-1);

            var ans = 0;
            for (var i = 0; i < t.Length; i++) {
            //Console.WriteLine($"{t[i]} {s[i]}");
               if (t[i] < s[i])
                   ans = Math.Max(ans, s[i]-1);
            }

            Console.WriteLine(ans);
        }

        static int[] Bfs(List<List<int>> tree, int s) {
            var q = new Queue<int>();
            q.Enqueue(s);
            var ret = new int[tree.Count];

            while (q.Count > 0) {
               var  w = q.Dequeue();
               foreach (var d in tree[w]) {
                  if (ret[d] != 0 || d == s) continue;
                  ret[d] = ret[w] + 1;
                  q.Enqueue(d);
               }
            }

            return ret;
        }
    }
}

