            return Tuple.Create(minByItem, min);
        }
        public static IComparer<T> Reverse<T>(this IComparer<T> comparer) => Comparer<T>.Create((x, y) => comparer.Compare(y, x));
        public static Dictionary<TKey, int> GroupCount<TSource, TKey>(this IEnumerable<TSource> source, Func<TSource, TKey> keySelector) => source.GroupBy(keySelector).ToDictionary(g => g.Key, g => g.Count());
        public static Dictionary<TKey, int> GroupCount<TKey>(this IEnumerable<TKey> source) => source.GroupCount(i => i);
    }
    public class ConsoleReader { private string[] ReadLineSplit() => textReader.ReadLine().Split(Array.Empty<char>(), StringSplitOptions.RemoveEmptyEntries); private string[] line = Array.Empty<string>(); private int linePosition; private TextReader textReader; public ConsoleReader(TextReader tr) { textReader = tr; } public int Int => int.Parse(String); public int Int0 => Int - 1; public long Long => long.Parse(String); public double Double => double.Parse(String); public string String { get { if (linePosition >= line.Length) { linePosition = 0; line = ReadLineSplit(); } return line[linePosition++]; } } public class SplitLine { private string[] splited; public SplitLine(ConsoleReader cr) { splited = cr.ReadLineSplit(); cr.line = Array.Empty<string>(); } public int[] Int => String.Select(x => int.Parse(x)).ToArray(); public int[] Int0 => String.Select(x => int.Parse(x) - 1).ToArray(); public long[] Long => String.Select(x => long.Parse(x)).ToArray(); public double[] Double => String.Select(x => double.Parse(x)).ToArray(); public string[] String => splited; } public SplitLine Split => new SplitLine(this); public class RepeatReader : IEnumerable<ConsoleReader> { ConsoleReader cr; int count; public RepeatReader(ConsoleReader cr, int count) { this.cr = cr; this.count = count; } public IEnumerator<ConsoleReader> GetEnumerator() => Enumerable.Repeat(cr, count).GetEnumerator(); System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator(); public string[] String => this.Select(cr => cr.String).ToArray(); public int[] Int => this.Select(cr => cr.Int).ToArray(); public int[] Int0 => this.Select(cr => cr.Int - 1).ToArray(); public long[] Long => this.Select(cr => cr.Long).ToArray(); public double[] Double => this.Select(cr => cr.Double).ToArray(); } public RepeatReader Repeat(int count) => new RepeatReader(this, count); }
    public class Program
    {
        [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;
        public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
        static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc());

        #endregion
        public object Calc()
        {
            var N = cr.Int;
            var u = cr.Int0;
            var v = cr.Int0;
            var gb = new GraphBuilder(N, cr, N - 1, false);
            var takaTree = gb.ToTree(u);
            var aokiTree = gb.ToTree(v);

            if (takaTree[u].children.Length == 1 && takaTree[u].children[0] == v)
                return 0;

            var takaDepth = new int[N][];
            foreach (var g in takaTree.GroupBy(t => t.depth))
            {
                takaDepth[g.Key] = g.Select(t => t.index).ToArray();
            }

            var aokiDepth = new int[N][];
            foreach (var g in aokiTree.GroupBy(t => t.depth))
            {
                aokiDepth[g.Key] = g.Select(t => t.index).ToArray();
            }

            var takaTarget = new HashSet<int>(Enumerable.Range(0, N));
            for (int i = N - 1; i >= 0; i--)
            {
                if (takaDepth[i] != null)
                {
                    takaTarget.ExceptWith(takaDepth[i]);
                }
                if (aokiDepth[i] != null)
                {
                    if (aokiDepth[i].Any(d => takaTarget.Contains(d)))
                    {
                        return i - 1;
                    }
                }


            }

            return 1;
        }


        class GraphBuilder
        {
            private List<int>[] roots;
            private List<int>[] children;
            public GraphBuilder(int count, bool isOriented = true)
            {
                this.roots = new List<int>[count];
                this.children = new List<int>[count];
                for (int i = 0; i < count; i++)
                {
                    if (isOriented)
                    {
                        this.roots[i] = new List<int>();
                        this.children[i] = new List<int>();
                    }
                    else
                    {
                        this.roots[i] = this.children[i] = new List<int>();
                    }
                }
            }
            public GraphBuilder(int count, ConsoleReader cr, int edgeCount, bool isOriented = true) : this(count, isOriented)
            {
                for (int i = 0; i < edgeCount; i++)
                    this.Add(cr.Int - 1, cr.Int - 1);
            }
            public void Add(int from, int to)
            {
                children[from].Add(to);
                roots[to].Add(from);
            }
            public TreeNode[] ToTree(int root)
            {
                if (this.roots[0] != this.children[0]) throw new Exception("木には無向グラフをしたほうが良い");
                var res = new TreeNode[this.children.Length];
                res[root] = new TreeNode(root, -1, this.children[root].ToArray(), 0);

                var queue = new Queue<int>();
                foreach (var child in res[root].children)
                {
                    res[child] = new TreeNode(child, root, Array.Empty<int>(), 1);
                    queue.Enqueue(child);
                }

                while (queue.Count > 0)
                {
                    var from = queue.Dequeue();
                    if (res[from].root == -1)
                        res[from].children = this.children[from].ToArray();
                    else
                    {
                        var children = new List<int>(this.children[from].Count);
                        foreach (var c in this.children[from])
                            if (c != res[from].root)
                                children.Add(c);

                        res[from].children = children.ToArray();
                    }

                    foreach (var child in res[from].children)
                    {
                        res[child] = new TreeNode(child, from, Array.Empty<int>(), res[from].depth + 1);
                        queue.Enqueue(child);
                    }
                }

                return res;
            }

            public Node[] ToArray() =>
                Enumerable
                .Zip(roots, children, (r, c) => Tuple.Create(r, c))
                .Select((t, i) => new Node(i, t.Item1.ToArray(), t.Item2.ToArray()))
                .ToArray();
        }
        public class TreeNode : IEquatable<TreeNode>
        {
            public TreeNode(int i, int root, int[] children, int depth)
            {
                this.index = i;
                this.root = root;
                this.children = children;
                this.depth = depth;
            }
            public int index;
            public int root;
            public int[] children;
            public int depth;

            public override string ToString() => $"children: {string.Join(",", children)}";
            public override bool Equals(object obj)
            {
                if (obj is TreeNode)
                    return this.Equals((TreeNode)obj);
                else
                    return false;
            }
            public bool Equals(TreeNode other) => this.index == other.index;
            public override int GetHashCode() => this.index;
        }
        public class Node : IEquatable<Node>
        {
            public Node(int i, int[] roots, int[] children)
            {
                this.index = i;
                this.roots = roots;
                this.children = children;
            }
            public int index;
            public int[] roots;
            public int[] children;

            public override string ToString() => $"children: {string.Join(",", children)}";
            public override bool Equals(object obj)
            {
                if (obj is Node)
                    return this.Equals((Node)obj);
                else
                    return false;
            }
            public bool Equals(Node other) => this.index == other.index;
            public override int GetHashCode() => this.index;
        }



    }
}

