		VT<ll,ll>[] abl;
		MyIO.ReadLines(n-1,out abl);
		List<ll>[] g = MakeGraph(abl, -1);

		List<ll> oni = new List<ll>();
		bool[] visit1 = new bool[n];
		Func<ll,bool> dfs1 = null;
		dfs1 = (i)=>{
			if(visit1[i]) return false;
			if(i==v-1) return true;
			visit1[i] = true;
			bool ret = false;
			foreach (var e in g[i])
			{
				oni.Add(e);
				ret = dfs1(e);
				if(ret) {
					break;
				}else{
					oni.RemoveAt(oni.Count-1);
				}
			}
			return ret;
		};

		dfs1(u-1);

		bool[] visit2 = new bool[n];
		bool[] opath = new bool[n];
		foreach (var i in oni)
		{
			opath[i] = true;
		}

		if(g[u-1].Count==1&&oni.Count==1) {
			MyIO.WriteMulti(0);
			return;
		}
		if(g[u-1].Count==1&&oni.Count==2) {
			MyIO.WriteMulti(1);
			return;
		}
		visit2[oni[(oni.Count-1)/2]] = true;
		Func<ll,ll,ll,ll> dfs2 = null;
		dfs2 = (i,d,c)=>{
			visit2[i] = true;
			ll ret = d-2*c;
			foreach (var e in g[i])
			{
				if(visit2[e]) continue;
				if(opath[e]){
					Chmax(ref ret, dfs2(e,d+1,c+1));
				}else{
					Chmax(ref ret, dfs2(e,d+1,c));
				}
			}
			return ret;
		};

		ll ans = dfs2(u-1, oni.Count - oni.Count%2,0);

		MyIO.WriteMulti(ans);
	}



	public static long Gcd(long a, long b) {
	    var v = new[] { a, b };
	    while (v[1] != 0) v = new[] { v[1], v[0] % v[1] };
	    return v[0];
	}

	public static long Lcm(long a, long b) => a / Gcd(a, b) * b;

    public static List<long>[] MakeGraph(VT<long,long>[] inEdges, long shift=0){
        long lim = -1;
		foreach (var e in inEdges)
        {
            if(lim<e.Item1) lim = e.Item1;
            if(lim<e.Item2) lim = e.Item2;
        }
        List<long>[] ret = new List<long>[Math.Max(lim+shift+1,0)];
        if (ret.Length==0) return ret;
        for (int i = 0; i < ret.Length; i++) ret[i] = new List<long>();
		foreach (var e in inEdges)
        {
            ret[e.Item1+shift].Add(e.Item2+shift);
            ret[e.Item2+shift].Add(e.Item1+shift);
        }
        return ret;
    }










