            public override bool Equals(object obj)
            {
                if (obj is TreeNode)
                    return this.Equals((TreeNode)obj);
                else
                    return false;
            }
            public bool Equals(TreeNode other) => this.index == other.index;
            public override int GetHashCode() => this.index;
        }
