public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "bust" : "win"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        N = cr;
        u = cr.Int0;
        v = cr.Int0;
        gb = new GraphBuilder(N, cr, N - 1, false);
        takahashi = gb.ToTree(u);
        aoki = gb.ToTree(v);
        var d = takahashi[v].depth;
        if (takahashi[u].children.Length == 1)
        {
            if (d == 1) return 0;
        }

        int max = int.MinValue;
        for (int i = 0; i < N; i++)
        {
            if (takahashi[i].depth < aoki[i].depth)
                UpdateMax(ref max, aoki[aoki[i].root].depth);
        }
        return max;
    }

    TreeNode[] takahashi;
    TreeNode[] aoki;

    int N;
    int u;
    int v;
