        /// h行w列の整数の行列の入力
        /// </summary>
        public static void @in(long h, long w, out long[][] a)
        {
            a = new long[h][];
            for (long i = 0; i < h; i++) @in(out a[i]);
        }

        /// <summary>
        /// 1行に書かれた1つの小数の入力
        /// </summary>
        public static void @in(out double d) => d = double.Parse(String());

        /// <summary>
        /// 1行に書かれた小数の配列の入力
        /// </summary>
        public static void @in(out double[] dArr) => dArr = Split().Select(double.Parse).ToArray();
    }

    class Program
    {
        public static void Main(string[] args)
        {
            StreamWriter streamWriter = new StreamWriter(Console.OpenStandardOutput()) {AutoFlush = false};
            Console.SetOut(streamWriter);
            new Solver().Solve();
            Console.Out.Flush();
        }

        public static void Debug()
        {
            new Solver().Solve();
        }
    }

    class Solver
    {
        private long N;
        private long u;
        private long v;
        private long[] A;
        private long[] B;

        public void Solve()
        {
            @in(out N, out u, out v);
            @in(N - 1, out A, out B);

            HashSet<long>[] tree = new HashSet<long>[N + 1];
            for (int i = 0; i < N + 1; i++)
            {
                tree[i] = new HashSet<long>();
            }

            for (int i = 0; i < N - 1; i++)
            {
                tree[A[i]].Add(B[i]);
                tree[B[i]].Add(A[i]);
            }


            long[] tDiff = new long[N + 1];
            long[] aDiff = new long[N + 1];

            Queue<long> q = new Queue<long>();
            HashSet<long> memo = new HashSet<long>();
            tDiff[u] = 0;
            memo.Add(u);
            q.Enqueue(u);

            while (q.Count > 0)
            {
                var c = q.Dequeue();
                foreach (long l in tree[c])
                {
                    if (memo.Contains(l))
                    {
                        continue;
                    }

                    memo.Add(l);
                    q.Enqueue(l);
                    tDiff[l] = tDiff[c] + 1;
                }
            }

            q = new Queue<long>();
            memo = new HashSet<long>();
            aDiff[v] = 0;
            memo.Add(v);
            q.Enqueue(v);

            while (q.Count > 0)
            {
                var c = q.Dequeue();
                foreach (long l in tree[c])
                {
                    if (memo.Contains(l))
                    {
                        continue;
                    }

                    memo.Add(l);
                    q.Enqueue(l);
                    aDiff[l] = aDiff[c] + 1;
                }
            }

            long ans = 0;
            for (int i = 1; i <= N; i++)
            {
                if (aDiff[i] > tDiff[i])
                {
                    ans = aDiff[i];
                }
            }

            Console.WriteLine(ans - 1);
        }
    }
}

