    public static void Main()
    {
        int N, takahashi,aoki;
        new readint(out N, out takahashi, out aoki);
        List<int>[] map = new List<int>[N+1];
        for (int i = 0; i < N+1; i++)
        {
            map[i] = new List<int>();
        }
        for (int i = 0; i < N-1; i++)
        {
            int a, b;
            new readint(out a, out b);
            map[a].Add(b);
            map[b].Add(a);

        }

        int[] aokiDistance = new int[N+1];
        int[] takahashiDistance = new int[N + 1];

        //全探索
        Queue<int> takahashiPlace = new Queue<int>();
        Queue<int> aokiPlace = new Queue<int>();
        for (int i = 0; i < map[aoki].Count; i++)
        {
            aokiPlace.Enqueue(map[aoki][i]);
        }
        for (int i = 0; i < map[takahashi].Count; i++)
        {
            takahashiPlace.Enqueue(map[takahashi][i]);
        }

        while (aokiPlace.Count > 0)
        {
            int aokichouten = aokiPlace.Dequeue();
            int maxvalue = -1;
            for (int i = 0; i < map[aokichouten].Count; i++)
            {
                if (maxvalue < aokiDistance[map[aokichouten][i]]) maxvalue = aokiDistance[map[aokichouten][i]];
                if(aokiDistance[map[aokichouten][i]] ==0 && (map[aokichouten][i] != aoki))aokiPlace.Enqueue(map[aokichouten][i]);
            }
            aokiDistance[aokichouten]=++maxvalue;
        }
        while(takahashiPlace.Count > 0)
        {
            int takahashichouten = takahashiPlace.Dequeue();
            int maxvalue = -1;
            for (int i = 0; i < map[takahashichouten].Count; i++)
            {
                if (maxvalue < takahashiDistance[map[takahashichouten][i]]) maxvalue = takahashiDistance[map[takahashichouten][i]];
                if (takahashiDistance[map[takahashichouten][i]] == 0 && (map[takahashichouten][i] != takahashi)) takahashiPlace.Enqueue(map[takahashichouten][i]);
            }
            takahashiDistance[takahashichouten] = ++maxvalue;
        }

        long output = 0;
        for (int i = 1; i <= N; i++)
        {
            //スコア計算
            long score = 0;
            if (takahashiDistance[i] > aokiDistance[i]) continue;
            if (takahashiDistance[i] == aokiDistance[i]) score = aokiDistance[i];
            else
            {
                score = aokiDistance[i] - 1;
            }
            if (output < score)
            {
                output = score;
            }
        }
        Console.WriteLine(output);


    }
