namespace AtCoder.Contest.F
{
	static class Program
	{
		public static void Solve(Scanner cin)
		{
			var (n, u, v) = cin.ReadValue<int, int, int>();
			var (a, b) = cin.ReadValueArray<int, int>(n - 1);

			var connected = new List<List<int>>();
			var parent = new List<int>();
			var seen = new List<bool>();
			var depth = new List<int>();
			for (int i = 0; i < n; i++)
			{
				connected.Add(new List<int>());
				parent.Add(0);
				seen.Add(false);
				depth.Add(0);
			}
			for (int i = 0; i < n - 1; i++)
			{
				connected[a[i] - 1].Add(b[i] - 1);
				connected[b[i] - 1].Add(a[i] - 1);
			}
			var q = new Queue<int>();
			q.Enqueue(v - 1);
			parent[v - 1] = -1;
			seen[v - 1] = true;
			while (q.Count > 0)
			{
				var next = q.Dequeue();
				foreach (var e in connected[next])
				{
					if (seen[e]) continue;

					parent[e] = next;
					seen[e] = true;
					depth[e] = depth[next] + 1;
					q.Enqueue(e);
				}
			}

			for (int i = 0; i < n; i++)
			{
				seen[i] = false;
			}

			int takahashi = u - 1;
			int depthTakahashi = depth[u - 1];
			for (int i = 0; i < (depthTakahashi - 1) / 2; i++)
			{
				takahashi = parent[takahashi];
			}
			int maxdepth = depth[takahashi];

			q.Enqueue(takahashi);
			seen[takahashi] = true;

			while (q.Count > 0)
			{
				var next = q.Dequeue();
				foreach (var e in connected[next])
				{
					if (seen[e]) continue;
					if (e == parent[next]) continue;

					maxdepth = Math.Max(maxdepth, depth[e]);

					q.Enqueue(e);
				}
			}

			Console.WriteLine(maxdepth - 1);
		}

		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
			Console.SetOut(sw);
			var cin = new Scanner();
			Solve(cin);
			Console.Out.Flush();
		}
	}

	class Scanner
	{
		string[] s;
		int i;

		char[] separator = new char[] { ' ' };

		public Scanner()
		{
			s = new string[0];
			i = 0;
		}

		public string Read() => ReadString();

		public string ReadString()
		{
			if (i < s.Length) return s[i++];
			string st = Console.ReadLine();
			while (st == "") st = Console.ReadLine();
			s = st.Split(separator, StringSplitOptions.RemoveEmptyEntries);
			if (s.Length == 0) return ReadString();
			i = 0;
			return s[i++];
		}

		public string[] ReadStringArray(int N)
		{
			string[] Array = new string[N];
			for (int i = 0; i < N; i++)
			{
				Array[i] = ReadString();
			}
			return Array;
		}

		public int ReadInt()
		{
			return int.Parse(ReadString());
		}

