using System;
using System.Collections.Generic;
using static Assistant.Input;
using static Assistant.Debug;
using System.Linq;
using Assistant;

namespace ABC148F
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = RInt;
            var u = RInt - 1;
            var v = RInt - 1;

            List<int>[] edges = new List<int>[N].Select(x => new List<int>()).ToArray();
            for (int i = 0; i < N - 1; i++)
            {
                var a = RInt - 1;
                var b = RInt - 1;
                edges[a].Add(b);
                edges[b].Add(a);
            }

            Queue<int> queA = new Queue<int>();
            queA.Enqueue(v);
            int[] distA = new int[N].Select(x => -1).ToArray();
            distA[v] = 0;
            while (queA.Count > 0)
            {
                int now = queA.Dequeue();
                foreach (var to in edges[now])
                {
                    if (distA[to] == -1)
                    {
                        distA[to] = distA[now] + 1;
                        queA.Enqueue(to);
                    }
                }
            }
            Draw1D(distA);

            Queue<int> queT = new Queue<int>();
            queT.Enqueue(u);
            int ans = 0;
            int[] distT = new int[N].Select(x => -1).ToArray();
            distT[u] = 0;
            while (queT.Count > 0)
            {
                int a = queT.Count;
                for (int i = 0; i < a; i++)
                {
                    int now = queT.Dequeue();
                    if (distA[now] <= distT[now])
                    {
                        ans = Math.Max(distA[now], ans);
                        continue;
                    }

                    if (edges[now].Count == 1) // 戻る
                    {
                        int to = edges[now][0];

                        distT[to] = distT[now] + 1;
                        queT.Enqueue(to);
                    }
                    else
                    {
                        foreach (var to in edges[now])
                        {
                            if (distT[to] != -1) continue;

                            distT[to] = distT[now] + 1;
                            queT.Enqueue(to);
                        }
                    }

                }
            }
            Draw1D(distT);

            Console.WriteLine(ans);
        }


    }


