	public static void Solve_F() {
		long  n, u, v;
		MyIO.ReadMulti(out n, out u, out v);
		VT<ll,ll>[] abl;
		MyIO.ReadLines(n-1,out abl);
		List<ll>[] g = MakeGraph(abl, -1);



		if(g[u-1].Count==1&&g[u-1][0]==v-1) {
			MyIO.WriteMulti(0);
			return;
		}
		if(g[u-1].Count==1&&g[g[u-1][0]].Contains(v-1)) {
			MyIO.WriteMulti(1);
			return;
		}
		bool[] visit1 = new bool[n];
		bool[] visit2 = new bool[n];
		Dictionary<ll,ll> d1 = new Dictionary<ll, ll>();
		if (g[u-1].Count==1) d1[u-1] = 0;
		Dictionary<ll,ll> d2 = new Dictionary<ll, ll>();
		if (g[v-1].Count==1) d2[v-1] = 0;
		Func<ll,ll,ll> dfs1 = null;
		dfs1 = (i,d)=>{
			visit1[i] = true;
			ll cnt = 0;
			foreach (var e in g[i])
			{
				if(visit1[e]) continue;
				dfs1(e,d+1);
				cnt++;
			}
			if(cnt==0) d1[i] = d;
			return 0;
		};
		Func<ll,ll,ll> dfs2 = null;
		dfs2 = (i,d)=>{
			visit2[i] = true;
			ll cnt = 0;
			foreach (var e in g[i])
			{
				if(visit2[e]) continue;
				dfs2(e,d+1);
				cnt++;
			}
			if(cnt==0) d2[i] = d;
			return 0;
		};
		dfs1(u-1, 0);
		dfs2(v-1, 0);

		ll ans = 0;
		foreach (var kv in d2)
		{
			ll x = kv.Value-d1[kv.Key];
			if(0<x) Chmax(ref ans, kv.Value-x%2);
		}

		MyIO.WriteMulti(ans);
	}



	public static long Gcd(long a, long b) {
	    var v = new[] { a, b };
	    while (v[1] != 0) v = new[] { v[1], v[0] % v[1] };
	    return v[0];
	}

	public static long Lcm(long a, long b) => a / Gcd(a, b) * b;

    public static List<long>[] MakeGraph(VT<long,long>[] inEdges, long shift=0){
        long lim = -1;
		foreach (var e in inEdges)
        {
            if(lim<e.Item1) lim = e.Item1;
            if(lim<e.Item2) lim = e.Item2;
        }
        List<long>[] ret = new List<long>[Math.Max(lim+shift+1,0)];
        if (ret.Length==0) return ret;
        for (int i = 0; i < ret.Length; i++) ret[i] = new List<long>();
		foreach (var e in inEdges)
        {
            ret[e.Item1+shift].Add(e.Item2+shift);
            ret[e.Item2+shift].Add(e.Item1+shift);
        }
        return ret;
    }










