    /// <summary>
    /// 最小共通祖先を求める
    /// </summary>
    public class LowestCommonAncestor
    {
        public int N;

        public List<int>[] G;

        public int[] vs;    // オイラーツアーの配列 長さは 2 * N - 1
        public int[] depth; // オイラーツアーの配列のノードの深さ 長さは 2 * N - 1

        public int[] id;               // 最初にそのノードを訪れたときにvs[]にメモしたインデックス 長さは N
        public int[] depthByInitIndex; // もともとのノード配列のインデックスから深さを求めるための配列 長さは N

        public SegTreeForLca segTreeForLca;

        public int[] pathIndexes;
        public bool  found;

        public LowestCommonAncestor(int N)
        {
            this.N = N;

            G = new List<int>[N];

            for (int i = 0; i < N; i++)
            {
                G[i] = new List<int>();
            }

            pathIndexes = new int[N];
            for (int i = 0; i < N; i++)
            {
                pathIndexes[i] = -1;
            }
        }

        public void AddEdge(int a, int b)
        {
            G[a].Add(b);
            G[b].Add(a);
        }

        public void Build(int root)
        {
            vs    = new int[2 * N - 1];
            depth = new int[2 * N - 1];
            id    = new int[N];

            int k = 0;

            Dfs(root, -1, 0, ref k);

            segTreeForLca = new SegTreeForLca(depth);

            depthByInitIndex = new int[N];
            for (int i = 0; i < 2 * N - 1; i++)
            {
                depthByInitIndex[vs[i]] = depth[i];
            }
        }

        /// <summary>
        /// ノードuとノードvの最小共通祖先のノードのインデックスを得る
        /// ここでいうインデックスは、元の配列のインデックスであり、オイラーツアーの方ではないので注意
        /// </summary>
        public int GetLcaIndex(int u, int v)
        {
            int left  = Math.Min(id[u], id[v]);
            int right = Math.Max(id[u], id[v]);

            int eulerIndex = segTreeForLca.QueryWithIndex(left, right + 1).Index;

            return vs[eulerIndex];
        }

        /// <summary>
        /// ノードuとノードvの距離を求める
        /// </summary>
        public int GetDistance(int u, int v)
        {
            int lcaIndex = GetLcaIndex(u, v);
            return depthByInitIndex[u] + depthByInitIndex[v] - 2 * depthByInitIndex[lcaIndex];
        }

        public void Dfs(int v, int parent, int d, ref int k)
        {
            if (!found)
            {
                pathIndexes[d] = v;

                if (v == Program.u)
                {
                    found = true;
                }
            }

            id[v]      = k;
            vs[k]      = v;
            depth[k++] = d;

            for (int i = 0; i < G[v].Count; i++)
            {
                if (G[v][i] != parent)
                {
                    Dfs(G[v][i], v, d + 1, ref k);
                    vs[k]      = v;
                    depth[k++] = d;

                    if (!found)
                    {
                        pathIndexes[d] = v;
                    }
                }
            }
        }
    }

    /// <summary>
    /// 
    /// SegmentTree LCA用
    /// QueryでIndexを取得できるタイプ
    /// 
    /// Dataは0始まりになっている
    /// ノードiの子ノードの番号は 2 * i + 1 / 2 * i + 2
    /// ノードiの親ノードの番号は (i - 1) / 2
    /// 
    ///        0
    ///    1       2
    ///  3   4   5   6
    /// 
    /// </summary>
    public class SegTreeForLca
    {
        private int   leafCount; // 葉の数
        private int[] data;

        private const int identity = int.MaxValue; // 単位元

        private int[] leafIndexes; // そのノードが採用している値の葉のindex

        public SegTreeForLca(IList<int> initialValues)
        {
            int initialValuesLength = initialValues.Count;

            leafCount = 1;

            while (leafCount < initialValuesLength) leafCount <<= 1;

            data        = new int[2 * leafCount - 1];
            leafIndexes = new int[2 * leafCount - 1];

            for (int i = 0; i < initialValuesLength; i++)
            {
                data[i + leafCount - 1]        = initialValues[i];
                leafIndexes[i + leafCount - 1] = i;
            }

            for (int i = initialValuesLength; i < leafCount; i++)
            {
                data[i + leafCount - 1]        = identity;
                leafIndexes[i + leafCount - 1] = i;
            }

            for (int i = leafCount - 2; i >= 0; i--)
            {
                if (data[i * 2 + 1] < data[i * 2 + 2])
                {
                    data[i]        = data[i * 2 + 1];
                    leafIndexes[i] = leafIndexes[i * 2 + 1];
                }
                else
                {
                    data[i]        = data[i * 2 + 2];
                    leafIndexes[i] = leafIndexes[i * 2 + 2];
                }
            }
        }

        /// <summary>
        /// ツリーの更新なしに i番目の葉の値を更新する
        /// </summary>
        public void AssignWithoutUpdate(int i, int value)
        {
            data[i + leafCount - 1] = value;
        }

        /// <summary>
        /// i番目の葉の値を更新し、ツリーを更新する
        /// </summary>
        public void Update(int i, int value)
        {
            int now = i + leafCount - 1;
            data[now] = value;

            while (now > 0)
            {
                now = (now - 1) / 2;

                if (data[now * 2 + 1] < data[now * 2 + 2])
                {
                    data[now]        = data[now * 2 + 1];
                    leafIndexes[now] = leafIndexes[now * 2 + 1];
                }
                else
                {
                    data[now]        = data[now * 2 + 2];
                    leafIndexes[now] = leafIndexes[now * 2 + 2];
                }
            }
        }

        /// <summary>
        /// i番目の葉の値を取得する
        /// </summary>
        public int Look(int i)
        {
            return data[i + leafCount - 1];
        }

        // QueryでIndexを取得したいときに使う
        public struct SegNodePair
        {
            public int Data;
            public int Index;

            public SegNodePair(int data, int index)
            {
                Data  = data;
                Index = index;
            }
        }

        public SegNodePair QueryWithIndex(int a, int b)
        {
            return QueryWithIndexInternal(a, b, 0, 0, leafCount);
        }

        /// <summary>
        /// [a, b) の区間に対するクエリについて
        /// ノード i (区間 [l, r) 担当) が答える
        /// </summary>
        private SegNodePair QueryWithIndexInternal(int a, int b, int i, int l, int r)
        {
            if (r <= a || b <= l) return new SegNodePair(identity, -1);
            if (a <= l && r <= b) return new SegNodePair(data[i], leafIndexes[i]);

            SegNodePair leftPair = QueryWithIndexInternal(a, b, i * 2 + 1,
                l, (l + r) / 2);
            SegNodePair rightPair = QueryWithIndexInternal(a, b, i * 2 + 2,
                (l + r) / 2, r);

            if (leftPair.Data < rightPair.Data)
            {
                return leftPair;
            }
            else
            {
                return rightPair;
            }
        }
    }

