using N = System.Int32;

public class Solver
{
    public void Solve()
    {
        N n = ri;
        N u = ri - 1;
        N v = ri - 1;
        List<List<N>> path = new List<List<N>>();
        for (int i = 0; i < n; i++)
        {
            path.Add(new List<N>());
        }
        N a = 0;
        N b = 0;
        for (int i = 0; i < n - 1; i++)
        {
            a = ri - 1;
            b = ri - 1;
            path[a].Add(b);
            path[b].Add(a);
        }
        N[] dis_t = new N[n];
        N[] dis_a = new N[n];
        bool[] stack = new bool[n];
        bool[] seen = new bool[n];
        seen[u] = true;
        stack[u] = true;
        while (stack.Any(x => x == true))
        {
            for (int i = 0; i < n; i++)
            {
                if (!stack[i]) continue;
                stack[i] = false;
                foreach (var to in path[i])
                {
                    if (!seen[to])
                    {
                        dis_t[to] = dis_t[i] + 1;
                        seen[to] = true;
                        stack[to] = true;
                    }
                }
            }
        }
        seen = new bool[n];
        seen[v] = true;
        stack[v] = true;
        while (stack.Any(x => x == true))
        {
            for (int i = 0; i < n; i++)
            {
                if (!stack[i]) continue;
                stack[i] = false;
                foreach (var to in path[i])
                {
                    if (!seen[to])
                    {
                        dis_a[to] = dis_a[i] + 1;
                        seen[to] = true;
                        stack[to] = true;
                    }
                }
            }
        }
        N p = 0;
        for(int i = 0; i < n; i++)
        {
            if (dis_a[i] > dis_t[i] && p < dis_a[i]) p = dis_a[i];
        }
        Write(p - 1);
    }




