	public static long Gcd(long a, long b) {
	    var v = new[] { a, b };
	    while (v[1] != 0) v = new[] { v[1], v[0] % v[1] };
	    return v[0];
	}

	public static long Lcm(long a, long b) => a / Gcd(a, b) * b;

    public static List<long>[] MakeGraph(VT<long,long>[] inEdges, long shift=0){
        long lim = -1;
		foreach (var e in inEdges)
        {
            if(lim<e.Item1) lim = e.Item1;
            if(lim<e.Item2) lim = e.Item2;
        }
        List<long>[] ret = new List<long>[Math.Max(lim+shift+1,0)];
        if (ret.Length==0) return ret;
        for (int i = 0; i < ret.Length; i++) ret[i] = new List<long>();
		foreach (var e in inEdges)
        {
            ret[e.Item1+shift].Add(e.Item2+shift);
            ret[e.Item2+shift].Add(e.Item1+shift);
        }
        return ret;
    }










