        public List<int>[] Nodes { get; }

        public List<int[]> Connenters { get; }

        public void Connent_NodeIdStartsFrom0(int to, int from)
        {
            Connenters.Add(new int[3] { to, from, 0 });
            Nodes[to].Add(from);
            Nodes[from].Add(to);
        }
    }

    static void Main()
    {
        int[] Nuv = ReadInts;
        int N = Nuv[0];
        int u = Nuv[1]-1;
        int v = Nuv[2]-1;

        Tree tree = new Tree(N);

        for (int i = 0; i < N-1; i++)
        {
            var con = ReadInts;
            tree.Connent_NodeIdStartsFrom0(con[0]-1, con[1]-1);
        }

        int[] takahashi = new int[N];
        takahashi[u] = 0;
        int[] aoki = new int[N];
        aoki[v] = 0;


        DFSTree(u, 0, tree, new HashSet<int>() {u }, takahashi);
        DFSTree(v, 0, tree, new HashSet<int>() { v }, aoki);

        int ans = 0;
        for (int i = 0; i < N; i++)
        {
            if (aoki[i] > takahashi[i])
            {
                ans = Max(aoki[i] - 1,ans);
            }
        }

        WriteLine(ans);

    }

    /// <summary>
    /// 0始まりのノードになってる? 初期位置はdoneとansに入ってる? 
    /// </summary>
    /// <param name="start">初期位置</param>
    /// <param name="count">歩数</param>
    /// <param name="tree"></param>
    /// <param name="done">確認済みのノードを入れる</param>
    /// <param name="ans">ノードidがindex 移動カウントがvalue</param>
    public static void DFSTree(int start,int count,Tree tree,HashSet<int> done,int[] ans)
    {

        foreach(int child in tree.Nodes[start])
        {
            if (!done.Contains(child))
            {
                ans[child] = count + 1;
                done.Add(child);
                DFSTree(child, count + 1, tree, done,ans);
            }
        }
    }



}

