public class Dlca<T>{
	private bool[] b;
	private int[][] h;
	private int[] de;
	private int o;
	private List<T>[] li;
	public Dlca(List<T>[] li,bool bo){
		this.li=li;
		int n=li.Length;
		o=(int)Log(n-1,2)+1;
		de=new int[n];
		de[0]=-1;
		h=new int[o][];
		b=new bool[n];
		h[0]=new int[n];
		if(bo){
			if(li.GetType()==typeof(List<int>[])){Fd1(1,0);}
			else{Fd2(1,0);}
		}
		else{
			if(li.GetType()==typeof(List<int>[])){for(int i=1;i<n;i++){if(!b[i]){Fd1(i,0);}}}
			else{for(int i=1;i<n;i++){if(!b[i]){Fd2(i,0);}}}
		}
		for(int i=1;i<o;i++){
			h[i]=new int[n];
			for(int j=1;j<n;j++){h[i][j]=h[i-1][h[i-1][j]];}
		}
	}
	private void Fd1(int a,int f){
		b[a]=true;
		de[a]=f;
		for(int i=0;i<li[a].Count;i++){
			int j=(int)(object)li[a][i];
			if(!b[j]){h[0][j]=a;Fd1(j,f+1);}
		}
	}
	private void Fd2(int a,int f){
		b[a]=true;
		de[a]=f;
		for(int i=0;i<li[a].Count;i++){
			int j=((Tuple<int,int>)(object)li[a][i]).Item1;
			if(!b[j]){h[0][j]=a;Fd2(j,f+((Tuple<int,int>)(object)li[a][i]).Item2);}
		}
	}
	public int Lca(int a,int b){
		if(de[a]>de[b]){int c=a;a=b;b=c;}
		for(int i=o-1;de[a]!=de[b];i--){if(de[h[i][b]]>=de[a]){b=h[i][b];}}
		if(a==b){return a;}
		for(int i=o-1;i>=0;i--){if(h[i][a]!=h[i][b]){a=h[i][a];b=h[i][b];}}
		return h[0][a];
	}
	public int Di(int a,int b){
		int l=Lca(a,b);
		return l!=0?de[a]+de[b]-(de[l]<<1):int.MinValue;
	}
}

