class Tree
{
    public List<int>[] Input(int n, HLTree H, int indexed = 1)
    {
        Scanner cin = new Scanner();
        var ret = new List<int>[n];
        for (int i = 0; i < ret.Length; i++) ret[i] = new List<int>();
        for (int i = 0; i < n - 1; i++)
        {
            int a = cin.nextint - indexed;
            int b = cin.nextint - indexed;
            ret[a].Add(b);
            ret[b].Add(a);
            H.AddEdge(a, b);
        }
        return ret;
    }
    public int BFS(List<int>[] T, int s, out int[] dist, int ban, IEnumerable<int> multi = null)
    {
        int n = T.Length;
        dist = new int[n];
        for (int i = 0; i < dist.Length; i++) dist[i] = -1;

        var Q = new Queue<int>();
        if (multi == null) { Q.Enqueue(s); dist[s] = 0; }
        else foreach (var v in multi) { Q.Enqueue(v); dist[v] = 0; }
        int id = s;

        while (Q.Count > 0)
        {
            var u = Q.Dequeue();
            if (u == ban) continue;
            foreach (var v in T[u])
            {
                if (dist[v] >= 0) continue;
                dist[v] = dist[u] + 1;
                id = v;
                Q.Enqueue(v);
            }
        }
        return id;
    }
