        }

        public void Solve(ConsoleInput cin)
        {
            N = cin.ReadInt;
            var u = cin.ReadInt - 1;
            var v = cin.ReadInt - 1;
            to = new List<int>[N];
            for (int i = 0; i < N; i++)
            {
                to[i] = new List<int>();
            }
            for (int i = 0; i < N - 1; i++)
            {
                var A = cin.ReadInt - 1;
                var B = cin.ReadInt - 1;
                to[A].Add(B);
                to[B].Add(A);
            }
            var distU = CalcDist(u);
            var distV = CalcDist(v);

            var mx = 0;
            for (int i = 0; i < N; i++)
            {
                if (distU[i] < distV[i])
                {
                    mx = Max(mx, distV[i]);
                }
            }
            var ans = mx - 1;
            Console.WriteLine(ans);
        }

        int N;
        List<int>[] to;

        int[] CalcDist(int p)
        {
            var dist = new int[N];
            dfs(ref dist, p, 0, -1);
            return dist;
        }

        void dfs(ref int[] dist, int p, int d, int pp)
        {
            dist[p] = d;
            foreach (var next in to[p])
            {
                if (next != pp)
                {
                    dfs(ref dist, next, d + 1, p);
                }
            }
        }
    }

