        u--; v--;
        var G = new Graph<int>(N);
        for (int i = 0; i < N-1; i++)
        {
            var r = RInts(x=>int.Parse(x)-1);
            G.Add(r[0], r[1]);
            G.Add(r[1], r[0]);
        }
        var usedv = Enumerable.Repeat(-1, N).ToArray();
        var usedu = Enumerable.Repeat(-1, N).ToArray();
        var que = new Queue<(int, int)>();
        que.Enqueue((v, 0));
        usedv[v] = 0;
        while (que.Count > 0)
        {
            var t = que.Dequeue();
            var n = t.Item1;
            var c = t.Item2;
            foreach (var i in G[n])
            {
                if (usedv[i] != -1) continue;
                usedv[i] = c + 1;
                que.Enqueue((i, c + 1));
            }
        }
        que = new Queue<(int, int)>();
        que.Enqueue((u, 0));
        usedu[u] = 0;
        while (que.Count > 0)
        {
            var t = que.Dequeue();
            var n = t.Item1;
            var c = t.Item2;
            foreach (var i in G[n])
            {
                if (usedu[i] != -1) continue;
                if (usedu[i] > usedv[i]) continue;
                usedu[i] = c + 1;
                que.Enqueue((i, c + 1));
            }
        }
        int ans = 0;
        for (int i = 0; i < N; i++)
        {
            if (usedu[i]==-1||usedv[i] <= usedu[i]) continue;
