     }

     static int nibunn(int[] array, int target)
     {
         int L = 0;
         int R = array.Length; 

         while(R - L > 1)
         {
             int mid = (R + L) / 2;
             if (array[mid] > target) L = mid;
             else R = mid;
         }
         return L;
     }


