     readonly static int MAX_N = 100005;
     private static int n;
     private static List<int> dist;
     private static List<int>[] Tree = new List<int>[MAX_N];
     public static void Main(string[] args)
     {
         int[] inputs = ReadLineToInts();
         n = inputs[0];
         int u = inputs[1];
         int v = inputs[2];
         u--;
         v--;
         for (int i = 0; i < n; i++)
         {
             Tree[i] = new List<int>();
         }
         for (int i = 0; i < n-1; i++)
         {
             int[] inputs2 = ReadLineToInts();
             int a = inputs2[0];
             int b = inputs2[1];
             a--;
             b--;
             Tree[a].Add(b);
             Tree[b].Add(a);
         }
         List<int> distU = calcDist(u);
         List<int> distV = calcDist(v);
         int mx = 0;
         for (int i = 0; i < n; i++)
         {
             if (distU[i] < distV[i])
             {
                 mx = Math.Max(mx, distV[i]);
             }
         }
         int ans = mx - 1;
         WriteLine(ans);
     }

     static List<int> calcDist(int node)
     {
         dist = new List<int>();
         for (int i = 0; i < n; i++)
         {
             dist.Add(0);
         }
         dfs(node);
         return dist;
     }

     static void dfs(int v, int d = 0, int p = -1)
     {
         dist[v] = d;
         foreach (var c in Tree[v])
         {
             if (c == p) continue;
             dfs(c, d+1, v);
         }
     }
