    class Solver
    {
        private long N;
        private long u;
        private long v;
        private long[] A;
        private long[] B;

        public void Solve()
        {
            @in(out N, out u, out v);
            @in(N - 1, out A, out B);

            HashSet<long>[] tree = new HashSet<long>[N + 1];
            for (int i = 0; i < N + 1; i++)
            {
                tree[i] = new HashSet<long>();
            }

            for (int i = 0; i < N - 1; i++)
            {
                tree[A[i]].Add(B[i]);
                tree[B[i]].Add(A[i]);
            }


            long[] t = new long[N + 1];
            long[] a = new long[N + 1];

            Queue<long> q = new Queue<long>();
            HashSet<long> memo = new HashSet<long>();
            t[u] = 0;
            memo.Add(u);
            q.Enqueue(u);

            while (q.Count > 0)
            {
                var c = q.Dequeue();
                foreach (long l in tree[c])
                {
                    if (memo.Contains(l))
                    {
                        continue;
                    }

                    memo.Add(l);
                    q.Enqueue(l);
                    t[l] = t[c] + 1;
                }
            }

            q = new Queue<long>();
            memo = new HashSet<long>();
            a[v] = 0;
            memo.Add(v);
            q.Enqueue(v);

            while (q.Count > 0)
            {
                var c = q.Dequeue();
                foreach (long l in tree[c])
                {
                    if (memo.Contains(l))
                    {
                        continue;
                    }

                    memo.Add(l);
                    q.Enqueue(l);
                    a[l] = a[c] + 1;
                }
            }

            long ans = 0;
            for (int i = 1; i <= N; i++)
            {
                if (a[i] > t[i])
                {
                    ans = Max(a[i], ans);
                }
            }

            Console.WriteLine(ans - 1);
        }
    }
}

