func main() {
  io := IO{bufio.NewReaderSize(os.Stdin,100),bufio.NewWriterSize(os.Stdout,100)}
  n,u,v := io.Next3Ints()
  u,v = u-1,v-1
  g := make([][]int,n)
  for i:=0;i<n-1;i++ {
    a,b := io.Next2Ints()
    a,b = a-1,b-1
    g[a] = append(g[a],b)
    g[b] = append(g[b],a)
  }
  du := dfs(g,u)
  dv := dfs(g,v)
  x := 0
  for i:=0;i<n;i++ {
    if len(g[i]) > 1 { continue }
    if du[i] < dv[i] && x < dv[i] { x = dv[i] }
  }
  fmt.Println(x-1)
}
func dfs(g [][]int,s int) []int {
  x := make([]int,len(g))
  var rec func(int,int,int)
  rec = func(v,p,d int) {
    x[v] = d
    for _,u := range g[v] {
      if u == p { continue }
      rec(u,v,d+1)
    }
  }
  rec(s,-1,0)
  return x
}

type IO struct {
  reader *bufio.Reader
  writer *bufio.Writer
}
func(io *IO) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := io.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(io *IO) Println(a ...interface{}) (int,error) {
  return fmt.Fprintln(io.writer,a...)
}
func(io *IO) Flush() error {
  return io.writer.Flush()
}
func(io *IO) Next2Ints() (int,int) {
  s := strings.Fields(io.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  return x,y
}
func(io *IO) Next3Ints() (int,int,int) {
  s := strings.Fields(io.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  z,_ := strconv.Atoi(s[2])
  return x,y,z
}

