import (
  "bufio"
  "fmt"
  "os"
  "strconv"
  "strings"
)

func main() {
  io := IO{bufio.NewReaderSize(os.Stdin,100),bufio.NewWriterSize(os.Stdout,100)}
  n,u,v := io.Next3Ints()
  u,v = u-1,v-1
  g := make([][]int,n)
  for i:=0;i<n-1;i++ {
    a,b := io.Next2Ints()
    a,b = a-1,b-1
    g[a] = append(g[a],b)
    g[b] = append(g[b],a)
  }
  lca := NewLca(g)
  x := 0
  for i:=0;i<n;i++ {
    if len(g[i]) > 1 { continue }
    du := lca.Distance(u,i)
    dv := lca.Distance(v,i)
    if du < dv && x < dv { x = dv }
  }
  fmt.Println(x-1)
}

type Lca struct { g [][]int;par [][]int;depth []int }
func NewLca(g [][]int) Lca {
  k := 0
  n := len(g)
  for (1<<uint(k)) < n { k++ }
  par := make([][]int,k)
  for i:=0;i<k;i++ { par[i] = make([]int,n) }
  depth := make([]int,n)
  lca := Lca{g,par,depth}
  lca.Par()
  return lca
}
func(l Lca) Dfs(v,p,d int) {
  l.par[0][v] = p
  l.depth[v] = d
  for _,u := range l.g[v] {
    if u != p { l.Dfs(u,v,d+1) }
  }
}
func(l Lca) Par() {
  l.Dfs(0,-1,0)
  n := len(l.depth)
  for k:=0;k<len(l.par)-1;k++ {
    for i:=0;i<n;i++ {
      if l.par[k][i] < 0 { l.par[k+1][i] = -1;continue }
      l.par[k+1][i] = l.par[k][l.par[k][i]]
    }
  }
}
func(l Lca) Distance(x,y int) int {
  return l.depth[x]+l.depth[y]-2*l.depth[l.Of(x,y)]
}
func(l Lca) Of(x,y int) int {
  if l.depth[x] > l.depth[y] { x,y = y,x }
  for k:=0;k<len(l.par);k++ {
    if ((l.depth[y]-l.depth[x])>>uint(k))&1 == 1 {
      y = l.par[k][y]
    }
  }
  if x == y { return x }
  for k:=len(l.par)-1;k>-1;k-- {
    if l.par[k][x] != l.par[k][y] {
      x,y = l.par[k][x],l.par[k][y]
    }
  }
  return l.par[0][x]
}

type IO struct {
  reader *bufio.Reader
  writer *bufio.Writer
}
func(io *IO) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := io.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(io *IO) Println(a ...interface{}) (int,error) {
  return fmt.Fprintln(io.writer,a...)
}
func(io *IO) Flush() error {
  return io.writer.Flush()
}
func(io *IO) Next2Ints() (int,int) {
  s := strings.Fields(io.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  return x,y
}
func(io *IO) Next3Ints() (int,int,int) {
  s := strings.Fields(io.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  z,_ := strconv.Atoi(s[2])
  return x,y,z
}

