		t.AddEdge(a, b)
	}
	distT := t.DFS(u)
	distA := t.DFS(v)
	distTtoX := distA[u]
	q := []int{u}
	var c int
	isVisited := make([]bool, len(t.g))
	for len(q) != 0 {
		c, q = q[0], q[1:]
		isVisited[c] = true
		chmax(&distTtoX, distA[c])
		for _, next := range t.g[c] {
			if isVisited[next] { continue }
			if !(distT[next] < distA[next]) { continue }
			q = append(q, next)
		}
	}
	ans := distTtoX - 1
	pln(ans)
}

