func calc(g [][]int, v int) []int {
	n := len(g)
	ds := make([]int, n)
	for i := 0; i < n; i++ {
		ds[i] = -1
	}
	ds[v] = 0

	var dfs func(v, p int)
	dfs = func(v, p int) {
