  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func WriteIntVec(A []int) {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

func Dijkstra(G [][]int, v int) []int {
  N := len(G)
  D := make([]int, N)
  for i := range D {
    D[i] = -1
  }
  D[v] = 0
  Q := make([]int, N)
  Q[0] = v
  pos := 1
  for _, q := range Q {
    for _, adj := range G[q] {
      if 0 <= D[adj] { continue }
      D[adj] = D[q] + 1
      Q[pos] = adj
      pos++
    }
  }
  return D
}

func Max(A []int) int {
  max := A[0]
  for _, a := range A {
    if max < a { max = a }
  }
  return max
}

