    G[a] = append(G[a], b)
    G[b] = append(G[b], a)
  }
  T := Dijkstra(G, u)
  A := Dijkstra(G, v)
  D := make([]int, N)
  for i := range D {
    if A[i] < T[i] { continue }
    if T[i] == A[i] { D[i] = A[i] }
    if T[i] < A[i] { D[i] = A[i] - 1 }
  }
  Write(Max(D))
  Output()
}

