		sp = prt[sp]
		mp++
	}

	// bottom path
	bp := int((mp - 1) / 2)
	sp = u
	for i := 0; i < bp; i++ {
		sp = prt[sp]
	}

	// calc depth
	cd(sp, 0)
	fmt.Println(mp - bp + md - 1)

	//fmt.Println(ps)
	//fmt.Println(prt)
	//fmt.Println(mp)
	//fmt.Println(bp, sp)
	//fmt.Println(md)
}

func cd(sp, depth int) {
	if depth > md {
		md = depth
	}
	for _, cp := range ps[sp] {
		if cp == prt[sp] {
			continue
		}
		cd(cp, depth+1)
	}
}

func dfs(p, fp int) {
	prt[p] = fp
	for _, cp := range ps[p] {
		if cp == fp {
			continue
		}
		dfs(cp, p)
	}
}

