func (lca *Lca) init(n, r int, edges [][]Edge) {
	parents := make([][]int, 32)
	for i := 0; i < 32; i++ {
		parents[i] = make([]int, n)
	}
	lca.depth = make([]int, n)
	lca.parents = parents
	lca.dfs(r, -1, 0, edges)
	for i := 1; i < 32; i++ {
		for j := 0; j < n; j++ {
			lca.parents[i][j] = -1
			if lca.parents[i-1][j] == -1 {
				continue
			}
			lca.parents[i][j] = lca.parents[i-1][lca.parents[i-1][j]]
		}
	}
}

func (lca *Lca) dfs(i, p, h int, edges [][]Edge) {
	lca.depth[i] = h
	lca.parents[0][i] = p
	for _, e := range edges[i] {
		if e.to == p {
			continue
		}
		lca.dfs(e.to, i, h+1, edges)
	}
}

func (lca *Lca) get(u, v int) int {
	if lca.depth[u] > lca.depth[v] {
		u, v = v, u
	}
	h := lca.depth[v] - lca.depth[u]
	for i := 0; i < 32; i++ {
		if h>>uint(i)&1 == 1 {
			v = lca.parents[i][v]
		}
	}
	if u == v {
		return u
	}
	for i := 30; i >= 0; i-- {
		if lca.parents[i][u] == lca.parents[i][v] {
			continue
		}
		u = lca.parents[i][u]
		v = lca.parents[i][v]
	}
	return lca.parents[0][u]
}

