package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

var n, u, v int
var ps [][]int // 隣接頂点の保持
var prt []int  // 深さ優先探索における親頂点の保持
var md int

func main() {
	fmt.Scan(&n, &u, &v)
	// 頂点番号をリストのインデックスと対応させる為、それぞれ1減算する
	// こうすることで、後の繰り返し処理が色々と楽に記述できる
	u--
	v--

	var sc = bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	ps = make([][]int, n)
	for i := 0; i < n-1; i++ {
		sc.Scan()
		a, _ := strconv.Atoi(sc.Text())
		sc.Scan()
		b, _ := strconv.Atoi(sc.Text())
		// 頂点番号をリストのインデックスと対応させる為、それぞれ1減算する
		// こうすることで、後の繰り返し処理が色々と楽に記述できる
		a--
		b--
		// 頂点aとbは双方向に移動可能なので
		ps[a] = append(ps[a], b) // 頂点aの隣接頂点リストに頂点bを追加する
		ps[b] = append(ps[b], a) // 頂点bの隣接頂点リストに頂点aを追加する
	}

	// 頂点uとvが同じ場所で始まる場合、青木君の移動回数は0で終わる
	if u == v {
		fmt.Println(0)
		return
	}

	// make parent
	// 頂点vを根とする深さ優先探索を行う
	prt = make([]int, n)
	prt[v] = -1
	dfs(v, -1)

	// check min path
	// 頂点uを始点として頂点vを終点とする最短コストの経路を求める
	var mp int
	sp := u
	for sp != v { // uとvが同じ頂点になるまで繰り返す
		sp = prt[sp] // 現在の始点と隣接する頂点を次の始点にする
		mp++         // 頂点間の移動コストを加算する（1固定）
	}

	// bottom path
	// uとvが同じ葉に存在し移動中にかち合うケースを最低移動回数とする
	bp := int((mp - 1) / 2)
	// uとvを結ぶ最短経路における中間頂点を求める
	sp = u
	for i := 0; i < bp; i++ {
		sp = prt[sp] // 現在の始点の親を新たな始点にする
	}

	// calc depth
	// 中間頂点を起点とする最深頂点の深度を求める（
	cd(sp, 0)

	// mp: 頂点uを始点として頂点vを終点とする最短経路のコスト
	// bp: 頂点uとvそれぞれが最短で合流するよう動いたときのuの最短コスト
	// -----> vから出発した青木君は高橋君の動き方を把握してるので最短手で追い詰めようとする。
	// md: 頂点uとvを結ぶ最短経路上の中間頂点を起点としたときの最深頂点の深度（追加コスト）
	// -----> uから出発した高橋君は逃げ場所として一番遠いところを目指す。
	// mp - bp + md - 1: 頂点uから出発した高橋君を、頂点vから出発した青木君が捕まえるのに必要な移動回数
	fmt.Println(mp - bp + md - 1)
}

// cd は親頂点の木prtを活用して、始点spから見た最深頂点を探索し、その最大深度をmdに設定する
func cd(sp, depth int) {
	if depth > md { // 現在の最大深度より深い深度が確認できた場合
		md = depth // 最大深度を更新する
	}
	for _, cp := range ps[sp] { // 始点spの各隣接頂点spに対して
		if cp == prt[sp] { // 隣接点が始点の親である場合はパスする
			continue
		}
		cd(cp, depth+1) // 深度を一つ上げ、隣接頂点を始点とする深度調査を行う
	}
}

// dfs は深さ優先探索（再帰あり）で親頂点の木prtを形成する
func dfs(p, fp int) {
	prt[p] = fp // 頂点pの親頂点fpを登録する

	for _, cp := range ps[p] { // 頂点pの隣接点cpに対して
		if cp == fp { // 頂点pと親頂点fpが同じ場合はパスする
			continue
		}
		dfs(cp, p) // 同じように深さ優先探索を繰り返す
	}
}

