		G[a] = append(G[a], b)
		G[b] = append(G[b], a)
	}

	// u: 高橋, v: 青木
	for _, nid := range G[v] {
		if nid == u && len(G[u]) == 1 {
			fmt.Println(0)
			return
		}
	}

	dfs(v, 0)

	ans := 0
	for i := 0; i < n; i++ {
		ChMax(&ans, steps[i])
	}
	fmt.Println(ans - 1)
}

func dfs(cid, step int) {
	visited[cid] = true
	steps[cid] = step

	for _, nid := range G[cid] {
		if visited[nid] {
			continue
		}
		dfs(nid, step+1)
	}
}

// ChMax accepts a pointer of integer and a target value.
// If target value is LARGER than the first argument,
//	then the first argument will be updated by the second argument.
func ChMax(updatedValue *int, target int) bool {
	if *updatedValue < target {
		*updatedValue = target
		return true
	}
	return false
}

