//NewBridge is
func NewBridge(a, b *Node) (bridge *Bridge) {
	bridge = &Bridge{}
	bridge.edges = [...]Edge{{node: a, Bridge: bridge}, {node: b, Bridge: bridge}}
	a.edges = append(a.edges, &bridge.edges[1])
	b.edges = append(b.edges, &bridge.edges[0])
	return
}

