func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(true)
	n, u, v := r.nextInt(),r.nextInt(),r.nextInt()

	nodes:=make([]Node, n+1)
	for i := 1; i <= n; i++ {
		nodes[i] = Node{id: i}
	}
	for i, end := 1, n-1; i <= end; i++ {
		r.Scan(true)
		NewBridge(&nodes[r.nextInt()], &nodes[r.nextInt()])
	}

	type stk struct {
		pre *Node
		node *Node
		level int
		istarget bool
	}
	stack :=make([]stk, 0, n)
	stack = append(stack, stk{node:&nodes[v]})
	ulevel :=0
	for len(stack) > 0{
		cur:=&stack[0]
		stack=stack[1:]

		if cur.node.id == u {
			ulevel = cur.level			
		}

		target:=cur.istarget || cur.node.id == u
		nextlevel:=cur.level+1
		for _,edge:=range cur.node.edges{

			if edge.node == cur.pre {				
				continue
			}
			edge.node.parent = cur.node			
			stack = append(stack, stk{node:edge.node, pre:cur.node, istarget:target, level:nextlevel})

		}
	}
	{
		cur:=&nodes[u]
		for i:=(ulevel-1)/2;i>0;i--{
			cur = cur.parent 
		}
		u=cur.id
	}
	stack =make([]stk, 0, n)
	stack = append(stack, stk{node:&nodes[v]})
	ans:=0
	for len(stack) > 0{
		cur:=&stack[0]
		stack=stack[1:]

		target:=cur.istarget || cur.node.id == u
		if target{
			ans = cur.level
		}
		nextlevel:=cur.level+1
		for _,edge:=range cur.node.edges{

			if edge.node == cur.pre {				
				continue
			}
			edge.node.parent = cur.node			
			stack = append(stack, stk{node:edge.node, pre:cur.node, istarget:target, level:nextlevel})

		}
	}

	fmt.Fprintln(stdout, ans-1)
}

