func f(n int, x int, nexts [][]int) []int {
	d := make([]int, n)
	for i := 0; i < n; i++ {
		d[i] = 10000000
	}
	d[x] = 0
	q := []int{x}
	for len(q) > 0 {
		current := q[0]
		q = q[1:]
		for _, next := range nexts[current] {
			if d[current]+1 < d[next] {
				q = append(q, next)
				d[next] = d[current] + 1
			}
		}
	}
	return d
}

