type Tree struct {
	n      int
	edges  [][]Edge
	dt, da []int
}

func (tr *Tree) init(n int) {
	edges := make([][]Edge, n)
	for i := 0; i < n; i++ {
		edges[i] = make([]Edge, 0)
	}
	tr.n = n
	tr.edges = edges
}

func (tr *Tree) addEdge(i int, e Edge) {
	tr.edges[i] = append(tr.edges[i], e)
}

