void main(string[] args) {
  long N, u, v;
  readf(" %d %d %d ", &N, &u, &v);
  --u; --v;

  auto E = new long[][](N);
  foreach (i; 0..N-1) {
    long a, b;
    readf(" %d %d ", &a, &b);
    --a; --b;
    E[a] ~= b;
    E[b] ~= a;
  }

  auto level    = new long[](N);
  auto parent   = new long[](N);
  auto children = new long[][](N);
  auto dist     = new long[](N);

  long setlevel(size_t x, long l, long p = -1) {
    if (p != -1) {
      parent[x] = p;
    }
    level[x] = l;

    long maxdist;
    foreach (e; E[x]) {
      if (e != p) {
        maxdist.amax(setlevel(e, l+1, x) + 1);
        children[x] ~= e;
      }
    }
    dist[x] = maxdist;
    return maxdist;
  }

  parent[] = -1;
  level[]  = -1;
  setlevel(u, 0);

  long ans = level[v] <= 2? 0: (level[v]-1)/2;

  u = v;
  foreach (i; 0..ans+1) u = parent[u];

  if (level[v]%2 == 0) {
    u = parent[u];
    ++ans;
  }

  parent[] = -1;
  level[]  = -1;
  setlevel(u, 0);

  long aoki_branch = v;
  while (parent[aoki_branch] != u) {
    aoki_branch = parent[aoki_branch];
  }

  long taka_branch = -1;
  foreach (c; children[u]) {
    if (c == aoki_branch) continue;
    if (taka_branch == -1 || dist[taka_branch] < dist[c]) {
      taka_branch = c;
    }
  }
  if (taka_branch != -1) {
    ans += dist[taka_branch]+1;
  }
  ans.writeln;
}

