void main()
{
    long N, U, V;
    scan(N, U, V);
    U--, V--;
    auto G = new long[][](N);
    foreach (_; 0 .. N - 1)
    {
        long A, B;
        scan(A, B);
        A--, B--;
        G[A] ~= B;
        G[B] ~= A;
    }

    if (G[U].length == 1 && G[U][0] == V)
    {
        writeln(0);
        return;
    }

    void bfs1(ref long[] leave, ref long[] dist, long v)
    {
        DList!long S;
        S.insertBack(v);
        dist[] = -1;
        dist[v] = 0;
        leave[] = true;
        while (!S.empty)
        {
            long u = S.front;
            S.removeFront;
            foreach (w; G[u])
                if (dist[w] == -1)
                {
                    dist[w] = dist[u] + 1;
                    S.insertBack(w);
                    leave[u] = false;
                }
        }
    }

    auto du = new long[](N);
    auto l = new long[](N);
    auto dv = new long[](N);
    bfs1(l, du, U);
    bfs1(l, dv, V);
