auto solve(long N, long u, long v, long[] A, long[] B) {
    auto nodes = iota(0, N + 1).map!(i => new Node(i)).array;
    auto edges = chain(
        iota(N - 1).map!(i => new Edge(A[i], B[i])),
        iota(N - 1).map!(i => new Edge(B[i], A[i])),
    ).array;

    auto tree = new Graph!(Node, Edge)(nodes, edges);
    tree.constructTree(v);

    auto uDepth = tree.nodes[u].depth;

    auto n = tree.nodes[u];
    foreach (_; 0 .. (uDepth - 1) / 2) {
        n = n.parent;
    }

    long subTreeDepth = 0;

    void dig(Node node, long depth) {
        subTreeDepth = max(subTreeDepth, depth);
        foreach (c; tree.childrenFrom(node)) {
            dig(c, depth + 1);
        }
    }

    dig(n, 0);

    auto ans = subTreeDepth + (uDepth - 1) / 2;
    if (uDepth % 2 == 0)
        ans++;

    return ans;
}


