}



class Edge {
    long from;
    long to;

    this(long from, long to) {
        this.from = from;
        this.to = to;
    }
}

class Node {
    alias id this;
    long id;
    Node parent;
    long depth;
    bool isRoot;

    this(long id) { this.id = id; }
}


class Graph(NodeT = Node, EdgeT = Edge) {
    // from range
    this(NodeT[] nodes, EdgeT[] edges) {
        this.nodes = nodes;
        this.edges = edges;
        this.adj = new AdjacencyList(nodes.length);

        foreach (ref dests; adj)
            dests = make!EdgeList;

        foreach (e; edges) {
            adj[e.from].insert(e);
        }
    }

    auto destsFrom(long from) {
        return adj[from][].map!(e => nodes[e.to]);
    }

    auto edgesFrom(long from) {
        return adj[from][];
    }

    enum isTree =
        __traits(hasMember, NodeT, "isRoot")
        && __traits(hasMember, NodeT, "parent")
        && __traits(hasMember, NodeT, "depth");

    static if (isTree) {
        NodeT root;
        long maxDepth;

        auto childrenFrom(long from) {
            return adj[from][]
                .map!(e => nodes[e.to])
                .filter!(n => n.id != nodes[from].parent.id);
        }

        void constructTree(long root) {
            auto visited = new bool[](nodes.length);

            void dig(NodeT parent) {
                visited[parent] = true;

                foreach (n; destsFrom(parent)) {
                    if (visited[n])
                        continue;
                    n.isRoot = false;
                    n.parent = parent;
                    n.depth = parent.depth + 1;
                    maxDepth = max(maxDepth, n.depth);
                    dig(n);
                }
            }

            auto rootNode = nodes[root];
            this.root = rootNode;
            maxDepth = 0;
            rootNode.isRoot = true;
            rootNode.parent = null;
            rootNode.depth = 0;
            dig(rootNode);
        }
    }

    private:
    alias EdgeList = SList!EdgeT;
    alias AdjacencyList = EdgeList[];
    NodeT[] nodes;
    EdgeT[] edges;
    AdjacencyList adj;
}

