struct Tree
{
    Node[] nodes;
    int[int] m_deepest, m_depth;
    struct Node
    {
        int label;
        int[] neighbor;
        int[] children;
        int parent;
    }
    int deepest(int label)
    {
        if (auto p = label in m_deepest)
            return *p;
        if (nodes[label].children.empty)
            return m_deepest[label] = 0;
        return m_deepest[label] = nodes[label].children.map!(_=>deepest(_)).reduce!max+1;
    }
    int depth(int label)
    {
        if (auto p = label in m_depth)
            return *p;
        if (nodes[label].parent == label)
            return m_depth[label] = 0;
        return m_depth[label] = depth(nodes[label].parent) + 1;
    }
}
int moves(int distance, int room)
{
    stderr.writefln("moves(%d, %d)", distance, room);
    if (distance == 0)
        return 0;
    return (distance - 1) + room;
}

