class tree:
  def __init__(self, N, v):
    self.__N = N
    self.__a = [ver(i) for i in range(N+1)]
    self.__root = v

  def find_root(self, x):
    if self.__a[x].get_p() == -1:
      return x
    else:
      return self.__find(self.__a[x].get_p())

  def leaves(self):
    res = []
    for i, var in enumerate(self.__a):
      if not var.get_c():
        res.append(i)
    return res

  def add_(self, x, y):
    self.__a[x].add_c(y)
    self.__a[y].add_c(x)

  def change_root(self, v, d):
    self.__a[v].set_d(d)
    d += 1
    for i in self.__a[v].get_c():
      self.__a[i].set_p(self.__a[i].pop_c(v)) 
      self.change_root(i, d)

  def show_p(self):
    res = []
    for i in self.__a:
      res.append(i.get_p())
    return res

  def show_d(self):
    res = []
    for i in self.__a:
      res.append(i.get_d())
    return res

