def BFS(g, s, e):
    d = 1
    q = [s]
    visited = set()
    visited.add(s)
    if s == e:
        return 0

    while len(q) != 0:
        qs = len(q)
        for _ in range(qs):
            qpop = q[0]
            q = q[1:]
            for v in g[qpop]:
                if v == e:
                    return d
                if v not in visited:
                    q.append(v)
                    visited.add(v)
        d += 1

    return d


def DFS(g, taka, e, aoki, visited, af):
    visited.add(taka)
    if taka == aoki:
        af = 1
    if taka == e and af == 0:
        return 1
    for node in g[taka]:
        if node not in visited:
            if DFS(g, node, e, aoki, visited, af):
                return 1
    if taka == aoki and af == 1:
        af = 0
    return 0


def taka(g, s):
    visited = set()
    visited.add(s)
    q = [s]
    d = 0
    distanceTable = {}

    while len(q) != 0:
        d += 1
        # distanceTable[d] = []
        qs = len(q)
        for _ in range(qs):
            qpop = q[0]
            q = q[1:]
            if len(g[qpop]) == 1 and list(g[qpop])[0] in visited:
                # print("reached:")
                # print(qpop)
                distanceTable[qpop] = d-1
            else:
                for v in g[qpop]:
                    if v not in visited:
                        q.append(v)
                        visited.add(v)

    return distanceTable


