def BFS(g, s, e):
    d = 1
    q = [s]
    visited = set()
    visited.add(s)
    if s == e:
        return 0

    while (len(q) != 0):
        qs = len(q)
        for _ in range(qs):
            for v in g[q[0]]:
                if v == e:
                    return d
                if v not in visited:
                    q.append(v)
                    visited.add(v)
                q = q[1:]
            d += 1

    return d


