def dfs(N, L, s, node = None, blocks = None):
    depth = [-1] * N

    stack = [(0, s)]
    while stack:
        d, p = stack.pop()
        depth[p] = d

        if blocks is not None:
            if d == 0:
                depth[p] = -1
            else:
                if d == blocks[p]:
                    continue

                if node is not None and p in node:
                    depth[p] =  d + 2 * ((blocks[p] - d) // 2)
                    continue

        for q in L[p]:
            if blocks is not None:
                if blocks[q] < d + 1:
                    continue

            if depth[q] != -1:
                continue
            stack.append((d + 1, q))
    return depth


def main():
    N, u, v = read_values()
    u -= 1
    v -= 1
    L = [set() for _ in range(N)]
    for _ in range(N - 1):
        A, B = read_values()
        A -= 1
        B -= 1
        L[A].add(B)
        L[B].add(A)

    node = {i for i in range(N) if len(L[i]) == 1} 
    depth_A = dfs(N, L, v)
    depth_T = dfs(N, L, u, node, depth_A)

