	let n: usize = s.next().unwrap().parse().unwrap();
	let aoki = s.next().unwrap().parse::<usize>().unwrap() - 1;
	let takh = s.next().unwrap().parse::<usize>().unwrap() - 1;
	let mut edges = vec![vec![]; n];
	for _ in 0..n - 1 {
		let a = s.next().unwrap().parse::<usize>().unwrap() - 1;
		let b = s.next().unwrap().parse::<usize>().unwrap() - 1;
		edges[a].push(b);
		edges[b].push(a);
	}
	let tree = Tree::new(&edges, takh);
	let ans = edges.iter().enumerate().fold(0, |r, (i, l)|{
		if l.len() == 1 {
			let a = tree.lca(aoki, i);
			if tree.depth[aoki] - tree.depth[a] < tree.depth[a] {
				return std::cmp::max(r, tree.depth[i] - 1);
			}
		}
		r
	});
	println!("{:?}", ans);
}

struct Tree {
	parent: Vec<Vec<Option<usize>>>,
	depth: Vec<i32>,
}

impl Tree {
	fn new(edges: &Vec<Vec<usize>>, root: usize) -> Self {
		let n = edges.len();
		let log = (n as f64).log(2.).floor() as usize;
		let mut parent = vec![vec![None; n]; log + 1];
		let mut depth = vec![0; n];
		let mut st = std::collections::VecDeque::new();
		st.push_front((root, None, 0));
		while let Some((v, p, d)) = st.pop_back() {
			parent[0][v] = p;
			depth[v] = d;
			for e in edges[v].iter() {
				if *e != p.unwrap_or(std::usize::MAX) {
					st.push_back((*e, Some(v), d + 1));
				}
			}
		}
		for k in 0..parent.len() - 1 {
			for v in 0..n {
				if let Some(p) = parent[k][v] {
					parent[k + 1][v] = parent[k][p];
				}
			}
		}
		Tree { parent: parent, depth: depth }
	}

	fn lca(&self, u: usize, v: usize) -> usize {
		let (mut u, mut v) = if self.depth[u] > self.depth[v] { (v, u) } else { (u, v) };
		for k in 0..self.parent.len() {
			if ((self.depth[v] - self.depth[u]) >> k) & 1 != 0 {
				v = self.parent[k][v].unwrap();
			}
		}
		if u == v {
			u
		} else {
			for k in (0..self.parent.len()).rev() {
				if self.parent[k][u] != self.parent[k][v] {
					u = self.parent[k][u].unwrap();
					v = self.parent[k][v].unwrap();
				}
			}
			self.parent[0][u].unwrap()
		}
	}
}

