use std::collections::VecDeque;

fn bfs(adj: &Vec<Vec<usize>>, dist: &mut Vec<i64>, start: usize) {
  dist[start] = 0;
  let mut q = VecDeque::new();
  q.push_back(start);
  while let Some(v) = q.pop_front() {
    let d = dist[v];
    for &next in &adj[v] {
      if dist[next] < d {
        continue;
      }
      dist[next] = d + 1;
      q.push_back(next);
    }
  }
}

