fn make_tree(
    cur_idx: usize,
    parent_idx: usize,
    edges: &Vec<Vec<usize>>,
    tree: &mut Vec<Vec<usize>>,
    parent_dict: &mut HashMap<usize, usize>,
) {
    for child_idx in edges[cur_idx].iter() {
        if *child_idx == parent_idx {
            continue;
        }
        tree[cur_idx].push(*child_idx);
        parent_dict.insert(*child_idx, cur_idx);
        make_tree(*child_idx, cur_idx, edges, tree, parent_dict);
    }
}

fn topological_dfs(cur_idx: usize, tree: &Vec<Vec<usize>>, result: &mut Vec<usize>) {
    for child_idx in tree[cur_idx].iter() {
        result.push(*child_idx);
        topological_dfs(*child_idx, tree, result);
    }
}

fn get_depth_dfs(
    cur: usize,
    parent: usize,
    cur_depth: usize,
    depth: &mut Vec<usize>,
    tree: &Vec<Vec<usize>>,
) {
    depth[cur] = cur_depth;
    for &to in tree[cur].iter() {
        if to == parent {
            continue;
        }
        get_depth_dfs(to, cur, cur_depth + 1, depth, tree);
    }
}

fn main() {
    let v = read_vec::<usize>();
    let (n, u, v) = (v[0], v[1] - 1, v[2] - 1);
    let mut edges: Vec<Vec<usize>> = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let v = read_vec::<usize>();
        let (a, b) = (v[0] - 1, v[1] - 1);
        edges[a].push(b);
        edges[b].push(a);
    }

    let mut tree: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut parent_dict: HashMap<usize, usize> = HashMap::new();
    let root = v;
    make_tree(root, n, &edges, &mut tree, &mut parent_dict);
    let mut topological_sorted_indexes = vec![root];
    topological_dfs(root, &tree, &mut topological_sorted_indexes);

    let mut depth = vec![0; n];
    get_depth_dfs(root, root, 0, &mut depth, &tree);
    // debug!(depth);

    let mut depth_children = vec![0; n];
    for &ti in topological_sorted_indexes.iter().rev() {
        depth_children[ti] = depth[ti];
        for &ci in tree[ti].iter() {
            depth_children[ti] = max(depth_children[ti], depth_children[ci]);
        }
    }

    let mut most_depth = depth_children[u];
    let mut cur = u;
    let mut dist = 0;
    loop {
        let parent = parent_dict[&cur];
        dist += 1;
        cur = parent;
        if dist >= depth[parent] {
            break;
        }
        most_depth = max(most_depth, depth_children[cur]);
    }
    println!("{}", most_depth - 1);
}

