fn shortest_path(s: usize, g: usize, edges: &Vec<Vec<usize>>) -> Vec<usize> {
    let mut queue: VecDeque<usize> = VecDeque::new();
    queue.push_back(s);
    let mut visited: HashSet<usize> = HashSet::new();
    let mut prev = vec![edges.len(); edges.len()];
    visited.insert(s);
    while !queue.is_empty() {
        let target = queue.pop_front().unwrap();
        for edge in &edges[target] {
            if !visited.contains(edge) {
                prev[*edge] = target;
                queue.push_back(*edge);
                visited.insert(*edge);
            }
        }
    }
    let mut path: Vec<usize> = Vec::new();
    let mut i = g;
    while i != edges.len() {
        path.push(i);
        i = prev[i];
    }
    path.reverse();
    path
}

fn count(idx: usize, path: &Vec<usize>, edges: &Vec<Vec<usize>>, visited: &mut HashSet<usize>) -> usize {
    let mut ans = 0;
    visited.insert(idx);
    for edge in &edges[idx] {
        if !visited.contains(edge) && !path.contains(edge) {
            ans = max(ans, count(*edge, path, edges, visited) + 1);
            visited.insert(*edge);
        }
    }
    ans
}

fn main() {
    let (n, u, v) = input_tuple_three();
    let mut edges: Vec<Vec<usize>> = Vec::new();
    for _ in 0..n {
        edges.push(Vec::new());
    }
    for _ in 0..(n-1) {
        let (a, b) = input_tuple();
        edges[(a - 1) as usize].push(b - 1);
        edges[(b - 1) as usize].push(a - 1);
    }
    let path = shortest_path(u - 1, v - 1, &edges);

    let mut visited: HashSet<usize> = HashSet::new();
    // println!("{:?}", path);

    let mut ans = 0;
    for i in 0..path.len() / 2 {
        // println!("{} {}", path[i], count(path[i], &path, &edges, &mut visited));
        let len = path.len() - 1 - i + count(path[i], &path, &edges, &mut visited) - 1;
        // println!("len = {}", len);
        ans = max(ans, len);
    }
    println!("{}", ans);
}

