use input::*;
use std::collections::VecDeque;

const TAKAHASHI: usize = 1;
const AOKI: usize = 2;

fn dfs(
    v: &Vec<Vec<usize>>,
    map: &Vec<usize>,
    k: usize,
    d: usize,
    parent: usize,
    ans: &mut Vec<usize>,
) {
    if map[k] == TAKAHASHI {
        ans.push(d);
    }
    for z in &v[k] {
        if *z == parent {
            continue;
        }
        dfs(v, map, *z, d + 1, k, ans);
    }
}

fn main() {
    let (n, u, w): (usize, usize, usize);
    input!(n, u, w);
    let mut v = vec![vec![]; n];
    let mut map = vec![0; n];
    for _ in 0..n - 1 {
        let (a, b): (usize, usize);
        input!(a, b);
        v[a - 1].push(b - 1);
        v[b - 1].push(a - 1);
    }

    let mut qt = VecDeque::new();
    let mut qa = VecDeque::new();

    qt.push_front(u - 1);
    map[u - 1] = TAKAHASHI;
    qa.push_front(w - 1);
    map[w - 1] = AOKI;

    while !qt.is_empty() || !qa.is_empty() {
        if !qt.is_empty() {
            let buf = qt.pop_back().unwrap();
            for z in &v[buf] {
                if map[*z] == 0 {
                    map[*z] = TAKAHASHI;
                    qt.push_front(*z);
                }
            }
        }

        if !qa.is_empty() {
            let buf = qa.pop_back().unwrap();
            for z in &v[buf] {
                if map[*z] == 0 {
                    map[*z] = AOKI;
                    qa.push_front(*z);
                }
            }
        }
    }
    let mut ans = vec![];
    dfs(&v, &map, w - 1, 0, w - 1, &mut ans);
    let z=*ans.iter().max().unwrap();
    p(z-1);

}

