        let d = ((e.0).0 & 1) ^ (a_dist[e.1].0 & 1);
        ans = std::cmp::min(ans, a_dist[e.1].0 - 2 + d);
    }
    println!("{}", ans);
}

fn make_dist(graph: &Vec<Vec<usize>>, s: usize) -> Vec<(usize,usize)> {
    let mut dist = vec![(0, 0); graph.len()];
    dist[s] = (1, s);
    let mut stack = vec![s];
    while let Some(x) = stack.pop() {
        let c = dist[x].0 + 1;
        for &y in &graph[x] {
            if dist[y].0 == 0 {
                dist[y] = (c, x);
                stack.push(y);
            }
        }
    }
    dist
}

