#[derive(Debug)]
struct Graph {
    neighbors: Vec<Vec<usize>>,
    visited: Vec<bool>,
    parent: Vec<usize>,
    depth: Vec<usize>,
    height: Vec<usize>,
}

impl Graph {
    fn new(n: usize) -> Graph {
        Graph {
            neighbors: vec![Vec::new(); n],
            visited: vec![false; n],
            parent: vec![0; n],
            depth: vec![0; n],
            height: vec![0; n],
        }
    }
    fn add_edge(&mut self, i: usize, j: usize) {
        self.neighbors[i].push(j);
        self.neighbors[j].push(i);
    }
    fn dfs(&mut self, i: usize, p: usize, d: usize) -> Option<usize> {
        if self.visited[i] {
            return None;
        }
        self.visited[i] = true;
        self.parent[i] = p;
        self.depth[i] = d;
        let mut h = 0;
        for j in self.neighbors[i].clone() {
            if let Some(h1) = self.dfs(j, i, d + 1) {
                h = std::cmp::max(h, h1 + 1)
            }
        }
        self.height[i] = h;
        Some(h)
    }
}

