    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let taka: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
    let aoki: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
    let mut g = vec![vec![]; n];
    for _ in 1..n {
        let a: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        g[a].push(b);
        g[b].push(a);
    }
    let mut parent = vec![aoki; n];
    let mut depth = vec![0; n];
    let mut stack = vec![aoki];
    while let Some(v) = stack.pop() {
        for &u in g[v].iter() {
            if u != parent[v] {
                parent[u] = v;
                depth[u] = depth[v] + 1;
                stack.push(u);
            }
        }
    }
    let mut ans = 0;
    let mut up = 0;
    let mut now = taka;
    while depth[now] >= up + 3 {
        now = parent[now];
        up += 1;
        ans += 1;
    }
    if (up - depth[now]) % 2 == 0 {
        ans += 1;
    }
    let mut stack = vec![(now, parent[now], 0)];
    let mut max = 0;
    while let Some((v, p, d)) = stack.pop() {
        max = std::cmp::max(d, max);
        for &u in g[v].iter() {
            if u != p {
                stack.push((u, v, d + 1));
            }
        }
    }
    ans += max;
    println!("{}", ans);
