    }

    while !q.is_empty(){
        let (s, d) = q.pop_front().unwrap();

        let mut is_leaf = true;
        for to in adj[s].iter(){
            if diff2v[*to] != INF {
                continue;
            }
            is_leaf = false;

            diff2v[*to] = d + 1;

            if diff2u[*to] <= diff2v[*to]{
                continue;
            }

            q.push_back((*to, diff2v[*to]));
        }

        if is_leaf{
            // eprintln!()
            // eprintln!("s: {}, {}, {}", s, ans, diff2u[s]);
            chmax!(ans, diff2v[s] as isize ); // / 2 * 2);
        }
    }

    // eprintln!("{:?}", diff2u);
