    }
    let mut graph = vec![vec![]; n];
    for &(s, t) in &es {
        graph[s].push(t);
        graph[t].push(s);
    }
    let dist_t = f(&graph, pt);
    let dist_a = f(&graph, pa);
    let mut res = 0;
    for i in 0..n {
        if dist_t[i] < dist_a[i] {
            res = max(res, dist_a[i] - 1);
        }
    }
    println!("{}", res);
}

