    }

    let mut h = vec![vec![]; n];  // digraph from v
    {
        let mut stack = vec![v];
        let mut visited = vec![false; n];
        while let Some(v) = stack.pop() {
            if visited[v] { continue }
            visited[v] = true;
            for &u in g[v].iter() {
                if visited[u] { continue }
                h[v].push(u);
                stack.push(u)
            }
        }
    }

    let mut r = vec![vec![]; n];  // rev of h
    {
        for u in 0..n {
            for &v in h[u].iter() {
                r[v].push(u);
            }
        }
    }

    let mut line = vec![];
    {
        let mut u = u;
        while u != v {
            line.push(u);
            u = r[u][0];
        }
