fn read_line() -> String {
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).ok();
    buf
}

fn dfs(v: usize, g: &Vec<Vec<usize>>, memo: &mut Vec<i32>, s: i32) {
    if memo[v] >= 0 {
        return;
    }
    memo[v] = s;
    for t in g[v].iter() {
        dfs(*t, g, memo, s+1);
    }
}

fn dfs2(v: usize, g: &Vec<Vec<usize>>, memo: &Vec<i32>, visited: &mut Vec<bool>, s: i32) -> i32 {
    if memo[v] <= s {
        return memo[v];
    } else if visited[v] {
        return memo[v] - 1;
    }
    visited[v] = true;
    let mut res = s;
    for t in g[v].iter() {
        res = cmp::max(res, dfs2(*t, g, memo, visited, s+1));
    }
    res
}

fn main() {
    let line: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let n = line[0];
    let u = line[1] - 1;
    let v = line[2] - 1;

    let mut g = vec![Vec::new(); n];
    for i in 0..n-1 {
        let line: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
        let a = line[0] - 1;
        let b = line[1] - 1;
        g[a].push(b);
        g[b].push(a);
    }    
    let mut memo = vec![-1; n];
    dfs(v, &g, &mut memo, 0);
    let mut visited = vec![false; n];
    let ans = dfs2(u, &g, &memo, &mut visited, 0);
    println!("{}", ans);
}

use std::collections::HashSet;
use std::io::{stdin, Read};

macro_rules! parse {
    ($iter: ident) => {
        $iter.next().unwrap().parse().unwrap()
    };
    ($iter: ident,2) => {
        (parse!($iter), parse!($iter))
    };
    ($iter: ident,3) => {
        (parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident,4) => {
        (parse!($iter), parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident, $n: ident) => {
        (&mut $iter).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut iter = s.split_whitespace();
    let (n, u, v): (usize, usize, usize) = parse!(iter, 3);
    let u = u - 1;
    let v = v - 1;
    let mut tree: Vec<Vec<usize>> = vec![vec![]; n];
    for _ in 0..(n - 1) {
        let (a, b): (usize, usize) = parse!(iter, 2);
        tree[a - 1].push(b - 1);
        tree[b - 1].push(a - 1);
    }
    let mut du = vec![-1; n];
    let mut dv = vec![-1; n];
    du[u] = 0;
    dv[v] = 0;
    dfs(u, 1, &tree, &mut du);
    dfs(v, 1, &tree, &mut dv);
    let mut ret = 0;
    for i in 0..n {
        if du[i] < dv[i] {
            ret = std::cmp::max(ret, dv[i] - 1)
        }
    }
    println!("{}", ret);
}

fn dfs(cur: usize, curd: isize, tree: &Vec<Vec<usize>>, d: &mut Vec<isize>) {
    for &c in &tree[cur] {
        if d[c] == -1 {
            d[c] = curd;
            dfs(c, curd + 1, tree, d);
        }
    }
}

