trait IteratorExt: Iterator {
    fn toVec(self) -> Vec<Self::Item>;
}

impl<T: Iterator> IteratorExt for T {
    fn toVec(self) -> Vec<Self::Item> {
        self.collect()
    }
}

trait CharExt {
    fn toNum(&self) -> usize;
    fn toAlphabetIndex(&self) -> usize;
    fn toNumIndex(&self) -> usize;
}
impl CharExt for char {
    fn toNum(&self) -> usize {
        return *self as usize;
    }
    fn toAlphabetIndex(&self) -> usize {
        return self.toNum() - 'a' as usize;
    }
    fn toNumIndex(&self) -> usize {
        return self.toNum() - '0' as usize;
    }
}

trait VectorExt {
    fn joinToString(&self, s: &str) -> String;
}
impl<T: ToString> VectorExt for Vec<T> {
    fn joinToString(&self, s: &str) -> String {
        return self
            .iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join(s);
    }
}

trait UsizeExt {
    fn pow(&self, n: usize) -> usize;
}
impl UsizeExt for usize {
    fn pow(&self, n: usize) -> usize {
        return ((*self as u64).pow(n as u32)) as usize;
    }
}

fn main() {
    input! {
       n: usize,
       u:usize1,
       v:usize1,
       edges:[(usize1,usize1);n-1],
    }

    let mut map = vec![vec![]; n];
    let mut used: Vec<Option<usize>> = vec![None; n];
    for &(f, t) in &edges {
        map[f].push(t);
        map[t].push(f);
    }

    let mut ans: usize = 0;
    let mut kouho = VecDeque::new();
    kouho.push_back((u, 0));
    used[u] = Some(INF_USIZE);
    let mut dist = 0;
    while !kouho.is_empty() {
        let (p, depth) = kouho.pop_front().unwrap();
        for i in 0..map[p].len() {
            let next = map[p][i];
            if used[next].is_some() {
                continue;
            }
            used[next] = Some(p);
            kouho.push_back((next, depth + 1));
        }
    }

    mydbg!(dist, used);
    let mut path = vec![];
    let mut cur = v;
    path.push(cur);
    loop {
        mydbg!(cur);
        cur = used[cur].unwrap();
        if cur == INF_USIZE {
            break;
        }
        path.push(cur);
    }

    path.reverse();
    let b = path[(path.len()) / 2];
    mydbg!(path, b);
    let mut kouho = VecDeque::new();

    let mut canmove = vec![false; n];
    kouho.push_back((u, 0));
    canmove[u] = true;
    while !kouho.is_empty() {
        let (p, depth) = kouho.pop_front().unwrap();
        for i in 0..map[p].len() {
            let next = map[p][i];
            if canmove[next] {
                continue;
            }
            if next == b {
                continue;
            }
            canmove[next] = true;
            kouho.push_back((next, depth + 1));
        }
    }

    let mut kouho = VecDeque::new();
    let mut used2: Vec<Option<usize>> = vec![None; n];
    kouho.push_back((v, 0));
    used2[v] = Some(0);
    while !kouho.is_empty() {
        let (p, depth) = kouho.pop_front().unwrap();
        for i in 0..map[p].len() {
            let next = map[p][i];
            if used2[next].is_some() {
                continue;
            }
            used2[next] = Some(depth + 1);
            kouho.push_back((next, depth + 1));
        }
    }
    mydbg!(used2);

    let mut tmp = used2
        .iter()
        .map(|x| if x.is_some() { x.unwrap() } else { 0 })
        .zip(canmove)
        .filter(|&(_, x)| x)
        .toVec();

    tmp.sort_by_key(|x| x.1);
    tmp.reverse();
    mydbg!(tmp);
    ans = tmp[0].0.saturating_sub(1);
    echo!(ans);
}

use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let n_u_v = lines.next().unwrap().unwrap();
    let mut n_u_v = n_u_v.split_whitespace();
    let n = n_u_v.next().unwrap().parse::<usize>().unwrap();
    let u = n_u_v.next().unwrap().parse::<usize>().unwrap();
    let v = n_u_v.next().unwrap().parse::<usize>().unwrap();
    let mut vertices: Vec<Vec<usize>> = vec![vec![]; n + 1];
    for _ in 1..n {
        let a_b = lines.next().unwrap().unwrap();
        let mut a_b = a_b.split_whitespace();
        let a = a_b.next().unwrap().parse::<usize>().unwrap();
        let b = a_b.next().unwrap().parse::<usize>().unwrap();
        vertices[a].push(b);
        vertices[b].push(a);
    }

    let mut takahashi: Vec<usize> = vec![u];
    let mut is_takahashi: Vec<bool> = vec![false; n + 1];
    is_takahashi[u] = true;

    let mut aoki: Vec<usize> = vec![v];
    let mut is_aoki: Vec<bool> = vec![false; n + 1];
    is_aoki[v] = true;

    let mut ans = 0;
    while !takahashi.is_empty() {
        let mut next_takahashi: Vec<usize> = vec![];
        for &t in takahashi.iter() {
            is_takahashi[t] = false;
            for &next_t in vertices[t].iter() {
                if !is_aoki[next_t] {
                    is_takahashi[next_t] = true;
                    next_takahashi.push(next_t);
                }
            }
        }
        takahashi = next_takahashi;

        if takahashi.is_empty() {
            break;
        }

        let mut next_aoki: Vec<usize> = vec![];
        for &a in aoki.iter() {
            is_aoki[a] = false;
            for &next_a in vertices[a].iter() {
                is_aoki[next_a] = true;
                next_aoki.push(next_a);
                if is_takahashi[next_a] {
                    is_takahashi[next_a] = false;
                    let index = takahashi.iter().position(|&x| x == next_a).unwrap();
                    takahashi.remove(index);
                }
            }
        }
        aoki = next_aoki;

        ans += 1;
    }

    println!("{}", ans);
}

