fn dfs(v: usize, g: &Vec<Vec<usize>>, memo: &mut Vec<i32>, s: i32) {
    if memo[v] >= 0 {
        return;
    }
    memo[v] = s;
    for t in g[v].iter() {
        dfs(*t, g, memo, s+1);
    }
}

fn dfs2(v: usize, g: &Vec<Vec<usize>>, memo: &Vec<i32>, visited: &mut Vec<bool>, s: i32) -> i32 {
    if memo[v] <= s {
        return memo[v];
    } else if visited[v] {
        if g[v].len() == 1 {
            return memo[v] - 1;
        } else {
            return memo[v];
        }
    }
    visited[v] = true;
    let mut res = s;
    for t in g[v].iter() {
        res = cmp::max(res, dfs2(*t, g, memo, visited, s+1));
    }
    res
}

