#[fastout()]
fn main() {
    input! {
        n: usize, u: Usize1, v: Usize1,
        ab: [(Usize1, Usize1); n-1]
    }
    let mut graph = vec![Vec::new(); n];
    for (a, b) in ab {
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut udist = vec![0; n];
    let mut stack = Vec::new();
    stack.push((u, u, 0));
    while let Some((node, prev, dist)) = stack.pop() {
        udist[node] = dist;
        for &next in &graph[node] {
            if next != prev {
                stack.push((next, node, dist+1));
            }
        }
    }

    let mut vdist = vec![0; n];
    let mut stack = Vec::new();
    stack.push((v, v, 0));
    while let Some((node, prev, dist)) = stack.pop() {
        vdist[node] = dist;
        for &next in &graph[node] {
            if next != prev {
                stack.push((next, node, dist+1));
            }
        }
    }

    let mut dist = 0;
    for i in 0..n {
        let d = vdist[i];
        if udist[i] < d {
            dist = max(dist, d);
        }        
    }
    println!("{}", dist - 1);
}

