    for i in 0..n {
        if t_dist[i].0 >= a_dist[i].0 {
            t_dist[i].0 = 0;
        }
    }
    let mut stack = vec![u];
    while let Some(x) = stack.pop() {
        if t_dist[x].0 == 0 {
            ans = std::cmp::min(ans, a_dist[x].0 - 1);
            continue;
        }
        let mut cnt = 0;
        for &y in &graph[x] {
            if t_dist[y].0 > t_dist[x].0 {
