       v:usize1,
       edges:[(usize1,usize1);n-1],
    }

    let mut map = vec![vec![]; n];
    let mut used: Vec<Option<usize>> = vec![None; n];
    for &(f, t) in &edges {
        map[f].push(t);
        map[t].push(f);
    }

    let mut ans: usize = 0;
    let mut kouho = VecDeque::new();
    kouho.push_back((u, 0));
    used[u] = Some(INF_USIZE);
    let mut dist = 0;
    while !kouho.is_empty() {
        let (p, depth) = kouho.pop_front().unwrap();
        if p == v {
            break;
        }
        for i in 0..map[p].len() {
            let next = map[p][i];
            if used[next].is_some() {
                continue;
            }
            used[next] = Some(p);
            kouho.push_back((next, depth + 1));
        }
    }

    //mydbg!(dist, used);
    let mut path = vec![];
    path.push(v);
    let mut cur = v;
    loop {
        //mydbg!(cur);
        cur = used[cur].unwrap();
        if cur == INF_USIZE {
            break;
        }
        path.push(cur);
    }

    path.reverse();
    let b = path[min(path.len() - 1, ((path.len() + 1) / 2))];
    //mydbg!(path, b);
    let mut kouho = VecDeque::new();

    let mut canmove = vec![false; n];
    kouho.push_back((u, 0));
    canmove[u] = true;
    while !kouho.is_empty() {
        let (p, depth) = kouho.pop_front().unwrap();
        for i in 0..map[p].len() {
            let next = map[p][i];
            if canmove[next] {
                continue;
            }
            if next == b {
                continue;
            }
            canmove[next] = true;
            kouho.push_back((next, depth + 1));
        }
    }

    //mydbg!(canmove);
    let mut kouho = VecDeque::new();
    let mut used2: Vec<Option<usize>> = vec![None; n];
    kouho.push_back((v, 0));
    used2[v] = Some(0);
    while !kouho.is_empty() {
        let (p, depth) = kouho.pop_front().unwrap();
        for i in 0..map[p].len() {
            let next = map[p][i];
            if used2[next].is_some() {
                continue;
            }
            used2[next] = Some(depth + 1);
            kouho.push_back((next, depth + 1));
        }
    }
    //mydbg!(used2);

    let mut tmp = used2
        .iter()
        .map(|x| if x.is_some() { x.unwrap() } else { 0 })
        .zip(canmove)
        .filter(|&(_, x)| x)
        .toVec();

    tmp.sort_by_key(|x| x.0);
    tmp.reverse();
    //mydbg!(tmp);
    ans = tmp[0].0.saturating_sub(1);
