fn construct_paths(
    pos: usize,
    pre: Option<usize>,
    edges: &Vec<Vec<usize>>,
    paths: &mut Vec<usize>,
    u: usize,
    v: usize,
) -> bool {
    if pos == v {
        return true;
    }
    paths.push(pos);
    for &nxt in edges[pos].iter() {
        if let Some(p) = pre {
            if nxt == p {
                continue;
            }
        }
        if construct_paths(nxt, Some(pos), edges, paths, u, v) {
            return true;
        }
    }
    paths.pop();
    false
}

fn dfs(
    pos: usize,
    pre: Option<usize>,
    edges: &Vec<Vec<usize>>,
    cnt: usize,
    costs: &mut Vec<usize>,
    v: usize,
) {
    if pos == v {
        return;
    }
    costs[pos] = cnt;
    for &nxt in edges[pos].iter() {
        if let Some(p) = pre {
            if p == nxt {
                continue;
            }
        }
        dfs(nxt, Some(pos), edges, cnt + 1, costs, v);
    }
}

fn solve() {
    let stdin = std::io::stdin();
    let mut scn = Scanner {
        stdin: stdin.lock(),
    };
    let n: usize = scn.read();
    let u: usize = scn.read::<usize>() - 1;
    let v: usize = scn.read::<usize>() - 1;
    let mut edges = vec![vec![]; n];
    let ab: Vec<(usize, usize)> = (0..n - 1)
        .map(|_| {
            let a: usize = scn.read::<usize>() - 1;
            let b: usize = scn.read::<usize>() - 1;
            edges[a].push(b);
            edges[b].push(a);
            (a, b)
        })
        .collect();
    let mut paths = vec![];
    construct_paths(u, None, &edges, &mut paths, u, v);

    let mut result = 0;
    let d = paths.len() / 2;

    let (u, v) = if paths.len() >= 3 {
        result += d;
        let node = paths[d];
        let u = node;
        let v = if d + 1 < paths.len() { paths[d + 1] } else { v };
        (u, v)
    } else {
        (paths[d], v)
    };

    //let u = node;
    //let v = if paths.len() >= 3 && d + 1 < paths.len() { paths[d + 1] } else { v };
    //eprintln!("{:?} {:?}", u, v);
    //eprintln!("{:?}", paths);
    //eprintln!("{:?}", node);

    let mut costs = vec![0; n];
    dfs(u, None, &edges, 0, &mut costs, v);
    ///eprintln!("{:?}", costs);
    let d1 = costs.iter().max().unwrap();

    println!("{}", result + d1);
}

