    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input! {
        n: usize,
        u: usize,
        v: usize,
        ab: [(usize, usize); n - 1]
    }
    let mut adjacency = vec![vec![]; n + 1];
    for (ai, bi) in ab {
        adjacency[ai].push(bi);
        adjacency[bi].push(ai);
    }

    let mut height = vec![0; n + 1];
    let mut parent = vec![0; n + 1];
    let mut queue = VecDeque::new();
    let mut visited = HashSet::new();
    queue.push_back(v);
    while queue.len() > 0 {
        let w = queue.pop_front().unwrap();
        visited.insert(w);
        for &x in adjacency[w].iter() {
            if !visited.contains(&x) {
                height[x] = height[w] + 1;
                parent[x] = w;
                queue.push_back(x);
            }
        }
    }
    // println!("{:?}", height);
    // println!("{:?}", parent);

    let mut u_ancestor = vec![];
    let mut w = u;
    while parent[w] != v {
        u_ancestor.push(parent[w]);
        w = parent[w];
    }
    // println!("{:?}", u_ancestor);

    let mut result = height[u] / 2;
    let h = (height[u] - 1) / 2;
    for &w in u_ancestor[0..h].iter() {
        let mut max = 0;
        let mut queue = VecDeque::new();
        let mut visited = HashSet::new();
        queue.push_back(w);
        while queue.len() > 0 {
            let x = queue.pop_front().unwrap();
            visited.insert(x);
            for &y in adjacency[x].iter() {
                if !visited.contains(&y) && !u_ancestor.contains(&y) && height[y] > height[w] {
                    let d = height[y] - height[w];
                    if d > max {
                        max = d;
                    }
                    queue.push_back(y);
                }
            }
        }
        // println!("{}", max);
        let d = max + height[u] - height[w];
        if d > result {
            result = d;
        }
        // println!("{} {}", w, d);
    }

    println!("{}", result);
}

