fn dfs(pos: usize, par: usize, t: usize, graph: &Graph, mid: &mut Vec<usize>) -> bool {
    for &next in &graph[pos] {
        if next == par {
            continue;
        }
        if next == t {
            mid.push(pos);
            return true;
        }
        if dfs(next, pos, t, graph, mid) {
            mid.push(pos);
            return true;
        }
    }
    false
}

fn dfs2(pos: usize, par: usize, graph: &Graph) -> usize {
    let mut r = 0;
    for &next in &graph[pos] {
        if next == par {
            continue;
        }
        r = max(r, dfs2(next, pos, graph) + 1);
    }
    return r;
}

