fn dfs(node: usize, nodes: &Vec<Vec<usize>>, depth: &mut Vec<usize>, visited: &mut Vec<bool>, current_depth: usize) {
    visited[node] = true;
    for &next in &nodes[node] {
        if visited[next] {
            continue;
        }
        dfs(next, nodes, depth, visited, current_depth+1);
        visited[next] = true;
    }
    depth[node] = current_depth;
}

fn dfs2(node: usize, nodes: &Vec<Vec<usize>>, visited: &mut Vec<bool>, goal: usize) -> Option<usize> {
    visited[node] = true;
    if node == goal {
        return Some(0);
    }
    for &next in &nodes[node] {
        if visited[next] {
            continue;
        }
        let depth = dfs2(next, nodes, visited, goal);
        visited[next] = true;
        if let Some(depth) = depth {
            return Some(depth+1);
        }
    }
    None
}

fn lower_bound<F>(l: usize, r: usize, criterion: F) -> usize
where
    F: Fn(usize) -> bool,
{
    let mut l = l;
    let mut r = r;
    while r - l > 1 {
        let mid = l + (r - l) / 2;
        if criterion(mid) {
            r = mid;
        } else {
            l = mid;
        }
    }
    l
}

fn solve() {
    let (n,u,v) = get!(usize, usize, usize);
    let ab = get!(usize, usize; n-1);

    if u == v {
        println!("0");
        return;
    }

    let mut nodes = vec![Vec::new(); n+1];
    for (a,b) in ab {
        nodes[a].push(b);
        nodes[b].push(a);
    }

    let mut a_depth = vec![0; n+1];
    let mut t_depth = vec![0; n+1];
    dfs(u, &nodes, &mut t_depth, &mut vec![false; n+1], 0);
    dfs(v, &nodes, &mut a_depth, &mut vec![false; n+1], 0);

    let mut a_depth_inv = BTreeMap::new();
    let mut t_depth_inv = BTreeMap::new();
    for i in 1..n+1 {
        a_depth_inv.entry(&a_depth[i]).or_insert(Vec::new()).push(i);
        t_depth_inv.entry(&t_depth[i]).or_insert(Vec::new()).push(i);
    }

    let mn = dfs2(u, &nodes, &mut vec![false; n+1], v).unwrap();

    let crit = |dist: usize| {
        let vec = a_depth_inv.get(&dist).cloned().unwrap_or(Vec::new());
        for node in vec {
            if t_depth[node] <= dist {
                return false;
            }
        }
        true
    };
    let res = lower_bound(mn, n, crit);
    println!("{}", res-1);
}

