fn calc(s: usize, g: &Vec<Vec<usize>>) -> Vec<usize> {
    let n = g.len();
    let mut dist = vec![usize::max_value(); n];
    let mut queue: VecDeque<usize> = VecDeque::new();
    dist[s] = 0;
    queue.push_back(s);
    while let Some(u) = queue.pop_front() {
        for &next in g[u].iter() {
            if dist[next] > dist[u] + 1 {
                dist[next] = dist[u] + 1;
                queue.push_back(next);
            }
        }
    }
    dist
}

fn run() {
    let n: usize = scan();
    let s0: usize = scan();
    let s1: usize = scan();
    let s0 = s0 - 1;
    let s1 = s1 - 1;

    let mut graph = vec![Vec::new(); n];
    let edges: Vec<(usize, usize)> = scan_iter().collect();
    for (a, b) in edges {
        graph[a - 1].push(b - 1);
        graph[b - 1].push(a - 1);
    }

    let dist0 = calc(s0, &graph);
    let dist1 = calc(s1, &graph);
    let ans = dist0
        .into_iter()
        .zip(dist1.into_iter())
        .filter(|&(a, b)| a < b)
        .map(|(_, b)| b)
        .max()
        .unwrap();
    println!("{}", ans - 1);
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}

