use std::io::Read;
use std::collections::VecDeque;

fn bfs(tree: &Vec<Vec<usize>>, start: usize) -> Vec<usize> {
    let mut dist: Vec<usize> = vec![tree.len(); tree.len()];
    let mut queue: VecDeque<usize> = VecDeque::new();

    dist[start] = 0;
    queue.push_back(start);

    while !queue.is_empty() {
        let curr_node = queue.pop_front().unwrap();
        for i in &tree[curr_node] {
            if dist[*i] < tree.len() {
                continue;
            }
            dist[*i] = dist[curr_node] + 1;
            queue.push_back(*i);
        }
    }
    dist
}

fn main() {
    let mut buf = String::new();
    let stdin = std::io::stdin();
    stdin.lock().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let u: usize = iter.next().unwrap().parse().unwrap();
    let v: usize = iter.next().unwrap().parse().unwrap();

    let mut tree: Vec<Vec<usize>> = vec![vec![0]; n+1];

    for _ in 1..n {
        let a: usize = iter.next().unwrap().parse().unwrap();
        let b: usize = iter.next().unwrap().parse().unwrap();
        tree[a].push(b);
        tree[b].push(a);
    }

    let mut ans: usize = 0;
    let dist_from_u = bfs(&tree, u);
    let dist_from_v = bfs(&tree, v);

    for (du, dv) in dist_from_u.iter().zip(&dist_from_v) {
        if du <= dv {
            ans = std::cmp::max(ans, dv-1);
        }
    }

    println!("{}", ans);
}

