fn dfs(pos: usize, pre: Option<usize>, edges: &[Vec<usize>], d: usize, costs: &mut [usize]) {
    costs[pos] = d;
    for &nxt in edges[pos].iter() {
        if let Some(p) = pre {
            if p == nxt {
                continue;
            }
        }
        dfs(nxt, Some(pos), edges, d + 1, costs);
    }
}


