    let v: usize = scn.read::<usize>() - 1;
    let mut edges = vec![vec![]; n];
    let ab: Vec<_> = (0..n - 1)
        .map(|_| {
            let x: usize = scn.read::<usize>() - 1;
            let y: usize = scn.read::<usize>() - 1;
            edges[x].push(y);
            edges[y].push(x);
            (x, y)
        })
        .collect();
        let mut costs1 = vec![0; n];
        let mut costs2 = vec![0; n];
        dfs(u, None, &edges, 0, &mut costs1);
        dfs(v, None, &edges, 0, &mut costs2);

        let mut result = 0;
        for (c1, c2) in costs1.iter().zip(costs2.iter()) {            
            if c1 < c2 {
                result = std::cmp::max(result, *c2);
            }
        }
        println!("{}", result - 1);
