fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());

    input!{
        n:usize, u:usize, v:usize,
        ab:[(usize,usize);n-1],
    }

    let mut g = vec![vec![]; n];
    for (a,b) in ab {
        g[a-1].push(b-1);
        g[b-1].push(a-1);
    }

    let (taka, _) = depth_table(&g, u-1);
    let (aoki, is_leaf) = depth_table(&g, v-1);

    let mut ans = 0;
    for i in 0..n {
        if is_leaf[i] {
            if taka[i] < aoki[i] {
                chmax!(ans, aoki[i]-1);
            }
        }
    }
    println!("{}", ans);
}

fn depth_table(g: &[Vec<usize>], root: usize) -> (Vec<i64>, Vec<bool>) {
    let n = g.len();
    let mut dp = vec![0; n];
    let mut is_leaf = vec![false; n];
    let mut S = vec![];
    let mut visited = vec![false; n];
    visited[root] = true;
    S.push(root);
    while !S.is_empty() {
        let v = S.pop().unwrap();
        let mut found = false;
        for i in 0..g[v].len() {
            let u = g[v][i];
            if !visited[u] {
                dp[u] = dp[v] + 1;
                visited[u] = true;
                S.push(u);
                found = true;
            }
        }
        if !found {
            is_leaf[v] = true;
        }
    }
    (dp, is_leaf)
}

