use input::*;
use std::collections::VecDeque;

const TAKAHASHI: usize = 1;
const TAKAHASHI_2: usize = 3;
const AOKI: usize = 2;

fn dfs(
    v: &Vec<Vec<usize>>,
    map: &Vec<usize>,
    k: usize,
    d: usize,
    parent: usize,
    ans: &mut Vec<usize>,
    ans2: &mut Vec<usize>,
    x: &mut usize,
    tk: usize,
) {
    if k == tk {
        *x = d;
    }

    if map[k] == TAKAHASHI || map[k] == TAKAHASHI_2 {
        if d % 2 == 0 && map[k] == TAKAHASHI_2 {
            ans2.push(d);
        } else if d % 2 != 0 && map[k] == TAKAHASHI {
            ans2.push(d);
        }
        if d % 2 == 0 && map[k] == TAKAHASHI {
            ans.push(d);
        } else if d % 2 != 0 && map[k] == TAKAHASHI_2 {
            ans.push(d);
        }
    }
    for z in &v[k] {
        if *z == parent {
            continue;
        }
        dfs(v, map, *z, d + 1, k, ans, ans2, x, tk);
    }
}

fn main() {
    let (n, u, w): (usize, usize, usize);
    input!(n, u, w);
    let mut v = vec![vec![]; n];
    let mut map = vec![0; n];
    for _ in 0..n - 1 {
        let (a, b): (usize, usize);
        input!(a, b);
        v[a - 1].push(b - 1);
        v[b - 1].push(a - 1);
    }

    let mut qt = VecDeque::new();
    let mut qa = VecDeque::new();

    qt.push_front(u - 1);
    map[u - 1] = TAKAHASHI;
    qa.push_front(w - 1);
    map[w - 1] = AOKI;
    let mut flag = true;

    while !qt.is_empty() || !qa.is_empty() {
        if !qt.is_empty() {
            let buf = qt.pop_back().unwrap();
            for z in &v[buf] {
                if map[*z] == 0 {
                    if flag {
                        map[*z] = TAKAHASHI;
                    } else {
                        map[*z] = TAKAHASHI_2;
                    }
                    qt.push_front(*z);
                }
            }
            flag = !flag;
        }

        if !qa.is_empty() {
            let buf = qa.pop_back().unwrap();
            for z in &v[buf] {
                if map[*z] == 0 {
                    map[*z] = AOKI;
                    qa.push_front(*z);
                }
            }
        }
    }
    let mut ans = vec![];
    let mut ans2 = vec![];
    let mut q = 0;
    dfs(
        &v,
        &map,
        w - 1,
        0,
        w - 1,
        &mut ans,
        &mut ans2,
        &mut q,
        u - 1,
    );
    if ans.is_empty() {
        ans.push(99999);
    }
    if ans2.is_empty() {
        ans2.push(999999);
    }
    let mut z1 = *ans.iter().max().unwrap();
    let mut z2 = *ans2.iter().max().unwrap();

    if z1%2!=0{
        z1=z2-1;
    }
    if z2%2==0{
        z2=z1-1;
    }

    p(std::cmp::min(z1,z2));
}

