use std::cmp;

fn calc_dist(v0: usize, adj: &[Vec<usize>], visited: &mut [bool], dist: &mut [usize]) {
    let mut queue = Vec::new();
    queue.push((0, v0));
    visited[v0] = true;
    dist[v0] = 0;
    while let Some((d, v)) = queue.pop() {
        for &next in &adj[v] {
            if visited[next] {
                continue;
            }
            visited[next] = true;
            dist[next] = d+1;
            queue.push((d+1, next));
        }
    }
}

fn dfs(v: usize, p: Option<usize>, adj: &[Vec<usize>], d_t: &[usize], d_a: &[usize]) -> usize {
    if d_a[v] < d_t[v] {
        return 0;
    }

    let d = d_a[v];
    cmp::max(d, adj[v].iter().filter(|&&next| Some(next) != p).map(|&next| {
        dfs(next, Some(v), adj, d_t, d_a)
    }).max().unwrap_or(0))
}

