        u: usize1,
        v: usize1,
        es: [(usize1, usize1); n - 1]
    }
    let mut t = vec![vec![]; n];
    for &(a, b) in &es {
        t[a].push(b);
        t[b].push(a);
    }
    let dt = dist_from(u, &t);
    let da = dist_from(v, &t);
    let mut ans = 0;
    for i in 0..n {
        if da[i] < dt[i] {
            continue;
        }
        ans = max(ans, da[i] - 1);
    }
    println!("{}", ans);
}

fn dist_from(u: usize, t: &Vec<Vec<usize>>) -> Vec<usize> {
    let n = t.len();
    let mut ret = vec![n; n];
    ret[u] = 0;
    let mut q = vec![u];
    while let Some(a) = q.pop() {
        for &b in &t[a] {
            if ret[b] + 1 == ret[a] {
                continue;
            }
            ret[b] = ret[a] + 1;
            q.push(b);
        }
    }
    ret
}

