fn graph_dfs(v: usize, p: usize, depth: &mut Vec<i64>, graph: &Vec<Vec<usize>>) {
    let mut res: (i64) = (0);
    if (p != INF as usize) {
        depth[v] = depth[p] + 1;
    } else {
        depth[v] = 0;
    }
    // println!("{:?}", v);

    for nv in graph[v].iter() {
        if (*nv == p || depth[*nv] != -1) {
            continue;
        }
        graph_dfs(*nv, v, depth, graph);
    }
    // return res;
}

fn solve() {
    let (mut n, mut u, mut v) = readuuu();
    u -= 1;
    v -= 1;
    let mut d1: Vec<i64> = vec![-1; n];
    let mut d2: Vec<i64> = vec![-1; n];
    let mut vv: Vec<Vec<usize>> = vec![vec![0; (0) as usize]; (n) as usize];

    for i in 0..n - 1 {
        let (mut a, mut b) = readuu();
        a -= 1;
        b -= 1;
        vv[a].push(b);
        vv[b].push(a);
    }
    graph_dfs(u, INF as usize, &mut d1, &vv);
    graph_dfs(v, INF as usize, &mut d2, &vv);
    let mut dist: Vec<i64> = vec![0; n];
    for i in 0..n {
        dist[i] = d1[i] - d2[i];
    }
    for i in 0..n {
        if (vv[i].len() == 1) {
            dist[i] = -1;
        }
    }
    let mut res = 0;
    let mut dd = -1 * INF;
    for i in 0..n {
        if (dd < dist[i]) {
            res = i;
            dd = max(dd, dist[i]);
        }
    }

    return;
}
fn main() {
    solve()
}

