        let i = read::<usize>();
        (i[0], i[1] - 1, i[2] - 1)
    };
    let mut g = vec![Vec::new(); n];
    for _ in 1..n {
        let (a, b) = {
            let i = read::<usize>();
            (i[0] - 1, i[1] - 1)
        };
        g[a].push(b);
        g[b].push(a);
    }
    let mut du = vec![0; n];
    let mut qu = Vec::new();
    qu.push((u, n + 1));
    while let Some((p, par)) = qu.pop() {
        for &x in &g[p] {
            if x == par || du[x] != 0 { continue; }
            du[x] = du[p] + 1;
            qu.push((x, p));
        }
    }

    let mut dv = vec![0; n];
    let mut qv = Vec::new();
    qv.push((v, n + 1));
    while let Some((p, par)) = qv.pop() {
        for &x in &g[p] {
            if x == par || dv[x] != 0 { continue; }
            dv[x] = dv[p] + 1;
            qv.push((x, p));
        }
    }

    let mut max = 0;
    let mut node = 0;
    for i in 0..n {
        if dv[i] < du[i] { continue; }
        if dv[i] - du[i] > max {
            max = du[i] - dv[i];
            node = i;
        }
    }

    println!("{}", dv[node] - 1);
}


